local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["npc:delgren-the-purifier"] = {n="Делгрен Очиститель",s="Делгрен Очиститель — паладин-человек, расквартированный на Заставе Мейстры на северной окраине Ясеневого леса. Действуя вместе с соратниками Балтулом Ударом Тени и Фиро Железнорук, он помогает ночным эльфам очищать земли от демонической магии и магии Тени, угрожающей границе, уделяя особое внимание зловещему Культу Темной Нити.",h="Делгрен Очиститель — паладин-человек, расквартированный на Заставе Мейстры на северной окраине Ясеневого леса.",kw={"althalaxx","argent dawn","ashenvale","balthule shadowstrike","cult of the dark strand","delgren","delgren the purifier","feero ironhand","maestra's post","tower of althalaxx","алталакс","серебряный рассвет","ясеневый лес","балтул удар тени","культ темной нити","делгрен","делгрен очиститель","фиро железнорук","застава мейстры","башня алталакса"},ang={["class:Paladin"]="Делгрен олицетворяет дальний рубеж Света в Калимдоре и показывает, как паладины приспосабливают свой крестовый поход против демонов и темной магии далеко за пределами Восточных королевств.",["faction:Alliance"]="Для путников Альянса, идущих на юг от Темных берегов, Делгрен и его соратники служат надежным военным оплотом на опасной дороге через Ясеневый лес.",["race:NightElf"]="Хотя кальдорай нередко с недоверием относятся к чужим верованиям, отряд Делгрена заслужил доверие своим практическим походом против демонических культов, тревожащих древние руины."},sec={{t="Крестоносец на границе кальдорай",b="Паладины-люди редко встречаются в древних лесах Калимдора, но Делгрен Очиститель прибыл сюда с миссией. Состоя в Серебряном Рассвете, Делгрен отправился на запад с отрядом священных воинов, решивших помочь новым союзникам Альянса, ночным эльфам, против остатков демонов и нежити, уцелевших после Третьей войны. Расквартированный у границы Темных берегов и Ясеневого леса, он несет бдительную стражу над путниками, идущими на юг от Аубердина."},{t="Искоренение Темной Нити",b="Непосредственный поход Делгрена направлен против Культа Темной Нити, злобного заговора, действующего вокруг Башни Алталакса на севере Темных берегов. Действуя вместе с разведчиком Балтулом Ударом Тени, Делгрен организует вылазки на земли культа, расследует их темные ритуалы и посылает искателей приключений убивать культистов, разбивать их средоточия призыва и выкорчевывать порочных чернокнижников, осмелившихся иметь дело с демонической тенью."},{t="Нетрадиционный ум",b="Несмотря на пылкую преданность Свету и рьяное прозвище, Делгрен имеет необычный взгляд на запутанную политику Калимдора. К досаде и неодобрению своих консервативных начальников, он нашел время выучить орочий язык. Это редкое лингвистическое умение говорит о нестандартном уме, стремящемся понять врагов и соседей, делящих этот дикий континент, а не полагаться лишь на слепую догму."}},faq={{q="Кто такой Делгрен Очиститель?",a="Делгрен — паладин-человек, расквартированный на Заставе Мейстры у дороги на севере Ясеневого леса. Как представитель Серебряного Рассвета, он помогает ночным эльфам защищать свои земли от демонической порчи, культистов и теней, оставшихся после вторжения Легиона.",al={"who is delgren","delgren lore","who is the paladin at maestras post","кто такой делгрен","предания о делгрене","кто паладин на заставе мейстры"}},{q="Где найти Делгрена?",a="Делгрен стоит на Заставе Мейстры, небольшом форпосте ночных эльфов на северо-западе Ясеневого леса, чуть южнее пограничной тропы, ведущей в Темные берега.",al={"where is delgren","delgren location","delgren coordinates","где делгрен","местонахождение делгрена","координаты делгрена"}},{q="Почему паладин-человек забрался так далеко, в Ясеневый лес?",a="Делгрен отправился на запад с отрядом паладинов Серебряного Рассвета, чтобы помочь союзникам Альянса, ночным эльфам. Их цель — помочь искоренить демонические вторжения, остатки нежити и темные культы, угрожающие северу Калимдора.",al={"why is delgren in ashenvale","why are there humans in ashenvale","delgren mission","почему делгрен в ясеневом лесу","почему в ясеневом лесу люди","миссия делгрена"}},{q="Как Делгрен связан с Башней Алталакса?",a="Делгрен и его соратники следят за порочной деятельностью, исходящей от Башни Алталакса на севере Темных берегов. Он направляет искателей приключений исследовать руины, охотиться на Культ Темной Нити и пресекать их темные практики призыва.",al={"delgren althalaxx","tower of althalaxx quests","cult of the dark strand","делгрен алталакс","задания башни алталакса","культ темной нити"}},{q="Почему Делгрен выучил орочий язык?",a="Делгрен выучил орочий язык, чтобы лучше понимать положение дел и обитателей Калимдора, и это решение вызвало заметное неодобрение его начальников в ордене.",al={"delgren speaks orcish","does delgren speak orcish","delgren orc language","делгрен говорит на орочьем","говорит ли делгрен на орочьем","орочий язык делгрена"}},{q="С кем работает Делгрен на Заставе Мейстры?",a="Он действует вместе с Балтулом Ударом Тени и Фиро Железнорук, и они слаженным отрядом следят за угрозами на границе, занимаются снабжением и истребляют культистов Тени на ясеневой границе.",al={"delgren companions","who is at maestras post","соратники делгрена","кто на заставе мейстры"}}},fp="20,326,35.474.0,23.449.1,18.429.0,28.276.0,25.142.0,52.228.0,55.246.0,29.170.0,45.194.0"}
P.entries["npc:demisette-cloyce"] = {n="Демизетта Клойс",s="Демизетта Клойс — человек, наставница чернокнижников, скрывающаяся в подземных склепах под «Забитым ягненком» в Квартале магов Штормграда. Действуя под прикрытием городского дна, она обучает приверженцев искусства Скверны и направляет многообещающих служителей к более глубоким и опасным тайнам магии.",h="Демизетта Клойс — человек, наставница чернокнижников, скрывающаяся в подземных склепах под «Забитым ягненком»...",kw={"cloyce","demisette","mage quarter","menara voidrender","slaughtered lamb","stormwind","warlock trainer","клойс","демизетта","квартал магов","менара расщепительница бездны","забитый ягненок","штормград","наставник чернокнижников"},ang={["class:Warlock"]="Демизетта — важный контакт на пути служителя в Штормграде: она дает основы построения заклинаний, а позже направляет чернокнижников к получению коней Скверны и подчинению демонических сфер.",["race:Human"]="Спрятанная под столицей человеческой цивилизации, Клойс воплощает тихую и опасную окраину человечества, которая отказывается от Света ради демонической силы."},sec={{t="Склепы «Забитого ягненка»",b="Пока власти Штормграда поддерживают внешний вид порядка и праведности Света, практики магии Скверны собираются в сырых подвалах под «Забитым ягненком» в Квартале магов. Демизетта Клойс живет в этих катакомбах и обучает чернокнижников, готовых рискнуть и освоить запретные искусства. У нее мало терпения к неподготовленным и непосвященным: она наставляет учеников, что темные энергии развращают лишь тех, кому не хватает дисциплины, чтобы овладеть ими."},{t="Связь между ковенами",b="Демизетта — далеко не простая наставница заклинаний: она служит важнейшим связующим звеном для чернокнижников по всему Азероту. Когда служитель достигает достаточного мастерства, она направляет его далеко за стены Штормграда — к могущественным призывателям, таким как Менара Расщепительница Бездны в Степях, чтобы он получил мощные артефакты и подчинил грозных коней Скверны."}},faq={{q="Кто такая Демизетта Клойс?",a="Демизетта Клойс — человек, наставница чернокнижников, которая обосновалась в подвале таверны «Забитый ягненок» в Квартале магов Штормграда. Она обучает начинающих чернокнижников демоническому призыву и темным заклинаниям.",al={"who is demisette","demisette cloyce lore","who is demisette cloyce","кто такая демизетта","демизетта клойс предыстория","кто такая демизетта клойс"}},{q="Почему она прячется в подвале таверны?",a="Шабаш чернокнижников собирается в подземном погребе «Забитого ягненка», вдали от посторонних глаз. Их темные занятия делают таверну неприметным местом встреч.",al={"why is she in the cellar","why slaughtered lamb","slaughtered lamb basement","почему она в подвале","почему забитый ягненок","подвал забитого ягненка"}},{q="Как она связана со Степями?",a="Демизетта отправляет опытных чернокнижников за море на поиски Менары Расщепительницы Бездны, могущественной призывательницы в Кабестане на побережье Степей, чтобы они освоили сложные ритуалы, мощные сферы и обряды подчинения.",al={"demisette barrens","in search of menara voidrender","menara voidrender connection","демизетта степи","поиск менары расщепительницы бездны","связь с менарой расщепительницей бездны"}},{q="Как она относится к тем, кто не чернокнижник?",a="Демизетта питает глубокое презрение к чужакам. Если вы не следуете путем чернокнижника, она предупредит, что тьма вас не принимает, и прикажет вам прекратить болтовню и покинуть ее присутствие.",al={"demisette dialogue","talking to demisette","диалог демизетты","разговор с демизеттой"}}},fp="16,311,34.482.0,21.353.0,24.211.0,37.167.0,38.214.0,35.198.0"}
P.entries["npc:denalan"] = {n="Деналан",s="Деналан — искусный ночной эльф, травник и ботаник, который ухаживает за тихим участком на восточном берегу озера Аль'Амет. Работая под простым навесом, он посвящает дни изучению растений острова и поиску ботанических средств от странной порчи, поразившей Тельдрассил. Он часто привлекает юных искателей приключений собирать образцы, изучать свирепых древесных малышей и испытывать зачарованную почву.",h="Деналан — искусный ночной эльф, травник и ботаник, который ухаживает за тихим участком на восточном берегу...",kw={"blackmoss","botany","denalan","herbalist","kaldorei","lake al'ameth","oakenscowl","planter","teldrassil","timberlings","черномшец злосмрадный","ботаника","деналан","травник","кальдораи","озеро аль'амет","хмурый дуб","грядка","тельдрассил","древесные малыши"},ang={["class:Druid"]="Друиды найдут общее дело с опытами Деналана у озера: его работа напрямую помогает усилиям Круга Кенария выследить и изгнать порчу, распространяющуюся в корнях Тельдрассила.",["profession:Herbalism"]="Деналан воплощает традицию изучения растений у кальдораев и показывает, как сбор и выращивание диких растений помогают выявить более глубокие недуги природного мира.",["race:NightElf"]="Исследования Деналана у озера Аль'Амет — это ранние попытки кальдораев понять неожиданные изъяны и трудности роста их нового дома, Тельдрассила."},sec={{t="Ботаник у озера Аль'Амет",b="Пока многие кальдораи сосредоточены на воинской бдительности или высоких обрядах друидов, Деналан занимается терпеливым и тщательным ремеслом травничества. На тихом восточном берегу озера Аль'Амет он устроил скромный исследовательский лагерь: тканевый навес, простые полевые инструменты и аккуратные ряды грядок. Вместо того чтобы удалиться в величественные курганы Дарнасса, он предпочитает оставаться ближе к земле и напрямую изучать необычную флору, проросшую после посадки нового Мирового Древа."},{t="Исследование недугов Тельдрассила",b="Исследования Деналана — не просто научное любопытство: они связаны с растущим беспокойством среди местных обитателей Тельдрассила. Древесные малыши, обычно мирные лесные существа из дерева и ростков, стали все более агрессивными. Деналан зачаровывает особую почву, чтобы выращивать в неволе дикие семена и выяснять, как злые силы проникают в корневые системы. Изучая странные образцы — мерцающие листья, светящиеся плоды и обвитые мхом наросты, — он стремится выявить ту темную порчу, что тревожит лесные ветви."}},faq={{q="Где найти Деналана?",a="Деналан находится на восточном берегу озера Аль'Амет на юге Тельдрассила, к югу от Доланаара. У самой воды он держит небольшой лагерь с навесом и несколькими грядками.",al={"denalan location","where is denalan","denalan map","где деналан","местонахождение деналана","деналан карта"}},{q="Что Деналан исследует в своем лагере?",a="Деналан — травник, изучающий необычную флору Тельдрассила и агрессивное поведение местных лесных духов. Он использует зачарованные грядки, чтобы выращивать семена древесных малышей, исследовать любопытные образцы диких растений и искать способы очистить порчу, проникающую в экосистему нового Мирового Древа.",al={"what does denalan do","denalan purpose","why is denalan at the lake","чем занимается деналан","цель деналана","почему деналан у озера"}},{q="Почему древесные малыши нападают на людей?",a="Древесные малыши — растительные духи природы, обитающие в ветвях Тельдрассила. Обычно они мирная часть лесной экологии, но стали свирепыми и непредсказуемыми из-за неестественной порчи, распространяющейся в почве и корнях Мирового Древа, и исследователи вроде Деналана изучают их семена.",al={"why are timberlings aggressive","timberling lore","corrupted timberlings","почему древесные малыши агрессивны","предания о древесных малышах","оскверненные древесные малыши"}},{q="Для чего нужны грядки Деналана?",a="У Деналана есть особо подготовленные грядки с зачарованной землей. Он выращивает на них дикие семена и странные растительные черенки, что позволяет безопасно наблюдать, как лесная флора реагирует на очищенную почву вдали от диких загрязнений.",al={"denalan planter","denalans earth","denalan dirt boxes","грядка деналана","земля деналана","ящики с землей деналана"}},{q="С кем работает Деналан?",a="Деналан тесно сотрудничал с другими травниками, например с Сильвией Шепот Цветов, и поддерживает постоянную связь с исследователями и учеными-друидами по всему Тельдрассилу, в том числе с Релианом Зеленым Костром в Дарнассе.",al={"denalan allies","who does denalan report to","союзники деналана","кому подчиняется деналан"}},{q="Что такое Сердце, поросшее мхом, которое изучает Деналан?",a="Сердце, поросшее мхом, — пораженное порчей растительное ядро, добытое у Черномшеца злосмрадного, оскверненного древесного малыша в Тельдрассиле. Деналан изучает его в своей зачарованной почве, чтобы понять неестественную болезнь, искажающую растительную жизнь острова.",al={"moss twined heart","moss-twined heart quest","blackmoss heart","сердце поросшее мхом","задание сердце поросшее мхом","сердце черномшеца злосмрадного"}}},fp="7,412,27.520.0,36.526.0,25.205.0,44.296.0,41.311.0,42.250.0,27.212.0,52.236.0"}
P.entries["npc:dendrite-starblaze"] = {n="Дендрит Блеск Звезд",s="Дендрит Блеск Звезд — ночной эльф-друид, живущий в священной деревне Ночная Гавань в Лунной поляне. Служа Кругу Кенария, он выступает важным наставником и проводником для начинающих друидов из числа ночных эльфов и таурен. Через него последователей призывают в священную рощу, чтобы они освоили важные обряды: очищение от ядов и единение с обликами природы.",h="Дендрит Блеск Звезд — ночной эльф-друид, живущий в священной деревне Ночная Гавань в Лунной поляне.",kw={"aquatic form","cenarion circle","curing the sick","dendrite starblaze","druid","lessons anew","moonglade","night elf","nighthaven","водный облик","круг кенария","лечение больных","дендрит блеск звезд","друид","уроки заново","лунная поляна","ночной эльф","ночная гавань"},ang={["class:Druid"]="Дендрит Блеск Звезд — один из ваших главных проводников при первой телепортации в Лунную поляну: он учит вас лечить недуги и осваивать водные облики.",["race:NightElf"]="Дендрит хранит классические обряды заботы о природе у кальдораев и приветствует посвящаемых кальдораев в ордене Кенария в Ночной Гавани.",["race:Tauren"]="Для друидов-таурен, приходящих в Лунную поляну из Мулгора, Дендрит служит живым доказательством того, что связь Круга Кенария выше вражды между Ордой и Альянсом."},sec={{t="Проводник в священной гавани",b="Находясь в Ночной Гавани, Дендрит Блеск Звезд воплощает беспристрастный и непреходящий дух Круга Кенария. Когда начинающие друиды учатся настраивать дух на «Телепортацию: Лунная поляна», Дендрит одним из первых встречает их по прибытии. Он соединяет древнюю традицию кальдораев и зарождающийся путь таурен, относясь ко всем, кто внял зову природы, как к родным под ветвями священной гавани."},{t="Испытания дикой природы",b="Главная обязанность Дендрита — посвящать учеников-друидов в глубокие тайны природы. Он направляет новичков через испытания, необходимые для понимания яда и недуга, отправляя их исследовать оскверненные воды и находить целебные травы. Он также следит за шагами, ведущими друидов к водным испытаниям, проверяя их терпение и выносливость под водой, прежде чем даровать единение с водными обликами."}},faq={{q="Кто такой Дендрит Блеск Звезд?",a="Дендрит Блеск Звезд — ночной эльф-друид и наставник Круга Кенария в Ночной Гавани в Лунной поляне. Он ведет развивающихся друидов через важные испытания и обучение своего класса.",al={"dendrite starblaze","who is dendrite","starblaze moonglade","дендрит блеск звезд","кто такой дендрит","блеск звезд лунная поляна"}},{q="Почему ночной эльф обучает таурен Орды?",a="Круг Кенария стоит вне политических фракций Альянса и Орды. В Лунной поляне ночные эльфы и таурены вместе практикуют искусство друидов по древним клятвам братства, оставляя мирские конфликты за горными перевалами.",al={"why does dendrite train horde","dendrite tauren druid","cross faction druid mentor","почему дендрит учит орду","дендрит друид таурен","наставник друидов обеих фракций"}},{q="Какие задания предлагает Дендрит Блеск Звезд?",a="Дендрит ведет несколько основополагающих испытаний друидов. Среди них задания на овладение лечением от яда и болезней, а также испытания на пути к единению, необходимому для водного облика.",al={"dendrite quests","starblaze quest list","задания дендрита","список заданий блеск звезд"}},{q="Где найти Дендрита Блеска Звезд?",a="Он находится в Ночной Гавани — поселении на северном берегу озера Элуне'ара в Лунной поляне.",al={"dendrite location","where is starblaze","dendrite starblaze map","где дендрит","где блеск звезд","дендрит блеск звезд карта"}},{q="Как молодые друиды впервые добираются до Дендрита?",a="Начинающих друидов учат заклинанию «Телепортация: Лунная поляна» их расовые наставники примерно на десятом уровне обучения. Оно переносит их прямо в Лунную поляну, где их ждет Дендрит.",al={"how to get to dendrite","teleport to moonglade quest","как добраться до дендрита","задание телепорт в лунную поляну"}},{q="Могут ли искатели приключений, не друиды, говорить с ним?",a="Не друиды могут посетить Ночную Гавань и поговорить с Дендритом, но он не предлагает обучение, испытания или задания тем, кто не принадлежит к друидским традициям Круга Кенария.",al={"non druid dendrite","can warrior talk to starblaze","не друид дендрит","может ли воин говорить с блеском звезд"}}},fp="18,368,27.425.0,18.422.0,26.175.0,40.246.0,42.189.0,38.107.0,54.202.0,44.165.0"}
P.entries["npc:deputy-feldon"] = {kw={"bridge","deputy feldon","feldon","gnolls","guard","lakeshire","redridge","мост","заместитель судьи фелдон","фелдон","гноллы","стражник","страж","приозерье","красногорье"},ang={["faction:Alliance"]="Фелдон олицетворяет отчаянное положение внешних земель Штормграда, где местные стражники вынуждены просить проходящих героев помочь сохранить мир короля."},sec={{t="Страж на взводе",b="Standing watch near the southern approach to the Lakeshire bridge, Deputy Feldon represents an overextended town guard fighting to keep basic trade and travel routes open. With the Blackrock orcs pressing from the north and gnoll packs overrunning the southern hills, guardsmen like Feldon are stretched to their limits. Unable to leave his post without compromising the town's perimeter, he relies on passing adventurers to cull the gnolls encroaching on the roadway before they can cut Lakeshire off entirely."}},faq={{q="Who is Deputy Feldon?",a="Заместитель судьи Фелдон — офицер городской стражи Приозерья, стоящий к югу от моста, соединяющего город с главной южной дорогой в Красногорье.",al={"feldon","who is feldon","deputy feldon role","фелдон","кто такой фелдон","роль заместителя судьи фелдона"}},{q="Почему заместитель судьи Фелдон беспокоится из-за гноллов?",a="Стаи гноллов становятся все смелее, подбираются к южной окраине города и донимают путников. Фелдон опасается, что если их число не сократить, они полностью перекроют южную дорогу в Приозерье.",al={"why gnolls","feldon gnoll problem","encroaching gnolls","почему гноллы","проблема фелдона с гноллами","наступающие гноллы"}},{q="Почему Фелдон не справляется с гноллами сам?",a="Стражи Приозерья остро нуждаются в людях и сталкиваются одновременно с угрозой орков и гноллов. Фелдон не может покинуть свой пост у моста, не оставив вход в город без охраны.",al={"why doesn't feldon fight","feldon duty","почему фелдон не сражается","долг фелдона"}},{q="Где найти заместителя судьи Фелдона?",a="Он несет вахту на дороге к югу от Большого моста Приозерья и следит за южными подходами к городу.",al={"feldon location","where is feldon","где фелдон","местонахождение фелдона"}}},fp="13,254,15.511.0,21.159.0,42.231.0,48.202.0,33.125.0"}
P.entries["npc:deputy-rainer"] = {n="Заместитель судьи Рейнер",s="Заместитель судьи Рейнер — офицер Армии Штормграда, расквартированный у Гарнизона у Западного ручья на западной границе Элвиннского леса. Ему поручено сдерживать натиск стай гноллов и бандитов, проникающих из Западного Края, и он координирует местную оборону, когда официальные подкрепления не прибывают.",h="Заместитель судьи Рейнер — офицер Армии Штормграда, расквартированный у Гарнизона у Западного ручья на...",kw={"deputy rainer","elwynn forest","gryan stoutmantle","hogger","marshal dughan","riverpaw","westbrook garrison","westfall","заместитель судьи рейнер","элвиннский лес","гриан камнегрив","дробитель","маршал дугхан","речная лапа","гарнизон у западного ручья","западный край"},ang={["faction:Alliance"]="Заместитель судьи Рейнер олицетворяет истончающиеся края военного влияния Штормграда и показывает героям Альянса, как местным гарнизонам приходится приспосабливаться, чтобы выжить без регулярной поддержки короны."},sec={{t="Оборона западной границы",b="Гарнизон у Западного ручья — самый западный оплот Элвиннского леса, расположенный у дороги, ведущей в Западный Край. Из-за политического паралича в Штормграде основная часть армии находится за границей или погрязла в бюрократии, и приграничные посты вроде Западного ручья остаются с крайне малым числом людей. Заместитель судьи Рейнер стоит у башни и организует ту скромную оборону, какую может собрать гарнизон. Дороги постоянно находятся под угрозой агрессивных гноллов Речной Лапы и бродячих воров, поэтому Рейнеру приходится полагаться на проезжих путников и наемных авантюристов, а не на королевские полки, чтобы лесные тропы оставались безопасными."},{t="Дорога в Западный Край",b="Помимо борьбы с угрозой со стороны стаи Речной Лапы и предостережений путникам о печально известном вожаке гноллов Дробителе, Рейнер служит важным звеном связи с неспокойными землями за рекой. Зная, что хаос на границах Элвиннского леса исходит от беззаконных ферм на западе, он направляет способных добровольцев в Западный Край, указывая им на Гриана Камнегрива и бедствующее Народное ополчение."}},faq={{q="Кто такой заместитель судьи Рейнер?",a="Заместитель судьи Рейнер — офицер Армии Штормграда, расквартированный в Гарнизоне у Западного ручья на западной окраине Элвиннского леса. Он отвечает за безопасность местных дорог и нанимает авантюристов для борьбы с окрестными угрозами.",al={"rainer elwynn","who is rainer","westbrook garrison officer","рейнер элвиннский лес","кто такой рейнер","офицер гарнизона у западного ручья"}},{q="Почему в Гарнизоне у Западного ручья не хватает людей?",a="Основные силы Армии Штормграда развернуты в других местах, а политический разброд в столице не позволяет регулярным подкреплениям доходить до отдаленных областей. Поэтому маршалу Дугхану в Златоземье приходится полагаться на независимых авантюристов, которые помогают Рейнеру.",al={"why no guards at westbrook","why is the garrison struggling","westbrook needs help","почему нет стражи у западного ручья","почему гарнизон бедствует","западному ручью нужна помощь"}},{q="Какие угрозы пытается отразить Рейнер?",a="Рейнер в основном занят сдерживанием стаи гноллов Речной Лапы, наводнившей лес к югу от гарнизона, бродячими ворами и печально известным вожаком гноллов Дробителем, который нападает на путников у границы.",al={"what enemies are near westbrook","riverpaw gnolls westbrook","westbrook gnolls","какие враги у западного ручья","гноллы речной лапы","гноллы у западного ручья"}},{q="Куда Рейнер отправляет авантюристов после зачистки гноллов?",a="Когда угроза гноллов у гарнизона подавлена, Рейнер направляет опытных авантюристов через западную границу в Западный Край, чтобы помочь Гриану Камнегриву и Народному ополчению у Сторожевого холма.",al={"where to go after rainer","rainer quest westfall","after westbrook garrison","куда идти после рейнера","задание рейнера западный край","после гарнизона у западного ручья"}}},fp="13,311,26.631.0,20.452.0,21.207.0,38.263.0,41.208.0,61.201.0"}
P.entries["npc:devrak"] = {n="Деврак",s="Деврак — орк, мастер наездников на ветрокрылах, расквартированный на Перекрестке в Степях. Будучи главным воздушным звеном центрального Калимдора, он руководит сетью виверн Орды, которые перевозят припасы и гонцов между Дуротаром, Мулгором и пограничными форпостами. Он также следит, чтобы важные грузы, такие как дичь и выделанные шкуры, бесперебойно доходили до столиц Орды.",h="Деврак — орк, мастер наездников на ветрокрылах, расквартированный на Перекрестке в Степях.",kw={"barrens","crossroads","devrak","flight master","orgrimmar","thunder bluff","wind rider","wyvern","степи","перекресток","деврак","мастер полетов","оргриммар","громовой утес","ветрокрыл","виверна"},ang={["faction:Horde"]="Деврак — незаменимый союзник для любого авантюриста Орды в Калимдоре, центральный узел, соединяющий земли орков, троллей и таурен.",["race:Orc"]="Деврак, расквартированный в засушливом сердце Степей, демонстрирует орочий талант обращаться с ветрокрылами Калимдора, сближаясь со свирепыми зверями ради господства в воздухе."},sec={{t="Хранитель гнезд Перекрестка",b="Деврак, расположившийся на пересечении главных торговых путей Калимдора, ухаживает за вивернами, которые связывают Орду на огромных расстояниях. Перекресток открыт палящему солнцу и уязвим для свинобразов, кентавров и разведчиков Альянса, поэтому быстрое воздушное сообщение незаменимо. Деврак работает и с опытными странниками, и с неопытными гонцами, подбирая седоков к обученным наездникам на ветрокрылах, способным пересечь саванну и достичь горных высот Мулгора или каменистых каньонов Дуротара."},{t="Припасы для Вождя и предводителя",b="Помимо перевозки путников, Деврак играет важную роль в снабжении границ. Охотники Степей добывают мясо и шкуры в изобилии, и Деврак помогает направлять их прямо к кухонным кострам Оргриммара и дубильщикам Громового Утеса. Знакомя начинающих гонцов с мастерами полетов на разных материках, он укрепляет воздушную артерию, питающую земли Орды."},{t="Смертоносное гнездо",b="Мастера полетов в спорных пограничных землях не могут позволить себе остаться беззащитными. Деврак — не просто укротитель зверей: когда Перекресток подвергается нападению, он призывает разъяренных виверн, и те разрывают незваных гостей ядовитыми жалами и когтями, делая его гнездо опасной целью для любого, кто осмелится напасть на поселение."}},faq={{q="Какова роль Деврака на Перекрестке?",a="Деврак — мастер полетов Орды на Перекрестке в Степях. Он ухаживает за ветрокрылами форпоста, открывает маршруты полета к соседним поселениям Калимдора и координирует перевозку гонцов, солдат и важных торговых грузов.",al={"who is devrak","what does devrak do","devrak job","crossroads flight master","кто такой деврак","что делает деврак","работа деврака","мастер полетов перекрестка"}},{q="Куда Деврак может меня доставить?",a="Из своего гнезда на Перекрестке Деврак связан с крупными столицами, такими как Оргриммар и Громовой Утес, а также с пограничными форпостами в Ясеневом лесу, Когтистых горах, Пылевых топях, Тысяче Игл и на южных рубежах — если вы предварительно поговорили с этими мастерами полетов.",al={"devrak flight paths","where can i fly from crossroads","crossroads flight routes","маршруты деврака","куда лететь с перекрестка","полеты с перекрестка"}},{q="Какие задания выдает Деврак?",a="Деврак помогает с заданиями гонцов, которые учат молодых авантюристов Орды пользоваться сетью полетов, в том числе доставить свежее мясо Гришке в Оргриммар и связки шкур в Громовой Утес.",al={"devrak quests","crossroads flight quest","задания деврака","задание полета перекрестка"}},{q="Как Деврак защищается, если Перекресток подвергся нападению?",a="Деврака охраняет его гнездо. Если на него нападут рейдеры Альянса или враждебные звери, он может призвать свирепых разъяренных виверн, которые помогут ему в бою и прогонят нападающих зубами и когтями.",al={"can devrak fight","killing devrak","devrak defense","может ли деврак сражаться","убить деврака","защита деврака"}},{q="Почему мастер полетов на Перекрестке так важен?",a="Степи — связующий хребет центрального Калимдора. Поскольку Перекресток соединяет Дуротар, Мулгор, Ясеневый лес и Когтистые горы, гнездо Деврака позволяет Орде быстро перебрасывать силы и координировать снабжение, не тратя дни на путь пешком.",al={"why is crossroads flight master important","crossroads location significance","почему важен мастер полетов перекрестка","значение перекрестка"}},{q="С какими существами работает Деврак?",a="Деврак управляет ветрокрылами, также известными как виверны. Эти драконоподобные крылатые хищники, обитающие на пиках и плато Калимдора, подружились с Ордой и служат надежными летающими скакунами на сложной местности.",al={"what mounts does devrak have","crossroads mounts","какие скакуны у деврака","скакуны перекрестка"}}},fp="6,381,31.509.0,43.382.0,14.350.0,40.258.0,24.282.0,30.189.0,61.189.0,60.262.0,34.211.0"}
P.entries["npc:dextren-ward"] = {n="Декстрен Вард",s="Декстрен Вард — печально известный преступник и расхититель могил, заключенный в Тюрьме Штормграда. До поимки он наживался на выкапывании тел на Кладбище Вороньего Холма в Сумеречном лесу и передавал их некроманту Морбенту Скверну. Теперь, оказавшись в разгаре кровавого бунта в тюрьме, он остается приговоренным к смерти городским советом Темнолесья.",h="Декстрен Вард — печально известный преступник и расхититель могил, заключенный в Тюрьме Штормграда.",kw={"councilman millstipe","crime and punishment","dextren ward","duskwood","grave robber","morbent fel","raven hill cemetery","stormwind","the stockade","член совета миллстайп","преступление и наказание","декстрен вард","сумеречный лес","расхититель могил","морбент скверн","кладбище вороньего холма","штормград","тюрьма"},ang={["class:Paladin"]="Сотрудничество Варда с некромантами, поставка им свежих трупов — отвратительное оскорбление святости Света и мирного покоя усопших.",["class:Priest"]="Осквернение священной земли на Вороньем Холме делает судьбу Варда долгом нравственного и духовного искупления.",["faction:Alliance"]="Для защитников Альянса, помогающих Темнолесью, покончить с Декстреном Вардом — акт справедливости для осквернленных семей Сумеречного леса и важная задача в восстановлении порядка в охваченной бунтом Тюрьме."},sec={{t="Грабеж могил в Сумеречном лесу",b="Прежде чем оказаться в цепях под улицами Штормграда, Декстрен Вард вел мрачный и прибыльный промысел в окутанных туманом чащах Сумеречного леса. Кладбище Вороньего Холма и без того было местом скорби и растущего ужаса, но Вард считал его могилы личной каменоломней. Он охотился не просто за безделушками и реликвиями, оставленными с мертвыми, а торговал плотью, выкапывая свежие могилы для местных темных практиков."},{t="Пешка некроманта",b="Главным клиентом Варда был Морбент Скверн, некромант, чьи темные ритуалы терзают Сумеречный лес и множат ряды нежити. Поставляя тела Скверну, Вард прямо способствовал ужасу, охватившему Темнолесье. Хотя власти Штормграда в конце концов поймали его и бросили в Тюрьму, его преступления навлекли на него неугасимую ненависть жителей Сумеречного леса, и Член совета Миллстайп потребовал руку Варда как доказательство свершившегося правосудия."},{t="Хаос в Тюрьме",b="Когда в Тюрьме вспыхнул масштабный мятеж, Варда не освободили союзники — его выпустили из камеры, чтобы он присоединился к хаосу в запертом подземелье. Вооруженный и жестокий, он владеет своим уголком тюрьмы и страхом отгоняет чужаков, что делает его одной из первоочередных целей сил Альянса, восстанавливающих порядок."}},faq={{q="Кто такой Декстрен Вард?",a="Декстрен Вард — известный преступник, заключенный в Тюрьме Штормграда. Это элитный заключенный-человек, повинный в ограблении мертвецов в Сумеречном лесу для темных ритуалов.",al={"who is dextren ward","dextren ward lore","stockade dextren","кто такой декстрен вард","предыстория декстрена варда","декстрен в тюрьме"}},{q="Почему Декстрен Вард находится в Тюрьме?",a="Варда поймали и заключили в тюрьму за расхищение могил на Кладбище Вороньего Холма в Сумеречном лесу. Вместо ценностей он выкапывал свежие трупы и продавал их прямо некроманту Морбенту Скверну.",al={"why was he arrested","dextren ward crime","what did dextren do","почему его арестовали","преступление декстрена варда","что сделал декстрен"}},{q="Кто хочет смерти Декстрена Варда?",a="Смерти Варда хочет Член совета Миллстайп из Темнолесья. Миллстайп жаждет возмездия за осквернение могил Сумеречного леса и требует отрубленную руку Варда как доказательство его смерти.",al={"who wants dextren dead","dextren ward bounty","crime and punishment questgiver","кто хочет смерти декстрена","награда за декстрена варда","преступление и наказание"}},{q="Как Вард связан с Морбентом Скверном?",a="Вард поставлял трупы Морбенту Скверну. Выкапывая свежезахороненных мертвецов на Кладбище Вороньего Холма, Вард обеспечивал Скверна сырьем для некромантических опытов и создания нежити.",al={"morbent fel connection","dextren ward morbent fel","who bought the bodies","связь с морбентом скверном","декстрен вард морбент скверн","кто покупал тела"}},{q="Где найти Декстрена Варда?",a="Он находится в Тюрьме Штормграда — тюрьме строгого режима в каналах Штормграда. Во время продолжающегося тюремного бунта он скрывается в одном из тюремных блоков.",al={"dextren ward location","where is dextren ward","where to find dextren","где декстрен вард","местонахождение декстрена варда","где найти декстрена"}},{q="Почему для задания нужна рука Декстрена?",a="Член совета Миллстайп прямо требует холодную мертвую руку Варда как неопровержимое вещественное доказательство того, что расхититель больше не сможет раскапывать могилы Сумеречного леса и наживаться на некромантии.",al={"why sever his hand","dextren ward hand","proof of death dextren","зачем отрубать руку","рука декстрена варда","доказательство смерти декстрена"}}},fp="12,354,25.431.0,23.452.0,21.368.0,20.169.0,36.190.0,28.175.0,41.206.0,32.182.0,42.186.0"}
P.entries["npc:dirania-silvershine"] = {n="Дирания Серебряное Сияние",s="Дирания Серебряное Сияние — ночной эльф, жительница Тенистой долины в Тельдрассиле. Преданная и наблюдательная, она присматривает за тихой рощей и заботится о своем спутнике Иверроне, когда его безрассудные затеи ставят его в опасное положение.",h="Дирания Серебряное Сияние — ночной эльф, жительница Тенистой долины в Тельдрассиле.",kw={"antidote","dirania","iverron","shadowglen","silvershine","teldrassil","webwood","противоядие","дирания","иверрон","тенистая долина","серебряное сияние","тельдрассил","древоплет"},ang={["race:NightElf"]="Для молодых ночных эльфов, впервые попадающих в Тенистую долину, Дирания служит ранним напоминанием об узах дружбы и о подкрадывающихся опасностях, угрожающих даже новейшим убежищам Мирового Древа."},sec={{t="Страж Тенистой долины",b="Дирания стоит среди тихих ветвей Тенистой долины, уединенной низины, где молодые ночные эльфы начинают служить Калимдору и Альянсу. Пока многие в курганах и святилищах думают о более широком духовном долге, Дирания следит за теми, кто ближе всего к ней, и чутко замечает тихие опасности, пробуждающиеся даже в сердце Тельдрассила."},{t="Беда друга",b="Главная забота Дирании — ее спутник Иверрон. Слишком ретивый и неосторожный рядом с ядовитыми лесными тварями, ползающими по долине, Иверрон часто попадает в беду. Когда его кусает ядовитый паук-древоплет из этих мест, Дирания сама берется найти желающих собрать ингредиенты и приготовить лекарство, пока яд не нанес непоправимый вред."}},faq={{q="Кто такая Дирания Серебряное Сияние?",a="Дирания Серебряное Сияние — ночной эльф, живущий в Тенистой долине в Тельдрассиле. Она выдает задания и в основном занята спасением и исцелением своего друга Иверрона, после того как он столкнулся с местными ядовитыми животными.",al={"dirania","who is dirania","dirania silvershine lore","дирания","кто такая дирания","дирания серебряное сияние предания"}},{q="Где найти Диранию Серебряное Сияние?",a="Дирания находится в Тенистой долине, начальной низине в Тельдрассиле, недалеко от центральной тропы возле Альдрассила.",al={"dirania location","where is dirania","find dirania silvershine","местонахождение дирании","где дирания","найти диранию серебряное сияние"}},{q="Как Дирания связана с Иверроном?",a="Дирания и Иверрон — близкие друзья. Дирания благоразумнее и осмотрительнее из них двоих: когда Иверрон действует глупо и его кусает местная тварь, она берется раздобыть противоядие.",al={"is dirania related to iverron","iverron and dirania","dirania's friend","дирания родственница иверрона","иверрон и дирания","друг дирании"}},{q="Какие задания дает Дирания?",a="Она дает задания, связанные с помощью ее спутнику, в первую очередь «Друг в беде» и «Противоядие для Иверрона»: искателям приключений нужно добыть ингредиенты для лекарства от паучьего яда, поразившего Иверрона.",al={"dirania quests","quests from dirania silvershine","iverron quest","задания дирании","задания дирании серебряное сияние","задание иверрона"}},{q="Почему Дирания беспокоится о пауках в Тенистой долине?",a="Пауки-древоплеты, обитающие в ветвях Тенистой долины, несут сильный яд. Опытные часовые справляются с ними, но неопытные эльфы вроде Иверрона часто недооценивают опасность и рискуют пасть жертвой их укусов.",al={"shadowglen spiders","why spiders in teldrassil","webwood danger","пауки тенистой долины","почему пауки в тельдрассиле","опасность древоплетов"}},{q="Состоит ли Дирания в каком-либо ордене или фракции?",a="Дирания — ночной эльф Альянса, мирно живущий в Тельдрассиле. Она не показана активным членом Сестринства Элуны или Круга Кенария, а скорее заботливой мирной жительницей, присматривающей за сородичами.",al={"dirania faction","is dirania a druid","is dirania a sentinel","фракция дирании","дирания друид","дирания часовой"}}},fp="19,222,23.348.0,16.388.0,27.209.0,37.119.0,42.211.0,31.194.0,51.221.0,51.217.0"}
P.entries["npc:dirge-quikcleave"] = {n="Могиль Быстроруб",s="Могиль Быстроруб — гоблин, мастер кулинарии и торговец, принимающий посетителей в таверне Прибамбасска. Известный по всему Азероту своими изобретательными блюдами, он обучает опытных поваров, стремящихся достичь ранга искусника в кулинарии.",h="Могиль Быстроруб — гоблин, мастер кулинарии и торговец, принимающий посетителей в таверне Прибамбасска.",kw={"artisan cooking","clamlette surprise","cooking trainer","dirge quikcleave","gadgetzan","goblin chef","tanaris","кулинария искусника","мидии с сюпризом","учитель кулинарии","могиль быстроруб","прибамбасск","гоблин-повар","танарис"},ang={["profession:Cooking"]="Могиль Быстроруб — главный наставник искусников для честолюбивых поваров: он испытывает их мастерство своими фирменными рецептами мидий, прежде чем даровать звание мастера.",["race:Orc"]="Учителя в Оргриммаре направляют честолюбивых гурманов Орды прямо в пустыню Танариса, чтобы они обратились к кулинарному наставничеству Могиля."},sec={{t="Мастер Колуна",b="Dirge Quikcleave resides in the dusty desert outpost of Gadgetzan, serving drinks and meats to parched travelers passing through the Tanaris sands. Despite operating out of a frontier tavern, he claims the mantle of the greatest living culinary artist in Azeroth. City cooking trainers across the world direct their most promising students to Dirge when they have exhausted ordinary lessons. His kitchen mastery is known for demanding, unusual ingredients—from giant clam meat and eggs for his Clamlette creations to the exotic beasts of distant shores."},{t="Экзотические вкусы и сомнительные услуги",b="За бравадой гурмана Могиль сохраняет предприимчивую жилку, свойственную любому гоблину в пустыне. Он поддерживает связи с эксцентричными личностями по всему Калимдору и не прочь взяться за опасные кулинарные затеи. Те, кто готов добыть мясо свирепых зверей, например чудовищных химероков с Острова Ужаса в Фераласе, найдут, что Могиль может приготовить сытные блюда, способные поддержать героев в опасных странствиях, — если не задавать слишком много вопросов о его личных делах."}},faq={{q="Кто такой Могиль Быстроруб?",a="Могиль Быстроруб — гоблин, мастер-повар и поставщик провизии в таверне Прибамбасска в Танарисе. Он известен как один из лучших кулинаров Азерота и учит начинающих поваров совершенствовать мастерство до ранга искусника.",al={"dirge quikcleave lore","who is dirge","gadgetzan chef","могиль быстроруб предания","кто такой могиль","повар прибамбасска"}},{q="Где найти Могиля Быстроруба?",a="Он находится в таверне торгового города картеля Трескобот Прибамбасск, в северных дюнах Танариса.",al={"dirge location","where is dirge quikcleave","dirge inn","местонахождение могиля","где могиль быстроруб","таверна могиля"}},{q="Почему учителя кулинарии отправляют к нему искателей приключений?",a="Учителя кулинарии в столицах могут довести навык ученика лишь до определенного предела. Когда повар достигает ранга умельца, учителя посылают его к Могилю в Прибамбасск по заданию «Ступай в Прибамбасск!», чтобы он доказал свое мастерство и получил доступ к кулинарии ранга искусника.",al={"why visit dirge","artisan cooking quest","to gadgetzan you go","зачем идти к могилю","задание на кулинарию искусника","ступай в прибамбасск"}},{q="Чем славится Могиль?",a="Могиль известен своими «Мидиями с сюпризом» — пикантным омлетом из мяса и яиц гигантских моллюсков, а также сытными волчьими стейками и мощными «Отпадными химеровыми отбивными Дирга».",al={"dirge recipes","clamlette surprise","what does dirge cook","рецепты могиля","мидии с сюпризом","что готовит могиль"}}},fp="16,214,21.555.0,31.506.0,24.244.0,36.115.0,48.245.0,32.177.0"}
P.entries["npc:doan-karhan"] = {n="Доан Кархан",s="Доан Кархан — человек, ученый и практик темных искусств, живущий в уединении на юге Степей. Он посвятил жизнь изучению демонических артефактов Пылающего Легиона, особенно загадочного Шара Соран'рука.",h="Доан Кархан — человек, ученый и практик темных искусств, живущий в уединении на юге Степей.",kw={"barrens","doan karhan","orb of soran'ruk","orb of zargain","warlock","степи","доан кархан","шар соран'рука","сфера заргейна","чернокнижник"},ang={["class:Warlock"]="Доан Кархан — бесценный источник для опытных чернокнижников: он обладает тайными знаниями, нужными, чтобы находить, чинить и использовать легендарные демонические сферы.",["faction:Alliance"]="Хотя Доан и человек, он действует вдали от Штормграда и Терамора, предпочитая одинокое изгнание в сердце Калимдора ограничениям Великого Альянса."},sec={{t="Отшельник Степей",b="Доан Кархан живет в одиноком лагере в дикой саванне на юге Степей, вдали от цивилизованных оплотов Альянса. Он удалился в глушь не ради обычного уединения, а чтобы без помех изучать опасные демонические реликвии. Доан обладает глубокими знаниями о могущественных сосудах Скверны: он владеет Сферой Заргейна и одержим легендарным Шаром Соран'рука. Практикующие чернокнижники часто обращаются к нему, занимаясь созданием артефактов и темными ритуалами."}},faq={{q="Где находится Доан Кархан?",a="Доан Кархан разбил лагерь на юге Степей, в стороне к востоку от Лагеря Таурахо и главной дороги. Он живет один на небольшой, легко не замечаемой поляне.",al={"doan karhan location","where is doan karhan","doan karhan southern barrens","местонахождение доана кархана","где доан кархан","доан кархан юг степей"}},{q="Почему человек живет один в Степях?",a="Доан Кархан выбрал изгнание во враждебной глуши, чтобы исследовать магические реликвии Пылающего Легиона. Такие темные изыскания о демонических сферах запрещены или находятся под пристальным надзором на мирных землях Альянса.",al={"why is doan here","why is there a human in barrens","doan karhan lore","почему доан здесь","почему человек в степях","доан кархан предания"}},{q="Что такое Шар Соран'рука?",a="Шар Соран'рука — древняя могущественная реликвия Легиона, наполненная темной силой. Доан Кархан обладает обширными знаниями о ее создании и о подобной Сфере Заргейна и направляет чернокнижников, желающих воссоздать ее.",al={"soranruk orb","orb of soran'ruk","what is orb of soran'ruk","шар соран'рука","сфера соран'рука","что такое шар соран'рука"}}},fp="11,236,25.487.0,29.160.0,43.214.0,29.224.0"}
P.entries["npc:doctor-gregory-victor"] = {n="Доктор Грегори Виктор",s="Доктор Грегори Виктор — хирург из Отрекшихся, служащий в оплоте Орды Павший Молот на Нагорье Арати. Считаясь лучшим травматологом Орды, он принимает экзамен у начинающих медиков, желающих освоить сложную сортировку раненых и полевую первую помощь. Его холодная, клиническая эффективность не дает бойцам на передовой развалиться посреди ожесточенных местных конфликтов.",h="Доктор Грегори Виктор — хирург из Отрекшихся, служащий в оплоте Орды Павший Молот на Нагорье Арати.",kw={"arathi highlands","doctor gregory victor","first aid","gregory victor","hammerfall","horde trauma","surgeon","triage","нагорье арати","доктор грегори виктор","первая помощь","грегори виктор","павший молот","травматолог орды","хирург","сортировка раненых"},ang={["faction:Horde"]="Доктор Грегори Виктор оказывает жизненно важную помощь раненым на поле боя в одном из самых опасных аванпостов Орды, помогая воинам на арати-фронте вернуться в строй.",["race:Undead"]="В отличие от ядовитых смесей Королевского фармацевтического общества, Доктор Виктор демонстрирует мастерство Отрекшихся в обычной анатомии смертных и восстановительной хирургии."},sec={{t="Хирург Павшего Молота",b="Хотя многие смотрят на фармацевтов Отрекшихся с подозрением, Доктор Грегори Виктор служит Орде практической полевой хирургией, а не мертвящей алхимией. Находясь в глубине спорного Нагорья Арати, в Павшем Молоте, он оперирует солдат, потрепанных разбойниками Синдиката, огров Тяжелого Кулака и силами Альянса. Его пост служит и главным испытательным полем для полевых медиков Орды, требуя беспощадной эффективности и умения выделять критических больных под сильным давлением."}},faq={{q="Кто такой Доктор Грегори Виктор?",a="Доктор Грегори Виктор — врач из Отрекшихся, служащий в Павшем Молоте на Нагорье Арати. Он главный хирург-травматолог Орды, отвечающий за сортировку раненых и обучение опытных полевых медиков.",al={"doctor victor","gregory victor","who is gregory victor","доктор виктор","грегори виктор","кто такой грегори виктор"}},{q="Где найти Доктора Грегори Виктора?",a="Он находится в крепости Павший Молот на северо-востоке Нагорья Арати.",al={"gregory victor location","where is victor","doctor victor where","местонахождение грегори виктора","где виктор","где доктор виктор"}},{q="Какую роль он играет для Орды?",a="Доктор Виктор строгим экзаменом проверяет многообещающих полевых медиков в сортировке раненых и учит их стабилизировать умирающих и изготавливать улучшенные тканевые повязки для боя на передовой.",al={"what does gregory victor do","gregory victor first aid","horde trauma doctor","что делает грегори виктор","грегори виктор первая помощь","травматолог орды"}},{q="Кто его коллега в Альянсе?",a="Доктор Густав ван Склифф, находящийся на Острове Терамор в Пылевых топях, руководит обучением Альянса сложной травматологии и сортировке раненых.",al={"alliance equivalent doctor victor","alliance triage doctor","аналог доктора виктора в альянсе","доктор сортировки альянса"}}},fp="21,369,21.487.0,29.225.0,39.93.0,37.191.0,32.136.0"}
P.entries["npc:doctor-gustaf-vanhowzen"] = {n="Доктор Густав ван Склифф",s="Доктор Густав ван Склифф — хирург-травматолог и главный врач Травматологов Альянса на Острове Терамор. Находясь в Цитадели, он обучает целителей острова и принимает экзамен у медиков, желающих освоить высшие ступени полевой сортировки и работы с повязками.",h="Доктор Густав ван Склифф — хирург-травматолог и главный врач Травматологов Альянса на Острове Терамор.",kw={"alliance trauma","artisan first aid","first aid","foothold citadel","gustaf vanhowzen","theramore","triage","vanhowzen","травматологи альянса","первая помощь искусника","первая помощь","цитадель","густав ван склифф","терамор","сортировка раненых","ван склифф"},ang={["faction:Alliance"]="Каждый медик Альянса, стремящийся освоить полевую хирургию, должен отправиться в Терамор и доказать свое умение сортировать раненых под бдительным взором Доктора ван Склиффа."},sec={{t="Главный врач Терамора",b="Доктор Густав ван Склифф, находящийся на нижнем этаже Цитадели на Острове Терамор, отвечает за медицинскую помощь войскам леди Джайны Праудмур и обучает полевых целителей оплота. В суровых условиях Пылевых топей ван Склифф требует строгой полевой компетентности и лично подвергает опытных медиков напряженному испытанию по сортировке раненых, чтобы убедиться, что они могут выделять критические раны под сильным давлением."}},faq={{q="Где найти Доктора Густава ван Склиффа?",a="Доктор ван Склифф находится на нижнем этаже Цитадели, главной крепости на Острове Терамор в Пылевых топях.",al={"vanhowzen location","where is gustaf vanhowzen","gustaf vanhowzen spot","местонахождение ван склиффа","где густав ван склифф","место густава ван склиффа"}},{q="Какую роль ван Склифф играет для Альянса?",a="Он главный врач Травматологов Альянса и ведущий хирург-травматолог Терамора. Помимо руководства медицинской палатой гарнизона, он обучает опытных полевых медиков Альянса первой помощи на уровне искусника.",al={"what does vanhowzen do","vanhowzen role","who is doctor vanhowzen","что делает ван склифф","роль ван склиффа","кто такой доктор ван склифф"}},{q="Чему Доктор ван Склифф учит игроков?",a="Он проводит оценку по первой помощи ранга искусника, позволяющую опытным медикам повысить предел навыка, и обучает квалифицированных специалистов изготавливать улучшенные повязки, такие как плотные бинты из магической ткани и бинты из рунной ткани.",al={"what can i learn from vanhowzen","vanhowzen training","first aid from vanhowzen","чему научит ван склифф","обучение у ван склиффа","первая помощь у ван склиффа"}},{q="Есть ли у Орды аналог Доктора ван Склиффа?",a="Да. Равный ему специалист-травматолог Орды — Доктор Грегори Виктор, обучающий полевых медиков и проводящий экзамены по сортировке раненых в Павшем Молоте на Нагорье Арати.",al={"horde triage trainer","horde vanhowzen counterpart","who is horde first aid master","учитель сортировки орды","аналог ван склиффа в орде","кто мастер первой помощи орды"}}},fp="23,268,28.425.0,43.136.0,48.222.0,41.216.0,54.167.0"}
P.entries["npc:donova-snowden"] = {n="Донова Снегонора",s="Донова Снегонора — отважная исследовательница-дворф, разбившая лагерь у термальных вод возле Источников Ледяного Пламени в Зимних Ключах. Несмотря на лютый холод и враждебных животных, она изучает необычную термальную активность региона и наблюдает за все более одержимыми фурболгами племени Зимней Спячки.",h="Донова Снегонора — отважная исследовательница-дворф, разбившая лагерь у термальных вод возле Источников...",kw={"donova snowden","firewater","frostfire hot springs","furbolg","researcher","winterfall","winterspring","донова снегонора","огненная вода","источники ледяного пламени","фурболг","исследователь","зимняя спячка","зимние ключи"},ang={["faction:Horde"]="Несмотря на дворфийское происхождение, Донова готова не обращать внимания на принадлежность к фракции, чтобы нанять способных разведчиков против диких зверей и одержимых фурболгов Зимних Ключей.",["race:Dwarf"]="Встретить собрата-дворфа, в одиночку отважившегося на заснеженные вершины, — привычное дело: это показывает неизменную тягу дворфов к полевой работе и исследованиям вдали от Каз Модана."},sec={{t="Одинокая исследовательница в снегах",b="Пока большинство путников держатся безопасного Круговзора, Донова Снегонора решила разбить лагерь в ледяной глуши возле Источников Ледяного Пламени. Она проводит дни, изучая любопытные геотермальные аномалии, пробивающиеся сквозь вечную мерзлоту, а также темные влияния, угрожающие местным животным Зимних Ключей. Практичная и решительная, она привлекает проходящих мимо искателей приключений как Альянса, так и Орды, чтобы собирать образцы и помогать сдерживать местные угрозы."},{t="Изучение племени Зимней Спячки",b="Основное внимание Доновы сосредоточено на фурболгах племени Зимней Спячки, чье поведение скатилось к беспорядочной агрессии. Исследуя сильные зелья вроде огненной воды Зимней Спячки и странные ядовитые вещества, ходящие среди племен, она стремится выяснить первопричину их внезапного безумия. Ее полевые исследования делают ее важным контактом для всех, кто хочет понять порчу, распространяющуюся по северным горам."}},faq={{q="Где найти Донову Снегонора?",a="Донова Снегонора разбила лагерь у небольшого горячего источника к юго-западу от Источников Ледяного Пламени в Зимних Ключах, через главную дорогу от них.",al={"donova snowden location","where is donova","donova snowden map","донова снегонора где находится","где донова","донова снегонора на карте"}},{q="Почему Донова живет здесь, на лютом морозе?",a="Она проводит экологическое исследование необычных горячих источников Зимних Ключей и изучает порчу, поразившую местное племя фурболгов Зимней Спячки.",al={"why is donova in winterspring","donova snowden purpose","почему донова в зимних ключах","чем занимается донова снегонора"}},{q="Станет ли Донова работать с игроками Орды?",a="Да. Хотя Донова — дворф, она работает как независимый исследователь и дает задания искателям приключений как Альянса, так и Орды.",al={"is donova alliance only","can horde talk to donova","donova snowden faction","донова только для альянса","может ли орда говорить с доновой","фракция донова снегонора"}},{q="Что Донова исследует у фурболгов племени Зимней Спячки?",a="Она изучает загадочную порчу, ввергающую племя Зимней Спячки в безумие, в частности их странные зелья вроде огненной воды Зимней Спячки и мерзкие ядовитые вещества, найденные у их бегунов.",al={"donova furbolg quest","winterfall firewater research","задание донова фурболги","исследование огненной воды зимней спячки"}}},fp="14,292,29.469.0,28.457.1,32.130.0,44.159.0,36.128.0,63.214.0"}
P.entries["npc:donyal-tovald"] = {n="Донал Товальд",s="Донал Товальд — управитель-человек, служащий в Королевской библиотеке Крепости Штормграда. В рамках инициативы, начатой юным королем Андуином Ринном, он следит за сохранностью книг королевства и работает над распространением копий исторических текстов среди широкой публики.",h="Донал Товальд — управитель-человек, служащий в Королевской библиотеке Крепости Штормграда.",kw={"anduin wrynn","books","donyal tovald","history","librarian","royal library","stormwind keep","андуин ринн","книги","донал товальд","история","библиотекарь","королевская библиотека","крепость штормграда"},ang={["class:Mage"]="Маги, посещающие Крепость Штормграда, могут оценить преданность Товальда сохранению письменных знаний, пусть эти тексты и скорее исторические, чем тайные.",["race:Human"]="Для людей Штормграда Товальд олицетворяет стремление восстановить и сохранить свою культуру и записанную историю после Первой войны и восстановления столицы."},sec={{t="Хранитель истории Штормграда",b="Донал Товальд работает в тихих альковах Королевской библиотеки в Крепости Штормграда и заботится об обширном собрании исторических хроник, свитков и научных трудов королевства. Хотя библиотека в основном служит знати и королевскому двору, юный король Андуин Ринн поддержал инициативу сделать знания доступнее для простых горожан. Товальд занимается сохранением и копированием этих текстов, помогая тому, чтобы уроки и победы Альянса не были забыты среди бурной политической обстановки в королевстве."}},faq={{q="Кто такой Донал Товальд?",a="Донал Товальд — библиотекарь-человек, служащий в Королевской библиотеке Крепости Штормграда. Он ведет архивы королевства и руководит инициативой, поддержанной королем Андуином Ринном, по распространению копий исторических книг среди народа.",al={"who is tovald","royal librarian","donyal tovald lore","кто такой товальд","королевский библиотекарь","донал товальд предыстория"}},{q="Где найти Донала Товальда?",a="Его можно найти в Королевской библиотеке в восточной части Крепости Штормграда, среди книжных полок и исторических свитков.",al={"donyal tovald location","where is tovald","how to find tovald","донал товальд где находится","где товальд","как найти товальда"}},{q="Почему он раздает книги горожанам?",a="Юный король Андуин Ринн поддержал королевский проект по просвещению народа и распространению знаний. Донал Товальд — управитель, который следит за копированием и раздачей этих королевских рукописей.",al={"anduin book initiative","stormwind library project","why does he give books","инициатива андуина с книгами","проект библиотеки штормграда","почему он раздает книги"}},{q="Связан ли он с Домом знати или с духовенством?",a="Товальд подчиняется непосредственно короне как хранитель королевских архивов в Крепости Штормграда и занимается историческими и научными текстами, а не церковными или политическими доктринами.",al={"is tovald church of light","tovald faction","товальд церковь света","фракция товальда"}}},fp="13,260,30.548.0,21.230.0,31.134.0,40.201.0,56.186.0"}
P.entries["npc:doomsayer-wiserunner"] = {n="Провидец Хранитель Мудрости",s="Этот уважаемый старейшина-таурен, известный как Провидец Хранитель Мудрости, верно служит своему народу на холмистых равнинах Мулгора. Из пещеры в холмах к северо-западу от Деревни Кровавого Копыта он помогает молодым храбрецам-тауренам проходить традиционные обряды, ведущие к духовной зрелости.",h="Этот уважаемый старейшина-таурен, известный как Провидец Хранитель Мудрости, верно служит своему народу на...",kw={"camp narache","doomsayer wiserunner","mulgore","rite of vision","rite of wisdom","seer wiserunner","tauren elder","лагерь нараче","предсказатель хранитель мудрости","мулгор","обряд прозрения","обряд мудрости","провидец хранитель мудрости","старейшина таурен"},ang={["class:Shaman"]="Шаманы увидят в Хранителе Мудрости блюстителя древних традиций, понимающего послания, вплетенные в землю и небо.",["race:Tauren"]="Для молодых шу'хало, отправляющихся за пределы Плато Красного Облака, Провидец Хранитель Мудрости — важный наставник на пути предков к духовной зрелости."},sec={{t="Проводник по священному пути",b="Провидец Хранитель Мудрости живет среди мягких утесов Мулгора как старейшина и мистик шу'хало. Когда молодые охотники и шаманы проходят первые испытания силы и прозрения, их отправляют к нему за советом во время обрядов предков. Он толкует видения Матери-Земли и наставляет молодежь, как почитать предков, даруя прочную мудрость, объединяющую разрозненные кочевые племена в единую общину."}},faq={{q="Почему этого персонажа называют «Предсказатель Хранитель Мудрости»?",a="Он известен как Провидец Хранитель Мудрости, почитаемый старейшина-таурен, пользующийся уважением племен Мулгора. Он не имеет отношения к предсказанию бед: его роль — наставлять молодых посвящаемых в священных обрядах.",al={"doomsayer wiserunner name","why doomsayer","seer vs doomsayer","имя предсказатель хранитель мудрости","почему предсказатель","провидец или предсказатель"}},{q="Какую роль он играет в Мулгоре?",a="Провидец Хранитель Мудрости — духовный наставник молодых тауренов. После того как храбрецы отправляются на первые поиски видений, он принимает их для прохождения традиционного Обряда мудрости, проверяя их готовность служить племени и Матери-Земле.",al={"what does wiserunner do","seer wiserunner purpose","wiserunner role","чем занимается хранитель мудрости","назначение провидца хранителя мудрости","роль хранителя мудрости"}},{q="Где найти Провидца Хранителя Мудрости?",a="Его можно найти в пещере в холмах к северо-западу от Деревни Кровавого Копыта, куда видение из Обряда прозрения приводит молодых тауренов. Оттуда он отправляет их к востоку от Громового Утеса, к духам предков в Красных скалах.",al={"where is wiserunner","seer wiserunner location","wiserunner coords","где хранитель мудрости","провидец хранитель мудрости где находится","хранитель мудрости координаты"}}},fp="15,293,26.435.0,64.196.0,34.235.0,35.217.0"}
P.entries["npc:doras"] = {n="Дорас",s="Дорас — главный мастер ветрокрылов Орды в Оргриммаре; он обитает высоко на деревянной башне над Аллеей Силы. Он управляет вивернами столицы, отправляя гонцов, разведчиков и путников по всему Калимдору.",h="Дорас — главный мастер ветрокрылов Орды в Оргриммаре; он обитает высоко на деревянной башне над Аллеей Силы.",kw={"doras","flight master","orgrimmar","valley of strength","wind rider master","wyvern","дорас","мастер полетов","оргриммар","аллея силы","мастер ветрокрылов","виверна"},ang={["faction:Horde"]="Для любого искателя приключений Орды Дорас — главная воздушная артерия из столицы, позволяющая быстро добираться до союзных поселений по всему Калимдору."},sec={{t="Хозяин небесного пути",b="На деревянной площадке над Аллеей Силы Дорас ухаживает за крылатыми хищниками, известными как ветрокрылы, или виверны. С тех пор как Орда обосновалась в Дуротаре, эти хитрые кожистокрылые твари стали основой связи и перевозок Орды по Калимдору. Дорас заботится о них, подбирая отдохнувших скакунов всадникам и следя за тем, чтобы важные сообщения и подкрепления достигали дальних застав, таких как Перекресток, Громовой Утес и поселения в глубине Ясеневого леса или Пылевых топей."}},faq={{q="Где найти Дораса?",a="Дорас находится на вершине башни полетов, прямо над Аллеей Силы в Оргриммаре. До его насеста можно добраться по извилистым пандусам центральных деревянных построек у входа в город.",al={"doras location","where is orgrimmar flight master","orgrimmar wyvern master","дорас где находится","где мастер полетов оргриммара","мастер виверн оргриммара"}},{q="Каких существ обучает Дорас?",a="Дорас управляет ветрокрылами, которых также часто называют вивернами. Эти разумные ядовитые крылатые хищники, обитающие в засушливых скалах и саваннах Калимдора, подружились с Ордой и служат надежными летающими скакунами на большие расстояния.",al={"orgrimmar mounts","what does doras fly","what are wind riders","скакуны оргриммара","на ком летает дорас","кто такие ветрокрылы"}},{q="Куда Дорас может отправить путников?",a="Со своего насеста в Оргриммаре Дорас связывает путников с устоявшимися заставами Орды в центральном и северном Калимдоре, включая Перекресток в Степях, Громовой Утес в Мулгоре и военные лагеря в Ясеневом лесу и дальше.",al={"doras flight paths","where can i fly from orgrimmar","orgrimmar flight routes","маршруты дораса","куда можно полететь из оргриммара","полеты из оргриммара"}}},fp="5,225,20.498.0,23.213.0,32.246.0,31.232.0"}
P.entries["npc:doren"] = {n="Дорен",s="Лейтенант Дорен командует Лагерем Повстанцев, укрывшимся на севере Тернистой долины. Когда-то офицер под началом Полковника Курцена, Дорен поднял мятеж, после того как его начальник и другие участники экспедиции впали в безумие. Теперь он руководит партизанским сопротивлением, стремясь найти источник недуга и уничтожить Курцена.",h="Лейтенант Дорен командует Лагерем Повстанцев, укрывшимся на севере Тернистой долины.",kw={"bookie herod","colonel kurzen","doren","kurzen","kurzen's compound","lieutenant doren","rebel camp","stranglethorn","thorsen","букмекер герод","полковник курцен","дорен","курцен","лагерь курцена","лейтенант дорен","лагерь повстанцев","тернистая долина","торсен"},ang={["faction:Alliance"]="Для солдат Альянса Дорен олицетворяет трагические последствия джунглевой экспедиции Штормграда, давая шанс исправить зло Курцена и вернуть порядок на дикий рубеж.",["race:Human"]="Люди узнают в Дорене военную дисциплину — напоминание о том, как одинокая служба вдали от Королевства Штормград сказывается на рассудке и боевом духе."},sec={{t="Мятеж в джунглях",b="Лейтенант Дорен был направлен в Тернистую долину под знаменем Штормграда и командованием Полковника Курцена. Экспедиция должна была закрепиться в диких южных джунглях, но быстро пошла прахом, когда Курцен и его ближний круг поддались неистовому, жестокому безумию. Не желая отказываться от рассудка и чести, Дорен и отряд верных бойцов нарушили строй. Они бежали на север и основали Лагерь Повстанцев у дороги, предпочтя измену рабскому служению безумцу."},{t="В поисках правды",b="Со своей ненадежной заставы Дорен руководит операциями против Лагеря Курцена. Он поддерживает снабжение через нейтральные стороны, в том числе гоблинов вроде Кразека в Пиратской бухте, чтобы его редеющие отряды были сыты и вооружены. Помимо выживания, Дорен ищет ответы: он засылает шпионов, таких как рядовой Торсен, в тыл врага, чтобы узнать, что прокляло Полковника, и выявить предателей и пособников вроде букмекера Герода. В конечном счете Дорен верит, что единственный способ спасти честь того, что осталось от экспедиции, — покончить с самим Курценом."}},faq={{q="Кто такой лейтенант Дорен?",a="Лейтенант Дорен — предводитель Лагеря Повстанцев на севере Тернистой долины. Прежде второй после Полковника Курцена в экспедиции из Штормграда, Дорен возглавил отколовшуюся группу солдат, отказавшихся следовать за Полковником после его безумия.",al={"who is doren","doren lore","rebel camp leader","кто такой дорен","дорен предыстория","предводитель лагеря повстанцев"}},{q="Почему Дорена считают повстанцем?",a="Дорен и его отряд подняли мятеж против своего командира, Полковника Курцена. Поскольку Курцен был официально назначенным главой экспедиции, отделение и вооруженное выступление против него формально сделали Дорена и его людей мятежниками, хотя они порвали с ним, чтобы сохранить рассудок и противостоять тирании Курцена.",al={"why is it called rebel camp","why did doren rebel","kurzen mutiny","почему лагерь повстанцев","почему дорен восстал","мятеж против курцена"}},{q="Что свело Полковника Курцена с ума?",a="Точный источник безумия, поразившего Курцена и его ближний круг, остается тайной, которую Дорен активно пытается раскрыть. Дорен использует разведку и лазутчиков, чтобы выяснить, что развратило его бывшего командира в глубине джунглей.",al={"why did kurzen go crazy","kurzens madness","почему курцен сошел с ума","безумие курцена"}},{q="Как Дорен снабжает Лагерь Повстанцев?",a="Отрезанный от официальной поддержки Штормграда, Дорен полагается на тайные поставки и торговые договоренности с третьими сторонами. В частности, он взаимодействует с гоблинами-торговцами вроде Кразека в южной пиратской гавани Пиратская бухта, чтобы снаряжать своих людей.",al={"rebel camp supplies","doren supplies","снабжение лагеря повстанцев","снабжение дорена"}},{q="Кто такой букмекер Герод и как он связан с Дореном?",a="Букмекер Герод — соратник в отрядах Курцена. Дорен подозревает, что Герод причастен к раскрытию истинной преданности тайного агента Дорена, рядового Торсена, когда тот проникал в лагерь.",al={"bookie herod","herod rebel camp","букмекер герод","герод лагерь повстанцев"}},{q="Подчиняется ли Дорен Штормграду?",a="Дорен остается верен идеалам Альянса, но поскольку он нарушил строй против командира в поле, он действует самостоятельно. Он приветствует искателей приключений Альянса, готовых помочь исправить последствия катастрофической экспедиции.",al={"doren alliance","doren stormwind allegiance","дорен альянс","дорен верность штормграду"}}},fp="5,319,22.497.0,20.558.1,24.242.0,32.324.0,30.242.0,44.251.0,56.210.0,31.223.0"}
P.entries["npc:dorn-plainstalker"] = {n="Дорн Вольный Ловчий",s="Дорн Вольный Ловчий — тауренский старейшина-отшельник, живущий в Углу Семи Ветров над каньонами Тысячи Игл. Он следит за проведением традиционных обрядовых испытаний, проверяя характер и стойкость искателей приключений из Орды. Через испытания веры, выносливости, силы и знаний он определяет, достойны ли путники служить Матери-Земле и своему народу.",h="Дорн Вольный Ловчий — тауренский старейшина-отшельник, живущий в Углу Семи Ветров над каньонами Тысячи Игл.",kw={"dorn plainstalker","freewind post","tauren trial","test of endurance","test of faith","test of lore","test of strength","thousand needles","weathered nook","дорн вольный ловчий","застава вольного ветра","тауренское испытание","испытание выносливости","испытание веры","испытание знаний","испытание силы","тысяча игл","угол семи ветров"},ang={["faction:Horde"]="Дорн принимает всех героев Орды, готовых пройти его испытания, и следит, чтобы воины, охотники и шаманы всех рас доказали свою доблесть в суровых глухих землях Калимдора.",["race:Tauren"]="Для тауренов, бродящих по Тысяче Игл, Дорн воплощает продолжение кочевых традиций предков и духовных обрядов, проверяющих ваше равновесие с Матерью-Землей."},sec={{t="Отшельник высоких утесов",b="Дорн Вольный Ловчий уединился в неглубокой пещере на вершине скал Угла Семи Ветров, вдали от суеты Заставы Вольного Ветра. Чтобы добраться до его горного убежища, нужно пробираться по отвесным северным утесам над возвышающимися внизу плато. С этого тихого места Дорн хранит древние обычаи и судит тех, кто ищет наставления в суровых южных степях."},{t="Четыре испытания",b="Дорн Вольный Ловчий проводит паломников через череду трудных испытаний, которые должны измерить главные добродетели тауренского героя: веру, выносливость, силу и знания. Это не простое упражнение в грубой силе: искателям приходится побороть страх, слепо шагнуть в неизвестность, пережить хитрых хищников глуши и поразмыслить о священной истории Калимдора, прежде чем пройти последнее испытание."}},faq={{q="Кто такой Дорн Вольный Ловчий?",a="Дорн Вольный Ловчий — тауренский отшельник и старейшина, живущий в Углу Семи Ветров, уединенном убежище на утесе высоко над Тысячей Игл. Он проводит традиционные испытания для будущих героев Орды.",al={"who is dorn","dorn lore","dorn plainstalker","кто такой дорн","дорн предания","дорн вольный ловчий"}},{q="Где найти Дорна Вольного Ловчего?",a="Он находится в пещере в Углу Семи Ветров. От Заставы Вольного Ветра идите на север к высоким утесам у края каньона, затем следуйте по гребню на восток, пока не найдете подъем к его горному убежищу.",al={"where is dorn","how to reach dorn plainstalker","weathered nook location","где дорн","как добраться до дорна вольного ловчего","угол семи ветров расположение"}},{q="Какие испытания проводит Дорн?",a="Дорн руководит четырьмя священными испытаниями: Испытанием веры, Испытанием выносливости, Испытанием силы и Испытанием знаний. Их прохождение доказывает мужество путника, его физическую стойкость, боевое умение и уважение к традициям.",al={"dorn plainstalker quests","test of faith","trials of passage thousand needles","задания дорна вольного ловчего","испытание веры","испытания тысяча игл"}},{q="Что такое Испытание веры?",a="В Испытании веры паломник должен шагнуть с головокружительного утесного помоста в пропасть, показав абсолютное доверие и преодолев первобытный страх.",al={"leap of faith thousand needles","test of faith dorn","прыжок веры тысяча игл","испытание веры дорн"}},{q="Почему Дорн живет один в пещере?",a="Дорн следует аскетичным духовным традициям тауренов. Живя в одиночестве на высотах Угла Семи Ветров, вдали от повседневной торговли и обороны Заставы Вольного Ветра, он сохраняет спокойное место для размышлений и испытаний искателей.",al={"why is dorn isolated","dorn plainstalker background","почему дорн отшельник","дорн вольный ловчий история"}},{q="Связан ли Дорн с Заставой Вольного Ветра?",a="Хотя он живет вне самой Заставы Вольного Ветра, Дорн — верный член Орды и тауренских племен, помогающий отважным путникам, бредущим по продуваемым ветрами каньонам.",al={"freewind post elder","is dorn horde","старейшина заставы вольного ветра","дорн орда"}}},fp="17,395,25.386.0,15.401.0,25.212.0,35.215.0,37.210.0,26.152.0,35.237.0,38.171.0"}
P.entries["npc:drum-fel"] = {n="Драм Желчный",s="Драм Желчный — командир-орк, стоящий во главе аванпоста Орды Павший Молот на Нагорье Арати. Вместе с женой Корин он руководит военными действиями по защите убежища от наступающих троллей, огров и остатков людей. Его стратегия жизненно важна для создания прочного оплота Орды в Арати.",h="Драм Желчный — командир-орк, стоящий во главе аванпоста Орды Павший Молот на Нагорье Арати.",kw={"arathi highlands","boulderfist","drum fel","hammerfall","korin fel","orkalar","witherbark","нагорье арати","тяжелый кулак","драм желчный","павший молот","корин желчная","ор'калар","сухокожие"},ang={["faction:Horde"]="Для воинов Орды, продвигающихся по Восточным королевствам, Драм Желчный — один из главных военных координаторов, защищающих хрупкую связь между Подгородом и южными землями.",["race:Orc"]="Драм Желчный воплощает практическую военную стойкость, нужную для восстановления жизни орков в Восточных королевствах: он держится на той самой земле, где когда-то стояли лагеря для интернированных."},sec={{t="Страж Павшего Молота",b="Драм Желчный, находясь в укрепленном убежище Павший Молот, отвечает за оборону и расширение владений Орды в Арати. Окруженный соперниками, он координирует военные удары по лесным троллям Сухокожих и клану огров Тяжелого Кулака, удерживающему Камен'гор и Крепость Тяжелого Кулака. Драм понимает, что Павший Молот не может выжить в изоляции: чтобы процветать, он должен сломить силу соседей. Поэтому он регулярно отправляет опытных бойцов на вражескую территорию, чтобы сорвать угрозы прежде, чем они нападут на лагерь Орды."},{t="Угроза в Стромгарде",b="Поход Драма Желчного простирается до руин Крепости Стромгард, где огры Тяжелого Кулака окопались среди павшего человеческого королевства. Много лет назад Драм победил огра-громилу Ор'Калара и нажил себе непрощающего врага. Драм не знает, что Ор'Калар ждет в Стромгарде, жаждя мести. Чтобы уберечь мужа от засады, вызванной этой враждой, его жена Корин тайно принимает меры, скрывая присутствие Ор'Калара, и рассчитывает на посторонних искателей приключений, которые устранят угрозу, пока Драм сам не бросился в бой."}},faq={{q="Кто такой Драм Желчный?",a="Драм Желчный — вождь орков в Павшем Молоте на Нагорье Арати. Он координирует военные кампании крепости против соперничающих сил региона.",al={"drum fel","who is drum fel","hammerfall drum","драм желчный","кто такой драм желчный","павший молот драм"}},{q="Где найти Драма Желчного?",a="Он находится в поселении Орды Павший Молот на северо-востоке Нагорья Арати, к востоку от главной дороги, ведущей на север во Внутренние земли.",al={"drum fel location","where is drum fel","find drum fel","драм желчный расположение","где драм желчный","найти драма желчного"}},{q="Кто такая Корин Желчная?",a="Корин Желчная — жена Драма. Она тоже живет в Павшем Молоте.",al={"korin fel","drum fel wife","корин желчная","жена драма желчного"}},{q="Почему огр Ор'Калар хочет смерти Драма Желчного?",a="Много лет назад Драм Желчный победил Ор'Калара в бою. Глубоко униженный огр теперь скрывается в руинах Крепости Стромгард и замышляет месть орку-командиру.",al={"orkalar grudge","why does orkalar hate drum fel","or'kalar drum fel","вражда ор'калара","почему ор'калар ненавидит драма желчного","ор'калар драм желчный"}},{q="Каким угрозам противостоит Драм Желчный?",a="Драм Желчный направляет удары против огров Тяжелого Кулака в Камен'горе, Крепости Тяжелого Кулака и Крепости Стромгард, а также против соседнего племени троллей Сухокожих.",al={"drum fel quests","drum fel enemies","who does drum fel fight","задания драма желчного","враги драма желчного","с кем сражается драм желчный"}}},fp="8,316,20.585.0,24.525.1,16.161.0,28.161.0,17.57.0,46.169.0,34.155.0"}
P.entries["npc:drusilla-la-salle"] = {n="Друзилла ла Салле",s="Друзилла ла Салле — человек, учитель чернокнижников, живущая на мрачном кладбище за пределами Аббатства Североземья. Действуя на краю Священного ордена Североземья, она наставляет начинающих заклинателей в темных искусствах призыва и тьмы. Когда запретные знания выходят за стены аббатства, она без колебаний пускает в ход расчетливость и темную магию, чтобы заполучить их.",h="Друзилла ла Салле — человек, учитель чернокнижников, живущая на мрачном кладбище за пределами Аббатства...",kw={"abbey","drusilla la salle","graveyard","northshire","powers of the void","stolen tome","warlock trainer","аббатство","друзилла ла салле","кладбище","североземье","силы бездны","украденный том","учитель чернокнижников"},ang={["class:Priest"]="Стоя за пределами святых залов Североземья, Друзилла воплощает темную противоположность вашего призвания: она торгует тьмой и демоническими сделками рядом с освященным кладбищем.",["class:Warlock"]="Друзилла — ваш первый наставник в темных искусствах: она ведет вас к практическому владению проклятиями и призывом Скверны и учит скрывать честолюбие на виду у всех."},sec={{t="Тени на святой земле",b="Пока паладины и жрецы занимаются под витражами Аббатства Североземья, Друзилла ла Салле остается на открытом воздухе среди надгробий кладбища. Демонология и магия Скверны глубоко запретны в королевстве Штормград, и чернокнижникам приходится жить на окраине приличного общества. Друзилла дает начальное обучение новичкам-чернокнижникам, получившим порочные письма, и учит их управлять силой тьмы, не навлекая немедленного гнева властей аббатства."},{t="Силы Бездны",b="В Библиотечном крыле Аббатства Североземья тайно хранится несколько опасных и запретных томов, среди них «Силы Бездны». Друзилла давно жаждет заполучить рукопись, но чернокнижник, слоняющийся в охраняемых архивах, сразу вызвал бы подозрения. Ее шанс наступает, когда послушник-отступник бежит из аббатства к Братству Справедливости, прихватив книгу. Воспользовавшись кражей, Друзилла посылает учеников выследить предателя и доставить гримуар ей под предлогом возвращения имущества аббатства."}},faq={{q="Почему чернокнижнику позволено находиться рядом с Аббатством Североземья?",a="Церковь Священного Света и руководство Штормграда глубоко не доверяют чернокнижникам. Друзилла ла Салле остается за пределами самого аббатства, уединившись на соседнем кладбище, где проводит занятия вдали от набожных жрецов и клириков, учащихся внутри.",al={"why is drusilla at abbey","warlock in holy abbey","why is she in the graveyard","почему друзилла у аббатства","чернокнижник в святом аббатстве","почему она на кладбище"}},{q="Какую книгу Друзилла пытается заполучить?",a="She seeks a grimoire titled 'Powers of the Void'. It was originally locked away in a protected section of Northshire Abbey's Library Wing, far out of reach of open warlock investigation until a Defias defector stole it.",al={"what book does she want","powers of the void book","the stolen tome quest book","какую книгу она хочет","книга силы бездны","украденный том задание"}},{q="Кто украл книгу из библиотеки?",a="Послушник, обучавшийся в Аббатстве Североземья, нарушил обет, примкнул к Братству Справедливости и похитил том, после чего бежал в ближний лагерь в Долине Североземья.",al={"who took the tome","defias book thief","who stole powers of the void","кто взял том","вор книги братства справедливости","кто украл силы бездны"}},{q="Какую роль она играет для новых чернокнижников-людей?",a="Друзилла — самый первый учитель для чернокнижников-людей: она принимает порочные письма, отправленные новобранцам, и обучает их основным проклятиям и призыву прислужников.",al={"human warlock trainer northshire","who trains warlocks in northshire","учитель чернокнижников людей североземье","кто обучает чернокнижников в североземье"}}},fp="17,364,22.500.0,18.541.1,47.274.0,39.219.0,36.166.0,47.163.0"}
P.entries["npc:duke-hydraxis"] = {n="Герцог Гидраксис",s="Герцог Гидраксис — благородный элементаль воды, командующий Гидраксианскими Повелителями Вод с отдаленного, омываемого волнами островка у берегов Азшары. Давший клятву Нептулону Укротителю Приливов, он собирает смертных искателей приключений для ударов по древним элементальным соперникам, в первую очередь по Рагнаросу Повелителю Огня.",h="Герцог Гидраксис — благородный элементаль воды, командующий Гидраксианскими Повелителями Вод с отдаленного...",kw={"azshara","duke hydraxis","hydraxian waterlords","hydraxis","molten core","neptulon","ragnaros","water elemental","азшара","герцог гидраксис","гидраксианские повелители вод","гидраксис","огненные недра","нептулон","рагнарос","элементаль воды"},ang={["class:Shaman"]="Для шаманов, напрямую общающихся с первородными стихиями, встреча с элементалем такого положения, как герцог Гидраксис, дает редкое представление о древней иерархии Нептулона и вечном соперничестве стихийных миров."},sec={{t="Владыка Повелителей Вод",b="Герцог Гидраксис, обитающий на одинокой скале к северо-востоку от Памятника Черному Ворону в Азшаре, — главный посланник Гидраксианских Повелителей Вод. Если большинство элементалей, связанных с Азеротом, враждебны и хаотичны, то Гидраксис действует с расчетливой целью. Будучи преданным вассалом Нептулона Укротителя Приливов, он считает воду самой чистой и важной из первородных сил. Он холодно следит за растущим смятением в Азероте, ища героев, способных изменить баланс стихийной войны."},{t="Война против огня",b="Главная кампания Гидраксиса направлена против пылающих полчищ Повелителя огня Рагнароса. Он считает вторжение огненных элементалей язвой мира, которую необходимо погасить. Прежде чем даровать свое доверие или средства для штурма огненной твердыни Рагнароса в Огненных Недрах, герцог Гидраксис требует от смертных доказать силу, стойкость и верность, убивая враждебных элементалей на всех континентах. Те, кто покажет себя достойным, получают благословение моря и способ погасить священное пламя, охраняющее владения Повелителя огня."}},faq={{q="Где найти герцога Гидраксиса?",a="Герцог Гидраксис находится на крошечном изолированном острове у восточного побережья Азшары, прямо к северо-востоку от Памятника Черному Ворону.",al={"where is hydraxis","duke hydraxis location","find duke hydraxis","hydraxis map spot","где гидраксис","герцог гидраксис расположение","найти герцога гидраксиса","гидраксис на карте"}},{q="С кем связан герцог Гидраксис?",a="Он возглавляет Гидраксианских Повелителей Вод и служит Нептулону Укротителю Приливов, элементальному владыке воды.",al={"who does hydraxis serve","hydraxis faction","neptulon servant","кому служит гидраксис","фракция гидраксиса","слуга нептулона"}},{q="Почему герцог Гидраксис интересуется смертными героями?",a="Он ищет надежных смертных союзников для войны против враждебных элементальных сил, особенно огненных воинств Рагнароса, скрывающихся в Черной горе.",al={"why does hydraxis need us","what does hydraxis want","hydraxis purpose","зачем гидраксису мы","чего хочет гидраксис","цель гидраксиса"}},{q="Как герцог Гидраксис связан с Огненными Недрами?",a="Герцог Гидраксис направляет героев на борьбу с Рагнаросом Повелителем Огня и предоставляет стихийные средства, необходимые, чтобы погасить руны и победить боссов, охраняющих Огненные Недра.",al={"hydraxis molten core","hydraxis ragnaros","mc hydraxis","гидраксис огненные недра","гидраксис рагнарос","гидраксис мс"}}},fp="13,287,22.506.0,20.552.0,33.133.0,34.99.0,52.158.0,54.169.0"}
P.entries["npc:durnan-furcutter"] = {n="Дарнан Мехорез",s="Дарнан Мехорез — дворф-портной и торговец кожей, работающий в Старой Наковальне в Холодной долине. Стоя у входа в местную таверну, он снабжает только что обученных дворфов и гномов-искателей приключений легкой одеждой, защищающей от пронизывающего горного холода.",h="Дарнан Мехорез — дворф-портной и торговец кожей, работающий в Старой Наковальне в Холодной долине.",kw={"anvilmar","cloth vendor","coldridge valley","dun morogh","durnan furcutter","leather vendor","scalding mornbrew","старая наковальня","торговец тканью","холодная долина","дун морог","дарнан мехорез","торговец кожей","жгучая бражка"},ang={["profession:Tailoring"]="Для начинающих портных такие торговцы, как Дарнан, олицетворяют простую одежду, которая спасает разведчиков и подмастерьев в заснеженных перевалах, пока ее не вытеснит мастерская ткань.",["race:Dwarf"]="Дарнан воплощает практичную сторону жизни дворфов в Холодной долине: прочное ремесло, любовь к горячему напитку и дружеские шутки на снегу."},sec={{t="Теплый стежок на холоде",b="Старая Наковальня — первое испытательное поле для молодых дворфов и изгнанных гномов, и не каждый воин выходит вперед в тяжелом железе. Дарнан Мехорез обслуживает разведчиков, разбойников и заклинателей, которым нужна легкая, гибкая одежда, чтобы сохранять проворство и не поддаваться лютым ветрам Дун Морога. Он стоит прямо возле очага Старой Наковальни, продает обычные тканые и сшитые кожаные вещи и утверждает, что его товар — лучший во всей долине."},{t="С кружкой в руке",b="Как и всякий настоящий дворф, живущий в заснеженных предгорьях, Дарнан ценит крепкий напиток почти так же, как честную торговлю. Он часто бывает в таверне Старой Наковальни и любит дымящуюся кружку жгучей бражки, чтобы прогнать ледяной сквозняк. Искатели приключений, выполняющие поручения в лагере, нередко приносят свежее пиво прямо ему в руки или возвращают его пустые кружки трактирщику."}},faq={{q="Кто такой Дарнан Мехорез?",a="Дарнан Мехорез — дворф, торговец доспехами в Старой Наковальне в Холодной долине. Он продает базовую тканевую и кожаную экипировку начинающим искателям приключений, отправляющимся в путь по Дун Морогу.",al={"durnan","furcutter","who is durnan furcutter","дарнан","мехорез","кто такой дарнан мехорез"}},{q="Где найти Дарнана Мехореза?",a="Его можно найти снаружи, у входа в главный зал Старой Наковальни в Холодной долине, неподалеку от наставников и местных торговцев.",al={"durnan location","where is durnan","anvilmar cloth vendor","дарнан где найти","где дарнан","торговец тканью старая наковальня"}},{q="Что продает Дарнан?",a="Он предлагает набор начальных тканевых и кожаных доспехов для классов, полагающихся на ловкость или заклинания, а не на тяжелую кольчугу.",al={"durnan wares","what does durnan sell","товары дарнана","что продает дарнан"}},{q="Почему он связан с доставкой жгучей бражки?",a="Дарнан подолгу работает на ледяных ветрах Холодной долины и полагается на теплые кружки жгучей бражки из соседней таверны, чтобы оставаться бодрым и согретым.",al={"durnan beer quest","scalding mornbrew durnan","durnan drink","задание дарнана с пивом","жгучая бражка дарнан","напиток дарнана"}}},fp="16,273,25.456.0,13.397.0,24.190.0,34.147.0,22.152.0,53.140.0"}
P.entries["npc:duthorian-rall"] = {n="Даториан Ралл",s="Даториан Ралл — уважаемый рыцарь-человек Серебряной Длани, служащий в Соборе Света Штормграда. Один из самых влиятельных паладинов Альянса, он руководит обучением и духовными испытаниями будущих святых воинов. Он ведет новобранцев через торжественные обеты милосердия, доблести и преданности, чтобы защищать Азерот от Плети и скрытых внутренних угроз.",h="Даториан Ралл — уважаемый рыцарь-человек Серебряной Длани, служащий в Соборе Света Штормграда.",kw={"cathedral of light","daphne stilwell","duthorian rall","jordan stilwell","paladin trainer","silver hand","stormwind","symbol of life","tome of divinity","tome of valor","собор света","дафна стилвелл","даториан ралл","джордан стилвелл","наставник паладинов","серебряная длань","штормград","знак жизни","фолиант божественности","фолиант отваги"},ang={["class:Paladin"]="Даториан Ралл — один из ваших главных духовных наставников в Штормграде: он проверяет ваше сострадание и доблесть в базовых испытаниях, открывающих силу воскрешения, божественное чутье и боевого коня.",["faction:Alliance"]="Как влиятельный лидер Серебряной Длани, Даториан следит, чтобы защитники Альянса оставались нравственными и способными защищать королевство как от бандитов, так и от нежити.",["race:Human"]="Неразрывно связанный с Собором Света Штормграда, Даториан Ралл олицетворяет неугасающую преданность и рыцарскую дисциплину, занимающие центральное место в вере и обществе людей."},sec={{t="Опора Серебряной Длани",b="Стоя под сводами трансепта Собора Света, Даториан Ралл воплощает почтенные традиции Рыцарей Серебряной Длани. Пока королевство охвачено внутренними раздорами, а король Вариан Ринн пропал, Даториан берет на себя важную задачу — воспитывать в новичках праведную дисциплину. Уважаемые паладины, в том числе Брат Вильгельм в Североземье и Брандар Железный Молот в Стальгорне, направляют многообещающих новобранцев к нему, чтобы начать священные испытания."},{t="Испытания сострадания и жизни",b="Даториан учит, что воинская мощь без нравственной основы пуста. С помощью Фолианта Божественности он проверяет способность паладина к состраданию, требуя поступков милосердия и бескорыстного служения по всему Штормграду, прежде чем доверить более глубокие тайны. Его испытания завершаются проверкой кандидатов Знаком жизни возле Часовых Вечности: их посылают помогать раненым союзникам и учат направлять чудесную силу Света, чтобы возвращать павших соратников из мертвых."},{t="Цена доблести",b="Помимо духовных размышлений, Даториан требует непоколебимого мужества перед лицом опасности. В испытаниях доблести он предупреждает претендентов, что их обеты могут потребовать жизни. Он проверяет их решимость, посылая новичков в опасные места — например, защищать Дафну Стилвелл от изгоев из Братства Справедливости в Западном Крае, — а затем направляет их к мастеру-кузнецу Джордану Стилвеллу за пределами Стальгорна и дарует священных скакунов, достойных их положения."}},faq={{q="Кто такой Даториан Ралл?",a="Даториан Ралл — видный рыцарь Серебряной Длани, живущий в Соборе Света в Штормграде. Он наставник и духовный учитель новых паладинов и испытывает их преданность и мужество от имени Церкви Священного Света.",al={"duthorian rall lore","who is duthorian","cathedral paladin duthorian","даториан ралл предания","кто такой даториан","паладин собора даториан"}},{q="Где найти Даториана Ралла?",a="Его можно найти в восточном крыле Собора Света, расположенного в центре Соборной площади в Штормграде.",al={"where is duthorian rall","duthorian rall location","how to find duthorian","где даториан ралл","даториан ралл местонахождение","как найти даториана"}},{q="Как он связан с Фолиантом Божественности?",a="Даториан выдает паладинам Книгу Божественности и ведет их через испытания смирения, сострадания и спасения. Выполнив их, новичок доказывает, что достоин владеть силой воскрешения Света.",al={"tome of divinity duthorian","redemption quest duthorian","symbol of life quest","фолиант божественности даториан","задание искупление даториан","задание знак жизни"}},{q="Почему Даториан посылает паладинов в Западный Край?",a="Во время испытания Фолианта Отваги Даториан посылает паладинов защищать Дафну Стилвелл от бандитов из Братства Справедливости на ее ферме в Западном Крае, чтобы они показали готовность жертвовать собой ради защиты невинных.",al={"daphne stilwell quest","tome of valor westfall","westfall paladin quest","задание дафна стилвелл","фолиант отваги западный край","задание паладина в западном крае"}},{q="Какие награды Даториан дает паладинам, прошедшим его испытания?",a="Успешные паладины получают под его руководством важные священные умения: дар воскрешения, способность чувствовать нежить, защитное снаряжение, такое как Бастион Штормграда, и, наконец, призываемого боевого коня.",al={"duthorian quest rewards","what do you get from duthorian","награды даториана","что дает даториан"}},{q="Кто изначально отправляет искателей приключений к Даториану?",a="Претендентов обычно направляют к нему наставники паладинов, в том числе Брат Вильгельм в Долине Североземья и Брандар Железный Молот в Стальгорне.",al={"who sends you to duthorian","duthorian breadcrumb quest","кто посылает к даториану","подводящее задание даториана"}}},fp="14,388,27.502.0,29.469.0,18.450.1,22.257.0,34.135.0,47.216.0,45.216.0,66.235.0,45.144.0"}
P.entries["npc:ebru"] = {n="Эбру",s="Эбру — друидка-ночная эльфийка, укрывшаяся в скалах над Пещерами Стенаний. Одна из немногих оставшихся неискаженных учениц верховного друида Наралекса, она беспомощно наблюдает, как мечта ее наставника возродить Степи превращается в кошмар. Со своего места она вербует отважных путников, готовых спуститься в подземные глубины и истребить мутировавших чудовищ, порожденных Кошмаром.",h="Эбру — друидка-ночная эльфийка, укрывшаяся в скалах над Пещерами Стенаний.",kw={"barrens","cenarion circle","deviate","druid","ebru","naralex","wailing caverns","степи","круг кенария","перерожденные","друид","эбру","наралекс","пещеры стенаний"},ang={["class:Druid"]="Для друидов Круга Кенария встреча с Эбру — суровое напоминание о страшных опасностях путешествий по Изумрудному Сну и о катастрофической цене потери контроля.",["race:NightElf"]="Эбру олицетворяет небольшой обособленный анклав ночных эльфов в засушливом сердце Калимдора, вдали от древних ветвей Ясеневого леса и Тельдрассила."},sec={{t="Дозор над спуском",b="Пока большинство последователей верховного друида Наралекса поддалось изумрудной порче, расползающейся по пещерам, Эбру удалось вырваться из хватки кошмара. Она расположилась в огромной черепообразной скале над входом в Пещеры Стенаний и несет дозор над спуском. Она знает, что благородный замысел Наралекса — добраться до подземных источников и превратить засушливые Степи в цветущие леса — обернулся ужасной бедой, и отчаянно направляет готовых помочь искателей приключений уничтожать растущее число перерожденных зверей, угрожающих захлестнуть окрестные равнины."},{t="Цена порчи",b="Кошмар исказил не только экосистему пещер, но и соратников Эбру, превратив их в фанатичных Друидов Клыка. Лишившись товарищей и столкнувшись с крушением своего круга, Эбру сосредоточилась на сдерживании."}},faq={{q="Кто такая Эбру?",a="Эбру — друидка-ночная эльфийка и неискаженная ученица верховного друида Наралекса. Она живет в пещере высоко над входом в Пещеры Стенаний, наблюдает за местом и координирует усилия по сдерживанию порчи, расползающейся по Степям.",al={"who is ebru","ebru lore","about ebru","кто такая эбру","эбру предания","об эбру"}},{q="Почему Эбру находится над Пещерами Стенаний?",a="Она бежала наверх, когда ритуал Наралекса обернулся Изумрудным Кошмаром, превратив ее соратников во враждебных фанатиков. Ее убежище в скале над входом в пещеру позволяет следить за пещерами, оставаясь в безопасности от диких чудовищ внутри.",al={"where is ebru","why is ebru up here","ebru cave location","где эбру","почему эбру наверху","пещера эбру"}},{q="Что случилось с Наралексом и другими его учениками?",a="Наралекс погрузился в глубокий транс, чтобы добраться до подземных источников, но его разум оказался в ловушке Изумрудного Кошмара. Возникшая порча исказила растительность и животных пещер и свела с ума большинство его учеников, превратив их в Друидов Клыка.",al={"what happened to the disciples","naralex fate","druids of the fang origin","что случилось с учениками","судьба наралекса","происхождение друидов клыка"}},{q="О чем Эбру просит путников?",a="Эбру призывает искателей приключений спуститься в глубины Пещер Стенаний, истребить перерожденных зверей и нанести ответный удар мутировавшим чудовищам, рожденным из мучительных снов ее наставника.",al={"ebru quests","deviate eradication","cleansing the caverns","задания эбру","истребление перерожденных","очищение пещер"}}},fp="4,377,25.562.0,23.238.1,12.247.0,46.256.0,49.263.0,35.188.0"}
P.entries["npc:edwin-vancleef"] = {n="Эдвин ван Клиф",s="Эдвин ван Клиф был талантливым главой Гильдии каменщиков, которая отстроила Штормград после Второй войны. Когда Дом знати обманул его с оплатой, он возглавил жестокий мятеж рабочих и основал разбойничье Братство Справедливости. Из глубин Мертвых копей в Западном Крае он замышляет месть королевству, которое сам помогал восстанавливать.",h="Эдвин ван Клиф был талантливым главой Гильдии каменщиков, которая отстроила Штормград после Второй войны.",kw={"brotherhood","deadmines","defias","moonbrook","stonemasons","stormwind","vancleef","westfall","братство","мертвые копи","братство справедливости","луноречье","каменщики","штормград","ван клиф","западный край"},ang={["class:Rogue"]="Ван Клифа обучал сам глава ШРУ Матиас Шоу, поэтому он стал одним из самых умелых разбойников Азерота, сочетая руководство гильдией с приемами элитного убийцы.",["faction:Alliance"]="Командиры Альянса считают ван Клифа главной внутренней угрозой безопасности южных человеческих земель: он парализовал Западный Край и границы Элвиннского леса.",["race:Human"]="Для людей Штормграда ван Клиф воплощает трагедию послевоенного восстановления королевства: преданный герой, лишенный заработка, ставший самым опасным мятежником державы."},sec={{t="Зодчий королевства",b="После опустошений Первой войны Эдвин ван Клиф возглавил Гильдию каменщиков в грандиозном деле восстановления Штормграда. Непревзойденный мастер и идеалист, ван Клиф руководил возведением величественных крепостных стен и высоких соборов столицы и даже наблюдал за строительством Крепости Стражей Пустоты, призванной охранять Темный портал. Наряду с мастерством зодчего ван Клиф был на редкость опасным агентом: скрытности, обману и владению клинком его обучил друг детства Матиас Шоу."},{t="Мятеж и Братство",b="Когда годы труда подошли к концу, Дом знати наделал огромных долгов на военных кампаниях и отказался выплатить каменщикам обещанное вознаграждение. Разгневанный ван Клиф потребовал возмещения, но знать лишь официально распустила гильдию. Мастеровые восстали, начались беспорядочные уличные бунты в Штормграде, во время которых погибла жена короля Вариана Ринна, королева Тиффин. Изгнанный из столицы в ходе королевской расправы, ван Клиф собрал своих изгнанных рабочих и союзных отщепенцев в Западном Крае и объединил их под знаменем Братства Справедливости."},{t="Возмездие из тени",b="Пользуясь тем, что корона пренебрегала сельскими землями, Братство Справедливости прогнало фермеров Западного Края и захватило его богатые залежи золота. В глубинах Мертвых копей Луноречья ван Клиф руководил постройкой огромного боевого корабля, готовя вооруженный штурм самого Штормграда. Пока Дом знати считал воров неорганизованными разбойниками, ван Клиф заключил союзы с речными мошенниками, гноллами и Пиратами Кровавого Паруса, превратив озлобленный рабочий союз в армию, готовую сокрушить монархию."}},faq={{q="Кто такой Эдвин ван Клиф?",a="Он — вдохновитель Братства Справедливости и бывший глава Гильдии каменщиков. Это великий зодчий, отстроивший Штормград после того, как Орда разрушила его в Первую войну.",al={"who is vancleef","edwin vancleef lore","vancleef identity","кто такой ван клиф","эдвин ван клиф предания","личность ван клифа"}},{q="Почему каменщики восстали против Штормграда?",a="После восстановления Штормграда Дом знати отказался платить Гильдии каменщиков оговоренное жалованье из-за чрезмерных долгов королевства. Когда ван Клиф и рабочие стали протестовать, знать распустила гильдию, что вызвало жестокие бунты на улицах.",al={"why did defias rebel","why did stonemasons riot","reason for defias riot","почему восстало братство справедливости","почему бунтовали каменщики","причина бунта"}},{q="Где скрывается Эдвин ван Клиф?",a="Он руководит Братством Справедливости из самых дальних глубин Мертвых копей в Западном Крае; по слухам, вход в них находится у тихой деревни Луноречье.",al={"where is vancleef","vancleef location","deadmines boss location","где ван клиф","местонахождение ван клифа","босс мертвых копей"}},{q="Как он связан с Матиасом Шоу?",a="Матиас Шоу был другом детства Эдвина. Шоу лично обучил ван Клифа скрытности, воровству и бою, надеясь, что тот присоединится к нему в королевской разведке ШРУ.",al={"vancleef and shaw","is vancleef related to shaw","mathias shaw friend","ван клиф и шоу","родственник ли ван клиф шоу","друг матиас шоу"}},{q="Что случилось с королевой Тиффин во время мятежа?",a="Во время беспорядочных уличных бунтов, вызванных неоплатой труда каменщиков, брошенный камень попал в молодую жену короля Вариана, королеву Тиффин Ринн, и убил ее. Ее смерть вызвала у короля Вариана яростные репрессии, и ван Клифу с его людьми пришлось бежать из города.",al={"how did tiffin die","who killed tiffin wrynn","queen tiffin death","как умерла тиффин","кто убил тиффин ринн","смерть королевы тиффин"}},{q="Что он строит в Мертвых копях?",a="Ходят слухи, что Братство Справедливости наняло хитроумных гоблинов, чтобы построить на дне Мертвых копей нечто ужасное, но что именно — пока неизвестно.",al={"deadmines ship","what is inside deadmines","vancleef warship","корабль мертвых копей","что внутри мертвых копей","боевой корабль ван клифа"}}},fp="14,354,24.539.0,28.580.0,28.533.1,22.202.0,49.258.0,31.164.1,39.205.0,46.246.0,37.169.1"}
P.entries["npc:einar-stonegrip"] = {n="Эйнар Камнехват",kw={"crocolisk","einar stonegrip","james halloran","menethil harbor","sida","skins","trapper","wetlands","кроколиск","эйнар камнехват","джеймс халлоран","гавань менетилов","сида","шкуры","охотник","болотина"},ang={["faction:Alliance"]="Путники, идущие между Стальгорном и Гаванью Менетилов, часто проходят мимо дорожного поста Эйнара, и для них это легкая курьерская работа на маршрутах снабжения Альянса.",["race:Dwarf"]="Эйнар олицетворяет суровую самостоятельность, свойственную дворфам-горцам, хотя семейные неурядицы заставляют его ночевать в сырых болотах, а не в теплой таверне."},sec={{t="Охотник на Перекрестке",b="Эйнар Камнехват поселился на центральной развилке дорог, ведущих к Дун Альгазу, Дун Модру и Гавани Менетилов, и зарабатывает на жизнь, пробираясь по сырым топям Болотины. Он охотится на местных кроколисков ради прочных шкур, которые поставляет кожевникам и торговцам на побережье. Хотя он достаточно крепок, чтобы вытаскивать рептилий из трясины, домашних ссор он боится до дрожи. Из-за тяжелой размолвки с женой Сидой Эйнар остается на дороге и нанимает путников доставлять связки шкур своему торговому партнеру Джеймсу Халлорану, лишь бы самому не ступать в Гавань Менетилов."}},faq={{q="Кто такой Эйнар Камнехват?",a="Эйнар Камнехват — дворф-скорняк и охотник, живущий на перекрестке в Болотине. Он зарабатывает на жизнь добычей шкур кроколисков, которые продает в Гавани Менетилов.",al={"who is einar","einar stonegrip lore","wetlands dwarf crossroads","кто такой эйнар","эйнар камнехват предания","дворф болотина перекресток"}},{q="Почему Эйнар не доставляет свои товары в Гавань Менетилов сам?",a="Эйнар в ужасных отношениях со своей женой Сидой, живущей в Гавани Менетилов. Чтобы не столкнуться с ее гневом, он предпочитает оставаться в болотах и платить проходящим курьерам за доставку товаров.",al={"why doesn't einar go to town","einar stonegrip wife","why hire adventurers","почему эйнар не идет в город","жена эйнара камнехвата","зачем нанимать искателей приключений"}},{q="С кем Эйнар работает в Гавани Менетилов?",a="Эйнар собирает шкуры кроколисков по контракту для Джеймса Халлорана, торговца из Гавани Менетилов, который занимается распространением и продажей кожаных изделий.",al={"einar business partner","who buys einar skins","james halloran connection","деловой партнер эйнара","кто покупает шкуры эйнара","джеймс халлоран связь"}}},fp="15,245,27.596.0,23.165.0,57.206.0,44.147.0"}
P.entries["npc:eitrigg"] = {n="Эйтригг",s="Эйтригг — опытный ветеран Первой и Второй войн, который стоит рядом с вождем Траллом как уважаемый советник в Оргриммаре. Некогда высокопоставленный лейтенант клана Черной горы, он разочаровался в старой демонической Орде и жил в изгнании, пока необыкновенная дружба с человеком-паладином не изменила его судьбу. Сегодня он помогает Новой Орде вернуться к истокам чести и шаманизма.",h="Эйтригг — опытный ветеран Первой и Второй войн, который стоит рядом с вождем Траллом как уважаемый советник в...",kw={"blackrock clan","blood and honor","eitrigg","grommash hold","hearthglen","orgrim doomhammer","orgrimmar","stratholme","thrall","tirion fordring","клан черной горы","кровь и честь","эйтригг","крепость громмаш","дольный очаг","оргрим молот рока","оргриммар","стратхольм","тралл","тирион фордринг"},ang={["class:Paladin"]="История Эйтригга и Тириона Фордринга известна среди паладинов как высшее испытание долга и праведной чести.",["class:Warrior"]="Эйтригг воплощает воинскую честь, сохраненную сквозь десятилетия трагедий: он пережил две войны благодаря огромной силе и несломленной дисциплине.",["faction:Horde"]="Эйтригг служит живой институциональной памятью Орды и стоит рядом с Траллом, чтобы ошибки отравленного демонами прошлого никогда не повторились.",["race:Orc"]="Для орков Дуротара Эйтригг — почитаемый старейшина, чье происхождение из клана Черной горы доказывает, что любой орк способен принять честь и искупить наследие своего народа."},sec={{t="Ветеран Старой Орды",b="Эйтригг родился на Дреноре в клане Черной горы и был одним из главных лейтенантов вождя Чернорука наряду с Оргримом Молотом Рока и Вароком Саурфангом. Когда Молот Рока захватил власть над Ордой, Эйтригг остался доверенным офицером и надзирал за плененной убийцей Гароной, полуорком. Хотя поначалу он отмахивался от ее откровений о Гул'дане и демонической порче Совета Теней, ужасные сражения и окончательное поражение Орды во Второй войне заставили его взглянуть в лицо мрачной действительности. Потрясенный тем, как манипулировали его народом, Эйтригг ушел от разрозненных остатков Орды и удалился в добровольное изгнание, ища лишь уединения в глуши Лордерона."},{t="Кровь и честь",b="Спустя годы изгнания Эйтригга обнаружил в заброшенной башне близ Дольного Очага паладин Тирион Фордринг. Их первая схватка обрушила руины, но вместо того чтобы добить потерявшего сознание человека, Эйтригг вытащил его из-под обломков в безопасное место. Тронутый этим проявлением истинной воинской чести, Тирион поклялся в дружбе и отказался выдать убежище отшельника. Когда местные власти Альянса в конце концов схватили Эйтригга и приговорили его к повешению в Стратхольме, Тирион отбросил собственное рыцарское звание, земли и свободу, напав, чтобы спасти осужденного орка. Эта легендарная связь показала обоим воинам, что честь выше горькой вражды их народов."},{t="Советник Вождя",b="Когда Тирион отчаянно пытался освободить Эйтригга в Стратхольме, недавно объединенная Орда Тралла совершила набег на город и вывела старого воина. Встреча с Траллом убедила Эйтригга, что орки избавляются от демонической скверны и заново открывают наследие предков-шаманов. Вернувшись с Траллом через Великое море в Калимдор, Эйтригг занял почетное место в Аллее Мудрости в Оргриммаре. Теперь он стоит в Крепости Громмаш как советник молодого Вождя, помогает оценивать новобранцев и делится с ними нелегко добытой мудростью, чтобы Новая Орда никогда не повторила трагедий прошлого."}},faq={{q="Кто такой Эйтригг?",a="Эйтригг — пожилой орк-воин из клана Черной горы, служивший лейтенантом под началом Чернорука и Оргрима Молота Рока в Первую и Вторую войны. Сегодня он живет в Крепости Громмаш в Оргриммаре как доверенный советник вождя Тралла.",al={"who is eitrigg","eitrigg lore","orc standing by thrall","кто такой эйтригг","эйтригг предания","орк рядом с траллом"}},{q="Почему Эйтригг считает человека своим братом?",a="Живя в изгнании в Лордероне, Эйтригг спас жизнь паладину Тириону Фордрингу во время поединка, обрушившего каменную башню. В ответ Тирион сберег тайну убежища Эйтригга, а позже сразился со своими же людьми в Стратхольме, чтобы предотвратить казнь Эйтригга, и потерял при этом титул и земли. Связанный взаимной честью, Эйтригг считает Тириона братом.",al={"eitrigg and tirion","eitrigg human friend","blood and honor","эйтригг и тирион","друг эйтригга человек","кровь и честь"}},{q="К какому клану принадлежит Эйтригг?",a="Эйтригг принадлежит к клану Черной горы. Он был высокопоставленным командиром в старых войнах, но покинул порочные остатки клана, узнав правду о демонической порче, которая ими руководила.",al={"eitrigg clan","is eitrigg blackrock","клан эйтригга","эйтригг из черной горы"}},{q="Почему Эйтригг покинул Старую Орду?",a="Во время Второй войны Эйтригг охранял убийцу Гарону, которая раскрыла поклонение демонам и манипуляции Гул'дана и Совета Теней. После поражения Орды Эйтригг понял, что ее слова были правдой, и ушел с отвращением, ища тихое место, чтобы умереть, но не служить порочной военной машине.",al={"why did eitrigg leave","eitrigg exile","почему эйтригг ушел","изгнание эйтригга"}},{q="Как Эйтригг оказался в Оргриммаре?",a="Когда силы Альянса схватили Эйтригга и приготовились казнить его в Стратхольме, Тралл с отрядом совершил набег на город и освободил его. Увидев преданность Тралла чести и возрождение шаманизма, Эйтригг решил последовать за молодым Вождем в Калимдор.",al={"how did eitrigg meet thrall","eitrigg rescued","как эйтригг встретил тралла","спасение эйтригга"}},{q="Какую роль Эйтригг играет в Оргриммаре сейчас?",a="Эйтригг напрямую советует Траллу в Крепости Громмаш и помогает проверять и оценивать новобранцев, клянущихся в верности Новой Орде.",al={"eitrigg quest","what does eitrigg do","задание эйтригга","чем занимается эйтригг"}}},fp="7,404,26.720.0,15.714.0,25.608.0,15.245.0,46.363.0,33.208.0,36.302.0,36.259.0,51.139.0"}
P.entries["npc:elanaria"] = {n="Эланария",s="Эланария — ночная эльфийка, наставница и координатор воинов, находящаяся на Террасе Воинов в Дарнассе. Она направляет начинающих бойцов по всему Калимдору, испытывая их доблесть в схватках с опасными противниками, такими как сатир Ворлус Подлое Копыто, и с духовными сущностями вроде Тени Элуры. Ее наставления служат важным связующим звеном для солдат Альянса, оттачивающих боевое мастерство в столице ночных эльфов.",h="Эланария — ночная эльфийка, наставница и координатор воинов, находящаяся на Террасе Воинов в Дарнассе.",kw={"darnassus","elanaria","shade of elura","smith mathiel","teldrassil","vorlus vilehoof","warrior quests","warrior's terrace","дарнасс","эланария","тень элуры","кузнец матиль","тельдрассил","ворлус подлое копыто","задания воина","терраса воинов"},ang={["class:Warrior"]="Эланария — важный контакт на Террасе Воинов: она дает боевые испытания по уровню, а наградой служит прочное снаряжение, и они оттачивают тактические навыки ведения боя.",["faction:Alliance"]="Из столицы Тельдрассила Эланария помогает поддерживать боевую готовность и вооружает солдат, защищающих интересы Альянса на севере Калимдора.",["race:NightElf"]="Эланария, представляя воинские традиции Дарнасса, стремится очистить исконные земли кальдораев от порочных существ, таких как сатиры и неупокоенные тени."},sec={{t="Часовой Террасы",b="Эланария гордо стоит на Террасе Воинов среди ветвей Дарнасса и служит наставницей и связующим звеном для воинов-бойцов. В эпоху, когда ночные эльфы официально присоединились к Великому Альянсу, ее роль не ограничивается обучением местных Часовых: она готовит воинов любого происхождения к суровым испытаниям, с которыми сталкиваются их земли."},{t="Испытания железа и духа",b="Эланария не раздает похвалу легко: она ждет дисциплины, стойкости и доказанной силы. Она посылает опытных искателей приключений уничтожать грозных противников, терзающих Ясеневый лес и Темные берега, в том числе оскверненного сатира Ворлуса Подлого Копыта и неупокоенных духов вроде Тени Элуры. Она также поддерживает связь с умелыми мастерами, например с Кузнецом Матиль, чтобы достойные воины были как следует вооружены для войны."}},faq={{q="Кто такая Эланария?",a="Эланария — ночная эльфийка, находящаяся на Террасе Воинов в Дарнассе. Она выдает боевые задания и поручает начинающим воинам испытания в схватках по всему северному Калимдору.",al={"elanaria darnassus","who is elanaria","elanaria npc","эланария дарнасс","кто такая эланария","эланария нпс"}},{q="Где найти Эланарию?",a="Она находится на Террасе Воинов — возвышенном северном районе Дарнасса, отведенном под военные тренировочные площадки и оборонительные сооружения города.",al={"elanaria location","where is elanaria","elanaria spot","эланария местонахождение","где эланария","где найти эланарию"}},{q="Какие задания дает Эланария?",a="Эланария — ключевая фигура в развитии воинов среднего уровня. Она дает поручения: выследить сатира Ворлуса Подлого Копыта, сразиться с Тенью Элуры и наладить взаимодействие с местными оружейниками вроде Кузнеца Матиль.",al={"elanaria quests","quests from elanaria","elanaria warrior quest","задания эланарии","задания от эланарии","задание воина эланария"}},{q="Почему Эланария посылает бойцов против Ворлуса Подлого Копыта?",a="Ворлус Подлое Копыто — опасный сатир, чья демоническая порча угрожает северным землям. Эланария поручает способным воинам убить его, чтобы защитить леса и доказать свою доблесть на поле боя.",al={"elanaria vorlus","vorlus vilehoof quest","why kill vorlus vilehoof","эланария ворлус","задание ворлус подлое копыто","зачем убивать ворлуса подлое копыто"}},{q="Кто такая Кузнец Матиль?",a="Кузнец Матиль — мастер-оружейник, находящаяся в Дарнассе. Эланария направляет воинов к Матиль, чтобы они могли изготовить или получить особое боевое снаряжение, пригодное для сражений на передовой.",al={"mathiel connection","smith mathiel warrior","elanaria and mathiel","связь с матиль","кузнец матиль воин","эланария и матиль"}},{q="Работает ли Эланария с теми, кто не ночной эльф?",a="Да. Как часть Альянса, Эланария помогает всем подходящим воинам Альянса, которые приходят на Террасу Воинов в поисках наставлений и особой подготовки.",al={"can humans talk to elanaria","alliance warrior elanaria","может ли человек говорить с эланарией","воин альянса эланария"}}},fp="8,400,25.365.0,25.409.0,16.181.0,26.148.0,32.219.0,56.207.0,21.184.0,44.156.0"}
P.entries["npc:elder-bloodhoof"] = {n="Старейшина Кровавое Копыто",s="Старейшина Кровавое Копыто — дух предка, покоящийся к северу от Деревни Кровавого Копыта в Мулгоре. Он заметно является путникам во время Лунного фестиваля и почитается как дух-хранитель племени Кровавого Копыта.",h="Старейшина Кровавое Копыто — дух предка, покоящийся к северу от Деревни Кровавого Копыта в Мулгоре.",kw={"ancestor","bloodhoof village","elder bloodhoof","lunar festival","mulgore","red rocks","tauren spirit","предок","деревня кровавого копыта","старейшина кровавое копыто","лунный фестиваль","мулгор","красные скалы","дух тауренов"},ang={["class:Shaman"]="Шаманы почитают Старейшину Кровавого Копыта как проявление почитания предков, показывающее, как духи предков направляют и защищают своих потомков в материальном мире.",["race:Tauren"]="Для паломников-тауренов почтить Старейшину Кровавого Копыта — значит напрямую приобщиться к роду племени и отдать дань жертве тех, кто ходил по Мулгору задолго до основания Громового Утеса."},sec={{t="Дух предков",b="Старейшина Кровавое Копыто воплощает глубокую духовную связь, которая объединяет тауренов с их родом. Этот призрачный старейшина, являющийся близ Деревни Кровавого Копыта, присматривает за своим народом и награждает почтительных путников, ищущих мудрости во время Лунного фестиваля. Его присутствие подтверждает непреходящее водительство ушедших вождей и предков племени, чьи духи неразрывно связаны с равнинами Мулгора."}},faq={{q="Кто такой Старейшина Кровавое Копыто?",a="Старейшина Кровавое Копыто — призрачный дух тауренов, появляющийся к северу от Деревни Кровавого Копыта в Мулгоре. Он представляет почитаемых предков племени Кровавого Копыта и дарует благословения и древнюю мудрость путникам, навещающим его во время сезонных традиций, таких как Лунный фестиваль.",al={"elder bloodhoof lore","who is the ghost outside bloodhoof village","elder bloodhoof identity","предания старейшины кровавое копыто","кто призрак у деревни кровавого копыта","личность старейшины кровавое копыто"}},{q="Когда можно увидеть Старейшину Кровавого Копыта?",a="Старейшина Кровавое Копыто является главным образом во время ежегодного Лунного фестиваля, выступая как дух-старейшина, дарующий праздничные благословения.",al={"where is elder bloodhoof","elder bloodhoof missing","how to find elder bloodhoof","где старейшина кровавое копыто","старейшина кровавое копыто пропал","как найти старейшину кровавое копыто"}},{q="Как он связан с Деревней Кровавого Копыта?",a="Будучи почитаемым предком, носящим имя клана, Старейшина Кровавое Копыто присматривает за исконным поселением — Деревней Кровавого Копыта. По традиции тауренов духи предков особенно важны, когда остаются рядом с местами, где живут и собираются их потомки.",al={"why is he near bloodhoof village","elder bloodhoof relation to cairne","почему он у деревни кровавого копыта","старейшина кровавое копыто родство с кэрном"}}},fp="15,221,23.396.0,23.275.0,33.131.0,44.246.0"}
P.entries["npc:elder-bronzebeard"] = {n="Старейшина Бронзобород",s="Старейшина Бронзобород — древний дух земельных, появляющийся в Мистическом квартале Стальгорна во время Лунного фестиваля. Он носит имя клана, правящего городом, и его призрачное присутствие служит мостом между современными дворфами и их каменными предками.",h="Старейшина Бронзобород — древний дух земельных, появляющийся в Мистическом квартале Стальгорна во время...",kw={"ancestor","earthen","elder bronzebeard","ironforge","lunar festival","magni","mystic ward","предок","земельные","старейшина бронзобород","стальгорн","лунный фестиваль","магни","мистический квартал"},ang={["faction:Alliance"]="Паломники Альянса, посещающие Стальгорн во время Лунного фестиваля, встречают старейшину, олицетворяющего самые основы дворфийского королевства.",["race:Dwarf"]="Для дворфов встреча со Старейшиной Бронзобородом — редкая возможность напрямую взглянуть на свое земельное происхождение, подтверждающее исторические находки Лиги исследователей."},sec={{t="Прародитель в Мистическом квартале",b="Старейшина Бронзобород, появляющийся у пруда в Мистическом квартале Стальгорна, не имеет плоти современных дворфов: его призрачный облик — это земельный, древняя раса, созданная Титанами из живого камня. Дворфийские ученые и исследователи только начинают открывать их происхождение раскопками по всему Каз Модану и за его пределами, и присутствие этого духа становится поразительной живой реликвией. Его имя и облик говорят о том, что он прямой предок клана Бронзобородов и безмолвно свидетельствует, как далеко ушли его каменнорожденные потомки."}},faq={{q="Почему Старейшина Бронзобород выглядит как земельный, а не как обычный дворф?",a="Дворфы — потомки земельных, древних существ, созданных Титанами из камня, которые позже поддались Проклятию плоти. Поскольку Старейшина Бронзобород жил в далеком прошлом, до того как это превращение полностью свершилось, его дух сохраняет каменный облик эпохи земельных.",al={"why is elder bronzebeard stone","is elder bronzebeard earthen","elder bronzebeard race","почему старейшина бронзобород каменный","старейшина бронзобород земельный","раса старейшины бронзоборода"}},{q="Состоит ли он в родстве с королем Магни Бронзобородом?",a="Хотя точные ветви древних родословных утрачены в истории, его имя и присутствие в столице дворфов убедительно указывают, что он — почитаемый прародитель клана Бронзобородов, рода, правящего Стальгорном при короле Магни.",al={"is he magni's ancestor","magni bronzebeard relative","bronzebeard family tree","предок ли он магни","родственник магни бронзоборода","родословная бронзобородов"}},{q="Почему Старейшина Бронзобород находится в Стальгорне?",a="Во время Лунного фестиваля духи старейшин являются по всему Азероту, чтобы даровать путникам мудрость и благословения. Старейшина Бронзобород появляется в Мистическом квартале Стальгорна, у тихого пруда, где собираются дворфийские маги и ученые.",al={"what is elder bronzebeard doing here","where is elder bronzebeard","mystic ward ghost","что здесь делает старейшина бронзобород","где старейшина бронзобород","призрак мистического квартала"}}},fp="17,276,31.551.0,75.284.0,40.247.0,38.259.0"}
P.entries["npc:elder-darkcore"] = {n="Старейшина Черносерд",s="Старейшина Черносерд — древний дух, появляющийся во время Лунного фестиваля в тронном зале Руин Лордерона над Подгородом. Олицетворяя почитаемых предков мира, он дарует благословение и праздничные знаки путникам, которые ищут его. Его присутствие создает мирный, задумчивый миг среди руин павшего человеческого королевства.",h="Старейшина Черносерд — древний дух, появляющийся во время Лунного фестиваля в тронном зале Руин Лордерона над...",kw={"ancestor","coin of ancestry","darkcore","elder darkcore","lunar festival","ruins of lordaeron","throne room","undercity","предок","монета наследия","черносерд","старейшина черносерд","лунный фестиваль","руины лордерона","тронный зал","подгород"},ang={["faction:Alliance"]="Чтобы навестить Старейшину Черносерда, нужно проскользнуть мимо Отрекшихся часовых высокого уровня и королевских стражей вокруг руин Столицы, что делает его одной из самых опасных остановок фестиваля для Альянса.",["race:Undead"]="Старейшина Черносерд пребывает в нескольких шагах от подъемников на поверхность Подгорода, на тех самых камнях, где было разрушено королевство Лордерон."},sec={{t="Дух в тронном зале",b="Во время ежегодного Лунного фестиваля духи древних старейшин являются по всему Азероту, чтобы поделиться мудростью с искателями приключений. Старейшина Черносерд несет бдение в одном из самых мрачных мест мира — королевском тронном зале в Руинах Лордерона, прямо над входом в Подгород. Этот призрачный предок, окруженный залитым кровью полом, на котором пал король Теренас Менетил II, дарует Монету Наследия и благословение тем, кто достаточно храбр, чтобы войти в сердце земель Отрекшихся и отдать дань уважения."}},faq={{q="Кто такой Старейшина Черносерд?",a="Старейшина Черносерд — один из почитаемых призрачных предков, являющихся во время сезонного Лунного фестиваля. Он появляется в тронном зале над Подгородом, чтобы даровать посетителям благословения и Монеты Наследия.",al={"elder darkcore","darkcore","who is darkcore","старейшина черносерд","черносерд","кто такой черносерд"}},{q="Где найти Старейшину Черносерда?",a="Он находится в разрушенном тронном зале Столицы, в Руинах Лордерона, прямо над входом в спуск, ведущий в Подгород.",al={"where is darkcore","darkcore location","undercity elder","где черносерд","местонахождение черносерда","старейшина подгорода"}},{q="Враждебен ли Старейшина Черносерд к Альянсу?",a="Сам Старейшина Черносерд нейтрален и приветствует всех путников, пришедших почтить его. Однако, поскольку он находится в оплоте Отрекшихся — Руинах Лордерона, — искателям приключений Альянса нужно осторожно избегать враждебных стражей, патрулирующих поблизости.",al={"can alliance talk to darkcore","is darkcore horde","undercity lunar festival alliance","может ли альянс говорить с черносердом","черносерд орда ли","лунный фестиваль подгород альянс"}},{q="Что дает почтение Старейшине Черносерду?",a="Выражение почтения ему завершает праздничное задание в память о нем и приносит в награду Монету Наследия и счастливый красный конверт с праздничными угощениями.",al={"darkcore reward","darkcore quest","награда черносерда","задание черносерда"}}},fp="14,358,27.525.0,22.210.0,32.148.0,42.248.0,43.151.0"}
P.entries["npc:elder-goldwell"] = {n="Старейшина Златокладезь",s="Старейшина Златокладезь — древний дух земли, обитающий возле поселения дворфов Каранос в Дун Мороге. Появляясь во время Лунного фестиваля, этот почитаемый предок воплощает забытые истоки современной цивилизации дворфов.",h="Старейшина Златокладезь — древний дух земли, обитающий возле поселения дворфов Каранос в Дун Мороге.",kw={"ancestor","bronzebeard","dun morogh","earthen","elder goldwell","goldwell","kharanos","lunar festival","предок","бронзобород","дун морог","земельный","старейшина златокладезь","златокладезь","каранос","лунный фестиваль"},ang={["faction:Alliance"]="Путники из Альянса, проходящие через Каранос, часто ищут Златокладезя, чтобы почтить его и получить традиционные благословения удачи.",["race:Dwarf"]="Для дворфов встреча со Старейшиной Златокладезем — редкая возможность непосредственно увидеть свое древнее каменное наследие и род, связывающий современный Стальгорн с земельными."},sec={{t="Дух земельных",b="Старейшина Златокладезь предстает прозрачным духом земли и наблюдает за заснеженными склонами Караноса. В отличие от современных смертных дворфов из плоти и крови, его каменный облик напоминает древнюю расу, созданную титанами, от которой произошел клан Бронзобородов. Тем, кто почтит его во время праздников предков, странники получают его благословение и монету предков."}},faq={{q="Кто такой Старейшина Златокладезь?",a="Старейшина Златокладезь — дух предка из числа земельных, которого можно найти в Дун Мороге. Он приходит в Каранос во время праздника предков, чтобы современные путники могли почтить предков дворфов.",al={"elder goldwell identity","who is goldwell","goldwell lore","старейшина златокладезь кто это","кто такой златокладезь","предания о златокладезе"}},{q="Где находится Старейшина Златокладезь?",a="Его можно найти за пределами дворфийского города Каранос в Дун Мороге, обычно возле местной таверны и мест сбора.",al={"elder goldwell location","where to find elder goldwell","find goldwell","старейшина златокладезь где находится","где найти старейшину златокладезя","найти златокладезя"}},{q="Почему Старейшина Златокладезь выглядит как земельный, а не как дворф?",a="Дворфы ведут свой род от каменнокожих земельных, созданных титанами. Будучи одним из древнейших духов, чтящих прошлые поколения, Златокладезь сохраняет изначальный облик земельного, а не смертную плоть живых дворфов.",al={"why is goldwell earthen","is goldwell an earthen","goldwell rock dwarf","почему златокладезь земельный","земельный ли златокладезь","каменный дворф златокладезь"}},{q="Связан ли Старейшина Златокладезь с кланом Бронзобородов?",a="His connection to the Bronzebeard clan is unconfirmed. He is an earthen ancestor spirit found in Kharanos.",al={"is goldwell bronzebeard","goldwell clan","златокладезь бронзобород","клан златокладезя"}}},fp="14,232,23.366.0,22.202.0,32.124.0,65.240.0,47.106.0"}
P.entries["npc:elder-graveborn"] = {n="Старейшина Могильный Холм",s="Старейшина Могильный Холм — дух предка, который появляется к юго-востоку от Брилла во время Лунного фестиваля. Он предстает призрачным старцем из земельных, чтит путников и направляет паломников, ищущих других древних духов на севере Лордерона.",h="Старейшина Могильный Холм — дух предка, который появляется к юго-востоку от Брилла во время Лунного фестиваля.",kw={"ancestor","brill","earthen","elder graveborn","graveborn","lunar festival","tirisfal glades","предок","брилл","земельный","старейшина могильный холм","могильный холм","лунный фестиваль","тирисфальские леса"},ang={["faction:Alliance"]="Паломникам из Альянса приходится осторожно обходить окраины Брилла, чтобы почтить Могильного Холма и не навлечь гнев стражи и патрулей Отрекшихся.",["race:Undead"]="Для Отрекшихся, идущих по дороге между Бриллом и Подгородом, Могильный Холм служит спокойным напоминанием о древнем прошлом Азерота, пребывающим в покое вдали от Плети и порчи."},sec={{t="Дух в Тирисфале",b="За Отрекшимся городом Брилл, среди мрачных лесов Тирисфальских лесов, во время Лунного фестиваля, который проходит по всему миру, стоит Старейшина Могильный Холм. Несмотря на оскверненные окрестности и бедственное состояние королевства, призрачный старец мирно приветствует путников, ищущих традиционные благословения праздника. Помимо собственной мудрости предков, Могильный Холм делится вестями о других старейшинах поблизости, указывая паломникам на духов в Подгороде, Гробнице и в Чумных землях."}},faq={{q="Кто такой Старейшина Могильный Холм?",a="Старейшина Могильный Холм — почитаемый призрак предка, появляющийся во время Лунного фестиваля. Он возникает в Тирисфальских лесах к юго-востоку от Брилла, чтобы даровать праздничные благословения проходящим искателям приключений.",al={"elder graveborn lore","who is graveborn","brill ghost elder","старейшина могильный холм предания","кто такой могильный холм","призрак старейшина брилл"}},{q="Почему он находится в Тирисфальских лесах?",a="Во время Лунного фестиваля духи предков появляются по всему Азероту, чтобы почтить героев прошлого и общее наследие. Старейшина Могильный Холм присматривает за землями у Брилла, храня древнее присутствие среди павшего королевства Лордерон.",al={"why brill","where is elder graveborn","почему брилл","где старейшина могильный холм"}},{q="Могут ли искатели приключений из Альянса говорить с ним?",a="Да. Старейшины фестиваля приветствуют путников обеих фракций независимо от территории. Однако персонажам Альянса следует соблюдать осторожность, приближаясь к его месту упокоения, так как он находится совсем рядом с оплотом Отрекшихся — Бриллом.",al={"can alliance talk to graveborn","alliance elder brill","может ли альянс говорить с могильным холмом","старейшина альянс брилл"}},{q="Какие сведения он дает путникам?",a="Старейшина Могильный Холм направляет паломников к другим местным предкам, делясь слухами о духах в Подгороде, Гробнице в Серебряном бору, Часовне Последней Надежды, Гроте Слез и Некроситете.",al={"elder graveborn directions","graveborn quotes","старейшина могильный холм подсказки","могильный холм реплики"}}},fp="15,259,20.543.0,23.194.0,29.240.0,38.230.0,41.194.0"}
P.entries["npc:elder-morningdew"] = {n="Старейшина Утренняя Роса",s="Старейшина Утренняя Роса — древний дух ночных эльфов, появляющийся во время Лунного фестиваля в Тысяче Игл. Она дарует мудрость и благословения предков путникам, которые ищут ее среди сухих каньонов и высохших соляных равнин Мерцающей равнины.",h="Старейшина Утренняя Роса — древний дух ночных эльфов, появляющийся во время Лунного фестиваля в Тысяче Игл.",kw={"ancestor","elder","elder morningdew","ghost","lunar festival","morningdew","night elf","thousand needles","предок","старейшина","старейшина утренняя роса","призрак","лунный фестиваль","утренняя роса","ночной эльф","тысяча игл"},ang={["race:NightElf"]="Для кальдораев поиск древних старейшин вроде Утренней Росы — священный долг почтения, связывающий современных ночных эльфов с почитаемыми духами тех, кто жил до них.",["race:Tauren"]="Таурены глубоко чтят духов предков, поэтому встречи со старейшинами по всему Калимдору для них — естественное продолжение культурного почтения к мудрости прошлого."},sec={{t="Почитаемый дух фестиваля",b="Во время Лунного фестиваля духи почитаемых предков ночных эльфов и таурен появляются по всему Калимдору и Восточным королевствам, славя мудрость, наследие и мир. Старейшина Утренняя Роса — одно из таких явлений: она приходит в Тысячу Игл, чтобы приветствовать паломников. Не связанная ни с одной фракцией и смертными распрями, она вручает свою монету наследия любому искателю приключений, достаточно почтительному, чтобы обратиться к ней за советом и принять ее благословение."}},faq={{q="Кто такая Старейшина Утренняя Роса?",a="Старейшина Утренняя Роса — дух предка ночных эльфов, появляющийся во время ежегодного Лунного фестиваля. Она ждет в Тысяче Игл, чтобы путники из Альянса и Орды почтили ее.",al={"elder morningdew lore","who is morningdew","morningdew identity","старейшина утренняя роса предания","кто такая утренняя роса","утренняя роса кто это"}},{q="Зачем ее искать?",a="Искатели приключений находят ее во время Лунного фестиваля, чтобы почтить предков, и в обмен на почтение к ее духу получают Монету Наследия и благословение мудрости.",al={"why find elder morningdew","morningdew purpose","lunar festival elder","зачем искать утреннюю росу","утренняя роса зачем","старейшина лунного фестиваля"}},{q="Принадлежит ли она Альянсу или Орде?",a="Как и все старейшины Лунного фестиваля, Старейшина Утренняя Роса не вмешивается в политику смертных. Искатели приключений и Альянса, и Орды могут мирно подойти к ней, чтобы почтить ее.",al={"is morningdew hostile","elder morningdew faction","can horde talk to morningdew","враждебна ли утренняя роса","старейшина утренняя роса фракция","может ли орда говорить с утренней росой"}}},fp="16,246,33.432.0,24.191.0,39.181.0,41.170.0"}
P.entries["npc:elder-obsidian"] = {n="Старейшина Обсидиан",s="Старейшина Обсидиан — дух предка из земельных, появляющийся у Гробницы в Серебряном бору во время ежегодного Лунного фестиваля. Среди могил, захваченных Отрекшимися, он дарует мудрость и благословения древнего мира путникам, чтящим праздник.",h="Старейшина Обсидиан — дух предка из земельных, появляющийся у Гробницы в Серебряном бору во время ежегодного...",kw={"ancestor","coin of ancestry","earthen","elder obsidian","lunar festival","sepulcher","silverpine","предок","монета наследия","земельный","старейшина обсидиан","лунный фестиваль","гробница","серебряный бор"},ang={["faction:Alliance"]="Паломникам из Альянса, ищущим Старейшину Обсидиана, следует быть осторожными: избранное им место покоя находится в сердце поселения Отрекшихся — Гробницы.",["race:Dwarf"]="Для дворфов, интересующихся своим происхождением от созданных титанами, беседа с духом земельного вроде Старейшины Обсидиана — редкая возможность заглянуть в первобытное прошлое их высеченных из камня предков."},sec={{t="Дух у Гробницы",b="Среди мрачных склепов Гробницы Старейшина Обсидиан резко контрастирует с унылыми просторами Серебряного бора. Как неземной старец из земельных, его дух появляется во время Лунного фестиваля, чтобы славить древнее наследие Азерота. Хотя окрестные склепы удерживают Отрекшиеся, а их тревожат дикие ворген, Обсидиан мирно приветствует странников любой принадлежности и дарует Монету Наследия и древние благословения тем, кто потрудился искать его мудрость."}},faq={{q="Кто такой Старейшина Обсидиан?",a="Старейшина Обсидиан — древний призрак из земельных, появляющийся в Серебряном бору. Он показывается только во время Лунного фестиваля и приветствует путников, чтящих наследие предков мира.",al={"elder obsidian lore","who is obsidian","sepulcher elder","старейшина обсидиан предания","кто такой обсидиан","старейшина гробницы"}},{q="Где можно найти Старейшину Обсидиана?",a="Он покоится на кладбище Гробницы — селения под властью Отрекшихся, расположенного у дороги в центре Серебряного бора.",al={"elder obsidian location","where is obsidian","find elder obsidian","старейшина обсидиан где находится","где обсидиан","найти старейшину обсидиана"}},{q="Почему старейшина из земельных появляется в Серебряном бору?",a="Во время Лунного фестиваля духи древних старейшин появляются в землях по всему Азероту, чтобы поделиться мудростью предков. Духовное присутствие Обсидиана выходит за рамки местных территориальных конфликтов и позволяет ему тихо общаться с миром среди древних могил.",al={"why is obsidian in silverpine","earthen in silverpine","почему обсидиан в серебряном бору","земельный в серебряном бору"}},{q="Могут ли искатели приключений из Альянса говорить со Старейшиной Обсидианом?",a="Да. Старейшины фестиваля нейтральны ко всем путникам независимо от фракции. Однако, поскольку он покоится в Гробнице, искателям приключений из Альянса приходится осторожно пробираться мимо враждебной стражи Отрекшихся, чтобы добраться до него.",al={"can alliance visit elder obsidian","elder obsidian alliance friendly","может ли альянс посетить старейшину обсидиана","старейшина обсидиан дружелюбен к альянсу"}}},fp="14,275,25.494.0,22.188.0,34.153.0,54.251.0,51.227.0"}
P.entries["npc:elder-runetotem"] = {n="Старейшина Рунический Тотем",s="Старейшина Рунический Тотем — дух предка таурен, появляющийся у Колючего Холма в Дуротаре во время Лунного фестиваля. Как одна из почитаемых старейшин Орды, она дарует мудрость и благословение путникам, которые ищут ее среди красных каньонов.",h="Старейшина Рунический Тотем — дух предка таурен, появляющийся у Колючего Холма в Дуротаре во время Лунного...",kw={"coin of ancestry","durotar","elder runetotem","lunar festival","razor hill","runetotem","tauren ghost","монета наследия","дуротар","старейшина рунический тотем","лунный фестиваль","колючий холм","рунический тотем","призрак таурен"},ang={["faction:Horde"]="Стоя у хорошо укрепленного поселения Колючий Холм, она воплощает духовный союз между орками Дуротара и тауренами Мулгора.",["race:Tauren"]="Встретить почтенного предка племени Рунический Тотем так далеко от Мулгора — смиряющее напоминание о том, что духи Шу'хало присматривают за своими союзниками во всех землях."},sec={{t="Дух в Дуротаре",b="Хотя духи предков таурен обычно связаны с травянистыми равнинами и священными местами погребения Мулгора, Старейшина Рунический Тотем обитает вдали от пастбищ своего народа. Она появляется у пыльного поселения Колючий Холм в Дуротаре. Для молодых орков и странствующих искателей приключений ее неземное присутствие — мост между древними традициями Шу'хало и суровым новым домом, который Орда создала на берегу Великого моря."},{t="Почести предков",b="During the Lunar Festival, the spirits of great leaders, shamans, and heroes manifest throughout the world to commune with the living. Elder Runetotem represents the Runetotem line—a lineage known for deep reverence for the Earth Mother and spiritual communion. Travelers honoring her presence are granted ancestral tokens and her spiritual blessing."}},faq={{q="Кто такая Старейшина Рунический Тотем?",a="Старейшина Рунический Тотем — призрачный предок таурен, появляющийся близ Колючего Холма в Дуротаре. Она одна из почитаемых старейшин, возвращающихся во время Лунного фестиваля, чтобы приветствовать путников и даровать благословения предков.",al={"elder runetotem lore","who is the tauren ghost in razor hill","runetotem ghost","старейшина рунический тотем предания","кто призрак таурен в колючем холме","призрак рунический тотем"}},{q="Почему дух таурен находится в Дуротаре?",a="Хотя большинство духов предков таурен связаны с Мулгором, духи Лунного фестиваля странствуют повсюду по Калимдору и Восточным королевствам. Ее присутствие у Колючего Холма позволяет путникам из Орды, проходящим через Дуротар, почтить мудрость детей Матери-Земли.",al={"why is runetotem in razor hill","tauren ghost durotar","почему рунический тотем в колючем холме","призрак таурен дуротар"}},{q="What connection does she have to the Runetotem tribe?",a="Она носит имя клана Рунический Тотем — одного из выдающихся родов таурен, известных своими шаманами, духовными наставниками и связью с миром природы.",al={"runetotem tribe elder","runetotem family","старейшина племени рунический тотем","семья рунический тотем"}},{q="Что дает разговор с ней?",a="Разговор со Старейшиной Руническим Тотемом чтит ее память во время Лунного фестиваля, и искатели приключений получают Монету Наследия и временное благословение духов.",al={"what does elder runetotem give","runetotem reward","что дает старейшина рунический тотем","награда рунический тотем"}}},fp="15,244,19.432.0,16.352.0,23.207.0,42.296.0,53.162.0,34.163.0"}
P.entries["npc:elder-skyseer"] = {n="Старейшина Небесный Провидец",s="Старейшина Небесный Провидец — дух предка-таурена, обитающий на вершине высоких утесов Заставы Вольного Ветра в Тысяче Игл. Как почитаемый старейшина, вернувшийся из мира духов, он наблюдает за путями Орды и остается тесно связан с местами упокоения своего народа.",h="Старейшина Небесный Провидец — дух предка-таурена, обитающий на вершине высоких утесов Заставы Вольного Ветра...",kw={"ancestor","elder skyseer","freewind post","red rocks","tauren ghost","thousand needles","предок","старейшина небесный провидец","застава вольного ветра","красные скалы","призрак таурена","тысяча игл"},ang={["class:Shaman"]="Как духовные посредники, говорящие со стихиями и духами, шаманы видят в Старейшине Небесном Провидце непреходящую мудрость предков, продолжающих присматривать за живыми.",["race:Tauren"]="Для тауренов встреча со Старейшиной Небесным Провидцем — прямое общение с предком, воплощение духовного почтения, которому учат в Красных скалах и на равнинах Мулгора."},sec={{t="Дух Заставы Вольного Ветра",b="Высоко над соляными каньонами Тысячи Игл Старейшина Небесный Провидец пребывает в продуваемом ветрами поселении на плато — Заставе Вольного Ветра. Пока тауренов Заставы Вольного Ветра заняты делами у опасных мостов и деревянных площадок форпоста, Небесный Провидец наблюдает за землей как предок, шагнувший за грань мира смертных. Он служит путеводным маяком для странников, ищущих мудрость прошлых поколений, и дарует благословение тем, кто чтит старые обычаи."},{t="Связь с землями предков",b="Хотя его дух обычно является среди выветренных игл, Небесный Провидец принадлежит к древнему роду предков-тауренов, чей народ чтит священную землю Мулгора, где духи предков Красных скал оберегают племена. Духи вроде Небесного Провидца показывают, как тонка для тауренов завеса между физическим миром и духами предков: они направляют будущие поколения через память и ритуалы."}},faq={{q="Кто такой Старейшина Небесный Провидец?",a="Старейшина Небесный Провидец — дух предка-таурена, являющийся на Заставе Вольного Ветра в Тысяче Игл. Он один из почитаемых старейшин, чьи духи присматривают за современными путниками и дают наставления предков тем, кто их ищет.",al={"elder skyseer lore","who is skyseer","skyseer npc","старейшина небесный провидец предания","кто такой небесный провидец","небесный провидец нпс"}},{q="Почему Старейшина Небесный Провидец — призрак?",a="Он древний предок, покинувший мир смертных. Культура тауренов хранит глубокую духовную связь с предками, и некоторые выдающиеся старейшины остаются или возвращаются в облике духов, чтобы направлять живых.",al={"why is skyseer dead","is elder skyseer dead","ghost tauren freewind","почему небесный провидец мертв","мертв ли старейшина небесный провидец","призрак таурен застава вольного ветра"}},{q="Как он связан с Мулгором?",a="Как и всех предков-тауренов, Небесного Провидца чтит народ, чья родина — Мулгор, где духи предков Красных скал оберегают племена. Однако его собственный дух является на Заставе Вольного Ветра в Тысяче Игл.",al={"skyseer red rocks","skyseer mulgore connection","небесный провидец красные скалы","небесный провидец связь с мулгором"}},{q="Где найти Старейшину Небесного Провидца?",a="Старейшина Небесный Провидец находится на Заставе Вольного Ветра в Тысяче Игл, на укрепленном поселении на плато высоко над дном каньона.",al={"elder skyseer location","find skyseer","where is skyseer","старейшина небесный провидец местонахождение","найти небесного провидца","где небесный провидец"}}},fp="13,283,25.461.0,27.413.0,21.223.0,29.221.0,34.219.0,31.136.0"}
P.entries["npc:elder-starweave"] = {n="Старейшина Звездная Пряжа",s="Старейшина Звездная Пряжа — дух предка ночных эльфов, которого чтят во время Лунного фестиваля. Она пребывает в портовом городке Аубердин на туманном побережье Темных берегов и делится мудростью древних эпох с проходящими паломниками.",h="Старейшина Звездная Пряжа — дух предка ночных эльфов, которого чтят во время Лунного фестиваля.",kw={"ancestor","auberdine","coin of ancestry","darkshore","elder starweave","lunar festival","starweave","предок","аубердин","монета предков","темные берега","старейшина звездная пряжа","лунный фестиваль","звездная пряжа"},ang={["class:Druid"]="Друиды, наблюдающие за праздником, находят в размышлениях Звездной Пряжи о небесах созвучие с учением Кенария об обновлении, памяти и гармонии с миром природы.",["race:NightElf"]="Встреча со Старейшиной Звездной Пряжей на Темных берегах напрямую связывает кальдораев-искателей приключений с их давним родом предков, взиравших на Элуну и звезды сквозь древние катаклизмы."},sec={{t="Маяк в Аубердине",b="Старейшина Звездная Пряжа является в облике эфирной тени среди прибрежных построек Аубердина. Она одна из почитаемых предков, которых чтят Круг Кенария и народы Калимдора. Многие путники спешат через порт вглубь суши или за море, но те, кто остановится перед ней, получают благословение предков. Звездная Пряжа говорит о движении небесных светил и замечает, что звезды нынешней эпохи чертят незнакомые пути, служащие маяками надежды и стойкости для будущих поколений."}},faq={{q="Кто такая Старейшина Звездная Пряжа?",a="Старейшина Звездная Пряжа — дух предка ночных эльфов, который появляется в Аубердине во время Лунного фестиваля, чтобы поприветствовать путников, поделиться древней мудростью и вручить им Монеты предков.",al={"elder starweave lore","who is starweave","starweave the elder","старейшина звездная пряжа предания","кто такая звездная пряжа","звездная пряжа старейшина"}},{q="Где можно найти Старейшину Звездную Пряжу?",a="Ее можно найти близ поселения Аубердин на берегу Темных берегов.",al={"where is elder starweave","elder starweave location","starweave spot","где старейшина звездная пряжа","старейшина звездная пряжа местонахождение","место звездной пряжи"}},{q="Почему она является в облике духа?",a="Она почитаемый предок, являющийся во время Лунного фестиваля в духовной форме, чтобы живые могли отдать дань уважения тем, кто сформировал далекое прошлое ночных эльфов.",al={"why is starweave a ghost","is starweave dead","why ghost","почему звездная пряжа призрак","мертва ли звездная пряжа","почему призрак"}},{q="Могут ли игроки Орды говорить с ней?",a="Да. Старейшины-предки, которых чтят во время Лунного фестиваля, приветствуют путников любой принадлежности, хотя искателям приключений из Орды следует соблюдать осторожность в Аубердине, дружественном Альянсу порту.",al={"can horde visit starweave","horde elder starweave","может ли орда посетить звездную пряжу","орда старейшина звездная пряжа"}}},fp="15,224,21.495.0,23.170.0,35.93.0,32.177.0,31.187.0"}
P.entries["npc:eleanor-shackleton"] = {n="Элеонора Шеклтон",s="Элеонора Шеклтон — Отрекшаяся любительница походной жизни, разбившая лагерь к юго-западу от Брилла в Тирисфальских лесах. Вместо того чтобы оставаться в городе или Подгороде, она помогает странникам осваивать выживание в дикой местности и полевые ремесла. Ее фамилия совпадает с фамилиями других Отрекшихся в этом краю, что намекает на сохранившиеся связи из жизни до чумы.",h="Элеонора Шеклтон — Отрекшаяся любительница походной жизни, разбившая лагерь к юго-западу от Брилла в...",kw={"brill","camping 101","eleanor shackleton","shackleton","sticks and bones","the adventurer","the great outdoors","tirisfal glades","брилл","основы лагерной жизни","элеонора шеклтон","шеклтон","палки и кости","искатель приключений","на природе","тирисфальские леса"},ang={["profession:Cooking"]="Уроки Элеоноры охватывают разведение полевого костра и приготовление пищи вдали от цивилизованных очагов, поэтому ее лагерь — важная остановка для странствующих поваров.",["race:Undead"]="Для Отрекшихся умение выживать в дикой местности без удобств живых жизненно важно, и Элеонора следит, чтобы недавно восставшие собратья быстро привыкали к походным лишениям в Тирисфале."},sec={{t="Проводник по лесам",b="Пока многие недавно пробудившиеся Отрекшиеся отправляются прямо в Брилл или спускаются в Подгород, Элеонора Шеклтон разбивает лагерь в мрачных лесах на юго-западе. Выжить в Тирисфале можно лишь практичной самостоятельностью, и Элеонора обучает начинающих искателей приключений жить на зараженной земле. На своих полевых уроках она учит путников устраивать стоянки, собирать дрова и заниматься ремеслами вдали от кузнечных горнов и кухонь цивилизации."},{t="Связи из прошлой жизни",b="В разрушенных остатках Лордерона фамилии часто остаются единственной уцелевшей нитью, связывающей нежить с прошлой жизнью. Элеонора носит фамилию Шеклтон, как Пирс Шеклтон в Брилле и Саманта Шеклтон в другой части Тирисфальских лесов. Поддерживают ли эти трое тесные узы или лишь имеют общих предков со времен смертной жизни, каждый нашел свое место на службе делу Отрекшихся в погибшем королевстве."}},faq={{q="Где найти Элеонору Шеклтон?",a="Элеонора Шеклтон разбила лагерь к юго-западу от Брилла, в лесу Тирисфальских лесов, вдали от главной мощеной дороги.",al={"eleanor shackleton location","where is eleanor","shackleton spot","элеонора шеклтон местонахождение","где элеонора","место шеклтон"}},{q="Чему Элеонора Шеклтон учит искателей приключений?",a="Элеонора знакомит путников с основами выживания в дикой местности: учит разбивать лагерь, добывать пищу и заниматься профессиями вдали от жилья.",al={"eleanor quests","what does eleanor do","camping quests tirisfal","задания элеоноры","что делает элеонора","задания лагерь тирисфальские леса"}},{q="Родственна ли Элеонора другим Шеклтонам в Лордероне?",a="У нее общая фамилия с Пирсом Шеклтоном в Брилле и Самантой Шеклтон, что указывает на возможное родство еще с жизни до того, как королевство пало перед Плетью.",al={"pierce shackleton relative","samantha shackleton","shackleton family lore","пирс шеклтон родственник","саманта шеклтон","семья шеклтон предания"}},{q="Почему она разбила лагерь за пределами Брилла, а не живет в городе?",a="Элеонора занимается полевым мастерством и выживанием в дикой местности. Лагерь в лесу позволяет ей встречать странников и обучать их прямо там, где эти навыки нужны.",al={"why camp outside brill","eleanor shackleton camp","почему лагерь за бриллом","лагерь элеоноры шеклтон"}}},fp="18,356,21.516.0,21.435.0,36.125.0,47.154.0,53.169.0,60.171.0"}
P.entries["npc:electrocutioner-6000"] = {n="Электрошокер 6000",s="Электрошокер 6000 — смертоносный сверхзаряженный паучий танк, поставленный охранять Пусковую установку в облученных залах Гномрегана. Им управляет известный лепрогном лейтенант Том «Жареные Штаны» Крэнкл. Он воплощает безрассудное стремление мекжинера Термоштепселя превратить высокое напряжение в оружие.",h="Электрошокер 6000 — смертоносный сверхзаряженный паучий танк, поставленный охранять Пусковую установку в...",kw={"crankle","electrocutioner","gnomeregan","launch bay","sizzlepants","spider tank","thermaplugg","workshop key","крэнкл","электрошокер","гномреган","пусковая установка","жареные штаны","паучий танк","термоштепсель","ключ от мастерской"},ang={["faction:Alliance"]="Прорыв в Пусковую установку и уничтожение Крэнкла жизненно важны, чтобы добыть Ключ от мастерской и обойти опасные передние коридоры при освобождении Гномрегана.",["profession:Engineering"]="Инженеры восхищаются необузданной мощностью высокого напряжения, заключенной в шасси, хотя безрассудное отсутствие заземления у Термоштепселя делает машину смертельно опасной для собственного экипажа.",["race:Gnome"]="Для изгнанных гномов Стальгорна Электрошокер 6000 — оскорбление их мастерства: опасное, непроверенное чудовище, отражающее извращенное пренебрежение Термоштепселя к инженерной этике и жизням гномов."},sec={{t="Шокирующий прототип Термоштепселя",b="Мекжинер Термоштепсель никогда не славился строгими испытаниями на безопасность. Одержимый манией величия и спешкой, он регулярно отправляет непроверенные боевые машины прямо с чертежной доски в настоящий бой. Электрошокер 6000 стал его первой попыткой использовать необузданные электрические разряды как наступательную систему, установленную на бронированное шасси паукообразного танка. Вместо того чтобы отрабатывать смертоносные скачки напряжения в лаборатории, Термоштепсель сразу отправил его охранять верхние ярусы Пусковой установки Гномрегана."},{t="Лейтенант «Жареные Штаны»",b="Управление экспериментальными машинами часто оборачивается смертью, особенно когда речь о смертельном напряжении. Первые пилоты-испытатели гибли в мучительных авариях, но лейтенант Том Крэнкл выдержал смертоносные разряды и остался жив у органов управления. Получив мрачное прозвище «Жареные Штаны», он стал символом стойкости среди облученных лепрогномов, верных Термоштепселю, и яростно охраняет путь к внутренним мастерским."}},faq={{q="Где найти Электрошокер 6000?",a="Электрошокер 6000 стоит на приподнятой площадке мостков над Пусковой установкой в павшем городе Гномрегане.",al={"electrocutioner 6000 location","where is electrocutioner","find electrocutioner 6000","электрошокер 6000 местонахождение","где электрошокер","найти электрошокер 6000"}},{q="Кто управляет Электрошокером 6000?",a="Им управляет лейтенант Том Крэнкл, более известный как «Жареные Штаны». Это безумный офицер из лепрогномов, прославившийся среди войск Термоштепселя как единственный пилот, переживший опасные внутренние электрические разряды танка.",al={"who drives electrocutioner 6000","sizzlepants","tom sizzlepants crankle","pilot of electrocutioner","кто управляет электрошокером 6000","жареные штаны","том жареные штаны крэнкл","пилот электрошокера"}},{q="Почему машина так неустойчива?",a="Мекжинер Термоштепсель отказывается тратить время на должные проверки безопасности и предпочитает немедленно пускать изобретения в дело. Электрошокер 6000 стал его первым опытом с электрифицированным паучьим танком, и его смертоносные линии питания нестабильны и опасны даже для собственного пилота.",al={"why does it shock","electrocutioner prototype","thermaplugg design","почему бьет током","прототип электрошокера","конструкция термоштепселя"}},{q="Почему победа над Электрошокером 6000 важна для исследователей?",a="У пилота хранится Ключ от мастерской — устройство, отпирающее заднюю дверь в более глубокие инженерные отсеки Гномрегана и дающее отрядам более быстрый путь через отвоеванные помещения.",al={"workshop key","why kill electrocutioner","electrocutioner 6000 loot","ключ от мастерской","зачем убивать электрошокер","электрошокер 6000 добыча"}},{q="Электрошокер — это автомат или транспорт?",a="Это модифицированный паучий танк — бронированная механическая машина, которой вручную управляет пилот из внутренней кабины, а не автономный роботизированный механизм.",al={"is electrocutioner a robot","electrocutioner spider tank type","электрошокер робот","тип паучьего танка электрошокер"}}},fp="20,310,32.492.0,24.433.0,44.135.0,36.234.0,31.294.0,66.206.0,49.171.0"}
P.entries["npc:elling-trias"] = {n="Иллинг Триас",s="Иллинг Триас управляет «Сыром Триаса» — небольшой лавкой в оживленном Торговом квартале Штормграда. Внешне он жизнерадостный и увлеченный торговец молочными продуктами, но втайне является одним из самых осведомленных торговцев информацией в королевстве. За головками сыра и приветливой болтовней Триас держит руку на пульсе событий, происходящих на разных континентах.",h="Иллинг Триас управляет «Сыром Триаса» — небольшой лавкой в оживленном Торговом квартале Штормграда.",kw={"elaine trias","elling trias","mathias shaw","missing diplomat","si:7","stormwind","trade district","trias cheese","tyrion","элейн триас","иллинг триас","матиас шоу","пропавший дипломат","шру","штормград","торговый квартал","сыр триаса","тирион"},ang={["class:Rogue"]="Любой знаток скрытности понимает, что сырная лавка Иллинга — идеальное место для тайника. Близость к Старому городу и тесные связи с Матиасом Шоу делают его неотъемлемой частью штормградского преступного мира.",["faction:Alliance"]="Иллинг служит незаметной опорой разведки Альянса, тихо отсеивая слухи от Терамора до Дольного Очага, чтобы защитить королевство от внутреннего разложения."},sec={{t="Мастер-сыровар",b="Для обычного покупателя, прогуливающегося по Торговому кварталу, Иллинг Триас — всего лишь мастер, преданный тонким сырным сортам: он трудится в лавке вместе с женой Элейн и сыном Беном. Он увлеченно расхваливает головки сыра и дружелюбно болтает с горожанами. Но посвященные знают, что «Сыр Триаса» — один из самых надежных прикрытий Штормграда. Постоянный шум городской торговли служит отличным прикрытием для агентов, придворных и искателей приключений, которым нужно тихо переговорить, не привлекая внимания городской стражи."},{t="Паутина шепотов",b="Сеть осведомителей и союзников Иллинга поразительна для простого лавочника. Он поддерживает связи с Мастером Матиасом Шоу из ШРУ, взаимодействует с представителями Церкви, такими как епископ Делавей, и переписывается с агентами в таких отдаленных местах, как Темнолесье, Остров Терамор и далекие Чумные земли близ Дольного Очага. Когда появляются странные слухи — о разбойниках на дорогах или о тихих передвижениях в сельской местности, — Триас нередко складывает головоломку задолго до того, как о ней узнает королевский двор."},{t="Пропавший дипломат",b="Когда высокопоставленный дипломат исчезает во время плавания в Терамор, Иллинг Триас становится ключевым звеном в раскрытии заговора. Направляя следователей к своим знакомым — среди них отдалившийся от дел агент по имени Йорген и старый друг Тирион, — Триас помогает выявить причастность Братства Справедливости к похищению. Несмотря на острый ум и циничные шутки, Иллинг понимает, что заговор уходит корнями в самое сердце штормградской аристократии."}},faq={{q="Кто такой Иллинг Триас?",a="Иллинг Триас на вид торговец сыром, который вместе с семьей держит «Сыр Триаса» в Торговом квартале Штормграда. Под этим прикрытием скрывается опытный торговец сведениями, связанный с ШРУ, Церковью и дальними форпостами по всему Азероту.",al={"who is elling","elling trias identity","trias cheese guy","кто такой иллинг","личность иллинга триаса","сырник триас"}},{q="Где находится его сырная лавка?",a="«Сыр Триаса» находится в Торговом квартале Штормграда, в ряду лавок вдоль внешней стены канала, неподалеку от границы, ведущей к Старому городу.",al={"trias cheese location","where is elling trias","trias shop stormwind","где сыр триаса","где найти иллинга триаса","лавка триаса штормград"}},{q="Как он связан с Братством Справедливости?",a="Триас не состоит в Братстве Справедливости, а следит за его действиями через свою сеть осведомителей. Он помогает искателям приключений из Альянса выявлять причастность Братства Справедливости к подрывным замыслам, включая похищение королевского дипломата.",al={"trias defias","is trias in the defias","триас братство справедливости","состоит ли триас в братстве справедливости"}},{q="Откуда он знает Матиаса Шоу?",a="Иллинг тесно сотрудничает с Мастером Матиасом Шоу и разведывательным аппаратом ШРУ. Его лавка служит неофициальным наблюдательным пунктом, откуда можно начинать осторожные расследования в обход официальных королевских каналов.",al={"trias and shaw","trias si7","is trias si7","триас и шоу","триас шру","связан ли триас с шру"}},{q="Кто работает в лавке вместе с ним?",a="Иллинг держит «Сыр Триаса» вместе с женой Элейн Триас и сыном Беном Триасом. Вместе они поддерживают видимость оживленной обычной семейной торговой лавки.",al={"trias family","elling trias wife","семья триаса","жена иллинга триаса"}},{q="Какова его роль в расследовании дела о пропавшем дипломате?",a="Следователи, направленные к Триасу епископом Делавеем, пользуются обширной сетью знакомств Иллинга, включая его старых соратников Йоргена и Тириона, чтобы проследить действия Братства Справедливости и выяснить, кто захватил дипломата, направлявшегося в Терамор.",al={"missing diplomat trias","why visit trias cheese","пропавший дипломат триас","зачем идти к сыру триаса"}}},fp="12,377,23.523.0,17.478.0,20.442.1,20.243.0,33.161.0,49.235.1,30.211.0,27.163.0,62.220.1"}
P.entries["npc:elu"] = {n="Элу",s="Элу — ученик наездника на ветрокрылах, расквартированный на вершине Заставы Вольного Ветра в Тысяче Игл. Стремясь начать официальное обучение и подняться в небо, он поручает путникам из Орды добывать яйца диких виверн из ближайших гнезд.",h="Элу — ученик наездника на ветрокрылах, расквартированный на вершине Заставы Вольного Ветра в Тысяче Игл.",kw={"elu","freewind post","highperch","thousand needles","wind rider","wyvern","wyvern eggs","элу","застава вольного ветра","скальное гнездовье","тысяча игл","наездник на ветрокрыле","виверна","яйца виверн"},ang={["faction:Horde"]="Сбор яиц виверн для Элу напрямую укрепляет курьерскую и транспортную сеть Орды, сохраняя воздушную связь между отдаленными форпостами Калимдора.",["race:Tauren"]="Для тауренов помощь Элу — это поддержка соплеменника, стремящегося освоить древнее и важное искусство обращения с вивернами высоко над родными каньонами."},sec={{t="Усердный ученик",b="Высоко над соляными равнинами и дном каньона на Заставе Вольного Ветра Элу проводит дни, ухаживая за летающими скакунами поселения и мечтая о собственном полете. Молодой таурен-ученик жаждет вступить в ряды мастеров-наездников на ветрокрылах, патрулирующих высокие плато Калимдора. Однако прежде чем начать настоящее обучение полетам, он должен доказать свои способности, пополнив запас виверн: он посылает умелых искателей приключений добывать целые яйца у свирепых диких виверн, гнездящихся в Скальном гнездовье."}},faq={{q="Кто такой Элу?",a="Элу — таурен, ученик наездника на ветрокрылах, расквартированный на Заставе Вольного Ветра в Тысяче Игл. Он отвечает за добычу и выращивание новых скакунов для воздушной сети Орды.",al={"elu freewind post","who is elu","tauren apprentice elu","элу застава вольного ветра","кто такой элу","таурен ученик элу"}},{q="Зачем Элу нужны яйца виверн?",a="Элу поручено пополнять стойла с вивернами для мастеров-наездников на ветрокрылах. Выращивание зверей из свежесобранных яиц позволяет должным образом обучить их и приучить к людям, чтобы они стали надежными скакунами Орды.",al={"why wyvern eggs","elu wyvern quest","elu quest goal","зачем яйца виверн","задание элу виверны","цель задания элу"}},{q="Куда Элу посылает искателей приключений за яйцами?",a="Он направляет их в Скальное гнездовье — опасное плато на западе Тысячи Игл, где колонии диких виверн яростно охраняют свои гнезда.",al={"where are wyvern eggs","where is highperch","elu egg location","где яйца виверн","где скальное гнездовье","где искать яйца элу"}}},fp="3,217,19.520.0,11.169.0,30.209.0,45.140.0"}
P.entries["npc:eva-sarkhoff"] = {n="Ева Саркофф",s="Ева Саркофф — призрачный остаток бывшей старшей горничной дома Баровых; вместе с мужем Люсьеном она остается неподалеку от ужасов Некроситета. Замученная и убитая Мясником при падении Каэр Дарроу, ее душа ищет отважных смертных, чтобы отомстить за их смерть и уничтожить их проклятые останки.",h="Ева Саркофф — призрачный остаток бывшей старшей горничной дома Баровых; вместе с мужем Люсьеном она остается...",kw={"barov","caer darrow","cult of the damned","eva sarkhoff","krastinov","lucien sarkhoff","scholomance","the butcher","барова","каэр дарроу","культ проклятых","ева саркофф","крастинов","люсьен саркофф","некроситет","мясник"},ang={["class:Priest"]="Вид неупокоенных мук Евы и Люсьена — суровое напоминание о жестокости Плети; священнослужители должны даровать покой их душам и очистить скверную магию, что их удерживает.",["race:Human"]="Ева и ее муж олицетворяют простых слуг Лордерона, преданных собственной развращенной аристократией, когда дом Баровых продал Каэр Дарроу Кел'Тузаду."},sec={{t="Падение дома Баровых",b="Ева десятилетиями служила богатому семейству Баровых старшей горничной, ухаживая за обширным замком Каэр Дарроу вместе с мужем Люсьеном, дворецким семьи. Когда Бароны стали одержимы страхом перед старостью и смертью и заботой о своем богатстве, они заключили роковую сделку с Кел'Тузадом. Поместье постепенно перешло к зарождающемуся Культу Проклятых, превратившему величественную усадьбу в Некроситет — тайную академию некромантии. Ева и Люсьен полгода прятались в коридорах замка, добывая еду и наблюдая, как культисты и чудовища шаг за шагом захватывают их дом."},{t="Скальпель Мясника",b="Плеть неизбежно обнаружила Еву и Люсьена и передала их доктору Теолену Крастинову, известному как Мясник. Крастинов неделями подвергал пару мучительным опытам, используя темную магию, чтобы продлить их жизнь далеко за пределы человеческой выносливости. Даже после смерти их тела скормили вурдалакам, а неупокоенные души приковали к Каэр Дарроу, где Ева теперь умоляет проходящих мимо искателей приключений убить Крастинова и сжечь их останки."}},faq={{q="Кем была Ева Саркофф до смерти?",a="Ева Саркофф была старшей горничной знатного семейства Баровых и десятилетиями жила и работала в замке Каэр Дарроу вместе с мужем Люсьеном, служившим дворецким.",al={"eva sarkhoff backstory","who is eva sarkhoff","eva lore","история евы саркофф","кто такая ева саркофф","ева предыстория"}},{q="Как умерла Ева?",a="После месяцев, проведенных в укрытии от Культа Проклятых, Еву и Люсьена обнаружили и передали доктору Теолену Крастинову. Крастинов безжалостно пытал их неделями, поддерживая в них жизнь темной магией, пока они наконец не умерли, а их тела не скормили вурдалакам.",al={"how did eva sarkhoff die","eva sarkhoff death","who killed eva","как умерла ева саркофф","смерть евы саркофф","кто убил еву"}},{q="Почему призрак Евы все еще в Каэр Дарроу?",a="Муки Евы были настолько ужасны и неестественны, что ее дух остался привязан к миру смертных. Она не обретет покой, пока доктор Крастинов не будет убит, а ее телесные останки в Некроситете не будут сожжены.",al={"why is eva a ghost","eva spirit","why is eva lingering","почему ева призрак","дух евы","почему ева не упокоилась"}}},fp="12,310,23.585.0,21.483.1,37.171.0,16.272.0,40.211.0"}
P.entries["npc:executor-arren"] = {n="Палач Аррен",s="Палач Аррен — высокопоставленный офицер Отрекшихся, расквартированный в Могильнике. Он руководит обороной и укреплением поселения, пока из могил поднимаются вновь пробудившиеся нежити. Аррен координирует местную борьбу с безмозглыми зомби Плети, дикими зверями и наступающими фанатиками Алого ордена.",h="Палач Аррен — высокопоставленный офицер Отрекшихся, расквартированный в Могильнике.",kw={"deathknell","executor arren","forsaken","night web's hollow","scarlet crusade","sylvanas","tirisfal glades","могильник","палач аррен","отрекшиеся","паучья низина","алый орден","сильвана","тирисфальские леса"},ang={["faction:Horde"]="Командование Аррена на передовой в Могильнике — первый оплот Орды на севере Лордерона, обеспечивающий выживание во враждебном окружении.",["race:Undead"]="Палач Аррен — один из первых командиров, которых встречает каждый Отрекшийся, выбравшись в Тирисфаль, и именно он дает им первое представление о службе Темной Госпоже."},sec={{t="Командир Могильника",b="Стоя непреклонно у часовни в Могильнике, Палач Аррен выступает главным военным голосом молодых Отрекшихся на месте их пробуждения. Пока смотрители в склепах помогают недавно восставшим нежити справиться с растерянностью, Аррен направляет их внимание вовне — на выживание. Под знаменем королевы Сильваны Ветрокрылой он организует местные вылазки, чтобы уничтожать безмозглых зомби, угрожающих границам деревни, и создавать безопасную территорию в тени падения Лордерона."},{t="Защита окраин",b="Могильник окружен опасностями куда более смертоносными, чем растерянные новички. По приказам Аррена разведчики и новобранцы уничтожают злобных пауков, населяющих Паучью низину, и устраняют опасных хищников, бродящих на лесных опушках. Требуя решительных действий от каждого, кто на них способен, Аррен проверяет стойкость новоприбывших, чтобы на службе Темной Госпожи остались лишь те, кто способен защитить свой второй шанс на существование."},{t="Багровая угроза",b="Главная стратегическая забота Аррена — Алый орден. Фанатики считают всех нежити чудовищами, подлежащими полному истреблению, и не различают или не желают различать Плеть и свободных Отрекшихся. Аррен организует точечные удары по патрулям Алого ордена, расположившимся в глуши Тирисфаля, перехватывая гонцов и изучая захваченные донесения, чтобы уберечь Могильник от очищения священным огнем."}},faq={{q="Кто такой Палач Аррен?",a="Палач Аррен — командующий офицер, отвечающий за Могильник в Тирисфальских лесах. Он превращает недавно восставших Отрекшихся в боеспособную силу для защиты деревни и охраны окрестностей.",al={"arren role","who is arren","deathknell executor","роль аррена","кто такой аррен","палач могильника"}},{q="Каково звание палача среди Отрекшихся?",a="Палачи — доверенные военные и административные командиры в иерархии Отрекшихся. Они управляют местными гарнизонами, руководят операциями в полевых условиях и обеспечивают исполнение воли и законов королевы Сильваны Ветрокрылой.",al={"executor title","what is an executor","forsaken executor rank","титул палач","кто такой палач","звание палача отрекшихся"}},{q="Почему Аррен посылает новобранцев против зомби?",a="Зомби, бродящие возле Могильника, — безмозглые остатки Плети, оставшиеся после того, как чума опустошила Лордерон. Аррен приказывает уничтожать их, чтобы вновь пробудившиеся нежить не были растерзаны, покинув склепы.",al={"why kill zombies","the damned quest","mindless scourge","зачем убивать зомби","задание проклятые","безмозглая плеть"}},{q="Почему Алый орден находится в Тирисфальских лесах?",a="Алый орден — радикальная человеческая фракция, посвятившая себя истреблению всей нежити. Ее форпосты разбросаны по руинам Лордерона, и она активно стремится уничтожить Отрекшихся, считая их неотличимыми от Плети.",al={"scarlet crusade tirisfal","why crusade here","crusaders in deathknell","алый орден тирисфаль","зачем здесь алый орден","алые в могильнике"}},{q="Что такое Паучья низина?",a="Паучья низина — кишащая пауками пещера к северу от Могильника. Аррен направляет новобранцев очистить ее от агрессивных пауков, чтобы устранить серьезную местную опасность и показать боевое мастерство.",al={"spider cave deathknell","night webs hollow","arren spider quest","пещера пауков могильник","паучья низина","задание аррена пауки"}},{q="Куда Аррен отправляет новобранцев после выполнения его заданий?",a="Когда непосредственные угрозы Могильнику устранены, Аррен отправляет способных новобранцев в Брилл — доложить Палачу Зуганду и помочь общим усилиям Отрекшихся в Тирисфальских лесах.",al={"next after deathknell","where to go after arren","the executor in the field","что дальше после могильника","куда идти после аррена","палач на передовой"}}},fp="14,332,23.510.0,24.454.0,18.435.1,22.220.0,44.211.0,49.217.0,46.218.0,27.196.0,58.189.0"}
P.entries["npc:executor-zygand"] = {n="Палач Зуганд",s="Палач Зуганд — старший командир Отрекшихся, расквартированный в ратуше Брилла. Он руководит оборонительными и военными операциями в центральной части Тирисфальских лесов. Подчиняясь непосредственно верховному командованию Подгорода, он координирует уничтожение сил Алого ордена, вторгающихся на земли Отрекшихся.",h="Палач Зуганд — старший командир Отрекшихся, расквартированный в ратуше Брилла.",kw={"arren","brill","deathguard","executor","maggot eye","scarlet crusade","tirisfal","zygand","аррен","брилл","страж смерти","палач","гнилоглаз","алый орден","тирисфаль","зуганд"},ang={["faction:Horde"]="Путники из Калимдора, посещающие Тирисфальские леса, видят в Зуганде организованное и дисциплинированное военное руководство, которое ведет борьбу Отрекшихся за защиту Лордерона.",["race:Undead"]="Для Отрекшихся, покидающих Могильник, Палач Зуганд олицетворяет более широкую военную власть Подгорода и принимает новых граждан на действительную службу против злейших врагов."},sec={{t="Командование в Брилле",b="Находясь в административном сердце Брилла, Палач Зуганд координирует оборону региона для Отрекшихся после их первого пробуждения в Могильнике. Будучи непосредственным начальником таких районных офицеров, как Палач Аррен, и полевых часовых, как Страж смерти Линнея, Зуганд обобщает разведданные и отправляет способных новобранцев защищать границы Лордерона от вторжений."},{t="Война с Орденом",b="Главная военная забота Зуганда — фанатичное присутствие Алого ордена, наводнившего заставы по всем Тирисфальским лесам. По его приказу агентов систематически отправляют против разведчиков, лагерей и передовых баз крестоносцев, чтобы фанатики никогда не набрали достаточно сил для угрозы подступам к Подгороду."}},faq={{q="Кто такой Палач Зуганд?",a="Палач Зуганд — старший офицер Отрекшихся, действующий из Брилла в Тирисфальских лесах. Он командует местными гарнизонами Стражей смерти, получает тактические донесения от офицеров низшего ранга и руководит военными кампаниями против местных угроз.",al={"zygand","who is executor zygand","zygand role","зуганд","кто такой палач зуганд","роль зуганда"}},{q="Где найти Палача Зуганда?",a="Он находится в главной ратуше Брилла или рядом с ней. Брилл — главное поселение Отрекшихся в Тирисфальских лесах, расположенное к северу от Подгорода.",al={"zygand location","where is zygand","executor zygand map","местонахождение зуганда","где зуганд","палач зуганд карта"}},{q="Какова главная цель Зуганда в Тирисфальских лесах?",a="Его главная задача — руководить региональной войной против Алого ордена. Он следит за передвижениями фанатиков по всему Тирисфалю и отдает приказы разрушать их лагеря и уничтожать руководство, пока они не выступили на Подгород.",al={"zygand quest goal","why fight crusade","zygand purpose","цель зуганда","зачем бороться с орденом","задача зуганда"}},{q="Кто подчиняется Палачу Зуганду?",a="Зуганд является начальником Палача Аррена, который направляет первых новобранцев в Могильнике, а также полевых часовых, таких как Страж смерти Линнея, патрулирующая главный перекресток Тирисфальских лесов.",al={"zygand subordinates","who serves zygand","arren superior","подчиненные зуганда","кто служит зуганду","начальник аррена"}},{q="Занимается ли Палач Зуганд угрозами со стороны немертвых-отщепенцев?",a="Да. Помимо борьбы с Алым орденом, Зуганд объявляет региональные награды за уничтожение диких немертвых и опасных падальщиков-одиночек, например гнолла-похитителя трупов Гнилоглаза, которые угрожают путникам в лесах.",al={"maggot eye","zygand bounties","wanted quests","гнилоглаз","награды зуганда","задания на охоту"}},{q="Какой ранг занимает «палач» среди Отрекшихся?",a="Палач — региональный правитель и военный командир в иерархии Отрекшихся. Палачи управляют поселениями, командуют местными отрядами Стражей смерти и обеспечивают власть королевы Сильваны в спорных областях Лордерона.",al={"what is an executor","executor rank","forsaken executor","кто такой палач","ранг палача","палач отрекшихся"}}},fp="15,297,16.392.0,22.341.0,23.236.0,33.146.0,46.239.0,31.198.0,49.226.0,53.231.0"}
P.entries["npc:falfindel-waywarder"] = {n="Хранитель дорог Фалфиндел",s="Хранитель дорог Фалфиндел — часовой из числа ночных эльфов, расквартированный в Таланааре, форпосте на границе Фераласа и Тысячи Игл. С этого пограничного поста он работает над исцелением оскверненных земель и защитой южных дебрей Калимдора. Путники, спускающиеся из Когтистых гор или Степей, часто застают его в поисках помощи в восстановлении равновесия в природе.",h="Хранитель дорог Фалфиндел — часовой из числа ночных эльфов, расквартированный в Таланааре, форпосте на...",kw={"charred vale","falfindel","feralas","stonetalon","thalanaar","thousand needles","waywarder","wisps","обугленная долина","фалфиндел","фералас","когтистые горы","таланаар","тысяча игл","хранитель дорог","блуждающие огоньки"},ang={["class:Druid"]="Его усилия по отправке лесных духов и блуждающих огоньков для исцеления выжженных почв Когтистых гор отражают священную миссию друидов — восстановление природы.",["faction:Alliance"]="Для путников из Альянса, совершающих долгий путь на юг из Степей или Когтистых гор, Фалфиндел и стража в Таланааре — радушное убежище.",["race:NightElf"]="Фалфиндел воплощает бдительность вашего народа на рубежах Калимдора: он стремится залечить шрамы природы и защитить от опасностей наступающих дебрей."},sec={{t="Стража на южной границе",b="Таланаар — это врата, где пышные леса Фераласа спускаются к высоким мезам и сухим соляным равнинам Тысячи Игл. Хранитель дорог Фалфиндел несет стражу на этом отдаленном форпосте и встречает усталых путников, проделавших долгий путь через континент. Окруженный величественной природой и скрытыми опасностями, он служит связующим звеном для ночных эльфов, следящих как за местными угрозами, так и за более широкими бедствиями природы по всему Калимдору."},{t="Исцеление Обугленной долины",b="Несмотря на свой южный пост, Фалфиндел глубоко обеспокоен разрушениями далеко на севере, в Когтистых горах. Обугленная долина, разоренная темным колдовством и огненным разрушением, остается болезненным шрамом на теле дикой природы Калимдора. Когда искатели приключений доставляют Фалфинделу помощь для ее восстановления, он взывает к духам леса. Призвав рои блуждающих огоньков, он велит им поспешить на север, в Когтистые горы, и начать исцелять выжженную землю."},{t="Наблюдение за свинобразами и пустошами",b="Помимо руководства восстановительными работами, Фалфиндел пристально следит за окрестностями, включая логова свинобразов в Лабиринтах Иглошкурых. Изучая найденные дневники и собирая сведения о предводителях свинобразов, Фалфиндел следит за тем, чтобы Альянс понимал растущие опасности, угрожающие перевалам между Фераласом и центральными пустынями."}},faq={{q="Где находится Хранитель дорог Фалфиндел?",a="Фалфиндел расквартирован в Таланааре, форпосте ночных эльфов на границе Фераласа и Тысячи Игл.",al={"falfindel location","where is falfindel","falfindel waywarder map","местонахождение фалфиндела","где фалфиндел","хранитель дорог фалфиндел карта"}},{q="Какова роль Фалфиндела в Таланааре?",a="Он служит часовым и проводником на форпосте: следит за региональными угрозами, такими как свинобразы в Тысяче Игл, и координирует восстановление разоренных земель вроде Обугленной долины.",al={"what does falfindel do","falfindel purpose","falfindel quests","чем занимается фалфиндел","задача фалфиндела","задания фалфиндела"}},{q="Как Фалфиндел помогает Обугленной долине?",a="Когда искатели приключений помогают вернуть Обугленную долину, Фалфиндел произносит заклинание и призывает лесных блуждающих огоньков, отправляя их на север, в Когтистые горы, исцелять зараженную землю.",al={"falfindel stonetalon","falfindel charred vale","reclaiming the charred vale falfindel","фалфиндел когтистые горы","фалфиндел обугленная долина","возвращение обугленной долины фалфиндел"}},{q="Почему Фалфиндела интересуют Лабиринты Иглошкурых?",a="Он изучает угрозу со стороны свинобразов Лабиринтов и осматривает такие предметы, как дневник Одинокой Брови, чтобы проследить влияние их предводителей, например Хозяйки Лабиринтов.",al={"crone of the kraul falfindel","lonebrow journal falfindel","falfindel quilboar","хозяйка лабиринтов фалфиндел","дневник одинокой брови фалфиндел","фалфиндел свинобразы"}},{q="Фалфиндел на стороне Альянса или нейтрален?",a="Фалфиндел — часовой ночных эльфов и союзник Альянса. Путники из Орды, приближающиеся к Таланаару, найдут форпост враждебным.",al={"is falfindel alliance","falfindel faction","фалфиндел альянс","фракция фалфиндела"}},{q="Что Фалфиндел говорит путникам?",a="Он тепло приветствует дружелюбных гостей, отмечая их долгий путь: «Похоже, вы проделали долгий путь.»",al={"falfindel gossip","falfindel quote","беседа фалфиндела","цитата фалфиндела"}}},fp="19,370,28.456.0,24.471.0,36.366.0,37.119.0,38.195.0,41.185.0,46.172.0,50.150.0,37.132.0"}
P.entries["npc:falla-sagewind"] = {n="Фолла Ветер Мудрости",s="Фолла Ветер Мудрости — замкнутая провидица-таурен, живущая высоко на скалистой вершине с видом на центральные Степи. Она расположилась между Перекрестком и Цветущим оазисом и изучает природные и мистические аномалии, тревожащие окрестные земли. К ней часто обращаются за советом искатели приключений, исследующие извращенную порчу, просачивающуюся из соседних Пещер Стенаний.",h="Фолла Ветер Мудрости — замкнутая провидица-таурен, живущая высоко на скалистой вершине с видом на центральные...",kw={"barrens","crossroads","falla","glowing shard","lushwater oasis","nightmares","sagewind","tauren","wailing caverns","степи","перекресток","фолла","светящийся осколок","цветущий оазис","кошмары","ветер мудрости","таурен","пещеры стенаний"},ang={["class:Druid"]="Друиды узнают в Фолле важную союзницу в изучении трагического падения Наралекса и Друидов Клыка в Пещерах Стенаний.",["faction:Horde"]="Фолла помогает Орде, истолковывая странные знамения и оскверненные реликвии, которые приносят разведчики из спорных саванн Степей.",["race:Tauren"]="Фолла Ветер Мудрости воплощает долг таурен — тихо оберегать землю, высматривая духовную гниль с высоты, пока их собратья защищают дороги внизу."},sec={{t="Наблюдательница с высокой скалы",b="Фолла Ветер Мудрости разбила лагерь высоко над пылью и суетой степных троп, на уединенной вершине к юго-западу от Перекрестка. Оттуда она торжественно следит за хрупкими саваннами внизу, наблюдая за внезапными переменами в поведении животных и надвигающейся порчей, поднимающейся из подземных расселин Пещер Стенаний. Одинокое бдение отделяет ее от повседневной торговли Перекрестка, делая ее внимательной отшельницей, чуткой к духам и безмолвным ранам земли."},{t="Пробуждающийся кошмар",b="Когда из мутировавших зверей Степей извлекают странные пульсирующие осколки, мудрые путники идут взбираться на скалы к Фолле. Она помогает истолковать извращенную магию, разрушающую естественный порядок оазисов. Распознав мрачные признаки того, что Изумрудный Сон портится под землей, она отправляет героев к мудрым друидам Круга Кенария за более глубокими ответами о кошмаре, пускающем корни в этом регионе."}},faq={{q="Кто такая Фолла Ветер Мудрости?",a="Фолла Ветер Мудрости — одинокая провидица-таурен, живущая на высокой скале к юго-западу от Перекрестка в Степях. Она наблюдает за землей и помогает путникам, пытающимся понять странные магические недуги, распространяющиеся по региону.",al={"who is falla sagewind","who is falla","falla sagewind lore","кто такая фолла ветер мудрости","кто такая фолла","фолла ветер мудрости предания"}},{q="Где найти Фоллу Ветер Мудрости?",a="Она находится на вершине крутой горы прямо к юго-западу от Перекрестка и к северу от Цветущего оазиса. Чтобы добраться до ее лагеря, нужно подняться по извилистым каменистым тропам от окружающей саванны.",al={"falla sagewind location","where is falla","how to reach falla sagewind","местонахождение фоллы ветер мудрости","где фолла","как добраться до фоллы ветер мудрости"}},{q="Почему Фоллу Ветер Мудрости интересуют Пещеры Стенаний?",a="Фолла следит за равновесием природы в Степях. Когда искатели приключений приносят ей светящийся осколок из глубин Пещер Стенаний, она узнает в нем сущность Изумрудного Сна, обращенную в кошмар, и призывает отнести его мудрому друиду.",al={"falla wailing caverns","why does falla care about the oasis","falla glowing shard","фолла пещеры стенаний","почему фолла заботится об оазисе","фолла светящийся осколок"}},{q="Связана ли Фолла Ветер Мудрости с каким-либо кланом или семьей?",a="Она носит фамилию Ветер Мудрости, как и другие известные таурены, например Охотник Ветер Мудрости и Тауху Ветер Мудрости. Хотя семейная связь вероятна, учитывая традиции именования у таурен, она в основном держится особняком на своем утесе.",al={"sagewind family","who are the sagewinds","is falla related to tahu","семья ветер мудрости","кто такие ветер мудрости","фолла родственница тауху"}},{q="Какие задания связаны с Фоллой Ветер Мудрости?",a="Фолла участвует в расследованиях, связанных с Пещерами Стенаний, в частности принимает или продолжает задания «Светящийся осколок» и «Кошмары», посвященные темному сну, который оскверняет местные оазисы.",al={"falla sagewind quests","quests from falla","in nightmares quest","задания фоллы ветер мудрости","задания от фоллы","задание кошмары"}},{q="Могут ли игроки Альянса общаться с Фоллой Ветер Мудрости?",a="Да. Фолла помогает путникам обеих фракций со Светящимся осколком: искателей приключений Альянса она отправляет к Матренгилу Медвежьей Лапе в Дарнасс, а искателей приключений Орды — к Хамуулу Руническому Тотему в Громовой Утес.",al={"is falla sagewind hostile","falla alliance friendly","враждебна ли фолла ветер мудрости","фолла дружелюбна к альянсу"}}},fp="14,352,24.528.0,20.438.1,22.242.0,32.209.0,56.260.0,53.237.0,35.214.0,50.194.0"}
P.entries["npc:fallen-hero-of-the-horde"] = {n="Павший герой Орды",s="Павший герой Орды — неупокоенный дух орка-воина, стоящий на страже на южной дороге из Болота Печали. Связанный сожалением и бесчестьем, он предупреждает проходящих путников об ужасах Выжженных земель и ищет защитников, готовых избавить его измученных солдат от демонического рабства.",h="Павший герой Орды — неупокоенный дух орка-воина, стоящий на страже на южной дороге из Болота Печали.",kw={"allistarj","fallen hero of the horde","grol the destroyer","lieutenant kirith","razelikh the defiler","sevine","stones of binding","swamp talker","аллистардж","павший герой орды","грол разрушитель","лейтенант кирит","разелих осквернитель","севин","камни связывания","болотный вещун"},ang={["class:Warrior"]="Как павший прославленный воин, он духовно близок воинам-искателям приключений, которые знают горечь выживания, когда товарищи погибли.",["faction:Horde"]="Герой воплощает муку воина, чья честь была отнята демонической жестокостью, и взывает к искателям приключений Орды: отомстить за его погибший отряд и смыть пятно поражения с его наследия."},sec={{t="Трагический приказ",b="При жизни этот воин был прославленным защитником, посланным с отобранным полком солдат исследовать Выжженные земли и доложить о присутствии Пылающего Легиона. Его донесение так и не дошло: гонец, отправленный на север к Каменору, попал в засаду и был убит Болотным Вещуном и его мурлоками. Оставшись без приказов и подкреплений, командир в конце концов повел солдат на юг, в разоренные пустоши, чтобы противостоять растущей тьме. Это было роковой ошибкой. Разбитая демонами армия была рассеяна, пленена и подвергнута жестоким мучениям от рук повелителя ужаса Разелиха Осквернителя."},{t="Цена поражения",b="Попав в плен вместе со своим лейтенантом Киритом, командир терпел жестокие пытки в Змеиных Кольцах, пока пленители вырывали души у его уцелевших бойцов. Он бежал, но умер от смертельных ран у границы болота, и дух героя остался привязан к порогу Выжженных земель. Его солдат постигла еще более мрачная участь: их лишенные души оболочки были привязаны к мистическим камням и служат бессмертными рабами Разелиху и его лейтенантам — архимагу Аллистараджу, леди Севин и Гролу Разрушителю. Пока камни, связывающие их души, не разбиты, а мучения не прекращены, его беспокойный дух не обретет покоя."}},faq={{q="Кем был Павший герой при жизни?",a="Он был опытным орком-воином, избранным возглавить разведывательный отряд в Выжженных землях, чтобы оценить демоническую угрозу. Он умер от тяжелых ран, сбежав от пыток Разелиха Осквернителя, и его дух остался у дороги, ведущей из Болота Печали.",al={"fallen hero identity","fallen hero name","who is the fallen hero","личность павшего героя","имя павшего героя","кто такой павший герой"}},{q="Почему он бродит у границы Выжженных земель?",a="Его удерживает стыд за потерю полка и провал задания. Он отказывается уйти, пока отважные искатели приключений не отправятся на юг и не уничтожат камни связывания, которые держат его солдат в вечном услужении Пылающему Легиону.",al={"why is he a ghost","fallen hero ghost","why is he here","почему он призрак","призрак павшего героя","почему он здесь"}},{q="Что случилось с приказами, которые он отправил в Каменор?",a="Разведчик, несший его срочное донесение в Каменор, попал в засаду и был убит мурлоками из болота под предводительством Болотного Вещуна. Донесение было потеряно, подкрепления так и не пришли, и герою пришлось идти в Выжженные земли одному.",al={"missing orders","what happened to his orders","swamp talker courier","пропавшие приказы","что случилось с его приказами","гонец болотного вещуна"}},{q="Что случилось с его лейтенантом Киритом?",a="Лейтенант Кирит подвергся демоническим опытам в Змеиных Кольцах. Его душа была искажена, а тело превратилось в чудовищного охотника Скверны, скрывающегося в глубине пещеры.",al={"lieutenant kirith","who is kirith","what happened to kirith","лейтенант кирит","кто такой кирит","что случилось с киритом"}},{q="Почему его солдаты неуязвимы?",a="Разелих и его лейтенанты отделили души пленных солдат от плоти. Без души их тела не могут по-настоящему умереть. Освободить их можно, лишь избив тела почти до распада: тогда ближайшие камни, связывающие души, ненадолго становятся уязвимы.",al={"invulnerable soldiers","stones of binding","servants of razelikh","неуязвимые солдаты","камни связывания","слуги разелиха"}}},fp="24,325,16.645.0,20.641.1,32.284.0,51.232.0,47.259.0,40.194.1,34.293.1"}
P.entries["npc:fandral-staghelm"] = {n="Фэндрал Олений Шлем",s="Верховный друид Фэндрал Олений Шлем возглавляет друидов Круга Кенария в Анклаве Кенария в Дарнассе. Придя к власти после того, как Малфурион Ярость Бури исчез в Изумрудном Сне, он выступил за посадку нового Мирового Древа — Тельдрассила. Гордый, резкий и неустанно честолюбивый, Фэндрал выступает за агрессивное возрождение кальдораев, что часто сталкивает его с верховной жрицей Тирандой Шелест Ветра.",h="Верховный друид Фэндрал Олений Шлем возглавляет друидов Круга Кенария в Анклаве Кенария в Дарнассе.",kw={"cenarion circle","darnassus","fandral","malfurion","rajaxx","shifting sands","staghelm","teldrassil","valstann","круг кенария","дарнасс","фэндрал","малфурион","раджакс","зыбучие пески","олений шлем","тельдрассил","валстанн"},ang={["class:Druid"]="Олений Шлем командует дарнасскими друидами, подталкивая Круг Кенария к прямой мирской власти и вступая в конфликт с традиционными учениями спящего Малфуриона Ярость Бури.",["faction:Alliance"]="Хотя Тельдрассил служит оплотом Альянса на севере Калимдора, Олений Шлем смотрит на молодые расы с плохо скрываемым презрением и терпит их присутствие лишь тогда, когда этого требует политическая необходимость.",["race:NightElf"]="Как один из главных лидеров Дарнасса, Фэндрал воплощает гордость и ярость кальдораев, ведя заселение Тельдрассила, хотя простые жители чувствуют раскол между его анклавом и Храмом Луны."},sec={{t="Создатель Тельдрассила",b="После Третьей войны и жертвы Нордрассила на горе Хиджал ночные эльфы лишились бессмертия и своего священного убежища. Пока Малфурион Ярость Бури призывал к терпению и предостерегал от тщеславия, Фэндрал настаивал на смелом создании нового Мирового Древа у берегов Калимдора. Когда Малфурион впал в кому в Изумрудном Сне, Фэндрал взял инициативу на себя и повел друидов в посадке Тельдрассила. Он видел в огромном древе памятник стойкости кальдораев и средство вернуть утраченное могущество, хотя Аспекты драконов демонстративно отказали этому неодобренному начинанию в благословении."},{t="Трагедия в Зыбучих Песках",b="За тысячелетие до Первой войны Фэндрал был полевым командиром кальдораев в Силитусе во время Войны Зыбучих Песков. Среди насекомоподобных киражей он был известен как «Кар'сис» — Рука Земли — и удерживал линию фронта вместе с любимым единственным сыном Валстанном. Воспользовавшись привязанностью Фэндрала, киражский генерал Раджакс устроил ложную атаку на Деревню Южного Ветра и захватил Валстанна, безжалостно казнив его на глазах у потрясенного верховного друида. Эта потеря сломила дух Фэндрала, привела к тяжелому отступлению и навсегда оставила в нем горькую ненависть к рою, отпечатавшуюся в его надменном облике."},{t="Соперничество и гордыня",b="В мраморных ветвях Дарнасса Фэндрал управляет делами кальдораев надменной и непреклонной рукой. В отличие от верховной жрицы Тиранды Шелест Ветра, которая отдает предпочтение духовному сохранению и осторожной дипломатии, Фэндрал считает военное расширение и решительную силу главным условием выживания своего народа."}},faq={{q="Кто такой Фэндрал Олений Шлем?",a="Фэндрал Олений Шлем — временно исполняющий обязанности верховного друида Круга Кенария в Дарнассе, возглавляющий друидов-кальдораев в отсутствие Малфуриона Ярость Бури. Известный пылким нравом и имперскими амбициями, он главный вдохновитель создания Тельдрассила.",al={"fandral lore","who is the archdruid","archdruid of darnassus","предания о фэндрале","кто такой верховный друид","верховный друид дарнасса"}},{q="Почему Фэндрал не ладит с Тирандой?",a="Фэндрал выступает за военное возрождение кальдораев, агрессивное расширение и возвращение утраченного бессмертия. Тиранда Шелест Ветра придерживается осторожного духовного руководства через Элуну. Их разные взгляды на будущее ночных эльфов после Хиджала вызывают острые политические трения в Дарнассе.",al={"fandral and tyrande","why do druids and priestesses disagree","staghelm vs whisperwind","фэндрал и тиранда","почему друиды и жрицы спорят","олений шлем и шелест ветра"}},{q="Почему Тельдрассил посадили вопреки воле Малфуриона?",a="Малфурион считал, что посадка замены Нордрассила — акт гордыни, который природа не одобрит. Когда Малфурион впал в кому, Фэндрал собрал оставшихся друидов и все равно посадил Тельдрассил, стремясь вернуть кальдораям могущество и утраченное бессмертие.",al={"who created teldrassil","why did fandral plant teldrassil","origin of teldrassil","кто создал тельдрассил","почему фэндрал посадил тельдрассил","происхождение тельдрассила"}},{q="Что случилось с сыном Фэндрала?",a="Во время Войны Зыбучих Песков в Силитусе сын Фэндрала Валстанн был заманен в засаду у Деревни Южного Ветра. Киражский генерал Раджакс захватил Валстанна и убил его на глазах у Фэндрала, оставив верховного друида в горе и навсегда озлобленным.",al={"fandral son","who was valstann","valstann staghelm","сын фэндрала","кто такой валстанн","валстанн олений шлем"}},{q="Где можно найти Фэндрала Оленьего Шлема?",a="Фэндрал находится на вершине Анклава Кенария в Дарнассе, в окружении верных друидов и дел столицы кальдораев.",al={"where is fandral","fandral location","cenarion enclave leader","где фэндрал","местонахождение фэндрала","глава анклава кенария"}}},fp="16,417,23.647.0,29.638.0,18.306.0,24.261.0,43.290.0,54.286.0,31.269.0,36.135.0"}
P.entries["npc:farmer-furlbrow"] = {n="Фермер Хмуробров",s="Фермер Теодор Хмуробров — выселенный фермер из Западного Края, выращивавший тыквы, застрявший вместе с женой Верной на дороге возле Владения Янсена. Изгнанные из дома Братством Справедливости, супруги пытаются починить сломанную повозку и бежать в Элвиннский лес.",h="Фермер Теодор Хмуробров — выселенный фермер из Западного Края, выращивавший тыквы, застрявший вместе с женой...",kw={"blanchy","defias","furlbrow","heirloom","jansen","pumpkin","theodore","verna","wagon","watch","савраска","братство справедливости","хмуробров","реликвия","янсен","тыква","теодор","верна","повозка","часы"},ang={["faction:Alliance"]="Беда Теодора Хмуроброва олицетворяет полный крах гражданской власти в Западном Крае, где верные подданные королевства вынуждены бросать дома, не имея королевских солдат для защиты."},sec={{t="Жизнь, уложенная в повозку",b="Теодор Хмуробров когда-то выращивал тыквы на севере Западного Края, но растущая волна преступности заставила его и жену Верну бросить все, что у них было. Собрав что удалось спасти, они отправились к безопасному Элвиннскому лесу, призывая соседей, таких как Фермер Сальден, последовать их примеру. Беда настигла их на дороге возле Владения Янсена: повозка сломалась, и они остались на виду у бандитов и диких зверей. Пока Верна ухаживает за их любимой лошадью Старой Савраской, Теодор следит за дорогой со все большим отчаянием, стремясь вернуть дорогие вещи — например, карманные часы, подаренные ему отцом Верны в день свадьбы, — и надеясь предупредить Сторожевой холм о приближающихся бандитах."},{t="Свидетельства захвата земель",b="Когда Хмуробров бежал с фермы, он оставил важные юридические бумаги, включая купчую на свой участок. Искатели приключений, исследующие захваченные фермы, часто находят эти брошенные документы — осязаемое доказательство того, как Братство Справедливости изгоняло честных тружеников с их земли. Гриан Камнегрив и Народное ополчение опираются на такие свидетельства, чтобы учесть масштабы мятежа воров по всей провинции."}},faq={{q="Кто такой Фермер Хмуробров?",a="Теодор Хмуробров — фермер-тыквовод с севера Западного Края, лишившийся дома. Он и его жена Верна были изгнаны с участка Братством Справедливости и сейчас застряли возле сломанной повозки близ Владения Янсена.",al={"farmer furlbrow","theodore furlbrow","who is furlbrow","фермер хмуробров","теодор хмуробров","кто такой хмуробров"}},{q="Почему Фермер Хмуробров застрял на дороге?",a="Когда он бежал из Западного Края в безопасный Элвиннский лес, его повозка сломалась. Пока он не починит ее или не найдет помощь, они с женой вынуждены ютиться у обочины со своей старой лошадью Савраской.",al={"why is his wagon broken","why is furlbrow on the road","broken cart westfall","почему сломана повозка","почему хмуробров на дороге","сломанная телега западный край"}},{q="Какую семейную реликвию потерял Фермер Хмуробров?",a="При поспешном бегстве с фермы Теодор оставил дорогие ему карманные часы, подаренные отцом Верны в день свадьбы. Он просит путников, достаточно смелых, чтобы пройти по кишащим бандитами фермам, вернуть их ему.",al={"forgotten heirloom watch","furlbrow watch","pocket watch","забытая реликвия","часы хмуроброва","карманные часы"}},{q="Есть ли у Фермера Хмуроброва родные за пределами Западного Края?",a="У Теодора есть брат, работающий конюхом далеко на севере, в Мельнице Таррен в Предгорьях Хилсбрада.",al={"furlbrow family","furlbrow brother","семья хмуроброва","брат хмуроброва"}}},fp="15,260,24.743.0,24.424.1,23.227.0,44.214.0,39.239.0,54.108.0"}
P.entries["npc:farmer-saldean"] = {n="Фермер Сальден",s="Фермер Сальден — стойкий человек-фермер, живущий на Ферме Сальдена в центральном Западном Крае вместе с женой Сальмой. В отличие от многих соседей-фермеров, которые бежали или сдались, Сальден упорно обрабатывает свои неспокойные поля, несмотря на взбесившихся жатвенных големов и растущий бандитизм.",h="Фермер Сальден — стойкий человек-фермер, живущий на Ферме Сальдена в центральном Западном Крае вместе с женой...",kw={"chicken feed","farmer saldean","harvest watcher","saldean","saldean's farm","salma","the killing fields","westfall","цыплячий корм","фермер сальден","жатвенный страж","сальден","ферма сальдена","сальма","поля смерти","западный край"},ang={["faction:Alliance"]="Сальден воплощает упрямую стойкость оставшихся в Западном Крае верноподданных, цепляющихся за землю королевства даже тогда, когда королевских солдат нигде не видно.",["profession:Cooking"]="Фермеры вроде Сальдена — рушащаяся опора продовольственного снабжения Штормграда: сбереженный им урожай позволяет держать на столах по всему королевству простой хлеб."},sec={{t="Держа плуг",b="Фермер Сальден помнит время, когда Западный Край считался самой плодородной житницей по эту сторону Тернистой долины. Те благополучные годы обратились в прах. Окруженный заросшими полями, взбесившимися механическими жатвенными стражами и хищными бандитами, Сальден отказывается отдавать свою землю. Пока другие фермеры бросали свои акры или подавались в воры, он и его жена Сальма решительно намерены собрать хоть сколько-нибудь зерна. Доведенный до практичного отчаяния, он нанимает странствующих искателей приключений разбирать взбесившихся жатвенных големов, опустошающих его поля, чтобы забрать их детали и расчистить почву для посева."},{t="Коса Западного Края",b="Упорная защита Сальденом своей фермы делает его одним из немногих уцелевших оплотов мирной жизни между Сторожевым холмом и северным мостом. Несмотря на суровые обстоятельства, он поддерживает связи с Народным ополчением и, когда его собственные неотложные беды улажены, отправляет крепких путников к Гриану Камнегриву. Сальден слишком хорошо знает, что истребление диких жатвенных машин даст его ферме лишь временную передышку, если не покончить с более широким беззаконием, душащим округу."}},faq={{q="Кто такой Фермер Сальден?",a="Сальден — опытный человек-фермер, живущий на Ферме Сальдена в Западном Крае с женой Сальмой. Он один из немногих местных фермеров, упорно отказывающихся покидать свою землю, несмотря на голод, взбесившихся жатвенных големов и растущий в регионе бандитизм.",al={"saldean","who is saldean","saldean npc","сальден","кто такой сальден","нпс сальден"}},{q="Почему у Фермера Сальдена неприятности на ферме?",a="Автоматические жатвенные големы Западного Края сломались и взбесились: они бродят по полям и нападают на всех подряд. Сальдену нужны искатели приключений, которые выследят механических стражей и добудут их детали, чтобы он мог вернуть свои пшеничные поля.",al={"why are harvest golems attacking","saldean farm problem","почему жатвенные големы нападают","проблема фермы сальдена"}},{q="Где можно найти Фермера Сальдена?",a="Он находится возле своего дома на Ферме Сальдена, которая расположена прямо у главной дороги в центральной части Западного Края, к северу от Сторожевого холма.",al={"saldean location","where is saldean","saldean farm location","где сальден","местонахождение сальдена","расположение фермы сальдена"}},{q="Поддерживает ли Сальден Народное ополчение?",a="Да. Хотя Сальден целиком занят защитой своих посевов и дома, он отправляет способных искателей приключений по дороге к Гриану Камнегриву на Сторожевой холм, чтобы они помогли Народному ополчению защищать регион.",al={"saldean gryan stoutmantle","saldean militia","сальден гриан камнегрив","сальден ополчение"}},{q="Какие особые предметы продает Сальден?",a="Сальден продает простой хлеб и является главным торговцем предметом «Цыплячий корм» — необычным зерном, которое ищут путники, надеющиеся подружиться с местной птицей, бродящей по Западному Краю.",al={"saldean vendor","special chicken feed vendor","торговец сальден","торговец цыплячьим кормом"}}},fp="14,278,16.624.0,22.511.0,22.249.0,40.242.0,34.137.0,42.207.0,36.175.0"}
P.entries["npc:farthing"] = {n="Фартинг",s="Епископ Фартинг — человек-священнослужитель, живущий в Соборе Света в Штормграде. Посетителям и прихожанам он представляется преданным слугой Света, который наставляет паству и направляет помощь осажденным поселениям по всему королевству.",h="Епископ Фартинг — человек-священнослужитель, живущий в Соборе Света в Штормграде.",kw={"benedictus","bishop farthing","cathedral of light","farthing","morbent fel","seeking wisdom","stormwind","бенедикт","епископ фартинг","собор света","фартинг","морбент скверн","поиск мудрости","штормград"},ang={["class:Priest"]="Для жрецов, посещающих Собор Света, Фартинг олицетворяет устоявшуюся иерархию и ученую мудрость человеческого духовенства Штормграда.",["faction:Alliance"]="Искатели приключений, борющиеся с расползающейся порчей в южных землях Альянса, таких как Сумеречный лес, ищут у Фартинга и его собратьев по духовенству божественного прозрения и душевной стойкости."},sec={{t="Епископ в Штормграде",b="В безмятежных мраморных залах Собора Света епископ Фартинг — одна из видных фигур, заботящихся о духовных нуждах Штормграда. Вместе с архиепископом Бенедиктом и собравшимся духовенством он дает советы путникам, помогает изучающим священные искусства и исполняет гражданские и пастырские обязанности Церкви Священного Света."},{t="Помощь Зачумленным землям",b="Хотя Фартинг остается в столице, он направляет усердных путников в более мрачные уголки королевства, остро нуждающиеся в священной помощи. Когда приходят тревожные вести о некроманте Морбенте Скверне и расползающейся нежитевой заразе, охватывающей Сумеречный лес, Фартинг выступает советником в поисках способов одолеть темное колдовство и очистить зараженное приграничье."}},faq={{q="Где можно найти епископа Фартинга?",a="Епископ Фартинг живет в Соборе Света, расположенном в центре Соборной площади в Штормграде.",al={"farthing location","where is farthing","farthing map","где фартинг","местонахождение фартинга","карта фартинга"}},{q="Какую роль Фартинг играет в Соборе?",a="Он служит рукоположенным епископом Церкви Священного Света и наставляет приходящих верующих, обучающихся священников и искателей приключений, ищущих священной мудрости от имени далеких поселений.",al={"what does farthing do","who is farthing","чем занимается фартинг","кто такой фартинг"}},{q="Как Фартинг связан с Сумеречным лесом?",a="К Фартингу обращаются искатели приключений, сражающиеся с угрозой нежити в Сумеречном лесу: он советует по темным искусствам, питающим некроманта Морбента Скверна, и направляет души к очищению.",al={"farthing duskwood","farthing morbent fel","фартинг сумеречный лес","фартинг морбент скверн"}},{q="Связан ли Фартинг с другими жителями, носящими ту же фамилию?",a="Несколько других людей в землях людей носят фамилию Фартинг, в том числе Коулман и Иветта Фартинг, хотя о прямом родстве он не говорит.",al={"coleman farthing relative","farthing family","родственник коулман фартинг","семья фартинг"}}},fp="8,272,21.374.0,24.390.0,35.119.0,46.199.0,39.187.0,60.172.0"}
P.entries["npc:feegly-the-exiled"] = {n="Фиглай Изгнанник",s="Фиглай Изгнанник — изгнанный дворф, обитающий возле раскопок дворфов в Бейл Модане на юге Степей. Некогда его хвалили как одного из лучших копателей экспедиции, но одержимость найденной реликвией заставила генерала Двукоссу прогнать его.",h="Фиглай Изгнанник — изгнанный дворф, обитающий возле раскопок дворфов в Бейл Модане на юге Степей.",kw={"bael modan","barrens","digger","excavation","exiled","feegly","tear of the moons","trogg","бейл модан","степи","копатель","раскопки","изгнанник","фиглай","слеза лун","трогг"},ang={["faction:Horde"]="Горькая обида Фиглая на раскопщиков Бейл Модана делает его неожиданным союзником для странников Орды, желающих сорвать экспедицию дворфов в Степях.",["race:Dwarf"]="Для дворфов Фиглай — печальное и жуткое предостережение: искусный копатель, чья одержимость найденной реликвией стоила ему места среди сородичей."},sec={{t="Гибель копателя",b="До изгнания Фиглай считался одним из лучших раскопщиков Бейл Модана. Слеза Лун стала первой великой находкой раскопок, и Фиглай объявил ее силу своей. Генерал Двукосса назвал самоцвет проклятым, запер его в Крепости Бейл'дан и прогнал Фиглая. Теперь он в одиночестве мрачно бродит, отчаянно желая вернуть тот самый самоцвет, что губит его: когда он наконец берет его вновь, Слеза раскалывается, и он превращается в уродливого сутулого трогга."}},faq={{q="Кто такой Фиглай Изгнанник?",a="Фиглай — дворф, изгнанный раскопщик из Бейл Модана, который жаждет заполучить реликвию, известную как Слеза Лун.",al={"who is feegly","feegly lore","feegly the exiled","кто такой фиглай","предания о фиглае","фиглай изгнанник"}},{q="Почему Фиглая изгнали из Бейл Модана?",a="Фиглай одержимо увлекся Слезой Лун — первой великой находкой Бейл Модана. Генерал Двукосса назвал самоцвет проклятым, запер его в Крепости Бейл'дан и прогнал Фиглая.",al={"why exiled","what did feegly do","feegly banishment","почему изгнан","что сделал фиглай","изгнание фиглая"}},{q="Почему Фиглай готов говорить с искателями приключений Орды?",a="Преданный и изгнанный собратьями-дворфами, Фиглай не питает верности экспедиции Альянса. Он настолько отчаялся, что ищет помощи у путников Орды, чтобы вернуть желанную реликвию.",al={"why is feegly friendly to horde","feegly horde friendly","почему фиглай дружелюбен к орде","фиглай друг орды"}},{q="Что такое Слеза Лун?",a="Слеза Лун — самоцвет, обнаруженный раскопщиками в Бейл Модане, их первая великая находка там. Фиглай утверждает, что он дал ему силу, но генерал Двукосса счел его проклятым и запер в Крепости Бейл'дан.",al={"tear of the moons","feegly gem","feegly artifact","слеза лун","самоцвет фиглая","артефакт фиглая"}}},fp="17,252,15.460.1,25.113.0,38.184.0,51.189.0,30.214.0"}
P.entries["npc:feero-ironhand"] = {n="Фиро Железнорук",s="Фиро Железнорук — человек-боец, расквартированный на Заставе Мейстры в западной части Ясеневого леса. Неся стражу на границе Темных берегов и леса, он тесно сотрудничает с Делгреном Очистителем в борьбе со зловещим Культом Темной Нити.",h="Фиро Железнорук — человек-боец, расквартированный на Заставе Мейстры в западной части Ясеневого леса.",kw={"ashenvale","auberdine","cult of the dark strand","delgren the purifier","feero ironhand","maestra's post","ясеневый лес","аубердин","культ темной нити","делгрен очиститель","фиро железнорук","застава мейстры"},ang={["faction:Alliance"]="Фиро служит важной опорой для странников Альянса, идущих с Темных берегов в опасную спорную глушь Ясеневого леса.",["race:Human"]="Видеть собрата-человека на страже в древних эльфийских чащах Ясеневого леса — отрадный знак широкого сотрудничества Альянса."},sec={{t="Бастион на Заставе Мейстры",b="Застава Мейстры, расположенная на дороге, ведущей на юг от Темных берегов в Ясеневый лес, служит важным наблюдательным пунктом для путников и защитников Альянса. Фиро Железнорук действует с этой заставы, поддерживая связь и торговые пути с Аубердином и неусыпно следя за окрестными лесами. Вместе с Делгреном Очистителем Фиро направляет усилия против злобного Культа Темной Нити, не позволяя культистам и лесным хищникам перерезать путь между линиями снабжения Дарнасса и передовыми рубежами Ясеневого леса."}},faq={{q="Кто такой Фиро Железнорук?",a="Фиро Железнорук — человек-воин Альянса, расквартированный на Заставе Мейстры в западной части Ясеневого леса. Он помогает путникам, идущим между Темными берегами и Ясеневым лесом, и координирует снабжение, связанное с Аубердином.",al={"feero ironhand","who is feero","feero npc","фиро железнорук","кто такой фиро","фиро нпс"}},{q="Какова задача Фиро на Заставе Мейстры?",a="Фиро помогает удерживать форпост против местных угроз, поддерживая Делгрена Очистителя в борьбе с Культом Темной Нити и сохраняя важные курьерские и снабженческие пути к Темным берегам.",al={"why is feero here","feero role","maestras post human","зачем фиро здесь","роль фиро","человек на заставе мейстры"}},{q="Что такое Культ Темной Нити?",a="Культ Темной Нити — зловещий заговор, действующий на севере Ясеневого леса и балующийся темной магией и мерзкими ритуалами. Силы Альянса на Заставе Мейстры активно стараются сорвать и разрушить его замыслы.",al={"dark strand cult","cult of dark strand","dark strand","культ темной нити","темная нить","культисты темной нити"}},{q="Связан ли Фиро с Серебряным Рассветом?",a="Да. Фиро связан с Серебряным Рассветом и действует в тесном согласии с Делгреном Очистителем, паладином Серебряного Рассвета, борющимся с темными силами в лесу.",al={"feero argent dawn","is feero argent dawn","фиро серебряный рассвет","состоит ли фиро в серебряном рассвете"}}},fp="14,254,27.562.0,22.199.0,42.193.0,36.216.0,47.160.0"}
P.entries["npc:fel-zerul"] = {n="Фел'зерул",s="Фел'зерул — орк-чернокнижник, расквартированный в Каменоре в мутных глубинах Болота Печали. По прямому приказу вождя Тралла он изучает зловещее присутствие в затонувшем Храме Атал'Хаккара.",h="Фел'зерул — орк-чернокнижник, расквартированный в Каменоре в мутных глубинах Болота Печали.",kw={"atal'hakkar","fel'zerul","felzerul","stonard","swamp of sorrows","thrall","warlock","атал'хаккар","фел'зерул","фелзерул","каменор","болото печали","тралл","чернокнижник"},ang={["class:Warlock"]="Фел'зерул — официальное поручение чернокнижнику от Тралла, показывающее, что новая Орда порой полагается на адептов темных искусств в борьбе с неясными, эзотерическими угрозами.",["faction:Horde"]="Расквартированный в Каменоре, Фел'зерул служит передовым разведчиком раннего предупреждения: он следит, чтобы темная магия, гниющая в болоте, не застала врасплох оплот Орды в этом регионе."},sec={{t="Взгляд на Затонувший храм",b="Хотя Орда Тралла в целом относится к темным искусствам с подозрением, Вождь признает, что понять зловещие силы могут лишь те, кто их изучает. Фел'зерула направили в Каменор именно для того, чтобы разобраться в порче вокруг Озера Слез и погруженного в воду Храма Атал'Хаккара. Посылая искателей приключений за артефактами и на поиски изгнанных троллей Атал'ай, чернокнижник пытается выяснить, какое зло пробуждается под мутными водами, пока оно не угрожает южному форпосту Орды."}},faq={{q="Кто такой Фел'зерул?",a="Фел'зерул — орк-чернокнижник, живущий в Каменоре, оплоте Орды на Болоте Печали. Он служит следователем, изучающим темные ритуалы в соседнем Храме Атал'Хаккара.",al={"felzerul","who is fel'zerul","stonard warlock","фелзерул","кто такой фел'зерул","чернокнижник каменора"}},{q="Почему Тралл отправил чернокнижника в Каменор?",a="Вождь Тралл направил Фел'зерула, потому что для борьбы с древними проклятиями и кровавыми ритуалами нужен опыт в темном колдовстве. Задача Фел'зерула — следить за тревожными событиями вокруг затонувшего храма и защищать интересы Орды на болоте.",al={"thrall felzerul","why is felzerul here","felzerul mission","тралл фелзерул","зачем здесь фелзерул","задание фелзерула"}},{q="Что исследует Фел'зерул?",a="Фел'зерул исследует троллей Атал'ай и их нечестивые обряды в Храме Атал'Хаккара у Озера Слез. Он привлекает разведчиков и искателей приключений, чтобы поднять со дна артефакты и разыскать изгнанных жрецов, которые могут знать важные предания.",al={"felzerul quest lore","what does felzerul want","pool of tears investigation","предания фелзерула","чего хочет фелзерул","расследование озера слез"}}},fp="9,228,25.509.0,17.203.0,41.259.0,32.240.0"}
P.entries["npc:felgur-twocuts"] = {n="Фелгур Бью-Двоих",s="Фелгур Бью-Двоих — прямолинейный орк-разведчик на Заставе Скитающихся Духов в Пустошах. Он координирует действия Орды против местных кланов кентавров.",h="Фелгур Бью-Двоих — прямолинейный орк-разведчик на Заставе Скитающихся Духов в Пустошах.",kw={"centaur bounty","desolace","felgur twocuts","ghost walker post","horde","kolkar","orc","награда за кентавров","пустоши","фелгур бью-двоих","застава скитающихся духов","орда","колкар","орк"},ang={["faction:Horde"]="Фелгур служит важным связным по операциям на Заставе Скитающихся Духов и помогает Орде отбивать натиск агрессивных племен кентавров в Пустошах.",["race:Orc"]="Как и подобает практичным оркам в опасных пограничных землях, Фелгур ценит силу, скорость и быстрый результат выше пустых разговоров."},sec={{t="Грубоватый разведчик заставы",b="Стоя на страже посреди унылых просторов Заставы Скитающихся Духов в центре Пустошей, Фелгур Бью-Двоих не склонен к любезностям. Как передовой разведчик Орды, он оценивает угрозы, с которыми сталкиваются путники и поселенцы, идущие на запад через горы, особенно со стороны местных кентавров Колкар."},{t="Война с кентаврами",b="Фелгур направляет бойцов Орды истреблять местных вождей кентавров и собирать награды за головы воинственных племен, грозящих захлестнуть край. К нему обращаются все, кто хочет закрепить позиции Орды в Пустошах."}},faq={{q="Кто такой Фелгур Бью-Двоих?",a="Фелгур Бью-Двоих — орк-разведчик, выдающий задания, на Заставе Скитающихся Духов, передовом лагере Орды в Пустошах.",al={"felgur twocuts who","who is felgur","фелгур бью-двоих кто","кто такой фелгур"}},{q="Где найти Фелгура Бью-Двоих?",a="Он находится на Заставе Скитающихся Духов, к северу от центральной дороги, проходящей через Пустоши.",al={"felgur twocuts location","where is felgur","where is felgur twocuts","фелгур бью-двоих местонахождение","где фелгур","где фелгур бью-двоих"}},{q="Какие задания дает Фелгур Бью-Двоих?",a="Фелгур нанимает искателей приключений из Орды, чтобы они нападали на местных кентавров Колкар, выследили вождя Дез'хепа и собирали награды за враждебных кентавров.",al={"felgur quests","what does felgur want","задания фелгура","чего хочет фелгур"}},{q="Почему Фелгур так резок с посетителями?",a="Пустоши — опасная и суровая пустошь, окруженная враждебными кланами кентавров. Стоя на уединенной заставе, Фелгур не любит пустых разговоров и сосредоточен только на выживании и воинском долге.",al={"why is felgur rude","make it quick felgur","почему фелгур грубит","фелгур короче"}}},fp="14,144,21.297.0,18.233.0,22.122.0,32.92.0,36.138.0,36.213.0"}
P.entries["npc:felix-whindlebolt"] = {n="Феликс Ремонтуар",s="Феликс Ремонтуар — гном-беженец, нашедший приют в Старой Наковальне в Холодной долине. Спеша спастись от радиации, затопившей Гномреган, он потерял свои вещи, а враждебные тролли Мерзлогривы унесли их.",h="Феликс Ремонтуар — гном-беженец, нашедший приют в Старой Наковальне в Холодной долине.",kw={"anvilmar","coldridge valley","felix whindlebolt","frostmane","gnomeregan","refugee","whitebeard's encampment","старая наковальня","холодная долина","феликс ремонтуар","мерзлогрив","гномреган","беженец","лагерь белобородого"},ang={["race:Dwarf"]="Местные тролли Мерзлогривы стали смелее по всей Холодной долине и нападают на беззащитных гномов-беженцев, бродящих возле Старой Наковальни.",["race:Gnome"]="Феликс олицетворяет трудную судьбу ваших изгнанных сородичей, вынужденных страдать от безжалостного холода Дун Морога после катастрофы в Гномрегане."},sec={{t="Лишившийся дома путник",b="После трагического падения Гномрегана тысячи гномов бродили по холодным краям Дун Морога в поисках безопасности. Феликс Ремонтуар бежал из зараженного радиацией города так поспешно, что потерял все свои вещи и инструменты. Что хуже, ледяные тролли Мерзлогривы утащили его сундук, ящик и ведро с болтами в свои лагеря к юго-западу от Старой Наковальни, и он остался без средств, полагаясь на сострадательных странников, которые вернут украденное."}},faq={{q="Кто такой Феликс Ремонтуар?",a="Феликс Ремонтуар — гном-беженец, нашедший приют в Старой Наковальне в Холодной долине. Он потерял вещи, спасаясь из Гномрегана, и местные тролли Мерзлогривы забрали их.",al={"who is felix","felix whindlebolt lore","gnome at whitebeard camp","кто такой феликс","феликс ремонтуар предание","гном в лагере белобородого"}},{q="Куда пытался попасть Феликс?",a="Феликс бежал от радиации, захлестнувшей Гномреган после того, как попытка гномов изгнать троггов обернулась катастрофой. Он оказался в Старой Наковальне, дворфийской заставе в Холодной долине, хотя считает это место плохо подходящим для гнома.",al={"where was felix heading","felix destination","why is felix in coldridge valley","куда шел феликс","цель феликса","почему феликс в холодной долине"}},{q="Что случилось с его вещами?",a="Спеша бежать из Гномрегана, Феликс потерял сундук, ящик и ведро с болтами. Ледяные тролли Мерзлогривы унесли их в свои лагеря к юго-западу от Старой Наковальни, и он остался без припасов.",al={"who stole felix stuff","felix stolen gear","frostmane trolls felix","кто украл вещи феликса","украденные вещи феликса","тролли мерзлогривы феликс"}},{q="Что Феликс продает искателям приключений?",a="Ничего. Феликс не торговец: он потерял все вещи, спасаясь из Гномрегана, и в Старой Наковальне может предложить лишь благодарность тому, кто вернет его сундук, ящик и ведро с болтами.",al={"felix vendor items","what does felix offer","felix inventory","товары феликса","что предлагает феликс","инвентарь феликса"}}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:fenrus-the-devourer"] = {n="Фенрус Пожиратель",s="Фенрус Пожиратель — огромный ворг, бродящий по верхним покоям Крепости Темного Клыка. Эта ненасытная тварь, раздутая от неестественной магии, служит личным питомцем и стражем верховного мага Аругала. Всякий, кто осмелится проникнуть в личный кабинет мага, столкнется с этим диким чудовищем и его хозяином, который присматривает за ним.",h="Фенрус Пожиратель — огромный ворг, бродящий по верхним покоям Крепости Темного Клыка.",kw={"arugal","fenrus","fenrus the devourer","shadowfang keep","silverpine","worg","аругал","фенрус","фенрус пожиратель","крепость темного клыка","серебряный бор","варг"},ang={["class:Hunter"]="Не тратьте время на попытки приручить Фенруса. Разум зверя безвозвратно искажен темными искусствами Темного Клыка, и дикая природа над ним не властна.",["class:Mage"]="Фенрус — мрачное напоминание о том, как низко пал верховный маг Аругал, используя тайные искусства, чтобы превращать диких зверей в уродливых домашних стражей.",["class:Warlock"]="То, что верховный маг Аругал способен призывать демонов Бездны на помощь своему псу, показывает, как глубоко бывший маг Даларана погрузился в теневые запретные призывы."},sec={{t="Зверь в кабинете хозяина",b="В глубине Крепости Темного Клыка, у личных покоев верховного мага Аругала, обитает чудовищный варг Фенрус Пожиратель. В отличие от воргенов, бродящих по стенам, Фенрус — настоящий варг, раздувшийся до гигантских размеров. Бродя среди полок, свитков и тайных приспособлений личного кабинета Аругала, зверь служит и питомцем, и свирепым стражем периметра против любого, кто ищет голову безумного мага."},{t="Извращенная мощь",b="Неестественная громада Фенруса говорит о том, что он подвергся темной магии, пропитавшей крепость после гибели барона Сребролена. Верховный маг Аругал или его выпущенные воргены явно исказили существо тайными или теневыми опытами, превратив местного хищника в ненасытного исполина. Фенрус так дик и скован магией, что ни один охотник не может подчинить или приручить его разум."},{t="Бдительное око Аругала",b="Потревожить Фенруса — верная смерть для неосторожных. Заметив чужака, зверь издает оглушительный вой, разносящийся по всей крепости и привлекающий внимание самого Аругала. Не оставляя питомца без защиты, маг направляет свою темную волю в покои и призывает демонов Бездны, чтобы они помогли Фенрусу одолеть и сожрать захватчиков."}},faq={{q="Что за существо Фенрус?",a="Фенрус — исключительно крупный варг, природный волкоподобный хищник, обитающий в Лордероне, а не двуногий воргена. Его неестественные размеры и свирепость — прямой результат долгого воздействия темной магии, практикуемой в Крепости Темного Клыка.",al={"is fenrus a worgen","fenrus creature type","fenrus wolf","фенрус воргена","тип существа фенрус","фенрус волк"}},{q="Где найти Фенруса?",a="Фенрус бродит по кабинетам высоко в Крепости Темного Клыка в Серебряном бору. Его логово расположено прямо на подходе к внутреннему оплоту верховного мага Аругала.",al={"where is fenrus","fenrus location","fenrus room","где фенрус","местонахождение фенруса","комната фенруса"}},{q="Могут ли охотники приручить Фенруса?",a="Нет. Хотя по классификации Фенрус — обычный зверь, приручить его нельзя. Его разум полностью сломлен, дик и привязан к темной воле верховного мага Аругала.",al={"can i tame fenrus","is fenrus tameable","taming fenrus","можно ли приручить фенруса","приручается ли фенрус","приручение фенруса"}},{q="Почему Аругал призывает демонов, когда нападают на Фенруса?",a="Аругал считает Фенруса любимым питомцем и последним рубежом обороны перед своим убежищем. Когда Фенрус ревет, вступая в бой, Аругал вмешивается лично и призывает в покои демонов Бездны, чтобы одолеть тех, кто угрожает его зверю.",al={"arugal voidwalkers","why does arugal help fenrus","fenrus voidwalker add","демоны бездны аругала","почему аругал помогает фенрусу","демон бездны у фенруса"}},{q="Почему Фенрус намного крупнее обычных варгов?",a="Считается, что огромные размеры Фенруса — следствие темных магических опытов верховного мага Аругала или магических последствий нашествия воргенов, захвативших крепость.",al={"why is fenrus huge","fenrus size lore","giant worg","почему фенрус огромный","размер фенруса","гигантский варг"}},{q="Что происходит в подземелье, когда Фенрус вступает в бой?",a="Вступая в бой, Фенрус издает громовой рев, слышный всем в любой точке Крепости Темного Клыка, и оповещает о схватке у дверей Аругала.",al={"fenrus roar","fenrus howl across dungeon","loud roar sfk","рев фенруса","вой фенруса по подземелью","громкий рев кти"}}},fp="19,322,29.436.0,15.369.0,21.397.1,32.260.0,26.167.0,33.157.0,54.234.0,47.174.0,55.191.0"}
P.entries["npc:field-marshal-snowfall"] = {n="Фельдмаршал Снегопад",s="Фельдмаршал Снегопад — дворфийский военный офицер в Военном квартале Стальгорна, координирующий военные усилия Альянса против растущей угрозы силитидов. Перед лицом древнего зла, пробуждающегося в южных песках Силитуса, он руководит огромной снабженческой кампанией по оснащению армий союзников. Снегопад ведет учет пожертвованного сырья и награждает тех, кто помогает королевству готовиться к войне.",h="Фельдмаршал Снегопад — дворфийский военный офицер в Военном квартале Стальгорна, координирующий военные...",kw={"ahn'qiraj","field marshal snowfall","ironforge","military ward","signets","silithus","snowfall","war effort","ан'кираж","фельдмаршал снегопад","стальгорн","военный квартал","знаки","силитус","снегопад","военные усилия"},ang={["faction:Alliance"]="Снегопад воплощает единую промышленную и военную волю Альянса и призывает все расы от Штормграда до Дарнасса опустошить свои склады и подготовиться к грядущей битве.",["race:Dwarf"]="Находясь в воинском квартале Великой кузни, Снегопад с гордостью говорит о защите творений Титанов от древней, глубоко укоренившейся порочности."},sec={{t="Интендант усилий против Ан'Киража",b="Неся дозор в Военном квартале Стальгорна, Фельдмаршал Снегопад выступает главным координатором мобилизации Альянса против Ан'Киража. Он видит в назревающем конфликте не просто пограничную стычку, а решающую борьбу с древним врагом, враждебным всем созданиям Титанов. Снегопад ведает огромными запасами — миллионами бинтов, тоннами слитков, кожи, трав и пайков, собранных искателями приключений, — чтобы силы Альянса были вооружены, защищены и накормлены к началу похода на юг, в Силитус."},{t="Дорога в Силитус",b="Мобилизация целой фракции требует согласованности действий кузнецов, собирателей, поваров и солдат на всех территориях Альянса. Фельдмаршал Снегопад следит за каждым этапом этой огромной операции: принимает знаки отличия и выдает добровольцам запросы на снабжение. Когда необходимые военные припасы будут полностью собраны обеими фракциями, запасы упакуют и отвезут на юг, в Крепость Кенария, чтобы подготовить великое наступление на насекомых и Древнего бога, затаившегося за Стеной Скарабея."}},faq={{q="Кто такой Фельдмаршал Снегопад?",a="Фельдмаршал Снегопад — высокопоставленный дворфийский командир в Военном квартале Стальгорна. Ему поручено руководить обширным сбором припасов Альянса и вести его учет в преддверии войны против киражей в Силитусе.",al={"snowfall role","who is snowfall","field marshal snowfall lore","роль снегопада","кто такой снегопад","фельдмаршал снегопад предание"}},{q="Почему Альянс собирает так много припасов?",a="Древняя сила угрожает Калимдору из-за врат Ан'Киража. Чтобы успешно провести кампанию по суровым пустыням Силитуса, Альянс должен накопить огромные запасы доспехов, металлических слитков, бинтов, пищи и трав до выступления армий.",al={"why donate cloth","war effort purpose","why war supplies","зачем сдавать ткань","цель военных усилий","зачем военные припасы"}},{q="Куда идут собранные материалы, когда сбор завершен?",a="Когда Альянс и Орда выполняют общие нормы сбора, караваны и грузовые корабли доставляют огромные запасы в Крепость Кенария в Силитусе, где объединенные силы разворачивают передовой плацдарм.",al={"where do supplies go","what happens to the supplies","куда идут припасы","что станет с припасами"}},{q="Для чего нужны знаки военных припасов?",a="Знаки выдают тем, кто жертвует запрошенное оружие и материалы на нужды войны. Фельдмаршал Снегопад принимает эти знаки партиями и награждает усердных граждан Альянса ящиками с припасами и снаряжением за службу.",al={"signet turn ins","what are signets for","сдача знаков","для чего знаки"}}},fp="22,407,37.558.0,20.505.0,30.238.0,48.269.0,49.224.0,47.239.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="Фельдмаршал Стоунбридж",s="Фельдмаршал Стоунбридж — высокопоставленный офицер Альянса, расквартированный возле входа в Штормград. Она несет службу у Врат Штормграда на Аллее Героев, руководит обороной города вместе с генералом Маркусом Джонатаном и служит авторитетным лицом в вопросах великих военных побед.",h="Фельдмаршал Стоунбридж — высокопоставленный офицер Альянса, расквартированный возле входа в Штормград.",kw={"field marshal","gates","lord of blackrock","marcus jonathan","nefarian","stonebridge","stormwind","valley of heroes","фельдмаршал","врата","владыка черной горы","маркус джонатан","нефариан","стоунбридж","штормград","аллея героев"},ang={["class:Warrior"]="Как один из высших военачальников у городских врат, фельдмаршал Стоунбридж вызывает уважение у солдат передовой, стремящихся достичь высокого военного положения в Альянсе.",["faction:Alliance"]="Стоя плечом к плечу с генералом Маркусом Джонатаном, Стоунбридж воплощает неизменную бдительность армии Альянса, охраняющей Штормград от внешнего вторжения."},sec={{t="Бастион у врат",b="Фельдмаршал Стоунбридж стоит на страже сразу за высоким входом на Аллею Героев, под восточной аркой возле главных врат. Ее высокое звание в войсках Великого Альянса ставит ее в число высших представителей стратегического командования Штормграда, и она действует в тесном взаимодействии с генералом Маркусом Джонатаном. С этого заметного места она наблюдает за потоком защитников, путников и возвращающихся героев, входящих в столицу, и готова организовать гарнизон, если угроза прорвет внешний периметр."},{t="Хранительница трофеев",b="Помимо церемониальных и оборонительных обязанностей у городских врат, фельдмаршал Стоунбридж принимает важные донесения и трофеи из походов против сильнейших врагов, угрожающих королевству. Высокопоставленные командиры полагаются на таких офицеров, как Стоунбридж, чтобы проверять важнейшие разведданные и отмечать великие победы, одержанные в бою, включая гибель полководцев и чудовищ, гнездившихся в скалах Черной горы."}},faq={{q="Где находится фельдмаршал Стоунбридж?",a="Она стоит под аркой в северо-восточной части Аллеи Героев в Штормграде, сразу справа от генерала Маркуса Джонатана, если войти через городские врата.",al={"stonebridge location","where is field marshal stonebridge","find stonebridge","где стоунбридж","где находится фельдмаршал стоунбридж","найти стоунбридж"}},{q="Какова роль фельдмаршала Стоунбридж в Штормграде?",a="Она высокопоставленный офицер армии Альянса: помогает генералу Маркусу Джонатану в обороне главных врат Штормграда и принимает важные военные донесения и трофеи великих побед, доставленные героями Альянса.",al={"what does stonebridge do","stonebridge purpose","who is field marshal stonebridge","чем занимается стоунбридж","роль стоунбридж","кто такая фельдмаршал стоунбридж"}},{q="Какое звание у фельдмаршала в Альянсе?",a="Фельдмаршал — одно из высших офицерских званий в командной структуре войск Великого Альянса, сразу ниже великого маршала. Офицеры этого звания руководят крупными тактическими развертываниями, секторами обороны городов и стратегическими гарнизонами.",al={"alliance field marshal rank","how high rank is stonebridge","звание фельдмаршала альянса","насколько высокое звание у стоунбридж"}},{q="В каких важных заданиях участвует фельдмаршал Стоунбридж?",a="Она офицер, принимающий донесение и трофей за задание «Владыка Черной горы», подтверждая гибель Нефариана, когда искатели приключений из Альянса приносят голову дракона к вратам Штормграда.",al={"stonebridge quests","the lord of blackrock quest ender","задания стоунбридж","владыка черной горы задание"}}},fp="25,285,22.552.0,18.432.0,43.180.0,54.251.0,45.239.0,52.195.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="Первый помощник Фитсиммонс",s="Первый помощник Фитсиммонс — оборванный, дурно пахнущий моряк, который целыми днями пьет у таверны «Большая вода» в Гавани Менетилов. Когда-то он был первым помощником на «Владычице волн» из Третьей флотилии Кул Тираса и остался единственным известным живым свидетелем гибели флотилии во время Второй войны. Измученный трагедией, он ищет добровольцев, готовых встретиться с неупокоенными духами его утонувших товарищей.",h="Первый помощник Фитсиммонс — оборванный, дурно пахнущий моряк, который целыми днями пьет у таверны «Большая...",kw={"deepwater tavern","eye of paleth","first mate fitzsimmons","fitzsimmons","kul tiras","lost fleet","menethil harbor","third fleet","wave mistress","таверна большая вода","око палета","первый помощник фитсиммонс","фитсиммонс","кул тирас","погибший флот","гавань менетилов","третья флотилия","владычица волн"},ang={["faction:Alliance"]="Фитсиммонс представляет трагическую главу морской истории Альянса и напоминает героям о страшных потерях в борьбе с армадой порабощенных драконов Орды.",["race:Human"]="Как ветеран Кул Тираса, Фитсиммонс тесно связан культурой с морским королевством людей, которое многим пожертвовало ради защиты Лордерона во время Второй войны."},sec={{t="Сломленный моряк",b="Первый помощник Фитсиммонс валяется у таверны «Большая вода» в сыром соленом воздухе Гавани Менетилов, и его легко не заметить или вовсе обойти стороной из-за исходящего от него зловония. Большинству посетителей он кажется очередным сломленным старым морским волком, топящим воспоминания в вине. Но те, кто готов присесть и выслушать, узнают жуткие истории о гордой флотилии, павшей от огня и когтей."},{t="Гибель Третьей флотилии",b="Во время Второй войны Фитсиммонс служил первым помощником на «Владычице волн» в составе Третьей флотилии Кул Тираса, посланной сражаться с Ордой. У берегов Болотины флотилию подстерегли и сожгли порабощенные красные драконы, на которых летали орки клана Драконьей Пасти. Корабли были разбиты и потоплены, и только Фитсиммонсу удалось живым выбраться на берег."},{t="Неснятое проклятие",b="Спасение от драконьего огня не принесло Фитсиммонсу покоя. Остовы кораблей, теперь известные как Погибший Флот, населены его бывшими товарищами по команде, которые восстали проклятой нежитью и не могут упокоиться в своих водных могилах. Движимый виной и ужасом, Фитсиммонс нанимает путников, чтобы они уничтожили моряков-нежить и добыли древние реликвии, способные снять зло, связывающее их души."}},faq={{q="Кто такой первый помощник Фитсиммонс?",a="Это старый култирасский моряк, бывший первый помощник «Владычицы волн». Он пережил катастрофическую гибель Третьей флотилии Кул Тираса во Второй войне, а теперь пропивает свои дни у таверны «Большая вода» в Гавани Менетилов.",al={"fitzsimmons lore","who is fitzsimmons","first mate fitzsimmons","предыстория фитсиммонса","кто такой фитсиммонс","первый помощник фитсиммонс"}},{q="Что случилось с его кораблем?",a="«Владычицу волн» и остальную Третью флотилию во Второй войне подстерегли порабощенные красные драконы, на которых летали воины клана Драконьей Пасти. Корабли сгорели и разбились о рифы у берега Болотины.",al={"what happened to wave mistress","third fleet destruction","why did his ship sink","что случилось с владычицей волн","гибель третьей флотилии","почему затонул его корабль"}},{q="Где находится Погибший Флот?",a="Разбитые корпуса кораблей лежат под водой вдоль скалистого берега к северу от Гавани Менетилов в Болотине, и теперь их охраняют мурлоки и неупокоенные духи утонувших моряков.",al={"lost fleet location","where are the sunken ships","fitzsimmons ship location","где погибший флот","где затонувшие корабли","где корабль фитсиммонса"}},{q="Почему он хочет, чтобы искатели приключений сразились с его бывшей командой?",a="Утонувшие моряки Третьей флотилии восстали проклятой, измученной нежитью, вместо того чтобы уйти в мир иной. Фитсиммонс ищет храбрых путников, чтобы упокоить их и забрать артефакты, удерживающие их души в оковах.",al={"cursed crew quest lore","why kill his crew","проклятая команда задание","зачем убивать его команду"}},{q="Что такое Око Палета?",a="Это древний могущественный артефакт, находившийся на борту кораблей Третьей флотилии. Его темная сила связана с проклятием, поразившим затонувших моряков, поэтому его возвращение необходимо, чтобы упокоить погибшую флотилию.",al={"eye of paleth","paleth relic","око палета","реликвия палета"}},{q="Почему от Фитсиммонса так плохо пахнет?",a="Потеряв все с гибелью флотилии, Фитсиммонс годами живет в пьяной запущенности у таверны «Большая вода», носит пропитанные морской водой лохмотья и редко моется.",al={"why does fitzsimmons smell","fitzsimmons stench","почему фитсиммонс воняет","вонь фитсиммонса"}}},fp="22,397,15.367.0,27.366.0,19.390.1,30.232.0,26.212.0,32.182.0,51.206.0,26.197.0,34.173.0"}
P.entries["npc:fizzle-brassbolts"] = {n="Пшикс Медноштиф",s="Пшикс Медноштиф — известный гномий инженер, обосновавшийся на выжженной солнцем соляной равнине Виражей на Миражах в Тысяче Игл. Вместе со своим соперником гоблином Поззиком Пшикс основал трассу, чтобы противопоставить точную гномью инженерию безрассудной гоблинской изобретательности в скоростных гонках на ракетных машинах. Он постоянно ищет детали, топливо и странные пустынные реагенты для своей гоночной команды.",h="Пшикс Медноштиф — известный гномий инженер, обосновавшийся на выжженной солнцем соляной равнине Виражей на...",kw={"brassbolts","fizzle","mega","mirage raceway","pozzik","rocket car","shimmering flats","thousand needles","медноштиф","пшикс","гима","виражи на миражах","поззик","ракетная машина","мерцающая равнина","тысяча игл"},ang={["faction:Alliance"]="Хотя Пшикс работает в нейтральной скоростной зоне, он дружелюбно встречает странников Альянса, идущих на юг к Танарису, и помогает им с механикой.",["profession:Engineering"]="Коллеги-инженеры оценят преданность Пшикса оптимизации ракетных двигателей и разработке передовых машин в суровых условиях пустыни.",["race:Gnome"]="Пшикс несет честь всего Гномрегана в пустыню, твердо решив доказать, что гномья точность превосходит гоблинскую безрассудность."},sec={{t="Дело принципа и поршней",b="В мерцающем зное Мерцающей равнины политические союзы и древние обиды уступают реву моторов. Пшикс Медноштиф прибыл сюда с одной целью: раз и навсегда доказать, что гномье мастерство намного превосходит грубую гоблинскую возню. Вместе со своим гоблинским двойником Поззиком он помог создать Виражи на Миражах, привлекая гоночные машины, команды механиков и зрителей в безлюдную котловину."},{t="Возня на равнине",b="Гонки по сухим соляным руслам на головокружительной скорости требуют постоянной импровизации. Будучи ярым членом Гильдии инженеров-механиков Азерота (ГИМА), Пшикс не боится нетрадиционных опытов. Испытывает ли он взрывоопасные смеси из местного яда существ или нанимает путников за запасными механическими деталями, Пшикс полон решимости, чтобы колеса его гонщика вертелись быстрее любого взрывного гоблинского устройства."}},faq={{q="Кто такой Пшикс Медноштиф?",a="Пшикс Медноштиф — мастер-инженер из гномов и главный организатор гномьей гоночной команды на Виражах на Миражах в Тысяче Игл.",al={"who is fizzle","fizzle brassbolts lore","gnome at raceway","кто такой пшикс","пшикс медноштиф предыстория","гном на трассе"}},{q="Почему Пшикс пришел на Мерцающую равнину?",a="Он пришел разрешить технический спор с гоблином-инженером Поззиком о том, чья раса превосходит в инженерии. Вместе они создали Виражи на Миражах, чтобы лицом к лицу испытать свои ракетные машины на плоской соляной равнине.",al={"why is fizzle here","raceway purpose","why raceway built","зачем пшикс здесь","назначение трассы","зачем построили трассу"}},{q="Что такое ГИМА?",a="ГИМА — это Гильдия инженеров-механиков Азерота. Пшикс — ее преданный член, воплощающий приверженность гильдии тщательной разработке и техническому совершенствованию.",al={"fizzle guild","mechanical engineers guild","what is mega","гильдия пшикса","гильдия инженеров-механиков","что такое гима"}},{q="Зачем Пшиксу яд существ для гоночных машин?",a="Пшикс постоянно экспериментирует с местными реагентами, создавая мощные жидкости для двигателей, присадки и ускорители, которые дадут его ракетным машинам преимущество над машинами Поззика.",al={"salt flat venom quest","venom racing fuel","why does he need venom","задание яд соляной равнины","яд гоночное топливо","зачем ему яд"}},{q="Сражается ли Пшикс с гоблинами?",a="Не оружием. Хотя между ними есть глубокая профессиональная зависть, Пшикс и Поззик поддерживают шаткое нейтральное перемирие на трассе, чтобы сосредоточиться исключительно на скоростных состязаниях.",al={"is fizzle hostile to goblins","fizzle pozzik fight","враждебен ли пшикс к гоблинам","пшикс поззик драка"}},{q="Кто такой пилот Длиннобород?",a="Пилот Длиннобород — дворфийский летчик и личный друг семьи Медноштифов, разделяющий их любовь к опасным механизмам и пустынным трассам.",al={"pilot longbeard connection","fizzle pilot friend","связь пилота длинноборода","друг пшикса пилот"}}},fp="17,397,33.444.0,22.443.0,25.146.0,44.222.0,13.172.0,50.179.0,38.181.0,23.146.0"}
P.entries["npc:fleet-master-seahorn"] = {n="Командир флота Морской Рог",s="Командир флота Морской Рог — опытный таурен-мореход, морской командир Налетчиков Черноводья в Пиратской бухте. Он расположен на верхнем балконе Таверны «Соленый моряк» рядом с бароном Ревилгазом и отвечает за морскую оборону гоблинского порта. Его главная задача — защищать гавань от нависшей угрозы со стороны заклятых врагов, Пиратов Кровавого Паруса.",h="Командир флота Морской Рог — опытный таурен-мореход, морской командир Налетчиков Черноводья в Пиратской бухте.",kw={"blackwater raiders","bloodsail","booty bay","faldir's cove","firallon","fleet master seahorn","revilgaz","salty sailor tavern","seahorn","wild shore","налетчики черноводья","кровавый парус","пиратская бухта","бухта фальдира","фираллон","командир флота морской рог","ревилгаз","таверна соленый моряк","морской рог","пустынный берег"},ang={["class:Rogue"]="Разбойники в Пиратской бухте видят в Морском Роге центр прибрежного шпионажа: он организует тайные рейды против военных кораблей Кровавого Паруса и перехватывает вражеские приказы.",["faction:Horde"]="Хотя Морской Рог — таурен, он верен исключительно Картелю Хитрая Шестеренка и Налетчикам Черноводья и сохраняет нейтралитет по отношению к путникам и из Орды, и из Альянса.",["race:Tauren"]="Морской Рог — один из крайне редких тауренов, покинувших внутренние равнины Калимдора ради покорения открытого океана; он служит командиром флота нейтрального гоблинского порта."},sec={{t="Бык в открытом море",b="Хотя таурены известны по всему Калимдору как жители равнин, командир флота Морской Рог выбрал совсем иную жизнь на океане. Облаченный в пиратское одеяние, он командует флотом Налетчиков Черноводья — частным военно-морским крылом Картеля Хитрая Шестеренка в Тернистой долине. Находясь на верхнем этаже Таверны «Соленый моряк», Морской Рог работает плечом к плечу с бароном Ревилгазом, координируя морские маршруты, распределение команд и береговую оборону этого беззаконного, но строго управляемого порта — Пиратской бухты."},{t="Защита бухты",b="Главная постоянная забота Морского Рога — Пираты Кровавого Паруса, которые устроили укрепленные лагеря на южном Пустынном береге и поставили военные корабли у побережья. Когда стало известно, что командир флота Фираллон и верхушка Кровавого Паруса намерены начать прямой штурм и разграбить Пиратскую бухту, Морской Рог действует решительно. Отправив наемников захватить вражескую переписку и убрать Фираллона, Килхаула и Тихого Омута на их флагмане, он успешно спасает порт от полного разорения."},{t="Глаза на морях",b="Помимо отражения пиратских налетов, Морской Рог руководит разными торговыми и спасательными предприятиями в Восточных королевствах. Он координирует поиски утонувших сокровищ у побережья Арати близ Бухты Фальдира, работая с водолазами-спасателями, чтобы добыть эльфийские реликвии. Он также сообщает Ревилгазу о выгодных возможностях, появляющихся в городе, например о соревновательной рыбалке и местной торговле, чтобы флот Черноводья оставался богатым и опережал соперников."}},faq={{q="Где находится командир флота Морской Рог?",a="Он находится на верхнем этаже и балконе Таверны «Соленый моряк» в Пиратской бухте, рядом с бароном Ревилгазом, и смотрит на доки.",al={"where is seahorn","seahorn location","find seahorn","где морской рог","морской рог местонахождение","найти морского рога"}},{q="Почему таурен служит командиром пиратского флота?",a="Хотя большинство тауренов тесно связаны с равнинами и духовными традициями Мулгора, Морской Рог увлекся мореходством и наемной морской жизнью. Его морское мастерство и властное присутствие принесли ему руководство Налетчиками Черноводья под началом барона Ревилгаза.",al={"tauren pirate","why is seahorn a pirate","tauren in booty bay","таурен пират","почему морской рог пират","таурен в пиратской бухте"}},{q="Каковы отношения Морского Рога и барона Ревилгаза?",a="Морской Рог — заместитель барона Ревилгаза и морской командир его Налетчиков Черноводья. Пока Ревилгаз занимается политикой, торговлей и финансами, Морской Рог отвечает за флот, тактическую разведку и оборонительные военные операции Пиратской бухты.",al={"seahorn and revilgaz","is seahorn revilgaz bodyguard","who works for revilgaz","морской рог и ревилгаз","телохранитель ревилгаза","кто работает на ревилгаза"}},{q="Кто такие Налетчики Черноводья?",a="Налетчики Черноводья — частный флот корсаров, верных Картелю Хитрая Шестеренка, с базой в Пиратской бухте. В отличие от разбойников-налетчиков, грабящих без разбора, они действуют как официальный флот, защищающий интересы гоблинских торговцев и поддерживающий порядок в южных морях.",al={"blackwater raiders","what faction is seahorn","booty bay pirates","налетчики черноводья","к какой фракции принадлежит морской рог","пираты пиратской бухты"}},{q="Почему Морской Рог хочет остановить Пиратов Кровавого Паруса?",a="Пираты Кровавого Паруса — заклятые соперники Налетчиков Черноводья. Под предводительством командира флота Фираллона они разбили лагеря на Пустынном береге и намерены захватить саму Пиратскую бухту. Морской Рог постоянно работает над тем, чтобы упредить их планы вторжения.",al={"seahorn vs bloodsail","bloodsail conflict","why fight bloodsail","морской рог против кровавого паруса","конфликт с кровавым парусом","зачем воевать с кровавым парусом"}},{q="Ведет ли Морской Рог дела за пределами Тернистой долины?",a="Да. Морской Рог работает с агентами-спасателями, такими как Доктор Дракслегейдж и Мураш О'Брин, чтобы поднять потерянный груз и эльфийские сокровища, затонувшие близ Бухты Фальдира у Нагорья Арати, и доставляет ценные артефакты на свой пост в Пиратской бухте.",al={"faldirs cove seahorn","seahorn sunken treasure","arathi quests seahorn","бухта фальдира морской рог","затонувшие сокровища морской рог","задания арати морской рог"}}},fp="20,378,23.506.0,17.524.1,20.470.0,38.143.0,49.254.0,51.250.0,31.277.0,55.254.0,57.242.0"}
P.entries["npc:foggy-mackreel"] = {n="Туманник Маккрил",s="Туманник Маккрил — бесстрашный дворф, оказавшийся в опасном положении на разрушенной нижней кладке Моста Тандола. Несмотря на раздробленный камень под ногами и головокружительную пропасть внизу, его по-настоящему заботит лишь доставка самогона на север, в Южнобережье.",h="Туманник Маккрил — бесстрашный дворф, оказавшийся в опасном положении на разрушенной нижней кладке Моста...",kw={"arathi","foggy","mackreel","moonshine","southshore","thandol span","wetlands","арати","туманник","маккрил","самогон","южнобережье","мост тандола","болотина"},ang={["faction:Alliance"]="Курьеры Альянса, путешествующие между Стальгорном и северным форпостом Южнобережье, часто встречают Туманника и берут его застрявший груз, чтобы помочь собрату по Альянсу.",["race:Dwarf"]="Маккрил воплощает упрямую стойкость и странные приоритеты дворфов: он ценит своевременную доставку крепкого спиртного куда выше таких мелочей, как застрять над смертельной пропастью."},sec={{t="В ловушке на мосту",b="Устроившись на сломанных опорах под разрушенным Мостом Тандола, Туманник Маккрил выглядит совершенно невозмутимым в своем опасном положении. Хотя диверсии клана Черного Железа и разрушения войны раскололи великий мост между Болотиной и Нагорьем Арати, Маккрил считает свое шаткое положение мелкой неприятностью. Он думает не о спасении, а о недоставленной партии крепкого самогона для посетителей Южнобережья в Предгорьях Хилсбрада. Он охотно нанимает проходящих искателей приключений, достаточно ловких, чтобы добраться до его уступа, чтобы они закончили доставку вместо него."}},faq={{q="Кто такой Туманник Маккрил?",a="Туманник Маккрил — эксцентричный дворф-курьер, застрявший на разрушенных каменных столбах под сломанным Мостом Тандола. Несмотря на пропасть, он остается совершенно спокоен и сосредоточен на доставке своего самогона.",al={"foggy mackreel","who is foggy","mackreel npc","туманник маккрил","кто такой туманник","маккрил нпс"}},{q="Где найти Туманника Маккрила?",a="Он находится на каменной площадке посередине разрушенного центрального пролета Моста Тандола; добраться можно, осторожно спрыгнув с конструкции моста со стороны Нагорья Арати.",al={"where is foggy mackreel","foggy mackreel location","how to find mackreel","где туманник маккрил","туманник маккрил местонахождение","как найти маккрила"}},{q="Почему Туманник Маккрил оказался внизу?",a="Туманник застрял среди обломков Моста Тандола во время своих странствий. Но вместо того чтобы искать спасения, он больше всего хочет найти того, кто согласится донести его груз самогона до Южнобережья.",al={"why is foggy stranded","how did mackreel get there","why is he on the bridge","почему туманник застрял","как маккрил там оказался","почему он на мосту"}},{q="Какое задание дает Туманник Маккрил?",a="Он предлагает задание «Самогон Маккрила», прося путников доставить кувшин его крепкого напитка в таверну Южнобережья, находящегося за Нагорьем Арати.",al={"foggy quest","mackreel moonshine quest","what quest does foggy give","задание туманника","задание самогон маккрила","какое задание дает туманник"}}},fp="14,264,20.583.0,22.226.0,32.183.0,33.217.0,37.143.0"}
P.entries["npc:foreman-oslow"] = {n="Штейгер Ослоу",s="Штейгер Ослоу — осажденный главный строитель Приозерья, которому поручено восстановить разрушенный Мост Безмолвия в сердце Красногорья. Из-за артиллерии орков Черной горы и налетчиков-гноллов его работы по восстановлению застопорились: грузы потеряны, оборудование затонуло. Он во многом полагается на странствующих искателей приключений, которые вернут его инструменты и добудут материалы, чтобы Приозерье восстановило важный торговый путь.",h="Штейгер Ослоу — осажденный главный строитель Приозерья, которому поручено восстановить разрушенный Мост...",kw={"blackrock","everstill bridge","foreman oslow","goldshire","lakeshire","oslow","redridge","toolbox","черная гора","мост безмолвия","штейгер ослоу","златоземье","приозерье","ослоу","красногорье","ящик с инструментами"},ang={["faction:Alliance"]="Разрушенный мост Приозерья оставляет восточную границу открытой, поэтому восстановительные работы Ослоу стратегически необходимы для защиты границы Альянса.",["profession:Mining"]="Ослоу нужны сырье, металлические изделия и поставки из карьеров для восстановления разрушенной кладки, поэтому он тесно связан с местными поставками минералов."},sec={{t="Город, рассеченный надвое",b="Стоя у расколотой кладки Моста Безмолвия, Штейгер Ослоу ведет трудную борьбу. Мост — жизненная артерия Приозерья: он пересекает Озеро Безмолвия и соединяет западные дороги к Элвиннскому лесу с восточными берегами. Орки Черной горы, спустившиеся со скал Водопада Каменной Стражи, нацелились на переправу, чтобы парализовать снабжение и передвижение войск города, оставив поселение разделенным и уязвимым."},{t="Затонувшая сталь и украденный камень",b="Каждая попытка Ослоу восстановить мост словно преследуется невезением. Когда мост рухнул, запасные инструменты отправили по суше из Златоземья и погрузили на озерный паром. Орочьи катапульты взяли судно на прицел, и тяжелый железный ящик с инструментами отправился прямо на илистое дно Озера Безмолвия. В довершение бед местные гноллы Красногорья устроили засаду на его обозы и унесли бревна и заклепки для раствора, нужные для возведения арок."}},faq={{q="Кто такой Штейгер Ослоу?",a="Штейгер Ослоу — человек, каменщик и строитель, расположившийся в Приозерье. Он главный мастер, отвечающий за содержание и восстановление Моста Безмолвия.",al={"foreman oslow","who is oslow","lakeshire builder","штейгер ослоу","кто такой ослоу","строитель приозерья"}},{q="Почему Мост Безмолвия разрушен?",a="Мост Безмолвия разрушили орки Черной горы из Красногорья. Уничтожение пролета перерезало главную дорогу Приозерья, серьезно ослабило оборону города и затруднило сообщение между восточным и западным берегами.",al={"why is the bridge broken","who broke lakeshire bridge","everstill bridge destroyed","почему мост разрушен","кто разрушил мост приозерья","мост безмолвия уничтожен"}},{q="Где потерянные инструменты Ослоу?",a="Тяжелый ящик с инструментами Ослоу лежит на дне Озера Безмолвия. Лодку, везшую его из Златоземья, поразил и потопил обстрел катапульт Черной горы.",al={"where are the tools","lost tools location","oslow toolbox","где инструменты","потерянные инструменты","ящик с инструментами ослоу"}},{q="Почему мост до сих пор не починили?",a="Орочьи катапульты потопили его инструменты в озере, а гноллы крадут стройматериалы из прибывающих грузов, поэтому у Ослоу нет материалов и оборудования, чтобы возобновить строительство без посторонней помощи.",al={"why is bridge not fixed","lakeshire bridge delay","почему мост не починен","задержка ремонта моста приозерья"}},{q="Откуда изначально взялись припасы Ослоу?",a="Запасные инструменты сначала привезли на телеге из Златоземья в Элвиннском лесу, а затем перегрузили на озерный паром, чтобы обойти разрушенный пролет.",al={"supply wagon origin","where did tools come from","откуда обоз с припасами","откуда взялись инструменты"}},{q="С какими угрозами сталкивается Ослоу?",a="Ослоу постоянно подвергается нападениям с двух сторон: орки клана Черной горы, засевшие на близких высотах, обстреливают озеро осадными машинами, а рыскающие гноллы нападают на обозы с припасами.",al={"oslow enemies","who attacks the bridge","враги ослоу","кто нападает на мост"}}},fp="13,413,17.430.0,29.449.0,21.172.0,35.246.0,29.155.0,40.213.0,48.158.0,35.193.0"}
P.entries["npc:foreman-stonebrow"] = {n="Штейгер Камнелоб",s="Штейгер Камнелоб — дворф-надзиратель, представляющий Лигу шахтеров в Карьере Гол'Болар на востоке Дун Морога. После того как агрессивные трогги выбрались из породы и захватили место раскопок, ему пришлось организовать оборону и нанять искателей приключений, чтобы очистить шахты.",h="Штейгер Камнелоб — дворф-надзиратель, представляющий Лигу шахтеров в Карьере Гол'Болар на востоке Дун Морога.",kw={"dun morogh","foreman stonebrow","gol bolar","gol'bolar quarry","miners' league","stonebrow","troggs","дун морог","штейгер камнелоб","гол'болар","карьер гол'болар","лига шахтеров","камнелоб","трогги"},ang={["profession:Mining"]="Шахтеры профессионально заинтересованы в помощи Камнелобу, ведь возвращение богатых залежей камня и руды карьера жизненно важно для работы гильдий Каз Модана.",["race:Dwarf"]="Для дворфов вторжение троггов в Карьер Гол'Болар — прямой удар по каменной промышленности Стальгорна и мрачное напоминание о древних угрозах, таящихся под их исконной землей."},sec={{t="Беда в Гол'Боларе",b="Штейгеру Камнелобу поручили руководить работами в Карьере Гол'Болар — важном дворфийском раскопе в горах к востоку от Караноса. Когда глубокие раскопки вскрыли скрытые норы троггов, подземные твари заполонили шахты и прогнали шахтеров от их оборудования. Не желая полностью покидать место, Камнелоб остается на краю карьера, чтобы нанять любых крепких путников, готовых оттеснить троггов."}},faq={{q="Кто такой Штейгер Камнелоб?",a="Штейгер Камнелоб — дворф из Лиги шахтеров, руководящий работами в Карьере Гол'Болар в Дун Мороге. Он координирует работы и старается сохранять карьер в безопасности.",al={"stonebrow","who is stonebrow","foreman stonebrow lore","камнелоб","кто такой камнелоб","штейгер камнелоб предания"}},{q="Почему Штейгер Камнелоб просит о помощи?",a="Раскопки в Карьере Гол'Болар случайно вскрыли подземные пещеры троггов. Трогги заполонили нижние террасы, убивая рабочих и вынудив уцелевших шахтеров отступить в лагерь на краю.",al={"gol bolar trogg problem","why need help","quarry quest","проблема троггов гол'болар","зачем нужна помощь","задание карьера"}},{q="Что такое Лига шахтеров?",a="Лига шахтеров — дворфийская гильдия и торговая организация со штаб-квартирой в Стальгорне, которая руководит горными экспедициями, добычей ресурсов и работой карьеров по всему Каз Модану.",al={"miners league","what is miners league","лига шахтеров","что такое лига шахтеров"}},{q="Где найти Штейгера Камнелоба?",a="Он расположился в лагере на краю Карьера Гол'Болар, в восточных холмах Дун Морога, недалеко от дороги к Лок Модану.",al={"stonebrow location","where is foreman stonebrow","где камнелоб","где штейгер камнелоб"}}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="Штейгер Тазз'рил",s="Штейгер Тазз'рил — орк, надсмотрщик за рабочими в Долине Испытаний в Дуротаре. В его обязанности входит следить, чтобы батраки работали по графику, и поддерживать базовую инфраструктуру для молодых воинов. Его постоянно раздражают ленивые работники и культисты неподалеку.",h="Штейгер Тазз'рил — орк, надсмотрщик за рабочими в Долине Испытаний в Дуротаре.",kw={"blackjack","burning blade","durotar","foreman","lazy peons","thazzril","valley of trials","дубинка","пылающий клинок","дуротар","штейгер","ленивые батраки","тазз'рил","долина испытаний"},ang={["profession:Mining"]="Тазз'рил ценит хорошее горное снаряжение, о чем говорит его отчаянное желание вернуть зачарованную кирку из темных глубин Грота Пылающего Клинка.",["race:Orc"]="Для молодых орков Тазз'рил — первый урок устройства общества Орды: сила на поле боя возможна лишь тогда, когда ее поддерживает неприметный дисциплинированный труд."},sec={{t="Порядок среди батраков",b="Строительство нового дома на суровом красном камне Дуротара требует нескончаемого труда. В Долине Испытаний Штейгер Тазз'рил надзирает за пеонами, которые рубят лес и собирают материалы для лагеря и всей военной кампании Орды. К несчастью для Тазз'рила, пеоны славятся склонностью лениться и дремать под пустынным солнцем. Чтобы стройка не стояла, он часто привлекает новоприбывших рекрутов, чтобы они хорошенько огрели спящих работников его верной дубинкой, внушая послушание грубым убеждением."},{t="Потерянная кирка в опасных руках",b="В обязанности Тазз'рила входит и разведка минеральных ресурсов долины, но однажды это привело к досадной оплошности. Исследуя пещеру, известную как Грот Пылающего Клинка, он был вынужден бежать от темных культистов и случайно бросил свою драгоценную зачарованную кирку. Он слишком осторожен, чтобы возвращаться за ней самому среди собравшихся чернокнижников и их демонических слуг, и полагается на молодых искателей приключений из Орды: пусть спустятся в глубину и вернут его инструмент."}},faq={{q="Кто такой штейгер Тазз'рил?",a="Штейгер Тазз'рил — орк, надсмотрщик за рабочими в Долине Испытаний в Дуротаре. Он отвечает за рабочие бригады, заготовку леса и разведку полезных ресурсов в округе для нужд поселения Орды.",al={"who is thazzril","thazzril valley of trials","foreman thazzril lore","кто такой тазз'рил","тазз'рил долина испытаний","штейгер тазз'рил предания"}},{q="Зачем Тазз'рил дает игрокам дубинку?",a="Батраки под его присмотром часто засыпают под деревьями вместо того, чтобы заготавливать лес. Тазз'рил выдает зачарованную деревянную дубинку, чтобы вбить в них немного дисциплины и прогнать обратно к работе.",al={"why hit lazy peons","thazzril blackjack","lazy peons quest lore","зачем бить ленивых батраков","дубинка тазз'рила","задание ленивые батраки"}},{q="Почему кирка Тазз'рила оказалась в пещере Пылающего Клинка?",a="Разведывая окрестные пещеры в поисках рудных жил, Тазз'рил забрел в Грот Пылающего Клинка. Испугавшись культистов, прятавшихся в тени, он поспешно отступил и оставил свою ценную зачарованную кирку.",al={"thazzril pick","why is pick in coven","burning blade pick","кирка тазз'рила","почему кирка в гроте","кирка пылающего клинка"}},{q="Какова его роль в Орде?",a="Тазз'рил не солдат на передовой и не шаман, а гражданский надсмотрщик. Его обязанности связаны с тылом Дуротара: руководить физическим трудом, следить за запасами для строительства и обеспечивать работу батраков.",al={"is thazzril a soldier","thazzril rank","тазз'рил солдат","звание тазз'рила"}}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:foreman-thistlenettle"] = {n="Штейгер Чертополох",s="Штейгер Чертополох был дворфом-надсмотрщиком, представлявшим Лигу шахтеров и Лигу исследователей в глубинах Западного Края. После страшного обвала, заточившего его бригаду в подземных туннелях Мертвых копей, он погиб вместе со своими рабочими и восстал вновь нежитью-вурдалаком. Теперь он бродит по темным обрушенным коридорам, и узнать его можно лишь по значку гильдии, который он до сих пор носит.",h="Штейгер Чертополох был дворфом-надсмотрщиком, представлявшим Лигу шахтеров и Лигу исследователей в глубинах...",kw={"badge","cave-in","deadmines","foreman","ghoul","miners' league","thistlenettle","wilder","значок","обвал","мертвые копи","штейгер","вурдалак","лига шахтеров","чертополох","чертополохх"},ang={["profession:Mining"]="Судьба Чертополоха — мрачное напоминание всем шахтерам о вечной опасности обвалов и враждебных подземных глубин.",["race:Dwarf"]="Трагическая гибель штейгера Лиги исследователей и целой бригады дворфов напоминает об опасностях, таящихся под человеческими королевствами."},sec={{t="Трагедия в Мертвых копях",b="До того как Братство Справедливости полностью захватило Мертвые копи, в их богатые жилы углублялись законные горные экспедиции. Штейгер Чертополох руководил одной из них от имени Лиги шахтеров и Лиги исследователей. Глубоко в туннелях под Луноречьем случился обвал, отрезавший его отряд от поверхности. Запертые шахтеры умерли во тьме, но покой их был недолгим: зловещая мертвящая порча подняла Чертополоха и его бригаду голодными вурдалаками, и те стали бродить по темным переходам."},{t="Горе брата",b="В Штормграде его брат Чертополохх Дикий месяцами не находил себе места, гадая о судьбе пропавшей бригады шахтеров. Из занятых туннелей не доходило никаких вестей, но со временем поползли слухи, что павший надсмотрщик все еще ходит среди мертвых. Искателей приключений, что отваживаются подойти к окраинам Мертвых копей, просят найти нежить-штейгера, прекратить его муки и вернуть его значок, чтобы принести покой скорбящим родным."}},faq={{q="Кем был штейгер Чертополох до смерти?",a="Это был дворф-штейгер, связанный и с Лигой шахтеров, и с Лигой исследователей. Он повел бригаду шахтеров в Мертвые копи до того, как их полностью укрепили преступники, чтобы добывать руду и исследовать подземные жилы.",al={"thistlenettle lore","who is foreman thistlenettle","thistlenettle background","предания о чертополохе","кто такой штейгер чертополох","история чертополоха"}},{q="Почему штейгер Чертополох стал нежитью-вурдалаком?",a="Страшный обвал обрушил туннели над Чертополохом и его отрядом шахтеров и убил их. Темные подземные силы или остаточный некромантский след в лабиринте копей затем оживили их останки и превратили дворфов в неупокоенных вурдалаков.",al={"why is he a ghoul","how did thistlenettle die","thistlenettle undead","почему он вурдалак","как умер чертополох","чертополох нежить"}},{q="Где находится штейгер Чертополох?",a="Он бродит в тупиковом обрушенном туннеле во внешнем лабиринте Мертвых копей, перед порталом в само подземелье, в окружении своих оживших бывших шахтеров.",al={"where to find thistlenettle","thistlenettle location","deadmines foreman spot","где найти чертополоха","местонахождение чертополоха","штейгер мертвые копи"}},{q="Кто разыскивает штейгера Чертополоха?",a="Его брат, Чертополохх Дикий, живущий в Квартале Дворфов города Штормград. Чертополохх ищет доказательства судьбы брата и просит путников принести Амулет Чертополоха.",al={"who wants thistlenettle dead","wilder brother","thistlenettle quest giver","кто хочет смерти чертополоха","чертополохх брат","кто выдает задание чертополоха"}}},fp="21,416,24.530.0,17.419.1,45.237.0,45.261.0,39.181.0,41.186.0"}
P.entries["npc:frahun-shadewhisper"] = {n="Фрагун Шепот Тени",s="Фрагун Шепот Тени — ночной эльф, учитель разбойников в Альдрассиле, в Тенистой долине. Он обучает новоиспеченных ночных эльфов-разведчиков и разбойников основам скрытности, ловкости и внезапных ударов. Он носит ту же фамилию, что и Эрион Шепот Тени, другой учитель этого ремесла в Дарнассе.",h="Фрагун Шепот Тени — ночной эльф, учитель разбойников в Альдрассиле, в Тенистой долине.",kw={"aldrassil","encrypted sigil","erion","frahun","rogue trainer","shadewhisper","shadowglen","teldrassil","альдрассил","зашифрованный знак","эрион","фрагун","учитель разбойников","шепот тени","тенистая долина","тельдрассил"},ang={["class:Rogue"]="Фрагун Шепот Тени — самый первый наставник ночных эльфов-разбойников: он знакомит их со скрытностью, засадами и мастерством владения оружием.",["race:NightElf"]="Фрагун показывает, как ночные эльфы превращают свою природную ночную склонность и неуловимость в смертоносные практические боевые навыки для защиты Тельдрассила."},sec={{t="Наставник в тенях",b="В безопасном убежище Альдрассила, в сердце Тельдрассила, Фрагун Шепот Тени обучает начинающих разбойников тихому искусству маскировки и владения клинком. Хотя общество ночных эльфов чаще чтит жриц, стражей и друидов, ремесло разведчиков и лазутчиков по-прежнему необходимо для защиты ветвей Мирового Древа. Фрагун принимает новобранцев, приходящих с зашифрованным знаком, оценивает их задатки и направляет их первые шаги."}},faq={{q="Кто такой Фрагун Шепот Тени?",a="Фрагун Шепот Тени — ночной эльф, учитель разбойников в Альдрассиле, в Тельдрассиле. Он учит начинающих разбойников основам скрытности, точного боя и тайной тактики.",al={"frahun lore","who is frahun","frahun shadewhisper role","фрагун предания","кто такой фрагун","роль фрагуна шепот тени"}},{q="Где найти Фрагуна Шепота Тени?",a="Он находится в Альдрассиле, центральном оплоте начальной области Тенистая долина в Тельдрассиле.",al={"frahun location","where is frahun","find frahun shadewhisper","местонахождение фрагуна","где фрагун","найти фрагуна шепот тени"}},{q="Родственник ли Фрагун Эриону Шепоту Тени?",a="Судя по общей фамилии и одинаковому занятию — обучению разбойников, — Фрагун, как считается, родственник Эриона Шепота Тени, который обучает разбойников в Дарнассе.",al={"erion shadewhisper brother","frahun erion related","shadewhisper family","брат эриона шепот тени","фрагун и эрион родственники","семья шепот тени"}},{q="Какую роль играет с ним Зашифрованный знак?",a="Начинающие ночные эльфы-разбойники начинают путь, принеся зашифрованный знак прямо Фрагуну, что отмечает их как кандидатов, готовых к формальному обучению ремеслу разбойника.",al={"encrypted sigil turn in","frahun sigil","rogue starting quest","сдать зашифрованный знак","знак фрагуна","начальное задание разбойника"}}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furen-longbeard"] = {n="Фьюрен Длиннобород",s="Фьюрен Длиннобород — мастер-оружейник из дворфов, работающий в оживленном Квартале Дворфов Штормграда. Он ученик знаменитого кузнеца Гриманда Элмора и специализируется на тяжелом защитном снаряжении и прочных кольчугах для опытных защитников Альянса. Воины всего королевства обращаются к его знаниям в металлургии, чтобы выковать особые доспехи, готовые к бою.",h="Фьюрен Длиннобород — мастер-оружейник из дворфов, работающий в оживленном Квартале Дворфов Штормграда.",kw={"armorer","blacksmith","dwarven district","fire hardened mail","furen longbeard","grimand elmore","stormwind","warrior","оружейник","кузнец","квартал дворфов","закаленный доспех","фьюрен длиннобород","гриманд элмор","штормград","воин"},ang={["class:Warrior"]="Для начинающих воинов Альянса Фьюрен Длиннобород — важный помощник, превращающий сырую боевую решимость и собранные реагенты в необходимые закаленные защитные доспехи.",["profession:Blacksmithing"]="Фьюрен воплощает высокие стандарты дворфийской кузнечной школы, утвердившиеся в Штормграде, и демонстрирует передовые приемы, перенятые у Гриманда Элмора.",["race:Dwarf"]="Даже вдали от Стальгорна Фьюрен Длиннобород хранит дворфийские металлургические традиции в сердце столицы людей."},sec={{t="Дворф-кузнец в столице людей",b="Фьюрен Длиннобород занимается своим ремеслом вдали от великих кузниц Стальгорна: его дом — среди булыжника и копоти Квартала Дворфов Штормграда. Как и многие его сородичи, Фьюрен принес на юг традиционную дворфийскую металлургию, чтобы помочь восстановлению и обороне королевства. Работая среди пылающих горнов и звенящих наковален, он поддерживает прочные связи с другими мастерами по всему городу и за его пределами."},{t="Мастерство Закаленного доспеха",b="Обученный почтенным мастером Гримандом Элмором, Фьюрен довел до совершенства приемы обработки тяжелых кольчуг и латных доспехов, чтобы они выдерживали жесточайшие удары на поле боя. К Фьюрену часто обращаются многообещающие молодые воины в поисках прочной защиты; для своих фирменных закаленных доспехов он требует редкие руды, особые детали и необычные реагенты из дальних уголков мира."}},faq={{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — дворф-оружейник, работающий в Квартале Дворфов Штормграда. Он служит важным связным и наставником для воинов Альянса, желающих получить кольчужные доспехи работы мастера.",al={"who is furen","furen longbeard lore","dwarf armorer stormwind","кто такой фьюрен","фьюрен длиннобород предания","дворф-оружейник штормград"}},{q="Где найти Фьюрена Длинноборода?",a="Он находится в Квартале Дворфов Штормграда, рядом с шумными кузницами и мастерскими, которыми славится этот район.",al={"where is furen longbeard","furen longbeard location","furen stormwind","где фьюрен длиннобород","местонахождение фьюрена длинноборода","фьюрен штормград"}},{q="Кто обучил Фьюрена кузнечному делу?",a="Фьюрена обучил изготовлению доспехов и металлургии Гриманд Элмор, уважаемый опытный мастер, также живущий в Квартале Дворфов.",al={"furen teacher","furen mentor","who trained furen","учитель фьюрена","наставник фьюрена","кто обучал фьюрена"}},{q="Какие доспехи Фьюрен славится изготовлением?",a="Он известен изготовлением Закаленного доспеха — прочного комплекта брони, создаваемого сложными металлургическими способами из редких компонентов, собранных по всему континенту.",al={"fire hardened mail","furen armor quest","warrior mail quest stormwind","закаленный доспех","задание фьюрена о доспехе","задание воина кольчуга штормград"}},{q="Родственник ли Фьюрен Длиннобород другим Длиннобородам?",a="Он носит имя клана, общее с несколькими другими известными дворфами Восточных королевств, например с опытным горцем Пилотом Длиннобородом, однако сам занимается исключительно кузнечным делом.",al={"furen family","longbeard clan","pilot longbeard relative","семья фьюрена","клан длиннобородов","родственник пилота длинноборода"}},{q="Почему воины ищут Фьюрена Длинноборода?",a="Воинов, доказавших базовое боевое мастерство, направляют к Фьюрену за тяжелой прочной броней, способной выдержать бои на передовой против более опасных врагов.",al={"why do warriors visit furen","warrior quest dwarven district","furen warrior trainer","зачем воины идут к фьюрену","задание воина квартал дворфов","фьюрен учитель воинов"}}},fp="15,369,36.416.0,29.380.0,23.205.0,35.145.0,36.130.0,40.180.0,47.179.0,41.169.0"}
P.entries["npc:furl-scornbrow"] = {n="Фурл Хмурый Лоб",s="Фурл Хмурый Лоб — стареющий орк-дозорный, несущий службу на сторожевой башне к северо-западу от Колючего Холма. Из-за возраста он больше не может сражаться на передовой, поэтому наблюдает за красными каньонами Дуротара и мастерит прочные заплечные мешки для юных путников, отправляющихся в дорогу.",h="Фурл Хмурый Лоб — стареющий орк-дозорный, несущий службу на сторожевой башне к северо-западу от Колючего...",kw={"carry your weight","durotar","furl scornbrow","lookout","orc","razor hill","watchtower","приносить пользу","дуротар","фурл хмурый лоб","дозорный пост","орк","колючий холм","сторожевая башня"},ang={["faction:Horde"]="Фурл несет службу на хребтах за пределами Колючего Холма и воплощает бдительность, необходимую для защиты молодых поселений Дуротара от остающихся угроз.",["race:Orc"]="Фурл воплощает веру орков в то, что, даже когда возраст отнимает у воина боевую силу, честная жизнь означает поиск иного способа служить клану и Орде."},sec={{t="Страж хребта",b="Высоко на деревянной сторожевой башне к северо-западу от Колючего Холма Фурл Хмурый Лоб несет тихую вахту над центральными равнинами Дуротара. В напряженные первые дни после основания Оргриммара такие дозорные, как Фурл, были жизненно важны: они трубили в сигнальные рога при появлении враждебных свинобразов, кентавров и чужаков из Кул Тираса. Теперь Дуротар стал спокойнее, а Колючий Холм обзавелся более надежными границами, поэтому тревоги случаются реже, и у Фурла остается много тихих часов на посту."},{t="Умелые руки",b="Фурл охотно признает, что его старые кости и угасающие силы не годятся для боя, но орк не так-то легко отказывается от своего предназначения. Вместо того чтобы сидеть без дела, он шьет холщовые мешки и заплечные сумки для новобранцев, которым нужно носить припасы. В обмен на грубую нитку и необходимые материалы он снаряжает неопытных искателей приключений, отправляющихся доказывать свою доблесть Орде."}},faq={{q="Кто такой Фурл Хмурый Лоб?",a="Фурл Хмурый Лоб — пожилой орк-дозорный, несущий службу на сторожевой башне на утесах к северо-западу от Колючего Холма. Не имея возможности из-за возраста сражаться на передовой, он следит за горизонтом, высматривая опасность, и шьет сумки для юных путников.",al={"who is furl","furl scornbrow lore","furl in razor hill","кто такой фурл","фурл хмурый лоб предания","фурл в колючем холме"}},{q="Какова роль Фурла в Дуротаре?",a="Он несет вахту на башне с сигнальным рогом, высматривая захватчиков, приближающихся к Колючему Холму. Поскольку под властью Орды Дуротар становится все безопаснее, тревогу он поднимает гораздо реже и проводит свободное время, помогая новобранцам собирать снаряжение.",al={"what does furl do","furl purpose","что делает фурл","предназначение фурла"}},{q="Почему Фурл просит у путников материалы?",a="Фурл считает, что каждый член Орды должен приносить пользу, несмотря ни на какие обстоятельства. Поскольку сражаться он больше не может, он шьет удобные дорожные сумки для молодых воинов, прося лишь простые материалы, например грубую нитку, чтобы закончить работу.",al={"carry your weight quest lore","why does furl want thread","задание «Каждый должен приносить пользу»","зачем фурлу нитки"}}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="Гаролас Талветрен",s="Гаролас Талветрен — ночной эльф-часовой, охраняющий руины Деревни Звездного Ветра в Тельдрассиле. Назначенный защитником Спящих друидов, он ищет помощи в борьбе с агрессивными фурболгами и темной порчей, тревожащей ветви Дерева.",h="Гаролас Талветрен — ночной эльф-часовой, охраняющий руины Деревни Звездного Ветра в Тельдрассиле.",kw={"a troubling breeze","gaerolas talvethren","gnarlpine corruption","starbreeze village","teldrassil","the sleeping","тревожный ветерок","гаролас талветрен","порча скрюченной сосны","деревня звездного ветра","тельдрассил","спящие"},ang={["class:Druid"]="Долг Гароласа как хранителя спящих друидов делает помощь ему личным делом защиты собратьев по Кругу Кенария.",["race:NightElf"]="Для юных ночных эльфов, покидающих Доланаар, помощь Гароласу — отрезвляющий урок того, насколько глубоко скверна проникла в священные ветви Тельдрассила."},sec={{t="Хранитель Спящих",b="Гаролас Талветрен, находясь в неспокойной Деревне Звездного Ветра, несет торжественный долг защиты Спящих друидов, которые покоятся в единении с Изумрудным Сном. Его бдительность стала тревожной: неестественная порча расползается по лесу и нарушает равновесие Тельдрассила."},{t="Угроза Скрюченной Сосны",b="Гаролас призывает путников дать отпор племени фурболгов Скрюченной Сосны, чей разум охватили безумие и свирепость. Исследуя скверну, исходящую от их шаманов, и выясняя корни их беды, он надеется сохранить то, что осталось от святости восточного Тельдрассила."}},faq={{q="Кто такой Гаролас Талветрен?",a="Это ночной эльф-защитник, несущий службу в Деревне Звездного Ветра. Он обязан охранять спящих друидов и расследовать странную порчу, поразившую окрестности.",al={"gaerolas","who is gaerolas","gaerolas role","гаролас","кто такой гаролас","роль гароласа"}},{q="Где найти Гароласа Талветрена?",a="Он находится в Деревне Звездного Ветра, в восточных ветвях Тельдрассила, к востоку от Доланаара.",al={"gaerolas location","where is gaerolas talvethren","find gaerolas","где найти гароласа","где гаролас талветрен","местонахождение гароласа"}},{q="Кто такие «Спящие», которых охраняет Гаролас?",a="Спящие — это ночные эльфы-друиды, погрузившиеся в долгий сон в курганах и святилищах, чтобы странствовать по Изумрудному Сну; их тела при этом остаются уязвимыми для физического вреда.",al={"the sleeping","who are the sleeping","sleeping druids","спящие","кто такие спящие","спящие друиды"}},{q="Какие угрозы беспокоят Гароласа?",a="Его глубоко тревожит порча, поразившая местных животных, и внезапная безумная враждебность племени фурболгов Скрюченной Сосны.",al={"starbreeze threats","gaerolas quests","gnarlpine trouble","угрозы звездного ветра","задания гароласа","беда скрюченной сосны"}}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="Гакин Темнопряд",s="Гакин Темнопряд — мастер-чернокнижник, тайно действующий глубоко под таверной «Забитый ягненок» в Квартале магов Штормграда. Он обучает начинающих чернокнижников Альянса темным искусствам, проверяя их решимость перед ритуалами призыва и подчинения демонов из иных миров.",h="Гакин Темнопряд — мастер-чернокнижник, тайно действующий глубоко под таверной «Забитый ягненок» в Квартале...",kw={"darkbinder","gakin","mage quarter","slaughtered lamb","succubus","surena caledon","voidwalker","warlock","темнопряд","гакин","квартал магов","забитый ягненок","суккуб","сурена каледон","демон бездны","чернокнижник"},ang={["class:Warlock"]="Гакин — важный наставник для чернокнижников-людей и гномов: он дает ключевые классовые задания на овладение ритуалами демона Бездны и суккуба в склепах Штормграда.",["faction:Alliance"]="Тайно действующий под столицей ковен Гакина Темнопряда демонстрирует прагматичные, пропитанные тенью компромиссы, на которые идут в самом сердце Альянса."},sec={{t="Тайное место встреч",b="Пока маги Штормграда открыто занимаются своим искусством в высоких башнях, служители тьмы и скверны вынуждены обитать там, куда не проникнет чужой взгляд. Под залом «Забитого ягненка» скрыт сырой подвал, похожий на склеп, с кругами призыва и мрачными томами. Гакин — опора этого тайного собрания: он следит, чтобы молодые чернокнижники усвоили дисциплину и сдержанность, прежде чем выпустят ужасы, которые не смогут контролировать."},{t="Повелитель демонов",b="Гакин сведущ в демонологии и ритуалах подчинения. Посвященных, заслуживших его внимание, он отправляет по королевству за редкими реликвиями и ингредиентами — от украденных талисманов из кровавого камня до порченой древесины из темных лесов. Когда реагенты собраны, Гакин руководит ритуалами в круге призыва склепа, заставляя новичков подчинять демонов Бездны и суккубов в смертельных испытаниях воли."},{t="Предательства и неоконченные дела",b="Не все ученики Гакина остаются послушными. Один из бывших подмастерьев, Сурена Каледон, скрылась с ценным колье кровавого камня и бежала в глушь. Подобные измены грозят выдать круг чернокнижников городской страже, поэтому Гакин посылает верных последователей вернуть утраченные артефакты и убрать свидетелей, прежде чем власти что-либо заметят."}},faq={{q="Где найти Гакина Темнопряда?",a="Гакин находится глубоко под таверной «Забитый ягненок» в Квартале магов Штормграда. Войдите в таверну, найдите спуск в глубине зала и идите по каменным туннелям, пока не доберетесь до круга призыва в нижнем склепе.",al={"where is gakin","gakin location","slaughtered lamb basement","где гакин","местонахождение гакина","подвал забитого ягненка"}},{q="Чем занимается Гакин Темнопряд?",a="Он — известный персонаж, выдающий задания чернокнижникам, и наставник персонажей Альянса. Он проверяет новичков, отправляя их на испытания по всему Азероту, и учит призывать и подчинять демонов, таких как демон Бездны и суккуб.",al={"what does gakin do","gakin role","gakin quests","что делает гакин","роль гакина","задания гакина"}},{q="Почему чернокнижникам позволено находиться под «Забитым ягненком»?",a="Демоническая магия в Штормграде запрещена и вызывает глубокое недоверие. Служители, обитающие под «Забитым ягненком», действуют в строгой тайне: их терпят лишь как опасный тайный ресурс и скрывают от городской стражи и жителей.",al={"why are warlocks allowed","are warlocks legal in stormwind","slaughtered lamb lore","почему чернокнижникам позволено","законны ли чернокнижники в штормграде","предания забитого ягненка"}},{q="Кто такая Сурена Каледон?",a="Сурена Каледон — бывшая ученица Гакина, укравшая у него могущественное колье кровавого камня. Ее предательство угрожает их тайному ордену, поэтому Гакин поручает чернокнижникам выследить ее.",al={"surena caledon","gakin student","who stole from gakin","сурена каледон","ученица гакина","кто обокрал гакина"}},{q="Каких демонов помогает призывать Гакин?",a="Гакин руководит ритуалами подчинения демонов Бездны и суккубов, помогая чернокнижникам привлекать существ в подземный круг и покорять их.",al={"gakin demons","gakin voidwalker","gakin succubus","демоны гакина","демон бездны гакин","суккуб гакин"}},{q="Кто такой Страхад и почему Гакин упоминает о нем?",a="Страхад Фарсан — опытный чернокнижник, живущий в холмах близ Кабестана в Калимдоре. Когда ученик осваивает основные ритуалы подчинения Гакина, тот направляет его за море продолжить мрачное обучение у Страхада.",al={"strahad","seeking strahad","where does gakin send me next","страхад","поиски страхада","куда гакин отправляет дальше"}}},fp="20,297,24.429.0,16.411.0,24.365.1,38.247.0,34.223.0,52.230.0,22.201.0,36.153.0,46.232.0"}
P.entries["npc:galgar"] = {n="Галгар",s="Галгар — орк-повар из Долины Испытаний в Дуротаре. Он готовит провизию для юных новобранцев, делающих первые шаги на службе Орде. Чтобы научить новичков основам добычи пропитания в суровой пустыне, он поручает им собирать дикие кактусовые яблоки для своего фирменного блюда.",h="Галгар — орк-повар из Долины Испытаний в Дуротаре.",kw={"cactus apple surprise","cactus apples","cook","durotar","galgar","horde recruit","valley of trials","кактусовый десерт","кактусовые яблоки","повар","дуротар","галгар","новобранец орды","долина испытаний"},ang={["profession:Cooking"]="Галгар воплощает практичную, простую кухню Орды, использующую скудные природные ресурсы Дуротара, чтобы новобранцы были сыты и готовы к бою.",["race:Orc"]="Для юных орков, делающих первые шаги в Долине Испытаний, поручение Галгара — привычный обряд посвящения перед встречей с более грозными опасностями дикой природы."},sec={{t="Повар в долине",b="Галгар живет у костра для готовки возле Логова в Долине Испытаний и кормит юных орков и троллей, проходящих первые обряды посвящения. Дуротар — сухая, суровая красная пустошь, где каждый кусок пищи приходится добывать у самой земли. Посылая новичков собирать спелые плоды кактуса, Галгар проверяет их внимательность и стойкость и заодно пополняет запасы кухни."},{t="Кактусовый десерт",b="Фирменный рецепт Галгара называется «Кактусовый десерт». Он открыто признает, что охота за колючими пустынными плодами — намеренно простое занятие, чтобы мягко ввести новобранцев в жизнь искателей приключений, но готовое блюдо остается основным пайком для голодных учеников. Даже самый закаленный воин Орды с чего-то начинал, и под бдительным взглядом Галгара этот путь начинается со сбора пищи в пустыне."}},faq={{q="Где найти Галгара?",a="Галгар находится в Долине Испытаний — стартовом каньоне орков и троллей на юго-западе Дуротара. Он стоит возле центрального костра и места для готовки у Логова.",al={"galgar location","where is galgar","galgar coordinates","местонахождение галгара","где галгар","координаты галгара"}},{q="О чем Галгар просит искателей приключений?",a="Он просит новичков собрать спелые кактусовые яблоки с диких кактусов, разбросанных по Долине Испытаний, чтобы приготовить свой «Кактусовый десерт».",al={"galgar quest","what does galgar want","задание галгара","что нужно галгару"}},{q="Почему Галгар посылает новобранцев собирать плоды?",a="Галгар признает, что задача намеренно проста. Это легкая первая работа, позволяющая молодым бойцам изучить долину и привыкнуть к самостоятельности в суровых землях Дуротара.",al={"why cactus apples","galgar test","зачем кактусовые яблоки","проверка галгара"}},{q="Что такое «Кактусовый десерт»?",a="Это фирменный рецепт Галгара: его готовят из свежих кактусовых яблок, собранных среди местной пустынной флоры Дуротара, чтобы подкреплять новобранцев.",al={"what is cactus apple surprise","galgar food","что такое кактусовый десерт","еда галгара"}}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="Ган'рул Кровавый Глаз",s="Ган'рул Кровавый Глаз — старший орк-учитель чернокнижников, обитающий в глубине темной пещеры Расселины Теней в Оргриммаре. Скрытый от бдительных глаз города наверху, он посвящает чернокнижников Орды в темные демонические обряды. Под его руководством новички учатся подчинять своей воле существ иных миров, таких как демоны Бездны и суккубы.",h="Ган'рул Кровавый Глаз — старший орк-учитель чернокнижников, обитающий в глубине темной пещеры Расселины Теней...",kw={"bloodeye","cleft of shadow","gan'rul","orgrimmar","succubus","trainer","voidwalker","warlock","кровавый глаз","расселина теней","ган'рул","оргриммар","суккуба","учитель","демон бездны","чернокнижник"},ang={["class:Warlock"]="Для чернокнижников, ищущих запретные знания, Ган'рул — важный наставник в Калимдоре, дающий знания и испытания, необходимые для подчинения демонов Бездны и суккуб.",["faction:Horde"]="Ган'рул воплощает шаткое положение магии скверны в Орде Тралла: ее используют ради военной мощи, но держат в подземных глубинах столицы."},sec={{t="Мастер в тенях",b="Хотя вождь Тралл терпит присутствие чернокнижников в новой Орде, их темные искусства нежеланны под открытым солнцем Дуротара. Ган'рул Кровавый Глаз устроил свой дом в Расселине Теней — подземном убежище под Оргриммаром, где заклинатели теней, разбойники и укротители скверны могут учиться без помех. Из этого подземного приюта Ган'рул служит одним из главных наставников растущих мастеров магии скверны."},{t="Подчинение Пустоты",b="Главная обязанность Ган'рула — надзор за опасными ритуалами призыва, которые необходимы честолюбивым чернокнижникам. Тем, кто хочет подчинить себе могущественных демонов, например стойкого демона Бездны или соблазнительную суккубу, нужно обратиться к Ган'рулу, чтобы получить компоненты для ритуала и узнать точные заклинания, позволяющие покорить призванное существо, пока оно не поглотило своего хозяина."}},faq={{q="Кто такой Ган'рул Кровавый Глаз?",a="Ган'рул Кровавый Глаз — орк-учитель чернокнижников в Оргриммаре. Он наставляет начинающих и опытных чернокнижников Орды, обучая их призывать и подчинять демонов из Круговерти Пустоты.",al={"gan'rul bloodeye","who is ganrul","ganrul bloodeye role","ган'рул кровавый глаз","кто такой ган'рул","роль ган'рула кровавого глаза"}},{q="Где найти Ган'рула Кровавого Глаза?",a="Он находится в Расселине Теней — сети подземных пещер под Оргриммаром. Он стоит рядом с другими последователями темных искусств, вдали от главных улиц города.",al={"ganrul location","where is gan'rul bloodeye","where is cleft of shadow trainer","где ган'рул","где ган'рул кровавый глаз","где учитель в расселине теней"}},{q="Почему чернокнижники скрываются в Расселине Теней?",a="Вождь Тралл и шаманское общество новой Орды глубоко не доверяют магии скверны и демонической порче после былого порабощения орков. Чернокнижников терпят в Орде лишь из-за их пользы, но их занятия вытеснены в тень, чтобы не допустить волнений в обществе.",al={"why in caves","why hide warlocks","cleft of shadow lore","почему в пещерах","почему прячут чернокнижников","предания расселины теней"}},{q="Каких демонов помогает призывать Ган'рул?",a="Ган'рул проводит чернокнижников через ритуалы призыва и подчинения демона Бездны и суккубы. Выполнение его заданий доказывает, что призыватель обладает силой воли, необходимой для власти над этими исчадиями.",al={"demons ganrul teaches","ganrul demon quests","voidwalker succubus trainer","демоны ган'рула","задания ган'рула","демон бездны суккуба учитель"}},{q="Есть ли у Ган'рула известная семья?",a="У него общая фамилия с Хальгой Кровавый Глаз, но их точное родство открыто не описано.",al={"gan'rul relatives","halga bloodeye relative","родственники ган'рула","родственница хальга кровавый глаз"}},{q="Кто такой Страхад, о котором говорит Ган'рул?",a="Страхад Фарсан — искусный чернокнижник, живущий в Степях близ холмов Кабестана. Со временем Ган'рул отправляет многообещающих учеников к Страхаду для более серьезного обучения и новых испытаний.",al={"seeking strahad","who is strahad","strahad quest","поиски страхада","кто такой страхад","задание страхада"}}},fp="16,344,23.407.0,18.364.0,24.187.0,34.188.0,47.285.0,37.219.0,35.100.0,38.198.0"}
P.entries["npc:gann-stonespire"] = {n="Ганн Каменное Копье",s="Ганн Каменное Копье — обиженный тауренский кочевник, бродящий по дорогам южных Степей близ Бейл Модана. Изгнанный дворфами-землекопами с охотничьих угодий своего племени, он жаждет отомстить захватчикам раскопок.",h="Ганн Каменное Копье — обиженный тауренский кочевник, бродящий по дорогам южных Степей близ Бейл Модана.",kw={"bael modan","bael'dun","gann stonespire","prospector khazgorm","southern barrens","stonespire","бейл модан","бейл'дан","ганн каменное копье","геолог хазгорм","южные степи","каменное копье"},ang={["faction:Horde"]="Помощь Ганну дает Орде важную тактическую возможность остановить экспансию Альянса, закрепившегося в южных Степях.",["race:Tauren"]="Беда Ганна отражает общую борьбу кочующих тауренов, чьи исконные земли и священная почва раз за разом оскверняются чужими экспедициями Альянса."},sec={{t="Изгнанный из Бейл Модана",b="До того как дворфийская экспедиция из Стальгорна возвела крепость Бейл Модан, окрестные земли были исконной территорией и охотничьими угодьями племени Ганна Каменного Копья. Дворфы-шахтеры прогнали коренных тауренов с их земли кирками, огнестрельным оружием и тяжелыми машинами, отвергнув мирные предложения. Теперь Ганн разбил лагерь у пыльной дороги в южных Степях; он не желает молча отказаться от наследия и собирает путников, чтобы ударить по землекопам."},{t="Возвращение земли и диверсия",b="Поняв, что мирная дипломатия полностью провалилась, Ганн направляет оперативников Орды сломить власть дворфов над раскопками. Его месть нацелена на руководство экспедиции, прежде всего на геолога Хазгорма, а затем на превращение дворфийского взрывчатого порошка и боеприпасов во взрывное устройство. Взорвав его прямо под дворфийской летающей машиной, Ганн намерен лишить их технологического преимущества и вернуть честь своему изгнанному народу."}},faq={{q="Кто такой Ганн Каменное Копье?",a="Ганн Каменное Копье — тауренский воин, чье племя некогда жило на землях, которые ныне занимает дворфийская крепость Бейл Модан. Изгнанный после основания дворфами раскопок, он ждет у дороги в южных Степях, жаждя мести и возвращения родины своего народа.",al={"who is gann","gann stonespire lore","tauren outside bael modan","кто такой ганн","предания ганна каменного копья","таурен у бейл модана"}},{q="Почему Ганн воюет с дворфами Бейл Модана?",a="Дворфийская экспедиция Бейл'дан прибыла в южные Степи и силой изгнала местных тауренов с их исконных охотничьих угодий ради строительства крепости для раскопок. После того как дворфы отвергли все дипломатические попытки, Ганн решил разрушить их предприятие силой.",al={"why does gann hate dwarves","why attack bael modan","gann bael modan conflict","почему ганн ненавидит дворфов","почему нападать на бейл модан","конфликт ганна и бейл модана"}},{q="Каков план Ганна против раскопок?",a="Сначала Ганн заказывает убийство дворфийских надсмотрщиков, включая геолога Хазгорма, чтобы захватить записи о раскопках. Затем из украденных дворфийских боеприпасов и взрывчатки он организует сборку бомбы, чтобы уничтожить летающую машину экспедиции и подорвать их технологическое превосходство.",al={"gann's revenge plan","what does gann do","bael modan bomb","план мести ганна","что делает ганн","бомба бейл модан"}},{q="Где Ганн Каменное Копье разбивает лагерь?",a="Его можно найти бродящим по дороге к западу от Бейл Модана в южных Степях, у самой границы раскопок.",al={"where is gann","gann stonespire location","где ганн","где ганн каменное копье"}}},fp="15,239,25.485.0,24.466.1,23.308.0,47.289.0,43.297.1,41.134.0"}
P.entries["npc:gar-thok"] = {n="Га'Ток",s="Га'Ток — опытный орк-воин и командир форпоста в Колючем Холме в Дуротаре. Он сражался на горе Хиджал и пережил первую высадку Кул Тираса на побережье Дуротара, а теперь руководит местной обороной от людей-захватчиков и местных угроз. Он направляет молодых рекрутов Орды, выходящих из Долины Испытаний, защищать красные пустоши новой родины.",h="Га'Ток — опытный орк-воин и командир форпоста в Колючем Холме в Дуротаре.",kw={"daelin","durotar","gar'thok","garthok","kul tiras","nazgrel","razor hill","rexxar","tiragarde","даэлин","дуротар","га'ток","кул тирас","назгрел","колючий холм","рексар","тирагард"},ang={["class:Warrior"]="Как командир передовой, переживший и демонические легионы, и жестокие морские засады, Га'Ток ждет от воинов боевой стойкости и безоговорочного послушания.",["faction:Horde"]="Га'Ток следит, чтобы новобранцы всех рас Орды понимали шаткость своих новых земель, и посылает их отражать остатки захватчиков Альянса.",["race:Orc"]="Для молодых орков, покидающих Долину Испытаний, Га'Ток олицетворяет суровую, непреклонную дисциплину поколения ветеранов, проливавшего кровь на горе Хиджал ради победы за Дуротар."},sec={{t="Ветеран красных пустошей",b="Прежде чем обосноваться в Колючем Холме, Га'Ток защищал лагерь орков в апокалиптической битве на горе Хиджал. После Третьей войны он отправился в Дуротар с вождем Траллом и служил лейтенантом под началом Назгрела в первые дни строительства новой родины. Когда странник-мок'нафал Рексар впервые прибыл в Дуротар, именно Га'Ток предупредил его о свирепых свинобразах, нападавших на границы, и призвал повелителя зверей защитить хрупкое поселение."},{t="Пережить вторжение адмирала",b="Решимость Га'Тока была испытана, когда флот Кул Тираса верховного адмирала Даэлина Праудмура высадился на восточном побережье Дуротара. Находясь на дальнем сторожевом посту, Га'Ток видел, как его гарнизон был разгромлен и жестоко перебит морской пехотой. Хотя его отряд был уничтожен, он выжил. Память о внезапном нападении закрепила его бдительность против уцелевших морпехов, которые все еще занимают Крепость Тирагард и прибрежные обломки кораблей."},{t="Оборона Колючего Холма",b="Ныне Га'Ток руководит военной обороной центрального Дуротара из казарм Колючего Холма. Он не тратит времени на любезности и сразу поручает молодым воинам, шаманам и разведчикам Орды зачищать вражеские остатки култирасцев, возвращать спасенные припасы и находить военные приказы в прибрежных руинах. По его мнению, безопасность Дуротара далеко не гарантирована и требует постоянного давления на всех, кто оспаривает право Орды на эту землю."}},faq={{q="Кто такой Га'Ток?",a="Га'Ток — орк-офицер в Колючем Холме, организующий местный военный отпор врагам в Дуротаре. Он ветеран Третьей войны, служивший под началом Назгрела при основании Оргриммара.",al={"garthok lore","who is garthok","razor hill commander","предания га'тока","кто такой га'ток","командир колючего холма"}},{q="Где сражался Га'Ток до прибытия в Колючий Холм?",a="Он сражался в битве на горе Хиджал, защищая укрепления орков от Пылающего Легиона и Плети. Позже он служил на пограничном форпосте в Дуротаре и вместе с Рексаром подавлял первые набеги свинобразов.",al={"garthok past","garthok mount hyjal","garthok history","прошлое га'тока","га'ток гора хиджал","история га'тока"}},{q="Почему Га'Ток так ненавидит людей в Дуротаре?",a="Во время вторжения под командованием верховного адмирала Даэлина Праудмура моряки Кул Тираса устроили засаду на форпост Га'Тока на побережье и перебили его людей. Он пережил нападение и теперь стремится уничтожить оставшиеся лагеря морпехов.",al={"why garthok hates kul tiras","garthok humans","tiragarde keep garthok","почему га'ток ненавидит кул тирас","га'ток люди","крепость тирагард га'ток"}},{q="С какими угрозами Га'Ток посылает бороться искателей приключений?",a="Га'Ток посылает рекрутов сражаться с враждебными култирасскими моряками в Крепости Тирагард, возвращать припасы с прибрежных обломков кораблей, отражать вторгшихся свинобразов и находить приказы, оставленные людскими командирами.",al={"garthok quests","what does garthok want","razor hill quests","задания га'тока","что нужно га'току","задания колючего холма"}},{q="Каковы его отношения с Назгрелом и Траллом?",a="Га'Ток служил доверенным лейтенантом под началом Назгрела во время первых колонизационных экспедиций в Дуротаре, действуя непосредственно по власти вождя Тралла для защиты границ новообретенной земли.",al={"garthok nazgrel","garthok thrall","garthok rank","га'ток назгрел","га'ток тралл","звание га'тока"}},{q="Где можно найти Га'Тока?",a="Га'Ток стоит у главной сторожевой башни и казарм в Колючем Холме — центральном поселении Дуротара к югу от Оргриммара.",al={"garthok location","where is garthok","find garthok","где га'ток","где найти га'тока","га'ток локация"}}},fp="8,378,27.491.0,32.468.0,21.473.0,16.219.0,53.217.0,53.239.0,53.219.0,49.219.0,28.133.0"}
P.entries["npc:gart-mistrunner"] = {n="Гарт Вестник Туманов",s="Гарт Вестник Туманов — местный учитель друидов в Лагере Нараче на Плато Красного Облака. Он встречает начинающих тауренов, призванных Матерью-Землей, и ведет их через первые обряды магии природы.",h="Гарт Вестник Туманов — местный учитель друидов в Лагере Нараче на Плато Красного Облака.",kw={"camp narache","druid trainer","gart mistrunner","mistrunner","mulgore","red cloud mesa","tauren druid","лагерь нараче","учитель друидов","гарт вестник туманов","вестник туманов","мулгор","плато красного облака","тауренский друид"},ang={["class:Druid"]="Для тауренских друидов Гарт Вестник Туманов — самый первый наставник, формирующий их связь с дикой природой и дарами Матери-Земли.",["race:Tauren"]="Гарт воплощает возрождение древних друидических традиций Шу'хало, передавая наследственную мудрость молодежи Лагеря Нараче."},sec={{t="Наставник Плато Красного Облака",b="Охраняя Лагерь Нараче, Гарт Вестник Туманов воплощает древний путь друидов, возрожденный среди Шу'хало. Новых тауренских друидов направляют прямо к Гарту, как только они ступают на Плато Красного Облака, нередко с зеленой запиской, поручающей их его заботам. Под его терпеливым руководством молодые друиды учатся общаться с миром природы, черпать исцеляющие силы природы и лунное сияние Му'ши, чтобы лечить союзников и поражать угрозы земле."}},faq={{q="Кто такой Гарт Вестник Туманов?",a="Гарт Вестник Туманов — тауренский учитель друидов в Лагере Нараче на Плато Красного Облака в Мулгоре. Он обучает начинающих тауренских друидов первым заклинаниям и обрядам.",al={"who is gart","gart mistrunner lore","gart mistrunner","кто такой гарт","предания гарта вестника туманов","гарт вестник туманов"}},{q="Каким заклинаниям он учит недавно пробудившихся друидов?",a="Гарт знакомит новичков с основными способностями природы: учит ранним исцеляющим заклинаниям, таким как «Целительное прикосновение», и боевой магии природы, например «Лунный огонь».",al={"what does gart teach","gart mistrunner training","druid spells camp narache","чему учит гарт","обучение у гарта вестника туманов","заклинания друида лагерь нараче"}},{q="Какова его связь с кланом Вестников Туманов?",a="«Вестник Туманов» — просто фамилия Гарта. В преданиях нет племени Вестников Туманов и нет сведений о его родне; он известен лишь как учитель друидов Лагеря Нараче.",al={"mistrunner clan","who are mistrunners","клан вестников туманов","кто такие вестники туманов"}}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gath-ilzogg"] = {n="Гат'Илзогг",s="Гат'Илзогг — грозный орк-полководец клана Черной горы, командующий силами вторжения, занявшими Крепость Каменной Стражи в Красногорье. Под его жестоким руководством орки захватили крепость и начали разорительные набеги на городок Приозерье, из-за чего отчаявшийся мировой судья города срочно объявил награду за его голову.",h="Гат'Илзогг — грозный орк-полководец клана Черной горы, командующий силами вторжения, занявшими Крепость...",ang={["faction:Alliance"]="Победа над Гат'Илзоггом сломает хребет наступлению клана Черной горы, угрожающему Приозерью, и станет ответом на отчаянный призыв Мирового судьи Соломона.",["race:Orc"]="Гат'Илзогг воплощает старые воинственные порядки клана Черной горы под началом Темной Орды, не имеющие ничего общего с новой Ордой Тралла в Калимдоре."},sec={{t="The Scourge of Stonewatch",b="Гат'Илзогг повел свои отряды на север из Пылающих степей с приказом закрепить Красногорье за кланом Черной горы. Опираясь на мерзкое колдовство ренегата-человека, чернокнижника Морганта, отряд Гат'Илзогга разгромил защитников Крепости Каменной Стражи и занял господствующую высоту над всей округой. Из этого укрепленного оплота он руководит дерзкими набегами в долины и к мосту Приозерья, постепенно душа человеческое поселение. Он редко сражается один: рядом с ним всегда элитные стражи Черной горы и свирепый черный дракончик по имени Подпалина."},{t="Непрочная власть",b="Despite his conquest of Stonewatch, Gath'Ilzogg's victory created new complications. Morganth quickly turned on his former orcish allies, raising an army of Shadowhide gnolls under Lieutenant Fangore that prey on Blackrock patrols and human travelers alike. Concurrently, Magistrate Solomon placed an open bounty on the warlord's head, pleading for any Alliance mercenaries or adventurers to scale the ramparts of Stonewatch Keep and end Gath'Ilzogg's terror before the town falls entirely."}},faq={{q="Кто такой Гат'Илзогг?",a="Гат'Илзогг — орк-полководец из клана Черной горы. Он возглавляет авангард, вторгшийся в Красногорье и захвативший у Альянса Крепость Каменной Стражи.",al={"gath'ilzogg lore","who is gathilzogg","blackrock boss redridge","гат'илзогг предания","кто такой гат'илзогг","босс черной горы красногорье"}},{q="Где найти Гат'Илзогга?",a="Он укрепился на самой вершине Крепости Каменной Стражи в восточных скалах Красногорья.",al={"gath'ilzogg location","where is gathilzogg","find gathilzogg","гат'илзогг местоположение","где гат'илзогг","найти гат'илзогга"}},{q="Почему у Гат'Илзогга есть дракончик?",a="Гат'Илзогга сопровождает черный дракончик по имени Подпалина. Считается, что это дар лорда Виктора Нефария в награду полководцу за успешный захват Крепости Каменной Стражи.",al={"why whelp next to gathilzogg","singe dragon","black dragon whelp gathilzogg","почему дракончик рядом с гат'илзоггом","подпалина дракон","черный дракончик гат'илзогг"}},{q="Почему за его голову назначена награда?",a="Magistrate Solomon of Lakeshire posted a high-priority bounty for Gath'Ilzogg's head because the warlord's constant raids and occupation of Stonewatch directly threaten Lakeshire with complete destruction.",al={"wanted gath'ilzogg","who wants gathilzogg dead","magistrate solomon bounty","разыскивается гат'илзогг","кто хочет смерти гат'илзогга","награда мирового судьи соломона"}},{q="Что произошло между Гат'Илзоггом и Моргантом?",a="The human warlock Morganth initially aided Gath'Ilzogg with dark magic to conquer Stonewatch. However, once the fortress fell, Morganth betrayed the orcs and raised an army of Shadowhide gnolls to attack both humanity and the Blackrock clan.",al={"morganth gathilzogg alliance","why are gnolls attacking orcs","morganth betrayal","моргант гат'илзогг союз","почему гноллы нападают на орков","предательство морганта"}}},fp="11,321,25.571.0,14.490.1,19.167.0,31.108.0,41.182.0,34.205.0,47.241.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="Гаксим Ржавошиппи",s="Гаксим Ржавошиппи — честолюбивый гном-ученый и механик, расквартированный в небольшом лагере Альянса на Паучьем тракте в Когтистых горах. Представитель Просвещенной Ассамблеи Чародейства, Алхимии и Технических Наук, он стремится доказать скептически настроенным ночным эльфам, что передовое искусство механики и алхимия способны сохранить их лесное царство. Научное любопытство сочетается в нем с яростной враждой к разрушительной деятельности Торговой Компании.",h="Гаксим Ржавошиппи — честолюбивый гном-ученый и механик, расквартированный в небольшом лагере Альянса на...",kw={"assembly","gaxim","gnome","kaela","rustfizzle","stonetalon","venture company","webwinder","windshear","ассамблея","гаксим","гном","кела","ржавошиппи","когтистые горы","торговая компания","паучий тракт","утес ветрорезов"},ang={["faction:Alliance"]="Расположившись на опасном Паучьем тракте, Гаксим выполняет важные задачи разведки, сбора сведений и саботажа, чтобы сдержать агрессивное промышленное вторжение в Когтистые горы.",["profession:Engineering"]="Гаксим применяет инженерные принципы на практике, разрабатывая тайные операции и тактические устройства, рассчитанные на то, чтобы выводить из строя грубые машины Торговой Компании.",["race:Gnome"]="Гаксим — образец гномьей академической гордости: он показывает древним культурам Калимдора, что шестеренки и реагенты могут спасти лес не хуже магии природы.",["race:NightElf"]="Хотя приверженцы традиций могут посмеиваться над его жужжащими устройствами и булькающими флаконами, Гаксим — верный союзник, активно защищающий границы Ясеневого леса и Когтистых гор от гоблинской индустрии."},sec={{t="Посланник науки",b="Хотя ночные эльфы традиционно полагаются на древнее друидизм и магию природы, Гаксим Ржавошиппи прибыл в скалистые ущелья Когтистых гор, чтобы показать совершенно иной взгляд. Представляя Просвещенную Ассамблею Чародейства, Алхимии и Технических Наук, он искренне верит, что точные механизмы и химические растворы способны защитить и возродить дикие земли Калимдора не хуже молитв Элуне. Разбив лагерь рядом с часовой Келой Копье Тени на Паучьем тракте, он неустанно убеждает своих высоких, замкнутых союзников в пользе инженерного дела для природы."},{t="Саботаж пил",b="Значительная часть энергии Гаксима направлена против Торговой Компании, чьи сплошные вырубки и промышленная алчность оскверняют соседний Утес Ветрорезов. Полагая, что грубые гоблинские машины не заслуживают ни уважения, ни пощады, Гаксим организует тайные операции и взрывоопасный химический саботаж против их лесозаготовок. Для него вывести из строя их крошшеры и выкрасть чертежи — не просто тактическая война, а наглядное доказательство того, что превосходный гномий разум всегда побеждает беспечный корпоративный грабеж."}},faq={{q="Кто такой Гаксим Ржавошиппи?",a="Гаксим Ржавошиппи — гном-ученый и изобретатель, расквартированный на дозорном посту Альянса на Паучьем тракте в Когтистых горах. Он служит посланником Просвещенной Ассамблеи Чародейства, Алхимии и Технических Наук.",al={"who is gaxim","gaxim rustfizzle lore","gnome in stonetalon","кто такой гаксим","гаксим ржавошиппи предания","гном в когтистых горах"}},{q="Что такое Просвещенная Ассамблея Чародейства, Алхимии и Технических Наук?",a="Это академическое и научное общество гномов, посвященное соединению тайной магии, алхимических смесей и механической инженерии. Гаксим представляет их идеалы за пределами родины, в Калимдоре.",al={"enlightened assembly","gaxim faction","gaxim group","просвещенная ассамблея","фракция гаксима","группа гаксима"}},{q="Почему Гаксим работает с ночными эльфами?",a="Гаксим хочет показать ночным эльфам, что гномья наука и алхимия способны активно защищать и исцелять лесные земли, предлагая современный ответ Альянса на вопрос охраны лесов наряду с традиционным друидизмом.",al={"why is gaxim here","gaxim night elves","gaxim purpose","почему гаксим здесь","гаксим ночные эльфы","цель гаксима"}},{q="Почему Гаксим ненавидит Торговую Компанию?",a="Торговая Компания безжалостно вырубает Утес Ветрорезов грубыми машинами и токсичными выбросами. Гаксим презирает их безрассудную эксплуатацию и с удовольствием обращает против них взрывоопасные химикаты и саботаж.",al={"gaxim venture co","gaxim vs venture company","why fight venture co","гаксим торговая компания","гаксим против торговой компании","почему бороться с торговой компанией"}},{q="Кто стоит лагерем с Гаксимом на Паучьем тракте?",a="Свой небольшой лагерь он делит с Келой Копье Тени, часовой из ночных эльфов, которая следит за тропами, ведущими к Утесу Ветрорезов.",al={"gaxim companion","who is with gaxim","gaxim and kaela","спутник гаксима","кто с гаксимом","гаксим и кела"}},{q="Где найти Гаксима Ржавошиппи?",a="Он находится в скромном лагере Альянса на Паучьем тракте, к юго-западу от промышленных лесозаготовок Утеса Ветрорезов в Когтистых горах.",al={"gaxim location","where is gaxim","gaxim rustfizzle map","гаксим местоположение","где гаксим","гаксим ржавошиппи карта"}}},fp="16,465,21.595.0,19.523.0,24.238.0,81.204.0,42.216.0,40.225.0,43.126.0,36.158.0"}
P.entries["npc:gazin-tenorm"] = {n="Газин Тенорм",kw={"cathedral of light","defias","duthorian rall","gazin tenorm","henze faulk","paladin","tome of divinity","собор света","братство справедливости","даториан ралл","газин тенорм","хенз фолк","паладин","фолиант божественности"},ang={["class:Paladin"]="Новички, постигающие пути сострадания и искупления, встречают Газина в Соборе Света, чтобы помочь его павшему брату по оружию, Хензу Фолку.",["race:Dwarf"]="Газин олицетворяет прочную солидарность Стальгорна и Штормграда: дворф-воитель, готовый сразиться с разбойниками Элвиннского леса по поручению советников королевства."},sec={{t="Разведчик в Соборе",b="Хотя Газин Тенорм проводит дни в тихих залах Собора Света, мыслями он остается в глуши Элвиннского леса. Газин и его близкий друг Хенз Фолк отправились в лес с неотложным поручением: собрать веские доказательства передвижений Братства Справедливости, чтобы представить их королевскому двору. Вылазка пошла прахом, когда на них напали из засады силы Братства. Газин едва спасся и вернулся в безопасный Штормград, но Хенз остался один в смертельной опасности, и Газин ищет стойкого героя Света, который поспешил бы на помощь его товарищу."}},faq={{q="Где найти Газина Тенорма?",a="Газина Тенорма можно найти в Соборе Света в Штормграде: он стоит у заднего алтаря рядом с высокопоставленными священнослужителями и наставниками-паладинами.",al={"gazin location","where is gazin tenorm","where is gazin","газин местоположение","где газин тенорм","где газин"}},{q="Что случилось с Газином Тенормом в Элвиннском лесу?",a="Расследуя деятельность Братства Справедливости вместе с товарищем Хензом Фолком, Газин попал в засаду разбойников. Ему удалось прорваться и бежать обратно в Штормград, но его друг остался в лесу.",al={"gazin story","what happened to gazin","why is gazin hurt","история газина","что случилось с газином","почему газин ранен"}},{q="Почему Газин расследовал деятельность Братства Справедливости?",a="Газин и Хенз Фолк отправились в Элвиннский лес, чтобы собрать неопровержимые доказательства преступной деятельности Братства Справедливости и представить их прямо советникам короля в Штормграде.",al={"why investigate defias","gazin mission","gazin henze defias","почему расследовать братство справедливости","миссия газина","газин хенз братство справедливости"}},{q="Как Газин связан с испытаниями паладинов?",a="Верховный паладин Даториан Ралл направляет к Газину начинающих паладинов-людей, ищущих Фолиант Божественности. Газин дает им средства и указания, как спасти его павшего товарища Хенза Фолка, проверяя доблесть и милосердие новичка.",al={"gazin tome of divinity","paladin quest gazin","henze faulk quest","газин фолиант божественности","задание паладина газин","задание хенз фолк"}}},fp="12,250,24.580.0,30.154.0,47.242.0,51.213.0,45.225.0"}
P.entries["npc:gazrog"] = {n="Газрог",s="Газрог — орк-воин, стоящий на посту на Перекрестке в самом сердце Степей. Отвечая за снабжение и безопасность на опасных дорогах саванны, он привлекает способных путников Орды к борьбе с местными угрозами и поискам пропавших патрулей.",h="Газрог — орк-воин, стоящий на посту на Перекрестке в самом сердце Степей.",kw={"barrens","crossroads","dogran","gazrog","horde outpost","raptor thieves","stolen silver","степи","перекресток","догран","газрог","застава орды","ящеры воры","украденное серебро"},ang={["faction:Horde"]="Газрог — один из первых, к кому обращаются искатели приключений Орды, покидающие Дуротар или Мулгор: он дает важную работу по созданию безопасных путей через Калимдор.",["race:Orc"]="Как орк-ветеран, держащий Перекресток, Газрог воплощает суровую, не терпящую излишеств выдержку, необходимую, чтобы обуздать непокорные рубежи Калимдора."},sec={{t="Страж Перекрестка",b="Перекресток — важнейший узел для всего транспорта Орды в Калимдоре, но его удаленность делает пути снабжения уязвимыми для разбойников и зверей. Газрог несет дозор вместе с защитниками поселения, следя за тем, чтобы грузы, деньги и гонцы доходили до цели. Поддержание порядка в бескрайней глуши требует постоянной бдительности, и Газрог сильно рассчитывает на проходящих искателей приключений, которые справляются с кризисами за стенами форпоста."},{t="Опасности саванны",b="Между хищными ящерами, тревожащими тропы, и агрессивными кланами свинобразов, нападающими на разведчиков, у Газрога дел всегда хватает. Он часто координирует ответ на грабежи на дорогах, например возвращение похищенных грузов Орды, и следит за пропавшими солдатами, как грунт Догран, оказавшийся раненым пленником свинобразов."}},faq={{q="Где найти Газрога?",a="Газрог находится на Перекрестке — центральном поселении, соединяющем северные, южные и восточные дороги Степей.",al={"gazrog location","where is gazrog","gazrog crossroads","газрог местоположение","где газрог","газрог перекресток"}},{q="Какую роль Газрог играет для Орды?",a="Он выступает как оперативный координатор и стражник Перекрестка: раздает задания по защите путей снабжения региона, возвращению перехваченных грузов и поискам пропавших бойцов Орды.",al={"gazrog job","who is gazrog","what does gazrog do","газрог должность","кто такой газрог","чем занимается газрог"}},{q="Что случилось с украденным серебром, о котором спрашивает Газрог?",a="Обозы Орды с деньгами часто становятся целью хитрых ящеров саванны и проходимцев, бродящих по тропам Степей, и Газрог посылает героев выследить зверей и вернуть груз.",al={"stolen silver quest","who stole the silver","barrens stolen shipment","задание украденное серебро","кто украл серебро","украденный груз степи"}},{q="Кто такой Догран?",a="Догран — грунт Орды, направленный на Перекресток в помощь Газрогу. Он не вернулся с задания: Газрог слышал, что он жив, но ранен и удерживается свинобразами в плену, и предпочел бы скрыть эти вести от подруги Дограна, Занкайи.",al={"news of dogran","where is dogran","gazrog dogran","вести о догране","где догран","газрог догран"}},{q="Связан ли Газрог с Кабестаном или гоблинами?",a="Нет. Газрог служит непосредственно Орде на Перекрестке, обеспечивая безопасность интересов орков, тауренов и троллей в центральных Степях.",al={"is gazrog ratchet","gazrog faction","gazrog goblin","газрог кабестан","фракция газрога","газрог гоблин"}},{q="Почему ящеры крадут припасы в Степях?",a="Точно никто не знает. Ящеры спрятали украденное серебро в своих гнездах в Землях Ящеров к югу от Кабестана, и Газрог задумывается, не ближе ли к истине рассказы об их разуме, чем он думал.",al={"raptor thieves why","do raptors steal things","raptors shiny","почему ящеры воры","крадут ли ящеры вещи","ящеры блестящее"}}},fp="6,258,28.475.0,16.330.0,26.129.0,41.187.0,53.196.0,14.237.0,49.145.0,49.211.0"}
P.entries["npc:gelbin-mekkatorque"] = {n="Гелбин Меггакрут",s="Гелбин Меггакрут — главный механик гномов, ныне живущий в изгнании в Городе механиков в Стальгорне. Известный как гениальный инженер, чьи изобретения включают механошагов и Подземный поезд, теперь он несет тяжкое бремя падения Гномрегана и руководит усилиями по возвращению родного дома своего народа.",h="Гелбин Меггакрут — главный механик гномов, ныне живущий в изгнании в Городе механиков в Стальгорне.",kw={"deeprun tram","gelbin","gnome","gnomeregan","high tinker","ironforge","mechanostrider","mekkatorque","thermaplugg","tinker town","подземный поезд","гелбин","гном","гномреган","главный механик","стальгорн","механошаг","меггакрут","термоштепсель","город механиков"},ang={["profession:Engineering"]="Встретить главного механика — значит встретить автора механошага, гироматического микрорегулятора и Подземного поезда. Его мастерская в Городе механиков — передний край технических новаторств.",["race:Gnome"]="Меггакрут — сердце вашего народа в изгнании. Хотя вина за отравление Гномрегана тяготит его, его гений и стремление освободить ваш родной дом вызывают абсолютную преданность в Городе механиков."},sec={{t="Главный механик и великий изобретатель",b="Гномы выбирают лидеров по уму и заслугам, а не по происхождению, и Гелбин Меггакрут стал главным механиком благодаря изобретательскому гению. Выпускник Университета Шестерни, он совершил переворот в личном транспорте, создав первого действующего механошага. За десятилетия работы он разработал гироматический микрорегулятор, автоматических ремонтных ботов и вместе с дворфами Бронзобородами создал их грозные осадные машины. Когда после Второй войны Штормграду понадобилось быстрое сообщение со Стальгорном, король Магни Бронзобород обратился к Меггакруту, который лично начертил схемы и руководил строительством Подземного поезда."},{t="Предательство и изгнание в Стальгорне",b="Величайшая трагедия Меггакрута случилась, когда трогги вторглись в Гномреган из глубин. По настоянию своего верного друга и главного советника, Сикко Термоштепселя, Меггакрут приказал выпустить радиоактивные отходы в нижние коридоры, чтобы уничтожить захватчиков. Но ядовитый газ погубил тысячи ни в чем не повинных гномов и обратил выживших в мутантов, а Термоштепсель захватил разрушенный город. Раздавленный чувством вины, но решивший исправить свою ошибку, Меггакрут повел уцелевших беженцев через Дун Морог в Стальгорн. Работая в Городе механиков по милости короля Магни, главный механик направляет военные и научные силы гномов к одной неизменной цели — освобождению Гномрегана."}},faq={{q="Кто такой Гелбин Меггакрут?",a="Гелбин Меггакрут — избранный главный механик и лидер гномов. Он мастер-инженер, создавший важнейшие гномьи технологии, в том числе механошагов, ремонтных ботов и Подземный поезд.",al={"high tinker","gnome leader","who is the gnome king","главный механик","лидер гномов","кто король гномов"}},{q="Почему Меггакрут в Стальгорне, а не в Гномрегане?",a="Гномреган захлестнуло жестокое вторжение троггов, а затем катастрофическое радиоактивное заражение. Меггакрут возглавил эвакуацию своего народа через Дун Морог в Стальгорн, где король Магни Бронзобород приютил гномов в Городе механиков, пока строятся планы по возвращению города.",al={"why is mekkatorque in ironforge","why are gnomes in ironforge","gnomeregan fall","почему меггакрут в стальгорне","почему гномы в стальгорне","падение гномрегана"}},{q="Что вызвало катастрофу в Гномрегане?",a="Перед бесконечными волнами троггов Меггакрут по совету доверенного советника решил выпустить ядовитый радиоактивный хладагент в нижние залы, чтобы остановить тварей. К несчастью, газ не остановил троггов, а лишь заразил город радиацией, убив тысячи гномов.",al={"what happened to gnomeregan","why is gnomeregan irradiated","thermaplugg betrayal","что случилось с гномреганом","почему гномреган заражен","предательство термоштепселя"}},{q="Что изобрел Меггакрут до того, как стал главным механиком?",a="Меггакрут изобрел механошага, подарив гномам собственное проворное верховое животное. Он также создал гироматический микрорегулятор, ремонтных ботов, схемы Подземного поезда между Стальгорном и Штормградом и участвовал в разработке дворфийской осадной машины.",al={"mekkatorque inventions","what did gelbin build","изобретения меггакрута","что построил гелбин"}},{q="Меггакрут — настоящий король?",a="У гномов нет наследственной монархии; их лидер — избранный главный механик, выбираемый за заслуги и интеллектуальные достижения. Его титул и власть происходят от избрания главным механиком.",al={"is mekkatorque a king","king of gnomes","меггакрут король","король гномов"}}},fp="18,326,35.716.0,31.706.1,26.203.0,54.282.0,42.264.0,56.249.0,30.191.0"}
P.entries["npc:gelihast"] = {n="Гелихаст",s="Гелихаст — свирепый вождь мурлоков с двумя клинками, обитающий в Пруду Аск'ара в Непроглядной Пучине. Привлеченный темным шепотом Древних богов, он прорубил себе путь в руины затонувшего храма и добился неохотного уважения культистов Сумеречного Молота.",h="Гелихаст — свирепый вождь мурлоков с двумя клинками, обитающий в Пруду Аск'ара в Непроглядной Пучине.",kw={"blackfathom deeps","blindlight","gelihast","murloc","old gods","pool of ask'ar","twilight's hammer","непроглядная пучина","слепосвет","гелихаст","мурлок","древние боги","пруд аск'ара","сумеречный молот"},ang={["class:Warrior"]="Гелихаст атакует с ослепительной скоростью клинков; умелые воины, подготовившись, могут обратить его неистовый натиск с двумя клинками целиком против него самого.",["faction:Alliance"]="Силам Альянса, стремящимся очистить скверну, просачивающуюся в Ясеневый лес, необходимо убрать Гелихаста, чтобы обезопасить северные проходы затонувшего храма.",["faction:Horde"]="Искатели приключений Орды, посланные прочесать Непроглядную Пучину, должны уничтожить Гелихаста, чтобы разрушить союз культистов, гнездящийся под Зорамским взморьем."},sec={{t="Смертоносный зов",b="Большинство мурлоков держится прибрежных мелководий, но Гелихаст ощутил темный, зловещий зов Древних богов из глубин под Ясеневым лесом. Влекомый этим первобытным шепотом, он пробился в затонувший храм Непроглядной Пучины. Когда культисты Сумеречного Молота попытались его остановить, он в одиночку перебил почти дюжину из них своими двумя мечами."},{t="Повелитель Слепосвета",b="Вместо мести культисты восхитились дикой свирепостью Гелихаста и отдали ему во власть Пруд Аск'ара. Там, в окружении своего выводка Слепосвета, кровожадный мурлок соорудил грубый алтарь. На нем он совершает мрачные жертвоприношения, получая темные дары от гнусного существа, дремлющего в бездне."}},faq={{q="Кто такой Гелихаст?",a="Гелихаст — жестокий вождь мурлоков, командующий племенем Слепосвета в Пруду Аск'ара в Непроглядной Пучине. Он сражается двумя клинками и служит темному существу, обитающему в руинах.",al={"who is gelihast","gelihast lore","gelihast background","кто такой гелихаст","гелихаст предание","гелихаст история"}},{q="Почему Гелихаст находится в Непроглядной Пучине?",a="Его привлек шепот Древних богов. Желая добраться до источника темного зова, он вторгся в руины и проложил кровавый путь через местных культистов, чтобы занять собственные владения.",al={"why is there a murloc in bfd","why is gelihast in the temple","почему в непроглядной пучине мурлок","почему гелихаст в храме"}},{q="Как Сумеречный Молот отреагировал на него?",a="Хотя Гелихаст перебил почти дюжину культистов Сумеречного Молота, войдя в храм, выжившие были так впечатлены его свирепостью и жестокостью, что позволили ему остаться и поклоняться вместе с ними.",al={"gelihast and twilights hammer","do cultists like gelihast","гелихаст и сумеречный молот","нравится ли культистам гелихаст"}},{q="Что за алтарь стоит за Гелихастом?",a="Гелихаст возвел святилище, чтобы приносить кровавые жертвы зловещему существу в руинах. Путники, победившие его, могут коснуться алтаря и получить благословение Непроглядной пучины.",al={"altar of the deep","gelihast altar","blessing of blackfathom altar","алтарь глубин","алтарь гелихаста","благословение непроглядной пучины алтарь"}},{q="Каким племенем мурлоков он правит?",a="Он возглавляет мурлоков Слепосвета — агрессивное племя, наводнившее Пруд Аск'ара в пещерах.",al={"gelihast tribe","what murlocs are in bfd","племя гелихаста","какие мурлоки в непроглядной пучине"}},{q="Что будет с Гелихастом, если его не остановить?",a="Он продолжит приносить жертвы на своем алтаре в Пруду Аск'ара, оставаясь жестоким исполнителем и фанатичным слугой темных ужасов, наводнивших руины.",al={"gelihast fate","who kills gelihast","судьба гелихаста","кто убивает гелихаста"}}},fp="8,284,16.355.0,24.334.0,16.204.0,41.193.0,43.217.0,34.177.0,35.104.0,49.163.0"}
P.entries["npc:gelkak-gyromast"] = {n="Гелхак Гиромачт",s="Гелхак Гиромачт — гном, говорящий как пиратский капитан, оказавшийся на мели на туманном берегу Туманного Предела на севере Темных берегов. Его корабль потопили жесткозубы, и он хочет починить своего механического первого помощника — Бешенатор 4100.",h="Гелхак Гиромачт — гном, говорящий как пиратский капитан, оказавшийся на мели на туманном берегу Туманного...",kw={"darkshore","gelkak gyromast","gnome inventor","mathystra","mist's edge","threshwackonator 4100","темные берега","гелхак гиромачт","гном-изобретатель","матистра","туманный предел","бешенатор 4100"},ang={["profession:Engineering"]="Положение Гелхака — классическая история гнома вдали от дома, возлагающего надежды на месть на устройство, столь впечатляющее, как Бешенатор 4100.",["race:Gnome"]="Встреча с собратом-гномом, оказавшимся на краю Калимдора, ярко напоминает, как далеко от дома могут занести гнома его приключения."},sec={{t="Потерпевший крушение на Туманном Пределе",b="Гелхак Гиромачт, обосновавшийся на пустынном северном побережье Темных берегов к западу от древних Руин Матистры, выглядит странно среди мрачных ночных берегов эльфов ночи. Говоря как старый морской волк, самопровозглашенный капитан потерял корабль из-за жесткозубов недалеко от берега. Когда его выбросило на туманный песок, ключ к его механическому первому помощнику, Бешенатору 4100, разбился о камни, а обломки растащили крабы, лесные ходоки и мурлоки, копавшиеся в обломках."},{t="Неисправность Бешенатора",b="Когда искатели приключений находят ключ, Гиромачт посылает их включить его первого помощника и привести к нему, стремясь натравить его на мурлоков и зверей побережья. Бешенатор 4100 послушно следует за ними, но как только добирается до капитана, дает сбой и становится враждебным, и героям приходится его уничтожить."}},faq={{q="Кто такой Гелхак Гиромачт?",a="Гелхак Гиромачт — эксцентричный гном, говорящий как пиратский капитан, оказавшийся на мели на северном пляже Темных берегов, известном как Туманный Предел, к западу от Руин Матистры.",al={"gelkak","who is gelkak","gyromast","гелхак","кто такой гелхак","гиромачт"}},{q="Почему Гелхак застрял на Темных берегах?",a="Его корабль потопили недалеко от берега жесткозубы, и его выбросило на пустынное северное побережье со сломанным ключом от механического первого помощника.",al={"why is gelkak here","gelkak darkshore","почему гелхак здесь","гелхак темные берега"}},{q="Что такое Бешенатор 4100?",a="Бешенатор 4100 — механическое творение Гелхака и его самопровозглашенный первый помощник. Гелхак хочет вернуть его в рабочее состояние, чтобы тот отомстил мурлокам и зверям побережья.",al={"threshwackonator","gelkak machine","robot","бешенатор","машина гелхака","робот"}},{q="Какая помощь нужна Гелхаку от путников?",a="Гелхак просит способных искателей приключений добыть три части сломанного ключа у крабов, лесных ходоков и мурлоков побережья, а затем с его помощью запустить Бешенатора 4100 и привести его к нему.",al={"gelkak quests","gyromast quests","задания гелхака","задания гиромачта"}}},fp="15,271,23.509.0,32.325.1,23.173.0,36.145.0,34.186.0,42.209.0"}
P.entries["npc:general-marcus-jonathan"] = {n="Генерал Маркус Джонатан",s="Генерал Маркус Джонатан — верховный командующий обороной Штормграда, расположившийся прямо у ворот в Аллее Героев. Ветеран Второй войны, он руководит гарнизоном, защищающим столицу, и занимается военными запросами пограничных поселений королевства.",h="Генерал Маркус Джонатан — верховный командующий обороной Штормграда, расположившийся прямо у ворот в Аллее...",kw={"general jonathan","lakeshire","magistrate solomon","marcus jonathan","reginald windsor","stormwind army","stormwind defense","valley of heroes","генерал джонатан","приозерье","магистрат соломон","маркус джонатан","реджинальд винздор","армия штормграда","оборона штормграда","аллея героев"},ang={["class:Warrior"]="Как верховный командующий воротами Штормграда и ветеран Второй войны, Джонатан воплощает вершину обычного воинского долга в рядах пехоты королевства.",["faction:Alliance"]="Маркус Джонатан воплощает воинскую гордость Штормграда у ворот столицы."},sec={{t="Командующий у ворот",b="Верхом на коне в Аллее Героев генерал Маркус Джонатан стоит на первой линии обороны и является высшим военным офицером, надзирающим за городскими воротами. Он сражался во Второй войне вместе с такими известными солдатами, как Реджинальд Винздор, под командованием генерала Туралиона. В это время растущего напряжения Джонатану приходится сочетать безопасность столицы со все более отчаянными просьбами о помощи от пограничных городов вроде Приозерья."},{t="Напряженное командование",b="Пока такие города, как Приозерье, умоляют прислать штормградских солдат для отпора оркам Черной горы и гноллам, Джонатан заверяет местных магистратов в своей готовности помочь, но втайне признается, что двор отдалился, а регентство при юном короле ведет себя странно."}},faq={{q="Где найти генерала Маркуса Джонатана?",a="Он стоит верхом сразу за главными воротами Штормграда, наблюдая за входным мостом в Аллее Героев.",al={"marcus jonathan location","where is general jonathan","stormwind gate commander","где маркус джонатан","где генерал джонатан","командующий воротами штормграда"}},{q="Какова военная история Маркуса Джонатана?",a="Маркус Джонатан — ветеран, служивший под началом генерала Туралиона во время Второй войны. Он сражался бок о бок с такими товарищами, как Реджинальд Винздор, прежде чем стать верховным командующим обороной Штормграда.",al={"marcus jonathan past","marcus jonathan lore","did marcus fight in the second war","прошлое маркуса джонатана","предание маркуса джонатана","сражался ли маркус во второй войне"}},{q="Что за монета в фонтане Даларана?",a="Будучи молодым рядовым, посетив Даларан, Маркус Джонатан бросил в фонтан медную монету, загадав однажды отрастить великолепные густые усы — и его выдающаяся растительность на лице подтверждает, что желание сбылось.",al={"marcus jonathan coin","dalaran fountain coin marcus","монета маркуса джонатана","монета в фонтане даларана маркус"}}},fp="23,272,22.465.0,18.256.1,41.132.0,43.215.0,47.208.0"}
P.entries["npc:gerard-tiller"] = {n="Джерард Румпель",s="Джерард Румпель — жаждущий батрак-человек, работающий возле амбара на Виноградниках Маклура в Элвиннском лесу. Ухаживая за виноградниками под жарким солнцем, он всегда готов обменять спелое красное яблоко любому путнику, который поделится бурдюком освежающей ключевой воды.",h="Джерард Румпель — жаждущий батрак-человек, работающий возле амбара на Виноградниках Маклура в Элвиннском лесу.",kw={"elwynn forest","gerard tiller","give gerard a drink","maclure vineyards","refreshing spring water","shiny red apple","элвиннский лес","джерард румпель","напоить джерарда","виноградники маклура","освежающая ключевая вода","спелое красное яблоко"},ang={["profession:Cooking"]="Готовность Джерарда обменивать свежие яблоки на простую ключевую воду делает его удобным источником фруктов для странствующих поваров, которым нужны простые ингредиенты."},sec={{t="Жаждущий батрак",b="Джерард Румпель проводит дни в трудах на полях и ухаживает за землей возле амбара на Виноградниках Маклура. Виноградники расположены к югу от Златоземья и дают один из самых известных в Элвинне сортов винограда, но уборка урожая — тяжелый труд. Румпеля постоянно мучает жажда, поэтому он охотно меняется с проходящими мимо искателями приключений. Если кто-то предложит ему свежий бурдюк прохладной ключевой воды, он с радостью отплатит за любезность спелыми красными яблоками, собранными прямо в местных садах."}},faq={{q="Кто такой Джерард Румпель?",a="Джерард Румпель — батрак-человек, работающий возле амбара на Виноградниках Маклура в южной части Элвиннского леса.",al={"gerard tiller identity","who is gerard","tiller elwynn","джерард румпель кто такой","кто такой джерард","румпель элвиннский лес"}},{q="Где найти Джерарда Румпеля?",a="Он стоит прямо у большого деревянного амбара на Виноградниках Маклура, к югу от Златоземья и к востоку от Фермы Стоунфилдов.",al={"gerard tiller location","where is gerard","find gerard elwynn","джерард румпель где находится","где джерард","найти джерарда элвиннский лес"}},{q="Чем торгует Джерард Румпель?",a="Джерард отдает спелое красное яблоко любому путнику, который принесет ему бурдюк освежающей ключевой воды, чтобы утолить жажду.",al={"gerard apple trade","gerard tiller water","what does gerard want","джерард обмен яблок","джерард румпель вода","что нужно джерарду"}},{q="Участвует ли Джерард во вражде Маклюров и Стоунфилдов?",a="Нет. Хотя он работает на Виноградниках Маклура, Джерард занят своими делами и тем, чтобы не мучиться от жажды, а не вмешивается в семейную вражду Маклюров и Стоунфилдов.",al={"gerard tiller feud","maclure feud gerard","джерард румпель вражда","вражда маклюров джерард"}}},fp="13,272,18.515.0,21.112.0,31.131.0,30.118.0,60.175.0"}
P.entries["npc:gerrig-bonegrip"] = {n="Геррик Костохват",s="Геррик Костохват — скромный торговец-дворф, обосновавшийся в мрачных коридорах Одинокой пещеры Стальгорна. За прилавком лавки «Руны и погибели Костохвата» он тихо покупает и продает эзотерические тексты о темных ритуалах и забытых древних силах.",h="Геррик Костохват — скромный торговец-дворф, обосновавшийся в мрачных коридорах Одинокой пещеры Стальгорна.",kw={"blackfathom deeps","bonegrip","forlorn cavern","gerrig","ironforge","lorgalis manuscript","runes and dooms","непроглядная пучина","костохват","одинокая пещера","геррик","стальгорн","манускрипт лоргалиса","руны и погибели"},ang={["class:Warlock"]="Для чернокнижников, бывающих в темных уголках Одинокой пещеры, собрание эзотерических ритуалов и темных томов Костохвата — удобный источник опасных знаний.",["race:Dwarf"]="Видеть, как собрат-дворф клянется в верности апокалиптическим сущностям Древних богов в самом сердце залов Стальгорна, — горькое напоминание о том, как глубоко может проникнуть Сумеречный Молот."},sec={{t="«Руны и погибели Костохвата»",b="В тусклых закоулках Одинокой пещеры Геррик Костохват кажется большинству горожан просто эксцентричным торговцем странными реликвиями и запретными знаниями. Однако его скромная лавка служит куда более темной цели. Костохват — активный член нигилистического культа Сумеречного Молота и использует свою лавку, чтобы собирать опасные рукописи и малоизвестные тексты о Древних богах прямо под носом у Сената Стальгорна и Высокого трона."},{t="Сбор запретных знаний",b="Геррик активно вербует ничего не подозревающих авантюристов Альянса, чтобы они добывали древние артефакты, например Манускрипт Лоргалиса, затерянный в глубинах Непроглядной Пучины. Когда эти реликвии попадают к нему в руки, он переписывает и распространяет кощунственные знания среди собратьев по культу по всему Азероту. Через тайные связи с темными личностями вроде Скуэрто и с теми, кто имеет дело с древними первородными существами, такими как Мизраэль, Костохват неустанно трудится над воплощением апокалиптических замыслов культа."}},faq={{q="Кто такой Геррик Костохват?",a="Gerrig Bonegrip is a dwarf running Bonegrip's Runes and Dooms in Ironforge's Forlorn Cavern. He deals in eccentric curiosities and obscure texts concerning ancient rituals.",al={"who is bonegrip","gerrig bonegrip lore","bonegrip ironforge","кто такой костохват","геррик костохват предыстория","костохват стальгорн"}},{q="Что он делает с Манускриптом Лоргалиса?",a="He seeks the Lorgalis Manuscript from Blackfathom Deeps for his collection of rare texts. Further investigation can uncover more about his use of it.",al={"why does bonegrip want lorgalis manuscript","knowledge in the deeps turn in","lorgalis manuscript use","зачем костохвату манускрипт лоргалиса","знания в пучине сдать","манускрипт лоргалиса применение"}},{q="How does Gerrig operate in Ironforge?",a="Gerrig maintains a low profile as an eccentric scholar and merchant in the Forlorn Cavern, where he buys and sells obscure texts.",al={"does ironforge know bonegrip is a cultist","why is bonegrip allowed in ironforge","знает ли стальгорн что костохват культист","почему костохвата терпят в стальгорне"}},{q="Как он связан с Мизраэлем?",a="Геррик — давний знакомый дворфа Скуэрто, который изучает запечатанного элементаля земли Мизраэля на Нагорье Арати. Благодаря этим связям Геррик помогает организовывать задачи, связанные с древними ритуалами заточения и первородными силами.",al={"gerrig bonegrip and myzrael","skuerto and gerrig","геррик костохват и мизраэль","скуэрто и геррик"}}},fp="15,264,26.449.1,30.487.1,23.172.2,45.149.1,37.129.2,34.238.0"}
P.entries["npc:gershala-nightwhisper"] = {n="Гершал Шепот Ночи",s="Гершал Шепот Ночи — ночной эльф-исследователь, живущий в прибрежном поселении Аубердин на Темных берегах. Глубоко обеспокоенный путем, которым пошли высшие эльфы Кель'Таласа, он изучает образцы проклятых морских и демонических существ, чтобы понять, как магическая порча искажает разум и тело.",h="Гершал Шепот Ночи — ночной эльф-исследователь, живущий в прибрежном поселении Аубердин на Темных берегах.",kw={"auberdine","blackfathom","corruption","darkshore","gershala","naga","nightwhisper","satyr","аубердин","непроглядная","порча","темные берега","гершал","нага","шепот ночи","сатир"},ang={["faction:Alliance"]="Гершал — один из главных заказчиков, отправляющих экспедиции Альянса навстречу опасностям Непроглядной Пучины и следящих, чтобы их вылазки приносили ценные тайные знания.",["race:NightElf"]="Для ночных эльфов мрачные изыскания Гершал — острое напоминание о древнем Расколе и страшной цене магической зависимости, которая когда-то превратила их собратьев в чудовищ."},sec={{t="Изучение превращений",b="Мирно живя в Аубердине, Гершал Шепот Ночи смотрит дальше насущных прибрежных бед Темных берегов — на более широкую, подкрадывающуюся опасность. С тревогой наблюдая, как оставшиеся высшие эльфы обращаются к опасным тайным практикам и называют себя эльфами крови, Гершал стремится понять биологический и духовный упадок, который влечет за собой неограниченная магия. Чтобы раскрыть эти тайны, он отправляет опытных авантюристов Альянса в затопленные залы Непроглядной Пучины, чтобы добыть оскверненные стволы мозга у населяющих их наг и сатиров."},{t="Противоядие от гибели",b="Мрачный интерес Гершал к стволам мозга наг и сатиров объясняется их общим происхождением: обе расы когда-то были ночными эльфами, пока не поддались королеве Азшаре и демоническим сделкам. Изучая физические следы, оставленные на их нервной системе тысячелетиями демонических и бездонных энергий, он надеется найти предостережения или защиту, которые удержат других эльфийских сородичей от падения в подобное чудовищное уродство."}},faq={{q="Где находится Гершал Шепот Ночи?",a="Гершал Шепот Ночи находится в Аубердине — главном портовом городе Альянса на побережье Темных берегов.",al={"gershala location","where is gershala","find gershala nightwhisper","гершал где находится","где гершал","найти гершал шепот ночи"}},{q="Зачем Гершал нужны стволы мозга наг и сатиров?",a="Гершал изучает оскверненные стволы мозга, чтобы понять, как глубокое магическое и демоническое превращение меняет строение тела бывших ночных эльфов. Нага и сатиры когда-то были эльфами, и он хочет понять физические механизмы их порчи.",al={"why brain stems","researching the corruption lore","what does gershala study","зачем стволы мозга","исследование порчи","что изучает гершал"}},{q="На что Гершал надеется своими исследованиями?",a="Гершал надеется, что его исследования дадут важные сведения, которые не позволят эльфам крови выродиться в злое и чудовищное уродство из-за опасной зависимости от скверны и неограниченной тайной силы.",al={"gershala goal","why help blood elves","gershala research purpose","цель гершал","зачем помогать эльфам крови","смысл исследований гершал"}},{q="Где находятся нужные Гершал образцы?",a="Он отправляет искателей приключений в Непроглядную Пучину — древние затопленные руины храма на побережье Ясеневого леса, кишащие нагами и сатирами.",al={"where are the stems","blackfathom deeps stems","where to find gershala items","где стволы","стволы непроглядная пучина","где найти предметы гершал"}}},fp="21,311,23.550.0,19.411.0,37.111.0,50.251.0,56.201.0,47.138.0"}
P.entries["npc:ghamoo-ra-classic"] = {n="Гхаму-ра",s="Гхаму-ра — древняя гигантская морская черепаха, обитающая в Пруду Аск'ара в Непроглядной Пучине. Некогда мирный обитатель затонувшего храма Элуны, он был захвачен, замучен и доведен до безумия культом Сумеречного Молота, чтобы стать свирепым стражем.",h="Гхаму-ра — древняя гигантская морская черепаха, обитающая в Пруду Аск'ара в Непроглядной Пучине.",kw={"blackfathom deeps","elune","ghamoo-ra","pool of ask'ar","tame","turtle","twilight's hammer","непроглядная пучина","элуна","гхаму-ра","пруд аск'ара","приручение","черепаха","сумеречный молот"},ang={["class:Druid"]="Друиды считают муки Гхаму-ра и навязанную ему агрессию трагическим осквернением дикой природы слугами Древних богов.",["class:Hunter"]="Охотники, отправляющиеся в Непроглядную Пучину, могут пожалеть Гхаму-ра — благородного древнего зверя, сломленного темным пленом, хотя терпеливый охотник все же может его приручить.",["race:NightElf"]="Для ночных эльфов судьба Гхаму-ра — горькое напоминание об осквернении священного храма Элуны мерзким Сумеречным Молотом."},sec={{t="Замученный кроткий зверь",b="До осквернения Непроглядной Пучины Гхаму-ра был одним из последних мирных природных обитателей затопленных руин храма ночных эльфов, посвященного Элуне. Когда нигилистический культ Сумеречного Молота захватил святилище, он поднял древнюю черепаху с места ее тихой жизни и заточил в плену. Вместо убийства ее годами систематически мучили, подвергая душевным и телесным пыткам от рук культистов."},{t="Страж Пучины",b="Сломленная долгой жестокостью, великая черепаха в конце концов поддалась безумию. Дав изуродованному существу имя Гхаму-ра, культисты обучили его быть свирепым зверем-защитником. Теперь Гхаму-ра патрулирует небольшой остров в Пруду Аск'ара в окружении мелких черепах и слепо нападает на любых чужаков, входящих в пещеры, служа тому самому культу, что сокрушил его разум."}},faq={{q="Кто такой Гхаму-ра?",a="Гхаму-ра — гигантская черепаха, обитающая в Пруду Аск'ара в Непроглядной Пучине. Некогда мирный обитатель храма Элуны, он был захвачен, замучен и превращен культом Сумеречного Молота в свирепого сторожевого зверя.",al={"ghamoo-ra lore","giant turtle bfd","who is ghamoo ra","гхаму-ра предыстория","гигантская черепаха непроглядная пучина","кто такой гхаму ра"}},{q="Почему Гхаму-ра враждебен к чужакам?",a="Культ Сумеречного Молота заточил черепаху и мучил ее несколько лет, сломив ее дух и доведя до полного безумия. Ее приучили бросаться на любого чужака, приближающегося к внутренним святилищам.",al={"why is turtle angry","why does turtle attack","ghamoo-ra madness","почему черепаха злится","почему черепаха нападает","безумие гхаму-ра"}},{q="Может ли охотник приручить Гхаму-ра?",a="Да. Несмотря на размеры и годы мучений, Гхаму-ра может приручить умелый охотник.",al={"tame ghamoo-ra","can hunter tame bfd turtle","приручить гхаму-ра","может ли охотник приручить черепаху непроглядной пучины"}},{q="Что такое Пруд Аск'ара?",a="Пруд Аск'ара — затопленная подземная пещера в Непроглядной Пучине. Гхаму-ра бродит в центре небольшого острова, окруженного смирными местными черепахами.",al={"pool of ask'ar","where is ghamoo ra","пруд аск'ара","где гхаму ра"}},{q="Как он связан с Древними богами?",a="Хотя Гхаму-ра по своей природе не создание Бездны, его разум исказили культисты Сумеречного Молота, поклоняющиеся Древним богам. Они превратили древнее существо в невольного защитника своих темных ритуальных мест.",al={"ghamoo-ra old gods","is turtle corrupted","гхаму-ра древние боги","осквернена ли черепаха"}}},fp="9,251,24.464.0,21.379.0,17.233.0,38.222.0,28.87.0,27.161.0,45.220.0"}
P.entries["npc:gilnid"] = {n="Гилнид",s="Гилнид, известный как Плавильщик, — главный инженер-гоблин, заведующий кузнями в глубинах Мертвых копей. Он следит за переплавкой сырой руды в очищенный металл и боеприпасы для тайного броненосного исполина Эдвина ван Клифа. Без его огненных работ у Братства Справедливости не было бы тяжелых пушек, нужных для штурма Штормграда.",h="Гилнид, известный как Плавильщик, — главный инженер-гоблин, заведующий кузнями в глубинах Мертвых копей.",kw={"cannons","deadmines","defias","forge","foundry","gilnid","goblin","juggernaut","smelter","vancleef","пушки","мертвые копи","братство справедливости","кузня","литейная","гилнид","гоблин","исполин","плавильщик","ван клиф"},ang={["faction:Alliance"]="Остановив Гилнида, вы прекратите сборку оружия Братства Справедливости и не дадите кораблю ван Клифа полностью вооружиться, прежде чем он начнет угрожать Порту Штормграда.",["profession:Engineering"]="Литейная Гилнида — яркий пример гоблинской тяжелой промышленности: в чрезвычайных условиях она выпускает стандартные корабельные пушки, боеприпасы и конструкционные листы.",["profession:Mining"]="Огромные доменные печи и плавильные чаны в мастерской Гилнида показывают, как Братство Справедливости превращает сырые минеральные богатства Западного Края в очищенное железо и вооружение."},sec={{t="Хозяин литейной",b="В глубине Мертвых копей Братство Справедливости полагается на промышленное мастерство, чтобы ковать оружие войны. Гилнид служит главным плавильщиком ван Клифа и командует небольшой армией рабочих-гоблинов, механиков и кузнецов в центральной литейной. Он выше большинства сородичей и безжалостно погоняет свою команду в дыму и шлаке, выкрикивая приказы и запрещая перерывы, чтобы сырая железная руда превращалась в тяжелые листы брони и смертоносные боеприпасы."},{t="Вооружение исполина",b="Плавильни играют ключевую роль в грандиозных замыслах Братства. Гилнид лично отвечает за ковку тяжелых пушек и боеприпасов для огромного броненосного военного корабля, стоящего в подземной бухте за его мастерской. Пока его литейная не выдаст все орудия, стволы и ядра, корабль Братства Справедливости не готов к задуманному удару по Штормграду."}},faq={{q="Кто такой Гилнид?",a="Гилнид — гоблин-инженер и главный плавильщик Эдвина ван Клифа в Мертвых копях. Он заведует кузнями Братства и руководит промышленными работами по отливке пушек и боеприпасов для его военной машины.",al={"gilnid deadmines","who is gilnid","the smelter","гилнид мертвые копи","кто такой гилнид","плавильщик"}},{q="Почему Гилнид находится в Мертвых копях?",a="Братство Справедливости наняло гоблинов-инженеров, чтобы построить и снабдить свой тайный военный корабль. Гилнида поставили во главе плавилен, где добытая железная руда превращается в готовые детали, броню и артиллерию.",al={"why is a goblin in deadmines","gilnid defias lore","what is gilnid doing","почему гоблин в мертвых копях","гилнид братство справедливости","чем занят гилнид"}},{q="Над чем работает Гилнид?",a="Гилнид отвечает за изготовление огромных пушек, деталей корабля и снарядов, нужных, чтобы вооружить исполина, спрятанного в доках в глубине шахт.",al={"gilnid cannon","what is gilnid building","deadmines forge purpose","гилнид пушки","что строит гилнид","кузня мертвых копей"}},{q="Почему нужно победить Гилнида?",a="Гилнид управляет литейной, преграждающей путь к бухте. Тяжелые взрывозащитные двери, ведущие дальше к кораблю Братства Справедливости, остаются запертыми, пока плавильня не будет захвачена.",al={"why kill gilnid","door past gilnid","зачем убивать гилнида","дверь за гилнидом"}},{q="Работает ли Гилнид напрямую на Эдвина ван Клифа?",a="Да. Он не входит в число первоначальных Каменщиков, а является нанятым гоблином-специалистом, служащим непосредственно ван Клифу и занимающимся тяжелой металлургией и производством оружия.",al={"vancleef and gilnid","is gilnid defias leader","ван клиф и гилнид","гилнид предводитель братства"}},{q="Почему вокруг него так много гоблинов?",a="Гилнид возглавляет особую команду гоблинов-инженеров в литейной. Под его строгим и неослабным надзором они обслуживают доменные печи, разливают расплавленное железо и собирают боеприпасы.",al={"gilnid goblins","deadmines forge crew","гилнид гоблины","команда кузни мертвых копей"}}},fp="6,339,21.433.0,21.374.1,14.208.0,31.218.0,26.155.0,28.179.0,45.177.0,41.182.0"}
P.entries["npc:gilshalan-windwalker"] = {n="Гилшалан Буйный Ветер",s="Гилшалан Буйный Ветер — ночной эльф-исследователь, отдыхающий у подножия великого дерева Альдрассил в Тенистой долине. Обеспокоенный внезапной порчей, пустившей корни в Тельдрассиле, он изучает местных животных, чтобы понять неестественную агрессию, терзающую ветви. Его наблюдения за пауками Паучьего леса дают первые подсказки о гнили, поражающей Мировое Древо.",h="Гилшалан Буйный Ветер — ночной эльф-исследователь, отдыхающий у подножия великого дерева Альдрассил в...",kw={"aldrassil","gilshalan","shadowglen","spider","tenaron","venom","webwood","windwalker","альдрассил","гилшалан","тенистая долина","паук","тенарон","яд","паучий лес","буйный ветер"},ang={["class:Druid"]="Его исследования напрямую помогают Кругу Кенария в попытках определить причину экологического дисбаланса, разъедающего ветви Тенистой долины.",["race:NightElf"]="Гилшалан воплощает первые усилия вашего народа понять, почему только что выросшее Мировое Древо уже порождает больных и свирепых животных."},sec={{t="Ученый у корней",b="Спокойно сидя на каменных ступенях, ведущих в Альдрассил, Гилшалан Буйный Ветер с растущей тревогой наблюдает за безмятежным пологом Тенистой долины. Тельдрассил был посажен, чтобы вернуть ночным эльфам утраченное убежище и гармонию с природой, но признаки глубокого духовного недуга появились почти сразу. Гилшалан посвятил себя изучению того, как эта порча проявляется у местных зверей, начиная с ядовитых паукообразных, плетущих паутину неподалеку."},{t="Угроза Паучьего леса",b="Главное внимание Гилшалана направлено на пауков Паучьего леса, обитающих в Паучьем логове на севере. Эти создания, когда-то составлявшие уравновешенную часть лесной экосистемы, стали неестественно враждебными и оскверненными. Посылая молодых новичков собирать ядовитые железы и целые паучьи яйца, Гилшалан анализирует изменившуюся силу яда и пытается выяснить, передается ли порча по наследству или распространяется извне через почву Тельдрассила."},{t="Весть для верховного друида",b="Получив яд и яйцо, Гилшалан полагает, что яд пауков обнаружит свойства, связанные с недавним ростом нового Мирового Древа. Он договаривается отправить образцы в Дарнасс, где продолжит исследования. Он также сообщает многообещающим защитникам, что Тенарон Хватка Бури зовет их в самую верхнюю комнату Альдрассила, где руководство друидов присматривает за юным Мировым Древом."}},faq={{q="Кто такой Гилшалан Буйный Ветер?",a="Гилшалан Буйный Ветер — ночной эльф-ученый, сидящий у подножия Альдрассила в Тенистой долине. Он исследует загадочную порчу, проникающую в животный мир Тельдрассила.",al={"gilshalan","who is gilshalan","windwalker night elf","гилшалан","кто такой гилшалан","буйный ветер ночной эльф"}},{q="Зачем Гилшалану яд пауков Паучьего леса?",a="Гилшалан хочет изучить химические и духовные свойства яда, чтобы понять, почему лесные пауки стали такими агрессивными и мутировавшими.",al={"why webwood venom","webwood venom quest","spider venom gilshalan","зачем яд паучьего леса","задание яд паучьего леса","паучий яд гилшалан"}},{q="Что он делает с яйцом паука Паучьего леса?",a="Ему нужны живые образцы для изучения, но взрослого гигантского паука слишком опасно ловить. Неразвившееся яйцо гораздо проще перевезти, поэтому он отправляет его в Дарнасс вместе с ядом, где паучат можно содержать и изучать.",al={"webwood egg quest","why spider eggs","egg of webwood","задание яйцо паучьего леса","зачем паучьи яйца","яйцо паука"}},{q="Куда Гилшалан отправляет искателей приключений дальше?",a="После доставки яйца он говорит искателям приключений, что их зовет Тенарон Хватка Бури, и отправляет их в самую верхнюю комнату на вершине Альдрассила.",al={"tenaron summons","who do i see after gilshalan","after webwood egg","зов тенарона","к кому идти после гилшалана","после яйца паучьего леса"}},{q="Где находится Гилшалан Буйный Ветер?",a="Он сидит на каменной дорожке у северного подножия Альдрассила, прямо у полого входа в центральное дерево Тенистой долины.",al={"gilshalan location","where is windwalker","find gilshalan","гилшалан где находится","где буйный ветер","найти гилшалана"}},{q="Почему животные в Тельдрассиле агрессивны?",a="Неизвестная порча начала просачиваться через корни и почву Тельдрассила, искажая разум и природу его созданий и вызывая тревогу ученых, таких как Гилшалан.",al={"why are spiders mad","teldrassil corruption","corrupted beasts shadowglen","почему пауки злые","порча тельдрассила","оскверненные звери тенистая долина"}}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:gilthares-firebough"] = {n="Гилтарес Огненный Цветок",s="Гилтарес Огненный Цветок — эльф-палубный матрос, томящийся в плену на вершине башни в Крепости Северной Стражи. Прежде он служил у каперов Тало'дан на судне, перевозившем самогон между Кабестаном и Пиратской бухтой, и ищет любой случай бежать от своих тюремщиков из Терамора.",h="Гилтарес Огненный Цветок — эльф-палубный матрос, томящийся в плену на вершине башни в Крепости Северной...",kw={"booty bay","free from the hold","gilthares firebough","northwatch hold","ratchet","thalo'dan privateers","пиратская бухта","освобождение из крепости","гилтарес огненный цветок","крепость северной стражи","кабестан","каперы тало'дан"},ang={["faction:Alliance"]="Хотя поначалу Гилтарес равнодушен к прохожим, он питает сильную ненависть к морякам Альянса, уничтожившим его судно и запершим его в камере.",["faction:Horde"]="Сопровождая Гилтареса прочь от Северной Стражи, вы легко нанесете удар по агрессии Терамора на побережье Степей."},sec={{t="Контрабандист за решеткой",b="Перевозя запрещенный груз между Кабестаном и Пиратской бухтой, Гилтарес Огненный Цветок увидел, как его корабль разнесли в щепки военные суда из Терамора. Единственный выживший в нападении капер был в цепях доставлен на берег и заперт в башне Крепости Северной Стражи. Хотя он одет в яркий красный цвет и не питает любви к фанатикам Альянса, перебившим его команду, Гилтарес не привередлив в выборе тех, кто поможет ему бежать, — лишь бы они смогли прорубиться с крепостных стен."}},faq={{q="Кто такой Гилтарес Огненный Цветок?",a="Гилтарес — эльф-палубный матрос, связанный с каперами Тало'дан. Он был схвачен, когда силы Северной Стражи перехватили и потопили его торговое судно у побережья Степей.",al={"who is gilthares","gilthares lore","who is this elf","кто такой гилтарес","гилтарес предания","кто этот эльф"}},{q="Почему он заключен в Крепости Северной Стражи?",a="Гилтарес служил на судне, перевозившем самогон между Кабестаном и Пиратской бухтой. Солдаты Терамора потопили корабль, убили остальную команду, а Гилтареса заключили в Крепости Северной Стражи как контрабандный груз и военнопленного.",al={"why is he in jail","why in a cage","northwatch prisoner","почему он в тюрьме","почему в клетке","пленник северной стражи"}},{q="Гилтарес — высший эльф или эльф крови?",a="Гилтарес — эльф из Кель'Таласа, работающий независимым моряком и не служащий ни Альянсу, ни регентству в Луносвете. Хотя его красная одежда часто ассоциируется с син'дорай, он служит каперам, а не какой-либо государственной фракции.",al={"what kind of elf is gilthares","high elf or blood elf","gilthares race","какой эльф гилтарес","высший эльф или эльф крови","раса гилтареса"}},{q="Кто такие каперы Тало'дан?",a="Каперы Тало'дан — независимая морская организация, занимающаяся контрабандой через Великое море, в том числе прибыльными перевозками самогона между Кабестаном и Пиратской бухтой.",al={"thalodan privateers","who does he work for","gilthares crew","каперы тало'дан","на кого он работает","команда гилтареса"}}},fp="19,254,22.498.0,27.182.0,40.239.0,39.257.0,33.187.0"}
P.entries["npc:glorin-steelbrow"] = {n="Глорин Стальной Лоб",s="Глорин Стальной Лоб — дворф-агент, которого можно найти за выпивкой в таверне «Большая вода» в Гавани Менетилов. Будучи соратником епископа Фартинга из Собора Света Штормграда, он помогает искателям приключений расследовать судьбу пропавшей Третьей флотилии и вернуть священные реликвии и материалы, разбросанные по побережью Болотины. Его усилия связывают зловещие земли Сумеречного леса с затонувшими кораблями севера.",h="Глорин Стальной Лоб — дворф-агент, которого можно найти за выпивкой в таверне «Большая вода» в Гавани...",kw={"bishop farthing","deepwater tavern","doomed fleet","duskwood","eye of paleth","glorin steelbrow","lightforge iron","menethil harbor","wetlands","епископ фартинг","таверна большая вода","обреченный флот","сумеречный лес","око палета","глорин стальной лоб","железо светоносной ковки","гавань менетилов","болотина"},ang={["class:Paladin"]="Паладины, выполняющие приказы Фартинга, найдут Глорина незаменимым в поисках железа Светоносной ковки — священного металла, необходимого для ковки оружия, благословленного Светом.",["faction:Alliance"]="Глорин играет ключевую роль в возвращении важных военных реликвий Альянса и освященных материалов, потерянных во время морских катастроф у берегов Болотины.",["race:Dwarf"]="Глорин олицетворяет дворфийскую предприимчивость и солидарность: из морского центра Гавани Менетилов он координирует поддержку союзников по всему Каз Модану и южным человеческим королевствам."},sec={{t="Связь в гавани",b="Пока епископ Фартинг помогает жителям Сумеречного леса против подкрадывающихся ужасов из Собора Света Штормграда, он поддерживает связи далеко на севере, в Гавани Менетилов. В шумной таверне «Большая вода» Глорин Стальной Лоб служит глазами и руками Фартинга на побережье. Он помогает и указывает путь путникам, посланным на север за священными металлами и забытыми реликвиями, становясь важным мостом между бедами южного леса и затонувшими обломками Болотины."},{t="Обреченный флот и утраченные реликвии",b="Стальной Лоб хорошо знает трагедию Третьей флотилии, чьи корабли были разбиты и утянуты под воду у берегов Болотины. Он направляет искателей приключений обыскать населенные призраками обломки в поисках потерянных слитков железа Светоносной ковки и могущественного проклятого артефакта — Ока Палета. Глорин знает, что возвращение такого священного вооружения необходимо для ковки оружия, способного сдержать темные силы, угрожающие Альянсу."}},faq={{q="Кто такой Глорин Стальной Лоб?",a="Глорин Стальной Лоб — дворф, находящийся в таверне «Большая вода» в Гавани Менетилов. Он действует по согласованию с епископом Фартингом из Штормграда, помогая искателям приключений, отправляющимся на север за затонувшим грузом и реликвиями с побережья Болотины.",al={"who is glorin","glorin steelbrow lore","what does glorin do","кто такой глорин","глорин стальной лоб предания","чем занимается глорин"}},{q="Где найти Глорина Стального Лба?",a="Глорин находится на первом этаже таверны «Большая вода» в Гавани Менетилов, расположенной на западном побережье Болотины.",al={"glorin location","where is glorin steelbrow","glorin deepwater tavern","глорин где находится","где глорин стальной лоб","глорин таверна большая вода"}},{q="Почему дворф из Гавани Менетилов связан с Сумеречным лесом?",a="Епископ Фартинг из Собора Света Штормграда ищет могущественные священные реликвии и освященные металлы, чтобы бороться с тьмой, наступающей на Сумеречный лес. Он посылает доверенных посланников к Глорину Стальному Лбу, который знает побережье Болотины и может указать искателям, где искать затонувшие остатки Третьей флотилии.",al={"why duskwood quest in wetlands","connection to farthing","why send to wetlands","почему задание сумеречного леса в болотине","связь с фартингом","почему посылают в болотину"}},{q="Что за Третья флотилия, о которой говорит Глорин?",a="Третья флотилия — морская экспедиция Альянса, потерпевшая катастрофу у берегов Болотины. Ее разбитые корпуса теперь лежат на морском дне, населенные призраками утонувших моряков и скрывающие ценный груз, например железо Светоносной ковки и древние артефакты.",al={"what is the doomed fleet","third fleet wetlands","the doomed fleet quest","что такое обреченный флот","третья флотилия болотина","задание обреченный флот"}},{q="Что такое Око Палета?",a="Око Палета — древняя религиозная реликвия, находившаяся на борту затонувшей флотилии. После того как его поднимут с океанского дна с помощью Глорина, оно должно пройти очищение у священников из-за темной порчи, сохраняющейся вокруг места крушения.",al={"eye of paleth","paleth relic","what is eye of paleth","око палета","реликвия палета","что такое око палета"}},{q="Для чего используется железо Светоносной ковки?",a="Железо Светоносной ковки — редкий освященный металл, из которого делают благословенное оружие, способное сразить могущественную нежить и демонов. Глорин помогает доставать потерянные слитки из затонувших кораблей, чтобы помочь защитникам Сумеречного леса.",al={"lightforge iron","lost ingots","blessed arm","железо светоносной ковки","потерянные слитки","благословенное оружие"}}},fp="16,405,19.496.0,32.444.1,24.239.0,34.128.0,57.294.0,48.240.0,26.243.0,33.221.0"}
P.entries["npc:gnoarn"] = {n="Гноарн",s="Гноарн — гном-изгнанник, живущий в Городе механиков в горном городе дворфов Стальгорне. Лишившись дома после страшного падения Гномрегана, он помогает своему рассеянному народу: направляет путешественников на помощь другим гномам-инженерам и уцелевшим.",h="Гноарн — гном-изгнанник, живущий в Городе механиков в горном городе дворфов Стальгорне.",kw={"bingles","gnoarn","gnomefro","gnomeregan","ironforge","shoni the shilent","tinker town","бинглз","гноарн","гномфро","гномреган","стальгорн","шони молшунья","город механиков"},ang={["faction:Alliance"]="Герои Альянса, проходящие через Стальгорн, могут поговорить с Гноарном и узнать о важных гномьих инженерных начинаниях в Дун Мороге, Лок Модане и Штормграде.",["race:Gnome"]="Для гномов Гноарн воплощает стойкость общины беженцев в Городе механиков: он следит, чтобы изгнанные инженеры не теряли связи друг с другом по всем Восточным королевствам."},sec={{t="Беженец из Гномрегана",b="Как и большинству своих соплеменников, Гноарну пришлось бежать из глубин Гномрегана, когда туда вторглись трогги и катастрофическое излучение сделало огромный подземный город непригодным для жизни. Найдя убежище в Городе механиков в Стальгорне благодаря гостеприимству дворфов Бронзобородов, Гноарн проводит дни, следя за судьбой других уцелевших. Он неофициально координирует беженцев и направляет способных путников к гномам в других краях, остро нуждающимся в помощи, — например, к застрявшему пилоту Бинглзу Покрышкинсу в Лок Модане или к честолюбивому инженеру Шони Молшунье в Штормграде."}},faq={{q="Кто такой Гноарн?",a="Гноарн — уцелевший гном, живущий среди беженцев в Городе механиков, гномьем квартале Стальгорна. Он направляет путешественников на помощь другим гномам-изгнанникам, которые работают над разными проектами по всем землям Альянса.",al={"who is this gnome","gnoarn lore","gnoarn npc","что это за гном","гноарн предания","гноарн нпс"}},{q="Где можно найти Гноарна?",a="Его можно найти в Городе механиков в северо-восточной части Стальгорна, среди гудящих механизмов, шестерней и верстаков его соплеменников-изгнанников.",al={"gnoarn location","where is gnoarn","find gnoarn","гноарн местонахождение","где гноарн","найти гноарна"}},{q="Какие задания выдает Гноарн?",a="Гноарн направляет искателей приключений на помощь другим разбросанным по свету гномам. В частности, он посылает их в Лок Модан проверить пропавшего пилота Бинглза Покрышкинса, а также отправляет путников в Штормград поговорить с изобретательницей Шони Молшуньей о ее гиродрилломатических экскаваторах.",al={"gnoarn quests","what does gnoarn want","гноарн задания","что нужно гноарну"}},{q="Что случилось с волосами Гноарна?",a="До падения Гномрегана Гноарн был известен своей эксцентричной прической «гномфро». К несчастью, он лишился своей особенной шевелюры после катастрофы и радиоактивных выбросов, разрушивших его родной город.",al={"gnoarn gnomefro","gnoarn hair","гноарн гномфро","гноарн волосы"}}},fp="6,259,33.597.0,14.214.0,26.161.0,32.286.0,31.230.0"}
P.entries["npc:godrick-farsan"] = {n="Годрик Фарсан",s="Годрик Фарсан — помощник чернокнижника из числа нежити в Подгороде, служит вместе с Карендином Халгаром в Магическом квартале Подгорода. Хотя он совершенно слеп, он обладает мистическим чутьем, позволяющим ему ощущать темные энергии и души вокруг.",h="Годрик Фарсан — помощник чернокнижника из числа нежити в Подгороде, служит вместе с Карендином Халгаром в...",kw={"carendin halgar","godrick farsan","hearts of the pure","strahad farsan","succubus","undercity","warlock","карендин халгар","годрик фарсан","сердца чистых","страхад фарсан","суккуб","подгород","чернокнижник"},ang={["class:Warlock"]="Чернокнижникам из числа Отрекшихся, желающим овладеть искусством призыва суккуба, следует обратиться к Годрику: он поможет подготовить нужные приманки и понять пожирающую природу демонических слуг.",["race:Undead"]="Годрик олицетворяет философию чернокнижников Отрекшихся: он принимает телесный распад и слепоту, развивая темную магическую чувствительность взамен смертных слабостей."},sec={{t="Глаза во тьме",b="Годрик Фарсан живет среди кругов призыва Магического квартала Подгорода и помогает наставнику Карендину Халгару обучать начинающих чернокнижников из числа Отрекшихся. Хотя физического зрения он лишен, Годрик утверждает, что видит необычным, демоническим способом, воспринимая мир через тени и остаточную энергию душ. Он испытывает тех, кто хочет подчинить могущественных демонов, и посылает их собирать чистые сердца и эссенции, необходимые для сложных ритуалов призыва."}},faq={{q="Кто такой Годрик Фарсан?",a="Годрик Фарсан — чернокнижник из числа Отрекшихся, находящийся в Магическом квартале Подгорода. Он помогает наставнику Карендину Халгару в обучении и ритуалах начинающих чернокнижников.",al={"godrick farsan","who is godrick","годрик фарсан","кто такой годрик"}},{q="Как Годрик видит, если он слеп?",a="Хотя Годрик утратил смертное зрение, он воспринимает окружение магическими чувствами. Он черпает из потока скверны и духовного резонанса душ, чтобы ориентироваться и наблюдать за миром вокруг.",al={"is godrick blind","how does godrick see","слеп ли годрик","как видит годрик"}},{q="Годрик связан родством со Страхадом Фарсаном?",a="Раз у них одна фамилия и одинаковая тяга к демонологии, Годрика считают родственником Страхада Фарсана, мастера-чернокнижника, живущего над Кабестаном в Степях.",al={"strahad farsan relation","strahad farsan brother","are godrick and strahad related","родство со страхадом фарсаном","брат страхада фарсана","родственники годрик и страхад"}},{q="Какую роль он играет в обучении чернокнижников?",a="Годрик помогает руководить обрядами подчинения для чернокнижников, в частности направляет их в заданиях вроде добычи чистых сердец, чтобы заманить и подчинить суккуба.",al={"godrick warlock quests","hearts of the pure quest","годрик задания чернокнижника","задание сердца чистых"}}},fp="14,253,16.456.0,22.199.0,35.215.0,37.160.0,43.152.0"}
P.entries["npc:golnir-bouldertoe"] = {n="Голнир Твердопал",s="Голнир Твердопал — торговец дворфов, продающий снаряжение для горняков, у шумной Великой кузни в Стальгорне. Он снабжает необходимыми припасами рудокопов и старателей, а также занимается посланиями для местных курьеров и путников.",h="Голнир Твердопал — торговец дворфов, продающий снаряжение для горняков, у шумной Великой кузни в Стальгорне.",kw={"bouldertoe","coal","flux","golnir","great forge","ironforge","mining supplier","твердопал","уголь","флюс","голнир","великая кузня","стальгорн","торговец снаряжением для горняков"},ang={["profession:Mining"]="Горняки, приходящие в Великую кузню, полагаются на Голнира в поисках необходимых инструментов, включая запасные кирки и флюсы, нужные для переплавки сырой жильной руды в чистые слитки.",["race:Dwarf"]="Для дворфов, вернувшихся из первых путешествий по Холодной долине или Караносу, Голнир становится первым знакомым в столице: он встречает путников прямо возле огненного сердца горы."},sec={{t="Торговец Великой кузни",b="В раскаленном жаре Великой кузни Стальгорна Голнир Твердопал снабжает старателей и мастеров всем необходимым для их ремесла. От прочных горных кирок до флюсов и угля — его товары питают неугасимые плавильные печи и кузни, ради которых известна столица дворфов. Голнир — родственник Геофрама Твердопала и надежный контакт для рабочих, прибывающих в город: он часто направляет новичков или принимает послания с припасами, доставленные из ближних застав."}},faq={{q="Где найти Голнира Твердопала?",a="Голнир Твердопал находится в Великой кузне в Стальгорне, рядом с центральными плавильнями и кузнечными участками, среди других торговцев.",al={"golnir location","where is golnir","golnir bouldertoe ironforge","голнир местонахождение","где голнир","голнир твердопал стальгорн"}},{q="Какие товары продает Голнир?",a="Он снабжает горняков, продавая необходимое снаряжение: горные кирки, уголь и флюсы, которые помогают старателям добывать и очищать сырую руду.",al={"golnir vendor wares","what does golnir sell","golnir inventory","голнир товары","что продает голнир","голнир ассортимент"}},{q="Участвует ли Голнир Твердопал в каких-либо заданиях?",a="Да. Задания курьеров, связывающие окрестные поселения дворфов со столицей, например поручения с участием Грита Турдена и прибывающие рейсы с застав вроде Телсамара, велят путникам передать сообщения прямо в руки Голниру.",al={"golnir quests","ride to ironforge golnir","голнир задания","полет в стальгорн голнир"}},{q="Есть ли у Голнира родственники в Дун Мороге?",a="Голнир носит то же имя клана, что и Геофрам Твердопал, учитель горного дела, работающий рядом с ним в Великой кузне Стальгорна.",al={"bouldertoe family","geofram bouldertoe relative","семья твердопалов","геофрам твердопал родственник"}}},fp="17,218,27.473.0,35.154.0,28.154.0,44.236.0,47.125.0"}
P.entries["npc:gorbold-steelhand"] = {n="Горбольд Сталерук",s="Горбольд Сталерук — торговец-дворф в Аубердине на туманном побережье Темных берегов. Вдали от заснеженных залов Каз Модана он снабжает путников, ремесленников и местных ночных эльфов товарами общего назначения и торговыми припасами.",h="Горбольд Сталерук — торговец-дворф в Аубердине на туманном побережье Темных берегов.",kw={"auberdine","darkshore","deep ocean vast sea","gorbold","ironforge","merchant","steelhand","vendor","аубердин","темные берега","безбрежное море глубокий океан","горбольд","стальгорн","торговец","сталерук","продавец"},ang={["faction:Alliance"]="Горбольд показывает практическое сотрудничество восточных народов Альянса и ночных эльфов, поддерживая торговлю через Великое море.",["race:Dwarf"]="Знакомое лицо из Стальгорна вроде Горбольда в туманной ночной обстановке Темных берегов — приятное напоминание о доме для путешествующих дворфов."},sec={{t="Торговец-дворф в Калимдоре",b="Хотя северные земли Калимдора населяют в основном скрытные ночные эльфы, заставам Альянса вроде Аубердина нужны торговцы из-за Великого моря, чтобы торговля не прерывалась. Горбольд Сталерук олицетворяет широкое присутствие стальгорнской торговли в этом краю. Работая бок о бок с кальдораями, он продает хозяйственные товары, реагенты, ремесленные мелочи и инструменты искателям приключений, готовящимся исследовать опасные берега и леса Темных берегов."},{t="Морские предприятия",b="Помимо повседневных товаров, Горбольд внимательно следит за опасными прибрежными водами у Аубердина. Усеянные рифами воды Темных берегов печально известны тем, что поглощают корабли Альянса, и торговцы вроде Горбольда напрямую заинтересованы в грузах, потерянных под волнами. Путники, готовые нырнуть в глубины, часто могут найти в нем покупателя спасенного имущества и потерянных журналов, разбросанных среди затонувших обломков."}},faq={{q="Кто такой Горбольд Сталерук?",a="Горбольд Сталерук — торговец-дворф, продающий товары общего назначения, из прибрежного порта Аубердин на Темных берегах.",al={"gorbold","who is gorbold steelhand","dwarf in auberdine","горбольд","кто такой горбольд сталерук","дворф в аубердине"}},{q="Что продает Горбольд Сталерук?",a="У него есть торговые припасы общего назначения, ингредиенты для ремесел, инструменты для сбора и реагенты вроде склянок и ниток, которые нужны торговому люду, проезжающему через Аубердин.",al={"what does gorbold sell","gorbold trade goods","gorbold vendor list","что продает горбольд","горбольд товары","горбольд список товаров"}},{q="Почему дворф из Стальгорна живет на Темных берегах?",a="Аубердин — важный транспортный узел Альянса, связывающий Калимдор с Восточными королевствами. Дворфы часто приезжают сюда ради торговли, исследований и поддержки действий союзников — ночных эльфов.",al={"why is a dwarf here","why is gorbold in darkshore","ironforge in auberdine","почему здесь дворф","почему горбольд на темных берегах","стальгорн в аубердине"}},{q="Дает ли Горбольд какие-либо задания?",a="Да, в задании «Безбрежное море, глубокий океан» он направляет искателей приключений к затонувшим обломкам у берегов Темных берегов, чтобы вернуть потерянный корабельный груз.",al={"gorbold quest","deep ocean vast sea quest giver","горбольд задание","безбрежное море глубокий океан задание"}}},fp="17,242,28.454.0,17.401.0,25.106.0,33.157.0,46.193.0,30.141.0"}
P.entries["npc:gordon-wendham"] = {n="Гордон Уиндем",s="Гордон Уиндем — оружейник и торговец из числа Отрекшихся, работающий в шумном Торговом квартале Подгорода. Он снабжает надежной сталью, клинками и дубинами недавно прибывших бойцов и местных защитников Темной Госпожи. Помимо торговли простым оружием, он нередко служит местным контактом для курьеров, прибывающих с поверхности.",h="Гордон Уиндем — оружейник и торговец из числа Отрекшихся, работающий в шумном Торговом квартале Подгорода.",kw={"forsaken","gordon wendham","michael garrett","trade quarter","undercity","weapon vendor","отрекшиеся","гордон уиндем","майкл гарретт","торговый квартал","подгород","торговец оружием"},ang={["class:Warrior"]="Гордон предлагает надежные простые клинки и дробящее оружие бойцам первых рядов, которые хотят отточить владение оружием в столице.",["race:Undead"]="Для недавно освобожденных Отрекшихся, покидающих Могильник, торговцы вроде Гордона Уиндема в Торговом квартале — практическая опора военных усилий их молодого государства."},sec={{t="Вооружение Торгового квартала",b="Гордон Уиндем живет среди сырой каменной кладки и химических каналов Торгового квартала Подгорода и снабжает необходимым оружием тех, кто берется за оружие во имя Отрекшихся. От простых кинжалов и ручных топоров до прочных палашей и булав — его товары рассчитаны на начинающих бойцов, которым нужно надежное железо, прежде чем отправиться в спорные земли Лордерона."},{t="Пункт назначения курьеров",b="Помимо торговли, Уиндем встроен в оживленную снабженческую сеть столицы. Путников, посланных с поручениями от распорядителей полетов и курьеров, например от укротителей летучих мышей на вершине руин, часто направляют прямо к его прилавку. Его центральное расположение в Торговом квартале делает его удобным и узнаваемым звеном в доставке простых припасов и посланий по всему подземному городу."}},faq={{q="Кто такой Гордон Уиндем?",a="Гордон Уиндем — торговец из числа нежити в Торговом квартале Подгорода. Он продает обычное боевое оружие и служит контактом для курьеров, прибывающих в столицу.",al={"gordon wendham lore","who is wendham","undercity gordon","гордон уиндем предания","кто такой уиндем","гордон подгород"}},{q="Где находится Гордон Уиндем?",a="Вы найдете его у оружейного прилавка в Торговом квартале — торговом кольце в подземных залах Подгорода.",al={"gordon wendham location","where is gordon undercity","trade quarter weapon vendor","гордон уиндем местонахождение","где гордон подгород","торговый квартал торговец оружием"}},{q="Что он продает?",a="Он предлагает широкий выбор простого оружия стандартного качества: мечи, кинжалы, булавы, посохи, топоры и разное метательное оружие, подходящее для развивающихся искателей приключений.",al={"wendham wares","what does gordon sell","gordon wendham weapons","товары уиндема","что продает гордон","гордон уиндем оружие"}},{q="Какие задания с ним связаны?",a="Он участвует во вводных заданиях на доставку между логовами летучих мышей на поверхности и внутренними районами Подгорода, в том числе в доставке между ним и укротителем летучих мышей Майклом Гарреттом.",al={"gordon wendham quests","ride to the undercity","michael garrett quest","гордон уиндем задания","полет в подгород","задание майкл гарретт"}}},fp="14,351,30.365.0,23.429.0,22.181.0,32.140.0,18.166.0,24.173.0"}
P.entries["npc:gornek"] = {n="Горнек",s="Горнек — надсмотрщик-орк, находящийся в Долине Испытаний в Дуротаре. Он первым встречает новичков — орков и троллей Черного Копья, готовящихся доказать свою доблесть Новой Орде.",h="Горнек — надсмотрщик-орк, находящийся в Долине Испытаний в Дуротаре.",kw={"den","durotar","gornek","parchment","the new horde","valley of trials","логово","дуротар","горнек","пергамент","новая орда","долина испытаний"},ang={["race:Orc"]="Для молодых орков явиться к Горнеку — самый первый шаг к тому, чтобы оставить детство и заслужить почетное место в Дуротаре.",["race:Troll"]="Как союзники, обретшие приют у Тралла, тролли Черного Копья предъявляют бумаги Горнеку, чтобы доказать, что они достойные соратники своих братьев-орков."},sec={{t="Встреча непроверенных",b="Стоя в самом сердце Долины Испытаний, Горнек представляет первое испытание дисциплины для будущих воинов, разведчиков и заклинателей Орды. По приказу вождя Тралла каждый юноша и новичок должен заслужить свое место стойкостью и упорством, а не по праву рождения. Горнек оценивает тех, кто входит в долину, читает их вводные предписания и направляет к наставникам по всему лагерю. Будь то шифрованная записка, пергамент с письменами или простая табличка — именно Горнек принимает у новобранцев бумаги и отправляет их на суровый путь выживания."},{t="Жизнь на службе Дуротара",b="Засушливые каньоны долины проверяют не только боевое мастерство, но и воспитывают общинный дух Новой Орды. Горнек следит, чтобы новички не слонялись без дела, и направляет их на испытания в ближние норы скорпидов, к логовам диких кабанов и под бдительные взоры опытных наставников. Тем, кто пережил обучение и перебил угрозы, таящиеся в оврагах красных скал, Горнек выражает последнее признание, прежде чем отправить их в более широкие и опасные земли Дуротара."}},faq={{q="Кто такой Горнек?",a="Горнек — орк, встречающий новобранцев и надсмотрщик в Долине Испытаний. Он наблюдает за новыми рекрутами Орды, читает их посвятительные документы и направляет к наставникам их классов.",al={"gornek","who is this orc","who is gornek","горнек","кто этот орк","кто такой горнек"}},{q="Где найти Горнека?",a="Он стоит почти в центре Долины Испытаний на юго-западе Дуротара, прямо у Логова, где молодые орки и тролли Черного Копья начинают свой путь.",al={"gornek location","where is gornek","gornek map","где горнек","горнек на карте","расположение горнека"}},{q="Почему новобранцы являются к нему?",a="Новички приходят со свитками и табличками, указывающими избранное ими призвание. Горнек изучает эти рекомендательные письма, подтверждает их право и отправляет к подходящим наставникам в долине.",al={"why visit gornek","parchment quest","tablet quest","зачем идти к горнеку","задание с пергаментом","задание с табличкой"}},{q="Какова его роль в Новой Орде?",a="Он служит координатором приема новичков в Новой Орде Тралла. Его долг — следить, чтобы ни один рекрут не вышел в земли Дуротара, не усвоив основ чести, выживания и боевой готовности.",al={"gornek horde role","what does gornek do","роль горнека в орде","что делает горнек"}}},fp="6,204,22.613.0,28.513.0,14.190.0,24.155.0,34.221.0,34.207.0"}
P.entries["npc:gramma-stonefield"] = {n="Бабуля Стоунфилд",s="Бабуля Стоунфилд, настоящее имя которой Милдред, — престарелая глава семьи Стоунфилдов, живущей на ферме в Элвиннском лесу. В отличие от своих сварливых родичей, она устала от горькой многовековой вражды с соседями Маклюрами. Тайно, за спиной семьи, она делает все, чтобы помочь внуку Томми Джо в его запретном романе с Мейбелл Маклюр.",h="Бабуля Стоунфилд, настоящее имя которой Милдред, — престарелая глава семьи Стоунфилдов, живущей на ферме в...",kw={"elwynn","gramma stonefield","maclure","maybell","mildred","stonefield farm","tommy joe","william pestle","элвинн","бабуля стоунфилд","маклюр","мейбелл","милдред","ферма стоунфилдов","томми джо","вильям пест"},ang={["faction:Alliance"]="Бабуля Стоунфилд — мягкое напоминание о том, что даже в сердце Альянса местные конфликты часто требуют тихой дипломатии и простого сочувствия, а не стали."},sec={{t="Тайная миротворица",b="Как старейшая из живущих Стоунфилдов, Милдред Стоунфилд десятилетиями наблюдала мелочные распри между своим домом и Маклюрами через дорогу. Вместо того чтобы разжигать злобу, она считает эту вражду бессмысленной и разрушительной. Когда ее внук Томми Джо Стоунфилд влюбился в Мейбелл Маклюр, Бабуля предпочла сострадание верности клану. Опираясь на старую дружбу с Вильямом Пестом в Златоземье, она тайно замышляет помочь влюбленным встречаться, преодолевая упрямую вражду, разделяющую две фермы."}},faq={{q="Кто такая Бабуля Стоунфилд?",a="Бабуля Стоунфилд, по имени Милдред, — престарелая глава семьи Стоунфилдов, живущей на ферме в центральной части Элвиннского леса. Она бабушка Томми Джо Стоунфилда.",al={"who is gramma","mildred stonefield","stonefield grandma","кто такая бабуля","милдред стоунфилд","бабушка стоунфилд"}},{q="Как она относится к вражде с Маклюрами?",a="Милдред не заинтересована в продолжении вражды. В отличие от большинства членов обеих семей, она считает обиду глупой и вредной и хотела бы видеть согласие между домами вместо бесконечных склок.",al={"stonefield maclure feud","does she hate maclures","вражда стоунфилдов и маклюров","ненавидит ли она маклюров"}},{q="Почему она помогает Томми Джо и Мейбелл?",a="Она любит внука Томми Джо и хочет, чтобы он был счастлив. Не принимая семейную вражду, она деятельно помогает его запретному роману с Мейбелл Маклюр, обращаясь к старому другу Вильяму Песту, чтобы тот придумал выход для влюбленных.",al={"why help tommy joe","gramma love potion","help lovers","почему помогает томми джо","бабуля любовное зелье","помощь влюбленным"}},{q="Кем ей приходится Вильям Пест?",a="Вильям Пест, алхимик из таверны Гордость Льва в Златоземье, — старый и верный друг Бабули Стоунфилд. Она связывается с ним через доверенных посыльных, чтобы он приготовил для Томми Джо незаметные снадобья и средства.",al={"william pestle connection","william pestle gramma","вильям пест связь","вильям пест бабуля"}}},fp="17,404,19.576.0,25.178.0,51.211.0,41.239.0,29.226.0"}
P.entries["npc:grand-mason-marblesten"] = {n="Главный камнетес Мраморщик",s="Главный камнетес Мраморщик — уважаемый каменщик-дворф, работающий в шумном Общинном квартале Стальгорна. Глубоко преданный королевскому наследию Каз Модана, он получил от короля Магни Бронзоборода заказ на памятник Салли Балу, дворфу-солдату, погибшему в трагедии на Мосту Тандола. Искатели приключений часто встречают его, помогая с материалами для этого скорбного памятника.",h="Главный камнетес Мраморщик — уважаемый каменщик-дворф, работающий в шумном Общинном квартале Стальгорна.",kw={"a king's tribute","bronzebeard","commons","grand mason","ironforge","magni","marblesten","stonemason","sully balloo","королевские почести","бронзобород","общинный квартал","главный камнетес","стальгорн","магни","мраморщик","каменотес","салли балу"},ang={["faction:Alliance"]="Чествование жертвы Салли Балу напоминает Альянсу о каждом солдате, павшем в его войнах.",["profession:Mining"]="Шахтеры, тесно работающие с породой Дун Морога и других земель, оценят строгие требования Мраморщика к качеству сырого камня.",["race:Dwarf"]="Для дворфов работа с камнем — наследие предков; помогая Мраморщику, они отдают дань и ремеслу Каз Модана, и памяти павшего солдата Салли Балу."},sec={{t="Мастер камня",b="Дворфийское каменное зодчество — не просто ремесло, а непреходящее искусство, формирующее саму душу Стальгорна. Главный камнетес Мраморщик — один из первых мастеров резца в городе, продолжатель вековой традиции высекать залы, колонны и огромные статуи прямо из живой горы. Работая в Общинном квартале, он руководит городскими проектами и памятниками, увековечивающими историю Бронзобородов."},{t="Королевские почести",b="Самое трогательное дело Мраморщика — памятник, заказанный королем Магни для Салли Балу, солдата, погибшего в трагедии на Мосту Тандола, в дар его скорбящей вдове. Желая создать по-настоящему долговечное творение, Главный камнетес настаивает на одном из лучших камней: Альтеракском граните с Холма Дарроу в Хилсбраде."}},faq={{q="Кто такой Главный камнетес Мраморщик?",a="Главный камнетес Мраморщик — старший каменщик-дворф из Общинного квартала Стальгорна. Ему поручены городские и королевские скульптурные проекты, в первую очередь памятник павшему солдату Салли Балу, заказанный королем Магни Бронзобородом.",al={"who is marblesten","marblesten role","grand mason npc","кто такой мраморщик","роль мраморщика","главный камнетес"}},{q="Где найти Главного камнетеса Мраморщика?",a="Его можно найти в Общинном квартале Стальгорна среди каменных блоков и архитектурных работ, недалеко от шумных лавок и банков города.",al={"marblesten location","where is marblesten","ironforge marblesten","где мраморщик","мраморщик локация","мраморщик стальгорн"}},{q="Над каким памятником работает Мраморщик?",a="Он строит памятник Салли Балу, дворфу-солдату, погибшему в трагедии на Мосту Тандола. Король Магни Бронзобород заказал его в честь Балу и его скорбящей вдовы.",al={"what is he building","kings tribute quest","marblesten statue","что он строит","задание королевские почести","статуя мраморщика"}},{q="Почему Мраморщику нужны искатели приключений для сбора материалов?",a="Мраморщик хочет создать поистине величественное и долговечное творение, поэтому работает только с одним из лучших камней. Он посылает путников на Холм Дарроу в Хилсбраде за Альтеракским гранитом.",al={"marblesten quests","why need stones","materials for monument","задания мраморщика","зачем нужны камни","материалы для памятника"}},{q="Что означает титул «Главный камнетес» в обществе дворфов?",a="У дворфов работа с камнем почитается наравне с кузнечным делом. «Главный камнетес» — искусный мастер каменного дела, которому доверяют крупные государственные проекты, королевские архитектурные замыслы и памятники для церемоний.",al={"what is a grand mason","dwarf mason rank","что такое главный камнетес","ранг каменщика дворфа"}},{q="Мраморщик — должностное лицо Альянса или частный подрядчик?",a="Мраморщик работает прямо в Стальгорне и служит королевству Стальгорн и Альянсу, тесно взаимодействуя с двором короля Магни Бронзоборода по королевским заказам.",al={"who does marblesten work for","marblesten faction","на кого работает мраморщик","фракция мраморщика"}}},fp="22,395,19.426.0,16.312.0,30.247.0,40.154.0,39.182.0,57.184.0,58.210.0,59.176.0"}
P.entries["npc:granis-swiftaxe"] = {n="Гранис Быстрый Топор",s="Гранис Быстрый Топор — дворф, наставник воинов в Таверне «Громоварка» в Караносе. Известный прямолинейным нравом и суровой подготовкой, он обучает молодых бойцов Альянса, выходящих из Туннеля Холодной долины, а опытных воинов направляет в Стальгорн.",h="Гранис Быстрый Топор — дворф, наставник воинов в Таверне «Громоварка» в Караносе.",kw={"dun morogh","granis swiftaxe","kharanos","muren stormpike","thunderbrew distillery","warrior trainer","дун морог","гранис быстрый топор","каранос","марен грозовая вершина","таверна громоварка","наставник воинов"},ang={["class:Warrior"]="Для воинов-дворфов и гномов, покидающих Холодную долину, Гранис дает необходимые начальные боевые уроки прямо рядом с кружкой свежего пива в таверне.",["race:Dwarf"]="Воплощая крепкий и упрямый дух пехотинцев Стальгорна, Гранис сочетает воинскую дисциплину с радостями местного эля."},sec={{t="Суровый наставник в Караносе",b="Греясь среди бочек Таверны «Громоварка», Гранис Быстрый Топор служит главным наставником по бою для молодых воинов, идущих через Дун Морог. Он обладает непреклонной гордостью, свойственной дворфийским бойцам, и открыто потешается над теми, кто не воин, и презирает их, когда они пытаются с ним заговорить. Когда ученик показывает достаточное мастерство в бою, Гранис отправляет его по горной тропе к главному наставнику Марен Грозовая Вершина в Военный квартал Стальгорна."}},faq={{q="Кто такой Гранис Быстрый Топор?",a="Гранис Быстрый Топор — дворф, наставник воинов на первом этаже Таверны «Громоварка» в Караносе. Он учит начальным боевым приемам молодых воинов-дворфов и гномов, странствующих по Дун Морогу.",al={"granis swiftaxe","who is granis","kharanos warrior trainer","гранис быстрый топор","кто такой гранис","наставник воинов каранос"}},{q="Почему Гранис насмехается над моим персонажем?",a="У Граниса нет терпения к тем, кто не идет путем воина. Если искатель приключений другого класса заговаривает с ним, он высмеивает саму мысль, что тот продержится хоть день под его суровой подготовкой.",al={"granis rude quote","why is granis laughing at me","granis non warrior text","грубая реплика граниса","почему гранис смеется надо мной","текст граниса для не воинов"}},{q="Куда Гранис отправляет растущих воинов?",a="Когда воин набирает достаточно опыта в Дун Мороге, Гранис направляет его к Марен Грозовая Вершина, старшему наставнику воинов в Военном квартале Стальгорна.",al={"muren stormpike quest","granis questline","who does granis send you to","задание марен грозовая вершина","цепочка заданий граниса","к кому гранис отправляет"}},{q="Родственен ли Гранис другим Быстрым Топорам в Каз Модане?",a="Хотя прямо это не подтверждено, его фамилия намекает на связь с другими известными Быстрыми Топорами региона, такими как Хегнар Быстрый Топор в Лок Модане и Грендин Быстрый Топор в Дун Мороге.",al={"swiftaxe family","granis swiftaxe relatives","семья быстрый топор","родственники граниса"}}},fp="15,285,26.485.0,23.216.0,34.218.0,42.170.0,51.175.0"}
P.entries["npc:great-father-winter"] = {n="Дедушка Зима",s="Дедушка Зима — пожилой орк, нанятый торговой компанией «Пастбища Дымного Леса», чтобы изображать легендарного героя праздника в Оргриммаре. Во время Зимнего Покрова он стоит возле Крепости Громмаш в Аллее Силы и выслушивает желания детей, но заметно устает от коммерческого праздничного веселья. В обмен на праздничные подарки и сезонные задания он обычно просит прохожих принести имбирное печенье и ледяное молоко.",h="Дедушка Зима — пожилой орк, нанятый торговой компанией «Пастбища Дымного Леса», чтобы изображать легендарного...",kw={"gingerbread cookies","great-father winter","greatfather winter","orgrimmar","smokywood pastures","valley of strength","winter veil","имбирное печенье","дедушка зима","оргриммар","пастбища дымного леса","аллея силы","зимний покров"},ang={["faction:Horde"]="Он служит главным сезонным символом Орды в Оргриммаре и предлагает праздничные подарки и задания от имени «Пастбищ Дымного Леса».",["profession:Cooking"]="Повара могут печь имбирное печенье по праздничным рецептам и приносить его вместе с молоком прямо Дедушке Зиме, чтобы поднять ему настроение.",["race:Orc"]="Хотя орки чтут смену времен года и стихии, вид соплеменника, превратившегося в костюмированного талисмана, торгующего скидками, испытывает терпение приверженцев традиций."},sec={{t="Нанятый миф",b="Древние предания говорят о Дедушке Зиме как о величественном духе стихии, который бродит по земле, неся снег и обновление природы, но фигура, сидящая в Аллее Силы, куда более обыденна. Это орк-артист на жалованье у «Пастбищ Дымного Леса», нанятый, чтобы подстегивать торговлю, рекламировать товары компании и развлекать молодежь Орды. Критики ворчат, что этот коммерческий талисман обесценивает настоящие сезонные традиции, но мало кто станет отрицать праздничное оживление, которое он приносит на городские улицы."},{t="Смена в Аллее Силы",b="Этот заместитель стоит прямо у Крепости Громмаш под ветвями украшенных елей и выдерживает изнурительную смену: дети карабкаются к нему на колени и излагают свои требования к подаркам. Между рекламными вставками о скидках «Пастбищ Дымного Леса» и вялыми праздничными поздравлениями его выносливость часто иссякает. Он открыто признается, что прячет в сумке бутылку праздничного хмельного, чтобы заглушить шум, как только смена закончится, и очень рассчитывает, что заглянувшие искатели приключений принесут ему закуски, чтобы он продержался."}},faq={{q="Это настоящий Дедушка Зима?",a="Нет. Это обычный орк, нанятый «Пастбищами Дымного Леса», чтобы наряжаться, изображать легендарного героя Зимнего Покрова и раздавать праздничные рекламные предложения в Оргриммаре.",al={"is he real","who is great-father winter","is he an actor","он настоящий","кто такой дедушка зима","он актер"}},{q="Где найти Дедушку Зиму в Оргриммаре?",a="Его можно найти в Аллее Силы: он расположился сразу у входа в Крепость Громмаш, рядом с деревом Зимнего Покрова и праздничными лотками.",al={"great-father winter location","where is great father winter","where to find winter orc","местонахождение дедушки зимы","где дедушка зима","где найти орка зиму"}},{q="Что он делает во время Зимнего Покрова?",a="Он развлекает гостей праздника, выслушивает просьбы детей о подарках, выдает рекламные задания «Пастбищ Дымного Леса» и раздает праздничные подарки под деревом, когда праздник достигает разгара.",al={"what does he do","great-father winter purpose","winter veil quests","что он делает","зачем нужен дедушка зима","задания зимнего покрова"}},{q="Почему он хочет имбирное печенье и молоко?",a="Шумные толпы и дети, непрерывно залезающие на колени, весь день полностью выматывают его. Он просит искателей приключений принести свежее имбирное печенье и молоко, чтобы поддержать силы до конца смены.",al={"treats for great father winter","why milk and cookies","gingerbread quest","угощение для дедушки зимы","почему молоко и печенье","задание имбирное печенье"}},{q="Что он думает о своей работе?",a="Он считает это представление нудным и выматывающим. Он открыто ворчит на нетерпеливых детей, торопливо проговаривает рекламные лозунги и с нетерпением считает минуты до того, как сможет выпить из бутылки веселья, спрятанной в сумке.",al={"does he like his job","great-father winter quotes","is he drunk","нравится ли ему работа","цитаты дедушки зимы","он пьян"}},{q="Есть ли такой персонаж у Альянса?",a="Да. У Альянса есть Дедушка Зима — пожилой дворф на службе у «Пастбищ Дымного Леса», который сидит возле праздничного дерева в Общинном квартале Стальгорна.",al={"alliance greatfather","ironforge santa","alliance counterpart","дедушка зима альянса","дед мороз стальгорна","двойник у альянса"}}},fp="19,438,12.510.0,36.525.0,36.154.0,50.145.0,48.183.0,46.205.0,30.223.0,44.149.0"}
P.entries["npc:greatfather-winter"] = {n="Дедушка Зима",s="Дедушка Зима — легендарное воплощение зимы и центральная фигура праздника Зимнего Покрова. Древние легенды чтут его как мифическое существо, укрывающее Азерот снегом, чтобы земля могла отдохнуть и обновиться, но современные горожане знают его в основном по коммерческому зрелищу, которым заправляют гоблины из «Пастбищ Дымного Леса».",h="Дедушка Зима — легендарное воплощение зимы и центральная фигура праздника Зимнего Покрова.",kw={"dun morogh","gingerbread cookies","great-father winter","greatfather winter","ironforge","orgrimmar","smokywood pastures","winter veil","дун морог","имбирное печенье","дедушка зима","стальгорн","оргриммар","пастбища дымного леса","зимний покров"},ang={["profession:Cooking"]="Праздник держится на умелых поварах, которые готовят имбирное печенье и другие праздничные угощения для «Пастбищ Дымного Леса» и самого Дедушки Зимы.",["race:Dwarf"]="Дворфы видят в Дедушке воплощение титанов, создавших мир, а заснеженные вершины Дун Морога считают живым свидетельством его прикосновения."},sec={{t="Миф и обновление",b="Согласно древним преданиям, Дедушка Зима — эфирный странник, который бродит по миру в конце года, раскидывая свой развевающийся снежный плащ над землей, чтобы природа могла уснуть и возродиться. Дворфы видят в нем воплощение или вестника титанов и указывают на покрытые инеем скалы Дун Морога как на живое свидетельство его благосклонности. Другие традиции, например тауренов, уважают его роль в смене времен года, но приписывают холод и бури стихийной работе Солнца и Луны, дающей Матери-Земле время на отдых. Куда бы ни дошла легенда, общины учились собираться и пировать вместе против холода, празднуя обещание возвращающейся жизни."},{t="«Пастбища Дымного Леса» и городские празднества",b="В крупных поселениях, таких как Стальгорн и Оргриммар, древний дух был полностью переработан предприимчивыми гоблинами из «Пастбищ Дымного Леса». Торговый картель распространил образ Дедушки Зимы как веселого старца в красном костюме с белой бородой, который летает на санях и раздает праздничные лакомства и игрушки. «Пастбища Дымного Леса» нанимают местных актеров — дворфа в Стальгорне и орка в Оргриммаре, — чтобы они выслушивали списки желаний детей, принимали подношения в виде молока и имбирного печенья и рекламировали сезонные товары под пышно украшенными деревьями."}},faq={{q="Настоящий ли дух Дедушка Зима в Стальгорне?",a="Нет, Дедушка Зима, сидящий у праздничного дерева в Стальгорне, — актер, нанятый гоблинской торговой компанией «Пастбища Дымного Леса». Компания устраивает такие появления, чтобы радовать детей и продавать сезонные сладости, хотя настоящие легенды говорят о подлинном эфирном существе, бродящем по миру зимой.",al={"is greatfather winter real","who is the guy in ironforge","is he an actor","настоящий ли дедушка зима","кто в стальгорне","он актер"}},{q="Почему дворфы чтут Дедушку Зиму?",a="Дворфы связывают Дедушку Зиму со своими создателями, титанами. Снежное покрывало, которое он набрасывает на землю, они считают благословением, а свою вечно холодную родину, Дун Морог, приводят как главное доказательство его благосклонности.",al={"dwarf winter veil","dwarven father winter","ironforge greatfather winter","дворфы зимний покров","дворфийский дедушка зима","дедушка зима стальгорн"}},{q="Что Дедушка Зима делает с принесенным ему печеньем и молоком?",a="Согласно праздничным преданиям, распространенным «Пастбищами Дымного Леса», Дедушка Зима любит полакомиться праздничным имбирным печеньем и ледяным молоком, просматривая списки желаний и распространяя праздничное веселье.",al={"treats for greatfather winter","why milk and cookies","gingerbread cookies quest","угощение для дедушки зимы","почему молоко и печенье","задание имбирное печенье"}},{q="Как Орда относится к Дедушке Зиме?",a="Орда участвует в празднествах в основном через городскую рекламную кампанию «Пастбищ Дымного Леса» в Оргриммаре, где Дедушка изображен орком. По своей культуре таурены видят в зиме важную пору сна и стихийного обновления для Матери-Земли и уважают роль Дедушки в круговороте времен года, но не поклоняются титанам буквально.",al={"horde greatfather winter","orgrimmar greatfather winter","tauren winter veil","дедушка зима орды","дедушка зима оргриммар","таурены зимний покров"}}},fp="18,362,16.674.0,39.571.0,55.303.0,41.228.0,73.202.0,43.359.0"}
P.entries["npc:greatmother-hawkwind"] = {n="Великая Мать Соколиный Ветер",s="Великая Мать Соколиный Ветер — почитаемая старейшина тауренов, отдыхающая у колодца на плато Красного Облака. Будучи матерью предводителя Лагеря Нараче, вождя Соколиного Ветра, она воплощает непреходящий дух и общинную ответственность племени, несмотря на преклонный возраст.",h="Великая Мать Соколиный Ветер — почитаемая старейшина тауренов, отдыхающая у колодца на плато Красного Облака.",kw={"a humble task","camp narache","chief hawkwind","greatmother hawkwind","mulgore","red cloud mesa","tauren elder","unaya","скромная просьба","лагерь нараче","вождь соколиный ветер","великая мать соколиный ветер","мулгор","плато красного облака","старейшина тауренов","унайя"},ang={["race:Tauren"]="Для молодых тауренов, начинающих путь на плато Красного Облака, Великая Мать Соколиный Ветер воплощает основные ценности Матери-Земли: уважение к старшим, общинную солидарность и смирение в служении."},sec={{t="Старейшина плато",b="Великая Мать Соколиный Ветер проводит дни у колодца со свежей водой в Лагере Нараче и служит духовной матриархом для молодых тауренов, начинающих обряды посвящения. Хотя годы замедлили ее шаг, она не позволяет возрасту отстранить себя от долга перед поселением. Она верит, что каждый член племени, молодой или старый, играет активную роль в поддержании общины, и часто просит юных новичков помочь с простыми домашними делами, например принести свежей воды."},{t="Материнское наставление",b="Будучи матерью вождя Соколиного Ветра, предводителя Лагеря Нараче, Великая Мать Соколиный Ветер дает неизменные советы и хранит тихое достоинство среди угроз, нависших над плато Красного Облака. Пока ее сын собирает охотников и воинов против наступающих свинобразов Дыбогривов и местных хищников, она заботится о моральном сердце поселения, напоминая только пробудившимся, что сила начинается со смирения и служения своим сородичам."}},faq={{q="Кто такая Великая Мать Соколиный Ветер?",a="Великая Мать Соколиный Ветер — пожилая матриарх тауренов, живущая в Лагере Нараче на плато Красного Облака. Она мать предводителя лагеря, вождя Соколиного Ветра, и служит старейшиной-наставницей для юных искателей приключений.",al={"greatmother hawkwind lore","who is greatmother hawkwind","camp narache elder","предания великой матери соколиный ветер","кто такая великая мать соколиный ветер","старейшина лагеря нараче"}},{q="Где ее можно найти?",a="Она сидит у колодца к юго-востоку от Лагеря Нараче, на плато Красного Облака на юго-западе Мулгора.",al={"greatmother hawkwind location","where is greatmother hawkwind","местонахождение великой матери соколиный ветер","где великая мать соколиный ветер"}},{q="Какие поручения она дает молодым тауренам?",a="Она поручает молодым тауренам задание «Скромная просьба»: набрать воды из колодца поселения и передать ее другим жителям лагеря. Эта работа учит, что ни одно дело не унизительно для истинного слуги племени.",al={"greatmother hawkwind quest","a humble task","задание великой матери соколиный ветер","скромная просьба"}},{q="Кем она приходится вождю Соколиному Ветру?",a="Она мать вождя Соколиного Ветра, который руководит обороной и обучением молодых воинов в Лагере Нараче.",al={"chief hawkwind mother","is she related to chief hawkwind","мать вождя соколиный ветер","родственница вождя соколиный ветер"}}},fp="20,247,17.476.0,19.413.0,28.203.0,23.96.0,40.205.0,39.107.0"}
P.entries["npc:grelin-whitebeard"] = {n="Грелин Белобород",s="Грелин Белобород — дворфийский разведчик, расквартированный в Холодной долине по королевскому указу для оценки угрозы со стороны троллей Мерзлогривов. Он действует из уединенного лагеря с неуклюжим подмастерьем и рассчитывает, что растущие в силе искатели приключений не дадут троллям вырваться, пока внимание Стальгорна поглощено кризисом троггов.",h="Грелин Белобород — дворфийский разведчик, расквартированный в Холодной долине по королевскому указу для...",kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","grik'nir","ironforge senate","senir whitebeard","the stolen journal","холодная долина","дун морог","мерзлогрив","грелин белобород","грик'нир","сенат стальгорна","сенир белобород","украденный дневник"},ang={["faction:Alliance"]="Бедственное положение Грелина показывает, как сильно растянуты армии Альянса и Стальгорна в Дун Мороге: одинокие разведчики вынуждены вести тихую войну против троллей в их укрытиях.",["race:Dwarf"]="Служа непосредственно королю Магни, Грелин олицетворяет тихую, упрямую стойкость разведчиков Стальгорна, удерживающих границы Дун Морога перед лицом растущих внутренних угроз.",["race:Gnome"]="Гномы-беженцы, только что пережившие трагедию Гномрегана, проходя через Холодную долину, застают Грелина в его отдаленном лагере за работой рядом с бродячим гномом."},sec={{t="Королевский наказ",b="Грелин Белобород и его брат Сенир были направлены в Холодную долину по прямому приказу Сената Стальгорна и самого короля Магни Бронзоборода. Их задача была ясна: оценить и устранить угрозу, исходящую от местных троллей Мерзлогривов. Поскольку официальная армия Стальгорна была полностью связана борьбой со вспышками троггов по всему Дун Морогу, братьям выделили совсем мало средств. Грелину пришлось основать форпост в заснеженных холмах и рассчитывать на местных новобранцев и проходящих новичков, которые выполнят необходимую работу."},{t="Беда на юге",b="Из своего лагеря Грелин следит за наступающим племенем Мерзлогривов к югу от Холодной долины. Тролли становятся все агрессивнее и устраивают все более дерзкие вылазки за пределы своих горных пещер. Во время одного из таких набегов раскрашенный здоровяк по имени Грик'нир Холодный проскользнул в оставленный без присмотра лагерь и унес полевой дневник Грелина с его важными наблюдениями. Не желая подвести Короля, Грелин посылает отважных путников вглубь пещер Мерзлогривов, чтобы вернуть украденные записи и убедиться, что его последние сведения дойдут до Сенира в Караносе."}},faq={{q="Почему Грелин Белобород находится здесь, в снегах?",a="Грелина официально направили Сенат Стальгорна и король Магни Бронзобород, чтобы расследовать и пресечь угрозу троллей Мерзлогривов в Холодной долине. Поскольку армия дворфов связана борьбой с угрозой троггов в других местах, Грелину приходится полагаться на независимых добровольцев.",al={"why is grelin here","grelin whitebeard purpose","who is grelin whitebeard","почему грелин здесь","задача грелина белоборода","кто такой грелин белобород"}},{q="Кто украл дневник Грелина?",a="Тролль из племени Мерзлогривов по имени Грик'нир Холодный совершил набег на лагерь Грелина, пока тот был без присмотра. Грелин лишь мельком увидел сильно разукрашенного здоровяка, убегающего с его полевыми записями в южные пещеры троллей.",al={"who stole the journal","stolen journal thief","grelin journal","кто украл дневник","вор дневника","дневник грелина"}},{q="Кто брат Грелина?",a="Его брат — Сенир Белобород, разведчик, расквартированный ниже по склону горы, в городке Каранос. Грелин собирает свои наблюдения за передвижениями троллей в отчеты и посылает доверенных гонцов, чтобы они доставили их прямо Сениру.",al={"grelin brother","senir whitebeard","who is senir","брат грелина","сенир белобород","кто такой сенир"}},{q="Кто находится с Грелином в его лагере?",a="Грелин делит свой небольшой лагерь с рассеянным подмастерьем-дворфом, так что толковой помощи у него почти нет, пока не прибудут способные новобранцы.",al={"whitebeard camp npcs","who is with grelin","grelin companions","персонажи лагеря белобородов","кто с грелином","спутники грелина"}},{q="Почему Стальгорн не присылает ему обычных солдат?",a="Защитники Стальгорна и силы Сената почти целиком поглощены повсеместным нашествием троггов, охватившим Дун Морог. Из-за этого такие разведчики, как Грелин, вынуждены решать региональные угрозы с помощью местных новобранцев.",al={"why no dwarven army","where is the ironforge guard","why no soldiers","почему нет армии дворфов","где стража стальгорна","почему нет солдат"}},{q="Что связывает Грелина с Джоной Железный Запас?",a="Джона Железный Запас — старый и верный друг Грелина. Находясь рядом с местом начала игры в Холодной долине, Джона направляет новых дворфов и гномов-новобранцев к лагерю Грелина.",al={"grelin and jona","jona ironstock","грелин и джона","джона железный запас"}}},fp="17,309,15.563.0,20.567.0,46.284.0,27.207.0,24.228.0,31.146.0,56.221.0,46.184.0"}
P.entries["npc:greta-mosshoof"] = {n="Грета Замшелое Копыто",s="Грета Замшелое Копыто — таурен-друид, союзница Изумрудного Круга в Изумрудном святилище на юге Оскверненного леса. Вместе с ночными эльфами и другими хранителями природы она изучает мерзостную порчу, расползающуюся по древнему лесу, и направляет разведчиков в оплот Совета Теней — Джеденар.",h="Грета Замшелое Копыто — таурен-друид, союзница Изумрудного Круга в Изумрудном святилище на юге Оскверненного...",kw={"corrupt water","emerald circle","emerald sanctuary","felwood","greta mosshoof","islen waterseer","jaedenar","оскверненная вода","изумрудный круг","изумрудное святилище","оскверненный лес","грета замшелое копыто","ислен заклинатель воды","джеденар"},ang={["class:Druid"]="Для друидов, стремящихся стереть шрамы, оставленные Пылающим Легионом, Грета Замшелое Копыто воплощает дух сотрудничества Кенария: она отбрасывает фракционные различия ради восстановления дикой природы Калимдора.",["race:Tauren"]="Грета показывает преданность тауренов делу исцеления ран Матери-Земли, даже далеко на севере, в землях, которые прежде охраняли одни лишь ночные эльфы."},sec={{t="Хранительница леса",b="Грета Замшелое Копыто несет службу в Изумрудном святилище на южной границе Оскверненного леса и вместе с Изумрудным Кругом борется со всепроникающей скверной, пожирающей древние леса. Она не желает отдавать зараженные земли демонической порче, оставшейся после Третьей войны, и координирует усилия, чтобы понять и остановить распространяющуюся гниль. Ее исследования сосредоточены на отравленных водах Оскверненного леса и мерзких культистах, засевших в Джеденаре."},{t="Удар по Совету Теней",b="Грета Замшелое Копыто сыграла важную роль в раскрытии замыслов Совета Теней, действующего из глубин Джеденара. Понимая, что оскверненные источники и мерзостные обереги в ущелье напрямую питают недуг, душащий землю, она привлекает путников: они должны взять пробы зараженной воды, обратиться за помощью к таким шаманам, как Ислен Заклинатель Воды на дальнем побережье, и уничтожить ритуальные жаровни, защищающие демонический культ от вторжения."}},faq={{q="Кто такая Грета Замшелое Копыто?",a="Грета Замшелое Копыто — таурен из Изумрудного Круга, несущая службу в Изумрудном святилище в Оскверненном лесу. Она помогает путникам и друидам исследовать и устранять демоническую порчу, отравляющую лес.",al={"greta mosshoof lore","who is greta mosshoof","greta felwood","грета замшелое копыто предания","кто такая грета замшелое копыто","грета оскверненный лес"}},{q="К какой фракции принадлежит Грета Замшелое Копыто?",a="Грета Замшелое Копыто состоит в Изумрудном Круге — нейтральной организации, посвятившей себя исцелению природы. Поэтому она дает советы и задания искателям приключений как из Альянса, так и из Орды.",al={"is greta mosshoof horde or alliance","greta mosshoof reputation","greta faction","грета замшелое копыто орда или альянс","грета замшелое копыто репутация","фракция греты"}},{q="Почему Грета отправляет искателей приключений в Джеденар?",a="Джеденар — оплот Совета Теней в Оскверненном лесу. Оттуда в водные потоки земли закачивают демоническую желчь и поддерживают обереги, укрывающие демонов. Грета направляет удары по Джеденару, чтобы разрушить их ритуалы и очистить зараженные источники.",al={"why jaedenar quest","greta mosshoof jaedenar","forces of jaedenar reason","почему задание джеденар","грета замшелое копыто джеденар","причина сил джеденара"}},{q="Какая связь у Греты Замшелого Копыта с Ислен Заклинательницей Воды?",a="Грета дружна с Ислен Заклинательницей Воды, мудрой шаманкой, живущей на побережье Степей. Найдя образцы оскверненной воды из Оскверненного леса, Грета отправляет искателей приключений к Ислен: ее духовное мастерство очистит жидкость, чтобы ею можно было очистить отравленные источники.",al={"greta and islen","islen waterseer connection","грета и ислен","связь с исленом заклинателем воды"}}},fp="14,297,22.465.0,30.441.1,22.202.0,43.181.0,47.265.0,55.268.0"}
P.entries["npc:grif-wildheart"] = {n="Гриф Дикое Сердце",s="Гриф Дикое Сердце — опытный дворфийский наставник охотников, который находится у таверны «Громоварка» в Караносе. Среди местных горцев он известен своей глубокой близостью к дикой природе и обучает начинающих стрелков выслеживанию, меткой стрельбе и обрядам приручения зверей. Для молодых охотников, покидающих Холодную долину, Гриф становится важным мостом между стрельбой из ружья и жизнью рядом с верным животным-спутником.",h="Гриф Дикое Сердце — опытный дворфийский наставник охотников, который находится у таверны «Громоварка» в...",kw={"beast taming","dun morogh","grif wildheart","hunter trainer","kharanos","mountaineer","taming the beast","thunderbrew distillery","укрощение зверей","дун морог","гриф дикое сердце","наставник охотников","каранос","горец","укрощение зверя","таверна громоварка"},ang={["class:Hunter"]="Гриф — необходимый наставник, посвящающий охотников Альянса в укрощение зверей: он выдает важные задания, позволяющие вам подружиться с дикими хищниками Дун Морога.",["faction:Alliance"]="Находясь в Караносе, Гриф готовит разведчиков и стрелков Альянса к выживанию в суровой глуши вокруг горного королевства Стальгорн.",["race:Dwarf"]="Воплощая традицию дворфов-горцев, Гриф показывает, что выносливость дворфа делает его исключительно подходящим для жизни бок о бок с дикими горными зверями."},sec={{t="Жизнь в дикой природе",b="Многие дворфы Стальгорна предпочитают жаркое тепло кузни или мерный стук кирок, но Гриф Дикое Сердце всецело посвятил жизнь морозным дебрям Дун Морога. Местные горцы вполголоса шутят, что он слишком много времени проводит с четвероногими зверями, но никто не спорит с его мастерством в науке дикой природы. Многие годы он выслеживал добычу на заснеженных хребтах вместе с опытными охотничьими спутниками, и потому прекрасно знает хищников, обитающих среди скал."},{t="Путь зверя",b="Когда молодые дворфы-охотники завершают начальные испытания в Холодной долине, их направляют прямиком в Каранос — за наставлениями Грифа. Он оттачивает их меткость и учит основам выживания в дикой природе, но главная его специальность — создание уз между охотником и зверем. В ходе строгих испытаний Гриф отправляет учеников в ледяные пустоши с жезлом укрощения, чтобы они проверили себя на знаковых хищниках Дун Морога: крупных скальных вепрях, снежных леопардах и ледяных медведях."},{t="Путь к Высокому трону",b="Когда охотник проявляет волю и самообладание, необходимые, чтобы усмирить трех разных диких зверей, обучение у Грифа в Караносе завершается. Понимая, что охотнику предстоит научиться кормить, дисциплинировать и тренировать нового союзника, он отправляет выпускников вверх по склону горы в Стальгорн. Там, под высокими сводами дворфийской столицы, начинающие охотники приходят к мастерам-укротителям, чтобы постичь искусство ухода за постоянным спутником на всю жизнь."}},faq={{q="Кто такой Гриф Дикое Сердце?",a="Гриф Дикое Сердце — дворф, наставник охотников в Караносе, в Дун Мороге. Он главный наставник начинающих охотников Альянса, которые осваивают ремесло за пределами Холодной долины.",al={"who is grif","grif wildheart identity","about grif","кто такой гриф","личность грифа дикое сердце","о грифе"}},{q="Где найти Грифа Дикого Сердца?",a="Он стоит на улице возле таверны «Громоварка» в деревне Каранос, у заснеженной дороги, ведущей из Туннеля Холодной долины в Стальгорн.",al={"grif wildheart location","where is grif","grif in kharanos","местонахождение грифа дикое сердце","где гриф","гриф в караносе"}},{q="Чему Гриф учит начинающих охотников?",a="Помимо общих умений охотника и приемов дальнего боя, Гриф проводит молодых охотников через испытания укрощения зверей и учит усмирять и подчинять диких вепрей, леопардов и медведей.",al={"what does grif teach","grif hunter training","grif skills","чему учит гриф","обучение охотников у грифа","навыки грифа"}},{q="Каких зверей Гриф посылает охотников укрощать?",a="Гриф поручает ученикам выследить и укротить трех особых существ Дун Морога: крупного скального вепря, снежного леопарда и ледяного медведя.",al={"grif taming quests","which animals to tame dun morogh","taming the beast targets","задания грифа на укрощение","каких животных укрощать в дун мороге","цели укрощения зверя"}},{q="Куда Гриф посылает охотников после испытаний укрощения?",a="Когда охотники доказывают умение укрощать диких животных, Гриф направляет их в город Стальгорн, к опытным укротителям, чтобы узнать о кормлении питомцев и управлении ими.",al={"where after grif","training the beast next step","grif follow up quest","куда после грифа","обучение зверя следующий шаг","продолжение задания грифа"}},{q="Что думают о Грифе горцы Стальгорна?",a="Местные горцы Стальгорна замечают, что Гриф проводит слишком много времени в обществе животных, а не людей, но охотно признают, что ремесло охотника он знает лучше почти всех.",al={"mountaineer opinion of grif","is grif respected","grif reputation","мнение горцев о грифе","уважают ли грифа","репутация грифа"}}},fp="14,424,19.495.0,20.507.0,24.472.0,22.187.0,32.138.0,36.200.0,43.152.0,66.188.0,49.198.0"}
P.entries["npc:grimbooze-thunderbrew"] = {n="Мрачнобух Громовар",s="Мрачнобух Громовар — эксцентричный дворф-пивовар из клана Громоваров, разбивший лагерь в Холмах Разбойничьих Кинжалов в Западном Крае. Он целыми днями варит крепкие напитки и говорит почти исключительно стихами.",h="Мрачнобух Громовар — эксцентричный дворф-пивовар из клана Громоваров, разбивший лагерь в Холмах Разбойничьих...",kw={"ale","brewer","dagger hills","distillery","grimbooze","kharanos","thunderbrew","westfall","эль","пивовар","холмы разбойничьих кинжалов","винокурня","мрачнобух","каранос","громовар","западный край"},ang={["profession:Cooking"]="Искатели приключений-кулинары и мастера напитков чтят наследие Громоваров, и встреча с Мрачнобухом становится уроком искусного пивоварения.",["race:Dwarf"]="Каждый дворф знает имя Громоваров, и встретить одного из их старейшин, варящего необычные напитки в холмах Западного Края, — приятный привкус Дун Морога."},sec={{t="Пивовар в изгнании",b="Мрачнобух родом из знаменитой пивоваренной семьи Громоваров из Караноса. Он покинул заснеженные вершины Дун Морога ради продуваемых ветрами холмов Западного Края. Известный веселым нравом и неуемной страстью к крепким напиткам, он имеет странную привычку говорить только в рифму и отвечает на вопросы путника лишь после того, как тот выполнит для него простое поручение. Путники, проходящие через опасные Холмы Разбойничьих Кинжалов, найдут его возле личных бочонков, всегда готового испытать вкус жаждущего гостя."}},faq={{q="Где найти Мрачнобуха Громовара?",a="Мрачнобух Громовар находится в Холмах Разбойничьих Кинжалов на юге Западного Края, где разбил лагерь среди холмов со своим пивоваренным оборудованием.",al={"grimbooze location","where is grimbooze","where to find grimbooze thunderbrew","местонахождение мрачнобуха","где мрачнобух","где найти мрачнобуха громовара"}},{q="Почему Мрачнобух говорит в рифму?",a="Никто не знает наверняка. Мрачнобух просто любит стихи и настаивает, что каждый, у кого к нему есть вопрос, должен сначала выполнить простое поручение.",al={"why does grimbooze rhyme","grimbooze rhyming","why is he talking in verse","почему мрачнобух рифмует","мрачнобух говорит в рифму","почему он говорит стихами"}},{q="Как он связан с таверной «Громоварка»?",a="Мрачнобух принадлежит к знаменитому клану Громоваров из Караноса в Дун Мороге. Пока родичи вроде Рагнара Громовара присматривают за семейной винокурней дома, Мрачнобух варит в одиночку на холмах Западного Края.",al={"grimbooze distillery","is grimbooze related to ragnar","thunderbrew family","мрачнобух винокурня","родня ли мрачнобух рагнару","семья громоваров"}}},fp="21,205,17.528.0,39.144.0,36.149.0,53.204.0"}
P.entries["npc:grish-longrunner"] = {n="Гриш Выносливый Гонец",s="Гриш Выносливый Гонец — таурен-разведчик и посыльный у Великого Подъемника, важной механической переправы между югом Степей и каньонами Тысячи Игл. Служа интересам Орды на этой оживленной границе, он наблюдает за путниками и координирует передвижение войск через рубеж.",h="Гриш Выносливый Гонец — таурен-разведчик и посыльный у Великого Подъемника, важной механической переправы...",kw={"barrens","calling in the reserves","great lift","grish","longrunner","tauren","thousand needles","степи","смена караула","великий подъемник","гриш","выносливый гонец","таурен","тысяча игл"},ang={["faction:Horde"]="Для курьеров и воинов Орды, идущих на юг к Тысяче Игл или возвращающихся на север в Степи, Гриш служит важным наблюдателем и связным у подъемника.",["race:Tauren"]="Гриш, носящий гордое имя Выносливого Гонца, воплощает выносливость и бдительность шу'хало, оберегающих важные пути по землям предков."},sec={{t="Страж у Подъемника",b="Гриш Выносливый Гонец стоит на страже прямо у громадного механизма Великого Подъемника, одной из самых опасных пограничных переправ центрального Калимдора. Платформенный подъемник — это путь, связывающий засушливые пустоши юга Степей с продуваемыми ветрами плато Тысячи Игл внизу. Из-за бродячих стай свинобразов и других соперничающих угроз путь по этой вертикальной границе опасен, поэтому такие разведчики, как Гриш, необходимы, чтобы Орда была в курсе и могла вызвать подкрепление там, где оно остро нужно."}},faq={{q="Кто такой Гриш Выносливый Гонец?",a="Гриш Выносливый Гонец — таурен-разведчик на стороне Орды, несущий службу у края Великого Подъемника, который спускается из Степей в Тысячу Игл.",al={"who is grish","grish longrunner identity","what does grish do","кто такой гриш","личность гриша выносливого гонца","чем занимается гриш"}},{q="Где найти Гриша Выносливого Гонца?",a="Он находится на юге Степей, прямо у механического входа на Великий Подъемник, ведущий вниз, в Тысячу Игл.",al={"grish longrunner location","where is grish","find grish","местонахождение гриша выносливого гонца","где гриш","найти гриша"}},{q="Какую роль он играет в этой местности?",a="Гриш служит связным для посыльных и путников Орды и помогает собирать и направлять местные подкрепления, в частности по просьбам вроде задания «Смена караула».",al={"grish purpose","grish quests","calling in the reserves grish","цель гриша","задания гриша","смена караула гриш"}}},fp="16,329,19.537.0,24.164.0,34.140.0,35.180.0"}
P.entries["npc:grub"] = {n="Грязнуля",s="Грязнуля — предприимчивый орк, живущий в придорожной хижине к востоку от Перекрестка в Степях. Он держит скромную пограничную закусочную вместе с поваром и пекарем и славится — или печально известен — тем, что открыл путникам кулинарное применение местных паразитов.",h="Грязнуля — предприимчивый орк, живущий в придорожной хижине к востоку от Перекрестка в Степях.",kw={"barrens","crossroads","dig rat stew","duhng","grub","tarban hearthgrain","степи","перекресток","крысиная похлебка","дунг","грязнуля","тарбан зерноочаг"},ang={["faction:Horde"]="Придорожная кухня Грязнули у самого Перекрестка дает путникам Орды сытную еду и урок находчивости в суровых степях.",["profession:Cooking"]="Грязнуля — важная остановка для начинающих пограничных поваров: он готов поделиться рецептом крысиной похлебки с каждым, кто достаточно смел, чтобы собрать ингредиенты."},sec={{t="Аппетит пограничья",b="Грязнуля, поселившийся у скал к востоку от Перекрестка, присматривает за простым жилищем, которое делит с Дунгом, своим поваром, и пекарем Тарбаном Зерноочагом. Жизнь в степях требует крепкого желудка, а Грязнуля доводит пограничную самостоятельность до крайности. Вместо того чтобы позволять обильным копателям-крысам Степей пропадать зря, он сделал их основным ингредиентом и предлагает учить странников варить из подземных грызунов наваристую, хотя и неприглядную похлебку."}},faq={{q="Кто такой Грязнуля?",a="Грязнуля — орк, живущий в хижине к востоку от Перекрестка в Степях. Он держит небольшое заведение вместе с поваром Дунгом и пекарем Тарбаном Зерноочагом и кормит путников, идущих через пыльное пограничье.",al={"grub","who is grub","orc east of crossroads","грязнуля","кто такой грязнуля","орк к востоку от перекрестка"}},{q="Где найти Грязнулю?",a="Грязнулю можно найти к востоку от Перекрестка, у подножия гор в Степях, в небольшом жилище неподалеку от главной тропы.",al={"grub location","where is grub","grub hut","местонахождение грязнули","где грязнуля","хижина грязнули"}},{q="С чем нужна помощь Грязнуле?",a="Грязнуля просит путников добыть в Степях копателей-крыс, из которых варит свою фирменную крысиную похлебку. Взамен он делится рецептом с поварами, готовыми ее приготовить.",al={"grub quest","dig rat stew quest","задание грязнули","задание крысиная похлебка"}}},fp="4,263,19.477.0,12.229.0,22.144.0,30.181.0"}
P.entries["npc:grull-hawkwind"] = {n="Грулл Соколиный Ветер",s="Грулл Соколиный Ветер — молодой воин-таурен, несущий службу в Лагере Нараче на Плато Красного Облака в Мулгоре. Как сын вождя Соколиного Ветра, он помогает направлять юных таурен, делающих первые шаги в мире. Он ведет молодых охотников и воинов через первые испытания, проверяя их решимость и чествуя предков.",h="Грулл Соколиный Ветер — молодой воин-таурен, несущий службу в Лагере Нараче на Плато Красного Облака в...",kw={"camp narache","chief hawkwind","grull hawkwind","mulgore","red cloud mesa","rite of strength","tauren","лагерь нараче","вождь соколиный ветер","грулл соколиный ветер","мулгор","плато красного облака","обряд силы","таурены"},ang={["class:Hunter"]="Грулл дает начинающим охотникам основные первые поручения, проверяя их терпение и мастерство на местной фауне Мулгора.",["race:Tauren"]="Для юных таурен, впервые ступающих на Плато Красного Облака, Грулл Соколиный Ветер нередко оказывается первым воином, который испытывает их силу и знакомит с традициями шу'хало."},sec={{t="Сын вождя",b="Стоя гордо рядом с воинами и старейшинами Лагеря Нараче, Грулл Соколиный Ветер несет и благородное происхождение от вождя Соколиного Ветра, и ответственность за подготовку молодежи племени. Он служит первым наставником для новичков на Плато Красного Облака и оценивает их готовность служить шу'хало. Давая испытания на выносливость, выслеживание и выживание в схватках с местными зверями, такими как бегуны по равнинам и горные пумы, Грулл следит, чтобы юные таурены понимали: равновесие и уважение к природе — основа жизни в Мулгоре."}},faq={{q="Кто такой Грулл Соколиный Ветер?",a="Грулл Соколиный Ветер — таурен, выдающий задания в Лагере Нараче на Плато Красного Облака. Он сын вождя Соколиного Ветра, предводителя поселения, и один из главных наставников для молодых таурен, начинающих свой путь.",al={"grull hawkwind role","who is grull","grull hawkwind lore","грулл соколиный ветер роль","кто такой грулл","грулл соколиный ветер предания"}},{q="Какую роль играет Грулл Соколиный Ветер для юных искателей приключений?",a="Грулл оценивает базовую подготовку юных таурен, получает вводные сведения от старейшин племени и поручает молодежи первые испытания в охоте и выживании на окрестных равнинах.",al={"grull quests","what does grull do","grull hawkwind purpose","задания грулла","что делает грулл","зачем нужен грулл соколиный ветер"}},{q="Грулл связан с руководством лагеря?",a="Да, Грулл — сын вождя Соколиного Ветра, предводителя Лагеря Нараче. Он чтит традиции отца и помогает готовить защитников лагеря.",al={"chief hawkwind son","grull hawkwind family","is grull related to the chief","сын вождя соколиного ветра","семья грулла соколиного ветра","родственник ли грулл вождю"}}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:grunt-dogran"] = {n="Рубака Догран",s="Рубака Догран — орк-солдат Орды, находящийся в плену в глубине земель свинобразов на юге Степей. Сначала его направили на Перекресток, затем в Лагерь Таурахо, а его патруль потерпел неудачу во время набега на Агама'гор.",h="Рубака Догран — орк-солдат Орды, находящийся в плену в глубине земель свинобразов на юге Степей.",kw={"agama'gor","barrens","camp taurajo","crossroads","dogran","dorgran","grunt dogran","quilboar","агама'гор","степи","лагерь таурахо","перекресток","догран","рубака догран","свинобразы"},ang={["faction:Horde"]="Его плен показывает, какую высокую цену платят гарнизоны Орды за защиту торговых дорог и границ в Степях от агрессивных племен свинобразов.",["race:Orc"]="Догран воплощает традиционный орочий идеал: смерть в бою почетнее, чем жизнь беспомощным калекой."},sec={{t="Долг рубаки",b="После повышения в армии Орды Рубаку Дограна отправили с Перекрестка усилить Лагерь Таурахо. Во главе отряда рубак он вошел в щетинистые земли Агама'гора, где его отряд яростно столкнулся со свинобразами-дыбогривами. Тяжело раненный и искалеченный в схватке, Догран не мог быть унесен отступавшими товарищами и попал в плен."},{t="Достойная судьба",b="Хотя Догран заперт в тылу врага и искалечен ранами, он сохраняет упрямую гордость, свойственную орочьим воинам. Вместо того чтобы вернуться домой сломленным и заставить подругу ухаживать за калекой, он решил дать свинобразам последний бой, прося лишь передать той, кого любит, знак его неугасающей преданности."}},faq={{q="Где находится Рубака Догран?",a="Догран томится в плену в Агама'горе, густонаселенном лагере свинобразов на юге Степей, к северу от Лагеря Таурахо.",al={"dogran location","where is dogran","find dogran barrens","где догран","местонахождение дограна","найти дограна степи"}},{q="Почему Дограна взяли в плен свинобразы?",a="Когда Догран вел патруль из Лагеря Таурахо для удара по свинобразам, в схватке он получил увечья. Товарищи не смогли вовремя вынести его, и он остался на милость чудовищ.",al={"why was dogran captured","how did dogran get caught","почему догран в плену","как догран попал в плен"}},{q="Почему Догран отказывается от спасения?",a="Догран навсегда искалечен в бою и отказывается возвращаться домой обузой для подруги. По-орочьи он предпочитает умереть на своих условиях в бою со свинобразами, чем доживать дни калекой.",al={"why wont dogran leave","dogran rescue","почему догран не уходит","спасение дограна"}},{q="Кто разыскивает Дограна?",a="Тревога из-за его исчезновения идет с Перекрестка и из Лагеря Таурахо, где разведчики и солдаты по крупицам восстанавливают судьбу пропавшего патруля.",al={"who sent me for dogran","dogran quest giver","кто послал за дограном","догран задания"}}},fp="12,236,14.400.0,17.335.1,30.126.0,40.210.0,37.209.1,26.153.0"}
P.entries["npc:grunt-logmar"] = {n="Рубака Логмар",s="Рубака Логмар — орк-воин Орды, несущий службу на юге Степей в Лагере Таурахо. Исполнительный и бдительный, он следит за угрозами вокруг лагеря и координирует поиски и помощь пропавшим разведчикам Орды в этом краю.",h="Рубака Логмар — орк-воин Орды, несущий службу на юге Степей в Лагере Таурахо.",kw={"camp taurajo","dogran","grunt logmar","ken'zigla's draught","orc grunt","taurajo","the barrens","лагерь таурахо","догран","рубака логмар","настой кен'зиглы","орк-рубака","таурахо","степи"},ang={["faction:Horde"]="Логмар олицетворяет передовое военное присутствие, поддерживающее таурен в Степях, и полагается на героев Орды, которые заботятся о павших и плененных разведчиках.",["race:Orc"]="Будучи орком-рубакой вдали от Оргриммара, Логмар показывает готовность Орды стоять плечом к плечу со своими союзниками-таурен."},sec={{t="Служба в Лагере Таурахо",b="Находясь среди таурен в Лагере Таурахо, Рубака Логмар служит зорким орком-стражем на южной границе Степей. Поселение расположено близ враждебных земель свинобразов и горных перевалов, ведущих в Когтистые горы и Мулгор, поэтому требуется постоянная бдительность. Логмар координирует донесения разведчиков и обращается к способным путникам Орды, когда его товарищи попадают в засаду или в плен к местным врагам."}},faq={{q="Кто такой Рубака Логмар?",a="Рубака Логмар — орк-солдат, несущий службу в Лагере Таурахо на юге Степей. Он служит Орде, охраняя поселение и руководя спасательными и разведывательными заданиями.",al={"grunt logmar","who is logmar","logmar barrens","рубака логмар","кто такой логмар","логмар степи"}},{q="Где можно найти Рубаку Логмара?",a="Он находится в Лагере Таурахо, форпосте на южных равнинах Степей, у дороги к Великому Подъемнику и в Тысячу Игл.",al={"where is logmar","logmar location","find grunt logmar","где логмар","местонахождение логмара","найти рубаку логмара"}},{q="Какими делами занимается Логмар?",a="Логмар заботится о безопасности пропавших разведчиков Орды: он поручает путникам выяснить, что случилось с рубакой Догран и почему он в плену, и добыть важные припасы, например настой Кен'зиглы.",al={"logmar quests","what does logmar want","dogran rescue","задания логмара","что нужно логмару","спасение дограна"}}},fp="12,235,20.419.0,20.174.0,32.155.0,33.201.0"}
P.entries["npc:grunth"] = {n="Грунт",s="Грунт — энергичный юный орк-сирота, живущий на попечении оргриммарского приюта на Тракте. Во время Детской недели он с радостью сопровождает героев Орды в больших путешествиях по Калимдору и Восточным королевствам, чтобы узнать, что значит быть героем.",h="Грунт — энергичный юный орк-сирота, живущий на попечении оргриммарского приюта на Тракте.",kw={"children's week","grunth","orc orphan","orgrimmar","orphan matron battlewail","orphan whistle","the drag","детская неделя","грунт","орк-сирота","оргриммар","попечительница сирот батлвейл","свисток сироты","тракт"},ang={["faction:Horde"]="Опека над Грунтом в Детскую неделю напоминает героям Орды, что защищает их фракция: растущее поколение, рожденное свободным, а не в демонической кабале.",["race:Orc"]="Грунт воплощает молодежь Дуротара: он растет, зная племенную честь и выживание, а не мрачное оцепенение лагерей для интернированных."},sec={{t="Любопытное дитя Орды",b="Живя на Тракте Оргриммара под присмотром Попечительницы сирот Батлвейл, Грунт представляет новое поколение молодой Орды. Как и многие юные зеленокожие, выросшие в суровых красных пустошах Дуротара, он смотрит на закованных в броню искателей приключений с изумлением и задает бесконечные вопросы: правда ли воины в доспехах страшные, почему молния в воде не убивает всю рыбу и увидит ли он когда-нибудь бой с настоящим драконом."},{t="Путешествия Детской недели",b="When festival season arrives, adventurers blow an Orcish Orphan Whistle to summon Grunth and take him on an expansive tour across the world. His bucket list spans the breadth of the Horde's domain: seeking an audience with High Chieftain Cairne Bloodhoof in Mulgore, venturing into the ruined throne room of Lordaeron, and visiting the rugged frontiers where his people fight for their future."}},faq={{q="Кто такой Грунт?",a="Грунт — орк-ребенок, живущий в оргриммарском приюте на Тракте. О нем заботится Попечительница сирот Батлвейл, и он мечтает стать легендарным героем Орды.",al={"grunth npc","orc orphan","orgrimmar orphan","грунт","орк-сирота","сирота оргриммара"}},{q="Где можно найти Грунта?",a="Он живет на Тракте в Оргриммаре с другими сиротами, но во время Детской недели искатель приключений может призвать его где угодно с помощью Свистка орка-сироты, полученного у Попечительницы сирот Батлвейл.",al={"grunth location","where is grunth","find grunth","где грунт","местонахождение грунта","найти грунта"}},{q="Какие места хочет посетить Грунт?",a="Grunth yearns to see the greatest icons of the Horde. His requests include visiting High Chieftain Cairne Bloodhoof in Thunder Bluff, touring the Ratchet docks, and traveling all the way to the ruined throne room of Lordaeron.",al={"grunth quests","what does the orphan want","grunth tour","задания грунта","чего хочет сирота","путешествие грунта"}},{q="Какой у Грунта характер?",a="Грунт шумный, любопытный и невероятно фантазирует. Он постоянно сыплет нелепыми загадками и детскими вопросами в адрес сопровождающих его героев: что на самом деле значит «зуг-зуг», как называется муха без крыльев — «ходун», и как бы между прочим сообщает, что засунул камень в нос.",al={"grunth quotes","grunth dialogue","what does grunth say","цитаты грунта","диалоги грунта","что говорит грунт"}}},fp="6,260,28.483.0,24.393.0,14.169.0,26.194.0,38.226.0,42.291.0"}
P.entries["npc:gryan-stoutmantle"] = {n="Гриан Камнегрив",s="Гриан Камнегрив — паладин Серебряной Длани и командир Народного ополчения, действующий из Сторожевого холма в Западном Крае. Уроженец Западного Края, он вернулся из разоренного северного королевства Лордерон, чтобы защитить родину, после того как корона Штормграда бросила эти земли на произвол бандитов.",h="Гриан Камнегрив — паладин Серебряной Длани и командир Народного ополчения, действующий из Сторожевого холма в...",kw={"deadmines","gryan","people's militia","sentinel hill","silver hand","stoutmantle","vancleef","westfall","wiley","мертвые копи","гриан","народное ополчение","сторожевой холм","серебряная длань","камнегрив","ван клиф","западный край","вилли"},ang={["class:Paladin"]="Камнегрив — живой пример долга Серебряной Длани: когда высшие советы церкви и короны игнорировали бедняков, он принес защиту Света прямо скромным земледельцам, которые нуждались в ней больше всех.",["faction:Alliance"]="Опора Гриана на независимых добровольцев обнажает горькие трещины в сердце земель Альянса, где политическое бездействие в Штормграде вынуждает верных граждан браться за оружие самим.",["race:Human"]="Уроженец Западного Края, Гриан воплощает стойкость сельских жителей Штормграда, держащихся против местных разбойников и бюрократического безразличия столицы."},sec={{t="Рыцарь, вернувшийся домой",b="Гриан Камнегрив начал службу вдали от тихих полей южного Азерота. В молодости он отправился на север, в Лордерон, принял обет рыцаря Серебряной Длани и пережил ужасы Третьей войны, даже став свидетелем трагического очищения Стратхольма, проведенного принцем Артасом Менетилом. Когда до него дошла весть, что его родная провинция Западный Край погружается в беззаконие, захваченная организованными разбойниками и брошенная короной, Гриан покинул северные фронты. Он променял имперские поля сражений на защиту честных земледельцев, поклявшись, что его дом не падет, как пал север."},{t="Народное ополчение",b="Вернувшись, Гриан обнаружил, что Западный Край почти не защищен. Из-за пренебрежения короны и политического паралича в Доме знати Штормград отказался присылать гарнизонные войска. В ответ Камнегрив основал на Сторожевом холме Народное ополчение, собрав местных фермеров, дозорных и странствующих наемников в добровольческий отряд обороны. Его силы с трудом удерживают рубеж против Братства Справедливости, гноллов-речных лап и враждебных механизмов и не могут выделить подкрепление, даже когда соседние поселения, такие как Приозерье, просят о помощи."},{t="Разоблачение главаря",b="Не желая сражаться вслепую, Камнегрив обратился к разветвленной сети осведомителей, чтобы выяснить, кто стоит за разорением Западного Края. Потребовав старый долг у темного плута Вилли Черного в Красногорье и посоветовавшись с Матиасом Шоу из ШРУ, Гриан раскрыл тайну: бандитов возглавлял Эдвин ван Клиф, обиженный главный зодчий Гильдии каменщиков. После того как ополчение схватило бандита, пытавшегося ограбить местную повозку, Гриан с помощью предателя определил штаб Братства, скрытый под Луноречьем в Мертвых копях, и поручил опытным бойцам убить ван Клифа."}},faq={{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — паладин Серебряной Длани, основатель и командир Народного ополчения, добровольческого гарнизона со штабом на Сторожевом холме, защищающего Западный Край.",al={"who is gryan","stoutmantle lore","leader of westfall","кто такой гриан","камнегрив предания","глава западного края"}},{q="Зачем нужно Народное ополчение, если Западный Край принадлежит Штормграду?",a="Дом знати Штормграда отказался выделять королевских солдат и средства казны на защиту отдаленной провинции. Брошенные на произвол судьбы перед мародерами и гноллами, местные крестьяне под руководством Гриана создали собственные независимые силы обороны.",al={"why militia","where is stormwind army","why did stormwind abandon westfall","зачем ополчение","где армия штормграда","почему штормград бросил западный край"}},{q="Что связывает Гриана с Серебряной Дланью?",a="В юности Гриан отправился в Лордерон, чтобы стать священным паладином Серебряной Длани. Он служил на северных полях сражений во время Третьей войны и присутствовал при очищении Стратхольма, после чего отправился на юг спасать свою родину.",al={"is gryan a paladin","gryan silver hand","gryan in lordaeron","гриан паладин","гриан серебряная длань","гриан в лордероне"}},{q="Почему Гриан отказывается посылать помощь в Приозерье?",a="Когда мировой судья Соломон из Приозерья попросил подкрепление против гноллов и орков Красногорья, Гриан был вынужден отказать. Народное ополчение предельно измотано удержанием Сторожевого холма: даже небольшой отряд привел бы к падению Западного Края под натиском Братства Справедливости.",al={"magistrate solomon request","help redridge","why no troops to lakeshire","просьба судьи соломона","помощь красногорью","почему нет войск в приозерье"}},{q="Как Гриан узнал, где прячется Братство Справедливости?",a="Благодаря сведениям от Вилли Черного и главы шпионов ШРУ Матиаса Шоу Гриан разоблачил Эдвина ван Клифа как вдохновителя. Затем ополчение схватило вора, известного как Предатель Братства Справедливости, который привел силы Альянса прямо к базе Братства в Мертвых копях под Луноречьем.",al={"finding deadmines","who found vancleef","defias traitor story","поиск мертвых копей","кто нашел ван клифа","история предателя братства"}},{q="Кто такой Вилли Черный для Гриана?",a="Вилли Черный — осведомитель, живущий в таверне Приозерья, который был обязан Гриану жизнью. Хотя Камнегрив не питает симпатии к сомнительной натуре плута, он воспользовался этим долгом, чтобы получить важные сведения о действиях Братства Справедливости.",al={"wiley and gryan","wiley the black debt","вилли и гриан","долг вилли черного"}}},fp="17,298,22.599.0,20.546.0,21.617.1,25.178.0,68.259.0,45.247.0,47.290.0,52.281.1,32.245.0"}
P.entries["npc:guard-berton"] = {n="Стражник Бертон",s="Стражник Бертон — человек, городской стражник, стоящий у таверны Приозерья в Красногорье. Разочарованный бюрократической волокитой судебной системы Штормграда, он добивается скорого правосудия над Таргорром Ужасным, пленным вождем орков.",h="Стражник Бертон — человек, городской стражник, стоящий у таверны Приозерья в Красногорье.",kw={"berton","guard berton","lakeshire","redridge","targorr","targorr the dread","the stockade","what comes around","бертон","стражник бертон","приозерье","красногорье","таргорр","таргорр ужасный","тюрьма"},ang={["faction:Alliance"]="Бертон олицетворяет растущее разочарование сельских поселений Альянса, где местные защитники видят, как центральная бюрократия Штормграда откладывает правосудие, пока пограничные города борются за выживание."},sec={{t="Стражник в поисках правосудия",b="Пока Красногорье трещит под угрозой вторжения орков Черной горы, стражник Бертон остается на посту у таверны Приозерья. Хотя местная оборона на грани краха, внимание Бертона приковано к пленному врагу — Таргорру Ужасному. Таргорра взяли в плен и заточили глубоко в Тюрьме Штормграда, приговорив к смерти за преступления против королевства. Но поскольку казнь в Штормграде отложена на неопределенный срок, Бертон не желает, чтобы жестокий налетчик сидел в камере, пока Приозерье истекает кровью. Он берет дело в свои руки и нанимает искателей приключений, чтобы в обход королевских проволочек казнить орка."}},faq={{q="Кто такой стражник Бертон?",a="Стражник Бертон — страж Альянса, стоящий у таверны Приозерья в Красногорье. Он известен главным образом тем, что нанимает искателей приключений, чтобы свершить правосудие над печально известным пленным орком.",al={"berton lakeshire","who is berton","бертон приозерье","кто такой бертон"}},{q="Почему стражник Бертон хочет убить Таргорра Ужасного?",a="Таргорр Ужасный был приговорен к казни за свои преступления, но руководство Штормграда приостановило приговор. Разочарованный этим промедлением, пока Красногорье остается в осаде, Бертон устраивает так, чтобы Таргорра убили в Тюрьме.",al={"why kill targorr","targorr execution","what comes around quest lore","зачем убивать таргорра","казнь таргорра","предания задания что посеешь"}},{q="Где содержится Таргорр Ужасный?",a="Таргорр заключен в Тюрьме — подземелье строгого режима в районе Каналов Штормграда.",al={"targorr location","where is targorr","местонахождение таргорра","где таргорр"}},{q="Где можно найти стражника Бертона?",a="Он несет вахту у входа в таверну Приозерья, наблюдая за центром Приозерья в Красногорье.",al={"where is berton","berton location","где бертон","местонахождение бертона"}}},fp="12,240,23.633.0,20.196.0,52.246.0,32.119.0,32.117.0"}
P.entries["npc:guard-howe"] = {n="Стражник Хоув",s="Стражник Хоув — городской стражник у южного подножия моста Приозерья в Красногорье. Движимый личной местью оркам Черной горы, вторгающимся в долину, он предлагает награды любому искателю приключений, готовому сразить захватчиков.",h="Стражник Хоув — городской стражник у южного подножия моста Приозерья в Красногорье.",kw={"blackrock bounty","blackrock orcs","guard howe","howe","lakeshire","redridge","награда за орков черной горы","орки черной горы","стражник хоув","хоув","приозерье","красногорье"},ang={["faction:Alliance"]="Приозерье почти не получает прямой помощи от Штормграда, и передовым стражникам вроде Хоува приходится рассчитывать на заходящих героев Альянса, чтобы орки Черной горы не захлестнули город."},sec={{t="Обида у моста",b="Стражник Хоув стоит чуть южнее большого каменного моста через Озеро Безмолвия и охраняет сердце Приозерья. Как и многие в осажденном городке, он видит в наступающих орках Черной горы смертельную угрозу для Красногорья. Питая горькую жажду мести клану, Хоув вербует проходящих наемников для охоты на орков в восточных холмах, обещая плату за вещественные доказательства их гибели."}},faq={{q="Кто такой стражник Хоув?",a="Стражник Хоув — человек, городской стражник, стоящий к югу от моста в Приозерье в Красногорье. Он помогает защищать поселение и направляет способных бойцов нанести ответный удар по вторгшимся оркам Черной горы.",al={"guard howe","howe lakeshire","who is howe","стражник хоув","хоув приозерье","кто такой хоув"}},{q="Почему стражник Хоув хочет убивать орков Черной горы?",a="Хоув питает личную ненависть к клану Черной горы, который глубоко проник в Красногорье и подвергает Приозерье непрестанному давлению. Он жаждет мщения и предлагает награды всем, кто сократит их ряды.",al={"why blackrock bounty","howe orcs","why does howe hate orcs","почему награда за орков черной горы","хоув орки","почему хоув ненавидит орков"}},{q="Состоит ли стражник Хоув в родстве с кем-то в этом краю?",a="У него общая фамилия с Соломаном Хоувом, что наводит на мысль о родстве, но он сосредоточен исключительно на службе — охране города и борьбе с орками.",al={"howe relatives","soloman howe relation","родственники хоува","родство соломана хоува"}}},fp="10,269,22.433.0,18.224.0,47.229.0,51.156.0"}
P.entries["npc:guard-thomas"] = {n="Стражник Томас",s="Стражник Томас — преданный солдат Армии Штормграда, стоящий на мосту к западу от Лесопилки Восточной долины. Изолированный на восточной границе Элвиннского леса, он руководит защитой местных поселенцев от хищных зверей и наступающих мурлоков.",h="Стражник Томас — преданный солдат Армии Штормграда, стоящий на мосту к западу от Лесопилки Восточной долины.",kw={"eastvale","eastvale logging camp","elwynn forest","guard thomas","lost guards","murloc","stormwind army","thomas","восточная долина","лесопилка восточной долины","элвиннский лес","стражник томас","пропавшие стражники","мурлок","армия штормграда","томас"},ang={["class:Warrior"]="Для юных воинов Альянса Томас олицетворяет дисциплину на передовой и негероическую повседневность обороны границ.",["faction:Alliance"]="Стражник Томас воплощает перенапряженное состояние Армии Штормграда, удерживающей важный форпост на границе с минимальной поддержкой короны."},sec={{t="На восточной границе",b="Пока внимание королевства обращено внутрь, к столице, или на запад, к Западному Краю, стражник Томас несет один из самых тихих, но опасных постов в Элвиннском лесу. Стоя у каменного моста через реку по пути к Лесопилке Восточной долины, Томас служит тонкой линией защиты между обычными лесорубами и агрессивными тварями, бродящими по лесу. Из-за нехватки сил Армии Штормграда стражники вроде Томаса вынуждены во многом полагаться на проходящих искателей приключений, чтобы поддерживать порядок и доставлять донесения в главное командование."},{t="Беды границы",b="Восточные окраины Элвиннского леса постоянно находятся под давлением. Агрессивные медведи и хищники рыщут у опушки, угрожая лесорубам и путникам, а странные племена мурлоков устроили стоянки вдоль водных путей. Томас следит за передвижениями этих водных хищников и назначает награды за сокращение их числа. Хуже того, разведывательные патрули вдоль реки время от времени бесследно исчезают, и Томасу приходится по крупицам выяснять судьбу своих товарищей на фоне растущей нестабильности в регионе."}},faq={{q="Где найти стражника Томаса?",a="Стражник Томас стоит на каменном мосту через реку к западу от Лесопилки Восточной долины, на восточной дороге в Элвиннском лесу.",al={"guard thomas location","where is thomas","guard thomas bridge","где стражник томас","где томас","стражник томас мост"}},{q="В чем состоит долг стражника Томаса в Элвиннском лесу?",a="Он офицер Армии Штормграда, назначенный охранять восточную границу Элвиннского леса. В его обязанности входит охрана торгового моста, защита рабочих поблизости от диких хищников и наблюдение за вторжениями враждебных мурлоков вдоль берегов реки.",al={"what does thomas do","guard thomas role","thomas eastvale","чем занимается томас","роль стражника томаса","томас восточная долина"}},{q="Почему стражник Томас просит помочь с пропавшими стражниками?",a="Обычные патрули, отправленные в речные низины, не вернулись с донесениями. Не имея достаточно подкрепления, чтобы оставить пост без присмотра, Томас нанимает странствующих искателей приключений, чтобы они обыскали водные пути и выяснили, что случилось с его пропавшими товарищами.",al={"lost guards elwynn","guard thomas missing scouts","what happened to the guards","пропавшие стражники элвинн","стражник томас пропавшие разведчики","что случилось со стражниками"}},{q="Почему мурлоки создают проблемы стражнику Томасу?",a="Племена мурлоков все чаще пробираются вверх по речным системам восточной части Элвиннского леса. Их растущее присутствие угрожает и местным лесозаготовкам, и сухопутным торговым путям, поэтому Томас назначил открытую награду за их плавники, чтобы водные пути оставались чистыми.",al={"murlocs eastvale","why kill murlocs","guard thomas murloc bounty","мурлоки восточная долина","зачем убивать мурлоков","награда за мурлоков стражник томас"}},{q="Кому подчиняется стражник Томас?",a="Томас служит в Армии Штормграда и по военной иерархии отчитывается перед региональным командованием в Златоземье и перед столицей. По мере ухудшения обстановки за границами его донесения также согласуются с руководством приграничья, например с Грианом Камнегривом в Западном Крае.",al={"thomas superior","stormwind army chain of command","who does thomas work for","начальник томаса","цепочка командования армии штормграда","на кого работает томас"}},{q="Куда стражник Томас направляет искателей приключений после завершения дел в Элвиннском лесу?",a="Когда ближайшие угрозы у Лесопилки Восточной долины и на восточной реке устранены, Томас выдает донесения, направляющие опытных путников в Западный Край — на помощь Гриану Камнегриву и измученному Народному ополчению.",al={"after guard thomas","where to go after eastvale","westfall report","после стражника томаса","куда идти после восточной долины","донесение в западный край"}}},fp="12,261,21.542.0,17.495.1,30.142.0,45.258.0,53.251.0,43.251.0,32.275.0,75.208.0"}
P.entries["npc:gubber-blump"] = {n="Груббер Блумп",kw={"auberdine","blump","darkshore","fishing","graun blump","gubber","reef crawler","shiny bauble","аубердин","блумп","темные берега","рыбная ловля","граун блумп","груббер","рифовый краб","блестящая безделушка"},ang={["profession:Cooking"]="Груббер увлечен прибрежной кухней, особенно свежим мясом рифовых крабов, и потому близок поварам, ищущим ингредиенты в водах Темных берегов.",["race:Dwarf"]="Видеть дворфа, счастливо живущего на туманном берегу Калимдора, а не в Каз Модане, необычно, но его прямолинейные шутки о родне доказывают, что он не утратил стальгорнских корней."},sec={{t="Рыбак из Аубердина",b="Большинство дворфов ищут уют под камнем или у ревущего горна, но Груббер Блумп предпочитает туманный берег Темных берегов. Он стоит на пляже Аубердина между распорядителем полетов и паромным причалом, обучает рыбной ловле и продает путникам простые рыболовные снасти. Он очень любит крабовое мясо, но часто просит искателей приключений помочь с уловом на опасном побережье, а также вернуть дорогие ему семейные рыболовные снасти."},{t="Семейные узы и услуги океану",b="Gubber is known to share candid stories about his family, notably his cousin Graun Blump, whom he insists possesses both a beard and an unusual odor. Travelers who lend a hand with his coastal errands—whether hauling in crawler legs or retrieving his family pole—often earn a thoughtful handwritten letter of thanks from Gubber, usually accompanied by a shiny fishing lure to encourage their future casts."}},faq={{q="Кто такой Груббер Блумп?",a="Gubber Blump is a dwarf fishing trainer and vendor located on the beach in Auberdine, situated right between the village docks and the hippogryph master.",al={"who is gubber blump","gubber blump npc","where is gubber blump","кто такой груббер блумп","груббер блумп нпс","где груббер блумп"}},{q="Чему учит и что продает Груббер Блумп?",a="Он обучает новичков рыбной ловле и продает начинающим рыболовам простые снасти, в том числе обычные удочки и блестящие безделушки.",al={"what does gubber sell","gubber blump trainer","darkshore fishing trainer","что продает груббер","груббер блумп учитель","учитель рыбной ловли темные берега"}},{q="Какие задания выдает Груббер Блумп?",a="Груббер просит путников вернуть потерянную семейную удочку и собрать отборное крабовое мясо на побережье в заданиях «Семья и рыболовная удочка» и «Дары моря».",al={"gubber blump quests","fruit of the sea","the family and the fishing pole","задания грубера блумпа","дары моря","семья и рыболовная удочка"}},{q="Кто такая Грауна Блумп?",a="Граун Блумп — двоюродная сестра Груббера. Груббер откровенно замечает, что у нее заметная борода и довольно необычный запах.",al={"graun blump","gubber blump cousin","граун блумп","кузина груббера блумпа"}}},fp="12,256,23.502.0,28.409.0,20.153.0,37.142.0,38.178.0,19.127.0"}
P.entries["npc:gunther-arcanus"] = {n="Гюнтер Чародей",s="Гюнтер Чародей — исключительно могущественный некромант, живущий на уединенном острове на Озере Ясноводном. Погибнув в Третью войну и восстав нежитью, он сам полностью разорвал мысленную власть Короля-лича. Долго считая себя единственной свободной нежитью, он защищал свое убежище от всех чужаков, пока его не нашли Отрекшиеся.",h="Гюнтер Чародей — исключительно могущественный некромант, живущий на уединенном острове на Озере Ясноводном.",kw={"arcanus","bethor","brightwater","dalaran","gunther","iceshard","kirin tor","lich","necromancer","thule","tirisfal","чародей","бетор","ясноводное","даларан","гюнтер","ледострел","кирин-тор","лич","некромант","тул","тирисфальские леса"},ang={["class:Mage"]="Гюнтер, обученный в Даларане, олицетворяет магов Кирин-Тора, тайно баловавшихся запретными некромантическими заклинаниями до вторжения Плети в Лордерон.",["class:Warlock"]="Уверенное владение темными искусствами и воскрешением у Гюнтера показывает, как далеко могла зайти запретная наука вне бдительного взора руководства Даларана.",["race:Undead"]="Самоосвобождение Гюнтера делает его исключением среди Отрекшихся и доказывает, что упорная тайная подготовка и железная воля порой способны разрушить мысленную власть Короля-лича."},sec={{t="Ученик Даларана",b="До падения Лордерона Гюнтер был многообещающим учеником в Кирин-Торе в Даларане. Вместе с близкими друзьями Бетором Ледострелом и Тулом Когтем Ворона он изучал магию тайных искусств, втайне углубляясь в некромантию вопреки строгим запретам Кирин-Тора на темную магию. В память о своем братстве трое однажды соединили свои ученические жезлы в одну семейную реликвию."},{t="Разрыв оков",b="Когда Плеть захлестнула север в Третью войну, Гюнтер погиб от Чумы нежизни и был поднят в услужение. В отличие от большинства, кому требовалось ослабление силы Короля-лича или вмешательство леди Сильваны, чтобы разорвать цепи, Гюнтер благодаря своему мастерству в тайной магии и несгибаемой воле сам стряхнул мысленное господство Короля-лича. Уверенный, что все прочие ходячие мертвецы остаются безвольными рабами Плети, он удалился на остров в Тирисфальских лесах, окружил себя бредущими стражами и прекратил всякие связи с живыми и мертвыми."},{t="Блудный лич",b="Ища могущественных союзников против Плети, Отрекшиеся отправили посланников за книгой заклинаний загадочного некроманта. Осмотрев тайный том в Подгороде, Бетор Ледострел узнал неповторимый почерк своего давно пропавшего товарища. Зачаровав возвращенный гримуар и потребовав уничтожить местных командиров Плети, Гюнтер наконец понял, что он не одинок в своей свободе. Убежденный, что группировка Сильваны — настоящее восстание против Плети, он заключил союз с бывшим однокашником, чтобы помогать Отрекшимся."}},faq={{q="Кто такой Гюнтер Чародей?",a="Это бывший маг Кирин-Тора из Даларана, погибший в Третью войну. Восстав нежитью, он сам освободился от власти Короля-лича и удалился на остров на Озере Ясноводном в Тирисфальских лесах.",al={"who is gunther","gunther lore","gunther arcanus story","кто такой гюнтер","гюнтер предания","история гюнтера чародея"}},{q="Почему Гюнтер выглядит как обычный Отрекшийся, а не как скелет-лич?",a="Обычные личи переносят дух в филактерию и принимают чудовищный парящий скелетообразный облик, а Гюнтер достиг подобного личу некромантического состояния, не покидая своего поднятого тела, и сохранил прежний смертный облик.",al={"why does gunther look human","gunther not a skeleton","why is gunther a lich","почему гюнтер похож на человека","гюнтер не скелет","почему гюнтер лич"}},{q="Почему Гюнтер жил один на острове?",a="Разорвав мысленный контроль Короля-лича, Гюнтер решил, что он единственная свободная нежить на свете. Считая остальных ходячих мертвецов безвольными рабами Плети, он уединился и приказал своим слугам убивать всякого, кто приблизится.",al={"why is gunther alone","gunther island isolation","why does gunther hide","почему гюнтер один","остров гюнтера","почему гюнтер прячется"}},{q="Откуда Гюнтер знает Бетора Ледострела?",a="Они были однокашниками и близкими друзьями в Даларане, учились у Кирин-Тора вместе с третьим магом по имени Тул Коготь Ворона. Трое друзей даже сплели свои ученические жезлы как символ своей связи.",al={"bethor and gunther","how does gunther know bethor","bethor iceshard history","бетор и гюнтер","откуда гюнтер знает бетора","история бетора ледострела"}},{q="Присоединяется ли Гюнтер к Отрекшимся?",a="Да. Когда искатели приключений возвращают его зачарованную книгу заклинаний и убивают местного агента Плети Лилит Нефару, доказывая независимость от Короля-лича, Гюнтер клянется в верности Беторе и делу Отрекшихся.",al={"does gunther join horde","gunther faction","is gunther forsaken","присоединится ли гюнтер к орде","фракция гюнтера","гюнтер отрекшийся"}},{q="Кто такая Лилит Нефара?",a="Лилит Нефара — агент Плети в Тирисфальских лесах. Гюнтер требует ее смерти как доказательства того, что искатель приключений действительно служит врагу Короля-лича, а не самой Плети.",al={"lillith nefara","nefara","gunther target","лиллит нефара","нефара","цель гюнтера"}}},fp="15,371,20.392.0,21.596.0,17.549.1,23.229.0,73.258.0,42.272.0,38.213.0,31.216.1,22.198.1"}
P.entries["npc:gurda-ragescar"] = {n="Гурда Печать Гнева",s="Гурда Печать Гнева была орком на небольшой заставе Орды к юго-западу от Заставы Расщепленного Дерева в Ясеневом лесу. Вместе с Фераном Сильным Ветром она пала, защищая лагерь от опасностей сумрачного леса.",h="Гурда Печать Гнева была орком на небольшой заставе Орды к юго-западу от Заставы Расщепленного Дерева в...",kw={"ashenvale","feran strongwind","gurda","orc","ragescar","splintertree","the lost pages","ясеневый лес","феран сильный ветер","гурда","орк","печать гнева","расщепленное дерево","утраченные страницы"},ang={["faction:Horde"]="Павший лагерь — мрачное напоминание о высокой цене, которую платит Орда, чтобы закрепиться в священных чащах Ясеневого леса."},sec={{t="Уничтоженная застава",b="К юго-западу от укрепленных стен Заставы Расщепленного Дерева Гурда Печать Гнева держала скромный лагерь Орды под густым пологом Ясеневого леса. На земле, за которую борются ночные эльфы-защитники и дикие звери, держать такие уединенные посты опасно. Гурда вместе с Фераном Сильным Ветром и отрядом стражей в итоге была разгромлена и убита на своем посту, и проходящим союзникам остались лишь следы их последнего боя."},{t="Павшие разведчики",b="Путники, бредущие рядом с тропой, могут наткнуться на печальное место гибели Гурды. Даже после смерти вещи и поручения ее лагеря рассказывают о делах Орды в лесах, включая пропавшие документы и приказы, сорванные засадой."}},faq={{q="Кто такая Гурда Печать Гнева?",a="Гурда Печать Гнева — орчиха-разведчица, выдающая задания, в небольшом лагере к юго-западу от Заставы Расщепленного Дерева в Ясеневом лесу. Она погибла насильственной смертью вместе со своими товарищами по лагерю.",al={"who is gurda","gurda ragescar lore","кто такая гурда","гурда печать гнева предания"}},{q="Где найти Гурду Печать Гнева?",a="Ее тело лежит в разгромленном лагере к юго-западу от Заставы Расщепленного Дерева, в стороне от дороги через центр Ясеневого леса.",al={"gurda location","where is gurda ragescar","где гурда","где гурда печать гнева"}},{q="Кто погиб вместе с ней?",a="Она погибла рядом с Фераном Сильным Ветром и их отрядом стражей при нападении на небольшой лагерь.",al={"who died with gurda","feran strongwind","кто погиб с гурдой","феран сильный ветер"}},{q="Какое задание связано с Гурдой Печать Гнева?",a="Гурда связана с заданием «Утраченные страницы», в котором нужно найти разбросанные документы в дебрях Ясеневого леса.",al={"gurda quests","the lost pages","задания гурды","утраченные страницы"}}},fp="14,208,15.473.0,17.266.0,22.179.0,34.115.0,29.108.0,35.117.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="Гвеннид Блай'Леггонд",s="Гвеннид Блай'Леггонд — ночная эльфийка, живущая в прибрежном порту Аубердин. Она живет на туманном берегу Темных берегов, следит за приливами и направляет путников исследовать странные останки, выбрасываемые на берег. Ее тревожат загадочные морские существа и огромные черепахи, туши которых стали загромождать северные пляжи.",h="Гвеннид Блай'Леггонд — ночная эльфийка, живущая в прибрежном порту Аубердин.",kw={"auberdine","beached sea creature","beached sea turtle","blyleggonde","darkshore","gwennyth","kaldorei","veiled sea","washed ashore","аубердин","выброшенное морское существо","выброшенная морская черепаха","блай'леггонд","темные берега","гвеннид","кальдораи","сокрытое море","останки на берегу"},ang={["class:Druid"]="Друиды, стремящиеся сохранить природную гармонию Калимдора, сочтут донесения Гвеннид о выброшенных морских обитателях тревожным признаком нарушений в прибрежной экосистеме.",["faction:Alliance"]="Аубердин — главный прибрежный порт Альянса на севере Калимдора; безопасность его вод и пляжей от скрытых угроз жизненно важна для всех союзных рас, проходящих здесь.",["race:NightElf"]="Для кальдораев неестественная гибель великих морских зверей у берегов Темных берегов — тревожный знак нарушенного равновесия на их исконных землях, и потому дозор Гвеннид на берегу особенно важен."},sec={{t="Хранительница зыбких песков",b="Гвеннид Блай'Леггонд живет в Аубердине, оживленной морской гавани Темных берегов. Пока многие в городе заняты лесом или плаваниями через Сокрытое Море, Гвеннид пристально следит за берегом. Приливы недавно стали мрачными: они выносят на прибой останки огромных морских обитателей. Чтобы понять, что происходит в водах у берега, она полагается на добровольцев, которые прочешут пески, соберут образцы костей и принесут ответы."},{t="Выброшенные гиганты",b="На пляжах к северу и югу от Аубердина появилось тревожно много выброшенных морских существ и древних морских черепах. Не желая оставлять их гибель незамеченной, Гвеннид просит путников осмотреть этих павших титанов. Изучая кости и выясняя, что выгнало этих зверей на берег или убило их, она надеется понять, какие скрытые опасности таятся у берегов северного Калимдора."}},faq={{q="Кто такая Гвеннид Блай'Леггонд?",a="Это ночная эльфийка из Аубердина в Темных берегах, изучающая недавние нарушения в природе вдоль побережья. Она просит путников осмотреть пляж и исследовать странные находки, выброшенные морем.",al={"who is gwennyth","gwennyth auberdine","gwennyth lore","кто такая гвеннид","гвеннид аубердин","гвеннид предания"}},{q="Где найти Гвеннид Блай'Леггонд?",a="Ее можно найти в прибрежном поселении Аубердин, у пляжа и причалов на окутанном туманом берегу Темных берегов.",al={"where is gwennyth","gwennyth location","find gwennyth","где гвеннид","местонахождение гвеннид","найти гвеннид"}},{q="Почему ее интересуют выброшенные существа?",a="Внезапная гибель и выбрасывание на берег огромных морских черепах и загадочных морских исполинов указывают на нарушение равновесия или невидимого хищника в водах у Темных берегов. Гвеннид хочет понять причину, исследуя останки, найденные на побережье.",al={"why beached turtles","why does she want bones","washed ashore quest","почему выбрасываются черепахи","зачем ей кости","останки на берегу задание"}},{q="Какие задания дает Гвеннид?",a="Она отправляет искателей приключений выполнять задание «Останки на берегу» и принимает различные находки, связанные с выброшенными морскими существами и морскими черепахами на побережье Темных берегов.",al={"gwennyth quests","what does she give","задания гвеннид","что она дает"}},{q="Входит ли она в Круг Кенария или в Часовых?",a="Нет. Она жрица Луны, служащая Сестрам Элуны в Аубердине, а не друид Круга Кенария и не командир Часовых, но разделяет глубокую заботу своего народа о здоровье и равновесии природы Темных берегов.",al={"gwennyth faction","is gwennyth a druid","фракция гвеннид","гвеннид друид"}},{q="Что означает ее имя?",a="Хотя необычная фамилия «Блай'Леггонд» вписывается в ритмичный стиль имен кальдораев, она является анаграммой «Leggy Blonde» — игривой шуткой создателей мира.",al={"bly leggonde meaning","gwennyth name easter egg","значение блай'леггонд","гвеннид пасхалка имени"}}},fp="21,348,29.489.0,19.409.0,29.212.0,39.134.0,43.248.0,32.196.0,52.234.0,24.167.0"}
P.entries["npc:hagar-lightninghoof"] = {n="Хагар Грозовое Копыто",s="Хагар Грозовое Копыто — таурен-разведчик, расположившийся высоко на Заставе Вольного Ветра в Тысяче Игл. Услышав слухи о странной кладке, спрятанной в глубине каньона, он расследует сообщения о чужеродном яйце, которое яростно охраняют местные ветряные змеи.",h="Хагар Грозовое Копыто — таурен-разведчик, расположившийся высоко на Заставе Вольного Ветра в Тысяче Игл.",kw={"alien egg","arikara","freewind post","hagar","lightninghoof","motega firemane","thousand needles","wind serpent","чужеродное яйцо","арикара","застава вольного ветра","хагар","грозовое копыто","мотега огненная грива","тысяча игл","ветряная змея"},ang={["faction:Horde"]="Хагар, расположившийся высоко над дном каньона на Заставе Вольного Ветра, полагается на умелых воинов Орды, способных проникнуть в опасные логова, недоступные обычным разведчикам.",["race:Tauren"]="Для тауренов помощь Хагару становится волнующим открытием: древние легенды об Арикаре, крылатом воплощении мщения, оказываются живой реальностью в каньонах внизу."},sec={{t="Странная кладка",b="Находясь среди высоких утесов Заставы Вольного Ветра, Хагар Грозовое Копыто услышал слухи о необычном яйце, лежащем глубоко в пещере внизу. Местные ветряные змеи охраняли гнездо с необычайной яростью и не подпускали любопытных разведчиков. Хагар ищет искателя приключений, достаточно смелого, чтобы проникнуть в логово змей: он хочет сам изучить находку и понять, какой зверь может вызывать такие защитные инстинкты у естественных хищников каньона."},{t="Воплощенный миф",b="Когда искатель приключений наконец добывает яйцо и приносит его на Заставу Вольного Ветра, оно вылупляется прямо перед Хагаром. Из него появляется молодая ветряная змея, похожая на легендарную Арикару — почитаемого духа, которого в преданиях тауренов считают воплощением мщения. Понимая огромное культурное и духовное значение возвращения этого существа, Хагар немедля отправляет путника к старейшине Мотеге Огненной Гриве."}},faq={{q="Кто такой Хагар Грозовое Копыто?",a="Хагар Грозовое Копыто — таурен, выдающий задания, живущий на Заставе Вольного Ветра в Тысяче Игл. Он изучает необычных животных в каньонах, в частности странное яйцо ветряной змеи, о котором сообщали из глубины соседней пещеры.",al={"who is hagar","hagar lightninghoof role","hagar lore","кто такой хагар","хагар грозовое копыто роль","хагар предания"}},{q="Где можно найти Хагара Грозового Копыта?",a="Он находится на вершине Заставы Вольного Ветра — главного оплота Орды, расположенного на огромных каменных иглах в центре Тысячи Игл.",al={"where is hagar","hagar lightninghoof location","freewind post hagar","где хагар","хагар грозовое копыто местонахождение","застава вольного ветра хагар"}},{q="Что за «чужеродное яйцо» ищет Хагар?",a="Чужеродное яйцо — необычное яйцо, которое ветряные змеи охраняют в подземном логове. Хагар просит искателей приключений принести его, чтобы изучить его природу.",al={"alien egg","what is the egg","wind serpent egg","чужеродное яйцо","что за яйцо","яйцо ветряной змеи"}},{q="К кому Хагар обращается по поводу яйца?",a="Хагар отправляет искателя приключений поговорить с Мотегой Огненной Гривой, старейшиной на Заставе Вольного Ветра, который лучше знает традиции тауренов.",al={"who do i turn serpent wild into","hagar follow up quest","where to go after hagar","к кому идти с яйцом","следующее задание хагара","куда идти после хагара"}}},fp="19,239,18.474.0,14.425.1,27.220.0,39.126.0,45.151.1,37.140.1"}
P.entries["npc:halaan-hawk-eye"] = {n="Халаан Соколиный Глаз",s="Халаан Соколиный Глаз — наблюдатель из Небожителей, стоящий на сторожевой башне Деревни Тендал на острове Зефрис. Не обладая ни магической чувствительностью, ни мистическим небесным зрением своих собратьев, он полагается на острое обычное зрение, чтобы следить за островом. Со своего поста он наблюдает за далекими якорными пилонами и предупреждает гостей о нестабильности их магии.",h="Халаан Соколиный Глаз — наблюдатель из Небожителей, стоящий на сторожевой башне Деревни Тендал на острове...",kw={"anchor pylon","halaan","hawk-eye","skyborne","skysight","thendal village","zephras isle","якорный пилон","халаан","соколиный глаз","небожители","небесное зрение","деревня тендал","остров зефрис"},ang={["race:Skyborne"]="Халаан представляет тех Небожителей, у которых нет природной склонности к управлению энергетическими линиями или небесному зрению, и потому служит общине неустанной бдительностью и воинским долгом."},sec={{t="Дозорный без магии",b="Высоко над Деревней Тендал Халаан Соколиный Глаз служит своему народу без даров, свойственных многим Небожителям. Он не может черпать магическую силу из энергетических линий под островом Зефрис и не способен заглядывать между мирами с помощью мистического небесного зрения. Вместо этого Халаан полагается на острые природные чувства. С башни он осматривает горизонт и следит за якорными пилонами острова, обращая внимание на их все более неустойчивую и неровную магическую энергию."}},faq={{q="Кто такой Халаан Соколиный Глаз?",a="Халаан Соколиный Глаз — страж из Небожителей, стоящий на сторожевой башне над Деревней Тендал на острове Зефрис. Он наблюдает за окрестностями и предупреждает искателей приключений о неровной магии, поражающей якорные пилоны острова.",al={"halaan hawkeye","who is halaan","thendal watchtower npc","халаан соколиный глаз","кто такой халаан","персонаж сторожевой башни тендал"}},{q="Чем Халаан отличается от других Небожителей?",a="В отличие от многих сородичей, Халаан не обладает ни мистическим небесным зрением, пронзающим завесу между мирами, ни врожденной способностью использовать подземные энергетические линии острова Зефрис. Вместо этого он полагается на острое зрение и природную наблюдательность.",al={"halaan abilities","can halaan use magic","halaan skysight","способности халаана","может ли халаан использовать магию","небесное зрение халаана"}},{q="Почему Халаан беспокоится о якорных пилонах?",a="Халаан следит за далекими якорными пилонами и заметил, что их магическая отдача стала неровной и неустойчивой, что создает неизвестную угрозу стабильности острова Зефрис.",al={"what is wrong with the pylons","anchors of zephras problem","что не так с пилонами","проблема якорей зефрис"}},{q="Где найти Халаана Соколиный Глаз?",a="Он стоит на деревянной сторожевой башне в Деревне Тендал на острове Зефрис и вглядывается в горизонт.",al={"where is halaan","halaan location","где халаан","местонахождение халаана"}}},fp="15,358,24.509.0,23.227.0,48.260.0,46.185.0,33.117.0"}
P.entries["npc:hamhock"] = {n="Хрупконог",s="Хрупконог — огромный двухголовый огр, заключенный в глубинах Тюрьмы Штормграда. Запертый под столицей вместе с закоренелыми мятежниками и головорезами из Братства Справедливости, он выделяется как особенно жестокий и неожиданный заключенный во время тюремного бунта.",h="Хрупконог — огромный двухголовый огр, заключенный в глубинах Тюрьмы Штормграда.",kw={"duskwood","hamhock","ogre","prison","splinter fist","stockade","stormwind","two-headed","сумеречный лес","хрупконог","огр","тюрьма","раскольничий кулак","штормград","двухголовый"},ang={["class:Warrior"]="Чтобы одолеть Хрупконога, нужно встретить грубую, громадную силу лицом к лицу в тесных тюремных коридорах.",["faction:Alliance"]="Свободно разгуливающий двухголовый огр прямо под улицами столицы показывает, насколько катастрофически городская стража потеряла контроль над Тюрьмой."},sec={{t="Громила за решеткой",b="Тюрьма Штормграда была построена для мелких воров, убийц и политических диссидентов, поэтому огромный двухголовый огр выглядел среди камер внушительно. Когда заключенные подняли восстание и захватили здание, Хрупконог остался в самом центре хаоса и крушил всякого глупца, вторгшегося в его блок."},{t="Темное происхождение",b="Власти Штормграда хранят мало открытых записей о том, как был пойман Хрупконог. Среди стражи и горожан ходят слухи, что его притащили на север из клана Раскольничьего Кулака в Лощине Вул'Гол в Сумеречном лесу. Другие подозревают, что Братство Справедливости наняло его как наемную силу, прежде чем он попал в руки городской стражи."}},faq={{q="Кто такой Хрупконог?",a="Хрупконог — элитный двухголовый огр, содержащийся в Тюрьме Штормграда. Во время восстания, поднятого заключенными из Братства Справедливости, он становится опасным препятствием в глубине тюремных коридоров.",al={"hamhock","who is the ogre in stockade","ogre boss stockade","хрупконог","кто огр в тюрьме","огр босс тюрьма"}},{q="Как огр оказался в Тюрьме Штормграда?",a="Официальные записи не описывают его поимку, но широко считается, что он либо плененный громила из клана Раскольничьего Кулака, обитающего в Сумеречном лесу, либо наемный головорез Братства Справедливости, пойманный во время незаконных дел.",al={"why is hamhock in jail","how did hamhock get captured","why is there an ogre in stockades","почему хрупконог в тюрьме","как поймали хрупконога","почему в тюрьме огр"}},{q="Союзен ли Хрупконог с бунтовщиками из Братства Справедливости?",a="Хотя вся тюрьма охвачена бунтом под началом главарей Братства Справедливости, неясно, действует ли Хрупконог заодно с ними или просто упивается безудержным хаосом разрушенных камер.",al={"is hamhock defias","hamhock defias brotherhood","does hamhock work for bazil","хрупконог братство справедливости","хрупконог в братстве","работает ли хрупконог на базила"}},{q="Связан ли Хрупконог с ограми Сумеречного леса?",a="Многие считают, что он родом из Лощины Вул'Гол в Сумеречном лесу, а значит, до пленения и доставки в Штормград он входил в клан Раскольничьего Кулака под началом Ззарк'Вула.",al={"is hamhock splinter fist","hamhock vulgol","vul'gol ogres stockade","хрупконог раскольничий кулак","хрупконог вул'гол","огры вул'гол тюрьма"}},{q="Связан ли Хрупконог с каким-либо особым заказом или заданием?",a="За голову Хрупконога не назначено ни официальных наград, ни городских ордеров. Он — случайная угроза, с которой сталкиваются искатели приключений, зачищая охваченную бунтом крепость.",al={"hamhock quest","is there a quest for hamhock","hamhock bounty","задание хрупконог","есть ли задание на хрупконога","награда за хрупконога"}},{q="Чем важны двухголовые огры?",a="У двухголовых огров на каждую голову приходится своя личность, и они часто хитрее или искуснее в магии, чем их одноголовые сородичи, что делает Хрупконога особенно опасным для обычных тюремных стражей.",al={"two headed ogre lore","why two heads","предания о двухголовых ограх","почему две головы"}}},fp="7,255,19.324.0,13.366.0,15.192.0,49.243.0,42.197.0,44.185.0,48.179.0,37.209.0"}
P.entries["npc:hana-zua"] = {n="Хана'зуа",s="Хана'зуа — тролль-разведчик из племени Черного Копья в Долине Испытаний, ставший жертвой ядовитых тварей, бродящих по гребням каньона. Раненный чудовищным скорпидом Саркотом, он лежит в ожидании помощи от молодых новобранцев Орды, стремящихся доказать свою доблесть.",h="Хана'зуа — тролль-разведчик из племени Черного Копья в Долине Испытаний, ставший жертвой ядовитых тварей...",kw={"darkspear","durotar","hana'zua","hanazua","sarkoth","scorpid","valley of trials","черное копье","дуротар","хана'зуа","саркот","скорпид","долина испытаний"},ang={["faction:Horde"]="Выживание Хана'зуа и месть за него — одно из первых испытаний верности и боевой готовности для будущих героев Орды.",["race:Troll"]="Для новобранцев из племени Черного Копья, только начинающих путь в Дуротаре, встреча с раненым сородичем показывает смертельную опасность местных зверей и необходимость защищать новообретенных союзников."},sec={{t="Разведчик, сраженный ядом",b="Пробираясь по сухим высотам над Долиной Испытаний, Хана'зуа столкнулся с Саркотом — необычайно свирепым и ядовитым скорпидом, бродящим по скалам. Тролль был одолен и ужален и едва пережил схватку. Не в силах двигаться или вернуться в лагерь самостоятельно, он лежит в пыли, надеясь, что проходящие новобранцы прикончат тварь и передадут весть о его беде в Логово."}},faq={{q="Кто такой Хана'зуа?",a="Хана'зуа — тролль из племени Черного Копья, раненым найденный в Долине Испытаний в Дуротаре. На него напали из засады и отравили, когда он выслеживал зверей на гребнях.",al={"hanazua","who is hanazua","injured troll valley of trials","хана'зуа","кто такой хана'зуа","раненый тролль долина испытаний"}},{q="Что случилось с Хана'зуа?",a="Его сразил Саркот — крупный и смертоносный скорпид, затаившийся на утесах над тренировочной площадкой. Сильный яд лишил его сил, и он не смог вернуться в безопасное место.",al={"why is hanazua hurt","who poisoned hanazua","hanazua injury","почему хана'зуа ранен","кто отравил хана'зуа","рана хана'зуа"}},{q="О чем он просит путников?",a="Хана'зуа просит способных искателей приключений отомстить за его ранение, убив Саркота, собрать коготь зверя в доказательство и передать весть о его состоянии наставникам в Логове.",al={"hanazua quest","what does hanazua want","задание хана'зуа","чего хочет хана'зуа"}}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="Ручник Ржавозубчик",s="Ручник Ржавозубчик — трудолюбивый гном, стоящий у входа в Туннель Холодной долины в Дун Мороге. Он организует поставки между уединенной тренировочной площадкой Холодной долины и городом Каранос, но недавние набеги троггов сильно мешают его работе.",h="Ручник Ржавозубчик — трудолюбивый гном, стоящий у входа в Туннель Холодной долины в Дун Мороге.",kw={"coldridge pass","coldridge valley","dun morogh","hands springsprocket","kharanos","springsprocket","supplies to tannok","туннель холодной долины","холодная долина","дун морог","ручник ржавозубчик","каранос","ржавозубчик","припасы для таннока"},ang={["faction:Alliance"]="Ручник поддерживает работу важных внутренних линий снабжения между дворфийскими новобранцами в Холодной долине и поселениями в глубине Дун Морога.",["race:Gnome"]="Для гномов-беженцев, покинувших Гномреган, Ручник олицетворяет тихую решимость гномов, вливающихся в местную торговлю и логистику Дун Морога наряду с их дворфийскими союзниками."},sec={{t="Затор в туннеле",b="Ручник Ржавозубчик, расположившийся у входа в Туннель Холодной долины, обнаружил, что его обычные рейсы с припасами полностью нарушены. Он регулярно доставляет провизию на Громоварское пивоварню и в трактир Караноса, но враждебные трогги из племени Каменной Челюсти заполонили подземный туннель, ведущий из долины. Торговля и движение остановлены, поэтому Ручнику приходится рассчитывать на способных путников, которые пронесут нужные ящики через опасный горный проход."}},faq={{q="Кто такой Ручник Ржавозубчик?",a="Это лояльный Альянсу гном, стоящий в Холодной долине у входа в Туннель Холодной долины и отвечающий за доставку припасов в нижние области Дун Морога.",al={"who is hands springsprocket","hands springsprocket lore","who is this gnome","кто такой ручник ржавозубчик","ручник ржавозубчик предания","кто этот гном"}},{q="Почему ему нужна помощь с доставкой припасов?",a="Проход, соединяющий Холодную долину с остальным Дун Морогом, заполонили свирепые трогги из племени Каменной Челюсти, и обычная перевозка слишком опасна без вооруженного сопровождения или способных искателей приключений.",al={"why does hands need help","coldridge pass supplies","why are supplies stuck","зачем ручнику помощь","туннель холодной долины припасы","почему застряли припасы"}},{q="Куда предназначены его припасы?",a="Он организует регулярные поставки в Каранос, в том числе товары для Таннока Молота Стужи и местных трактирщиков, которым нужна постоянная провизия со всех заснеженных вершин.",al={"where do supplies go","hands supply route","who gets the crate","куда идут припасы","маршрут ручника","кто получает ящик"}}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:hansel-heavyhands"] = {n="Хансел Большерук",s="Хансел Большерук — необычайно крупный дворф из клана Черного Железа, служащий в Братстве Тория в Лагере Братства Тория в Тлеющем ущелье. Надзиратели лагеря поручают ему опасную работу в полевых условиях, но он неизменно перекладывает рискованные дела на проходящих мимо искателей приключений, ссылаясь на разнообразные мелкие телесные недуги. Его громадная фигура выделяется среди сородичей, хотя рвение к полевой работе не соответствует его размерам.",h="Хансел Большерук — необычайно крупный дворф из клана Черного Железа, служащий в Братстве Тория в Лагере...",kw={"cauldron","dark iron","hansel heavyhands","incendosaur","lava spider","searing gorge","thorium brotherhood","thorium point","котлован","черное железо","хансел большерук","пламезавр","лавовый паук","тлеющее ущелье","братство тория","лагерь братства тория"},ang={["faction:Alliance"]="Хотя Альянс обычно воюет с приверженцами Черного Железа, Братство Тория принимает любого с крепкой рукой, и Хансел становится удобным источником местной работы за награду.",["faction:Horde"]="Путникам из Орды громадное сложение Хансела напомнит орка или таурена, хотя его нежелание вступать в честный бой наверняка заставит поднять бровь.",["race:Dwarf"]="Дворфы Бронзобороды и Громового Молота могут дивиться — или усмехаться — колоссальному сложению Хансела, гадая, как дворф из клана Черного Железа вымахал до таких размеров, проводя дни в уклонении от настоящего труда."},sec={{t="Великан среди дворфов",b="Даже по меркам широкоплечего клана Черного Железа Хансел Большерук — редкое исключение. Он возвышается над сородичами, а его массивное сложение по ширине и росту почти не уступает оркам, и одно его присутствие наводит на мысль о воине, созданном для бойни на передовой. Но, несмотря на грозный вид и внушительное прозвище, Хансел совершенно не желает лишний раз напрягаться и предпочитает относительную безопасность лагеря Братства Тория высоко над вулканическим пеплом."},{t="Мастер отговорок",b="Надсмотрщик Скрэндж и мастер-кузнец Горелик часто поручают Ханселу мрачную обязанность — истреблять огненных тварей в шлаковых ямах внизу. Когда ему велят расчистить Котлован от хищных пламезавров, Хансел отказывается, жалуясь на больные ноги. Когда ему приказывают истребить больших лавовых пауков, заполонивших выжженные пустоши, он заявляет, что на проклятом вулканическом кряже «морозный климат» и он из-за него жестоко простудился. Поэтому любой наемник, готовый встретиться с потоками магмы, всегда застает Хансела с готовым предложением работы."}},faq={{q="Кто такой Хансел Большерук?",a="Хансел Большерук — дворф из клана Черного Железа, связанный с Братством Тория. Он служит в Лагере Братства Тория в Тлеющем ущелье и известен своими поразительными размерами и удивительной способностью уклоняться от опасной полевой работы.",al={"who is hansel","hansel heavyhands lore","hansel dwarf","кто такой хансел","хансел большерук предания","хансел дворф"}},{q="Почему Хансел намного крупнее других дворфов?",a="Ясного объяснения его размерам не дается. Хансел — просто необычайно огромный дворф из клана Черного Железа с широкими плечами, толстыми конечностями и общим сложением, близким к орочьему.",al={"why is hansel so big","huge dwarf searing gorge","orc sized dwarf","почему хансел такой большой","огромный дворф тлеющее ущелье","дворф размером с орка"}},{q="Какие задания Хансел дает искателям приключений?",a="Хансел нанимает проходящих путников для выполнения поручений, которые спускает ему начальство. В частности, он платит наемникам за истребление больших лавовых пауков по всему Тлеющему ущелью и охоту на пламезавров в глубине Котлована.",al={"hansel heavyhands quests","what quests does hansel give","задания хансела большерука","какие задания дает хансел"}},{q="Почему Хансел не выполняет свою работу сам?",a="Стоит опасности появиться, и у Хансела находятся отговорки. Он ссылается на больные ноги, из-за которых не может идти в Котлован сражаться с пламезаврами, а когда ему велят охотиться на лавовых пауков, жалуется, что в пышущем жаром Тлеющем ущелье так холодно, что можно простудиться.",al={"why doesnt hansel fight","hansel excuses","почему хансел не сражается","отговорки хансела"}},{q="Верен ли Хансел императору дворфов Черного Железа?",a="Хансел состоит в Братстве Тория — отколовшейся фракции дворфов Черного Железа, порвавшей с императором Даграном Тауриссаном и Рагнаросом. К путникам из Альянса и Орды, посещающим Лагерь Братства Тория, он относится нейтрально.",al={"is hansel loyal to shadowforge","is hansel an enemy","верен ли хансел тенегорну","хансел враг"}},{q="Где можно найти Хансела Большерука?",a="Он находится в Лагере Братства Тория — скалистом форпосте на северном хребте над Тлеющим ущельем.",al={"hansel location","where is hansel","где хансел","местонахождение хансела"}}},fp="17,420,21.485.0,17.557.0,25.235.0,48.192.0,43.232.0,37.254.0,41.227.0,37.110.0"}
P.entries["npc:harb-clawhoof"] = {n="Харб Острое Копыто",s="Харб Острое Копыто — таурен, заводчик ездовых животных, живущий неподалеку от Деревни Кровавого Копыта в Мулгоре. Он ухаживает за выносливыми кодо племени и предоставляет их достойным наездникам-тауренам и доверенным защитникам Громового Утеса.",h="Харб Острое Копыто — таурен, заводчик ездовых животных, живущий неподалеку от Деревни Кровавого Копыта в...",kw={"bloodhoof village","harb clawhoof","kodo trainer","kodo vendor","mount vendor","mulgore kodo","thunder bluff mounts","деревня кровавого копыта","харб острое копыто","дрессировщик кодо","торговец кодо","торговец скакунами","кодо мулгор","скакуны громового утеса"},ang={["faction:Horde"]="Для орков, троллей и Отрекшихся кодо от Харба — высшая награда и знак дружбы, признанный старейшинами Громового Утеса.",["race:Tauren"]="Харб Острое Копыто предоставляет вам типичного скакуна вашего народа — и практичный способ передвижения по Мулгору, и символ ваших кочевых традиций."},sec={{t="Заводчик великих кодо",b="Харб Острое Копыто проводит дни возле загонов Деревни Кровавого Копыта, ухаживая за огромными кодо, на которых держатся перевозки и труд тауренов. Эти выносливые животные, способные нести огромный груз на большие расстояния, необходимы для жизни на равнинах. Харб следит, чтобы каждый зверь был ухожен и приучен к дисциплине и доставался только тем наездникам, которые пользуются уважением народа тауренов."},{t="Скакуны равнин",b="While tauren naturally earn the trust required to ride Harb's kodos, outsiders face stricter scrutiny. Due to their immense size and temperament, kodos are not easily guided by those unfamiliar with their nature. Non-tauren allies who wish to ride away atop one of Harb's prized mounts must first prove their loyalty and earn exalted status with Thunder Bluff."}},faq={{q="Где найти Харба Острого Копыта?",a="Харб Острое Копыто находится у загона для кодо на окраине Деревни Кровавого Копыта в центральном Мулгоре, к югу от Громового Утеса.",al={"harb clawhoof location","where is harb clawhoof","kodo vendor location","местонахождение харба острого копыта","где харб острое копыто","торговец кодо"}},{q="Что продает Харб Острое Копыто?",a="Харб продает разных кодо-скакунов, в том числе обычных коричневых и серых кодо, а также тяжелобронированных великих кодо для опытных наездников.",al={"what does harb sell","harb mounts","kodo vendor wares","что продает харб","скакуны харба","товары торговца кодо"}},{q="Могут ли не-таурены купить кодо у Харба?",a="Yes, but only if they have earned exalted standing with Thunder Bluff. Tauren can purchase them directly, but other Horde races must prove themselves to the tribe before Harb will entrust them with a kodo.",al={"can orcs buy kodos","can trolls ride kodos","kodo reputation requirement","могут ли орки купить кодо","могут ли тролли ездить на кодо","репутация для кодо"}},{q="Почему кодо так важны для тауренов?",a="Кодо — сильные, выносливые существа, идеально подходящие для кочевого образа жизни и открытых равнин центрального Калимдора. Они служат надежными вьючными животными, боевыми скакунами и тягловой силой для торговых перевозок по суровым землям.",al={"tauren kodo lore","why kodos","предания о кодо тауренов","почему кодо"}}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="Харкен Тотем Ветра",s="Харкен Тотем Ветра — таурен-охотник, живущий в Деревне Кровавого Копыта в Мулгоре. Верный традициям своего народа, он поручает молодым охотникам и путникам доказать свои навыки выслеживания и собирательства на золотистых равнинах.",h="Харкен Тотем Ветра — таурен-охотник, живущий в Деревне Кровавого Копыта в Мулгоре.",kw={"bloodhoof village","harken windtotem","mulgore","swoop hunting","tauren","windtotem","деревня кровавого копыта","харкен тотем ветра","мулгор","охота на перепелятников","таурены","тотем ветра"},ang={["class:Hunter"]="Для следопытов, проходящих через Деревню Кровавого Копыта, задание Харкена — сбить летающих перепелятников — служит важной ранней проверкой меткости и умения добывать трофеи.",["race:Tauren"]="Харкен Тотем Ветра воплощает исконную философию охоты тауренов: доказывать дисциплину и самостоятельность на равнинах, почитая зверей Матери-Земли."},sec={{t="Охотник Кровавого Копыта",b="Харкен Тотем Ветра живет в самом сердце Деревни Кровавого Копыта и служит наставником и проводником для тех, кто учится охотничьим обычаям тауренов. Жизнь на равнинах Мулгора требует уважения к природе и практического умения кормить свое племя. Харкен испытывает молодых искателей приключений, отправляя их охотиться на местных перепелятников, кружащих над плато, и собирать их перья, чтобы оценить терпение, меткость и умение добывать без расточительства."}},faq={{q="Кто такой Харкен Тотем Ветра?",a="Харкен — таурен-охотник, живущий в Деревне Кровавого Копыта в центральном Мулгоре. Он наставляет путников и начинающих искателей приключений, обучая их основам выслеживания и охотничьим традициям тауренов.",al={"harken windtotem lore","who is harken","харкен тотем ветра предания","кто такой харкен"}},{q="Где можно найти Харкена Тотема Ветра?",a="Харкен живет в Деревне Кровавого Копыта — поселении к югу от Громового Утеса в центральном Мулгоре.",al={"harken location","where is harken windtotem","где харкен","местонахождение харкена","где харкен тотем ветра"}},{q="Какие задания Харкен дает искателям приключений?",a="Он предлагает задание «Охота на перепелятников», в котором просит охотников отправиться на луга Мулгора, сразить диких перепелятников и собрать их прочные маховые перья.",al={"harken windtotem quests","swoop hunting quest","задания харкена тотема ветра","задание охота на перепелятников"}},{q="Приходится ли Харкен родственником Бовану Тотему Ветра?",a="У них одно имя клана — Тотем Ветра, что намекает на племенное или семейное родство, хотя Харкен занят лишь местной охотой возле деревни в Мулгоре.",al={"is harken related to bovan","bovan windtotem relation","родственник ли харкен бовану","родство с бованом тотемом ветра"}}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:harlan-bagley"] = {n="Харлан Багли",s="Харлан Багли — человек, оружейник и торговец, работающий в оружейной лавке «Львиное Сердце» в оживленном Торговом квартале Штормграда. Он занимается лавкой на северной стороне центра квартала и снабжает оружием и снаряжением как горожан, так и приезжих искателей приключений.",h="Харлан Багли — человек, оружейник и торговец, работающий в оружейной лавке «Львиное Сердце» в оживленном...",kw={"armorer","harlan bagley","lionheart armory","merchant","stormwind","trade district","оружейник","харлан багли","львиное сердце","торговец","штормград","торговый квартал"},ang={["faction:Alliance"]="Торговцы вроде Харлана Багли снабжают снаряжением и товарами главную столицу Альянса, пока обычные линии снабжения находятся под угрозой на окрестных землях."},sec={{t="Оружейная «Львиное Сердце»",b="Оружейная «Львиное Сердце» на северной стороне Торгового квартала — постоянная торговая точка в самом сердце Штормграда. За прилавком Харлан Багли ведет учет товара и торгует защитным снаряжением, полагаясь на поступающие товары и местных курьеров, чтобы полки не пустели, пока столица справляется с далекими пограничными конфликтами и нехваткой припасов."}},faq={{q="Кто такой Харлан Багли?",a="Харлан Багли — человек, лавочник и торговец, владелец оружейной «Львиное Сердце» — магазина снаряжения в Торговом квартале Штормграда.",al={"who is harlan","harlan bagley lore","lionheart armory vendor","кто такой харлан","харлан багли предания","торговец оружейной львиное сердце"}},{q="Где можно найти Харлана Багли?",a="Он находится в оружейной «Львиное Сердце» на северной стороне центральной площади Торгового квартала Штормграда.",al={"harlan bagley location","where is harlan","lionheart armory location","местонахождение харлана багли","где харлан","где оружейная львиное сердце"}},{q="Какую роль он играет в торговле Штормграда?",a="Как местный торговец в столице королевства, Багли поставляет доспехи и снаряжение, а порой нанимает искателей приключений для доставки заказов и охраны поставок, без которых его оружейная не смогла бы работать.",al={"what does harlan sell","harlan bagley business","что продает харлан","торговля харлана багли"}}},fp="13,269,20.388.0,21.147.0,31.120.0,47.199.0"}
P.entries["npc:harlo-barnaby"] = {n="Харло Барнаби",s="Харло Барнаби — раненый дворф-беженец, живущий в Гавани Менетилов. Едва спасшись от резни, когда клан Черного Железа захватил Дун Модр, он теперь предупреждает путников о трагедии, разыгравшейся в северных болотах.",h="Харло Барнаби — раненый дворф-беженец, живущий в Гавани Менетилов.",kw={"dark iron","dun modr","harlo barnaby","menethil harbor","thandol span","wetlands","черное железо","дун модр","харло барнаби","гавань менетилов","мост тандола","болотина"},ang={["faction:Alliance"]="Падение Дун Модра угрожает важному сухопутному мосту между болотами и землями Арати, поэтому предупреждения Харло крайне важны для сил Альянса.",["race:Dwarf"]="Харло — живое напоминание о непрекращающейся кровавой войне кланов против вероломных дворфов Черного Железа, стремящихся отрезать Каз Модан от севера."},sec={{t="Бегство из Дун Модра",b="Харло Барнаби жил в Дун Модре, пока северная крепость не пала под внезапным и жестоким натиском дворфов Черного Железа. В хаосе засады Харло бежал на юг, к безопасности, но получил в спину шальной топор. Потеряв сознание от удара, он каким-то образом пережил путь через болота и очнулся перевязанным в Гавани Менетилов. Хотя он жив, раны и воспоминания о бойне не позволяют ему вернуться, и он призывает искателей приключений Альянса осмотреть дымящиеся руины его прежнего дома."}},faq={{q="Кто такой Харло Барнаби?",a="Харло Барнаби — дворф из Стальгорна, живущий в Гавани Менетилов, переживший жестокое нападение дворфов Черного Железа на форпост Дун Модр.",al={"harlo barnaby","who is harlo","menethil harbor dwarf","харло барнаби","кто такой харло","дворф гавань менетилов"}},{q="Как Харло Барнаби оказался в Гавани Менетилов?",a="Убегая от вторжения в Дун Модр, он получил в спину брошенный топор. Во время отступления он потерял сознание и очнулся в безопасности в Гавани Менетилов, под присмотром местных целителей.",al={"how did harlo get here","harlo barnaby back injury","как харло здесь оказался","травма спины харло барнаби"}},{q="Что случилось с Дун Модром?",a="Дун Модр был захвачен и разорен враждебными дворфами Черного Железа, наступавшими на юг от Моста Тандола. Они уничтожили местных дворфов-защитников и прогнали выживших в болота.",al={"dun modr fall","what happened at dun modr","падение дун модра","что случилось в дун модре"}}},fp="13,226,20.526.0,21.131.0,48.192.0,26.181.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="Хегнар Громострел",s="Хегнар Громострел — дворф-оружейник, живущий у заснеженной дороги от Туннеля Холодной долины к Караносу. Он держит оживленный стрельбищный полигон и снабжает местных охотников и горцев огнестрельным оружием и боеприпасами.",h="Хегнар Громострел — дворф-оружейник, живущий у заснеженной дороги от Туннеля Холодной долины к Караносу.",kw={"ammo","coldridge pass","dun morogh","gunsmith","hegnar rumbleshot","kharanos","shooting range","боеприпасы","туннель холодной долины","дун морог","оружейник","хегнар громострел","каранос","тир"},ang={["class:Hunter"]="Стрелкам, выходящим из Холодной долины к заснеженным вершинам Дун Морога, Хегнар предлагает необходимые патроны, подсумки для боеприпасов и запасное огнестрельное оружие.",["race:Dwarf"]="Дворфы гордятся мастерством и меткостью, поэтому придорожный тир Хегнара — естественное место сбора для путников, желающих проверить свою меткость."},sec={{t="Оружейник у дороги",b="Хегнар Громострел устроил небольшой лагерь между Туннелем Холодной долины и Караносом и обслуживает дворфов-стрелков, путников и местное ополчение. В его лагере есть популярный тир, где горцы оттачивают меткость на диких зверях, бродящих по Дун Морогу. Из-за множества желающих пострелять боеприпасы расходуются быстро, и Хегнар постоянно зависит от новых поставок от своего поставщика, дворфа-инженера Лослора Руджа."}},faq={{q="Кто такой Хегнар Громострел?",a="Хегнар Громострел — дворф-оружейник, который держит под открытым небом тир и лагерь на главной тропе между Туннелем Холодной долины и Караносом.",al={"who is hegnar","hegnar rumbleshot npc","gunsmith in dun morogh","кто такой хегнар","хегнар громострел","оружейник в дун мороге"}},{q="Откуда Хегнар берет боеприпасы?",a="Хегнар полагается на Лослора Руджа, дворфа-инженера и поставщика из другой части Дун Морога, который изготавливает и поставляет боеприпасы, необходимые для работы тира.",al={"hegnar supplier","who supplies rumbleshot","ammo for rumbleshot quest","поставщик хегнара","кто снабжает громострела","патроны для задания громострела"}},{q="Что Хегнар делает для местных дворфов?",a="Он снаряжает местных охотников и ополченцев огнестрельным оружием и боеприпасами, а также предоставляет тир для стрелков, проходящих через Дун Морог.",al={"why is hegnar here","hegnar shooting range","rumbleshot role","зачем хегнар здесь","тир хегнара","роль громострела"}}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="Хенз Фолк",s="Хенз Фолк — дворф-искатель приключений, которого находят при смерти на каменном круге возле Часовых Вечности в Элвиннском лесу. Он был сражен Братством Справедливости, защищая своего спутника, и служит важным испытанием для будущих паладинов, которые учатся владеть даром воскрешения.",h="Хенз Фолк — дворф-искатель приключений, которого находят при смерти на каменном круге возле Часовых Вечности...",kw={"defias","elwynn forest","gazin tenorm","henze faulk","heroes' vigil","resurrection","symbol of life","tome of divinity","братство справедливости","элвиннский лес","газин тенорм","хенз фолк","часовые вечности","воскрешение","знак жизни","фолиант божественности"},ang={["class:Paladin"]="Хенз Фолк — ваше первое настоящее испытание божественного милосердия. Возвращая его с грани смерти при помощи Знака жизни, паладин узнает, что Свет — не просто оружие для битвы, а священная сила, способная бросить вызов смерти.",["race:Dwarf"]="Видеть собрата-дворфа поверженным в землях людей — суровое напоминание о том, что разбойники Братства Справедливости смертельно опасны для путников всех рас, а не только для местных жителей Штормграда."},sec={{t="Жертва у Часовых Вечности",b="Недалеко от древнего каменного кольца к востоку от Штормграда находятся Часовые Вечности — место, которое часто посещают разбойники из Братства Справедливости, рыщущие по Элвиннскому лесу. Именно здесь Хенза Фолка и его друга Газина Тенорма застали врасплох бандиты Братства Справедливости. Хенз подставился под удар, чтобы спасти Газина, и пал от клинков разбойников. Его спутник выжил и призвал помощь из Собора Света, а тело Хенза осталось на грани между жизнью и смертью в ожидании божественного вмешательства паладина со Знаком жизни."}},faq={{q="Кто такой Хенз Фолк?",a="Хенз Фолк — дворф из Стальгорна, которого находят смертельно раненным на каменном круге возле Часовых Вечности в Элвиннском лесу. Его застигли врасплох и сразили бандиты Братства Справедливости, когда он спасал своего друга Газина Тенорма.",al={"henze faulk","dwarf at heroes vigil","dying dwarf elwynn","хенз фолк","дворф у часовых вечности","умирающий дворф элвиннский лес"}},{q="Почему Хенз Фолк лежит на земле?",a="Хенза застало врасплох Братство Справедливости, когда он путешествовал с Газином Тенормом. Он принял на себя главный удар, чтобы Газин мог бежать, и остался смертельно раненным в ожидании воскрешения от неофита Света.",al={"why is henze dying","is henze dead","henze faulk dead","почему хенз умирает","мертв ли хенз","хенз фолк мертв"}},{q="Какая связь между Хензом и паладинами?",a="Хенз — центральная фигура обряда посвящения молодых паладинов, проходящих испытания Фолианта Божественности. Неофитам паладинов вверяют Знак жизни и отправляют в Элвиннский лес, чтобы они вернули Хенза из мертвых и доказали свое мастерство в самом священном благословении Света — искуплении.",al={"henze paladin quest","tome of divinity dwarf","хенз задание паладина","фолиант божественности дворф"}},{q="Кто такой Газин Тенорм?",a="Газин Тенорм — спутник Хенза Фолка. Когда их обоих загнали в угол бандиты Братства Справедливости, Хенз защитил Газина, и тот смог выжить и обратиться за помощью в Церковь Священного Света.",al={"who is gazin","gazin tenorm friend","кто такой газин","друг газина тенорма"}}},fp="11,281,28.507.0,19.206.0,39.223.0,39.292.0,20.184.0"}
P.entries["npc:heralath-fallowbrook"] = {n="Гералат Бурый Ручей",s="Гералат Бурый Ручей — умирающий ночной эльф-друид, заточенный в глубинах Лабиринтов Иглошкурых. Его послали выяснить причину колючей порчи вокруг останков Древнего Агамаггана, но он был схвачен и жестоко избит иглошкурыми. Последними словами он хочет передать весть о своей судьбе и дорогой его сердцу кулон жене в Дарнассе.",h="Гералат Бурый Ручей — умирающий ночной эльф-друид, заточенный в глубинах Лабиринтов Иглошкурых.",kw={"agamaggan","fallowbrook","henrig lonebrow","heralath","mortality wanes","quilboar","razorfen kraul","treshala","агамагган","бурый ручей","хенриг лонбро","гералат","угасание жизни","свинобраз","лабиринты иглошкурых","трешала"},ang={["class:Druid"]="Видеть собрата-друида, сломленного дикими колючими зарослями Лабиринтов Иглошкурых, — суровое напоминание о дикой, неумолимой порче, беспрепятственно расползающейся по южным Степям.",["race:NightElf"]="Отнести кулон Гералата в Дарнасс — значит почтить павшего брата, отдавшего жизнь в попытке понять и исцелить раненые земли Калимдора."},sec={{t="Трагическая миссия",b="Гералат Бурый Ручей был послан своим народом изучить древнего кабаньего бога Агамаггана и разрастающиеся колючие заросли, душащие южные Степи. Он искал корень порчи Лабиринтов Иглошкурых, но вместо ответов попал в плен к свинобразам. Запертый в грязном загоне и безжалостно избиваемый, Гералат слег от тяжелых ран и лихорадки. Перед тем как окончательно угаснуть, он рассказал все, что знал, другому пленнику, дворфу Хенригу Лонбро, и просил предупредить дозорный форпост в Таланааре об агрессии, разожженной старой свинобразихой Чарлгой Остробок."},{t="Последняя просьба",b="Лонбро удалось бежать, но Гералат был слишком слаб. Лежа на пороге смерти в запутанных загонах Лабиринтов, друид удерживает сознание лишь для того, чтобы обратиться к проходящим мимо искателям приключений. Он просит не о спасении, а о том, чтобы кулон его жены Трешалы забрали у его пленителей и отнесли в Дарнасс, чтобы она узнала о его судьбе и о том, что он хранил память о ней до конца."}},faq={{q="Кто такой Гералат Бурый Ручей?",a="Гералат Бурый Ручей — ночной эльф-друид, находящийся в плену в Лабиринтах Иглошкурых. Он отправился в Степи изучать порчу колючих зарослей и наследие павшего кабана, Древнего Агамаггана, но был схвачен и смертельно замучен свинобразами.",al={"who is heralath","heralath fallowbrook","night elf in razorfen","кто такой гералат","гералат бурый ручей","ночной эльф в лабиринтах иглошкурых"}},{q="Что случилось с Гералатом в Лабиринтах Иглошкурых?",a="После того как Гералата взяли в плен свинобразы-иглошкурые, его избили и заперли в хижине. Из-за непрестанных издевательств и болезни его тело не выдержало, и к моменту, когда до него добрались спасатели, он был при смерти.",al={"why is heralath dying","what happened to heralath fallowbrook","почему гералат умирает","что случилось с гералатом бурый ручей"}},{q="О чем Гералат просит путников?",a="Зная, что не выживет, Гералат умоляет искателей приключений забрать кулон его жены у свинобразов и доставить ей в Дарнасс, передав печальную весть о его смерти.",al={"heralath quest","mortality wanes quest","задание гералата","угасание жизни задание"}},{q="Кем был Хенриг Лонбро для Гералата?",a="Хенриг Лонбро — пленный дворф, содержавшийся в том же загоне, что и Гералат. Прежде чем Хенригу удалось бежать, Гералат поделился с ним важными сведениями об Агамаггане и умолял передать на форпост Таланаар весть о действиях Чарлги Остробок.",al={"henrig lonebrow heralath","dwarf captive razorfen","хенриг лонбро гералат","пленный дворф иглошкурые"}}},fp="20,351,16.596.0,12.413.1,28.252.0,48.213.0,39.174.0,36.262.0"}
P.entries["npc:herod"] = {n="Герод",s="Герод — прославленный воитель и берсерк Алого ордена, командующий Оружейной в Монастыре Алого ордена. Известный свирепым боевым мастерством и непреклонным рвением, он обучает новобранцев жестокому ближнему бою, необходимому для священной войны. Его смерти добиваются и отступники из Альянса, и правители Орды в Подгороде, чтобы ослабить военное ядро ордена.",h="Герод — прославленный воитель и берсерк Алого ордена, командующий Оружейной в Монастыре Алого ордена.",kw={"armory","berserker","herod","raleigh the devout","ravager","scarlet crusade","scarlet monastery","varimathras","оружейная","берсерк","герод","ролей благочестивый","разоритель","алый орден","монастырь алого ордена","вариматрас"},ang={["class:Warrior"]="Герод — яркий пример разъяренного воина, чьи яростные удары вихря и безрассудная агрессия делают его грозным образцом воинской доблести среди новобранцев Алого ордена.",["faction:Alliance"]="Герои Альянса, откликнувшиеся на просьбу Ролея Благочестивого, могут воочию увидеть, как некогда благородные защитники Лордерона под началом таких вождей, как Герод, скатились к безумной фанатичной кровожадности.",["faction:Horde"]="Для Орды и особенно для Отрекшихся устранение Герода напрямую выполняет приказ Вариматраса сокрушить руководство, угрожающее границам Тирисфальских лесов."},sec={{t="Воитель Оружейной",b="В укрепленных залах Оружейной Монастыря Алого ордена Герод является воплощением военной агрессии ордена. В отличие от магов и паладинов, направляющих священную магию в Соборе, Герод полагается на грубую, кровожадную физическую силу. Облаченный в кольчугу и вооруженный огромным двуручным топором, он лично обучает отряды алых новобранцев, внушая им яростную преданность истреблению всех, кто не примкнул к их фанатичному делу."},{t="Первоочередная цель",b="Поскольку Герод руководит снабжением оружием и боевой подготовкой воинов передовой Алого ордена, его устранение необходимо всем, кто стремится уничтожить орден. Ролей Благочестивый, бывший крестоносец, разочаровавшийся в безумии ордена и живущий в Южнобережье, призывает уничтожить Герода, чтобы сломить военное руководство ордена. Во всем Лордероне повелитель ужаса Вариматрас в Подгороде также добивается его казни, чтобы избавиться от опасного человеческого оплота у границ земель Отрекшихся."}},faq={{q="Кто такой Герод?",a="Герод — элитный воин-человек и командир Оружейной в Монастыре Алого ордена. Он один из четырех главных предводителей Монастыря и отвечает за снаряжение и муштру фанатичных бойцов ближнего боя ордена.",al={"herod lore","who is herod","herod scarlet monastery","герод предания","кто такой герод","герод монастырь алого ордена"}},{q="Где находится Герод?",a="Герода можно найти в сердце крыла Оружейной в Монастыре Алого ордена, расположенном на северо-востоке Тирисфальских лесов. Он ждет противников на центральной тренировочной арене, окруженной галереями для зрителей.",al={"where is herod","herod location","find herod","где герод","местонахождение герода","найти герода"}},{q="Почему Орда хочет смерти Герода?",a="Повелитель ужаса Вариматрас, действуя от имени Отрекшихся в Подгороде, добивается уничтожения ключевых командиров Монастыря, включая Герода, чтобы устранить сохраняющуюся угрозу ордена прямо у порога столицы Отрекшихся.",al={"varimathras herod quest","why horde kill herod","into the scarlet monastery","вариматрас герод задание","зачем орде убивать герода","в монастырь алого ордена"}},{q="Почему Альянс хочет смерти Герода?",a="Ролей Благочестивый, бывший член Алого ордена, находящийся в Предгорьях Хилсбрада, понимает, что орден скатился в фанатичное рвение. Он просит защитников Альянса уничтожить Герода, чтобы лишить орден его жестокого воинского руководства.",al={"in the name of the light","raleigh the devout herod","why alliance kill herod","во имя света","ролей благочестивый герод","зачем альянсу убивать герода"}},{q="Что происходит после победы над Геродом?",a="После поражения Герода толпа молодых алых новобранцев выбегает из окружающих казарм на арену, чтобы отомстить за своего наставника, что показывает глубину преданности, которую он воспитал в своих учениках.",al={"scarlet trainees","herod trainee rush","herod death event","алые новобранцы","новобранцы герода","смерть герода"}},{q="Каким бойцом является Герод?",a="Герод — берсерк и воин, а не традиционный священный паладин. Он использует яростные рывки и размашистые удары вихря, чтобы сокрушать врагов, полагаясь на чистое физическое неистовство, а не на заклинания Света.",al={"herod fighting style","is herod a paladin","стиль боя герода","паладин ли герод"}}},fp="5,373,26.452.0,22.488.0,13.228.0,23.200.0,35.239.0,38.254.0,36.201.1,30.210.0"}
P.entries["npc:high-executor-darthalia"] = {n="Верховный палач Дарталия",s="Верховный палач Дарталия — высокопоставленный военачальник Отрекшихся, расквартированная в Мельнице Таррен в Предгорьях Хилсбрада. Действуя под непосредственным руководством леди Сильваны Ветрокрылой и Вариматраса, она руководит операциями Отрекшихся против человеческой крепости Южнобережье и местных бандитов Синдиката. Ее руководство играет ключевую роль в защите южного фланга Орды в Лордероне.",h="Верховный палач Дарталия — высокопоставленный военачальник Отрекшихся, расквартированная в Мельнице Таррен в...",kw={"darthalia","high executor","hillsbrad","hillsbrad foothills","southshore","sylvanas","syndicate","tarren mill","varimathras","дарталия","верховный палач","хилсбрад","предгорья хилсбрада","южнобережье","сильвана","синдикат","мельница таррен","вариматрас"},ang={["faction:Alliance"]="Для людей Южнобережья и их союзников Дарталия — беспощадный зачинщик непрерывных нападений, угрожающих их последнему оплоту в Лордероне.",["faction:Horde"]="Искатели приключений Орды докладывают Дарталии, чтобы сдерживать агрессию Альянса и удерживать спорный рубеж Предгорий Хилсбрада."},sec={{t="Командующая Мельницы Таррен",b="Действуя из Мельницы Таррен, Верховный палач Дарталия является оперативным командующим сил Отрекшихся во всех Предгорьях Хилсбрада. Ее главная стратегическая задача — остановить расширение человеческого сопротивления, удерживать силы Альянса в Южнобережье и выслеживать беззаконных разбойников Синдиката, наводнивших окрестности. Каждое наступление на юг Хилсбрада проходит непосредственно через ее командование."},{t="Война за Хилсбрад",b="По прямым приказам высшего руководства Подгорода — Королевы банши и ее лейтенанта Вариматраса, повелителя ужаса, — Дарталия руководит беспощадной войной на истощение в Хилсбраде. Она координирует разведывательные вылазки, целевые удары по человеческому руководству и награды за головы опасных преступников, угрожающих власти Отрекшихся на севере Лордерона."}},faq={{q="Кто такой Верховный палач Дарталия?",a="Верховный палач Дарталия — военачальница Отрекшихся, расквартированная в Предгорьях Хилсбрада. Она отвечает за руководство военными усилиями Орды и Отрекшихся против человеческого города Южнобережье и за уничтожение враждебных угроз в регионе.",al={"who is darthalia","darthalia identity","executor darthalia","кто такая дарталия","личность дарталии","палач дарталия"}},{q="Где можно найти Дарталию?",a="Она командует силами Отрекшихся из Мельницы Таррен, организуя войска и координируя удары по центральной части Лордерона.",al={"darthalia location","where is darthalia","executor darthalia map","где дарталия","местонахождение дарталии","палач дарталия на карте"}},{q="Кому подчиняется Дарталия?",a="Дарталия действует в рамках прямой военной иерархии Подгорода и подчиняется леди Сильване Ветрокрылой и повелителю ужаса Вариматрасу, которые координируют оборону и расширение территории Отрекшихся.",al={"darthalia boss","darthalia faction","who commands darthalia","начальник дарталии","фракция дарталии","кто командует дарталией"}},{q="Какие задания Дарталия дает искателям приключений?",a="Дарталия поручает защитникам Орды наносить прямые удары по человеческим поселениям, казнить опасных преступников и выслеживать членов Синдиката, действующих по всем Предгорьям Хилсбрада.",al={"darthalia quests","quests from darthalia","what does darthalia want","задания дарталии","задания от дарталии","что хочет дарталия"}},{q="Почему Дарталия воюет с людьми Южнобережья?",a="Южнобережье — главный военный оплот Альянса в Лордероне. Задача Дарталии — подавить присутствие людей, защитить Мельницу Таррен и не дать Альянсу продвинуться на север к Подгороду.",al={"why attack southshore","southshore war","hillsbrad conflict","зачем нападать на южнобережье","война за южнобережье","конфликт в хилсбраде"}},{q="Каково звание Дарталии в армии Отрекшихся?",a="Как Верховный палач, Дарталия занимает одно из высших полевых званий в военной иерархии Отрекшихся, что дает ей оперативное командование региональными силами, форпостами и военной стратегией в этой местности.",al={"high executor rank","darthalia title","звание верховного палача","титул дарталии"}}},fp="23,385,24.440.0,21.364.0,31.235.0,29.129.0,29.208.0,46.198.0,51.216.0,50.207.0"}
P.entries["npc:high-executor-derrington"] = {n="Верховный палач Деррингтон",s="Верховный палач Деррингтон командует авангардом Отрекшихся, расквартированным в Бастионе на восточной границе Тирисфальских лесов. Этот суровый офицер руководит обороной Орды на передовой против угрозы Плети и Алого ордена, исходящей из Западных Чумных земель. Из этого укрепленного заграждения он направляет опытных бойцов к спорным руинам, таким как Андорал и Некроситет.",h="Верховный палач Деррингтон командует авангардом Отрекшихся, расквартированным в Бастионе на восточной границе...",kw={"andorhal","bulwark","derrington","forsaken","high executor derrington","scourge","tirisfal glades","western plaguelands","андорал","бастион","деррингтон","отрекшиеся","верховный палач деррингтон","плеть","тирисфальские леса","западные чумные земли"},ang={["class:Warrior"]="Деррингтон воплощает мрачную практичную стойкость солдата передовой, ценящего воинское мастерство и результаты на поле боя выше придворных интриг.",["faction:Horde"]="Для путников из Орды, прибывающих в Тирисфаль, Деррингтон — главный военный командир, направляющий силы в опасные конфликты Западных Чумных земель.",["race:Undead"]="Деррингтон представляет воинскую опору армии Отрекшихся, всецело нацеленную на то, чтобы сохранить отвоеванные земли от захвата Плетью и фанатизма Алого ордена."},sec={{t="Командир у порога",b="Верховный палач Деррингтон стоит прямо перед укрепленными заграждениями Бастиона и служит стражем между населенной призраками безопасностью Тирисфальских лесов и гниющими ужасами Западных Чумных земель. У Деррингтона мало терпения к политическим интригам в Подгороде: передовая для него — горнило простого выживания. Солдатам Орды и наемникам, желающим проверить свою доблесть, Деррингтон дает прямые боевые приказы, отправляя разведчиков и ударные отряды вглубь зараженных земель, чтобы сдержать вторжения врага до того, как они прорвутся в Тирисфаль."},{t="Война на два фронта",b="Оборона Деррингтона осаждена сразу с нескольких направлений. На востоке находится Плеть, закрепившаяся в разрушенном городе Андорал и растекающаяся по окрестностям через оскверняющие котлы. Одновременно с этим фанатики Алого ордена оспаривают северные укрепления и непрестанно сражаются с патрулями Отрекшихся. Деррингтон координирует точечные контратаки, диверсии против позиций Алого ордена и планомерное уничтожение полей котлов Плети, чтобы защитить восточную границу."}},faq={{q="Кто такой верховный палач Деррингтон?",a="Верховный палач Деррингтон — старший командир Отрекшихся в Бастионе, военном форпосте, отделяющем Тирисфальские леса от Западных Чумных земель. Он координирует стратегическое наступление Орды на восток против Плети и Алого ордена.",al={"derrington","who is derrington","high executor derrington lore","деррингтон","кто такой деррингтон","верховный палач деррингтон предания"}},{q="Где находится Деррингтон?",a="Он расквартирован в Бастионе — укрепленном узком проходе на дальнем восточном краю Тирисфальских лесов, у дороги в Западные Чумные земли.",al={"where is derrington","derrington location","find high executor derrington","где деррингтон","местонахождение деррингтона","найти верховного палача деррингтон"}},{q="Какова цель Деррингтона в Бастионе?",a="Цель Деррингтона — обеспечить выживание Отрекшихся, удерживая прочный оборонительный периметр против Плети и нанося удары на восток, в Западные Чумные земли. Он поручает искателям приключений разведать Андорал, вывести из строя чумные котлы и нейтрализовать действия Алого ордена.",al={"what does derrington want","bulwark purpose","derrington mission","чего хочет деррингтон","назначение бастиона","миссия деррингтона"}},{q="Интересует ли Деррингтона политика Подгорода?",a="Нет. Деррингтон открыто презирает придворных интриганов и политиков, замечая, что на передовой такой роскоши нет: там за выживание приходится бороться каждый день.",al={"derrington personality","is derrington political","характер деррингтона","политик ли деррингтон"}},{q="Каких главных врагов Деррингтон поручает уничтожать солдатам?",a="Деррингтон в первую очередь нацеливается на Плеть, удерживающую руины Андорала, темных некромантов в Некроситете и ближайшие гарнизоны Алого ордена, угрожающие восточным путям снабжения Орды.",al={"derrington quests","what does derrington fight","задания деррингтона","с кем сражается деррингтон"}},{q="Почему Бастион так сильно укреплен?",a="Бастион — главный узкий проход между относительной безопасностью Тирисфальских лесов и действующими зонами боев в Чумных землях. Силы Деррингтона удерживают перевал, не давая огромным полчищам Плети или походам Алого ордена докатиться прямо до Подгорода.",al={"why is the bulwark here","bulwark lore","почему здесь бастион","предания бастиона"}}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:high-executor-hadrec"] = {n="Верховный палач Хадрик",s="Верховный палач Хадрик — военный командир гарнизона Отрекшихся в Гробнице в Серебряном бору. Из этого центрального склепа он руководит обороной от местных угроз, включая гноллов клана Гнилошкуров, и расследует исчезновение разведчиков в этой местности. Он — главный офицер, направляющий действия Орды по всему Серебряному бору.",h="Верховный палач Хадрик — военный командир гарнизона Отрекшихся в Гробнице в Серебряном бору.",kw={"deathstalker","fenris isle","hadrec","high executor","rot hide","sepulcher","shadowfang","silverpine","страж смерти","остров фенриса","хадрик","верховный палач","гнилошкуры","гробница","темный клык","серебряный бор"},ang={["class:Rogue"]="Хадрик сильно полагается на Стражей смерти в добыче сведений и часто привлекает скрытных агентов, чтобы вызволять пропавших товарищей и добывать вражескую сукровицу и документы.",["faction:Horde"]="Союзники Отрекшихся, прибывающие из Калимдора, докладывают Хадрику, помогая стабилизировать Серебряный бор, и на собственном опыте узнают, насколько шатко положение Орды на севере Лордерона.",["race:Undead"]="Для Отрекшихся, идущих на юг из Могильника, Хадрик — голос верховного командования Подгорода, превращающий новорожденную нежить в организованных защитников Лордерона."},sec={{t="Командир в Гробнице",b="Верховный палач Хадрик, расквартированный в мраке Гробницы, руководит военными операциями Отрекшихся по всему Серебряному бору. Хотя Тирисфальские леса надежно защищены силами Темной Госпожи, Серебряный бор остается полным опасностей: его окружают враждебные маги Даларана, дикие воргены и наступающие гноллы. На Хадрике лежит мрачная обязанность укреплять территорию Отрекшихся и искоренять все, что бросает вызов власти Подгорода к югу от столицы."},{t="Плеть Гнилошкуров",b="Значительная часть забот Хадрика связана с гноллами Гнилошкурами и Островом Фенриса. Эти твари, затронутые нежитью, заполонили Мертвое поле и берега Озера Лордамер, создавая непредсказуемую и жестокую угрозу для патрулей Отрекшихся. Хадрик посылает агентов обшаривать ветхие паромы и гниющие фермы в поисках улик, выяснять, что наделяет тварей силой, и готовить прямой удар по их островной твердыне."},{t="Взгляд на Темный Клык",b="Помимо нашествия гноллов, Хадрик внимательно следит за сведениями Стражей смерти — тайного разведывательного подразделения Отрекшихся. Когда тайные агенты пропадают возле жутких шпилей Крепости Темного Клыка, Хадрик поручает искателям приключений выяснить их судьбу, чтобы Темная Госпожа была в курсе дел загадочного верховного мага Аругала и его проклятых воргенов."}},faq={{q="Кто такой верховный палач Хадрик?",a="Хадрик — офицер армии Отрекшихся в звании верховного палача. Он командует гарнизоном в Гробнице и тем самым является высшей властью Отрекшихся в делах Серебряного бора.",al={"hadrec lore","who is hadrec","sepulcher commander","предания хадрика","кто такой хадрик","командир гробницы"}},{q="Где можно найти верховного палача Хадрика?",a="Он находится в Гробнице — поселении Отрекшихся в центре Серебряного бора, у главной дороги с севера на юг.",al={"hadrec location","where is hadrec","find hadrec","местонахождение хадрика","где хадрик","найти хадрика"}},{q="Против каких угроз Хадрик направляет игроков?",a="Хадрик направляет солдат и искателей приключений против гноллов Гнилошкуров, терзающих Мертвое поле и Остров Фенриса. Он также руководит заданиями по поиску пропавших шпионов Стражей смерти и выяснению того, что происходит в Крепости Темного Клыка.",al={"hadrec quests","what does hadrec do","silverpine missions","задания хадрика","чем занимается хадрик","задания серебряного бора"}},{q="Чем занимается верховный палач в военной структуре Отрекшихся?",a="Верховный палач — высокопоставленный полевой командир армии Отрекшихся, которому поручен полный стратегический надзор над целым региональным форпостом или участком фронта под властью леди Сильваны Ветрокрылой.",al={"forsaken high executor","high executor rank","hadrec rank","верховный палач отрекшихся","звание верховного палача","звание хадрика"}},{q="Почему Хадрика интересует Остров Фенриса?",a="Остров Фенриса стал главным логовом гноллов Гнилошкуров. Чтобы обезопасить Озеро Лордамер и окрестные водные пути для линий снабжения Отрекшихся, Хадрик организует разведку и в итоге штурм, чтобы сломить предводителей гноллов.",al={"fenris isle hadrec","why assault fenris isle","rot hide fenris","остров фенриса хадрик","зачем штурмовать остров фенриса","гнилошкуры фенрис"}},{q="Как Хадрик связан с Крепостью Темного Клыка?",a="Хадрик взаимодействует со Стражами смерти — орденом шпионов Отрекшихся. Когда разведчики, посланные к Крепости Темного Клыка, не возвращаются с докладом, Хадрик поручает доверенным агентам исследовать крепость и выяснить, что с ними случилось.",al={"shadowfang keep hadrec","hadrec arugal","deathstalkers in shadowfang","крепость темного клыка хадрик","хадрик аругал","стражи смерти в темном клыке"}}},fp="20,377,26.464.0,20.432.0,17.369.1,28.201.0,40.130.0,48.229.0,60.208.0,40.233.0,47.226.0"}
P.entries["npc:high-inquisitor-fairbanks"] = {n="Верховный инквизитор Фэйрбанкс",s="Верховный инквизитор Фэйрбанкс был некогда почитаемым жрецом Рыцарей Серебряной Длани и доверенным советником верховного лорда Александроса Могрейна. Некогда видный духовный лидер уцелевших защитников Лордерона, он оказался связан судьбой с темным падением Алого ордена.",h="Верховный инквизитор Фэйрбанкс был некогда почитаемым жрецом Рыцарей Серебряной Длани и доверенным советником...",kw={"ashbringer","cathedral","fairbanks","hearthglen","inquisitor","mograine","renault","scarlet monastery","silver hand","stratholme","испепелитель","собор","фэйрбанкс","дольный очаг","инквизитор","могрейн","рено","монастырь алого ордена","серебряная длань","стратхольм"},ang={["class:Paladin"]="Фэйрбанкс видел темнейший час Серебряной Длани: день, когда почитаемый паладин обратил легендарный священный клинок против собственного отца.",["class:Priest"]="До своего падения Фэйрбанкс направлял Свет вместе с Могрейном, очищая темную сферу, ставшую Испепелителем.",["faction:Alliance"]="Трагедия Фэйрбанкса уходит корнями в павшее королевство Лордерон, где остатки Великого Альянса раскололись на фанатиков и изгоев.",["race:Undead"]="Фэйрбанкс показывает высшее лицемерие Алого ордена: тот прячет за алтарем одного из своих зараженных чумой мертвецов, а сам сжигает невинных Отрекшихся."},sec={{t="Советник владельца Испепелителя",b="До падения Лордерона Фэйрбанкс был уважаемым святым человеком среди Рыцарей Серебряной Длани. Когда верховный лорд Александрос Могрейн созвал роковое собрание в трактире Южнобережья, Фэйрбанкс стоял рядом с ним, помогая направлять силу Света в загадочный кристалл, которому предстояло стать сердцем легендарного Испепелителя. Когда принц Артас распустил орден паладинов, Фэйрбанкс сопровождал Могрейна в Стальгорн и был свидетелем того, как король Магни Бронзобород выковал великий клинок для борьбы с Плетью."},{t="Предательство в Стратхольме",b="Фэйрбанкс сопровождал Александроса Могрейна, когда старший сын Верховного лорда, Рено, привел их в страшную засаду Плети под Стратхольмом. Фэйрбанкс пал одним из первых под натиском когтей нежити, погребенный под грудами гниющих трупов. Из этого жуткого положения он молча наблюдал, как Рено схватил павший Испепелитель и вонзил его в сердце собственного отца, осквернив священный клинок отцеубийством. Уцелев в бойне, Фэйрбанкс выбрался из-под мертвецов и бежал обратно в Дольный Очаг, чтобы разоблачить предательство Рено."},{t="Казнь и изгнание",b="Отчаянные предупреждения Фэйрбанкса потрясли уцелевших защитников Лордерона. Те, кто поверил его ужасающему рассказу, покинули фанатичный орден и образовали Серебряный Рассвет. Те же, кто остался верен Рено и Сайдану Датрохану, объявили Фэйрбанкса богохульником и безумцем. Заразившись чумой, пока был погребен под трупами Плети, Фэйрбанкс был тайно казнен Алым орденом. Вместо того чтобы предать его священному погребению, крестоносцы бросили его тело в тайной комнате за алтарем Собора, где он в конце концов восстал тем самым чудовищем, которое они клялись искоренить."}},faq={{q="Где найти верховного инквизитора Фэйрбанкса?",a="Фэйрбанкс скрыт в крыле Собора Монастыря Алого ордена. Чтобы добраться до него, войдите в боковую часовню справа от главного алтаря и потяните скрытый настенный факел: тайная каменная дверь откроется и приведет в уединенный склеп.",al={"where is fairbanks","how to find fairbanks","fairbanks secret room","monastery secret door","где фэйрбанкс","как найти фэйрбанкса","тайная комната фэйрбанкса","тайная дверь монастыря"}},{q="Почему Фэйрбанкс стал нежитью?",a="Во время засады в Стратхольме Фэйрбанкс был заживо погребен под грудами трупов Плети, которые заразили его чумой нежизни. После того как Алый орден казнил его за обвинения против своих предводителей, его брошенное тело в конце концов поддалось заразе и тайно восстало.",al={"why is fairbanks a zombie","is fairbanks scourge","why is fairbanks undead","почему фэйрбанкс зомби","фэйрбанкс из плети","почему фэйрбанкс нежить"}},{q="Кем был Фэйрбанкс до казни?",a="Фэйрбанкс был набожным жрецом Рыцарей Серебряной Длани и главным советником верховного лорда Александроса Могрейна. Он помогал очищать кристалл, из которого создали Испепелитель, и был одним из первых духовных лидеров уцелевших защитников Лордерона.",al={"fairbanks backstory","who is high inquisitor fairbanks","fairbanks lore","предыстория фэйрбанкса","кто такой верховный инквизитор фэйрбанкс","предания фэйрбанкса"}},{q="Что вызвало раскол между Алым орденом и Серебряным Рассветом?",a="Когда Фэйрбанкс вернулся из Стратхольма и рассказал о том, чему там стал свидетелем, орден раскололся. Те, кто поверил Фэйрбанксу и отверг фанатизм Рено, ушли и основали Серебряный Рассвет, а приверженцы Рено остались в Алом ордене.",al={"argent dawn origin","why did argent dawn split","fairbanks argent dawn","происхождение серебряного рассвета","почему раскололся серебряный рассвет","фэйрбанкс серебряный рассвет"}},{q="Почему Алый орден убил Фэйрбанкса?",a="Руководство Алого ордена объявило его рассказ о событиях в Стратхольме злонамеренным богохульством. Кроме того, заметив у него ранние симптомы чумы от ран, полученных в Стратхольме, рыцари ордена убили его, чтобы заглушить правду.",al={"why did scarlet kill fairbanks","who killed fairbanks","fairbanks execution","почему алый орден убил фэйрбанкса","кто убил фэйрбанкса","казнь фэйрбанкса"}},{q="Кто заменил Фэйрбанкса на посту верховного инквизитора?",a="После казни и тайного заточения Фэйрбанкса роль верховного инквизитора заняла Салли Вайтмейн, возглавив инквизиторские допросы в Монастыре Алого ордена вместе с командиром Рено Могрейном.",al={"who is high inquisitor now","fairbanks replacement","who succeeded fairbanks","кто сейчас верховный инквизитор","замена фэйрбанкса","кто сменил фэйрбанкса"}}},fp="25,278,25.520.0,22.541.1,19.595.2,43.243.0,36.304.2,41.263.0,70.264.2,43.255.2,42.219.0"}
P.entries["npc:high-priest-rohan"] = {n="Верховный жрец Рохан",s="Верховный жрец Рохан — главный служитель Церкви Священного Света в Стальгорне; его можно найти в Зале Тайн, где он расхаживает взад и вперед. Он руководит духовным ростом начинающих жрецов по всему Альянсу и помогает тем, кто стремится овладеть Светом. Своими наставлениями и священными реликвиями он поддерживает духовную связь между горным королевством, Штормградом и дальними союзниками.",h="Верховный жрец Рохан — главный служитель Церкви Священного Света в Стальгорне; его можно найти в Зале Тайн...",kw={"church of the holy light","exorcism censer","grayson shadowbreaker","hall of mysteries","high priest rohan","ironforge","mystic ward","priest trainer","rohan","церковь священного света","курильница экзорцизма","грейсон тенелом","зал тайн","верховный жрец рохан","стальгорн","мистический квартал","учитель жрецов","рохан"},ang={["class:Paladin"]="Святые рыцари, посланные лордом Грейсоном Тенеломом, должны посетить Рохана и получить его знаменитую курильницу экзорцизма в обмен на помощь нуждающимся Стальгорна.",["class:Priest"]="Верховный жрец Рохан дает важные наставления и начальные умения, а затем направляет вас к известным наставникам в Штормграде или Дарнассе, чтобы вы освоили особые расовые молитвы.",["faction:Alliance"]="Благодаря тесному сотрудничеству с Собором Света, Храмом Луны и Кругом Кенария Рохан прочно связывает духовенство Стальгорна со всем Альянсом.",["race:Dwarf"]="Рохан воплощает преданность дворфов Свету и показывает, что коренастый народ Каз Модана наделен глубокой верой наряду с наследием титанов."},sec={{t="Пастырь Зала Тайн",b="Расхаживая по тихим плитам Зала Тайн в Мистическом квартале, верховный жрец Рохан выступает высшим представителем Церкви Священного Света в Стальгорне. Хотя дворфы издревле почитали титанов, дворфийские жрецы глубоко восприняли добродетели Света — мудрость, сострадание и справедливость. Рохан терпеливо обучает молодых служителей дисциплине, необходимой, чтобы направлять священную магию и укреплять разум против отчаяния."},{t="Мосты через Альянс",b="Рохан понимает, что духовное постижение принимает в Альянсе множество форм. Когда жрецы под его руководством усваивают основы, он направляет их дальше: людей и дворфов отправляет к верховной жрице Лорене в Штормград, а учеников из числа ночных эльфов — к жрице Алатее в Храме Луны в Дарнассе, чтобы постичь труднодоступные тайны, например Благодать Элуны. За пределами столиц он призывает последователей помогать там, где царит нужда, и даже посылает целителей на помощь друидам Круга Кенария в далекой Азшаре."},{t="Курильница экзорцизма",b="Помимо наставничества, Рохан хранит священные реликвии, важные для жрецов Альянса и братств паладинов. Среди них — благословенная курильница экзорцизма, закаленная годами очищения от мерзких духов. Когда Орден Серебряной Длани и лорд Грейсон Тенелом нуждаются в этом сосуде, чтобы укрепить священное призвание своих рыцарей, Рохан охотно отдает его, прося лишь милостыню, чтобы пополнить скудеющие запасы пищи Стальгорна для нуждающихся горожан."}},faq={{q="Где найти верховного жреца Рохана?",a="Верховный жрец Рохан находится в Зале Тайн в Мистическом квартале на северной стороне Стальгорна. Он расхаживает между священной библиотекой и алтарем.",al={"rohan location","where is priest trainer ironforge","rohan map","hall of mysteries priest trainer","где рохан","где учитель жрецов стальгорн","рохан на карте","зал тайн учитель жрецов"}},{q="Какую роль играет Рохан в Стальгорне?",a="Он старший учитель жрецов в Стальгорне и главный дворфийский представитель Церкви Священного Света в Каз Модане. Он обучает новых жрецов, дает духовные советы и направляет последователей к дальнейшему обучению по всему Азероту.",al={"who is rohan","what does rohan do","rohan lore","кто такой рохан","чем занимается рохан","предыстория рохана"}},{q="Почему Рохан отправляет жрецов в Дарнасс или Штормград?",a="Рохан считает, что духовный рост требует знакомства с разными традициями. Людей и дворфов он посылает в Собор Света в Штормграде, чтобы изучить особые молитвы, например Молитву отчаяния, а ночных эльфов направляет обратно в Храм Луны в Дарнассе, чтобы они обрели Благодать Элуны.",al={"rohan class quests","desperate prayer rohan","temple of the moon quest","задания рохана","молитва отчаяния рохан","задание храм луны"}},{q="Почему паладины ищут Рохана?",a="Паладины, посланные лордом Грейсоном Тенеломом, приходят к Рохану за его благословенной курильницей экзорцизма. Рохан отдает реликвию, помогая Ордену Серебряной Длани завершить обряды, и просит взамен скромное пожертвование припасов для голодающих бедняков Стальгорна.",al={"paladin quest rohan","exorcism censer","emphasis on sacrifice","задание паладина рохан","курильница экзорцизма","жертва"}},{q="Почему Рохан отправляет жрецов в Азшару?",a="Следуя заветам Света о милосердии и служении, Рохан посылает целителей на помощь ночным эльфам-друидам Круга Кенария, работающим в диких и суровых землях Азшары.",al={"cenarion aid rohan","rohan cenarion circle","помощь кенарийцам рохан","рохан круг кенария"}},{q="Обучает ли Рохан только дворфов?",a="Рохан наставляет любого последователя Альянса на пути жреца, будь то дворфы, люди или ночные эльфы: он дает начальное обучение, а затем отправляет их к наставникам их собственных традиций.",al={"can humans train with rohan","who does rohan train","могут ли люди учиться у рохана","кого обучает рохан"}}},fp="17,395,33.472.0,27.561.0,19.496.0,35.189.0,40.249.0,54.304.0,31.267.0,39.182.0,30.217.0"}
P.entries["npc:high-priestess-laurena"] = {n="Верховная жрица Лорена",s="Верховная жрица Лорена — уважаемая учительница жрецов из числа людей; она стоит за главным алтарем в Соборе Света в Штормграде. Спасшись из разрушенного Лордерона беженкой во время Третьей войны, теперь она обучает начинающих жрецов Альянса духовной преданности и магическим защитам.",h="Верховная жрица Лорена — уважаемая учительница жрецов из числа людей; она стоит за главным алтарем в Соборе...",kw={"arcane feedback","benedictus","cathedral of light","desperate prayer","high priestess","holy light","laurena","lordaeron","priest trainer","stormwind","волшебное искажение","бенедикт","собор света","молитва отчаяния","верховная жрица","свет","лорена","лордерон","учитель жрецов","штормград"},ang={["class:Priest"]="Верховная жрица Лорена — одна из главных наставниц жрецов в Штормграде: она ведет служителей-людей через священные испытания, дарует им Молитву отчаяния и учит способам прерывать вражеских заклинателей.",["faction:Alliance"]="Из Собора Света Лорена укрепляет духовный стержень Альянса, помогая его защитникам противостоять темной магии и ужасам нежити.",["race:Human"]="Как и многие люди в Штормграде, Лорена несет скорбь о павшем северном королевстве Лордерон; она отстроила свою жизнь заново и стала духовной опорой для собратьев-выживших."},sec={{t="Беженка из Лордерона",b="До того как занять место в высоких залах Собора Света, Лорена жила в северном королевстве Лордерон. Когда во время Третьей войны Плеть захлестнула эти земли, ей и всей ее семье посчастливилось выжить и бежать на юг, в Штормград, где они оказались беженцами. Несмотря на огромное горе и хаос, разрушившие ее родину, Лорена осталась тверда в своей вере и в итоге стала Верховной жрицей на службе Церкви Священного Света."},{t="Забота о верующих",b="Верховная жрица Лорена стоит прямо за центральным алтарем в святилище собора и посвящает себя наставничеству будущих жрецов. Когда многообещающие служители проявляют достаточно усердия и благочестия, их направляют к ней для углубления знаний. Лорена учит их призывать священные дары, например Молитву отчаяния, и обучает защитным искусствам, включая заклинания, обращающие вражескую волшебную магию против тех, кто ею владеет. Когда ученик усвоил все, что она может дать, она отправляет его к другим мастерам-жрецам Альянса."}},faq={{q="Где найти верховную жрицу Лорену?",a="Она стоит за главным алтарем в Соборе Света, который находится на Соборной площади в Штормграде.",al={"laurena location","where is priestess laurena","find laurena","где лорена","где жрица лорена","найти лорену"}},{q="Чему учит верховная жрица Лорена?",a="Лорена — учитель жрецов. Она дает основы людям-жрецам и обучает особым расовым молитвам, например Молитве отчаяния, а также защитам, таким как Волшебное искажение, оберегающим от враждебных заклинателей.",al={"laurena spells","priest trainer laurena","what does laurena teach","заклинания лорены","учитель жрецов лорена","чему учит лорена"}},{q="Откуда Лорена прибыла в Штормград?",a="Лорена родом из королевства Лордерон. Во время Третьей войны ее семья сумела избежать ужасов Плети и бежала в Штормград беженцами, где она продолжила свое религиозное служение.",al={"laurena backstory","is laurena from stormwind","laurena lordaeron","предыстория лорены","лорена из штормграда","лорена лордерон"}},{q="Подчиняется ли она архиепископу Бенедикту?",a="Да. Архиепископ Бенедикт — духовный предводитель Церкви Священного Света и возглавляет Собор Света, где Лорена служит Верховной жрицей.",al={"laurena and benedictus","who is laurena's boss","benedictus laurena","лорена и бенедикт","кто начальник лорены","бенедикт лорена"}},{q="Почему она направляет меня к другим учителям жрецов?",a="Разные народы и расы Альянса общаются с божественным по-своему. Когда Лорена обучила учеников основным молитвам Света, она отправляет их к мастерам-жрецам других традиций — например, к дворфийским мастерам в Стальгорне или жрицам ночных эльфов в Дарнассе, — чтобы расширить их духовный кругозор.",al={"laurena sends me away","a lack of fear quest","elunes grace quest","лорена отправляет меня прочь","задание отсутствие страха","задание благодать элуны"}},{q="Потеряла ли Лорена семью из-за нежити?",a="Что удивительно, ее ближайшая семья пережила падение Лордерона. Они были в числе счастливых беженцев, которым удалось невредимыми уйти от Плети и проделать долгий путь на юг, в безопасный Штормград.",al={"laurena family dead","what happened to laurena family","семья лорены погибла","что случилось с семьей лорены"}}},fp="22,297,22.515.0,20.585.0,40.123.0,39.227.0,45.214.0,43.166.0,48.338.0,42.203.0"}
P.entries["npc:highlord-demitrian"] = {n="Верховный лорд Демитриан",s="Верховный лорд Демитриан — одинокий человек-отшельник, живущий среди странных кристаллов на северо-западе Силитуса. Называя себя верным слугой принца Громораана, он владеет тайными знаниями, нужными для пробуждения спящего повелителя стихий. Искатели приключений с древними оковами стихий приходят к нему, чтобы раскрыть силу Ветроискателя.",h="Верховный лорд Демитриан — одинокий человек-отшельник, живущий среди странных кристаллов на северо-западе...",kw={"crystal vale","demitrian","highlord demitrian","silithus","thunderaan","thunderfury","vessel of rebirth","windseeker","долина кристаллов","демитриан","верховный лорд демитриан","силитус","громораан","громовая ярость","сосуд возрождения","ветроискатель"},ang={["class:Rogue"]="Разбойники, охотящиеся за легендарным клинком Ветроискателя, должны заключить сделку с Демитрианом в Силитусе, чтобы вернуть разбитого принца.",["class:Warrior"]="Воины, ищущие легендарный клинок Громовая ярость, должны найти Демитриана, чтобы начать испытание освобождения и пробуждения Ветроискателя.",["profession:Blacksmithing"]="Требования Демитриана для возрождения Громораана подразумевают глубокое мастерство кузнечного дела, чтобы выковать слитки зачарованного элементия из необработанной руды и огненных эссенций."},sec={{t="Отшельник Долины Кристаллов",b="Демитриан обитает в заброшенном лагере в Долине Кристаллов и выглядит чужим среди безжизненных пустошей Силитуса. Хотя он связан с Сумеречным Молотом, в чьем разоренном лагере он бродит, прежде всего он служит глашатаем принца Громораана, Ветроискателя. К гостям он относится с холодным безразличием, если они не несут доказательств разбитой сущности Ветроискателя."},{t="Сосуд возрождения",b="Цель Демитриана целиком связана с воскрешением Громораана. Если искатель приключений принесет ему Наручники Ветроносца — реликвии, добытые у огненных элементалей в Огненных Недрах, — Демитриан выдаст Сосуд возрождения. Он требует редкие стихийные реагенты, включая огромное количество зачарованного элементия и сущность Повелителя огня, чтобы восстановить физическую форму своего принца."},{t="Предательство Ветроискателя",b="Ритуал Демитриана призывает принца Громораана в Долину Кристаллов, где искатели приключений должны сразиться с возрожденным Ветроискателем. Победив повелителя стихий, они забирают Дремлющий клинок Игривого Ветра и приносят его испуганному Демитриану, который взамен пробуждает Громовую ярость."}},faq={{q="Где найти верховного лорда Демитриана?",a="Он находится на дальнем северо-западе Силитуса, возле Разоренного Сумеречного лагеря в Долине Кристаллов.",al={"demitrian location","where is demitrian","demitrian silithus spot","где демитриан","демитриан силитус","место демитриана"}},{q="Почему Демитриан отвечает лишь общими фразами?",a="Демитриан не предложит свою легендарную цепочку заданий, пока у вас нет хотя бы одной половины Наручников Ветроносца — редких сокровищ, которыми владеют барон Геддон и Гарр в Огненных Недрах.",al={"demitrian won't talk to me","how to get demitrian quest","demitrian gossip","демитриан не говорит со мной","как получить задание демитриана","диалог демитриана"}},{q="Как Демитриан связан с принцем Громорааном?",a="Демитриан — давший клятву смертный слуга принца Громораана. Он посвятил себя поискам разорванных оков принца и возвращению повелителя стихий в материальный мир.",al={"who does demitrian serve","demitrian thunderaan connection","is demitrian twilight hammer","кому служит демитриан","демитриан и громораан","демитриан сумеречный молот"}},{q="Что произойдет, если принести ему все материалы для сосуда?",a="Демитриан проводит ритуал, призывающий принца Громораана в Долину Кристаллов и возвращающий Ветроискателя в материальный мир.",al={"summoning thunderaan","what does demitrian do with the vessel","crystal vale summon","призыв громораана","что демитриан делает с сосудом","призыв долина кристаллов"}},{q="Связан ли Демитриан с культом Сумеречного Молота?",a="Он связан с Сумеречным Молотом и обитает в их разоренном лагере, а о Древних богах говорит с благоговением. Тем не менее его клятва верности принадлежит господину, принцу Громораану.",al={"is demitrian a cultist","demitrian twilight camp","demitrian faction","демитриан культист","демитриан сумеречный лагерь","фракция демитриана"}},{q="Как получить у него Громовую ярость?",a="Задание Демитриана связано с Наручниками Ветроносца и редкими материалами, относящимися к Громораану. Оно вовлекает искателей приключений в дело, уходящее корнями в заточение принца стихий.",al={"how to get thunderfury","thunderfury quest finish","demitrian blade","как получить громовую ярость","завершение задания громовая ярость","клинок демитриана"}}},fp="18,351,26.385.0,21.400.1,26.289.1,36.122.0,48.202.0,54.181.0,65.133.1,56.178.0,36.188.1"}
P.entries["npc:hogger"] = {n="Дробитель",s="Дробитель — свирепый вожак гноллов стаи Речной Лапы, рыскающих на юго-западе Элвиннского леса. Он намного крупнее сородичей и необычайно агрессивен, а своими набегами на местные фермы и убийствами ничего не подозревающих путников снискал дурную славу. За его жестокие нападения маршалы Штормграда назначили официальную награду.",h="Дробитель — свирепый вожак гноллов стаи Речной Лапы, рыскающих на юго-западе Элвиннского леса.",kw={"bounty","defias","dughan","elwynn","gnoll","goldshire","hogger","riverpaw","награда","братство справедливости","дугхан","элвиннский лес","гнолл","златоземье","дробитель","речная лапа"},ang={["faction:Alliance"]="Набеги Дробителя показывают, насколько истощена армия Штормграда: маршалам приходится полагаться на странствующих авантюристов, чтобы поддерживать порядок возле столицы.",["race:Human"]="Для юных защитников Штормграда встреча с Дробителем — первое серьезное испытание и прямой ответ на угрозы, подрывающие сердце Элвиннского леса."},sec={{t="Ужас Речной Лапы",b="Обосновавшись на холме Дробителя на юго-западе Элвиннского леса, Дробитель с неумолимой жестокостью правит местной стаей Речной Лапы. В годы после Третьей войны набеги гноллов на окрестные усадьбы становились все более дерзкими и согласованными. За ростом насилия стоит тревожный союз: Речная Лапа начала сговариваться с Братством Справедливости, обменивая свирепость на оружие, тактическое руководство и магическую поддержку. Чтобы защитить границы Элвиннского леса и торговые пути от дальнейшего кровопролития, маршал Дугхан назначил щедрую награду за голову Дробителя."}},faq={{q="Кто такой Дробитель?",a="Дробитель — огромный и чрезвычайно опасный гнолл, возглавляющий стаю Речной Лапы на юго-западе Элвиннского леса. Он известен набегами на соседние фермы, и власти Штормграда желают его смерти за жестокие нападения на человеческие поселения.",al={"hogger lore","who is hogger","riverpaw leader","дробитель предания","кто такой дробитель","вожак речной лапы"}},{q="Почему за голову Дробителя назначена награда?",a="Маршал Дугхан и стража Штормграда объявили официальную награду за Дробителя из-за его участившихся набегов на фермы и путников. Тот, кто осмелится положить конец его буйству, должен принести его огромную лапу в Златоземье в доказательство.",al={"wanted hogger","why kill hogger","hogger bounty","разыскивается дробитель","зачем убивать дробителя","награда за дробителя"}},{q="Работают ли гноллы Речной Лапы вместе с Братством Справедливости?",a="Да. Братство Справедливости вступило в сговор со стаей Речной Лапы: оно снабжает грубых гноллов добротным оружием, тактическими советами и магической поддержкой, чтобы еще сильнее подорвать власть Штормграда в этой местности.",al={"hogger defias","gnoll defias connection","riverpaw defias","дробитель братство справедливости","гноллы и братство справедливости","речная лапа братство"}},{q="Где Дробитель устраивает свой лагерь?",a="Дробитель обитает на холме Дробителя на юго-западе Элвиннского леса, в окружении преданных соплеменников из Речной Лапы, неподалеку от границы Западного Края.",al={"hogger location","where is hogger","hogger hill","где дробитель","местонахождение дробителя","холм дробителя"}}},fp="6,312,22.569.0,14.234.0,32.237.0,60.218.0,32.149.0"}
P.entries["npc:holt-thunderhorn"] = {n="Хольт Громовой Рог",s="Хольт Громовой Рог — таурен, учитель охотников на Вершине Охотников в парящем городе Громовой Утес. Он обучает как начинающих, так и опытных следопытов, дает основы боевой подготовки и направляет взрослеющих стрелков к особым испытаниям по всему Мулгору и за его пределами.",h="Хольт Громовой Рог — таурен, учитель охотников на Вершине Охотников в парящем городе Громовой Утес.",kw={"holt thunderhorn","hunter rise","hunter trainer","mulgore","thunder bluff","хольт громовой рог","вершина охотников","учитель охотников","мулгор","громовой утес"},ang={["class:Hunter"]="Хольт Громовой Рог — главный наставник в Громовом Утесе: он обучает приемам обращения с оружием, выслеживанию и направляет к приручению зверей.",["race:Tauren"]="Хольт на Вершине Охотников воплощает традиционную охотничью культуру таурен, которая кормила и защищала кочевые племена задолго до того, как они обрели постоянный дом на вершинах утеса."},sec={{t="Хозяин Вершины",b="Хольт Громовой Рог, обосновавшийся на Вершине Охотников над широкими равнинами Мулгора, служит Орде опытным наставником по стрельбе, выслеживанию и выживанию. Как и многие старейшины его ремесла, он помогает молодым таурен перейти от бродячей охоты к службе дисциплинированных защитников их новой столицы."}},faq={{q="Где можно найти Хольта Громового Рога?",a="Хольт Громовой Рог стоит на Вершине Охотников — юго-восточном возвышенном плато в столице таурен, Громовом Утесе, в Мулгоре.",al={"holt thunderhorn location","where is holt","hunter trainer thunder bluff","хольт громовой рог где","где хольт","учитель охотников громовой утес"}},{q="Чему учит Хольт Громовой Рог?",a="Он учитель охотников: обучает игроков основам стрельбы, выживания в дикой природе и приручения зверей, а также направляет новичков к особым испытаниям по повелению зверей.",al={"what does holt teach","holt thunderhorn trainer","what abilities holt","чему учит хольт","хольт громовой рог учитель","какие умения у хольта"}},{q="Какую роль охотники играют в Громовом Утесе?",a="Охотники — традиционная опора общества таурен: они добывают пропитание, патрулируют границы владений от набегов кентавров и чтят Мать-Землю уравновешенным, почтительным выслеживанием.",al={"hunter rise purpose","tauren hunter lore","вершина охотников","предания охотников таурен"}}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:houndmaster-loksey"] = {n="Псарь Локси",s="Псарь Локси — офицер, отвечающий за разведение и обучение грозных боевых псов Алого ордена. Он служит в псарне Оружейной Монастыря Алого ордена и натравливает свои своры на нежить, чужаков и мнимых еретиков. Его беспощадная дисциплина прославила монастырских зверей по всем Тирисфальским лесам.",h="Псарь Локси — офицер, отвечающий за разведение и обучение грозных боевых псов Алого ордена.",kw={"armory","houndmaster loksey","hounds","huntsman leopold","kennels","loksey","scarlet crusade","scarlet monastery","оружейная","псарь локси","псы","охотник леопольд","псарня","локси","алый орден","монастырь алого ордена"},ang={["class:Hunter"]="Локси олицетворяет жестокий, агрессивный подход к дрессировке зверей: он заставляет свирепых псов подчиняться фанатизму, а не выстраивает связь взаимного уважения.",["race:Undead"]="Отрекшимся лазутчикам следует остерегаться псов Локси: их специально учат улавливать запах мертвой плоти и предупреждать гарнизоны ордена."},sec={{t="Хозяин псарни",b="За хорошо укрепленными стенами Монастыря Алого ордена Псарь Локси руководит обучением свирепых ищеек и боевых псов. Алый орден рассчитывает на этих псов, когда нужно выследить зараженные чумой трупы, раскрыть спрятавшихся лазутчиков и догнать выживших, бегущих от гнева фанатиков. Локси полностью властвует над псарней Оружейной и следит, чтобы его подопечные были готовы разорвать чужаков на части."},{t="Семейное соперничество",b="Локси — не единственный в семье, кто обращается со зверями на службе делу. Его брат, охотник Леопольд, служит посланником Алого ордена при Серебряном Рассвете в Часовне Последней Надежды. Леопольд невысокого мнения о брате и в частных разговорах утверждает, что Локси едва справляется со своими псами, не говоря уж о том, чтобы представлять орден в важных дипломатических делах. Несмотря на презрение Леопольда, Локси остается ключевым офицером во внутренней иерархии Монастыря."}},faq={{q="Где можно найти Псаря Локси?",a="Псарь Локси находится в Оружейной Монастыря Алого ордена на северо-востоке Тирисфальских лесов, среди своих боевых псов в псарне.",al={"loksey location","where is loksey","houndmaster loksey location","локси где","где локси","местонахождение псаря локси"}},{q="Какую роль играет Локси в Алом ордене?",a="Он главный псарь Алого ордена в Монастыре и отвечает за разведение, выучку и командование боевыми псами, которых используют, чтобы вынюхивать нежить и выслеживать чужаков.",al={"what does loksey do","loksey job","houndmaster duty","что делает локси","должность локси","обязанности псаря"}},{q="Кем Локси приходится охотник Леопольд?",a="Охотник Леопольд — брат Локси. Леопольд представляет Алый орден в Часовне Последней Надежды и смотрит на Локси свысока, утверждая, что тот не способен как следует управлять псами и исполнять дипломатические обязанности.",al={"leopold loksey brother","who is leopold","loksey brother","леопольд брат локси","кто такой леопольд","брат локси"}},{q="Зачем Алому ордену псы?",a="Орден обучает свирепых псов, чтобы они по запаху выслеживали Плеть и Отрекшихся, охраняли территорию Монастыря и рвали на части убегающих врагов.",al={"why dogs","scarlet hounds purpose","crusade dogs","зачем собаки","назначение алых псов","собаки ордена"}},{q="Считается ли Локси одним из предводителей Монастыря Алого ордена?",a="Да, Локси признан одним из ключевых командиров в военной структуре Монастыря Алого ордена и руководит важной работой псарни в Оружейной.",al={"is loksey a boss","loksey rank","how important is loksey","локси босс","ранг локси","насколько важен локси"}},{q="Опасны ли псы сами по себе?",a="Да. Выращенные для агрессии и выдрессированные Локси, боевые псы Монастыря — свирепые хищники, способные за считаные мгновения разорвать закованного в доспехи чужака.",al={"are dogs strong","scarlet hounds danger","loksey pets","сильны ли собаки","опасность алых псов","питомцы локси"}}},fp="18,355,21.443.0,14.441.0,38.160.0,51.205.0,34.214.0,40.167.0,55.170.0,38.165.0"}
P.entries["npc:huldar"] = {n="Хальдар",s="Хальдар — дворф-возчик, стоящий на южной дороге Лок Модана у берега озера. Ему поручено доставлять жизненно важный взрывной порошок к месту раскопок на юге, а его караван постоянно подвергается нападениям местных опасностей и диверсантов из клана Черного Железа.",h="Хальдар — дворф-возчик, стоящий на южной дороге Лок Модана у берега озера.",kw={"blast powder","caravan","dark iron","excavation","huldar","loch modan","wagon","взрывной порошок","караван","черное железо","раскопки","хальдар","лок модан","повозка"},ang={["profession:Engineering"]="Любой инженер знает цену — и опасность — необработанного взрывного порошка, лежащего без защиты в брошенных деревянных бочках.",["race:Dwarf"]="Помощь Хальдару напрямую поддерживает раскопки Лиги исследователей и обеспечивает ваших сородичей порошком, нужным для раскрытия древних тайн титанов."},sec={{t="Опасная доставка порошка",b="Перевозка взрывчатки через Лок Модан — не простое дело. Хальдару поручили везти повозки с горным взрывным порошком к южным раскопкам, где дворфы-археологи и старатели отчаянно нуждаются в припасах. Но дороги в глуши становятся все опаснее. Из-за местных зверей, троггов и лазутчиков из клана Черного Железа у южного изгиба озера Хальдар застрял с поврежденной повозкой и надеется, что странники помогут сберечь оставшиеся бочонки с порошком и доставить груз к месту раскопок."}},faq={{q="Кто такой Хальдар?",a="Хальдар — дворф-возчик, застрявший со своей повозкой на южном берегу озера в Лок Модане. Ему поручили доставить взрывной порошок на ближайшие раскопки, но в пути случилась беда.",al={"who is huldar","huldar loch modan","wagon dwarf","кто такой хальдар","хальдар лок модан","дворф с повозкой"}},{q="Что в повозке Хальдара?",a="В его повозке бочки со взрывным порошком. Эта взрывчатка крайне нужна дворфам-старателям и археологам, работающим на раскопках к югу.",al={"what is huldar transporting","huldar wagon cargo","what are the barrels","что везет хальдар","груз повозки хальдара","что за бочки"}},{q="Почему Хальдар застрял на дороге?",a="Дороги на юге Лок Модана стали опасными из-за враждебных зверей, троггов и диверсантов — дворфов из клана Черного Железа. На груз Хальдара напали из засады, и ему пришлось остановиться и искать помощи, чтобы уберечь и доставить оставшиеся припасы.",al={"why is huldar stranded","huldar ambush","почему хальдар застрял","засада хальдара"}},{q="Почему дворфов из клана Черного Железа интересует его груз?",a="The Dark Iron clan actively seeks to undermine Ironforge's presence and historical research throughout Loch Modan. Cutting off blast powder halts excavation efforts and deprives dwarven operations of defensive and industrial supplies.",al={"dark iron blast powder","why dark irons attack huldar","взрывной порошок черного железа","почему черное железо нападает на хальдара"}}},fp="6,268,21.566.0,14.208.0,26.167.0,32.232.0,50.234.0"}
P.entries["npc:illiyana"] = {n="Иллиана",s="Иллиана — древняя дриада на юго-западе Ясеневого леса, посвятившая себя защите лесов от древней порчи. Бродя возле Святилища Эссины, она собирает героев Альянса, чтобы отразить свирепых сатиров, терзающих древние рощи. Ее бдительность воплощает вечную связь между дочерьми Кенария и дикой природой ночных эльфов.",h="Иллиана — древняя дриада на юго-западе Ясеневого леса, посвятившая себя защите лесов от древней порчи.",kw={"ashenvale","branch of cenarius","cenarius","dryad","forest song","illiyana","satyr","shrine of aessina","ясеневый лес","ветвь кенария","кенарий","дриада","песнь леса","иллиана","сатир","святилище эссины"},ang={["class:Druid"]="Друиды высоко чтут дриад как воплощение дикой природы, а помощь Иллиане в сохранении священных рощ напрямую отвечает долгу Кенария исцелять землю.",["race:NightElf"]="Для кальдораев дриады вроде Иллианы — священная родня Кенария, почитаемые защитницы, и их призыв к оружию против демонических сатиров встречает безотлагательный отклик."},sec={{t="Дочь леса",b="Как и все дриады, Иллиана — одна из дочерей полубога Кенария. Мирная, но яростно защищающая дикие земли, она патрулирует леса на юго-западе Ясеневого леса. Пока темные силы шевелятся, а леса страдают от ползущей порчи, Иллиана охраняет священные реликвии и рощи, храня первозданную святость природы."},{t="Угроза сатиров",b="Главная забота Иллианы в этих краях — неискоренимая скверна сатиров. Эти извращенные демонические существа неустанно стремятся осквернить поляны и угрожают ее сестрам-дриадам. Иллиана часто просит проходящих путников истреблять этих мерзких тварей и возвращать утраченные артефакты, включая Ветвь Кенария, чтобы леса оставались защищены от демонической скверны."}},faq={{q="Кто такая Иллиана?",a="Иллиана — дриада, бродящая на юго-западе Ясеневого леса возле Святилища Эссины. Как дочь Кенария, она посвящает свое существование охране диких земель и защите сестер от демонических сил.",al={"who is this dryad","illiyana ashenvale","what is illiyana","что за дриада","иллиана ясеневый лес","кто такая иллиана"}},{q="Почему Иллиана продолжает ходить, пока я с ней говорю?",a="Иллиана постоянно обходит лес по своему маршруту. В отличие от неподвижных персонажей, выдающих задания, она продолжает бдительно расхаживать по роще, даже беседуя с путниками.",al={"illiyana moving","why does she walk away","illiyana quest walking","иллиана двигается","почему она уходит","иллиана задание ходит"}},{q="Какие задания предлагает Иллиана?",a="Она призывает искателей приключений истреблять мерзких сатиров, угрожающих округе, и возвращать священные реликвии, например Ветвь Кенария, чтобы защитить своих сестер-дриад.",al={"illiyana quests","forest song quests","задания иллианы","задания песни леса"}},{q="Где находится Иллиана?",a="Она патрулирует возле Святилища Эссины на юго-западе Ясеневого леса, следя за тропами и ближними рощами.",al={"illiyana location","where to find illiyana","forest song dryad location","где иллиана","как найти иллиану","местонахождение дриады песни леса"}},{q="Почему сатиры угрожают дриадам?",a="Сатиры — древние ночные эльфы, искаженные демонической порчей, которые находят удовольствие в осквернении природы и порабощении детей Кенария. Дриады олицетворяют чистую, нетронутую красоту леса, поэтому становятся главной мишенью злобы сатиров.",al={"why do satyrs hate dryads","dryads and satyr lore","почему сатиры ненавидят дриад","дриады и сатиры предания"}},{q="Помогает ли Иллиана Орде?",a="Нет. Иллиана союзница ночных эльфов и всего Альянса. Тех, кто из Орды войдет в ее рощу, она и ее союзники встретят враждебно.",al={"is illiyana hostile to horde","can horde talk to illiyana","враждебна ли иллиана к орде","может ли орда говорить с иллианой"}}},fp="8,384,22.345.0,23.388.0,16.218.0,51.198.0,31.163.0,26.114.0,41.230.0,29.146.0"}
P.entries["npc:illiyana-moonblaze"] = {n="Иллиана Лунное Сияние",s="Иллиана Лунное Сияние — необычная разведчица и интендант из ночных эльфов, находящаяся в Роще Среброкрылых в Ясеневом лесу. Действуя вместе со Среброкрылыми Часовыми, она снабжает защитников Альянса, сражающихся против Всадников Песни Войны. Несмотря на офицерское положение, острое чутье и разбойничьи манеры выделяют ее среди традиционных военных чинов кальдораев.",h="Иллиана Лунное Сияние — необычная разведчица и интендант из ночных эльфов, находящаяся в Роще Среброкрылых в...",kw={"ashenvale","care package","illiyana moonblaze","rogue","sentinel","silverwing grove","warsong gulch","ясеневый лес","паек","иллиана лунное сияние","разбойник","часовой","роща среброкрылых","ущелье песни войны"},ang={["class:Rogue"]="Иллиана — редкое явление среди кальдораев: опытная скрытная следопытка, открыто работающая рядом с регулярными войсками вопреки традиционному презрению общества.",["faction:Alliance"]="Для бойцов Альянса, идущих на юг к спорной границе Ущелья Песни Войны, Иллиана — главный интендант, поставляющий оружие, доспехи и пайки.",["race:NightElf"]="Ее разбойничий облик резко контрастирует с обычными жрицами и Часовыми и показывает, как разведчики кальдораев применяют независимые методы для защиты Ясеневого леса."},sec={{t="Разведчица вне строя",b="Иллиана Лунное Сияние служит главным офицером снабжения Среброкрылых Часовых, расположившихся в Роще Среброкрылых. Однако достаточно одного взгляда, чтобы понять: она совсем не обычный часовой. С двумя клинками и в темном корсете она держится с развязностью разбойницы или пирата, а не с дисциплинированной выправкой воинов Элуны. Традиционная иерархия Часовых издавна относилась к людям ее ремесла настороженно, почти как к беззаконным разбойникам. Тем не менее ее непревзойденная хитрость и талант следопыта делают ее незаменимой в спорных лесах."},{t="Снабжение для линии фронта",b="Помимо необычных обязанностей разведчицы, Иллиана снаряжает добровольцев Альянса, готовящихся к схватке с кланом Песни Войны в Ущелье Песни Войны. Когда защитники заслуживают расположение Среброкрылых Часовых, она награждает их службу особыми пайками, редкими напитками и превосходным вооружением, созданным специально для лесных стычек. Она также чинит оружие и доспехи усталых бойцов, возвращающихся с передовой, и поддерживает снабжение военных усилий Часовых."}},faq={{q="Где найти Иллиану Лунное Сияние?",a="Она находится в Роще Среброкрылых на юго-востоке Ясеневого леса, рядом с местом сбора и порталом в Ущелье Песни Войны.",al={"illiyana moonblaze location","where is illiyana","silverwing quartermaster location","где иллиана лунное сияние","где найти иллиану","интендант среброкрылых"}},{q="Входит ли Иллиана Лунное Сияние в число Часовых?",a="Формально она имеет офицерское положение для координации снабжения, но не является традиционным Часовым. Ее прошлое связано с разведчиками и разбойниками кальдораев — ремеслом, к которому общество Часовых исторически относилось с подозрением.",al={"is illiyana a sentinel","illiyana rank","illiyana faction","иллиана часовой","звание иллианы","фракция иллианы"}},{q="Что Иллиана предлагает защитникам Альянса?",a="Она служит интендантом Среброкрылых Часовых и предлагает тем, кто заслужил репутацию у фракции, пайки, боевое вооружение, кольца, гербовые накидки и расходуемые предметы для борьбы в Ущелье Песни Войны.",al={"what does illiyana sell","warsong gulch rewards ashenvale","illiyana vendor","что продает иллиана","награды ущелья песни войны ясеневый лес","торговец иллиана"}},{q="Почему она выглядит и ведет себя как разбойница?",a="Ее умения основаны на скрытности, хитрости и смертоносном выслеживании, а не на жреческой преданности или воинской дисциплине Часовых. Хотя общество ночных эльфов часто считало такие пути бесчестными или сродни пиратству, ее практические навыки выживания в дикой природе оказываются жизненно важными в трудные времена.",al={"illiyana rogue lore","why is she dressed like a pirate","illiyana pirate","иллиана разбойница","почему одета как пират","иллиана пират"}},{q="Чинит ли она снаряжение?",a="Да, помимо снабжения особым военным снаряжением, она предоставляет обычный ремонт оружия и доспехов защитникам Альянса, отдыхающим в роще.",al={"can illiyana repair","silverwing repair vendor","repair in silverwing grove","может ли иллиана чинить","ремонт у среброкрылых","ремонт в роще среброкрылых"}},{q="Какие пайки она выдает?",a="Она помогает бойцам Альянса в заданиях по снабжению, связанных с простыми, обычными и усиленными пайками Часовых, обеспечивая защитников на передовой необходимыми припасами.",al={"sentinel care package","illiyana quests","warsong gulch packages","паек часовых","задания иллианы","пайки ущелья песни войны"}}},fp="18,371,25.572.0,28.478.0,36.125.0,48.241.0,47.221.0,39.282.0,35.148.0,37.188.0"}
P.entries["npc:ilthalaine"] = {n="Илталайн",s="Илталайн — ночной эльф-страж, несущий дозор в священной роще Тенистой долины на Тельдрассиле. Он первым встречает и наставляет юных ночных эльфов, делающих первые шаги в мире. Бдительный и чуткий к природе, он направляет начинающих искателей приключений к поддержанию хрупкого природного равновесия на ветвях Мирового Древа.",h="Илталайн — ночной эльф-страж, несущий дозор в священной роще Тенистой долины на Тельдрассиле.",kw={"aldrassil","balance of nature","ilthalaine","kaldorei","quest giver","shadowglen","sigil","teldrassil","альдрассил","природное равновесие","илталайн","кальдораи","задания","тенистая долина","печать","тельдрассил"},ang={["class:Druid"]="Для начинающих друидов наставления Илталайна об отстреле и природном равновесии становятся первыми практическими уроками принципов Кенария.",["faction:Alliance"]="Он воплощает спокойную, непреходящую бдительность кальдораев, принимая новых защитников на службу Дарнассу и всему Альянсу.",["race:NightElf"]="Илталайн — первый наставник, которого встречает каждый юный ночной эльф; он дает основы мудрости о заботе и священном равновесии их нового дома на Тельдрассиле."},sec={{t="Страж рощи",b="Стоя у сердца Тенистой долины, Илталайн часто оказывается первым, кого видит юный ночной эльф в начале пути. Он наблюдает за лесными тропами и замечает тонкие перемены в лесу, невидимые обычному глазу. Его долг — приветствовать возвращающихся сородичей и следить, чтобы новые защитники были воспитаны в традициях своего народа и готовы к обязанностям, связанным с заботой о Тельдрассиле."},{t="Природное равновесие",b="Даже под защитным пологом Тенистой долины среди местных зверей растет неестественная агрессия. Илталайн поручает юным защитникам охотиться на бродячих ночных саблезубов и кабанов, чья растущая численность и свирепость грозят нарушить гармонию ветви. Он видит в отстреле не жестокость, а священный долг — сохранить жизнь и унять необычное беспокойство, проникающее в новое Мировое Древо."},{t="Наставник на пути дисциплины",b="Помимо проверки воинского мастерства на искаженных животных, Илталайн направляет юных эльфов к их призванию. Вручая каждому путнику печать класса, он указывает прямо на их наставников в святилище Альдрассила — идет ли речь о пути воина, друида, разбойника, жреца или охотника. Благодаря ему каждый новичок узнает, где начинается его служба кальдораям."}},faq={{q="Кто такой Илталайн?",a="Илталайн — надзиратель кальдораев в Тенистой долине, защищенной начальной обители Тельдрассила. Он выдает первые задания только что созданным ночным эльфам, знакомя их с обязанностями и состоянием леса.",al={"ilthalaine lore","who is this night elf","shadowglen quest giver","илталайн предания","кто этот ночной эльф","задания тенистой долины"}},{q="Какова роль Илталайна в Тенистой долине?",a="Он присматривает за дикой природой Тенистой долины и следит, чтобы новые ночные эльфы понимали важность природного равновесия. Он отправляет юных посвященных на простую охоту и направляет их к учителям их классов внутри великого дерева Альдрассил.",al={"what does ilthalaine do","why is he here","ilthalaine purpose","что делает илталайн","почему он здесь","предназначение илталайна"}},{q="Почему Илталайн хочет сократить число молодых ночных саблезубов и кабанов?",a="Лесные создания Тенистой долины стали необычайно свирепыми и агрессивными, нарушая природную гармонию леса. Илталайн поручает юным защитникам сократить их излишнюю численность, чтобы восстановить порядок на ветви.",al={"balance of nature quest","why kill nightsabers","why kill boars","задание природное равновесие","зачем убивать саблезубов","зачем убивать кабанов"}},{q="Что это за печати, которые он выдает?",a="Илталайн выдает новичкам печати с надписями для каждого класса и велит искать их наставников — жриц, друидов, воинов и разбойников, — укрывшихся среди корней Альдрассила.",al={"etched sigil","simple sigil","verdant sigil","encrypted sigil","hallowed sigil","гравированная печать","простая печать","зеленая печать","зашифрованная печать","освященная печать"}},{q="Где можно найти Илталайна?",a="Он стоит прямо на центральной тропе Тенистой долины, к югу от огромной полой ветви Альдрассила на Тельдрассиле.",al={"ilthalaine location","where is ilthalaine","ilthalaine coords","где илталайн","илталайн координаты","местонахождение илталайна"}},{q="Связан ли Илталайн с друидами или с Часовыми?",a="Илталайн выступает общим попечителем и представителем кальдораев в Тенистой долине. Хотя он глубоко чувствует природу и друидический дух гармонии, он действует от имени всего дарнасского руководства, направляя новичков любой дисциплины.",al={"is he a druid","what faction is ilthalaine","он друид","к какой фракции относится илталайн"}}},fp="10,368,20.455.0,21.412.0,21.409.0,18.238.0,40.249.0,64.225.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-allison"] = {n="Хозяйка таверны Аллисон",s="Хозяйка таверны Аллисон управляет «Позолоченной розой» — одной из самых оживленных и центральных таверн Штормграда. Таверна расположена в самом сердце Торгового квартала, между банком и аукционным домом, и предлагает усталым путникам и местным торговцам привязку камня возвращения, прохладительные напитки и кров.",h="Хозяйка таверны Аллисон управляет «Позолоченной розой» — одной из самых оживленных и центральных таверн...",kw={"allison","gilded rose","hearthstone","innkeeper allison","stormwind","trade district","аллисон","позолоченная роза","камень возвращения","хозяйка таверны аллисон","штормград","торговый квартал"},ang={["faction:Alliance"]="Как хозяйка самой доступной таверны в торговом сердце Штормграда, Аллисон — одно из самых знакомых лиц для защитников Альянса, возвращающихся с передовой, чтобы отдохнуть и сдать добычу в банк."},sec={{t="Гостеприимство Торгового квартала",b="Расположенная между шумным торговым аукционным домом и главными хранилищами города, «Позолоченная роза» служит центром притяжения для искателей приключений, прибывающих в Штормград. Хозяйка таверны Аллисон стоит за главной стойкой на первом этаже, поддерживая порядок среди постоянного потока торговцев, наемников и приезжих дипломатов. Помимо предоставления ночлега и привязки камня возвращения, она часто участвует в местных праздниках и организует небольшие поручения для странствующих героев, ищущих отдыха в столице."}},faq={{q="Где найти хозяйку таверны Аллисон?",a="Хозяйка таверны Аллисон стоит за стойкой на первом этаже «Позолоченной розы». Таверна находится прямо в Торговом квартале Штормграда, между центральным банком и аукционным домом.",al={"allison location","where is innkeeper allison","gilded rose innkeeper","где аллисон","где хозяйка таверны аллисон","трактирщица позолоченной розы"}},{q="Какие услуги предлагает хозяйка таверны Аллисон?",a="Она оказывает обычные услуги трактирщика: игроки могут привязать камень возвращения к «Позолоченной розе», купить еду и напитки для отдыха, а во время городских сезонных событий и праздников порой взаимодействовать с ней.",al={"what does allison do","allison services","can i bind hearthstone here","что делает аллисон","услуги аллисон","привязать камень возвращения здесь"}},{q="Выдает ли хозяйка таверны Аллисон задания?",a="Да, Аллисон участвует в различных сезонных торжествах в течение года, например в праздниках, и порой бывает вовлечена в городские поручения для путников, ищущих помощи по всему королевству.",al={"allison quests","innkeeper allison quest","задания аллисон","задание хозяйки таверны аллисон"}}},fp="17,295,33.512.0,35.204.0,43.210.0,40.201.0"}
P.entries["npc:innkeeper-farley"] = {n="Хозяин таверны Фарли",s="Хозяин таверны Фредрик Фарли управляет таверной «Гордость Льва» в Златоземье, предоставляя еду, кров и камни возвращения путникам, проезжающим через Элвиннский лес. Его любят, он наблюдателен, часто хранит потерянную почту и выслушивает беды искателей приключений в пути.",h="Хозяин таверны Фредрик Фарли управляет таверной «Гордость Льва» в Златоземье, предоставляя еду, кров и камни...",kw={"elwynn forest","frandis","fredrik farley","goldshire","innkeeper farley","lion's pride inn","stalvan","элвиннский лес","фрэндис","фредрик фарли","златоземье","хозяин таверны фарли","таверна гордость льва","сталван"},ang={["faction:Alliance"]="Для новобранцев, выходящих из Долины Североземья, стойка Фарли в «Гордости Льва» часто становится первым местом, где они привязывают камень возвращения и закупают припасы."},sec={{t="Неотъемлемая часть Златоземья",b="Семья Фарли содержит таверну «Гордость Льва» со времен правления короля Ллейна Ринна I. Вместе с женой Вериной и дочерью Анной Фредрик ведет дело с радушием и острым глазом. Его большие крепкие руки хорошо подходят, чтобы разнимать трактирные драки и выставлять буйных посетителей, и он поддерживает порядок на одной из самых оживленных остановок королевства. Хотя его дни заполнены разливом эля и подачей сыра, он несет личное горе: его брат Фрэндис, стражник, погиб в Лордероне во время чумы Плети."},{t="Брошенный сундук гонца",b="Поскольку Златоземье лежит на перекрестке между Штормградом, Западным Краем и Сумеречным лесом, Фарли слышит множество слухов и имеет дело со странными путниками. В частности, он однажды приютил гонца, который в ужасе сбежал в ночь, бросив сумку. Фарли надежно спрятал оставшиеся письма в сундуке наверху — среди них нераспечатанное письмо бывшему школьному учителю Сталвану Мистмантлу, которое впоследствии становится важной уликой для расследователей, прослеживающих путь павшего наставника."}},faq={{q="Кто такой хозяин таверны Фарли?",a="Фредрик Фарли — владелец таверны «Гордость Льва» в Златоземье. Его семья управляет таверной из поколения в поколение, со времен короля Ллейна Ринна I. Он ведет дело вместе с женой Вериной, предлагая отдых и припасы путникам, пересекающим Элвиннский лес.",al={"innkeeper farley","fredrik farley","who is the goldshire innkeeper","хозяин таверны фарли","фредрик фарли","кто трактирщик в златоземье"}},{q="Что Фарли знает о Сталване Мистмантле?",a="Фарли помнит перепуганного гонца, который среди глубокой ночи сбежал из таверны «Гордость Льва», оставив несколько посылок. Фарли убрал брошенные письма в сундук наверху; среди них есть недоставленное письмо Сталвану Мистмантлу, которое могут забрать расследователи.",al={"farley stalvan","stalvan letter goldshire","legend of stalvan farley","фарли сталван","письмо сталвана златоземье","легенда о сталване фарли"}},{q="Где брат Фарли?",a="Брат Фредрика, Фрэндис Фарли, покинул юг и работал охранником караванов в северном королевстве Лордерон. Во время Третьей войны Фрэндис, как сообщалось, погиб от чумы нежити, разбив сердце Фредрику.",al={"farley brother","frandis farley lore","what happened to farley's brother","брат фарли","фрэндис фарли","что случилось с братом фарли"}},{q="Какие услуги Фарли предоставляет в таверне?",a="Фарли привязывает камни возвращения путников, сдает комнаты и продает множество напитков, соков и сыров со всего Альянса — от Альтеракского сыра и Даларанского острого сыра до местного Бри из Штормграда.",al={"lion's pride services","farley food and drink","goldshire hearthstone","услуги гордости льва","еда и напитки фарли","камень возвращения златоземье"}}},fp="16,265,19.550.0,29.508.1,24.280.0,47.282.0,26.219.0,45.209.0"}
P.entries["npc:innkeeper-firebrew"] = {n="Хозяин таверны Огневар",s="Хозяин таверны Огневар управляет таверной «Каменный огонь» в шумном Общинном квартале Стальгорна. Радушный хозяин для усталых горцев и приезжих сановников, он подает сытные дворфийские блюда и дает путникам отдых в недрах горы.",h="Хозяин таверны Огневар управляет таверной «Каменный огонь» в шумном Общинном квартале Стальгорна.",kw={"commons","dwarf","firebrew","hearthstone","innkeeper","ironforge","stonefire tavern","общинный квартал","дворф","огневар","камень возвращения","хозяин таверны","стальгорн","таверна каменный огонь"},ang={["faction:Alliance"]="Как главный хозяин таверны у главных врат, Огневар дает приезжим путникам Альянса центральное безопасное место для отдыха во время визита в столицу короля Магни Бронзоборода.",["race:Dwarf"]="Для дворфов, возвращающихся из дозоров по Каз Модану, таверна Огневара дарит уютное тепло дома и надежную кружку дворфийского крепкого эля."},sec={{t="Хозяин «Каменного огня»",b="Заведение хозяина таверны Огневара расположено в центральном кольце Общинного квартала и часто становится первым убежищем для путников, входящих через Великие врата Стальгорна. За стойкой, уставленной кружками эля, мехами с крепким элем и жареными окороками, Огневар встречает искателей приключений, направляющихся в заснеженные перевалы Дун Морога или вглубь горного королевства. Его таверна остается оживленным перекрестком, где собираются шахтеры, стрелки и посланники, чтобы укрыться от сквозняков в туннелях и обменяться рассказами у очага."}},faq={{q="Где найти хозяина таверны Огневара?",a="Хозяин таверны Огневар находится в таверне «Каменный огонь» на южной окраине Общинного квартала в Стальгорне.",al={"firebrew location","where is innkeeper firebrew","ironforge tavern keeper","где огневар","где хозяин таверны огневар","трактирщик стальгорна","расположение огневара"}},{q="Какие товары продает Огневар?",a="Он предлагает обычные товары хозяина таверны, специализируясь на сытной дворфийской еде. Путники могут купить напитки от местного дворфийского крепкого эля и меда до привозных вин, а также мясо и сытные блюда для дальних дорог.",al={"what does firebrew sell","firebrew drinks","stonefire tavern food","что продает огневар","напитки огневара","еда в таверне каменный огонь"}},{q="Принадлежит ли Огневар к какому-либо дворфийскому клану пивоваров?",a="Он носит фамилию Огневар, но его родственные связи не подтверждены.",al={"firebrew family","who is firebrew related to","семья огневара","чей родственник огневар"}},{q="Какие услуги он оказывает путникам?",a="Как хозяин таверны, Огневар позволяет путникам Альянса привязать камень возвращения к таверне «Каменный огонь» и предоставляет теплую постель, чтобы отдохнуть и восстановить силы в недрах горы.",al={"can i bind hearthstone here","ironforge hearthstone inn","привязать камень возвращения здесь","таверна стальгорна камень возвращения"}}},fp="18,235,23.540.0,36.117.0,38.230.0,47.78.0,43.178.0"}
P.entries["npc:innkeeper-grosk"] = {n="Хозяин таверны Гроск",s="Хозяин таверны Гроск управляет таверной в Колючем Холме и предлагает усталым путникам еду, питье и ночлег в центре Дуротара. Его заведение стоит на оживленной дороге между Долиной Испытаний и Оргриммаром и служит главным местом отдыха для молодых искателей приключений Орды, отправляющихся в большой мир.",h="Хозяин таверны Гроск управляет таверной в Колючем Холме и предлагает усталым путникам еду, питье и ночлег в...",kw={"durotar","grosk","innkeeper","innkeeper grosk","orgrimmar","peon's burden","razor hill","дуротар","гроск","хозяин таверны","хозяин таверны гроск","оргриммар","ноша батрака","колючий холм"},ang={["faction:Horde"]="Для молодых орков, троллей и приезжих тауренов, идущих на север от Долины Испытаний или Деревни Сен'джин, таверна Гроска — первый настоящий город и место привязки камня возвращения на дороге к Оргриммару."},sec={{t="Гостеприимство в Красных пустошах",b="Колючий Холм — важное поселение на перекрестке дорог, соединяющее южные тренировочные земли Дуротара с высокими стенами Оргриммара. В центре этого привала стоит хозяин таверны Гроск, орк, на котором лежит забота о приюте для воинов, разведчиков и батраков. Его таверна дает передышку от жаркой пустыни: здесь есть простая провизия, сытное мясо и прохладная вода для каждого путника под ее крепкими балками."},{t="Отдых для батрака",b="Гроск помогает не только проезжим путникам, но и местным работникам, на которых держится Дуротар. В задании «Ноша батрака» робкий батрак Укор, дотащивший еду до Долины Испытаний и узнавший, что она там не нужна, просит путников отнести груз обратно в таверну Гроска в Колючем Холме."}},faq={{q="Где находится хозяин таверны Гроск?",a="Хозяин таверны Гроск находится в таверне Колючего Холма, расположенного в самом центре Дуротара на главной дороге, ведущей на север к Оргриммару.",al={"innkeeper grosk location","where is grosk","razor hill innkeeper","где гроск","хозяин таверны гроск","трактирщик колючего холма","расположение гроска"}},{q="Какие услуги предоставляет хозяин таверны Гроск?",a="Гроск — хозяин таверны, у которого искатели приключений Орды могут привязать камень возвращения к Колючему Холму. Он также продает простую еду, воду и мясо, чтобы восстановить здоровье и ману между походами.",al={"what does grosk do","grosk vendor","can i bind hearthstone at razor hill","что делает гроск","гроск торговец","привязать камень возвращения в колючем холме"}},{q="Дает ли хозяин таверны Гроск какие-либо задания?",a="Он участвует в задании «Ноша батрака»: принимает груз с едой, который батрак Укор, испугавшись зверей Дуротара, не решился сам донести до Колючего Холма.",al={"innkeeper grosk quests","a peons burden turn in","задания гроска","ноша батрака сдать"}}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-gryshka"] = {n="Хозяйка таверны Гришка",s="Хозяйка таверны Гришка — орчиха, управляющая таверной «Сломанный клык» в Аллее Силы Оргриммара. Она первой встречает путников, входящих в ворота города, привязывает камни возвращения и предлагает еду и питье гостям из Орды. Она поддерживает тесные связи с охотниками и разведчиками по всему Дуротару и Степям, чтобы в ее таверне всегда были отборные куски мяса.",h="Хозяйка таверны Гришка — орчиха, управляющая таверной «Сломанный клык» в Аллее Силы Оргриммара.",kw={"broken tusk","doras","gryshka","hearthstone","innkeeper","orgrimmar","valley of strength","zargh","сломанный клык","дорас","гришка","камень возвращения","хозяин таверны","оргриммар","аллея силы","заргх"},ang={["faction:Horde"]="Для любого путника Орды, прибывшего в Дуротар, таверна Гришки в Аллее Силы часто становится главным местом, где можно привязать камень возвращения и пополнить запасы перед походом вглубь Калимдора.",["profession:Cooking"]="Повара оценят взыскательный вкус Гришки: она не жалеет усилий, чтобы добыть лучшие куски у охотников, живущих даже в Степях."},sec={{t="Очаг Аллеи Силы",b="За стойкой «Сломанного клыка» Гришка управляет одной из самых оживленных таверн Орды. Ее заведение находится сразу за главными воротами Оргриммара в Аллее Силы и служит первым местом отдыха для воинов, гонцов и прибывших героев, ищущих приют под знаменем Тралла."},{t="Вкус свежего мяса",b="Чтобы держать шумную таверну в засушливом каньоне, нужны постоянные поставки. Гришка известна любовью к свежему мясу и полагается на надежных охотников по землям Орды, снабжающих ее кухню. Такие товарищи, как Заргх на Перекрестке и Гримтак в Дуротаре, регулярно присылают в «Сломанный клык» лучшие куски дичи, чтобы удовлетворить ее взыскательные кулинарные требования."}},faq={{q="Кто такая хозяйка таверны Гришка?",a="Хозяйка таверны Гришка — орчиха, которая держит таверну «Сломанный клык» в Аллее Силы Оргриммара. Она принимает путников Орды, привязывает камни возвращения и продает еду и питье усталым искателям приключений.",al={"who is gryshka","gryshka orgrimmar","innkeeper broken tusk","кто такая гришка","гришка оргриммар","хозяйка таверны сломанный клык"}},{q="Где можно найти хозяйку таверны Гришку?",a="Она находится в таверне «Сломанный клык» в Аллее Силы — первом крупном районе, в который вы попадаете, пройдя через главные южные ворота Оргриммара.",al={"where is gryshka","broken tusk inn location","valley of strength innkeeper","где гришка","сломанный клык расположение","трактирщик аллеи силы"}},{q="Откуда Гришка берет мясо?",a="Гришка полагается на друзей и разведчиков по землям Орды, которые снабжают ее кладовую, в том числе на Заргха, живущего на Перекрестке в Степях, и Гримтака в Дуротаре, присылающих ей отборные куски дичи.",al={"gryshka food sources","who supplies the broken tusk","zargh meat delivery","откуда еда у гришки","кто снабжает сломанный клык","мясо от заргха"}},{q="Какие услуги предоставляет Гришка?",a="Гришка может привязать ваш камень возвращения к «Сломанному клыку», чтобы вы могли телепортироваться прямо в Оргриммар. Она также продает разную еду, хлеб и напитки для восстановления здоровья и маны.",al={"can i bind my hearthstone here","broken tusk hearthstone","gryshka vendor items","привязать камень возвращения здесь","сломанный клык камень возвращения","товары гришки"}},{q="Связана ли Гришка с насестом наездников на ветрокрылах?",a="Путники, отправленные с поручениями по перелетам из Степей, часто доставляют посылки прямо Гришке, а затем их направляют к Дорасу, укротителю ветрокрылов, живущему высоко на плато над городом.",al={"doras quest","wind rider master broken tusk","ride to orgrimmar inn","задание дораса","укротитель ветрокрылов сломанный клык","полет к таверне оргриммара"}},{q="Какой у Гришки характер?",a="Гришка — практичная, радушная орчиха, которая ценит хорошее мясо, прямую речь и держит таверну в достатке и порядке для постоянного потока воинов Орды, проходящих через столицу.",al={"is gryshka friendly","what is gryshka like","дружелюбна ли гришка","какая гришка"}}},fp="17,404,32.337.0,22.381.0,25.213.0,37.166.0,41.195.0,35.172.0,57.190.0,43.196.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="Хозяин таверны Кельдамир",s="Хозяин таверны Кельдамир заведует очагом и ночлегом центральной таверны в Доланааре на Тельдрассиле. Он предлагает еду, питье и место для отдыха молодым ночным эльфам, выходящим из Тенистой долины в широкие ветви Мирового Древа.",h="Хозяин таверны Кельдамир заведует очагом и ночлегом центральной таверны в Доланааре на Тельдрассиле.",kw={"dolanaar","hearthstone","inn","innkeeper","keldamyr","night elf","teldrassil","доланаар","камень возвращения","таверна","хозяин таверны","кельдамир","ночной эльф","тельдрассил"},ang={["race:NightElf"]="Для ночных эльфов, только покинувших тренировочные земли Тенистой долины, таверна Кельдамира обычно становится первым домом вдали от дома, где они привязывают камни возвращения."},sec={{t="Очаг Доланаара",b="Доланаар — первая большая деревня, до которой добираются новички, покинув укрытую поляну Альдрассила. Хозяин таверны Кельдамир ведет центральный приют общины, предлагая хлеб, родниковую воду и мягкие постели под покровом Тельдрассила. Путники, часовые и юные послушники, идущие в Дарнасс, часто останавливаются у его стойки, чтобы отдохнуть душой, привязать камни возвращения и запастись провизией для пути по ветвям."},{t="Доставки в городе",b="Таверне высоко среди ветвей нужны постоянные поставки из ближних поселений и от ремесленников. Местных курьеров часто отправляют прямо к столу Кельдамира, чтобы оставить товары, и это напрямую связывает его с ежедневной торговлей и снабжением, благодаря которым поселение Доланаар работает без перебоев."}},faq={{q="Где найти хозяина таверны Кельдамира?",a="Кельдамир находится в главном здании таверны в сердце Доланаара — первого крупного поселения к югу от Тенистой долины на ветвях Тельдрассила.",al={"keldamyr location","where is keldamyr","dolanaar innkeeper location","где кельдамир","расположение кельдамира","трактирщик доланаара"}},{q="Какие услуги предлагает хозяин таверны Кельдамир?",a="Он местный хозяин таверны: у его очага вы можете привязать камень возвращения, купить простую провизию — воду, молоко, сок и хлеб — или выйти из игры, отдохнув под его крышей.",al={"keldamyr wares","what does keldamyr sell","dolanaar inn food","товары кельдамира","что продает кельдамир","еда в таверне доланаара"}},{q="В каких заданиях участвует хозяин таверны Кельдамир?",a="Он получатель местного курьерского поручения «Посылка в Доланаар» и принимает посылки для содержания и снабжения таверны поселения.",al={"keldamyr quests","dolanaar delivery turn in","задания кельдамира","посылка в доланаар сдать"}}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:innkeeper-norman"] = {n="Хозяин таверны Норман",s="Хозяин таверны Норман заведует очагом главной таверны в Торговом квартале Подгорода. Тихий и усердный Отрекшийся, он предлагает путникам Орды отдых, привязку камней возвращения и еду на разные вкусы как живых, так и мертвых.",h="Хозяин таверны Норман заведует очагом главной таверны в Торговом квартале Подгорода.",kw={"bates","hallow's end","hearthstone","innkeeper","norman","trade quarter","undercity","бейтс","тыквовин","камень возвращения","хозяин таверны","норман","торговый квартал","подгород"},ang={["faction:Horde"]="Для живых союзников из Орды, посещающих Подгород, таверна Нормана — одно из немногих мест, где можно безопасно отдохнуть и восстановить силы в этой негостеприимной подземной крепости.",["race:Undead"]="Норман дает собратьям Отрекшимся центральное место сбора в сердце Торгового квартала, чтобы отдохнуть между поручениями Темной Госпожи."},sec={{t="Гостеприимство в Канализации",b="Хозяин таверны Норман, чья таверна расположена в оживленном Торговом квартале под разрушенной столицей Лордерона, дает кров посланникам, наемникам и искателям приключений, проходящим через оплот Отрекшихся. Несмотря на сырой холод и алхимическую вонь Подгорода, таверна Нормана остается шумным центром для путников, желающих привязать камни возвращения, поделиться новостями со всего Азерота или подготовиться к походам в Чумные земли."},{t="Праздничные чудачества",b="Обычно Норман занят продажей провизии и сдачей комнат, но с наступлением Тыквовина раскрывается его более странная сторона. В праздник Норман участвует в веселье и требует от отважных посетителей странных представлений — например, кудахтать как курица, — если они хотят получить праздничные лакомства вроде подгородских мятных конфет."}},faq={{q="Где найти хозяина таверны Нормана?",a="Хозяин таверны Норман находится в главной таверне Торгового квартала Подгорода, расположенной на южном изгибе внутреннего кольца.",al={"norman location","undercity innkeeper location","where is norman","где норман","расположение нормана","трактирщик подгорода"}},{q="Какие услуги предоставляет хозяин таверны Норман?",a="Он один из главных хозяев таверн Подгорода. Игроки могут привязать камни возвращения к его таверне, купить еду и питье для живых и нежити или безопасно выйти из игры, чтобы накопить отдых.",al={"norman services","undercity hearthstone","услуги нормана","камень возвращения подгород"}},{q="Почему Норман просит посетителей кудахтать как курица?",a="Во время праздника Тыквовин Норман участвует в традиционных праздничных проделках. Искатели приключений, желающие получить особые праздничные мятные конфеты, должны наступить на горло гордости и закудахтать как курица, чтобы заслужить его расположение.",al={"chicken clucking mints","norman chicken quest","кудахтанье конфеты","задание нормана курица","мятные конфеты"}},{q="Родственник ли Норман хозяину таверны Бейтсу?",a="Хотя они не упоминают друг друга ни при жизни, ни после смерти, о родстве между ними ничего не известно. Их имена вместе — игривый намек создателей мира на хозяина мотеля Нормана Бейтса из фильма «Психо».",al={"norman bates connection","innkeeper bates norman","норман бейтс","хозяин таверны бейтс норман"}}},fp="16,256,25.440.0,22.353.0,34.140.0,44.201.0,52.197.0,37.216.0"}
P.entries["npc:innkeeper-pala"] = {n="Хозяйка таверны Пала",s="Хозяйка таверны Пала управляет «Котом и шаманом» — шумной таверной на нижнем уровне Громового Утеса. Она предлагает приезжим искателям приключений привязать камень возвращения, холодные напитки и место для отдыха между путешествиями по Мулгору и за его пределами.",h="Хозяйка таверны Пала управляет «Котом и шаманом» — шумной таверной на нижнем уровне Громового Утеса.",kw={"cat and the shaman","hearthstone","innkeeper","innkeeper pala","mulgore","pala","thunder bluff","кот и шаман","камень возвращения","хозяйка таверны","хозяйка таверны пала","мулгор","пала","громовой утес"},ang={["faction:Horde"]="Орки, тролли и Отрекшиеся, приходящие в Мулгор, находят в таверне Палы удобную базу прямо у подъемников.",["race:Tauren"]="Для тауренов, возвращающихся домой с рубежей Калимдора, Пала — знакомое приветливое лицо под высокими тотемами центральных плато."},sec={{t="Гостеприимство нижнего уровня",b="Хозяйка таверны Пала присматривает за очагом «Кота и шамана» на нижнем уступе обширных плато Громового Утеса. Это заведение — одно из главных мест встречи путников, сходящих с центральных подъемников или прибывающих с раскинувшихся равнин Мулгора. Пала неусыпно следит за общим залом и заботится о том, чтобы усталые воины, странствующие друиды и гости из союзников Орды находили надежный кров, горячий напиток и привычное подобие родного дома вдали от дома."}},faq={{q="Где найти хозяйку таверны Палу?",a="Пала находится в таверне «Кот и шаман» на нижнем уступе Громового Утеса, рядом с главными подъемниками города.",al={"pala location","where is pala","innkeeper pala map","где пала","расположение палы","хозяйка таверны пала карта"}},{q="Какие услуги она оказывает путникам?",a="Как и другие хозяева таверн Калимдора, Пала может привязать ваш камень возвращения к «Коту и шаману», чтобы вы могли мгновенно вернуться. Она также продает простую еду и напитки для восстановления здоровья и маны.",al={"pala services","can i bind hearthstone thunder bluff","what does pala sell","услуги палы","привязать камень возвращения громовой утес","что продает пала"}},{q="Как называется ее таверна?",a="Ее таверна называется «Кот и шаман» — заведение для постоянного потока путников Орды, проходящих через нижний уровень города.",al={"cat and the shaman","thunder bluff lower inn name","pala inn name","кот и шаман","таверна нижнего уровня громовой утес","название таверны палы"}}},fp="14,243,29.485.0,32.134.0,44.192.0,31.146.0"}
P.entries["npc:interrogator-vishas"] = {n="Дознаватель Вишас",s="Дознаватель Джеймс Вишас — мастер пыток Алого ордена, обосновавшийся в глубине Кладбища в Монастыре Алого ордена. Известный пронзительным голосом и крайней жестокостью, он находит извращенное удовольствие в том, чтобы ломать пленников и испытывать пределы смертной плоти. Мало кто выходит из его пыточных с целым рассудком или телом.",h="Дознаватель Джеймс Вишас — мастер пыток Алого ордена, обосновавшийся в глубине Кладбища в Монастыре Алого...",kw={"graveyard","interrogator vishas","james vishas","lordamere lake","nancy vishas","scarlet monastery","torture","vorrel sengutz","кладбище","дознаватель вишас","джеймс вишас","озеро лордамер","нэнси вишас","монастырь алого ордена","пытки","воррел сенгутц"},ang={["class:Priest"]="Глядя, как Вишас прикрывается фанатизмом, освящая жуткие увечья, понимаешь, как священная цель может обратиться в извращенное безумие.",["faction:Alliance"]="Герои Альянса, узнавшие о деяниях Вишаса, быстро понимают, что Алый орден больше не отличает чудовищ Плети от невинных живых путников.",["race:Undead"]="Для Отрекшихся Вишас воплощает лицемерную злобу живых фанатиков: он пытает пленную нежить из чистой злобы, заявляя, что служит Свету."},sec={{t="Скальпель Великого инквизитора",b="В темных склепах и на погостах Монастыря Алого ордена Дознаватель Вишас занимается пленными врагами ордена. Пока снаружи фанатики шагают в сияющих доспехах под знаменами чистоты, Вишас воплощает мрачную правду их похода: необузданный садизм под маской религиозной праведной ярости. Допрос для него — не просто служебная обязанность, а ценное ремесло: он упивается муками пленных Отрекшихся, захваченных воинов Плети и любых живых путников, которым не повезло быть объявленными еретиками."},{t="Жизнь тихого домашнего уюта",b="За окровавленными фартуками и криками пыточной Вишас ведет на удивление домашнюю двойную жизнь. За стенами монастыря его семья — жена Нэнси Вишас и старший родственник дедушка Вишас — мирно живет в уединенном домике на восточном берегу Озера Лордамер в Альтеракских горах. Вишас даже приносит в личную жизнь жуткие трофеи своих жертв: он снял с пленного Отрекшегося Воррела Сенгутца его дорогое обручальное кольцо и подарил его Нэнси."}},faq={{q="Где найти Дознавателя Вишаса?",a="Дознаватель Вишас находится в глубине Кладбища в Монастыре Алого ордена, в Тирисфальских лесах. Он заправляет мрачной пыточной, уставленной железными клетками и окровавленными дыбами.",al={"vishas location","where is interrogator vishas","vishas room","где вишас","где дознаватель вишас","комната вишаса"}},{q="Почему Вишас пытает пленников?",a="Алый орден оправдывает пытки пленных стремлением искоренить порчу Плети и добыть сведения, но Вишас лично наслаждается причиняемой болью. Он безмерно гордится своей жестокостью и считает пытки своим искусством.",al={"why is vishas torturing people","vishas motivation","почему вишас пытает людей","мотивы вишаса"}},{q="Кто такой Воррел Сенгутц?",a="Воррел Сенгутц — пленник, которого Вишас держит в заточении на Кладбище монастыря и жестоко пытает. Вишас несколько недель подвергал Воррела мучениям и украл его обручальное кольцо, чтобы подарить жене.",al={"vorrel sengutz prisoner","who is the prisoner in the cage","воррел сенгутц пленник","кто пленник в клетке"}},{q="Где живет семья Вишаса?",a="Его семья живет вдали от монастыря, в неприметном домике на восточном берегу озера Лордамер в Альтеракских горах. Жена Нэнси и дедушка Вишас тихо живут там, словно далекие от его злодеяний.",al={"nancy vishas location","grandpa vishas","vishas family house","где нэнси вишас","дедушка вишас","дом семьи вишаса"}},{q="Кого Вишас держит в плену?",a="Алый орден считает нежить врагами. Среди пленников Вишаса — Отрекшийся Воррел Сенгутц, которого он пытает уже несколько недель.",al={"vishas prisoners","who does vishas torture","vishas captive vorrel","пленники вишаса","кого пытает вишас","пленник воррел"}},{q="Каковы голос и повадки Вишаса?",a="Вишас известен тем, кто с ним сталкивался, скрипучим высоким голосом, кудахчущим смехом и жутким воодушевлением всякий раз, когда выпадает случай вырвать тайны у несговорчивой жертвы.",al={"vishas voice","vishas personality","голос вишаса","характер вишаса"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
P.entries["npc:islen-waterseer"] = {n="Ислен Заклинатель Воды",s="Ислен Заклинатель Воды — уважаемая шаманка-таурен, живущая у тихой рыбацкой хижины на Лестнице Прилива, с видом на восточное море Степей. Благодаря глубокой связи с духами воды она направляет посвященных в испытаниях, необходимых для единения со стихией. Начинающие шаманы всей Орды приходят к ней за мудростью, чтобы получить свой Тотем воды.",h="Ислен Заклинатель Воды — уважаемая шаманка-таурен, живущая у тихой рыбацкой хижины на Лестнице Прилива, с...",kw={"barrens","call of water","greta mosshoof","islen","shaman","tidus stair","water sapta","waterseer","степи","зов воды","грета замшелое копыто","ислен","шаман","лестница прилива","сапта воды","заклинатель воды"},ang={["class:Shaman"]="Ислен — важная наставница на вашем пути: она проведет вас через стихийные обряды, нужные, чтобы связать себя с духами воды и общаться с ними, и вы получите свой Тотем воды.",["faction:Horde"]="Расположившись на побережье Степей, Ислен служит тихой духовной опорой Орды и приветствует путников как из Оргриммара, так и из Громового Утеса.",["race:Tauren"]="Ислен воплощает традиционное почтение тауренов к дарам Матери-Земли: она выбрала одинокую жизнь у моря, чтобы оставаться созвучной тонким течениям дикой природы."},sec={{t="Отшельник Лестницы Прилива",b="Вдали от шумных перекрестков и лагерей Степей Ислен Заклинатель Воды живет на скалистом берегу, известном как Лестница Прилива. Здесь, где сухие равнины встречаются с Великим морем, присутствие духов воды ощущается остро и повсюду. Вместо громовых залов и оживленных городов Ислен предпочитает этот тихий уголок: она проводит дни, прислушиваясь к приливам и помогая шаманам, ищущим единения с текучей стихией."},{t="Хозяйка Сапты воды",b="Понимание воды требует не только изучения, но и внутренней гармонии и духовного восприятия. Ислен направляет ищущих в приготовлении Сапты воды — священного отвара, пронзающего завесу между смертными чувствами и проявлениями стихий. Ее учения напоминают шаманам, что вода так же неуступчива и глубока, как текуча и целительна, и требует огромного уважения от всех, кто надеется призвать ее помощь."},{t="Узы по всей глуши",b="Хотя Ислен ведет тихую жизнь на побережье, ее духовное влияние и связи простираются по всему Калимдору. Ее связывает крепкая многолетняя дружба с Гретой Замшелым Копытом — другой мудрой таурен, сведущей в целительских искусствах. Благодаря этим связям знания Ислен об очищающей сути воды касаются дел далеко за пределами Степей и даже приносят духовную помощь землям, пораженным глубокой порчей."}},faq={{q="Кто такая Ислен Заклинатель Воды?",a="Ислен Заклинатель Воды — мудрая шаманка-таурен, живущая на побережье Степей у Лестницы Прилива. Ее редкая глубокая связь со стихийными духами воды делает ее духовной наставницей для шаманов, отправившихся за своим Тотемом воды.",al={"islen waterseer lore","who is islen","tidus stair tauren","предания об ислен","кто такая ислен","таурен лестница прилива"}},{q="Почему шаманы отправляются к ней?",a="Шаманов Орды направляют к Ислен их наставники в Дуротаре, Оргриммаре и Громовом Утесе во время испытаний Зова Воды. Она проверяет их понимание стихии и учит готовить Сапту воды, чтобы напрямую видеть элементалей воды.",al={"why visit islen","call of water npc","shaman quest barrens coast","зачем идти к ислен","зов воды персонаж","задание шамана побережье степей"}},{q="Где находится Ислен Заклинатель Воды?",a="Ее можно найти сидящей у небольшой рыбацкой хижины на Лестнице Прилива, на восточном побережье Степей, к югу от Торгового побережья.",al={"islen location","where is islen waterseer","find islen","где ислен","где ислен заклинатель воды","найти ислен"}},{q="Что такое Сапта воды, о которой она говорит?",a="Сапта воды — особым образом сваренный духовный напиток из стихийных компонентов. Выпив его, взор шамана проникает сквозь физический план и видит скрытых духов воды, обитающих в священных источниках и приливах.",al={"water sapta meaning","what does the sapta do","значение сапты воды","что делает сапта"}},{q="Кто такая Грета Замшелое Копыто, подруга Ислен?",a="Грета Замшелое Копыто — давняя спутница-таурен и последовательница духовных искусств. Их связывает крепкая дружба: они советуются друг с другом об очищении духа и целительной природе воды.",al={"greta mosshoof connection","islen friend","грета замшелое копыто связь","подруга ислен"}},{q="Принадлежит ли Ислен к определенной фракции или племени?",a="Ислен союзница Орды и Объединенных племен тауренов под началом Кэрна Кровавого Копыта. Хотя она живет уединенно на побережье, она охотно помогает шаманам-оркам, троллям и тауренам, присланным старейшинами Орды.",al={"islen faction","is islen horde","фракция ислен","ислен из орды"}}},fp="15,354,25.454.0,27.423.0,22.406.0,23.251.0,33.258.0,33.151.0,38.240.0,37.207.0,49.206.0"}
P.entries["npc:iverron"] = {n="Иверрон",s="Иверрон — молодой ночной эльф, которого можно найти в Тенистой долине, укрытой начальной ветви Тельдрассила. Пораженный ядом все более свирепых лесных паукообразных, он своим бедственным положением служит ранним предупреждением о растущей порче в Мировом Древе.",h="Иверрон — молодой ночной эльф, которого можно найти в Тенистой долине, укрытой начальной ветви Тельдрассила.",kw={"antidote","dentaria","iverron","kaldorei","shadowglen","spider","teldrassil","venom","противоядие","дирания","иверрон","кальдораи","тенистая долина","паук","тельдрассил","яд"},ang={["class:Druid"]="Друиды, обучающиеся в Тенистой долине, видят в отравлении Иверрона признак более глубокого недуга природы, для лечения которого нужны средства, созданные прямо из растений и животных долины.",["profession:Herbalism"]="Выживание Иверрона зависит от быстрого сбора местных растений Тенистой долины, что подчеркивает важность знания трав для сохранения жизни.",["race:NightElf"]="Для юных ночных эльфов, делающих первые шаги за пределами Альдрассила, несчастье Иверрона — ранний урок того, как быстро дикие земли Тельдрассила теряют равновесие."},sec={{t="Горький укус",b="Блуждая под тихим пологом Тенистой долины, Иверрон столкнулся с паутинными пауками, гнездящимися в долине. Быстро поддавшись их ядовитому укусу, юный эльф оказался беспомощным и не смог сам вернуться в безопасное место. Его беспомощность подчеркивает внезапную агрессию существ, когда-то мирно деливших с ним поляну."},{t="Отчаянные средства",b="Спасение Иверрона зависит от быстрой смекалки его товарищей и местных целителей, которым нужны сильные лесные ингредиенты — гиацинтовые грибы, лунные лилии и сукровица паутинных пауков, — чтобы сварить противоядие. Его встреча со смертью — суровое напоминание всем молодым кальдораям Тенистой долины, что ветви Тельдрассила — далеко не безупречное убежище."}},faq={{q="Кто такой Иверрон?",a="Иверрон — молодой ночной эльф, живущий в Тенистой долине в Тельдрассиле. Во время странствий по лесу он стал жертвой ядовитых тварей, населяющих ветви, и ему потребовалась срочная помощь, чтобы выжить.",al={"iverron lore","who is iverron","iverron night elf","предания об иверроне","кто такой иверрон","иверрон ночной эльф"}},{q="Что отравило Иверрона?",a="Его укусили свирепые паутинные пауки, обитающие в зарослях Тенистой долины; изнурительный яд не излечить обычным отдыхом.",al={"why is iverron sick","what bit iverron","iverron poison","почему иверрон болен","кто укусил иверрона","яд иверрона"}},{q="Как вылечить Иверрона?",a="Его лечат отваром из местных растений Тельдрассила, включая гиацинтовые грибы и лунные лилии, смешанным с сукровицей паутинных пауков, — так получается целевое противоядие.",al={"cure iverron","iverron antidote","saving iverron","вылечить иверрона","противоядие иверрона","спасение иверрона"}},{q="Где найти Иверрона?",a="Он находится в Тенистой долине — уединенной начальной лощине в кроне Тельдрассила, где начинают обучение юные ночные эльфы.",al={"iverron location","where is iverron","find iverron","где иверрон","расположение иверрона","найти иверрона"}},{q="Кто помогает Иверрону?",a="Иверрон отправляет искателей приключений к своей подруге Дирании Серебряному Сиянию, которая собирает ингредиенты для противоядия и отправляет их ему, пока оно не утратило силу.",al={"who saves iverron","iverron friends","dentaria silverglade iverron","кто спасает иверрона","друзья иверрона","дирания серебряное сияние иверрон"}},{q="Почему пауки в Тенистой долине так враждебны?",a="Внезапная агрессия пауков Тенистой долины — часть неестественного недуга, проникающего в Тельдрассил и превращающего обычно уединенных зверей в свирепых хищников.",al={"why spiders attack","teldrassil spider corruption","почему пауки нападают","порча пауков тельдрассил"}}},fp="7,253,13.356.0,18.356.1,15.205.0,22.159.0,21.195.0,27.130.0,23.158.0,45.160.0"}
P.entries["npc:jahan-hawkwing"] = {n="Джахан Соколиное Крыло",s="Джахан Соколиное Крыло — таурен-оружейник, живущий в Перекрестке в Степях. Он снабжает путников кожаными и кольчужными доспехами, необходимыми в суровых равнинах, полных хищников.",h="Джахан Соколиное Крыло — таурен-оружейник, живущий в Перекрестке в Степях.",kw={"armorer","bundle of hides","chainmail","crossroads","jahan hawkwing","leather armor","tauren","the barrens","оружейник","связка шкур","кольчуга","перекресток","джахан соколиное крыло","кожаные доспехи","таурен","степи"},ang={["faction:Horde"]="Джахан живет на пересечении главных троп Калимдора и следит за тем, чтобы воины и разведчики Орды были защищены от неустанных набегов кентавров и местных зверей.",["race:Tauren"]="Джахан воплощает практичный, самостоятельный нрав шу'хало: он использует кожевенное ремесло и прочные материалы, чтобы защитить путников на исконных землях Степей."},sec={{t="Оружейник Перекрестка",b="Джахан Соколиное Крыло живет в оживленном центре Перекрестка и заботится о снаряжении для странников и защитников Орды. Степи — суровая местность, где прочные доспехи часто решают, выживет ли путник или падет от рук кентавров, свинобразов или диких зверей. Джахан работает вместе с местными кожевниками, принимая поставки выделанных шкур, чтобы в его лавке всегда была надежная дубленая кожа и крепкая кольчуга."}},faq={{q="Кто такой Джахан Соколиное Крыло?",a="Джахан Соколиное Крыло — таурен-торговец и оружейник, живущий в Перекрестке в Степях. Он снабжает странствующих искателей приключений и стражей Орды защитным снаряжением из кожи и кольчуги.",al={"jahan hawkwing lore","who is jahan","crossroads armor vendor","джахан соколиное крыло предания","кто такой джахан","торговец доспехами перекресток"}},{q="Какие товары он продает?",a="Джахан продает простые комплекты дубленой кожи и кольчужных доспехов: куртки, сапоги, пояса, наручи и перчатки, подходящие начинающим воинам, охотникам и разведчикам.",al={"what does jahan sell","jahan hawkwing inventory","jahan armor","что продает джахан","товары джахана соколиное крыло","доспехи джахана"}},{q="Какие задания он дает путникам?",a="Джахан зависит от местных мастеров, которые поставляют ему товары. Он просит отзывчивых путников доставлять партии сырья или готовых материалов: отправлять связки шкур местным дубильщикам и ждать готовые изделия.",al={"jahan quests","bundle of hides quest","crossroads hide delivery","задания джахана","связка шкур задание","доставка шкур перекресток"}}},fp="14,183,25.437.0,22.183.0,24.165.0,38.206.0"}
P.entries["npc:jaina-proudmoore"] = {n="Джайна Праудмур",s="Леди Джайна Праудмур — правительница Острова Терамор и самая могущественная из живых чародеек-людей. Некогда лучшая ученица Кирин-Тора в Даларане, она провела выживших жителей Лордерона через Великое море, а теперь стремится сохранить хрупкий мир между Альянсом и Новой Ордой.",h="Леди Джайна Праудмур — правительница Острова Терамор и самая могущественная из живых чародеек-людей.",kw={"antonidas","arthas","dustwallow","jaina","kirin tor","proudmoore","theramore","thrall","антонидас","артас","пылевые топи","джайна","кирин-тор","праудмур","терамор","тралл"},ang={["class:Mage"]="Джайна обучалась у самого верховного мага Антонидаса и считается самой могущественной из живых чародеек-людей, воплощением вершин тайного мастерства Даларана.",["faction:Alliance"]="Джайна обеспечивает Альянсу важный плацдарм на юге Калимдора, уравновешивая верность регентству верховного лорда Болвара в Штормграде и стремление избежать войны с соседней Ордой."},sec={{t="Бегство в Калимдор",b="Дочь верховного адмирала Даэлина Праудмура из Кул Тираса, Джайна с ранних лет проявляла выдающиеся способности к тайной магии и училась у верховного мага Антонидаса в Даларане. Во время Третьей войны она вместе с принцем Артасом Менетилом исследовала загадочную Чуму нежизни и своими глазами видела трагическое падение Лордерона. Следуя предостережениям пророка Медива, она собрала отряд выживших людей и отплыла на запад, к забытому континенту Калимдор. Там ее войско заключило беспрецедентный союз с Ордой Тралла и ночными эльфами, и вместе они встали на горе Хиджал, чтобы победить Архимонда и сокрушить вторжение Пылающего Легиона."},{t="Леди Терамора",b="После поражения Легиона Джайна основала островную цитадель Терамор у берегов Пылевых топей, создав главный оплот Альянса на юге Калимдора. Ее приверженность дипломатии подверглась предельному испытанию, когда отец прибыл, желая отомстить оркам: Джайна отказалась поддержать его войну и не вмешалась, когда войска Тралла убили Верховного адмирала, чтобы не допустить нового разрушительного конфликта в Калимдоре. Сегодня она правит Тераморем как стойкая сторонница сосуществования, тесно сотрудничает с вождем Траллом и удерживает присутствие Альянса среди растущей местной напряженности."}},faq={{q="Кто такая леди Джайна Праудмур?",a="Джайна — правительница Острова Терамор и, пожалуй, самая одаренная из живых магов-людей. Она дочь покойного верховного адмирала Даэлина Праудмура из Кул Тираса и бывшая ученица верховного мага Антонидаса в Даларане.",al={"who is jaina","jaina proudmoore lore","theramore leader","кто такая джайна","джайна праудмур предания","правитель терамора"}},{q="Почему Джайна находится в Калимдоре, а не в Восточных королевствах?",a="Перед падением Лордерона в Третьей войне пророк Медив предупредил Джайну, чтобы она вывела как можно больше людей за море в Калимдор. Ее экспедиция пережила путь, сражалась на горе Хиджал и обосновалась в портовой крепости Терамор в Пылевых топях.",al={"why did jaina leave lordaeron","jaina kalimdor","why is theramore here","почему джайна покинула лордерон","джайна калимдор","почему терамор здесь"}},{q="Каковы отношения Джайны с Ордой?",a="Джайну связывает с вождем Траллом необычная, осторожная дружба. После совместной борьбы с Пылающим Легионом на горе Хиджал оба лидера стараются сохранить мир между своими народами, несмотря на резкое сопротивление сторонников жесткой линии с обеих сторон.",al={"is jaina friendly with thrall","jaina and horde","does jaina hate orcs","дружит ли джайна с траллом","джайна и орда","ненавидит ли джайна орков"}},{q="Что произошло между Джайной и принцем Артасом Менетилом?",a="Джайна и Артас были друзьями детства, и в юности их связь переросла в роман. Они вместе расследовали чуму, распространявшуюся по Лордерону, но Джайну ужаснуло падение Артаса в жестокость, кульминацией которого стала чистка Стратхольма: она отказалась участвовать в бойне над зараженными горожанами.",al={"jaina and arthas","did jaina love arthas","джайна и артас","любила ли джайна артаса"}}},fp="16,283,18.679.0,21.631.0,29.218.0,57.265.0,44.259.0,55.332.0"}
P.entries["npc:james-halloran"] = {n="Джеймс Халлоран",s="Джеймс Халлоран — человек-кожевник из Болотины, поставляющий отличные шкуры по всем восточным землям. Он живет в Гавани Менетилов и добывает прочные ценные шкуры местных кроколисков. Он полагается на проезжих путников и близкие торговые пути, чтобы собирать сырье и доставлять готовую кожу на рынок.",h="Джеймс Халлоран — человек-кожевник из Болотины, поставляющий отличные шкуры по всем восточным землям.",kw={"crocolisk","halloran","james halloran","leatherworking","menethil harbor","tanner","wetlands","кроколиск","халлоран","джеймс халлоран","кожевничество","гавань менетилов","кожевник","болотина"},ang={["class:Hunter"]="Охотники, пробирающиеся по сырым топям, найдут общий язык с Халлораном: его заработок зависит от выслеживания и добычи агрессивных местных рептилий-хищников.",["faction:Alliance"]="Торговля Халлорана помогает поддерживать коммерческое присутствие Альянса в суровой Болотине, поставляя ценную выделанную кожу в города королевства."},sec={{t="Кожевник в топях",b="Живя в Гавани Менетилов, Джеймс Халлоран зарабатывает на болотах сразу за городом. Предприимчивый кожевник Халлоран понял, что опасные трясины дают выгодный товар — шкуры кроколисков. Превращение грубой шкуры болотных рептилий в качественную кожу требует редкого мастерства, и готовые изделия Халлорана отправляют по местным торговым путям покупателям по всему Азероту."},{t="Шкуры, подмастерья и повседневная торговля",b="Работа рядом с болотом сопряжена с постоянной опасностью. Халлоран не может сам охотиться на каждого зверя, занимаясь чанами для выделки и торговой логистикой. Он часто нанимает выносливых путников для самой тяжелой работы: снимать шкуры с молодых болотных зверей и выполнять обычные поручения по доставке между мастерской и окрестными поселениями, чтобы его оживленное кожевенное дело было всегда обеспечено."}},faq={{q="Кто такой Джеймс Халлоран?",a="Джеймс Халлоран — человек-кожевник из Гавани Менетилов в Болотине. Он специализируется на охоте на местных кроколисков и снятии с них шкур, выделывая прочные шкуры в кожаные изделия, которые вывозят по всему миру.",al={"james halloran","halloran","who is halloran","wetlands tanner","джеймс халлоран","халлоран","кто такой халлоран","кожевник болотины"}},{q="Где Джеймс Халлоран продает свою кожу?",a="Халлоран перерабатывает сырые шкуры кроколисков в тонкую кожу и отправляет ее по всему Азероту. Для сбыта товаров за морями он во многом полагается на морскую торговлю, проходящую через Гавань Менетилов.",al={"halloran leather trade","where do crocolisk skins go","halloran business","торговля кожей халлорана","куда идут шкуры кроколисков","дела халлорана"}},{q="Зачем Халлорану искатели приключений для сбора шкур молодых кроколисков?",a="Выделка и дубление кожи — долгая и трудоемкая работа. Халлоран нанимает странствующих искателей приключений, чтобы они истребляли местных болотных кроколисков и снимали с них шкуры: так у него есть постоянный запас сырья, и ему не нужно покидать мастерскую.",al={"why kill young crocolisks","young crocolisk skins quest","crocolisk hides halloran","зачем убивать молодых кроколисков","задание шкуры молодых кроколисков","шкуры кроколисков халлоран"}},{q="Как Халлоран связан с Гаванью Менетилов?",a="Гавань Менетилов — главный торговый и снабженческий центр региона. Халлоран полагается на гавань и ее морские пути, чтобы вывозить выделанные шкуры на дальние рынки и поддерживать свое кожевенное дело.",al={"halloran menethil","halloran port connection","does halloran live in menethil","халлоран гавань менетилов","халлоран связь с портом","живет ли халлоран в гавани менетилов"}},{q="Где можно найти Джеймса Халлорана?",a="Халлоран живет и работает в Гавани Менетилов, оживленном порту на западном побережье Болотины; болота с кроколисками находятся сразу за городом.",al={"halloran location","where is james halloran","find halloran","где халлоран","где джеймс халлоран","найти халлорана"}},{q="Есть ли у Халлорана подмастерье?",a="Да. Халлоран отправил подмастерье, которого считает почти сыном, в болота снимать шкуры с гигантских кроколисков, но юношу изувечили, и он потерял ногу. Пока подмастерье поправляется, Халлоран полагается на выносливых путников, собирающих шкуры, от которых зависит его дело.",al={"halloran apprentice","apprentice duties halloran","who works for halloran","подмастерье халлорана","обязанности подмастерья халлорана","кто работает на халлорана"}}},fp="14,354,23.426.0,35.394.0,22.229.0,43.205.0,68.243.0,49.210.0,34.143.0,33.260.0"}
P.entries["npc:jannok-breezesong"] = {n="Джаннок Поющий Ветерок",s="Джаннок Поющий Ветерок — ночной эльф, учитель разбойников в деревне Доланаар на Тельдрассиле. Он обучает скрытности, хитрости и владению клинками молодых кальдораев-разбойников, отправляющихся в ветви Мирового Древа.",h="Джаннок Поющий Ветерок — ночной эльф, учитель разбойников в деревне Доланаар на Тельдрассиле.",kw={"breezesong","dolanaar","erion shadewhisper","jannok","night elf","rogue trainer","teldrassil","поющий ветерок","доланаар","эрион шепот тени","джаннок","ночной эльф","учитель разбойников","тельдрассил"},ang={["class:Rogue"]="Для молодых ночных эльфов-разбойников, начинающих путь на Тельдрассиле, Джаннок — главный наставник в Доланааре, прежде чем они отправятся в столицу.",["race:NightElf"]="Хотя культура кальдораи часто делает упор на часовых и друидизм, такие учителя, как Джаннок, готовят тех, кто предпочитает скрытность, яды и кинжалы."},sec={{t="Проводник в тенях",b="Джаннок Поющий Ветерок, которого можно найти отдыхающим под ветвями Доланаара, — главный наставник начинающих ночных эльфов-разбойников. В отличие от официальных часовых или уединенных друидов Тельдрассила, Джаннок наставляет тех, кто действует тихо, на окраинах общества: учит их скрываться в тенях, бить со спины и выживать незамеченными среди ветвей. Когда разбойник проходит начальные уроки в Доланааре, Джаннок направляет его к более опытным мастерам в столице, Дарнассе."}},faq={{q="Кто такой Джаннок Поющий Ветерок?",a="Джаннок Поющий Ветерок — ночной эльф, учитель разбойников в Доланааре на Тельдрассиле. Он обучает молодых кальдораев основным умениям и приемам разбойника.",al={"who is jannok","jannok breezesong role","dolanaar rogue trainer","кто такой джаннок","роль джаннока поющий ветерок","учитель разбойников доланаар"}},{q="Куда Джаннок Поющий Ветерок отправляет разбойников, достигших нового уровня?",a="Когда разбойник завершает начальное обучение в Доланааре, Джаннок направляет его в Дарнасс для дальнейшего обучения у Эриона Шепота Тени, старшего учителя разбойников в Анклаве Кенария.",al={"jannok quest","erion shadewhisper quest","dolanaar rogue next step","задание джаннока","задание эриона шепот тени","доланаар разбойник следующий шаг"}},{q="Где найти Джаннока в Доланааре?",a="Джаннок находится в Доланааре, главном поселении Тельдрассила за пределами Тенистой долины, среди павильонов учителей города.",al={"jannok location","where is jannok","find jannok breezesong","где джаннок","где найти джаннока","джаннок поющий ветерок"}}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jasper-fel"] = {n="Джаспер Скверн",s="Джаспер Скверн — неприметный поставщик, работающий в штаб-квартире ШРУ в Старом городе Штормграда. Он снабжает агентов кинжалами и разными флаконами, зорко наблюдает за посетителями и предупреждает их следить за языком. Его тихая торговля за закрытыми дверями поддерживает тайное крыло королевства.",h="Джаспер Скверн — неприметный поставщик, работающий в штаб-квартире ШРУ в Старом городе Штормграда.",kw={"daggers","jasper fel","morbent fel","old town","rogue supplies","si:7","stormwind","vials","кинжалы","джаспер скверн","морбент скверн","старый город","припасы разбойника","шру","штормград","флаконы"},ang={["class:Rogue"]="Джаспер Скверн поставляет необходимые флаконы и запасные клинки тайным агентам, практикующим свое ремесло в Штормграде."},sec={{t="Припасы для теней",b="Джаспер Скверн, обосновавшийся в казармах ШРУ в Старом городе, обслуживает очень особую клиентуру. Вместо обычного оружия для городской стражи он поставляет необходимые орудия ремесла: простые кинжалы и тонкие флаконы для варки и нанесения ядов. Скверн подчиняется строгой дисциплине разведывательного управления Матиаса Шоу и резко советует каждому подошедшему следить за речью. В твердыне, посвященной шпионажу и скрытой смертоносности, праздная болтовня — легкий путь к ранней кончине."}},faq={{q="Где найти Джаспера Скверна?",a="Джаспер Скверн находится в штаб-квартире ШРУ, в восточной части Старого города в Штормграде.",al={"jasper fel location","where is jasper fel","jasper fel stormwind","где джаспер скверн","джаспер скверн местоположение","джаспер скверн штормград"}},{q="Что продает Джаспер Скверн?",a="Он поставляет простые кинжалы и пустые флаконы разных видов, поэтому он полезен агентам, запасающимся компонентами для ядов.",al={"jasper fel vendor","what does fel sell","jasper fel wares","торговец джаспер скверн","что продает скверн","товары джаспера скверна"}},{q="Родственник ли Джаспер Скверн Морбенту Скверну?",a="У них одна фамилия, что породило догадки о родстве с некромантом Морбентом Скверном из Сумеречного леса, но сам Джаспер молчит о личных делах.",al={"jasper fel morbent fel","is jasper fel related to morbent","fel family duskwood","джаспер скверн морбент скверн","родственник ли джаспер морбенту","семья скверн сумеречный лес"}},{q="Почему Джаспер Скверн предупреждает говорить тихо?",a="Он работает прямо в ШРУ, в сердце шпионского аппарата Штормграда. Болтовня в организации, полной убийц и шпионов, считается опасной, и Скверн следит за тем, чтобы посетители вели себя в штаб-квартире с должной осторожностью.",al={"why speak quietly","jasper fel warning","wrong word throat cut","почему говорить тихо","предупреждение джаспера скверна","неверное слово перерезанное горло"}}},fp="10,297,24.536.0,28.115.0,26.134.0,37.178.0,49.240.0"}
P.entries["npc:je-neu-sancrea"] = {n="Дже'неу Санкри",s="Дже'неу Санкри — тролль из племени Черного Копья и один из Служителей Земли, находящийся в Форте Зорам'гар на побережье Ясеневого леса. Почувствовав темные возмущения глубоко под береговой линией, он направляет героев Орды расследовать порчу, распространяющуюся в древнем затопленном храме Непроглядной Пучины.",h="Дже'неу Санкри — тролль из племени Черного Копья и один из Служителей Земли, находящийся в Форте Зорам'гар на...",kw={"aku'mai","blackfathom deeps","earthen ring","je'neu sancrea","jeneu","twilight's hammer","zoram strand","zoram'gar outpost","аку'май","непроглядная пучина","служители земли","дже'неу санкри","дженеу","сумеречный молот","зорамское взморье","форт зорам'гар"},ang={["class:Shaman"]="Как видный тролль из племени Черного Копья среди Служителей Земли, Дже'неу воплощает шаманский долг — усмирять оскверненных элементалей и восстанавливать равновесие в водах Калимдора.",["faction:Horde"]="Дже'неу — главный для Орды персонаж, выдающий задания, и проводник по преданиям при входе в глубины Непроглядной Пучины из Ясеневого леса.",["race:Troll"]="Дже'неу показывает, как тролли Черного Копья приняли духовные пути Служителей Земли вместе со своими союзниками — таурен и орков."},sec={{t="Шаман на взморье",b="Пока большинство Служителей Земли заботятся о гармонии стихий по всему Калимдору, Дже'неу Санкри следит за уединенным и опасным Зорамским взморьем. Из Форта Зорам'гар он наблюдает за темными толчками и неестественными приливами возле разрушенного храма Непроглядной Пучины. Хотя он связан шаманскими обязанностями своего круга, его сильная преданность племени Черного Копья и Орде Тралла заставляет его работать только с героями Орды."},{t="Тени Пучины",b="Дже'неу стремится выяснить истинную причину расползающейся по побережью порчи. Через отважных искателей приключений он собирает оскверненные сапфировые сердцевины, изучает мерзкие останки элементалей воды, таких как барон Акванис, и раскрывает коварное влияние культа Сумеречного Молота. Темные ритуалы под волнами угрожают не только равновесию местных стихий, но и предвещают мрачное возвращение сил, служащих Древним богам."}},faq={{q="Кто такой Дже'неу Санкри?",a="Дже'неу Санкри — шаман-тролль из племени Черного Копья, связанный со Служителями Земли. Он находится в Форте Зорам'гар на побережье Ясеневого леса, где следит за растущей порчей, исходящей из Непроглядной Пучины.",al={"who is jeneu","jeneu sancrea lore","what is jeneu","кто такой дженеу","дже'неу санкри предыстория","что за дженеу"}},{q="Почему Дже'неу имеет дело только с героями Орды, если он из Служителей Земли?",a="Хотя Служители Земли как организация стремятся к равновесию стихий, а не к войне фракций, личные связи Дже'неу прочно привязаны к племени Черного Копья и Орде. Поскольку он живет в передовом военном форпосте Орды в Ясеневом лесу, путников из Альянса он не приветствует.",al={"why horde only","can alliance talk to jeneu","is jeneu neutral","почему только орда","может ли альянс говорить с дженеу","нейтрален ли дженеу"}},{q="Что Дже'неу расследует в Непроглядной Пучине?",a="Дже'неу расследует неестественное волнение стихий и темную магию, поднимающиеся из Непроглядной Пучины. Он поручает героям добыть оскверненные водные сердцевины, перебить культистов Сумеречного Молота и подтвердить слухи, что древняя гидра Аку'май служит древним злобным повелителям под морем.",al={"jeneu quest goals","what does jeneu want","why send players to bfd","цели заданий дженеу","чего хочет дженеу","зачем отправлять игроков в непроглядную пучину"}},{q="Где находится Дже'неу Санкри?",a="Дже'неу находится в Форте Зорам'гар — укрепленном поселении Орды на дальнем северо-западном побережье Ясеневого леса, прямо на Зорамском взморье к югу от Непроглядной Пучины.",al={"where is jeneu","jeneu sancrea location","find jeneu","где дженеу","дже'неу санкри местонахождение","найти дженеу"}},{q="Что такое Служители Земли?",a="Служители Земли — древний круг шаманов, посвятивший себя пониманию и умиротворению духов стихий мира. Они вмешиваются всякий раз, когда темные силы или хаотические существа нарушают естественную гармонию стихий.",al={"earthen ring lore","what is the earthen ring","shaman organization","служители земли предыстория","что такое служители земли","организация шаманов"}},{q="Чем угрожает Сумеречный Молот в Пучине?",a="Культ Сумеречного Молота проник в Непроглядную Пучину, чтобы почитать чудовище Аку'май и проводить ритуалы во славу Древних богов. Дже'неу поручает героям Орды убить их главарей, чтобы остановить их темное дело.",al={"twilights hammer bfd","twilight cult ashenvale","who are the cultists in bfd","сумеречный молот непроглядная пучина","сумеречный культ ясеневый лес","кто такие культисты в непроглядной пучине"}}},fp="14,300,22.452.0,19.449.1,22.215.0,71.296.0,50.299.0,32.174.0,25.212.0,57.225.0"}
P.entries["npc:jen-shan"] = {n="Джен'шан",s="Джен'шан — тролльша джунглей из племени Черного Копья, наставница охотников в Долине Испытаний в Дуротаре. Она направляет начинающих орков и троллей-стрелков, делающих первые шаги в дикие земли Орды. Молодых охотников посылают к ней, чтобы освоить основы выслеживания, дальнего боя и выживания.",h="Джен'шан — тролльша джунглей из племени Черного Копья, наставница охотников в Долине Испытаний в Дуротаре.",kw={"darkspear","durotar","etched parchment","etched tablet","hunter trainer","jen'shan","jenshan","troll","valley of trials","черное копье","дуротар","пергамент с письменами","каменная табличка","наставник охотников","джен'шан","дженшан","тролль","долина испытаний"},ang={["class:Hunter"]="Для молодых охотников-орков и троллей Джен'шан — самая первая наставница, которую вы встречаете: она учит основам дальнего боя, прежде чем вы покинете красные каньоны Логова.",["race:Troll"]="Джен'шан воплощает известное мастерство племени Черного Копья в выслеживании и разведке, благодаря которому молодые тролли сохраняют родовые охотничьи традиции в новом доме на другом континенте."},sec={{t="Наставница Красных песков",b="Среди обветренных лагерей Долины Испытаний Джен'шан служит главной наставницей охотников для новобранцев, доказывающих свою ценность Орде. Молодые орки и тролли Черного Копья приходят с надписанными табличками и пергаментами, которые направляют их прямо к ней. Своим острым глазом, закаленным годами в диких землях, она передает основы стрельбы из лука, меткости и выживания, чтобы ни один новичок не стал добычей скорпидов и вепрей, бродящих по дну каньона."}},faq={{q="Кто такая Джен'шан?",a="Джен'шан — тролльша джунглей из племени Черного Копья, наставница охотников в Долине Испытаний в Дуротаре. Она обучает начинающих охотников Орды основам знаний о диких землях, выслеживанию и дальнобойному оружию.",al={"jenshan lore","who is jenshan","valley hunter trainer","дженшан предыстория","кто такая дженшан","наставник охотников в долине"}},{q="Какие задания связаны с Джен'шан?",a="Начинающих охотников направляют к ней вводные учебные задания. Молодые орки-охотники приходят к ней, сдав Каменную табличку, а молодые тролли-охотники ищут ее с Пергаментом с письменами.",al={"jenshan quests","etched tablet jenshan","etched parchment jenshan","задания дженшан","каменная табличка дженшан","пергамент с письменами дженшан"}},{q="Почему тролльша обучает охотников на орочьем испытательном полигоне?",a="Долина Испытаний служит общим местом испытаний и для орков-новобранцев, и для изгнанных троллей Черного Копья, делящих Дуротар. Как мастера-разведчики и следопыты, тролли вроде Джен'шан играют важную роль в подготовке новых воинов и охотников обеих рас к службе Орде.",al={"why is a troll in valley of trials","troll trainer in durotar","почему тролль в долине испытаний","тролль-наставник в дуротаре"}}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jennea-cannon"] = {n="Джинния Пушка",s="Джинния Пушка — уважаемая наставница магов, человек, живущая в Святилище волшебника в Квартале магов Штормграда. Она руководит обучением начинающих чародеев, ведя их через основы наук и расследуя возмущения в потоках местной тайной энергии. Своими поручениями она проверяет, хватает ли ученикам дисциплины, чтобы управлять магией и не быть поглощенными ею.",h="Джинния Пушка — уважаемая наставница магов, человек, живущая в Святилище волшебника в Квартале магов...",kw={"andromath","blue recluse","jennea cannon","mage quarter","mage trainer","mirror lake","stormwind","wizard's sanctum","андромат","синий отшельник","джинния пушка","квартал магов","наставник магов","зеркальное озеро","штормград","святилище волшебника"},ang={["class:Mage"]="Джинния — важная наставница для магов Альянса на раннем этапе: она направляет ваши первые полевые изыскания и помогает вам изготовить официальные одеяния и посох волшебника.",["faction:Alliance"]="Работая в сердце Квартала магов Штормграда, Джинния следит за тем, чтобы новые чародеи королевства были дисциплинированными и способными безопасно служить Альянсу."},sec={{t="Проводница в Святилище",b="На вершине винтовой дорожки Святилища волшебника Джинния Пушка — одна из главных наставниц тайных практиков, прибывающих в Штормград. Она не просто вбивает заклинания в учеников, а делает упор на осторожность и самообладание. Тем, кто не владеет магией и проходит через башню, она дает суровое предостережение: неукрощенная магия сжигает неподготовленных — истину, которую начинающие заклинатели быстро усваивают под ее руководством."},{t="Полевая работа и основы",b="Джинния считает, что магическую теорию нужно проверять наблюдением в реальном мире. Она часто отправляет многообещающих учеников за городские стены — осмотреть такие места, как Зеркальное озеро в Элвиннском лесу, чтобы понять, как природные источники воды взаимодействуют с тайным резонансом. По мере продвижения учеников она проверяет их решимость, посылая расследовать беспорядки в «Синем отшельнике» или собирать нестабильные реагенты для создания их первых настоящих волшебных орудий."},{t="Связи с великими мастерами",b="Пока Джинния занимается начальным обучением и местными делами, она знает, когда ученик перерос ее программу. Когда посвященный показывает истинный потенциал, она направляет его выше по иерархии Святилища — к Верховному колдуну Андромату или даже за границы королевства, к уединенным практикам вроде Табеты в глубине Пылевых топей."}},faq={{q="Кто такая Джинния Пушка?",a="Это наставница магов, человек, находящаяся в Святилище волшебника в Квартале магов Штормграда; она обучает новых магов и руководит ранними магическими исследованиями.",al={"jennea cannon","who is jennea","stormwind mage trainer","джинния пушка","кто такая джинния","наставник магов штормграда"}},{q="Где найти Джиннию Пушка?",a="Она находится в Святилище волшебника — спиральной тайной башне в центре Квартала магов в Штормграде.",al={"jennea cannon location","where is jennea","find jennea","джинния пушка местонахождение","где джинния","найти джиннию"}},{q="Какие задания дает Джинния Пушка?",a="Она дает классовые задания магам Альянса: исследовать Зеркальное озеро в Элвиннском лесу, выяснить странные происшествия в таверне «Синий отшельник» и собрать материалы для создания снаряжения начинающего мага.",al={"jennea quests","jennea cannon questline","задания джиннии","цепочка заданий джиннии пушка"}},{q="Почему она отправляет магов к Зеркальному озеру?",a="Она поручает ученикам взять образец воды из Зеркального озера под водопадами Элвинна, чтобы научить их воспринимать тонкие окружающие магические потоки и взаимодействовать с ними.",al={"why mirror lake","mirror lake quest jennea","почему зеркальное озеро","задание зеркальное озеро джинния"}},{q="Общается ли Джинния Пушка с классами, не являющимися магами?",a="Не маги могут поговорить с ней, но она лишь строго посоветует быть осторожными с магией, предупредив, что она обжигает тех, кто не имеет должной подготовки.",al={"can non mages talk to jennea","jennea for other classes","могут ли не маги говорить с джиннией","джинния для других классов"}},{q="Кому подчиняется Джинния Пушка?",a="Она служит в иерархии Святилища волшебника и наставляет учеников, пока они не будут готовы учиться у старших фигур, таких как Верховный колдун Андромат.",al={"jennea superior","wizards sanctum leaders","начальник джиннии","руководство святилища волшебника"}}},fp="13,395,22.415.0,24.475.0,23.342.0,21.174.0,31.132.0,37.210.0,39.175.0,50.162.0,33.156.0"}
P.entries["npc:jergosh-the-invoker"] = {n="Жергош Призыватель Духов",s="Жергош Призыватель Духов — вероломный орк-чернокнижник, скрывающийся в глубине Огненной пропасти под Оргриммаром. Как высокопоставленный предводитель культистов Пламенеющего Клинка, он практикует демонические искусства прямо под носом у Вождя и плетет заговор против Орды.",h="Жергош Призыватель Духов — вероломный орк-чернокнижник, скрывающийся в глубине Огненной пропасти под...",ang={["faction:Horde"]="Ячейка Совета Теней, процветающая под тронным залом вождя, — недопустимая угроза безопасности, которую Орда не может позволить себе игнорировать.",["race:Orc"]="Жергош воплощает остающийся яд старой Орды — соблазн демонической крови и колдовства, который Тралл стремится изгнать из орочьей культуры."},sec={{t="Культ под городом",b="Пока Тралл неустанно ведет орков путем чести и шаманизма, Жергош отверг эти идеалы ради грубой демонической силы. Скрываясь в подземном лабиринте Огненной пропасти под Оргриммаром, он собрал последователей в Пламенеющий Клинок — коварную секту, связанную с остатками Совета Теней. Действуя во тьме прямо под столицей Орды, Жергош стремится уничтожить все, за что выступает новая Орда."},{t="Демонические замыслы",b="Jergosh's presence in the chasm is far from aimless wandering. His dark rituals and dangerous schemes eventually grew bold enough to attract the direct scrutiny of Thrall himself. Jergosh represents an existential infection within Durotar, reminding the Horde of the dark pacts they fought so desperately to leave behind."}},faq={{q="Кто такой Жергош Призыватель Духов?",a="Жергош Призыватель Духов — могущественный орк-чернокнижник и предводитель культистов Пламенеющего Клинка, действующих в Огненной пропасти. Вместо того чтобы следовать благородным путем Тралла, он предпочел демоническое колдовство.",al={"who is jergosh","jergosh lore","jergosh ragefire","кто такой жергош","жергош предыстория","жергош огненная пропасть"}},{q="Почему Жергош прячется в Огненной пропасти?",a="Огненная пропасть дает Пламенеющему Клинку уединенную сеть огненных пещер прямо под Оргриммаром. Оттуда Жергош и его культисты могут практиковать запретную темную магию и строить козни против Орды незамеченными.",al={"why is jergosh under orgrimmar","jergosh location lore","почему жергош под оргриммаром","местонахождение жергоша"}},{q="К какой фракции принадлежит Жергош?",a="Жергош — предводитель Пламенеющего Клинка, культа, связанного с Советом Теней и преданного служению демоническим силам, таким как Пылающий Легион.",al={"jergosh faction","is jergosh shadow council","searing blade leader","фракция жергоша","жергош совет теней","предводитель пламенеющего клинка"}},{q="Знает ли Тралл, что Жергош находится под Оргриммаром?",a="Да. Замыслы Жергоша стали настолько опасны, что слухи дошли до Тралла, и Вождь отправил доверенных искателей приключений в пропасть, чтобы уничтожить угрозу культистов.",al={"thrall jergosh","does thrall know about ragefire","тралл жергош","знает ли тралл об огненной пропасти"}},{q="Why does Jergosh practice fel magic instead of shamanism?",a="Jergosh willingly turned his back on the spiritual resurgence of his people, rejecting shamanistic harmony to chase the intoxicating power promised by the Burning Legion and dark arts.",al={"why warlock","jergosh fel magic"}}},fp="19,250,23.465.0,17.321.1,27.205.0,40.224.0,36.147.0,46.171.0,57.184.0"}
P.entries["npc:jern-hornhelm"] = {n="Джерн Шлеморог",s="Джерн Шлеморог — дворф-шахтер из Лиги исследователей, находящийся в городке Телсамар. Он обеспечивает важнейшее снабжение и связь между поселением, Стальгорном и местом археологических раскопок в глубине Лок Модана. Приключенцы часто помогают ему доставлять по региону горное снаряжение и отчеты о ходе работ.",h="Джерн Шлеморог — дворф-шахтер из Лиги исследователей, находящийся в городке Телсамар.",kw={"blasting powder","excavation","explorers' league","ironband","jern hornhelm","loch modan","miner","thelsamar","взрывчатый порошок","раскопки","лига исследователей","сталекрут","джерн шлеморог","лок модан","шахтер","телсамар"},ang={["faction:Alliance"]="Путники из Альянса, проходящие через Лок Модан, находят в Джерне важного связного для защиты региона и поддержания инфраструктуры дворфов.",["profession:Mining"]="Шахтеры оценят опыт Джерна в ремесле и его практическое понимание подземного снабжения, взрывных работ и перевозки ресурсов.",["race:Dwarf"]="Для дворфов помощь Джерну напрямую продвигает священное дело — раскрытие древнего наследия Титанов, погребенного глубоко в горах."},sec={{t="Снабжение в Телсамаре",b="Джерн Шлеморог находится в простом городке Телсамар и играет ключевую роль в снабжении дворфов по всему Лок Модану. Пока ученые дворфов и полевые группы отправляются в глушь, чтобы раскрыть тайны прошлого своих предков, бесперебойные поставки остаются крайне важными. Джерн следит за тем, чтобы необходимые припасы, инструменты и вести благополучно доходили до действующих мест раскопок."},{t="На службе Лиги исследователей",b="Как член Лиги исследователей, Джерн служит связующим звеном между полевыми археологами и руководством Лиги в Зале Исследователей в Стальгорне. Такие места, как Раскопки Сталекрута, во многом зависят от взрывчатого порошка, снаряжения и регулярных донесений, чтобы работа не прекращалась. Джерн нанимает надежных путников, чтобы они проходили по дорогам, кишащим троггами, и поддерживали раскопки в рабочем состоянии."}},faq={{q="Кто такой Джерн Шлеморог?",a="Джерн Шлеморог — дворф-шахтер и координатор снабжения, живущий в Телсамаре в Лок Модане. Он действует от имени Лиги исследователей, чтобы местные раскопки шли без помех.",al={"who is jern","jern hornhelm identity","thelsamar dwarf jern","кто такой джерн","джерн шлеморог кто он","дворф джерн из телсамара"}},{q="Где найти Джерна Шлеморога?",a="Его можно найти на открытом воздухе в городке Телсамар, расположенном в центре Лок Модана у главной дороги.",al={"jern hornhelm location","where is jern","jern hornhelm map","джерн шлеморог местоположение","где джерн","джерн шлеморог карта"}},{q="К какой фракции принадлежит Джерн Шлеморог?",a="Джерн связан с Альянсом и представляет Лигу исследователей дворфов, руководя перемещением людей и горного снаряжения.",al={"jern hornhelm faction","who does jern work for","is jern explorers league","фракция джерна шлеморога","на кого работает джерн","джерн из лиги исследователей"}},{q="Зачем Джерну нужно отправлять взрывчатый порошок на раскопки?",a="Археологические раскопки в горной местности требуют управляемых взрывов, чтобы пробиться сквозь упрямую породу. Джерн организует доставку особого взрывчатого порошка на место раскопок Геолога Сталекрута, чтобы отряд мог безопасно добраться до реликвий Титанов и древних каменных залов.",al={"powder to ironband lore","why excavation needs powder","blasting powder loch modan","порошок для сталекрута","зачем раскопкам порошок","взрывчатый порошок лок модан"}},{q="Как Джерн Шлеморог связан со Стальгорном?",a="Джерн — важное связующее звено между удаленными раскопками в Лок Модане и высшим руководством Лиги исследователей в Зале Исследователей в Стальгорне; он часто отправляет в столицу отчеты о ходе полевых работ.",al={"jern hornhelm ironforge","report to ironforge jern","джерн шлеморог стальгорн","отчет в стальгорн джерн"}},{q="С какими проблемами сталкиваются места раскопок в Лок Модане?",a="Внезапное появление агрессивных троггов, выбравшихся из-под земли, серьезно угрожает раскопкам и перекрыло торговые пути. Из-за этого регулярные поставки опасны без вооруженных приключенцев, сопровождающих грузы.",al={"ironband excavation problems","loch modan dig dangers","why jern needs help","проблемы раскопок сталекрута","опасности раскопок лок модан","зачем джерну помощь"}}},fp="13,350,22.390.0,29.391.0,21.187.0,31.113.0,42.148.0,58.279.0,48.234.0,53.223.0"}
P.entries["npc:jitters"] = {n="Трясунчик",s="Трясунчик — дрожащий, замкнутый человек, прячущийся среди руин Вороньего Холма на западе Сумеречного леса. Одолеваемый постоянной паранойей и страхом, он живет один на опасной западной окраине Сумеречного леса, полагаясь на помощь проходящих приключенцев и наблюдая за надвигающимися тенями.",h="Трясунчик — дрожащий, замкнутый человек, прячущийся среди руин Вороньего Холма на западе Сумеречного леса.",kw={"clerk daltry","dark riders","duskwood","jitters","raven hill","roland's doom","scythe of elune","sven yorgen","worgen","клерк далтри","темные всадники","сумеречный лес","трясунчик","вороний холм","погибель роланда","коса элуны","свен йорген","воргены"},ang={["class:Rogue"]="У Трясунчика быстрые инстинкты, помогающие избегать опасности, но они не уберегли его от ужаса и одиночества в Сумеречном лесу.",["faction:Alliance"]="Трясунчик олицетворяет человеческое лицо трагедии Сумеречного леса: он живет в страхе, пока Ночной Дозор пытается защитить его жителей."},sec={{t="Преследуемый отшельник",b="Трясунчик дрожит среди полуразрушенных домов Вороньего Холма и живет в постоянном ужасе перед хищниками, бродящими по западным тропам Сумеречного леса. Он полагается на проходящих приключенцев, отчаянно нуждаясь в еде и лихорадочно следя за надвигающимися тенями. Свое прозвище он давно получил за пугливые повадки и поразительную реакцию — умение отпрыгнуть от внезапной опасности, но его безумная паранойя порождена личной встречей с жуткими ужасами."},{t="Пробуждение в Погибели Роланда",b="Трясунчик первоначально был связан с Братством Справедливости, когда оно перебралось в Сумеречный лес. Копая в шахте, известной как Погибель Роланда, он обнаружил Косу Элуны, торчавшую из скалы. Артефакт выпустил в лес свирепых кровожадных воргенов. Трясунчик в ужасе смотрел, как его товарищей рвут на части, и едва спасся от резни живым."},{t="Бегство и усадьба",b="Бежав из шахты, Трясунчик скрылся в Темнолесье, купил у Клерка Далтри чистую книгу и, прячась в таверне «Алый ворон», лихорадочно записывал события этого кошмара. В панике он укрылся в амбаре на Усадьбе Йоргена. Там он видел, как Темные всадники в черных плащах убивают семью Свена Йоргена в поисках Косы. Боясь, что его обвинят или найдут, Трясунчик закопал страницы дневника в землю и бежал в Вороний Холм, преследуемый мучительной виной и неотступным страхом."}},faq={{q="Кто такой Трясунчик?",a="Трясунчик — напуганный человек, живущий в руинах Вороньего Холма. Он голоден, одинок и преследуем пережитым в Сумеречном лесу.",al={"who is this guy","jitters lore","jitters background","кто этот парень","трясунчик предыстория","трясунчик история"}},{q="Почему его зовут Трясунчик?",a="Прозвище возникло из-за его осторожной натуры, а именно из-за инстинктивной привычки уворачиваться от ударов и отпрыгивать от внезапных ловушек. Долгое одиночество и сильный страх в Сумеречном лесу лишь усилили его нервозность.",al={"why jitters","where did his name come from","jitters name origin","почему трясунчик","откуда его имя","происхождение имени трясунчик"}},{q="Какую опасность представляют воргены в Сумеречном лесу?",a="Воргены рыщут по лесам и дорогам Сумеречного леса, угрожая путникам и уединенным поселениям.",al={"worgen threat duskwood","beasts near jitters","duskwood worgen danger","угроза ворген сумеречный лес","звери возле трясунчика","опасность ворген сумеречный лес"}},{q="Что случилось с семьей Свена Йоргена?",a="Семью Свена Йоргена убили на их ферме, и он полон решимости выяснить, кто в этом виновен.",al={"sven farm massacre","who killed sven family","yorgen farmstead murder","резня на ферме свена","кто убил семью свена","убийство усадьба йоргена"}},{q="Как Трясунчик может помочь расследованию Свена Йоргена?",a="Дневник Трясунчика описывает его пережитое в Сумеречном лесу и может помочь Свену выяснить, что случилось с его семьей.",al={"jitters and sven investigation","how can jitters help sven","jitters account of duskwood","трясунчик и свен расследование","как трясунчик поможет свену","рассказ трясунчика о сумеречном лесе"}},{q="Что за дневник у Трясунчика?",a="Его дневник описывает пережитое в Сумеречном лесу и является частью расследования, связанного с Вороньим Холмом и семьей Свена Йоргена.",al={"jitters diary","jitters completed journal","daltry book","дневник трясунчика","законченный дневник трясунчика","книга далтри"}}},fp="7,282,16.468.0,30.388.1,24.493.1,15.132.1,25.244.0,43.88.1,38.108.1,49.111.1,25.132.1"}
P.entries["npc:jocaste"] = {n="Иокаста",s="Иокаста — ночная эльфийка, наставница охотников, живущая в зеленом Анклаве Кенария в Дарнассе. Работая вместе с Кругом Кенария, она обучает молодых ночных эльфов — стрелков и укротителей зверей, приходящих из дебрей Тельдрассила.",h="Иокаста — ночная эльфийка, наставница охотников, живущая в зеленом Анклаве Кенария в Дарнассе.",kw={"cenarion enclave","darnassus","hunter trainer","jocaste","night elf hunter","teldrassil","анклав кенария","дарнасс","наставник охотников","иокаста","ночной эльф охотник","тельдрассил"},ang={["class:Hunter"]="Для охотников-ночных эльфов, впервые пришедших в Дарнасс, Иокаста — ключевой учитель: она совершенствует боевые приемы и помогает укрепить связь с животными-спутниками.",["race:NightElf"]="Иокаста, живущая в Анклаве Кенария, воплощает тесную гармонию между странствующими ночными эльфами, дикими зверями Тельдрассила и учением Круга Кенария."},sec={{t="Наставница в Анклаве",b="Иокаста находится среди тихих рощ Анклава Кенария в Дарнассе и служит наставницей ночных эльфов-охотников. Когда начинающие следопыты заканчивают первоначальное обучение в Тенистой долине и отправляются в столицу, Иокаста помогает им стать опытными знатоками выживания. Она учит искусству стрельбы, выживанию в дикой природе и священной связи между охотником и дикими зверями Калимдора."}},faq={{q="Кто такая Иокаста?",a="Иокаста — ночная эльфийка, наставница охотников в Анклаве Кенария в столице Дарнасс; она обучает и направляет приверженцев охоты.",al={"jocaste lore","who is jocaste","jocaste darnassus","иокаста предыстория","кто такая иокаста","иокаста дарнасс"}},{q="Где найти Иокасту?",a="Ее можно найти среди деревьев и шатров Анклава Кенария, в северо-западном районе Дарнасса на ветвях Тельдрассила.",al={"jocaste location","where is jocaste","jocaste spot","иокаста местоположение","где иокаста","иокаста где стоит"}},{q="Какую роль она играет для молодых охотников?",a="Охотники, направленные в Дарнасс, ищут ее, чтобы совершенствовать мастерство, выполняя такие задания, как «Путь охотника», и научиться правильно приручать и обучать диких зверей.",al={"jocaste quests","the hunter's path jocaste","training the beast","задания иокасты","путь охотника иокаста","обучение зверя"}},{q="Связана ли Иокаста с Кругом Кенария?",a="Да. Хотя она обучает охотников, а не друидов, она действует в Анклаве Кенария и открыто приветствует приходящих охотников в присутствии Круга Кенария.",al={"is jocaste cenarion circle","jocaste faction","иокаста круг кенария","фракция иокасты"}}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:john-j-keeshan"] = {n="Джон Дж. Кеешан",ang={["class:Warrior"]="Для воинов Кеешан — мрачное свидетельство несгибаемой воинской выносливости: он пережил сотни схваток на передовой в трех войнах, изменивших мир.",["faction:Alliance"]="Кеешан олицетворяет тяжелую человеческую цену нескончаемой войны Альянса против орков клана Черной горы: на службе Штормграду он принес в жертву молодость, семью и душевный покой."},sec={{t="Жизнь, прошедшая на войне",b="Немногие из живущих солдат повидали столько сражений, сколько Джон Дж. Кеешан. Ветеран Первой, Второй и Третьей войн, Кеешан отслужил поразительные 248 сроков службы подряд под командованием полковника Тротемана в роте «Браво». Десятилетия непрерывного насилия дорого обошлись ему лично: его жена Нефрит была убита орками клана Черной горы во время боев, и у него остались лишь ее кулон и суровые инстинкты человека, выжившего на поле боя. Когда бои вспыхнули в Красногорье, Кеешан по-прежнему был в самой гуще событий, неся шрамы и воспоминания целой жизни, проведенной под ружьем."},{t="Плен в Скале Ренда",b="Когда клан Черной горы двинулся на север из Пылающих степей в Красногорье, Кеешан был среди защитников, сражавшихся за Крепость Каменной Стражи. Не выдержав натиска орков, он был взят живым, а не убит на поле боя. Захватчики из клана Черной горы утащили пленника в недра Скалы Ренда, и ветеран томился за линией врага, пока отряды спасения Альянса не пробились к нему, чтобы освободить его."}},faq={{q="Кто такой Джон Дж. Кеешан?",a="Джон Дж. Кеешан — ветеран армии Альянса, прошедший Первую, Вторую и Третью войны в составе роты «Браво». Старые товарищи зовут его Джонни. Это исключительно закаленный боец, переживший сотни сроков службы.",al={"keeshan lore","who is keeshan","corporal keeshan","кеешан предания","кто такой кеешан","капрал кеешан"}},{q="Почему Кеешан в плену в Скале Ренда?",a="Во время битвы с кланом Черной горы у Крепости Каменной Стражи Кеешана одолели, орки взяли его живым и утащили в свой лагерь в пещерах Скалы Ренда.",al={"why is keeshan captured","render's rock prisoner","how did keeshan get captured","почему кеешан в плену","пленник скалы ренда","как кеешан попал в плен"}},{q="Что случилось с его женой?",a="Жену Кеешана, Нефрит, убили орки клана Черной горы во время войн. После ее смерти Кеешан носил ее кулон как память о ней.",al={"keeshan wife","jade keeshan","keeshan pendant","жена кеешана","нефрит кеешан","кулон кеешана"}},{q="В каком подразделении служил Кеешан?",a="Кеешан служил в роте «Браво» под командованием полковника Тротемана и сражался в Великих войнах бок о бок с такими товарищами, как Месснер, Йоргенсен, Краукер и Дэнфорт.",al={"bravo company","keeshan squad","troteman squad","рота браво","отряд кеешана","отряд тротемана"}}},fp="15,282,21.612.0,26.444.1,23.255.0,43.192.0,26.144.0,33.172.0"}
P.entries["npc:jonathan-carevin"] = {kw={"calor","carevin family","darkshire","duskwood","jonathan carevin","night watch","undead","worgen","калор","семья карвинов","темнолесье","сумеречный лес","джонотан карвин","ночной дозор","нежить","ворген"},ang={["class:Hunter"]="Охотники находят общий язык с Карвином: он деятельно выслеживает и методично истребляет ночных хищников Сумеречного леса.",["class:Paladin"]="Рвение Карвина и его призывы к Свету против демонической скверны и нежити глубоко созвучны священным обетам паладина.",["faction:Alliance"]="Для защитников Альянса, пытающихся восстановить покой в Сумеречном лесу, Джонотан Карвин наносит точечные удары по сверхъестественным угрозам, которые остались без внимания из-за небрежения Штормграда."},sec={{t="Поход Карвинов",b="While Darkshire depends upon the Night Watch to patrol the roads and safeguard the township, Jonathan Carevin believes a mere defensive perimeter is insufficient. Alongside his family and allies like Calor, Jonathan takes the offensive. He actively targets the unholy fiends wandering Duskwood, pursuing a personal crusade to purge all demons, undead, and heretics from the region under the grace of the Light."},{t="Тень воргенов",b="Jonathan's vigilance extends beyond shambling skeletons and ghouls. He pays close attention to the savage, wolf-like beasts known as worgen that stalk the forest depths. Knowing the danger they present to an already besieged settlement, Jonathan coordinates investigations into their mysterious presence, seeking to uncover where these ungodly predators originated and putting an end to their nocturnal prowling."}},faq={{q="Who is Jonathan Carevin?",a="Jonathan Carevin is a grim hunter living in Darkshire in Duskwood. He leads the Carevin family in an active fight against the foul monsters haunting the forest.",al={"who is carevin","jonathan carevin lore","carevin darkshire","кто такой карвин","джонотан карвин предания","карвин темнолесье"}},{q="Чем он отличается от Ночного Дозора?",a="While the Night Watch focuses primarily on guarding Darkshire's perimeter and keeping the roads passable, Jonathan and his supporters actively track and hunt down the undead and other abominations to eradicate them at their source.",al={"is he night watch","carevin vs night watch","он из ночного дозора","карвин и ночной дозор"}},{q="С какими угрозами он борется?",a="Jonathan actively hunts the undead, ravenous worgen packs, demons, and anyone who would offer shelter or aid to such unholy abominations.",al={"what does carevin hunt","carevin targets","на кого охотится карвин","цели карвина"}},{q="Связан ли Джонотан с Алым орденом?",a="Его резкие речи, пылкая преданность Свету и строгая нетерпимость к скверне схожи со взглядами Алого ордена, но официально он действует независимо вместе со своей семьей в Темнолесье.",al={"carevin scarlet crusade","is carevin scarlet","карвин алый орден","карвин из алого ордена"}},{q="Кто помогает Джонотану в его деле?",a="Помимо ближайших родных, Джонотану напрямую помогают сочувствующие бойцы, например Калор, который помогает ему выслеживать вторжения чудовищ в лесу.",al={"carevin allies","who helps carevin","союзники карвина","кто помогает карвину"}},{q="Как он связан с воргенами?",a="Джонотан видит в воргенах противоестественную угрозу, терроризирующую жителей Сумеречного леса, и поручает путникам выяснить, откуда они внезапно появились в глуши.",al={"carevin worgen","why carevin hate worgen","карвин ворген","почему карвин ненавидит воргенов"}}},fp="16,277,19.410.0,24.412.1,24.160.0,40.231.0,27.137.0,48.203.0,36.171.0,37.170.0"}
P.entries["npc:jorah-annison"] = {n="Йорах Аннисон",s="Йорах Аннисон — картограф из Отрекшихся, живущий в Магическом квартале Подгорода. Хотя его ремесло связано с картами и географией, его познания бесценны для странствующих чародеев, ищущих редкие, разбросанные по Азероту сведения.",h="Йорах Аннисон — картограф из Отрекшихся, живущий в Магическом квартале Подгорода.",kw={"annison","cartographer","jorah","magic quarter","maps","tome of the cabal","undercity","warlock","аннисон","картограф","йорах","магический квартал","карты","фолиант заговора","подгород","чернокнижник"},ang={["class:Warlock"]="Йорах — незаменимый помощник для чернокнижников Орды, собирающих Фолиант заговора: он указывает важные координаты, где можно найти утерянные страницы по всему миру.",["faction:Horde"]="Благодаря своему мастерству картографа Йорах помогает искателям приключений Орды ориентироваться на незнакомых континентах и находить ценные реликвии.",["race:Undead"]="Йорах, житель Подгорода, показывает, как научные занятия Отрекшихся, например картография, служат выживанию всего его народа."},sec={{t="Знаток темных земель",b="Живя среди алхимических паров и арканного эха Магического квартала Подгорода, Йорах Аннисон занимается картографией. Тогда как многие ученые Отрекшихся посвящают свою нежизнь чуме или разрушительной магии, Йорах точно наносит на карты местность, границы и забытые места на континентах, давая Орде ценные сведения для снабжения и передвижения."},{t="След заговора",b="Знания Йораха о местности простираются далеко за пределы руин Лордерона. Чернокнижников, ищущих неуловимый Фолиант заговора, часто направляют к нему, чтобы выяснить, где можно найти древние тексты и остатки темных сект, — он связывает историю предания с далекой географией."}},faq={{q="Кто такой Йорах Аннисон?",a="Йорах Аннисон — картограф из числа нежити, живущий в Магическом квартале Подгорода. Он помогает путникам Орды сведениями о географии и исторических местах.",al={"jorah annison who","who is jorah","undercity cartographer","йорах аннисон кто","кто такой йорах","картограф подгорода"}},{q="Где найти Йораха Аннисона?",a="Он находится в Магическом квартале Подгорода — подземной столицы Отрекшихся, расположенной под руинами Лордерона.",al={"jorah annison location","where is jorah annison","find jorah","йорах аннисон местонахождение","где йорах аннисон","найти йораха"}},{q="Почему чернокнижникам нужно говорить с ним?",a="Чернокнижники, ищущие древний Фолиант заговора, обращаются к Йораху за его картографическим мастерством: он может указать им дальние места, где можно найти разрозненные фрагменты текста.",al={"jorah warlock quest","tome of the cabal jorah","why talk to jorah","задание чернокнижника йорах","фолиант заговора йорах","зачем говорить с йорахом"}},{q="К какой фракции принадлежит Йорах Аннисон?",a="Он принадлежит к Отрекшимся и предан Орде, служа своим собратьям в их столице.",al={"is jorah horde","jorah annison faction","йорах из орды","фракция йораха аннисона"}},{q="Продает ли Йорах Аннисон карты игрокам напрямую?",a="Йорах в первую очередь выступает советником и связным по заданиям, касающимся забытых мест, а не торговцем.",al={"does jorah sell maps","jorah merchant","продает ли йорах карты","йорах торговец"}},{q="Бывает ли Йорах Аннисон за пределами Подгорода?",a="Хотя его картография и указания по заданиям связаны с далекими краями, например со Степями, сам Йорах остается в Магическом квартале Подгорода.",al={"jorah in barrens","jorah outside undercity","йорах в степях","йорах за пределами подгорода"}}},fp="13,263,27.382.0,17.292.0,21.169.0,31.134.0,39.201.0,42.107.0,49.123.0,50.157.0"}
P.entries["npc:jordan-stilwell"] = {n="Джордан Стилвелл",s="Джордан Стилвелл — искусный оружейник-человек, работающий у заснеженных Врат Стальгорна в Дун Мороге. Хотя ему прочили путь паладина Света, он последовал ремеслу отца и стал мастером, чьи изделия служат паладинам всего Альянса. Он наиболее известен тем, что выковал Боевую перчатку Веригана в честь старого друга, Боша Веригана.",h="Джордан Стилвелл — искусный оружейник-человек, работающий у заснеженных Врат Стальгорна в Дун Мороге.",ang={["faction:Alliance"]="Бежав от ужасов воргенов Аругала в Серебряном бору, Джордан нашел убежище у дворфов Дун Морога и теперь отдает свое мастерство напрямую защитникам Альянса.",["profession:Blacksmithing"]="Обученный дворфом Балором Крепкоруком и владеющий зачарованным молотом, доставшимся от отца, Джордан — вершина смертного священного кузнечного мастерства."},sec={{t="Призвание у наковальни",b="Хотя от Джордана Стилвелла ожидали, что он примет священные обеты и станет паладином Церкви Священного Света, он в итоге избрал путь кузнеца. Он пошел по стопам отца и взял его зачарованный кузнечный молот. Мастерство Джордан оттачивал под руководством кузнеца-дворфа Балора Крепкорука. Хотя он отказался от мантии посвященного святого воина, Джордан остается глубоко верен Свету и посвящает свое незаурядное мастерство снаряжению воинов, сражающихся во имя Света."},{t="Бегство из Серебряного бора",b="Задолго до того, как открыть мастерскую на лютом морозе Дун Морога, Джордан работал кузнецом в замке барона Сребролена в Серебряном бору. Когда верховный маг Аругал напустил на крепость диких воргенов, превратив ее в проклятый оплот, известный как Крепость Темного Клыка, Джордану удалось спастись от кровавой бойни. Вынужденный бросить кузню и прежний дом, он в конце концов нашел приют среди дворфов Дун Морога."},{t="Ковка Боевой перчатки Веригана",b="Jordan keeps his forge outdoors near the gates of Ironforge, favoring the brisk alpine air over the stifling heat of the Great Forge inside the mountain. When the Church of the Holy Light sends worthy paladins to him, Jordan tasks them with recovering rare materials from across the world to craft a legendary two-handed warhammer. Named Verigan's Fist in honor of his old friend Bosch Verigan, the weapon stands as a testament to the enduring bond between devoted faith and masterful steel."}},faq={{q="Кто такой Джордан Стилвелл?",a="Jordan Stilwell is a master human blacksmith found working outside the Gates of Ironforge in Dun Morogh. He crafts sacred armaments for paladins of the Church of the Holy Light, most notably the legendary warhammer Verigan's Fist.",al={"who is jordan stilwell","jordan stilwell lore","who is this blacksmith outside ironforge","кто такой джордан стилвелл","джордан стилвелл предания","кто этот кузнец у стальгорна"}},{q="Почему Джордан Стилвелл работает на снегу, а не внутри Стальгорна?",a="По словам Даториана Ралла из Штормграда, Джордан предпочитает работать на свежем прохладном горном воздухе Дун Морога, а не в душном помещении Великой кузни в Стальгорне.",al={"why is jordan outside ironforge","why work in dun morogh","why is he in the snow","почему джордан у стальгорна","почему работает в дун мороге","почему он на снегу"}},{q="Как Джордан Стилвелл связан с Крепостью Темного Клыка?",a="Когда-то Джордан был оружейником и кузнецом в поместье барона Сребролена в Серебряном бору. Ему удалось бежать из крепости до или во время катастрофического мятежа, когда верховный маг Аругал и его дикие ворлены перебили гарнизон и захватили крепость.",al={"jordan stilwell shadowfang keep","jordan stilwell silverpine","did he live in pyrewood","джордан стилвелл крепость темного клыка","джордан стилвелл серебряный бор","жил ли он в сосновом лесу"}},{q="What is Verigan's Fist?",a="Verigan's Fist is a powerful two-handed holy hammer forged by Jordan Stilwell for Alliance paladins. It is named in honor of Jordan's old friend, Bosch Verigan.",al={"verigans fist","verigan hammer","who is verigan"}},{q="Кто обучал Джордана Стилвелла кузнечному делу?",a="Джордан унаследовал ремесло и зачарованный кузнечный молот от отца, а затем довел мастерство до совершенства под руководством кузнеца-дворфа Балора Крепкорука.",al={"who trained jordan stilwell","jordan stilwell teacher","where did he learn smithing","кто обучал джордана стилвелла","учитель джордана стилвелла","где он учился кузнечному делу"}},{q="Кто жена Джордана Стилвелла?",a="Джордан женат на Дафне Стилвелл. Вместе супруги оказали Церкви Священного Света огромную помощь на протяжении многих лет, и обоих почитают как глубоко преданных слуг веры.",al={"jordan stilwell wife","daphne stilwell husband","daphne stilwell","жена джордана стилвелла","муж дафны стилвелл","дафна стилвелл"}}},fp="15,358,22.527.0,22.418.0,22.491.1,23.230.0,78.181.0,56.266.0,23.160.0,45.178.0,30.192.0"}
P.entries["npc:jorgen"] = {n="Йорген",s="Йорген — осторожный информатор-человек, живущий в Штормграде, в укромном месте у воды, сразу при входе в Аллею Героев. Несмотря на скромное и неприметное место, он замешан в деликатных делах, связанных с видными лицами столицы, в том числе с Иллингом Триасом и епископом Делавеем.",h="Йорген — осторожный информатор-человек, живущий в Штормграде, в укромном месте у воды, сразу при входе в...",kw={"bishop delavey","elling trias","informant","jorgen","missing diplomat","stormwind","valley of heroes","епископ делавей","иллинг триас","информатор","йорген","пропавший дипломат","штормград","аллея героев"},ang={["class:Rogue"]="Йорген — часть уличной сети шепотков, процветающей под безупречным мрамором Штормграда и тесно связанной с тайными делами, которые ведутся через сырную лавку Триаса.",["faction:Alliance"]="Когда официальные каналы Штормграда упираются в бюрократические стены, надежные уличные информаторы вроде Йоргена становятся незаменимы в поиске угроз королевству."},sec={{t="Глаза у воды",b="Йорген держится внизу, у воды, сразу справа от монументального входа в Штормград, вдали от оживленных улиц города. Пока громадные статуи героев смотрят на мост наверху, Йорген из тени внизу наблюдает за тем, кто приходит и уходит. Он служит тихим контактом для тех, кому нужны сведения без огласки."},{t="Запутанная история",b="Осторожность Йоргена не случайна. Его связывает непростое прошлое с мастером-сыроделом и собирателем сведений Иллингом Триасом, а также с епископом Делавеем из Собора Света. Когда возникают щекотливые расследования, например о пропаже дипломата, посланного в Терамор, Йорген — один из немногих местных контактов, способных направить следователей в верную сторону, если они знают, как к нему подойти."}},faq={{q="Где найти Йоргена?",a="Йорген находится в Штормграде, в Аллее Героев. Войдя в городские ворота со стороны Элвиннского леса, спуститесь к воде справа от главного моста.",al={"jorgen location","where is jorgen","find jorgen","йорген местонахождение","где йорген","найти йоргена"}},{q="С кем в Штормграде связан Йорген?",a="Йоргена связывает давняя история с Иллингом Триасом, видным торговцем сыром из Торгового квартала с тайными связями, а также с епископом Делавеем из Собора Света.",al={"jorgen connections","jorgen ties","who does jorgen know","связи йоргена","йорген знакомые","кого знает йорген"}},{q="Какую роль играет Йорген в расследовании пропажи дипломата?",a="Во время поисков пропавшего посланника Йорген — ключевой информатор. Расследователей направляют к нему, чтобы выяснить, кто мог устроить тайные встречи и скрытые операции в королевстве.",al={"jorgen missing diplomat","jorgen quest","йорген пропавший дипломат","йорген задание"}},{q="Служит ли Йорген в городской страже Штормграда?",a="Нет. Йорген действует самостоятельно и держится вдали от официальных патрулей стражи, у берегов канала, где можно тайно поговорить без лишних ушей.",al={"is jorgen a guard","jorgen faction","йорген стражник","фракция йоргена"}}},fp="6,292,17.374.0,17.434.1,24.180.0,40.174.0,72.198.0,51.161.0"}
P.entries["npc:josef-gregorian"] = {n="Джозеф Грегориан",s="Джозеф Грегориан — Отрекшийся, учитель портняжного дела, работающий в Магическом квартале Подгорода. Он наставляет честолюбивых портных Орды, желающих ткать зачарованные ткани, делится опытом и направляет их к особым одеяниям.",h="Джозеф Грегориан — Отрекшийся, учитель портняжного дела, работающий в Магическом квартале Подгорода.",kw={"gathering materials","josef gregorian","magic quarter","spellfire robes","tailoring trainer","undercity","сбор материалов","джозеф грегориан","магический квартал","одеяние из чароткани","учитель портняжного дела","подгород"},ang={["profession:Tailoring"]="Для портных Орды Джозеф Грегориан — важный контакт в Лордероне: он обучает портных и шьет одеяния юным магам, приносящим ему материалы.",["race:Undead"]="Грегориан показывает, что даже смерть и нежизнь не истребили тонкое человеческое искусство портняжного дела: оно пережило падение Лордерона и служит новому обществу Отрекшихся."},sec={{t="Ткач Магического квартала",b="Среди тусклых алхимических фонарей и сырых сводов Магического квартала Джозеф Грегориан поддерживает тонкое мастерство портняжного дела для Отрекшихся и их союзников из Орды. Жизнь в подземном королевстве стала холодной, но работа с тканью по-прежнему важна для чернокнижников, магов и жрецов, направляющих необузданную энергию через тканые волокна. Грегориан — надежный наставник в столице, готовый обучать основным выкройкам и шить первые одеяния юным магам, принесшим нужные материалы."}},faq={{q="Где найти Джозефа Грегориана?",a="Джозеф Грегориан находится в Магическом квартале Подгорода, где занимается портняжным делом и обучает этому ремеслу городских заклинателей и ученых.",al={"josef gregorian location","where is gregorian","undercity tailor trainer","джозеф грегориан местонахождение","где грегориан","учитель портняжного дела подгород"}},{q="Какую роль играет Джозеф Грегориан в Подгороде?",a="Он учитель портняжного дела, обучающий мастеров Орды рецептам и приемам шитья. Он также шьет первые одеяния юным магам, которых к нему посылает Анастасия Хартвелл.",al={"what does josef gregorian do","josef gregorian trainer","undercity tailoring","чем занимается джозеф грегориан","джозеф грегориан учитель","портняжное дело подгород"}},{q="Какие задания дает Джозеф Грегориан?",a="Грегориан участвует в цепочке заданий для магов: Анастасия Хартвелл посылает к нему юных магов с льняной тканью и манакамнями Даларана, добытыми в Серебряном бору («Сбор материалов»), а он шьет им комплект простых одеяний из чароткани («Одеяние из чароткани»).",al={"josef gregorian quests","robe quests undercity","задания джозефа грегориана","задания на одеяния подгород"}}},fp="15,238,27.506.0,33.148.0,54.169.0,39.241.0"}
P.entries["npc:kaal-soulreaper"] = {n="Каел Жнец Душ",s="Каел Жнец Душ — орк, учитель чернокнижников, обосновавшийся в глубине Магического квартала Подгорода. Хотя он живет среди Отрекшихся, он поддерживает тесные связи с последователями темных искусств по всей Орде и часто направляет учеников к наставникам в дальних землях.",h="Каел Жнец Душ — орк, учитель чернокнижников, обосновавшийся в глубине Магического квартала Подгорода.",kw={"demonology","felsteed","kaal soulreaper","magic quarter","menara voidrender","undercity","warlock trainer","демонология","конь преисподней","каел жнец душ","магический квартал","менара расщепительница бездны","подгород","учитель чернокнижников"},ang={["class:Warlock"]="Каел Жнец Душ дает необходимую подготовку в демонических искусствах и указывает честолюбивым чернокнижникам путь к созданию Сферы Орахила и подчинению коня преисподней.",["race:Orc"]="В отличие от тайного шабаша в Расселине Теней, Каел действует открыто в столице Отрекшихся, вдали от бдительных глаз шаманского руководства Оргриммара."},sec={{t="Практик в тени",b="Пока Орда Тралла строго ограничивает и контролирует магию Скверны в Оргриммаре, такие практики, как Каел Жнец Душ, находят надежное убежище в подземных святилищах Лордерона. Живя в Магическом квартале Подгорода, Каел делится мастерством в обращении с демонами и проклятиями с чернокнижниками Орды, готовыми учиться. Помимо начального обучения, он служит важным контактом для тех, кто ищет большей силы, и отправляет честолюбивых учеников за море к наставникам вроде Менары Расщепительницы Бездны в Степях."}},faq={{q="Кто такой Каел Жнец Душ?",a="Каел Жнец Душ — орк, учитель чернокнижников, живущий в Магическом квартале Подгорода. Он обучает заклинаниям чернокнижников и наставляет тех, кто ищет особые темные артефакты и ритуалы.",al={"who is kaal","kaal soulreaper lore","kaal undercity","кто такой каел","каел жнец душ предания","каел подгород"}},{q="Почему орк-чернокнижник живет в Подгороде?",a="В орочьем обществе при вожде Тралле к чернокнижникам относятся с сильным подозрением и пристально следят за ними. Подгород предлагает куда более терпимую среду для изучения магии Тьмы и демонологии рядом с Отрекшимися.",al={"why is an orc in undercity","why is kaal in undercity","почему орк в подгороде","почему каел в подгороде"}},{q="Куда Каел Жнец Душ отправляет своих учеников?",a="Когда ученики достигают достаточного мастерства, Каел направляет их через Великое море в Степи учиться у Менары Расщепительницы Бездны или знакомит с другими видными чернокнижниками Орды.",al={"kaal quests","who does kaal send you to","задания каела","к кому посылает каел"}}},fp="15,279,29.516.0,23.195.0,46.201.0,48.185.0"}
P.entries["npc:kadrak"] = {n="Кадрак",s="Кадрак — опытный командир-орк, стоящий на Заставе Мор'шан на границе Степей и Ясеневого леса. Ему поручена охрана северного рубежа, и он направляет поток донесений и подкреплений в спорный лес. Для искателей приключений Орды, идущих через засушливые равнины, Кадрак — врата в непрекращающуюся борьбу с ночными эльфами.",h="Кадрак — опытный командир-орк, стоящий на Заставе Мор'шан на границе Степей и Ясеневого леса.",kw={"ashenvale","barrens","kadrak","mor'shan rampart","orc","rampart","splintertree post","warsong","ясеневый лес","степи","кадрак","застава мор'шан","орк","застава","застава расщепленного дерева","песнь войны"},ang={["class:Warrior"]="Кадрак воплощает дисциплину передовой: он полагается на холодную сталь и воинскую силу, чтобы удерживать укрепленный проход против враждебного лесного мастерства и партизанских набегов.",["faction:Alliance"]="Для сил Альянса, пытающихся ударить по Степям со стороны Ясеневого леса, Кадрак и его застава — укрепленная преграда, охраняющая сердце земель Орды.",["faction:Horde"]="Кадрак — ваша точка входа в кампании Ясеневого леса: он направляет поток воинов на север, чтобы защищать лесозаготовки и отвоевывать земли для Орды.",["race:Orc"]="Кадрак — стойкий ветеран, продолжающий дело территориальных усилий клана Песни Войны, и воплощает непреклонную решимость орков на границе Ясеневого леса."},sec={{t="Страж Заставы",b="Стоя на укрепленных деревянных заграждениях Заставы Мор'шан, Кадрак следит за главным путем, соединяющим Степи с Ясеневым лесом. Граница — шаткий рубеж: на юге лежат выжженные солнцем равнины, захваченные Ордой, а на севере высятся древние леса, яростно охраняемые ночными эльфами. Кадрак следит, чтобы оборонительный периметр оставался целым против наступающих Часовых и враждебных лесных тварей."},{t="Снабжение на передовой",b="Помимо удержания рубежа, Кадрак ведает важными военными сведениями между Степями и передовыми лагерями лесорубов в глубине леса. Он принимает гонцов с важными боевыми донесениями от Всадников Песни Войны и направляет перемещение припасов и свежих сил в такие опорные пункты, как Застава Расщепленного Дерева. Тех, кто к нему прибывает, быстро отправляют в самое сердце войны за земли."}},faq={{q="Кто такой Кадрак?",a="Кадрак — офицер-орк на Заставе Мор'шан. Он отвечает за охрану границы и направляет силы Орды, идущие между Степями и зонами боевых действий Ясеневого леса.",al={"kadrak identity","who is the orc at the wall","mor'shan rampart commander","кто такой кадрак","кто орк у стены","командир заставы мор'шан"}},{q="Где найти Кадрака?",a="Кадрак стоит на Заставе Мор'шан — укрепленном деревянном заграждении на дальней северной окраине Степей, отмечающем границу с Ясеневым лесом.",al={"kadrak location","find kadrak","where is kadrak","кадрак местонахождение","найти кадрака","где кадрак"}},{q="Какова роль Кадрака в Орде?",a="Он командует оборонительным периметром на границе, собирает военные сведения от разведчиков-гонцов и инструктирует путников Орды, идущих на север усиливать такие форпосты, как Застава Расщепленного Дерева.",al={"kadrak duties","what does kadrak do","kadrak role","обязанности кадрака","что делает кадрак","роль кадрака"}},{q="Почему Застава Мор'шан так сильно защищена?",a="Застава защищает северные подступы к Степям и Дуротару от ответных вторжений ночных эльфов, вызванных лесозаготовками Орды в Ясеневом лесу.",al={"why is mor'shan rampart fortified","purpose of the rampart","why guard ashenvale border","почему застава мор'шан укреплена","назначение заставы","зачем охранять границу ясеневого леса"}},{q="Какие задания Кадрак выдает или принимает?",a="Кадрак принимает донесения, доставленные из Степей, и отправляет искателей приключений с поручениями, связанными с разведданными Песни Войны и закреплением Орды на границе леса.",al={"kadrak quests","report to kadrak","the warsong reports","задания кадрака","доложить кадраку","донесения песни войны"}},{q="Связан ли Кадрак с другими известными деятелями Орды?",a="Кадрак связан с офицерами Орды на передовой, в том числе с капитаном Лободробом, и поддерживает регулярную связь со Всадниками Песни Войны, действующими в Ясеневом лесу.",al={"kadrak connections","kadrak and shatterskull","связи кадрака","кадрак и лободроб"}}},fp="6,379,23.446.0,19.406.0,14.173.0,26.155.0,35.187.0,45.165.0,44.190.0,53.167.0"}
P.entries["npc:kaela-shadowspear"] = {n="Кела Копье Тени",s="Кела Копье Тени — ночная эльфийка из Часовых, стоящая к юго-западу от Утеса Ветрорезов в Когтистых горах. Со своего небольшого форпоста она взаимодействует с другими Часовыми, следя за нарастающим напряжением и беспорядками в глуши. Она полагается на смелых путников, которые разведывают опасные земли и помогают раненым защитникам края.",h="Кела Копье Тени — ночная эльфийка из Часовых, стоящая к юго-западу от Утеса Ветрорезов в Когтистых горах.",kw={"ancients","kaela","rustfizzle","sentinel","shadowspear","spirits","stonetalon","thenysil","windshear","древние","кела","ржавошиппи","часовой","копье тени","духи","когтистые горы","тенисил","утес ветрорезов"},ang={["class:Druid"]="Друиды найдут общее дело с усилиями Келы выходить раненых древних и утишить муку потревоженных духов природы.",["faction:Alliance"]="Кела Копье Тени — важный контакт для искателей приключений Альянса, отправляющихся в спорные земли Когтистых гор: она координирует обмен разведданными между отдаленными форпостами.",["race:NightElf"]="Для ночных эльфов Кела воплощает стойкую оборону священной земли: она трудится, чтобы унять разгневанных духов и защитить почитаемых древних Калимдора."},sec={{t="Разведчица на границе",b="Находясь к юго-западу от промышленного разорения Утеса Ветрорезов, Кела Копье Тени бдительно следит за окрестными проходами. В Когтистых горах полно опасностей: Орда наступает, а гоблины используют природные богатства края. Действуя вместе с гномом Гаксимом Ржавошиппи, Кела служит важной передовой связной ночных эльфов и выслеживает угрозы, проникающие все глубже в исконные земли."},{t="Исцеление земли",b="Беспокойство в Когтистых горах — это не только территориальные стычки. Жестокое разрушение природы растревожило элементалей и причинило вред древним стражам леса. Кела неустанно посылает искателей приключений против разъяренных духов стихий и ухаживать за ранеными древними, страдающими в пылу конфликтов края, стремясь восстановить мир, пока земля не получила неизгладимых шрамов."}},faq={{q="Кто такая Кела Копье Тени?",a="Кела Копье Тени — ночная эльфийка, выдающая задания, в пограничном лагере к юго-западу от Утеса Ветрорезов в Когтистых горах. Она руководит разведкой в регионе и помогает защищать местных животных и духов.",al={"who is kaela","kaela shadowspear identity","kaela npc","кто такая кела","кела копье тени","кела персонаж"}},{q="Где найти Келу Копье Тени?",a="Она находится в небольшом лагере Альянса к юго-западу от Утеса Ветрорезов, у дороги в Когтистых горах, и делит лагерь с гномом-инженером Гаксимом Ржавошиппи.",al={"kaela shadowspear location","where is kaela","kaela stonetalon camp","кела копье тени местонахождение","где кела","лагерь келы когтистые горы"}},{q="Кому подчиняется Кела?",a="Кела тесно взаимодействует с Часовой Тенисил: они регулярно обмениваются разведданными о передвижениях врага и местных угрозах в Когтистых горах.",al={"kaela reports to who","kaela thenysil","kaela's commander","кому подчиняется кела","кела тенисил","командир келы"}},{q="Почему Келу тревожат элементали?",a="Интенсивные лесозаготовки, добыча руды и военное вторжение в Когтистых горах глубоко нарушили природное равновесие, и духи стихий впадают в ярость и нападают на всех поблизости.",al={"enraged spirits quest","why are spirits angry","kaela elemental spirits","задание разъяренные духи","почему духи злы","кела духи стихий"}},{q="Что происходит с древними близ Утеса Ветрорезов?",a="Региональные конфликты и стремительная вырубка лесов оставили древних защитников раненными и страдающими. Кела просит путников помочь найти и исцелить этих павших защитников природы.",al={"wounded ancients quest","kaela ancients","stonetalon wounded ancients","задание раненые древние","кела древние","раненые древние когтистые горы"}},{q="Почему рядом с Келой находится гном?",a="Кела делит лагерь с Гаксимом Ржавошиппи, гномом из Альянса. Пока Кела занята духовным и тактическим равновесием глуши, Гаксим занимается противодействием враждебным гоблинским механизмам и операциям поблизости.",al={"gaxim rustfizzle kaela","why is gaxim with kaela","gnome and night elf camp","гаксим ржавошиппи кела","почему гаксим с келой","лагерь гнома и ночной эльфийки"}}},fp="17,351,23.446.0,16.414.0,25.216.0,37.179.0,25.158.0,44.178.0,54.185.0,36.230.0"}
P.entries["npc:kalecgos"] = {n="Калесгос",kw={"anveena","blue dragon","kalec","kalecgos","malygos","sunwell","visage","анвина","синий дракон","калек","калесгос","малигос","солнечный колодец","облик"},ang={["class:Mage"]="Как член синего драконьего рода, Калесгос неразрывно связан с тайной магией, и его знания о магических потоках и энергии силовых линий глубоко увлекают чародеев Кирин-Тора."},sec={{t="Дракон среди смертных",b="В отличие от многих сородичей из синего драконьего рода, которые смотрят на смертных с безразличием или откровенным недоверием, Калесгос предпочитает ходить среди них как равный. Приняв облик полуэльфа с яркими иссиня-черными волосами, он выбирает располагающие образы смертных, чтобы свободно перемещаться по Азероту. Его чуткость отличает его от более древних и отстраненных драконов, хотя он по-прежнему страстно предан священному долгу своего рода — охранять магию."},{t="Поиски Солнечного Колодца",b="После разрушений Третьей войны Малигос отправил Калесгоса в Лордерон и Кель'Талас, чтобы найти уцелевшие остатки разрушенного Солнечного Колодца. Его миссия привела к столкновениям с дворфами-охотниками на драконов, агентами Плети и эльфом-предателем Дар'Ханом Дратиром. Вместе с возлюбленной Тайригосой и паладином-человеком Джорадом Мейсом Калек раскрыл тайну аватары Анвины Тигг и защитил источник силы от захвата нежитью."}},faq={{q="Кто такой Калесгос?",a="Калесгос — молодой синий дракон, посланник и следователь синего драконьего рода, давший клятву оберегать тайное равновесие во всем Азероте.",al={"who is kalec","what is kalecgos","kalecgos lore","кто такой калек","кто такой калесгос","история калесгоса"}},{q="Почему Калесгос выглядит как полуэльф?",a="Калесгос выбрал облик полукровки — наполовину человека, наполовину эльфа, — чтобы жить среди смертных рас как дружелюбный приятель и равный, а не принимать грандиозную или устрашающую форму.",al={"kalec visage","why mortal form","kalec half elf","облик калека","почему смертный облик","калек полуэльф"}},{q="Что привело Калесгоса в Лордерон и Кель'Талас?",a="Малигос поручил ему исследовать остаточные магические энергии, оставшиеся после того, как Плеть разрушила источник силы высших эльфов — Солнечный Колодец.",al={"kalec sunwell","why was kalec in quelthalas","калек солнечный колодец","почему калек был в кель'талас"}},{q="Как он связан с Хронорму?",a="Калесгос — близкий друг бронзовой драконихи Хронорму. Прежде чем Хрони выбрала смертный облик гномки, Калек советовал ей найти обличье, по-настоящему подходящее ей.",al={"kalec chromie","chronormu visage kalec","калек хрони","хронорму облик калек"}}},fp="8,271,22.463.0,25.480.1,16.151.0,39.178.0,51.147.0,36.175.0"}
P.entries["npc:kali-remik"] = {n="Кали Ремик",s="Кали Ремик — охотница из троллей племени Черного Копья, помогающая советами путникам в сердце земель Орды. Хорошо зная искусство выслеживания и выживания в Дуротаре, она направляет молодых охотников к Тотару в Колючий Холм, чтобы те научились приручению зверей.",h="Кали Ремик — охотница из троллей племени Черного Копья, помогающая советами путникам в сердце земель Орды.",kw={"darkspear","durotar","kali remik","sen'jin village","the hunter's path","tracker","valley of spirits","черное копье","дуротар","кали ремик","деревня сен'джин","путь охотника","следопыт","аллея духов"},ang={["class:Hunter"]="Для молодых стрелков-орков и троллей Кали — ступень на пути вперед: она замечает, когда ваши навыки превосходят деревенские учения, и отправляет вас к Тотару в Колючий Холм.",["race:Troll"]="Как и она, принадлежа к племени Черного Копья, Кали присматривает за сородичами, пока те заново строят жизнь на побережье Дуротара и селятся в Аллее Духов Оргриммара."},sec={{t="Проводница для охотников",b="Кали Ремик — опытная следопытка из троллей джунглей, хорошо знающая засушливые пустоши Дуротара и оживленные центры Орды. В прибрежных поселениях вроде Деревни Сен'джин она присматривает за молодыми разведчиками, делающими первые шаги за пределами Долины Испытаний. Зная, когда новичок перерос местные тренировочные площадки, она направляет многообещающих стрелков к Тотару в Колючий Холм, чтобы они начали путь повелителей зверей, следя за тем, чтобы пограничные ряды Орды оставались острыми и дисциплинированными."}},faq={{q="Кто такая Кали Ремик?",a="Кали Ремик — разведчица из троллей племени Черного Копья и персонаж, выдающий задания. Она помогает направлять начинающих искателей приключений из Орды, особенно охотников, готовых продолжить обучение за пределами местных застав.",al={"kali remik lore","who is kali remik","kali remik npc","кали ремик предания","кто такая кали ремик","кали ремик персонаж"}},{q="Где найти Кали Ремик?",a="Ее можно найти помогающей своему народу в Дуротаре, особенно возле Деревни Сен'джин.",al={"where is kali remik","kali remik location","find kali remik","где кали ремик","местоположение кали ремик","найти кали ремик"}},{q="Какие советы она дает охотникам?",a="В задании «Путь охотника» Кали направляет молодых охотников-орков и троллей, доказавших свои базовые навыки, в Колючий Холм, где Тотар помогает им встать на путь приручения собственного зверя-спутника.",al={"the hunters path quest","kali remik hunter quest","what does kali teach","задание путь охотника","кали ремик задание охотника","чему учит кали"}}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="Калтунк",s="Калтунк — орк-надсмотрщик, стоящий в самом сердце Долины Испытаний в Дуротаре. Он — первый, с кем встречаются молодые орки, делающие первые шаги в мире. Его долг — приветствовать этих будущих героев и направлять их к первым обязанностям на службе Орды.",h="Калтунк — орк-надсмотрщик, стоящий в самом сердце Долины Испытаний в Дуротаре.",kw={"durotar","gornek","kaltunk","orc starter","valley of trials","your place in the world","дуротар","горнек","калтунк","старт орка","долина испытаний","свое место в мире"},ang={["faction:Horde"]="Калтунк помогает поддерживать практичную дисциплину, необходимую для порядка на суровых испытательных землях Дуротара.",["race:Orc"]="Для каждого орка, выходящего в Калимдор, грубые наставления Калтунка — первые слова, которые он слышит, начиная добывать свою честь."},sec={{t="Первый шаг",b="Стоя под палящим солнцем Долины Испытаний, Калтунк наблюдает за только что прибывшими, жаждущими доказать, что достойны Орды. Пока другие наставники и старейшины назначают изнурительные испытания и охотничьи обряды, Калтунк следит, чтобы ни один новобранец не бродил бесцельно в красной пыли. Он отдает прямые приказы, направляя новичков к Горнеку и пути дисциплины."},{t="Хранитель долины",b="Долина Испытаний — нелегкое испытательное поле; ее выбрали именно для того, чтобы ковать силу и стойкость в каждом юноше, ступающем по дну ее каньонов. Калтунк воплощает эту суровую практичность. Он не произносит пышных речей и не нянчится, ожидая, что каждый орк быстро найдет свое место в мире и станет приносить пользу вождю."}},faq={{q="Кто такой Калтунк?",a="Калтунк — орк-надсмотрщик в Долине Испытаний. Он первый, кого встречают только что пробудившиеся орки-герои; его задача — направить их к наставникам и начать обучение.",al={"kaltunk role","who is this orc","kaltunk npc","роль калтунка","кто этот орк","калтунк персонаж"}},{q="Что Калтунк делает для новых героев?",a="Он дает новобранцам первое задание, отправляя их к Горнеку в другую часть долины, чтобы началось их настоящее обучение.",al={"kaltunk quest","what does kaltunk want","first quest valley of trials","задание калтунка","что хочет калтунк","первое задание долина испытаний"}},{q="Где найти Калтунка?",a="Он стоит рядом с центральной тренировочной палаткой и костром в Долине Испытаний — уединенной стартовой местности на юге Дуротара.",al={"kaltunk location","find kaltunk","where is kaltunk","местоположение калтунка","найти калтунка","где калтунк"}},{q="Почему он находится в Долине Испытаний?",a="Он служит встречающим надсмотрщиком, чтобы прибывающие орки-новобранцы были организованы и сразу направлены на путь службы Орде Тралла.",al={"why is kaltunk here","kaltunk purpose","почему калтунк здесь","зачем нужен калтунк"}}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:kam-deepfury"] = {n="Кам Гневливый",s="Кам Гневливый — известный диверсант из клана Черного Железа, заключенный в глубинах Тюрьмы Штормграда. В отличие от большинства узников тюрьмы, он не связан с Братством Справедливости: его схватили за организацию разрушительного взрыва на Мосту Тандола далеко на севере.",h="Кам Гневливый — известный диверсант из клана Черного Железа, заключенный в глубинах Тюрьмы Штормграда.",ang={["faction:Alliance"]="Пока большинство взглядов в Штормграде устремлено на восстание Братства Справедливости, Гневливый напоминает о более широкой угрозе клана Черного Железа северным рубежам Альянса.",["race:Dwarf"]="Для дворфов Стальгорна Кам Гневливый — заклятый враг: его диверсия разрушила Мост Тандола и убила родственника Длиннокоса Мрачного. Отомстить за эту потерю — вопрос личной чести."},sec={{t="Диверсант вдали от дома",b="Хотя Тюрьма заполнена в основном недовольными Каменщиками и мятежниками Братства Справедливости, Кам Гневливый стоит особняком. Дворф из клана Черного Железа, хитрый и жестокий, он был схвачен и доставлен в Штормград после операции, подорвавшей важную северную инфраструктуру. Он заперт глубоко в камерах тюрьмы, вдали от сородичей под Черной горой, но так же враждебен Альянсу, как любой мятежник в этих коридорах."},{t="Диверсия на Мосту Тандола",b="Разведка Альянса в Дун Модре, у северной границы Болотины, определила, что главным организатором взрыва, разрушившего Мост Тандола, был Гневливый. Взрыв разрушил один из огромных каменных мостов, соединяющих Болотину с Нагорьем Арати. Помимо нарушения важного торгового и военного пути Стальгорна и Альянса, диверсия унесла жизнь родственника дворфийского командира Длиннокоса Мрачного."},{t="Счеты к оплате",b="The Dark Iron insurrectionist did not manage to escape retribution for long, though imprisonment in Stormwind offered him temporary protection from his victims' relatives. Back in the Wetlands, Motley Garmason and the grieving Longbraid the Grim have sought mercenaries willing to infiltrate the riot-torn prison and sever Deepfury's head, settling a bloody grudge sparked hundreds of miles to the north."}},faq={{q="Кто такой Кам Гневливый?",a="Кам Гневливый — элитный узник-дворф из клана Черного Железа, запертый в Тюрьме Штормграда. Он известен организацией диверсии на Мосту Тандола на севере и не связан с мятежниками Братства Справедливости, заключенными вместе с ним.",al={"who is deepfury","kam deepfury lore","who is the dwarf in stockades","кто такой гневливый","кам гневливый предания","кто дворф в тюрьме"}},{q="Почему дворф из клана Черного Железа заперт в Тюрьме Штормграда?",a="Гневливый был схвачен после координации нападения, взорвавшего один из мостов Моста Тандола, что убило дворфийских защитников и перерезало важную сухопутную переправу между Болотиной и Арати. Его отправили в тюрьму Штормграда строгого режима ждать правосудия.",al={"why is he in stockade","what did kam deepfury do","why is he imprisoned","почему он в тюрьме","что сделал кам гневливый","почему он заключен"}},{q="Входит ли Кам Гневливый в Братство Справедливости?",a="Нет. Хотя он заключен вместе с Братством Справедливости во время его восстания в Тюрьме, Гневливый принадлежит к враждебному клану Черного Железа. Он действует целиком по агрессивной программе собственного клана против Альянса и Стальгорна.",al={"is he defias","kam deepfury defias","is deepfury working with vancleef","он из братства справедливости","кам гневливый братство","гневливый заодно с ван клифом"}},{q="Кто хочет смерти Кама Гневливого?",a="Motley Garmason and the Ironforge dwarven forces stationed at Dun Modr want him dead. Longbraid the Grim lost a relative in Deepfury's bombing of the Thandol Span, prompting them to send word to adventurers in Stormwind to claim his head.",al={"who gave the quest for deepfury","who wants deepfury killed","кто дал задание на гневливого","кто хочет убить гневливого"}},{q="Где Кам Гневливый совершил свое преступление?",a="Гневливый организовал диверсию на Мосту Тандола — колоссальном мостовом комплексе, соединяющем Болотину с Нагорьем Арати далеко к северу от Штормграда.",al={"where was the bridge blown up","deepfury bridge bombing","thandol span attack","где взорвали мост","гневливый взрыв моста","нападение на мост тандола"}},{q="Где найти Кама Гневливого в Тюрьме?",a="Кам Гневливый содержится в тюремных блоках Тюрьмы Штормграда, расположенной под районом каналов Штормграда.",al={"where is deepfury in stockade","kam deepfury location","где гневливый в тюрьме","кам гневливый местоположение"}}},fp="12,301,24.459.0,25.447.0,17.404.1,20.226.0,58.266.0,47.242.0,28.238.0,40.154.0,52.125.0"}
P.entries["npc:kanati-greycloud"] = {n="Канати Серое Облако",s="Канати Серое Облако — охотник-таурен, стоящий на Заставе Белого Плеса в Тысяче Игл. Вместе с товарищами-охотниками он организует оборону как может, постоянно терпя вражду местных кентавров племени Галак.",h="Канати Серое Облако — охотник-таурен, стоящий на Заставе Белого Плеса в Тысяче Игл.",kw={"assassination plot","centaur","galak","greycloud","kanati","thousand needles","whitereach post","заговор с убийством","кентавр","галак","серое облако","канати","тысяча игл","застава белого плеса"},ang={["faction:Horde"]="Застава Белого Плеса служит важным наблюдательным пунктом над игольчатыми каньонами; пока Канати жив, разведчики Орды следят за передвижениями кентавров.",["race:Tauren"]="Для таурен, идущих через Тысячу Игл, помощь Канати на Заставе Белого Плеса — важная защита соплеменников от их древних заклятых врагов, кентавров."},sec={{t="Опасный насест",b="Канати Серое Облако разбил лагерь на Заставе Белого Плеса, высоко на песчаниковых шпилях западной Тысячи Игл. Хотя каньон богат дичью и открытыми видами, он зажат кентаврами Галак, чьи отряды оспаривают каждый клочок сухих равнин внизу. Вместе с другими охотниками-таурен Канати следит за дном каньона, стараясь сохранить заставу от жестоких набегов окрестных разбойников."},{t="Засада кентавров",b="Кентавры Галак стремятся не просто изолировать Заставу Белого Плеса, а полностью уничтожить ее защитников. Гонцы, ходящие между лагерями кентавров, несут прямые приказы убить Канати и его товарищей. Путникам предстоит перехватить эти приказы и встать плечом к плечу с Канати, когда отряды Галак обрушатся на плато, чтобы перебить охотников заставы."}},faq={{q="Кто такой Канати Серое Облако?",a="Канати Серое Облако — охотник-таурен, живущий на Заставе Белого Плеса в западной Тысяче Игл, где он держит лагерь и защищается от хищных местных угроз.",al={"who is kanati","kanati greycloud lore","whitereach post tauren","кто такой канати","канати серое облако предания","таурены застава белого плеса"}},{q="Где найти Канати Серое Облако?",a="Канати находится на Заставе Белого Плеса — возвышенном лагере таурен на северных утесах в западной части Тысячи Игл.",al={"kanati location","where is kanati","where is greycloud","местоположение канати","где канати","где серое облако"}},{q="Почему кентавры Галак пытаются его убить?",a="Кентавры Галак стремятся к полному господству над каньонами Тысячи Игл и активно нападают на заставы Орды. Перехваченные приказы раскрывают согласованный заговор кентавров с целью убить Канати и сломить оборону заставы.",al={"why centaur attack kanati","galak assassination plot","protect kanati why","почему кентавры нападают на канати","заговор галак","защитить канати зачем"}},{q="Родственен ли Канати другим Серым Облакам?",a="Он носит ту же фамилию, что Тор Серое Облако и Кар Серое Облако — два таурена, встречающихся в других местах Калимдора, хотя точная родственная связь между ними не уточняется.",al={"greycloud family","tor greycloud relative","kar greycloud","семья серое облако","тор серое облако родственник","кар серое облако"}}},fp="16,218,18.433.0,14.426.1,24.160.0,34.146.0,45.224.0,38.175.0"}
P.entries["npc:kaplak"] = {n="Каплак",s="Каплак — орк, наставник разбойников в Колючем Холме в центральном Дуротаре. Он обучает молодых орков и троллей искусству скрытности, обмана и владения клинком, готовя их к службе Орде, прежде чем отправить в Оргриммар.",h="Каплак — орк, наставник разбойников в Колючем Холме в центральном Дуротаре.",kw={"durotar","kaplak","orc","orgrimmar","razor hill","rogue trainer","stealth","therzok","дуротар","каплак","орк","оргриммар","колючий холм","наставник разбойников","скрытность","терзок"},ang={["class:Rogue"]="Молодым разбойникам-оркам и троллям, покидающим Долину Испытаний, Каплак дает первое профессиональное обучение и направляет их к тайным сетям, действующим в Оргриммаре.",["faction:Horde"]="Каплак негласно следит за тем, чтобы у Орды были умелые разведчики, шпионы и убийцы, способные защищать Дуротар и действовать за пределами обычных линий фронта."},sec={{t="Наставник из теней",b="Каплак живет в поселении Колючий Холм и служит первым учителем юных разбойников Орды, покидающих Долину Испытаний. Если традиционная культура орков славит открытый бой и яростные атаки, то Каплак преподает более холодные и тихие науки, необходимые для выживания: незаметно выслеживать, взламывать замки и наносить смертельные удары со спины. Когда ученики перерастают его обучение в пыльных красных ущельях Дуротара, он направляет их на север, в столицу — Оргриммар, чтобы они совершенствовали мастерство среди опытных агентов гильдии."}},faq={{q="Кто такой Каплак?",a="Каплак — орк, наставник разбойников в Колючем Холме в Дуротаре. Он обучает начинающих разбойников-орков и троллей, покинувших Долину Испытаний, давая им первые навыки разбойника, а затем отправляет к более высоким наставникам в Оргриммар.",al={"who is kaplak","kaplak lore","kaplak razor hill","кто такой каплак","каплак предания","каплак колючий холм"}},{q="Где найти Каплака?",a="Каплака можно найти в Колючем Холме, центральном поселении Дуротара: обычно он отдыхает в казарме или рядом с ней вместе с другими наставниками классов.",al={"where is kaplak","kaplak location","find kaplak","где каплак","местонахождение каплака","найти каплака"}},{q="Какие задания дает Каплак?",a="Каплак помогает разбойникам по мере их роста, направляя их к более высоким наставникам и давая поручения, например отправляя искать Терзока в Оргриммаре.",al={"kaplak quests","quests from kaplak","задания каплака","квесты каплака"}}},fp="6,241,23.544.0,14.236.0,26.156.0,30.161.0"}
P.entries["npc:karang-amakkar"] = {n="Каранг Амаккар",s="Каранг Амаккар — орк-разведчик в форте Зорам'гар на скалистом побережье Ясеневого леса. Действуя на краю земель Орды, он сосредоточен на обуздании свирепых племен фурболгов, угрожающих путям снабжения и границам форта. Путешественники, проходящие через форт, полагаются на его знания местности, чтобы разобраться в опасных распрях леса.",h="Каранг Амаккар — орк-разведчик в форте Зорам'гар на скалистом побережье Ясеневого леса.",kw={"ashenvale","foulweald","furbolg","karang amakkar","thistlefur","zoram strand","zoram'gar outpost","ясеневый лес","гиблая чаща","фурболг","каранг амаккар","колючий мех","зорамское взморье","форт зорам'гар"},ang={["faction:Horde"]="Каранг Амаккар оказывает важную помощь путникам Орды, отважившимся на западные окраины Ясеневого леса, предлагая работу по отражению враждебных существ вокруг форта Зорам'гар.",["race:Orc"]="Находясь на отдаленной заставе вдали от Дуротара, Каранг воплощает суровую решимость орочьих часовых, удерживающих опасные границы."},sec={{t="На побережье Ясеневого леса",b="Каранг Амаккар обосновался в форте Зорам'гар на Зорамском взморье и служит Орде на одной из ее самых уязвимых пограничных застав. Лагерь постоянно находится под давлением со стороны моря, ночных эльфов и диких зверей вглубь суши. Каранг пристально следит за враждебными местными племенами вокруг дороги на восток, чтобы гонцы и разведотряды Орды не попали в засаду к оберегающим свои земли коренным племенам."},{t="Борьба с фурболгами",b="Каранг уделяет основное внимание фурболгам, обитающим в древних лесах, в первую очередь племенам Колючего Меха и Гиблой Чащи. Порча и первобытная ярость доводят этих медвежьих людей до неистовства, поэтому Каранг поручает умелым воинам истреблять их вожаков и зачищать берлоги, пока племена не смогли собраться для организованных нападений на Зорам'гар."}},faq={{q="Кто такой Каранг Амаккар?",a="Каранг Амаккар — орк, выдающий задания в форте Зорам'гар на побережье Ясеневого леса. Он действует от имени Орды, борясь с угрозами в регионе, особенно с враждебными кланами фурболгов.",al={"karang","who is karang","karang amakkar lore","каранг","кто такой каранг","каранг амаккар предания"}},{q="Где найти Каранга Амаккара?",a="Он находится в форте Зорам'гар, на северо-западном берегу Ясеневого леса у Зорамского взморья.",al={"karang location","where is karang amakkar","karang amakkar spot","где каранг","местонахождение каранга","где каранг амаккар"}},{q="Какие задания дает Каранг Амаккар?",a="Каранг поручает искателям приключений из Орды сразиться с агрессивными племенами фурболгов поблизости, направляя удары против клана Колючего Меха и вожака Гиблой Чащи.",al={"karang quests","karang tasks","what does karang want","задания каранга","квесты каранга","что нужно каррангу"}},{q="Почему Каранга тревожат фурболги?",a="Фурболги Ясеневого леса становятся все более дикими и порченными, нападают на путников и грозят отрезать форт Зорам'гар от остальных оплотов Орды в регионе.",al={"why kill furbolgs","furbolg threat ashenvale","thistlefur threat","зачем убивать фурболгов","угроза фурболгов ясеневый лес","угроза колючего меха"}},{q="Родственник ли Каранг Амаккар послушнику Амаккару?",a="Хотя у них общее имя клана или семейная фамилия, точное родство между Карангом и послушником Амаккаром остается неподтвержденным.",al={"amakkar family","initiate amakkar relative","karang family","семья амаккар","родственник послушника амаккара","семья каранга"}},{q="Сражается ли Каранг с ночными эльфами напрямую?",a="Обязанности Каранга в Зорам'гаре в основном связаны с защитой территории и борьбой с дикими угрозами, такими как фурболги Колючего Меха, а открытые военные действия против ночных эльфов он оставляет другим командирам Орды.",al={"karang vs night elves","karang alliance","каранг против ночных эльфов","каранг альянс"}}},fp="14,367,25.418.0,25.359.0,22.190.0,32.102.0,37.160.0,41.190.0,46.136.0,43.211.0"}
P.entries["npc:kargal-battlescar"] = {n="Каргал Боевой Шрам",s="Каргал Боевой Шрам — ветеран, орк-воин на Дальней заставе у восточной границы Степей. Охраняя переправу из Дуротара, он оценивает новобранцев и направляет способных бойцов вглубь земель для усиления обороны Орды.",h="Каргал Боевой Шрам — ветеран, орк-воин на Дальней заставе у восточной границы Степей.",kw={"barrens","battlescar","conscript","crossroads","durotar","far watch post","kargal","степи","боевой шрам","призыв","перекресток","дуротар","дальняя застава","каргал"},ang={["class:Warrior"]="Закаленный в боях ветеран со следами многих сражений, Каргал воплощает суровую стойкость, ожидаемую от бойцов Орды на передовой в диких приграничных землях.",["faction:Horde"]="Для новых искателей приключений Орды, покидающих Дуротар, Каргал Боевой Шрам становится знакомством с более широкой борьбой в Калимдоре: он собирает новобранцев для конфликтов, назревающих в Степях."},sec={{t="Страж границы",b="Неся вахту на Дальней заставе, Каргал Боевой Шрам надзирает за стратегическим рубежом, отделяющим суровые красные равнины Дуротара от обширной саванны Степей. Когда путники и новоприбывшие искатели приключений пересекают мост через Реку Строптивую, Каргал дает им понять, что мирные дни обучения в Долине Испытаний закончились. Степи — спорная и опасная земля, где хозяйничают агрессивные звери, набеги кентавров и племена свинобразов. Каргал осматривает проходящих, призывает желающих на службу Орде и отправляет их дальше, на Перекресток, помогать местным командирам охранять рубеж."}},faq={{q="Кто такой Каргал Боевой Шрам?",a="Каргал Боевой Шрам — орк-воин и командир заставы на Дальней заставе, расположенной у восточной дороги, ведущей из Дуротара в Степи.",al={"kargal battlescar","kargal","who is kargal","каргал боевой шрам","каргал","кто такой каргал"}},{q="Для чего нужна Дальняя застава?",a="Дальняя застава служит пунктом раннего оповещения и передовой обороной Степей от угроз, возникающих у границы Дуротара и вдоль Реки Строптивой.",al={"far watch post purpose","why far watch post","what is this outpost","назначение дальней заставы","зачем дальняя застава","что это за застава"}},{q="Куда Каргал отправляет новобранцев?",a="Каргал призывает путников, проходящих через заставу, и направляет их на запад по главной дороге к Перекрестку, центральному военному узлу Степей.",al={"kargal quest destination","where to go after kargal","where does kargal send you","куда ведет задание каргала","куда идти после каргала","куда каргал отправляет"}}},fp="17,276,22.656.0,25.157.0,42.171.0,36.161.0"}
P.entries["npc:karos-razok"] = {n="Карос Раззок",s="Карос Раззок — Отрекшийся, укротитель летучих мышей в Гробнице в Серебряном бору. Он заведует стаей нежити-летунов, напрямую связывающих этот спорный приграничный форпост с Подгородом и другими оплотами Орды.",h="Карос Раззок — Отрекшийся, укротитель летучих мышей в Гробнице в Серебряном бору.",kw={"bat handler","flight master","karos razok","sepulcher","silverpine forest","undercity","укротитель летучих мышей","мастер полетов","карос раззок","гробница","серебряный бор","подгород"},ang={["faction:Horde"]="Для путников Орды, идущих на юг к Предгорьям Хилсбрада, стая летучих мышей Раззока — незаменимый пункт на западном краю Лордерона.",["race:Undead"]="Карос Раззок — ваша связь с Подгородом: он следит, чтобы усилия на фронте в Серебряном бору оставались прочно связаны со столицей леди Сильваны."},sec={{t="Хранитель крыльев Гробницы",b="На деревянной площадке над склепами Гробницы Карос Раззок ухаживает за скелетами летучих мышей, жизненно важными для связи Отрекшихся. Поскольку Серебряный бор кишит воргенами Лунной Ярости, отступниками-магами Даларана и остатками людей Янтарной мельницы, путь по северной дороге по земле опасен. Раззок следит, чтобы гонцы, новобранцы и необходимые припасы могли пересекать проклятый полог леса по воздуху, удерживая линию фронта связанной со столицей в Тирисфальских лесах."}},faq={{q="Кто такой Карос Раззок?",a="Карос Раззок — мастер полетов из числа Отрекшихся в Гробнице в Серебряном бору. Он управляет стаей обученных вампирических летучих мышей, на которых путешествуют искатели приключений и гонцы Орды по Лордерону.",al={"karos razok role","who is the flight master in the sepulcher","sepulcher bat handler","карос раззок роль","кто мастер полетов в гробнице","укротитель летучих мышей гробницы"}},{q="Куда Карос Раззок может отправить путников?",a="Раззок связывает Гробницу напрямую с Подгородом в Тирисфальских лесах и с Мельницей Таррен в Предгорьях Хилсбрада, обеспечивая быстрое сообщение по северному Лордерону.",al={"sepulcher flight paths","where does the sepulcher bat fly","flight routes from sepulcher","маршруты полета гробница","куда летит летучая мышь гробницы","перелеты из гробницы"}},{q="С какими существами работает Карос?",a="Он ухаживает за крупными скелетами летучих мышей. Эти неживые твари — выносливые, неутомимые летуны, приспособленные к зараженному небу Лордерона; Отрекшиеся ценят их за бесшумность и стойкость.",al={"what mounts does razok have","forsaken flight beasts","what are the flying mounts at sepulcher","какие скакуны у раззока","летающие звери отрекшихся","летающие ездовые гробницы"}},{q="Почему мастер полетов важен в Гробнице?",a="Дороги Серебряного бора забиты враждебными силами — от проклятия воргенов Погребальных Костров до людей-магов Янтарной мельницы. Раззок обеспечивает воздушную связь, позволяющую Отрекшимся снабжать эту передовую базу, не попадая в засады на дороге.",al={"why is sepulcher bat master needed","sepulcher travel importance","зачем нужен мастер полетов в гробнице","важность перелетов гробницы"}}},fp="11,227,31.485.0,19.205.0,37.171.0,33.190.0,50.245.0"}
P.entries["npc:katie-hunter"] = {n="Кати Охотница",s="Кати Охотница — заводчица лошадей на конюшне Лесопилки Восточной долины на востоке Элвиннского леса. Она предоставляет обученных верховых лошадей и рысаков жителям Штормграда и доверенным защитникам Альянса. Вместе с Рэндалом Охотником она обеспечивает путников и солдат надежными скакунами для дорог королевства.",h="Кати Охотница — заводчица лошадей на конюшне Лесопилки Восточной долины на востоке Элвиннского леса.",kw={"eastvale","elwynn forest","horse vendor","katie hunter","logging camp","mounts","stables","stormwind","восточная долина","элвиннский лес","торговец лошадьми","кати охотница","лесопилка","скакуны","конюшни","штормград"},ang={["faction:Alliance"]="Представители союзных рас, заслужившие высокое положение и уважение при дворе Штормграда, могут получить право ездить в бой на холеных рысаках Кати.",["race:Human"]="Для путников-людей конюшни Кати — естественный этап пути: классические лошади Штормграда доступны, как только вы освоите основы верховой езды."},sec={{t="Конюшни Восточной долины",b="В тихих лесных прогалинах Лесопилки Восточной долины Кати Охотница заведует главным конским поголовьем королевства для начинающих всадников Элвиннского леса. Пока лесорубы заготавливают древесину для восстановления Штормграда, Кати ухаживает за конюшнями, выращивая разные надежные породы, включая пегих коней, кобыл и резвых рысаков. Ее лошади — классическая конная традиция королевства, верные спутники, способные пройти опасные дороги южного Азерота."}},faq={{q="Кто такая Кати Охотница?",a="Кати Охотница — заводчица лошадей и торговка скакунами Королевства Штормград; находится на конюшне Лесопилки Восточной долины в Элвиннском лесу.",al={"katie hunter elwynn","who is katie hunter","katie hunter horse vendor","кати охотница элвиннский лес","кто такая кати охотница","кати охотница торговец лошадьми"}},{q="Где найти Кати Охотницу?",a="Она находится в северной части Лесопилки Восточной долины и присматривает за загоном и конюшнями рядом с учителем верховой езды Рэндалом Охотником на востоке Элвиннского леса.",al={"katie hunter location","where is katie hunter","find katie hunter","где кати охотница","местонахождение кати охотницы","найти кати охотницу"}},{q="Могут ли не-люди купить у нее лошадей?",a="Да, но только если они достигли степени уважения «Превознесение» у Королевства Штормград. Люди могут купить ее лошадей без особой репутации.",al={"dwarf buy horse","night elf horse mount","stormwind reputation mount","дворф купить лошадь","ночной эльф лошадь","репутация штормграда скакун"}},{q="Каких лошадей она продает?",a="Katie provides standard riding horses—including pinto, brown, and chestnut varieties—as well as swift, armored steeds such as the Swift Palomino, Swift Brown Steed, and Swift White Steed.",al={"what mounts does katie sell","katie hunter horse types","какие скакуны у кати","виды лошадей кати охотницы"}}},fp="12,339,19.503.0,20.150.0,30.159.0,35.158.0,26.191.0"}
P.entries["npc:katrana-prestor"] = {n="Леди Катрана Престор",s="Леди Катрана Престор — знатная дама Штормграда и один из самых влиятельных голосов при дворе. Пока король Вариан пропал, она стоит рядом с юным королем Андуином и верховным лордом Болваром Фордрагоном в Крепости Штормграда как доверенный советник.",h="Леди Катрана Престор — знатная дама Штормграда и один из самых влиятельных голосов при дворе.",kw={"katrana","prestor","katrana prestor","lady prestor","advisor","stormwind keep","court","катрана","престор","катрана престор","леди престор","советник","крепость штормграда","двор"},sec={{t="Голос двора",b="Леди Престор прибыла ко двору несколько лет назад и быстро стала одной из самых доверенных фигур. Дворяне Штормграда ищут ее благосклонности, а ее советы определяют многие решения, принимаемые от имени юного короля, пока верховный лорд Болвар Фордрагон правит как регент. Просители, приходящие в Крепость Штормграда за солдатами или помощью, часто обнаруживают, что ее мнение весит не меньше, чем мнение регента."}},faq={{q="Кто такая леди Катрана Престор?",a="Леди Катрана Престор — знатная дама Штормграда и доверенный советник при дворе. Пока король Вариан пропал, она стоит рядом с юным королем Андуином и верховным лордом Болваром Фордрагоном в Крепости Штормграда, и ее слово имеет большой вес среди дворян.",al={"who is katrana prestor","who is lady prestor","katrana prestor lore","кто такая катрана престор","кто такая леди престор","катрана престор предания"}},{q="Почему она советует королю?",a="Исчезновение короля Вариана оставило на троне его юного сына Андуина, а верховный лорд Болвар Фордрагон правит как регент. Леди Престор сидит рядом с ними как советник. Многие решения двора, в том числе то, как Штормград отвечает на просьбы о помощи от дальних земель, проходят через ее советы.",al={"why is prestor at court","what does katrana do","почему престор при дворе","чем занимается катрана"}},{q="Где найти леди Престор?",a="Обычно ее можно найти в тронном зале Крепости Штормграда рядом с верховным лордом Болваром Фордрагоном и юным королем Андуином.",al={"where is katrana prestor","katrana prestor location","где катрана престор","местонахождение катраны престор"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="Каймард Меднокноп",s="Каймард Меднокноп — гоблин-торговец, представляющий Пастбища Дымного Леса в Оргриммаре во время праздника Зимнего Покрова. Он стоит в Аллее Силы, торгует праздничными товарами и направляет путников к праздничному веселью и пропавшим праздничным припасам. Его бойкая торговля приносит в столицу Орды сезонное веселье — и гоблинскую коммерческую предприимчивость.",h="Каймард Меднокноп — гоблин-торговец, представляющий Пастбища Дымного Леса в Оргриммаре во время праздника...",kw={"copperpinch","goblin","kaymard","metzen","orgrimmar","smokywood pastures","valley of strength","winter veil","меднокноп","гоблин","каймард","метцен","оргриммар","пастбища дымного леса","аллея силы","зимний покров"},ang={["faction:Horde"]="Для Орды Каймард воплощает коммерческую сторону Зимнего Покрова в Оргриммаре, сочетая традиционные зимние торжества с гоблинской предприимчивостью.",["profession:Cooking"]="Каймард и его коллеги из Пастбищ Дымного Леса поставляют сезонные рецепты и особые ингредиенты, необходимые для выпечки традиционных праздничных лакомств."},sec={{t="Зимний Покров по-гоблински",b="Когда наступает праздник Зимнего Покрова, Пастбища Дымного Леса открывают лавку прямо в шумной Аллее Силы в Оргриммаре, и возглавляет ее предприимчивый Каймард Меднокноп. Пока неподалеку Дедушка Зима принимает гостей, Каймард следит, чтобы сезон оставался прибыльным. Он продает изысканные лакомства, праздничную оберточную бумагу и все необходимое для торжества и воплощает гоблинский взгляд: ни один великий праздник не обходится без оживленного обмена монет."},{t="Праздничные хлопоты",b="Помимо торговли праздничным товаром, Каймард часто выступает связующим звеном в сезонных неприятностях, преследующих Пастбища Дымного Леса. От украденных партий праздничных сладостей до загадочного исчезновения оленя Метцена — Каймард охотно привлекает искателей приключений из Орды, чтобы разобраться с бедой в снегах и не дать празднику сорваться."}},faq={{q="Кто такой Каймард Меднокноп?",a="Каймард Меднокноп — гоблин-торговец, связанный с Пастбищами Дымного Леса. Во время праздника Зимнего Покрова он работает в Аллее Силы в Оргриммаре, продает сезонные товары высшего качества и дает прохожим праздничные поручения.",al={"who is kaymard","kaymard copperpinch lore","what does kaymard do","кто такой каймард","каймард меднокноп предания","чем занимается каймард"}},{q="Что такое Пастбища Дымного Леса?",a="Пастбища Дымного Леса — торговое объединение, которое занимается едой, лакомствами и сезонными товарами праздника Зимнего Покрова по всему Азероту. Оно снабжает праздничными товарами и Орду, и Альянс, получая при этом немалую прибыль.",al={"what is smokywood pastures","who does he work for","smokywood pastures lore","что такое пастбища дымного леса","на кого он работает","пастбища дымного леса предания"}},{q="Где найти Каймарда Меднокнопа?",a="Его можно найти в Аллее Силы в Оргриммаре, возле центральной праздничной витрины, где во время Зимнего Покрова сидит Дедушка Зима.",al={"kaymard location","where is kaymard copperpinch","where is he in orgrimmar","где каймард","где найти каймарда меднокнопа","где он в оргриммаре"}},{q="Почему он просит искателей приключений о помощи во время праздников?",a="Пастбища Дымного Леса часто сталкиваются с логистическими бедами во время Зимнего Покрова: у них крадут праздничные сладости и похищают любимого оленя Метцена. Каймард нанимает желающих искателей приключений, чтобы вернуть пропажу и уберечь сезонную прибыль.",al={"kaymard quests","winter veil treats quest","metzen quest horde","задания каймарда","задание лакомства зимнего покрова","задание метцен орда"}}},fp="19,352,22.459.0,21.345.0,27.228.0,27.234.0,37.172.0,57.259.0"}
P.entries["npc:keeper-albagorm"] = {n="Хранитель Албагорм",s="Хранитель Албагорм — хранитель рощи, живущий в уединенном убежище на Пике Каменного Когтя. Глубоко встревоженный разрухой, отравляющей южные части гор, он привлекает путников к исцелению выжженных земель Обугленной долины.",h="Хранитель Албагорм — хранитель рощи, живущий в уединенном убежище на Пике Каменного Когтя.",kw={"cenarius","charred vale","keeper albagorm","keeper of the grove","stonetalon","stonetalon peak","кенарий","обугленная долина","хранитель албагорм","хранитель рощи","когтистые горы","пик каменного когтя"},ang={["class:Druid"]="Как хранитель рощи, Албагорм напрямую связан с родом Кенария, поэтому его усилия по очищению Обугленной долины особенно близки друидам.",["faction:Alliance"]="Албагорм предлагает приют и наставления силам Альянса, пробирающимся через убежище ночных эльфов на Пике Каменного Когтя."},sec={{t="Страж на Пике",b="Среди мирных ветвей Пика Каменного Когтя Хранитель Албагорм бдительно охраняет одно из священных эльфийских убежищ Калимдора. Как и многие сыновья Кенария, он остро чувствует боль природы. Его взгляд обращен на юг, к дымящимся руинам Обугленной долины, подожженной алчной механизированной армией промышленников, а ныне занятой гарпиями Кровавой Ярости, которые не дают земле возродиться. Из своего убежища Албагорм неустанно трудится, чтобы остановить распространение порчи и восстановить равновесие в израненном лесу."}},faq={{q="Кто такой Хранитель Албагорм?",a="Он хранитель рощи — один из полубожественных отпрысков Кенария — и живет на Пике Каменного Когтя в Когтистых горах. Он союзник ночных эльфов и природных стражей Калимдора.",al={"keeper albagorm","who is albagorm","albagorm stonetalon","хранитель албагорм","кто такой албагорм","албагорм когтистые горы"}},{q="Где найти Хранителя Албагорма?",a="Он обитает на Пике Каменного Когтя — лояльном Альянсу убежище друидов, расположенном высоко в северо-западном углу Когтистых гор.",al={"keeper albagorm location","where is albagorm","albagorm coords","где хранитель албагорм","где албагорм","координаты албагорма"}},{q="С чем Хранителю Албагорму нужна помощь?",a="Албагорм стремится исцелить разруху Обугленной долины. Он посылает умелых искателей приключений в усыпанную пеплом котловину, чтобы очистить оскверненные земли и изгнать гарпий Кровавой Ярости, мешающих природе возродиться.",al={"keeper albagorm quests","what does albagorm want","reclaiming the charred vale","задания хранителя албагорма","чего хочет албагорм","возрождение обугленной долины"}}},fp="15,260,22.526.0,23.205.0,33.134.0,41.213.0"}
P.entries["npc:keeper-bel-dugur"] = {n="Хранитель Бел'дугур",s="Хранитель Бел'дугур — ученый Отрекшийся, живущий в глубинах Апотекариума Подгорода. Он служит своему народу, снаряжая экспедиции за темными томами и магическими артефактами по всему Азероту.",h="Хранитель Бел'дугур — ученый Отрекшийся, живущий в глубинах Апотекариума Подгорода.",kw={"apothecarium","bel'dugur","keeper beldugur","shadowfang","the book of ur","undercity","апотекариум","бел'дугур","хранитель белдугур","темный клык","книга ура","подгород"},ang={["class:Warlock"]="Чернокнижники часто сталкиваются с поручениями Бел'дугура: его интересы тесно связаны с опасными гримуарами, призывом из иных миров и темным оккультизмом.",["race:Undead"]="Бел'дугур кажется обычным ученым Отрекшимся, ищущим запретные знания для укрепления вашего королевства, но его истинные устремления лежат вне выживальческого дела Королевы банши."},sec={{t="Собиратель темных реликвий",b="Среди чанов и исследователей Апотекариума Хранитель Бел'дугур поручает искателям приключений добывать опасные арканные и оккультные реликвии по всему Азероту. Особый его интерес — Книга Ура, легендарный трактат о существах из иных измерений, запертый в Крепости Темного Клыка. Пока многие в Подгороде ищут магические знания, чтобы излечить состояние нежити или обратить его в оружие, приобретения Бел'дугура, похоже, направлены на раскрытие древних запретных сил."},{t="Скрытая верность",b="За спокойными манерами исследователя Подгорода скрывается тайная преданность апокалиптическому культу Сумеречного Молота. Задания и исследовательские поручения Бел'дугура тихо служат тайным целям культа: он добывает основополагающие гримуары призыва и магии Бездны под носом у ничего не подозревающих Королевского фармацевтического общества и леди Сильваны."}},faq={{q="Где найти Хранителя Бел'дугура?",a="Хранитель Бел'дугур находится в Апотекариуме — алхимическом квартале в южной части нижнего кольца Подгорода.",al={"keeper bel'dugur location","where is beldugur","beldugur map","хранитель бел'дугур где","где белдугур","карта белдугура"}},{q="Зачем Бел'дугуру Книга Ура?",a="Книга Ура содержит основополагающие исследования даларанского мага Ура о других измерениях и диких воргенах. Бел'дугур стремится использовать эти запретные принципы призыва для темных замыслов своих истинных хозяев.",al={"why book of ur","what does beldugur do with book of ur","зачем книга ура","что белдугур делает с книгой ура"}},{q="Верен ли Хранитель Бел'дугур леди Сильване?",a="Внешне он служит архивистом и исследователем Отрекшихся, но тонкие намеки в его изысканиях говорят о том, что его верность может принадлежать другим.",al={"is beldugur evil","beldugur faction","who does beldugur serve","белдугур злодей","фракция белдугура","кому служит белдугур"}},{q="Какие еще задания он дает искателям приключений?",a="Помимо Книги Ура из Крепости Темного Клыка, Бел'дугур направляет путников к забытым знаниям и запретным томам, в том числе к темным трактатам, связанным с древними ритуалами и запретным знанием.",al={"beldugur quests","keeper beldugur quests","задания белдугура","задания хранителя белдугура"}}},fp="16,211,26.501.0,16.349.2,34.129.0,39.227.1,43.155.2,42.181.0"}
P.entries["npc:keeper-bel-varil"] = {n="Хранитель Бел'варил",s="Хранитель Бел'варил — Отрекшийся смотритель и исследователь на Мельнице Таррен в Предгорьях Хилсбрада. Работая бок о бок с Вордином Войдглером, он направляет искателей приключений из Орды собирать магические реликвии и связующие материалы в окрестных землях для их оккультных исследований.",h="Хранитель Бел'варил — Отрекшийся смотритель и исследователь на Мельнице Таррен в Предгорьях Хилсбрада.",kw={"bel'varil","bracers of binding","hillsbrad foothills","keeper bel'varil","stone tokens","tarren mill","wordeen voidglare","бел'варил","наручи связывания","предгорья хилсбрада","хранитель бел'варил","каменные жетоны","мельница таррен","вордин войдглер"},ang={["faction:Horde"]="Героям Орды, сражающимся в Предгорьях Хилсбрада, Бел'варил предлагает практические награды за усмирение стихийных угроз и возвращение связывающих амулетов.",["race:Undead"]="Работа Бел'варила отражает стремление Отрекшихся к арканному мастерству и находчивости: тщательно изучая местные реликвии, они получают преимущество в Лордероне."},sec={{t="Исследования на Мельнице Таррен",b="В осажденной деревне — Мельнице Таррен — Хранитель Бел'варил тихо поддерживает магические и алхимические исследования Отрекшихся. Пока королевские аптекари и солдаты заняты гарнизоном Альянса неподалеку, в Южнобережье, Бел'варил занимается практическим колдовством и отправляет путников за каменными жетонами и связывающими наручами к ближайшим стихийным и зачарованным угрозам."}},faq={{q="Кто такой Хранитель Бел'варил?",a="Хранитель Бел'варил — ученый Отрекшийся на Мельнице Таррен в Предгорьях Хилсбрада. Он помогает коллеге-исследователю Вордину Войдглеру изучать магические артефакты и реагенты, найденные на спорной территории.",al={"keeper belvaril","who is belvaril","belvaril tarren mill","хранитель бел'варил","кто такой бел'варил","бел'варил мельница таррен"}},{q="Где найти Хранителя Бел'варила?",a="Его можно найти в поселении Отрекшихся на Мельнице Таррен на севере Предгорий Хилсбрада.",al={"belvaril location","where is keeper bel'varil","find keeper bel'varil","где бел'варил","где хранитель бел'варил","найти хранителя бел'варила"}},{q="Какие задания предлагает Хранитель Бел'варил?",a="Он привлекает искателей приключений из Орды к сбору магических остатков, таких как каменные жетоны и наручи связывания, помогая своему кругу понимать стихийные силы и управлять ими.",al={"belvaril quests","keeper bel'varil tasks","задания бел'варила","задания хранителя бел'варила"}}},fp="16,289,20.386.0,24.217.0,34.109.0,39.164.0"}
P.entries["npc:keldran"] = {n="Кельдран",s="Кельдран — орк-тайный агент, находящийся к северу от Аллеи Духов в Оргриммаре. Стремясь проложить путь к будущей дипломатии с Альянсом, он координирует тайные удары по остаткам демонов, чтобы доказать, что нынешняя Орда действительно отреклась от Пылающего Легиона.",h="Кельдран — орк-тайный агент, находящийся к северу от Аллеи Духов в Оргриммаре.",kw={"alliance relations","burning blade","desolace","keldran","maurin bonesplitter","orgrimmar","takata steelblade","valley of spirits","отношения с альянсом","пылающий клинок","пустоши","кельдран","маурин костолом","оргриммар","таката стальной клинок","аллея духов"},ang={["class:Warlock"]="Тайная война Кельдрана против Пылающего Клинка показывает, насколько сильно руководство Орды стремится дистанцироваться от неконтролируемой демонической порчи.",["faction:Horde"]="Кельдран представляет дальновидную часть Орды, которая понимает острую необходимость избавиться от демонической репутации, если она хочет добиться прочного мира в Калимдоре."},sec={{t="Дипломатический поход",b="Пока Тралл правит из Аллеи Мудрости, Кельдран работает на красных скалистых террасах города, пытаясь исправить затянувшуюся дипломатическую беду. Альянс по-прежнему считает всех орков кровожадными марионетками демонических повелителей — репутация, закрепившаяся в первых войнах. Убежденный, что даже Тралл устал от бесконечного конфликта, Кельдран считает, что настоящие мирные переговоры невозможны, пока в Калимдоре существуют культы поклонников демонов. Без официального одобрения Вождя он берет инициативу на себя, направляя доверенных агентов к далеким угрозам, чтобы раз и навсегда уничтожить демоническое пятно."},{t="Война в Пустошах",b="Чтобы подкрепить свои доводы перед Альянсом, Кельдран выбрал мрачные земли Пустошей. Он отправил Такату Стального Клинка и Маурина Костолома возглавить операции против демонического нашествия, особенно настаивая на уничтожении культистов Пылающего Клинка. Истребив этих демонопоклонников и принеся в Оргриммар осязаемые доказательства, Кельдран надеется неопровержимо показать, что новая Орда такой же враг Легиона, как люди и ночные эльфы."}},faq={{q="Кто такой Кельдран?",a="Кельдран — орк к северу от Аллеи Духов в Оргриммаре, который организует усилия по искоренению демонического влияния и открытию пути к дипломатическим отношениям с Альянсом.",al={"who is keldran","keldran lore","keldran npc","кто такой кельдран","кельдран предания","кельдран персонаж"}},{q="Почему Кельдрана волнуют отношения с Альянсом?",a="Кельдран полагает, что Тралл устает от непрерывной войны с Альянсом. Он знает, что мирные переговоры останутся невозможными, пока Альянс считает, что Орда по-прежнему в союзе с Пылающим Легионом.",al={"why alliance relations","keldran motives","why does he want peace","почему отношения с альянсом","мотивы кельдрана","почему он хочет мира"}},{q="Действует ли Кельдран по официальному приказу Тралла?",a="Нет. У Кельдрана нет официального разрешения вождя Тралла на его операцию: он действует самостоятельно, чтобы очистить имя Орды и заложить основу для будущего мира.",al={"did thrall send keldran","thrall orders keldran","is keldran sanctioned","тралл послал кельдрана","приказы тралла кельдрану","одобрен ли кельдран"}},{q="Чем занимается Кельдран в Пустошах?",a="Он отправил Такату Стального Клинка и Маурина Костолома в Пустоши, чтобы уничтожить местные демонические силы и решительно истребить присутствие культа Пылающего Клинка.",al={"desolace operation","why desolace","keldran burning blade","операция в пустошах","почему пустоши","кельдран пылающий клинок"}}},fp="7,277,20.591.0,19.487.1,15.181.0,56.212.0,49.177.0,34.166.0"}
P.entries["npc:kelm-hargunth"] = {n="Кельм Харгюнт",s="Кельм Харгюнт — главный офицер снабжения и интендант Всадников Песни Войны, расквартированный в Лагере Мор'шан на северной границе Степей. Он снаряжает защитников Орды, сражающихся с ночными эльфами в спорных лесах Ущелья Песни Войны. Посылками и провизией он обеспечивает бесперебойное снабжение фронта.",h="Кельм Харгюнт — главный офицер снабжения и интендант Всадников Песни Войны, расквартированный в Лагере...",kw={"barrens","care package","kelm hargunth","mor'shan base camp","pvp vendor","quartermaster","warsong gulch","warsong outriders","степи","посылка","кельм харгюнт","лагерь мор'шан","пвп торговец","интендант","ущелье песни войны","всадники песни войны"},ang={["class:Warrior"]="Воины переднего края во многом полагаются на прочные латные поножи, тяжелые клинки и пайки Харгюнта, чтобы удерживать строй против Альянса.",["faction:Horde"]="Кельм Харгюнт снабжает оружием любого солдата Орды, готового взяться за оружие против ночных эльфов в Ущелье Песни Войны.",["race:Orc"]="Для орков Харгюнт следит, чтобы наследие Грома Адский Крик в Ясеневом лесу не угасло: клан Песни Войны остается вооруженным и сытым."},sec={{t="Интендант Мор'шана",b="Кельм Харгюнт расположился на земляных валах с видом на Ясеневый лес и руководит снабжением Всадников Песни Войны в Лагере Мор'шан. Пока разведчики и налетчики сражаются за частоколом, Харгюнт распределяет оружие, доспехи и пайки, необходимые для затяжной пограничной войны. По его мнению, победа над Среброкрылыми Часовыми зависит не только от ярости в бою, но и от бесперебойных поставок."},{t="Помощь фронту",b="Харгюнт выдает особые припасы воинам, доказавшим доблесть в ущелье. От посылок с полевыми повязками и железными пайками до искусно изготовленного вооружения с алой эмблемой клана Песни Войны — его запасы предназначены лишь тем, кто проливает кровь за территориальные притязания Орды в богатых лесом землях к северу."}},faq={{q="Кто такой Кельм Харгюнт?",a="Кельм Харгюнт — орк, офицер снабжения Всадников Песни Войны. Он служит в Лагере Мор'шан на севере Степей и раздает оружие, доспехи и боевое снаряжение солдатам Орды, сражающимся в Ущелье Песни Войны.",al={"kelm hargunth","who is kelm","mor'shan vendor","warsong vendor","кельм харгюнт","кто такой кельм","торговец мор'шана","торговец песни войны"}},{q="Где находится Кельм Харгюнт?",a="Он находится в Лагере Мор'шан на дальнем севере Степей, у линии валов, ведущей в Ясеневый лес.",al={"kelm location","where is kelm hargunth","mor shan supply officer location","где кельм","где кельм харгюнт","офицер снабжения мор'шан где"}},{q="Какой фракции служит Кельм Харгюнт?",a="Он служит Всадникам Песни Войны — авангарду Орды, который добывает древесину и захватывает земли на юге Ясеневого леса в борьбе с ночными эльфами.",al={"kelm faction","warsong outriders quartermaster","who does kelm work for","фракция кельма","интендант всадников песни войны","на кого работает кельм"}},{q="Какие посылки предлагает Кельм?",a="Харгюнт выдает бойцам переднего края простые, обычные и улучшенные посылки. В этих наборах есть необходимые боевые мелочи, бинты и пайки, чтобы бойцы Орды могли продержаться в ущелье.",al={"outrider care package","kelm care package","warsong care package","посылка всадников","посылка кельма","посылка песни войны"}},{q="Почему Лагерь Мор'шан так важен для клана Песни Войны?",a="Лагерь Мор'шан — укрепленный плацдарм и контрольный пункт между Степями и Ясеневым лесом. Через него клан Песни Войны безопасно доставляет в земли Орды припасы, подкрепления и заготовленную древесину.",al={"why morshan base camp","morshan purpose","base camp lore","почему лагерь мор'шан","назначение мор'шана","предания лагеря"}},{q="Какое снаряжение предлагает Кельм Харгюнт?",a="Он снаряжает проверенных бойцов боевыми накидками Песни Войны, особым оружием вроде Клинка разведчика и Меча легионера, подогнанными комплектами доспехов, кольцами и боевыми зельями для ближних схваток.",al={"kelm pvp gear","warsong rewards","what does kelm sell","пвп снаряжение кельма","награды песни войны","что продает кельм"}}},fp="13,368,25.422.0,19.376.0,21.229.0,31.145.0,38.150.0,39.217.0,54.220.0,45.216.0"}
P.entries["npc:kerlonian-evershade"] = {n="Керлониан Вечный Сумрак",s="Керлониан Вечный Сумрак — ночной эльф, Друид-медведь, отдыхающий в Роще Древних на Темных берегах. Недавно очнувшись от долгого сна в Изумрудном Сне, он нуждается в помощи, чтобы пройти через оскверненные земли и добраться до безопасной Заставы Мейстры.",h="Керлониан Вечный Сумрак — ночной эльф, Друид-медведь, отдыхающий в Роще Древних на Темных берегах.",kw={"darkshore","druid of the claw","emerald dream","evershade","grove of the ancients","kerlonian","the sleeper has awakened","темные берега","друид-медведь","изумрудный сон","вечный сумрак","роща древних","керлониан","спящий пробудился"},ang={["class:Druid"]="Друиды-искатели приключений хорошо поймут беду Керлониана, ведь всем последователям Круга Кенария приходится справляться с тяжелой платой за глубокое единение с Изумрудным Сном.",["race:NightElf"]="Для путников-ночных эльфов сопровождение Керлониана означает защиту одного из древних защитников их народа, только что вернувшегося в мир, сильно изменившийся после Третьей войны."},sec={{t="Пробуждение на Темных берегах",b="Керлониан Вечный Сумрак принадлежит к Друидам-медведям, последователям тотема медведя, которые веками спали в курганах, пребывая в единении с Изумрудным Сном. После Третьей войны многие друиды пробудились растерянными в мире, разоренном порчей. Керлониан найден отдыхающим под древними деревьями Рощи Древних; он все еще не может стряхнуть сверхъестественную дремоту долгого отдыха. Сейчас его главная забота — безопасно пройти по тревожным лесам Темных берегов к Заставе Мейстры на границе Ясеневого леса."},{t="Опасный путь",b="Дорога из Рощи Древних далеко не безопасна. Распространяющаяся скверна на Темных берегах растревожила местных зверей и привела хищников и греллов к священным полянам. Ослабленный сном и страдающий от внезапных приступов усталости, Керлониан рассчитывает на отзывчивых путников из Альянса, которые защитят его по пути на юг к собратьям — ночным эльфам."}},faq={{q="Кто такой Керлониан Вечный Сумрак?",a="Керлониан Вечный Сумрак — ночной эльф, Друид-медведь, находящийся неподалеку от Рощи Древних на Темных берегах. Он недавно очнулся от Изумрудного Сна и нуждается в помощи, чтобы безопасно пройти через лес.",al={"who is kerlonian","kerlonian evershade lore","druid in grove of the ancients","кто такой керлониан","керлониан вечный сумрак предания","друид в роще древних"}},{q="Почему Керлониан засыпает на ходу?",a="Как и многие Друиды-медведи, веками спавшие в курганных логовах, Керлониан все еще страдает от остаточного оцепенения Изумрудного Сна. Его тело и разум еще не приспособились к яви, отчего на него внезапно накатывает сонливость.",al={"why is kerlonian sleeping","sleeper has awakened quest druid","kerlonian sleepy","почему керлониан спит","спящий пробудился задание друид","керлониан сонный"}},{q="Куда он пытается добраться?",a="Он ищет безопасный путь на юг, к Заставе Мейстры — форпосту ночных эльфов на границе Темных берегов и Ясеневого леса, где он сможет спокойно восстановить силы.",al={"kerlonian destination","where does kerlonian go","grove of the ancients escort destination","цель керлониана","куда идет керлониан","цель сопровождения в роще древних"}},{q="Кто такие Друиды-медведи?",a="Друиды-медведи — ночные эльфы-друиды, почитающие древнего медведя Урсока. Они черпают силу, стойкость и мощь зверя, традиционно охраняют курганы и земли ночных эльфов, а столетиями спят в Изумрудном Сне.",al={"what is druid of the claw","druids of the claw lore","что такое друид-медведь","друиды-медведи предания"}}},fp="19,262,22.554.0,21.395.0,27.204.0,45.243.0,25.154.0,28.229.0"}
P.entries["npc:kernobee"] = {n="Керноби",s="Керноби — гоблин-инженер, оказавшийся в ловушке в разрушенных залах Гномрегана. Наткнувшись на опасные тайны о саботаже дворфов из клана Черного Железа, он был схвачен, избит до потери сознания и брошен умирать среди троггов в жилых помещениях Общежития.",h="Керноби — гоблин-инженер, оказавшийся в ловушке в разрушенных залах Гномрегана.",kw={"dark iron","dormitory","gnomeregan","kernobee","ratchet","super rig","tinkerwiz","черное железо","общежитие","гномреган","керноби","кабестан","буровая установка","тинквиз"},ang={["profession:Engineering"]="Инженеры понимают, насколько опасно копаться в экспериментальных подземных механизмах вроде установок Черного Железа, когда на кону чертежи соперников.",["race:Gnome"]="Для гномов, сражающихся за возвращение родины, сведения Керноби — тревожное доказательство того, что катастрофе из тени способствовало вмешательство дворфов Черного Железа."},sec={{t="Смертельное открытие",b="Занимаясь делами или собирая добычу в павшей столице гномов, Керноби раскрыл страшную тайну: дворфы Черного Железа напрямую участвовали в постройке и работе огромной буровой установки под городом. Поняв ценность и смертельную опасность этих сведений, он попытался немедленно бежать в Кабестан, чтобы передать весть своему напарнику Тинквизу. К несчастью, дворфы Черного Железа поймали его до побега."},{t="Брошен троггам",b="Вместо того чтобы убить его сразу, похитители избили Керноби до беспамятства и бросили в небольшую комнату в коридоре Общежития, напротив Чистой зоны. Оставленный среди диких троггов и радиоактивных осадков, избитый гоблин всецело надеется на искателей приключений, которые приведут его в чувство и защитят, пока он не доберется до безопасного места."}},faq={{q="Кто такой Керноби?",a="Керноби — гоблин-агент, найденный без сознания в Общежитии Гномрегана. Он тесно сотрудничает с Тинквизом из Кабестана и отправился в руины, но попал в засаду.",al={"who is this goblin","kernobee lore","about kernobee","кто этот гоблин","керноби предания","о керноби"}},{q="Почему Керноби заточили в Гномрегане?",a="Керноби узнал, что клан Черного Железа тайно помогает строить подземные буровые машины в городе. Чтобы скрыть свое присутствие и саботаж, дворфы Черного Железа вывели его из строя и бросили в Общежитии умирать.",al={"why is he here","why did dark irons capture him","why in dormitory","почему он здесь","почему дворфы черного железа схватили его","почему в общежитии"}},{q="Кому подчиняется Керноби?",a="Он подчиняется Тинквизу, гоблину-инженеру, находящемуся за морем в нейтральном портовом городе Кабестан в Степях.",al={"who is tinkerwiz","where is he going","ratchet connection","кто такой тинквиз","куда он идет","связь с кабестаном"}},{q="Где в Гномрегане находится Керноби?",a="Он лежит без сознания в небольшой боковой комнате на нижнем уровне Общежития, на западной стороне, прямо напротив Чистой зоны.",al={"kernobee location","where is kernobee","find kernobee","где керноби","местонахождение керноби","найти керноби"}}},fp="8,253,18.470.0,19.335.0,16.180.0,42.247.0,28.119.0,40.149.0"}
P.entries["npc:keryn-sylvius"] = {n="Керин Сильвиус",s="Керин Сильвиус — человек, наставница разбойников на втором этаже таверны Гордость Льва в Златоземье. Скрывшись в читальной комнате таверны, она обучает начинающих плутов основам скрытности и владения клинком и тихо связывает их с разведкой Штормграда.",h="Керин Сильвиус — человек, наставница разбойников на втором этаже таверны Гордость Льва в Златоземье.",kw={"elwynn forest","goldshire","keryn sylvius","lion's pride inn","rogue trainer","si:7","элвиннский лес","златоземье","керин сильвиус","таверна гордость льва","наставник разбойников","шру"},ang={["class:Rogue"]="Сильвиус — главная наставница начинающих разбойников, бродящих по Элвиннскому лесу; со временем она направляет их к штаб-квартире ШРУ в Штормграде.",["faction:Alliance"]="Находясь над перекрестком Златоземья, она помогает тайным глазам Альянса следить за главными дорогами Элвинна."},sec={{t="Тихое присутствие в Златоземье",b="Пока на первом этаже таверны Гордость Льва шумят путники и усталые городские стражи, Керин Сильвиус остается в тихой читальной комнате наверху. Внешне неприметная, она наблюдает за потоком дорожных слухов и служит местной наставницей для разбойников, набирающихся опыта в Элвиннском лесу. Когда многообещающие агенты перерастают мелкое воровство и придорожные проделки, Сильвиус незаметно отправляет их в Штормград для встречи с ШРУ."}},faq={{q="Где найти Керин Сильвиус?",a="Она находится на втором этаже таверны Гордость Льва в Златоземье, в уединенной небольшой читальной комнате.",al={"keryn sylvius location","where is keryn","goldshire rogue trainer location","где керин сильвиус","где керин","наставник разбойников златоземья где"}},{q="Какие услуги она предлагает?",a="Керин Сильвиус — наставница разбойников: она обучает новым умениям, сбрасывает таланты и дает направление развивающимся разбойникам.",al={"what does keryn do","can she train me","keryn sylvius role","что делает керин","может ли она обучить меня","роль керин сильвиус"}},{q="Как она связана с ШРУ?",a="Сильвиус служит первым контактом для тайной разведывательной сети Штормграда: она отправляет способных агентов, доказавших свои умения, искать Мастера Матиаса Шоу и ШРУ в Старом городе.",al={"keryn si7","is she si:7","does she work for stormwind","керин шру","работает ли она на шру","служит ли она штормграду"}}},fp="13,279,29.470.0,31.108.0,29.135.0,38.201.0"}
P.entries["npc:khelden-bremen"] = {n="Кельден Бремен",s="Кельден Бремен — человек, маг и наставник на верхнем этаже Аббатства Североземья в Элвиннском лесу. Он руководит первым обучением начинающих магов, которые изучают тайные искусства на службе Штормграду.",h="Кельден Бремен — человек, маг и наставник на верхнем этаже Аббатства Североземья в Элвиннском лесу.",kw={"arcane","elwynn forest","glyphic letter","khelden bremen","mage trainer","northshire abbey","тайная магия","элвиннский лес","символьное письмо","кельден бремен","наставник магов","аббатство североземья"},ang={["class:Mage"]="Для магов-людей Кельден Бремен — первый формальный шаг к изучению тайной магии, прежде чем продолжить углубленное обучение в башнях Штормграда."},sec={{t="Наставник тайных искусств",b="В спокойных каменных стенах Аббатства Североземья Кельден Бремен служит главным наставником начинающих магов-людей. Пока духовенство и защитники занимаются внизу воинскими и духовными делами, Бремен ведет тихие занятия наверху. Здесь он знакомит новичков с дисциплиной, сосредоточенностью и основами техники, нужными для безопасного управления сырой магической энергией, прежде чем они отправятся в Элвиннский лес и дальше, в Квартал магов Штормграда."}},faq={{q="Кто такой Кельден Бремен?",a="Кельден Бремен — местный наставник магов в Аббатстве Североземья в Элвиннском лесу. Он ведет только пробудившихся магов через первые заклинания и основы тайных наук.",al={"who is khelden","bremen","mage trainer northshire","кто такой кельден","бремен","наставник магов североземья"}},{q="Где найти Кельдена Бремена?",a="Он находится на втором этаже Аббатства Североземья. Войдите в аббатство и поднимитесь по лестнице во второй комнате слева.",al={"where is khelden","khelden bremen location","northshire mage trainer location","где кельден","где кельден бремен","наставник магов североземья где"}},{q="Какую роль он играет для новых искателей приключений?",a="Начинающих магов-людей по прибытии в Североземье направляют к Кельдену, часто с рекомендательным Символьным письмом. Он обучает важным первым заклинаниям и помогает новичкам раскрыть магические способности.",al={"what does khelden do","bremen quests","glyphic letter recipient","что делает кельден","задания бремена","получатель символьного письма"}}},fp="14,225,19.459.0,22.172.0,32.134.0,43.205.0"}
P.entries["npc:kil-hala"] = {n="Кил'хала",kw={"barrens","crossroads","kil'hala","kilhala","laughing sisters","nether-lace","tailoring","trainer","степи","перекресток","кил'хала","смеющиеся сестры","кружево пустоты","портняжное дело","учитель"},ang={["faction:Horde"]="Снабжая тканями и обучая ремеслу на Перекрестке, Кил'хала помогает вооружить воинов и путников, закрепляющихся в Степях.",["profession:Tailoring"]="Кил'хала — важная остановка для портных Орды, путешествующих по Калимдору: он обучает приемам ремесла и дает задания на создание редких магических одеяний."},sec={{t="Портной из Степей",b="Кил'хала расположился в шумном центре Перекрестка и делится портняжным мастерством с проезжими путниками и новобранцами Орды. Хотя большая часть его ремесла — это обычные рулоны ткани и одежда для жизни в сухих степях, его знания простираются и на редкие магические ткани. Чтобы создать поистине замечательные одеяния, Кил'хала предлагает ткачам отправиться в дикие кроны Ясеневого леса, где у волшебных дриад можно добыть неземные материалы, такие как кружево Пустоты."}},faq={{q="Кто такой Кил'хала?",a="Кил'хала — тролль из племени Черного Копья и учитель портняжного дела на Перекрестке в Степях. Он помогает ремесленникам Орды освоить основы ткачества и пошива одежды.",al={"kilhala identity","who is kilhala","crossroads tailor","кто такой кил'хала","кил'хала","портной на перекрестке"}},{q="Где найти Кил'хала?",a="Он находится в Степях, в центральном поселении — на Перекрестке, рядом с другими учителями ремесел Орды.",al={"kilhala location","where is kilhala","kilhala spot","где кил'хала","местонахождение кил'хала","как найти кил'хала"}},{q="Какие задания Кил'хала дает портным?",a="Ткачам, желающим освоить сложное портняжное дело, он велит отправиться в Ясеневый лес и охотиться на дриад, известных как Смеющиеся сестры. Из их неземных локонов Кил'хала создает уникальное Одеяние из кружева Пустоты.",al={"kilhala quests","laughing sisters quest","nether lace garment","задания кил'хала","смеющиеся сестры","одеяние из кружева пустоты"}}},fp="8,339,21.461.0,16.189.0,26.124.0,41.197.0"}
P.entries["npc:kin-weelay"] = {n="Кин'вилай",s="Кин'вилай — известный знахарь племени Черного Копья, который находится в Лагере Гром'гол в Тернистой долине. Присланный прямо из Оргриммара, он оказывает авангарду Орды в джунглях мистическую помощь и дает советы. Его духовные познания жизненно важны для снятия темного моджо и спасения юного Йенику.",h="Кин'вилай — известный знахарь племени Черного Копья, который находится в Лагере Гром'гол в Тернистой долине.",kw={"darkspear","grom'gol","kin'weelay","kinweelay","mind's eye","stranglethorn","witch doctor","yenniku","черное копье","гром'гол","кин'вилай","око разума","тернистая долина","знахарь","йенику"},ang={["faction:Horde"]="Кин'вилай показывает ценность одухотворенности троллей для военных усилий Орды, предлагая магические средства против угроз, которые не одолеть одной силой.",["race:Troll"]="Для троллей племени Черного Копья Кин'вилай — один из самых уважаемых духовных наставников племени, посвятивший себя снятию жестоких проклятий их лесных сородичей."},sec={{t="Мастер моджо Черного Копья",b="Кин'вилай признан одним из самых могущественных знатоков традиционного колдовства среди племени Черного Копья и глубоко знает духов, порчу и магию душ. Когда возникают дела, связанные с духами предков или враждебными чарами троллей, разведчики Орды в Тернистой долине обращаются к нему, чтобы прорвать магическую завесу."},{t="Миссия в Гром'гол",b="Кин'вилай был отправлен на юг из пыльных улиц Оргриммара специально для поддержки Нимбойи в Лагере Гром'гол. Его цель не ограничивается военной поддержкой: он стремится разрушить зловещие путы, наложенные на Йенику, похищенного сына из доверенного рода вождя Вол'джина. Чтобы разрушить такое темное колдовство, Кин'вилай ищет мощные реагенты, прежде всего Око разума, чтобы создать камень душ, способный освободить плененные духи."}},faq={{q="Кто такой Кин'вилай?",a="Кин'вилай — уважаемый тролль-знахарь из племени Черного Копья, находящийся в Лагере Гром'гол на севере Тернистой долины. Известный мастерством в магии духов и душ, он был послан руководством Орды из Оргриммара.",al={"kinweelay lore","who is kin'weelay","gromgol witch doctor","кин'вилай","кто такой кин'вилай","знахарь гром'гол"}},{q="Почему Кин'вилай находится в Тернистой долине?",a="Он был послан в Лагерь Гром'гол, чтобы применить свои мистические таланты в помощь Нимбойе и местной экспедиции племени Черного Копья, в частности, чтобы найти юного Йенику и освободить его из лап враждебных троллей джунглей.",al={"why is kinweelay in gromgol","kinweelay purpose","почему кин'вилай в гром'гол","зачем здесь кин'вилай"}},{q="Что пытается создать Кин'вилай?",a="Кин'вилай стремится добыть реликвию, известную как Око разума. С помощью колдовства он намерен превратить ее в камень душ, который сможет захватить и надежно сохранить душу Йенику, разорвав темную власть над мальчиком.",al={"kinweelay minds eye","what does kinweelay make","кин'вилай око разума","что создает кин'вилай"}},{q="Откуда родом Кин'вилай?",a="Он прибыл из Оргриммара, где племя Черного Копья поддерживает прочные связи и имеет присутствие с тех пор, как вступило в Орду и поселилось на Островах Эха.",al={"kinweelay background","where did kinweelay come from","кин'вилай биография","откуда пришел кин'вилай"}},{q="Как он относится к другим племенам троллей Тернистой долины?",a="Он считает враждебные лесные племена, такие как Кровавый Скальп и Дробители Черепов, опасными соперниками, погрязшими в жестоких, извращенных обрядах. Он активно использует свое ремесло, чтобы противостоять их чарам и возвращать похищенную молодежь Черного Копья.",al={"kinweelay other trolls","kinweelay and bloodscalp","кин'вилай другие тролли","кин'вилай и кровавый скальп"}},{q="Какие предметы изучает Кин'вилай?",a="Кин'вилай исследует местные диковины с природным или наговорным резонансом, в том числе загадочные поющие кристаллы и ожерелья из костей, которые носят враждебные тролли джунглей, изучая их моджо, чтобы придумать средства противодействия.",al={"kinweelay items","singing crystals kinweelay","предметы кин'вилай","поющие кристаллы кин'вилай"}}},fp="10,308,26.324.0,23.444.1,18.227.0,40.201.0,36.222.0,32.146.0,57.216.0,41.219.0"}
P.entries["npc:kindal-moonweaver"] = {n="Кайдел Лунный Ткач",s="Кайдел Лунный Ткач — ночная эльфийка, уединившаяся в скрытой расщелине скалистых гор Фераласа, к северу от Лагеря Зловещего Тотема. Глубоко встревоженная жестоким обращением с животными в глуши, она наблюдает за воинственным племенем тауренов внизу и ищет помощи, чтобы освободить плененных зверей. Она родственница Джер'кай Лунный Ткач, и их объединяет цель защищать невинных лесных тварей.",h="Кайдел Лунный Ткач — ночная эльфийка, уединившаяся в скрытой расщелине скалистых гор Фераласа, к северу от...",kw={"dire maul","feralas","freedom for all creatures","grimtotem compound","hidden path","jer'kai moonweaver","kindal moonweaver","забытый город","фералас","свобода всем существам","лагерь зловещего тотема","скрытая тропа","джер'кай лунный ткач","кайдел лунный ткач"},ang={["class:Druid"]="Друиды найдут общий язык с единой преданностью Кайдел сохранению лесной жизни и освобождению плененных духов природы из жестоких железных клеток.",["class:Hunter"]="Охотники, связанные со зверями Калимдора, оценят усилия Кайдел по защите диких детенышей и наказанию тех, кто ловит дичь ради забавы или злого умысла.",["race:NightElf"]="Кайдел воплощает традиционную преданность кальдораев миру природы, будучи одинокой защитницей зверей, которым угрожают чужаки."},sec={{t="Наблюдательница на утесах",b="Кайдел Лунный Ткач, расположившаяся на узкой извилистой горной тропе, отчасти скрытой за деревьями к востоку от Забытого Города, тайно следит за долиной внизу. Хотя большая часть Фераласа оспаривается Ордой, ночными эльфами Оперенной Луны и древними руинами Эльдре'Таласа, Кайдел занята более близкой и насущной жестокостью. В низине племя Зловещего Тотема содержит укрепленный лагерь, где ловит и держит в загонах местных животных с далеко не добрыми целями. Со своего скрытого наблюдательного пункта Кайдел высматривает тех, кто готов отважиться проникнуть во вражеский лагерь и прекратить страдания внутри."},{t="Сострадание к дикой природе",b="Главная забота Кайдел — священное равновесие и кроткие существа Фераласа, которые не могут защититься от грубых пленителей. Вместе со своей родственницей Джер'кай Лунный Ткач она стремится освободить зверей из клеток и заботится о детенышах, оставшихся без защиты из-за жестокой браконьерской охоты. Вместо большой войны за земли ее внимание занято состраданием: освободить пленных фей и найти дом осиротевшей стрекозе-фее."}},faq={{q="Где находится Кайдел Лунный Ткач?",a="Кайдел прячется на северных утесах Фераласа, к востоку от Забытого Города и над Лагерем Зловещего Тотема. Добраться до нее можно по узкой скрытой горной тропе, ведущей вверх за рощей деревьев.",al={"kindal moonweaver location","how to find kindal","where is kindal","где кайдел лунный ткач","как найти кайдел","где кайдел"}},{q="Кто такая Кайдел Лунный Ткач?",a="Это одинокая ночная эльфийка, посвятившая себя защите животных и сохранению природы в Фераласе. Она следит за Лагерем Зловещего Тотема, чтобы мешать ловле местных животных.",al={"kindal lore","who is kindal","кайдел","кто такая кайдел","предания кайдел"}},{q="Какова цель Кайдел в Фераласе?",a="Кайдел хочет освободить существ, запертых в клетках в соседнем Лагере Зловещего Тотема, и позаботиться о том, чтобы осиротевшие звери глуши были спасены и получили безопасный приют.",al={"kindal quest purpose","why is kindal here","цель кайдел","зачем здесь кайдел"}},{q="Кайдел Лунный Ткач родственница Джер'кай Лунный Ткач?",a="Да, Кайдел — родственница Джер'кай Лунный Ткач. У обеих одна фамилия, и они вместе спасают истязаемых и лишившихся дома лесных существ в центральном Калимдоре.",al={"jerkai moonweaver connection","kindal and jerkai","джер'кай лунный ткач","кайдел и джер'кай"}},{q="Почему Кайдел выступает против Зловещего Тотема?",a="Клан Зловещего Тотема, занимающий лагерь под ее горным насестом, ловит и сажает в клетки диких зверей Фераласа. Кайдел стремится освободить этих существ из неволи и наказать их пленителей.",al={"kindal grimtotem","grimtotem compound kindal","кайдел зловещий тотем","лагерь зловещего тотема кайдел"}},{q="Дает ли Кайдел Лунный Ткач задания обеим фракциям?",a="Нет. Задания Кайдел доступны только Альянсу: она привлекает его искателей приключений, чтобы освободить пойманных существ из рук Зловещего Тотема.",al={"is kindal friendly to horde","can horde talk to kindal","дружелюбна ли кайдел к орде","может ли орда говорить с кайдел"}}},fp="17,391,26.598.0,23.447.0,35.210.0,25.182.0,33.174.0,51.184.0,37.191.0,53.131.0"}
P.entries["npc:kirge-sternhorn"] = {n="Кирдж Жесткий Рог",s="Кирдж Жесткий Рог — таурен, находящийся на суровом пограничье Степей. Он постоянно присутствует на пути путников через центральный Калимдор и направляет начинающих искателей приключений Орды на север, к важному форпосту — Перекрестку.",h="Кирдж Жесткий Рог — таурен, находящийся на суровом пограничье Степей.",kw={"barrens","crossroads","kirge","southern barrens","sternhorn","taurajo","tauren","степи","перекресток","кирдж","южные степи","жесткий рог","тауражо","таурен"},ang={["faction:Horde"]="Для путников, выходящих из южных земель, Кирдж служит первым ориентиром, направляя их к большому сообществу Орды на Перекрестке.",["race:Tauren"]="Кирдж олицетворяет основательный, гостеприимный дух Шу'хало, направляя сородичей и союзников через суровое пограничье их приемной родины."},sec={{t="Странник в Степях",b="Обширные выжженные солнцем равнины Степей страшат недавно прибывших странников, и Кирдж Жесткий Рог служит им добрым проводником. Он стоит к югу от центральных троп и присматривает за путниками, идущими между южными лагерями и сердцем Калимдора. Зная об опасности разбойничьих свинобразов и свирепых хищников, бродящих по саванне, Кирдж помогает молодым искателям приключений освоиться и отправиться к основным силам Орды на севере."}},faq={{q="Кто такой Кирдж Жесткий Рог?",a="Кирдж Жесткий Рог — таурен-странник и проводник, находящийся на южных просторах Степей и помогающий путникам Орды ориентироваться в пыльных равнинах.",al={"kirge sternhorn lore","who is kirge","kirge npc","кирдж жесткий рог","кто такой кирдж","кирдж"}},{q="Куда Кирдж отправляет путников?",a="Кирдж направляет путников на север, к Перекрестку — главному узлу Степей, где силы Орды координируют оборону и исследование региона.",al={"kirge quest","journey to the crossroads kirge","where does kirge send you","задание кирджа","путь к перекрестку","куда кирдж посылает"}},{q="Какой фракции служит Кирдж Жесткий Рог?",a="Кирдж предан Орде и своим собратьям-тауренам и помогает советом и делом всем представителям фракции, проходящим через эти земли.",al={"is kirge horde","kirge allegiance","кирдж из орды","верность кирджа"}}},fp="15,248,25.483.0,23.150.0,32.161.0,40.146.0"}
P.entries["npc:klannoc-macleod"] = {n="Кланнок Маклеод",s="Кланнок Маклеод — суровый воин-человек, живущий на Острове Битв у восточных берегов Степей. Он известен как судья боевого мастерства и испытывает начинающих бойцов Альянса и Орды, стремящихся освоить боевые стойки. Тех, кто заслужил его уважение, он направляет вглубь суши, к более серьезным испытаниям силы.",h="Кланнок Маклеод — суровый воин-человек, живущий на Острове Битв у восточных берегов Степей.",kw={"barrens","berserker","fray island","islander","klannoc","macleod","the affray","warrior","степи","берсеркер","остров битв","островитянин","кланнок","маклеод","побоище","воин"},ang={["class:Warrior"]="Кланнок Маклеод — важная фигура на пути воина: он проверяет вашу выносливость и ярость в Побоище, а затем направляет вас к освоению стойки берсеркера.",["faction:Alliance"]="Воинам Альянса приходится далеко заплывать в воды Калимдора у побережья Степей, чтобы найти Кланнока и доказать свою боевую готовность на Острове Битв.",["faction:Horde"]="Хотя Кланнок — человек, ему безразличны распри фракций: он принимает бойцов Орды, пришедших на его уединенный остров в поисках испытания и чести."},sec={{t="Хозяин Острова Битв",b="Кланнок Маклеод живет уединенно на Острове Битв у Торгового побережья в Степях и управляет жестоким испытательным полем для опытных бойцов. Хотя Кланнок — человек, он стоит в стороне от обычных политических споров Альянса и Орды и судит соперников лишь по их стойкости, владению клинком и выдержке под огнем."},{t="Побоище",b="Воины, направленные на Остров Битв, проходят испытание Маклеода — Побоище. Претенденты поднимаются на приподнятую железную решетку, где выдерживают нескончаемые волны жаждущих драки бойцов, пока за ними наблюдает Кланнок. Те, кто выстоит под натиском и победит выбранного им бойца, получают его одобрение, доказав, что обладают нравом, необходимым для обучения берсерков."}},faq={{q="Кто такой Кланнок Маклеод?",a="Кланнок Маклеод — ветеран, воин-человек, живущий на Острове Битв недалеко от побережья Степей. Он наставник и распорядитель испытаний для воинов, стремящихся проверить свои пределы и освоить новые приемы.",al={"who is klannoc","klannoc macleod lore","fray island guy","кто такой кланнок","кланнок маклеод предания","человек с острова битв"}},{q="Где найти Кланнока Маклеода?",a="Кланнок находится на Острове Битв — скалистом острове у восточного побережья Степей, к юго-востоку от Торгового побережья и Кабестана. Чтобы добраться до его лагеря, нужно переплыть открытую воду.",al={"klannoc location","where is fray island","how to get to klannoc","где кланнок","где остров битв","как добраться до кланнока"}},{q="Почему человек говорит с игроками Орды на Острове Битв?",a="Кланнок стоит вне традиционного конфликта Альянса и Орды. Как независимый мастер боя он заботится лишь о воинской дисциплине и этосе воина и охотно испытывает любого соперника, пришедшего с надлежащей рекомендацией.",al={"is klannoc hostile horde","why is klannoc neutral","horde klannoc","враждебен ли кланнок орде","почему кланнок нейтрален","кланнок орда"}},{q="Что такое Побоище?",a="Побоище — испытание на выносливость на Острове Битв. Воин должен встать на боевую площадку Кланнока и победить волны соперников, а затем сразиться с Большим Уиллом, доказав, что обладает яростью, необходимой для продвинутых воинских приемов.",al={"the affray quest","fray island trial","klannoc trial","задание побоище","испытание острова битв","испытание кланнока"}},{q="Зачем посылать воинов к Кланноку Маклеоду?",a="Наставники воинов по всему Азероту направляют самых перспективных учеников к Кланноку на испытание боевой стойкости, которое необходимо, чтобы подготовить их к яростной сосредоточенности стойки берсеркера.",al={"warrior quest fray island","why visit klannoc","berserker stance quest","задание воина остров битв","зачем идти к кланноку","задание стойка берсеркера"}},{q="К кому Кланнок отправляет вас после Побоища?",a="Когда вы докажете свою доблесть в Побоище, Кланнок направляет воинов на север, в Альтеракские горы, неподалеку от Мельницы Таррен, на поиски Бат'ра Ветростража за дальнейшими наставлениями.",al={"after klannoc","the windwatcher quest","who is the windwatcher","после кланнока","задание ветростраж","кто такой ветростраж"}}},fp="15,346,25.330.0,10.352.0,23.214.0,33.185.0,54.232.0,19.252.0,37.191.0,46.174.1"}
P.entries["npc:kor-ghan"] = {n="Кор'гхан",s="Кор'гхан — тролль джунглей из племени Черного Копья, которого можно найти в мрачных пещерах Расселины Теней в Оргриммаре. Он стоит прямо у лавки «Яды Реккула» и ищет помощи в изготовлении противоядий от ядовитых хищников глуши.",h="Кор'гхан — тролль джунглей из племени Черного Копья, которого можно найти в мрачных пещерах Расселины Теней в...",kw={"antidote","cleft of shadow","kor'ghan","korghan","orgrimmar","rekkul's poisons","scorpid venom","sen'jin village","противоядие","расселина теней","кор'гхан","оргриммар","яды реккула","яд скорпида","деревня сен'джин"},ang={["class:Rogue"]="Стоящий прямо у лавки «Яды Реккула» в Расселине Теней, Кор'гхан — привычная фигура для разбойников, приходящих в низы Оргриммара за реагентами и ядами.",["race:Troll"]="Как и многие соплеменники Черного Копья, покинувшие Деревню Сен'джин, Кор'гхан применяет практические знания об опасностях дикой природы Дуротара в укрепленной столице Орды."},sec={{t="Тролль в тени",b="Стоя перед лавкой «Яды Реккула» в пещерных глубинах Расселины Теней, Кор'гхан приглядывает за противоядиями и ядами. Из столицы он отправляет искателей приключений через красные каньоны собирать ядовитые компоненты у скорпидов Дуротара для изготовления жизненно важных противоядий."}},faq={{q="Кто такой Кор'гхан?",a="Кор'гхан — тролль из племени Черного Копья, живущий в Расселине Теней в Оргриммаре у лавки ядов Реккула.",al={"kor'ghan","who is kor'ghan","korghan npc","кор'гхан","кто такой кор'гхан","кор'гхан персонаж"}},{q="Где найти Кор'гхана?",a="Он находится в подземной Расселине Теней под центром Оргриммара, прямо перед лавкой «Яды Реккула».",al={"kor'ghan location","where is korghan","find korghan","где кор'гхан","местонахождение кор'гхана","найти кор'гхана"}},{q="С чем нужно помочь Кор'гхану?",a="Он нанимает путников собирать ядовитые железы у скорпидов-ядохвостов, бродящих у входа в Оргриммар, чтобы приготовить противоядия.",al={"kor'ghan quest","finding the antidote quest","korghan venom","задание кор'гхана","поиск противоядия","яд кор'гхана"}},{q="Бывал ли Кор'гхан когда-либо в Дуротаре?",a="Сам нет. Кор'гхан остается на своем месте рядом с торговцами ядами в Оргриммаре, но посылает искателей приключений в Дуротар собирать ядовитые железы у скорпидов-ядохвостов близ входа в город.",al={"kor'ghan sen'jin","korghan old location","кор'гхан сен'джин","прежнее местонахождение кор'гхана"}}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:korran"] = {n="Корран",s="Корран — тролль из племени Черного Копья, исследователь, расквартированный на Перекрестке в Степях. Служа Белгрому Каменная Булава в Оргриммаре, он следит за странными событиями в степях и изучает растущую угрозу насекомоподобных силитидов.",h="Корран — тролль из племени Черного Копья, исследователь, расквартированный на Перекрестке в Степях.",kw={"barrens","belgrom rockmaul","crossroads","egg hunt","field of giants","korran","silithid","степи","белгром каменная булава","перекресток","охота за яйцами","поля великанов","корран","силитид"},ang={["faction:Horde"]="Корран — бдительное око Орды, следящее за меняющейся экологией Калимдора и не позволяющее новым угрозам, вроде силитидов, застать Оргриммар врасплох, пока он укрепляет свои границы.",["race:Troll"]="Как тролль из племени Черного Копья, Корран привносит в засушливые Степи острое чутье разведчика и инстинкты выживания, применяя практичную хитрость для изучения странных чужеродных тварей."},sec={{t="Разведчик на Перекрестке",b="Пока большинство жителей Перекрестка заботятся о свирепых свинобразах и местных кланах кентавров, Корран следит за более скрытыми и коварными угрозами. Поставленный сюда по приказу Белгрома Каменная Булава из Оргриммара, тролль-разведчик наблюдает за меняющейся землей и руководит сбором сведений для руководства Орды."},{t="Вторжение силитидов",b="Главная забота Коррана сместилась на юг, к Полям Великанов, где странные насекомоподобные существа, известные как силитиды, начали зарываться в землю. Встревоженный их агрессивностью и быстрым продвижением, он нанимает проходящих искателей приключений выкапывать целые яйца с помощью его когтя, пытаясь выяснить, откуда взялся рой и какую опасность он представляет для молодой Орды."}},faq={{q="Кто такой Корран?",a="Корран — тролль из племени Черного Копья, расквартированный на Перекрестке в Степях. Он наблюдатель и исследователь, докладывающий Белгрому Каменная Булава в Оргриммаре.",al={"who is korran","korran troll","crossroads troll","кто такой корран","корран тролль","тролль на перекрестке"}},{q="Что Корран исследует в Степях?",a="Он исследует странных агрессивных насекомоподобных существ, силитидов, появившихся на юге Степей у Полей Великанов, а также похожие рои, о которых сообщают еще южнее, в Тысяче Игл.",al={"what does korran study","korran research","field of giants insects","что изучает корран","исследования коррана","насекомые полей великанов"}},{q="На кого работает Корран?",a="Корран служит Белгрому Каменная Булава, опытному воину, расквартированному в Аллее Чести в Оргриммаре, который следит за новыми угрозами по всему Калимдору в интересах Орды.",al={"who sent korran","korran superior","belgrom rockmaul","кто послал коррана","начальник коррана","белгром каменная булава"}},{q="Зачем Коррану яйца силитидов?",a="Ему нужны целые яйца, чтобы изучить жизненный цикл и происхождение роя силитидов. Изучая ранние образцы, Корран надеется понять, что это за существа, и определить, насколько велика угроза для земель Орды.",al={"why silithid eggs","egg hunt quest","korran claw","зачем яйца силитидов","задание охота за яйцами","коготь коррана"}}},fp="6,229,25.335.0,22.389.0,14.158.0,44.220.0,25.157.0,35.226.0"}
P.entries["npc:kravel-koalbeard"] = {n="Крейвел Углебрад",s="Крейвел Углебрад — хитрый предприимчивый дворф и мошенник, обосновавшийся на Виражах на Миражах в Мерцающей равнине. Он болеет за гонки не ради самого спорта, а видит в яростном соперничестве гномов и гоблинов отличную возможность набить карманы. От сбора бесхозных деталей машин до подтасовки результатов гонок с помощью шантажа и выпивки — Крейвел всегда ищет очередную выгодную аферу.",h="Крейвел Углебрад — хитрый предприимчивый дворф и мошенник, обосновавшийся на Виражах на Миражах в Мерцающей...",kw={"blackmail","koalbeard","kravel","mirage raceway","rocket car","sabotage","shimmering flats","thousand needles","шантаж","углебрад","крейвел","виражи на миражах","ракетная машина","саботаж","мерцающая равнина","тысяча игл"},ang={["class:Rogue"]="Разбойникам род занятий Крейвела Углебрада покажется знакомым: воровство, саботаж, шантаж и манипуляции алчными целями из тени.",["race:Dwarf"]="В отличие от честных шахтеров, старателей и горцев Стальгорна, Крейвел — отъявленный жулик и аферист, позорящий традиционные ценности дворфов.",["race:Gnome"]="Гномам стоит приглядывать за напитками и чертежами рядом с Крейвелом: он так же рад подсыпать что-нибудь гномам-пилотам, как и испортить их машины."},sec={{t="Мошенник на равнине",b="Пока большинство зрителей и участников на Виражах на Миражах поглощены механическим соперничеством и ревом ракетных двигателей, Крейвел Углебрад следит за чужими кошельками. Этот оппортунист действует в пыльных закоулках лагеря гонок и быстро предлагает контракты и услуги, за которыми редко стоят чистые намерения. Острое противостояние гномов-инженеров и гоблинов он считает не вдохновляющим состязанием, а благодатной почвой для вымогательства, саботажа и краж."},{t="Подтасовка гонок",b="Дела Крейвела простираются далеко за пределы сбора брошенного хлама на соляных равнинах. Чтобы повлиять на ставки и добиться нужного исхода, Крейвел посылает готовых на все искателей приключений с темными поручениями: распускать слухи, шантажировать и даже спаивать команды механиков перед заездом. Будь то крепкие напитки для гоблинов-механиков или для гномов-пилотов, Крейвел пойдет на любую подлость, чтобы набить карманы в день гонки."}},faq={{q="Кто такой Крейвел Углебрад?",a="Крейвел Углебрад — дворф-интриган и оппортунист, обосновавшийся на Виражах на Миражах в Мерцающей равнине. Он использует соперничество гномов и гоблинов, чтобы набивать карманы на сборе хлама, подтасовке гонок и вымогательстве.",al={"who is kravel","kravel koalbeard identity","mirage raceway dwarf","кто такой крейвел","крейвел углебрад","дворф на виражах на миражах"}},{q="Чем занимается Крейвел Углебрад на Виражах на Миражах?",a="Крейвел нанимает путников для темных поручений вокруг трассы. Среди его афер — сбор деталей ракетных машин, поиск компромата и саботаж команд: он спаивает механиков и пилотов, чтобы повлиять на исход гонок.",al={"kravel purpose","what does kravel want","kravel schemes","цель крейвела","чего хочет крейвел","аферы крейвела"}},{q="Зачем Крейвел пытается напоить гоночные команды?",a="Крейвел делает крупные ставки на исход гонок ракетных машин. Напоив гномов или гоблинов перед заездом, он подстраивает состязание так, чтобы результат принес ему наибольшую прибыль.",al={"get the gnomes drunk quest","get the goblins drunk","kravel sabotage","напои гномов задание","напои гоблинов","саботаж крейвела"}},{q="Где найти Крейвела Углебрада?",a="Он находится в Мерцающей равнине в Тысяче Игл и слоняется возле оживленных лагерей Виражей на Миражах.",al={"kravel location","where is kravel","kravel thousand needles","местоположение крейвела","где крейвел","крейвел тысяча игл"}},{q="Есть ли у Крейвела связи за пределами Тысячи Игл?",a="Да. Его сомнительные дела связаны с контактами в гоблинских портах Кабестана и Пиратской бухты, в том числе с Управляющим пристанью Головокружилкинсом из Кабестана, сплетниками и редкими напитками из Тернистой долины.",al={"kravel booty bay","kravel connections","крейвел пиратская бухта","связи крейвела"}},{q="Будет ли Крейвел работать и с Альянсом, и с Ордой?",a="Как и многие, кто действует в нейтральных местах вроде Виражей на Миражах, Крейвел заботится о золоте, а не о верности фракциям. Он охотно нанимает искателей приключений и из Альянса, и из Орды для своих афер.",al={"is kravel alliance only","can horde talk to kravel","крейвел только для альянса","может ли орда говорить с крейвелом"}}},fp="16,424,25.509.0,17.494.1,24.220.0,52.252.0,45.208.0,36.127.0,47.201.0,46.215.0"}
P.entries["npc:kreldig-ungor"] = {n="Крелдиг Унгор",s="Крелдиг Унгор — предприимчивый дворф-агент Поисковой корпорации, расположившийся высоко среди скал Высоты Найджела в Пустошах. Руководя полевыми операциями в бесплодной пустоши, он нанимает искателей приключений Альянса для возврата потерянных грузов и добычи ценных местных реагентов. Его контракты на спасение и возврат делают его главным контактом для путников в этом враждебном краю.",h="Крелдиг Унгор — предприимчивый дворф-агент Поисковой корпорации, расположившийся высоко среди скал Высоты...",kw={"alliance","desolace","dwarf","karnitol shipwreck","kreldig ungor","nijel's point","reclaimers inc","salvage","альянс","пустоши","дворф","крушение карнитола","крелдиг унгор","высота найджела","утилизаторы","спасение"},ang={["faction:Alliance"]="Расположившись на Высоте Найджела, Крелдиг целиком полагается на путников из Альянса, чтобы его контракты на спасение имущества выполнялись во враждебных землях.",["race:Dwarf"]="Крелдиг демонстрирует свойственную дворфам тягу к суровым пограничным исследованиям и коммерческие амбиции, устроив дело вдали от горных чертогов."},sec={{t="Полевой агент в пустошах",b="Высота Найджела дает Альянсу редкое убежище среди выжженных каньонов Пустошей и потому идеально подходит для деловых оппортунистов вроде Крелдига Унгора. Представляя Поисковую корпорацию, Крелдиг забрался далеко от безопасного Каз Модана в пустынную глушь, за которую борются кланы кентавров, демоны и Орда. Там, где другие видят руины и пепел, Крелдиг видит нетронутую прибыль и потерянное имущество, которое пора вернуть."},{t="Контракт Карнитола",b="Главное дело, приведшее Крелдига в Пустоши, — потерянный корабль Карнитола, разбившийся у коварного западного побережья. В грузе Карнитола были ценные товары, и Крелдиг организует поиски обломков и возврат разбросанного груза, пока мародеры или прибрежные морские великаны не растащили все."},{t="Сбор местных реагентов",b="Помимо морских спасательных работ, Крелдиг занимается для Поисковой корпорации добычей необычных биологических и минеральных сокровищ Пустошей. Суровая среда порождает уникальных животных и растения, части которых высоко ценятся алхимиками и инженерами в Восточных королевствах. Искатели приключений, готовые рискнуть встретиться с хищниками пустошей, получают у Крелдига стабильную плату."}},faq={{q="Кто такой Крелдиг Унгор?",a="Крелдиг Унгор — дворф-агент Поисковой корпорации, работающий из форпоста Альянса на Высоте Найджела в Пустошах. Он координирует спасательные задания и сбор образцов по всей зоне.",al={"kreldig ungor lore","who is kreldig","kreldig ungor","крелдиг унгор предания","кто такой крелдиг","крелдиг унгор"}},{q="Что такое Поисковая корпорация?",a="Поисковая корпорация — предпринимательское начинание, нацеленное на возврат потерянных грузов, извлечение обломков и сбор редких реагентов на опасных границах ради прибыли.",al={"reclaimers inc","who are reclaimers inc","reclaimers business","утилизаторы","кто такие утилизаторы","бизнес утилизаторов"}},{q="Где найти Крелдига Унгора?",a="Он находится в поселении Альянса на Высоте Найджела, высоко в скалистых горах северо-востока Пустошей.",al={"kreldig ungor location","where is kreldig","find kreldig ungor","местоположение крелдига унгора","где крелдиг","найти крелдига унгора"}},{q="Что нужно Крелдигу от крушения корабля Карнитола?",a="Корабль с ценными товарами Карнитола разбился у побережья Пустошей. Крелдиг нанимает искателей приключений, чтобы найти обломки и вернуть утерянный груз, пока его не разграбили или не уничтожили.",al={"karnitol shipwreck","kreldig karnitol","desolace shipwreck","крушение карнитола","крелдиг карнитол","кораблекрушение в пустошах"}},{q="Зачем Крелдиг собирает реагенты в Пустошах?",a="Суровая среда Пустошей порождает редких существ и уникальные природные составы. Крелдиг собирает эти образцы для снабжения алхимиков, измыслителей и покупателей в крупных городах Альянса.",al={"reagents for reclaimers inc","desolace reagents","why collect reagents","реагенты для утилизаторов","реагенты пустошей","зачем собирать реагенты"}},{q="Крелдиг работает на Стальгорн или на частное предприятие?",a="Хотя Крелдиг действует с форпоста Альянса и нанимает только странников Альянса, он представляет Поисковую корпорацию — коммерческое предприятие, занятое спасательными работами и торговлей, а не официальными военными целями короны.",al={"kreldig alliance or private","reclaimers inc ironforge","крелдиг альянс или частный","утилизаторы стальгорн"}}},fp="13,399,25.429.0,21.323.0,25.373.0,21.203.0,24.163.0,33.120.0,51.197.0,47.195.0,56.219.0"}
P.entries["npc:krolg"] = {n="Кролг",s="Кролг — неоскверненный фурболг, живущий в уединенной хижине к югу от Озера Мистраль в Ясеневом лесу. Прежде он был членом племени Гиблой Чащи, но порвал с сородичами, павшими жертвой демонического безумия, и говорит лишь с теми, кто предстает перед ним в облике фурболга.",h="Кролг — неоскверненный фурболг, живущий в уединенной хижине к югу от Озера Мистраль в Ясеневом лесу.",kw={"ashenvale furbolg","chief murgut","dartol's rod","foulweald","krolg","krolg's hut","mystral lake","raene's cleansing","фурболг ясеневого леса","вождь мургут","жезл дартола","гиблая чаща","кролг","хижина кролга","озеро мистраль","раэна – санитар ясеневого леса"},ang={["class:Druid"]="Друиды, стремящиеся восстановить равновесие в Ясеневом лесу, находят в Кролге бесценный здравый голос среди земель, заполоненных оскверненными зверями.",["faction:Alliance"]="Разведчики Альянса, помогающие Раэне Волкопас, рассчитывают на Кролга в борьбе с верхушкой враждебных фурболгов Гиблой Чащи.",["race:NightElf"]="Для ночных эльфов Астранаара Кролг — горько-сладкое напоминание о древних союзниках-фурболгах до того, как демоническая скверна разрушила племена."},sec={{t="Нерушимый разум",b="Хотя большинство фурболгов Гиблой Чащи в Ясеневом лесу поддались демонической скверне, оставленной Пылающим Легионом, Кролг сохранил ясность рассудка и не затронут безумием. Живя в уединенном убежище к югу от Озера Мистраль, он осторожно присматривает за лесом. Видев, как его сородичи трагически скатились к бессмысленной жестокости, он не доверяет чужакам и говорит лишь с теми, кто выглядит как его сородичи."},{t="Наследие Дартола",b="Благодаря магическим чарам Жезла Преображения Дартола путники из Альянса могут принять облик фурболга. Увидев в них дружественный родственный дух, Кролг открывается и делится важными сведениями об очищении земли. Он направляет героев против Рэна Кровавого Клыка и его стражей, чьи порочность и ненависть угрожают лесу."}},faq={{q="Почему Кролг не разговаривает со мной?",a="Кролг крайне подозрительно относится к чужакам и страшится жестокого хаоса, охватившего лес. Он полностью проигнорирует вас, если на вас нет облика фурболга, даруемого Жезлом Преображения Дартола во время цепочки заданий «Раэна – санитар Ясеневого леса».",al={"krolg wont speak","cant talk to krolg","why is krolg silent","кролг не говорит","не могу поговорить с кролгом","почему кролг молчит"}},{q="Где найти Кролга?",a="He lives in a small shelter known as Krolg's Hut, situated just south of Mystral Lake in south-central Ashenvale.",al={"krolg location","where is krolg","krolg hut","местоположение кролга","где кролг","хижина кролга"}},{q="К какому племени принадлежит Кролг?",a="Кролг изначально принадлежал к племени Гиблой Чащи. В отличие от остальных сородичей, павших жертвой скверны и демонического неистовства, он сохранил рассудок и порвал с ними связи.",al={"krolg tribe","is krolg foulweald","племя кролга","кролг гиблая чаща"}},{q="Враждебен ли Кролг к игрокам?",a="Кролг нападает на чужаков, подошедших к нему без облика фурболга. Перед встречей с ним искатели приключений должны использовать Жезл Преображения Дартола.",al={"does krolg attack","is krolg an enemy","нападает ли кролг","кролг враг"}},{q="Почему Кролг хочет смерти Рэна Кровавого Клыка?",a="Кролг считает Рэна Кровавого Клыка жадным до власти и усилившимся благодаря скверне. Хотя Кролг винит ночных эльфов в страданиях сородичей, он не позволит Рану угрожать их детям и другим существам леса.",al={"krolg ran bloodtooth","why kill ran bloodtooth","кролг рэн кровавый клык","зачем убивать рэна кровавого клыка"}},{q="Кем был Дартол, чей жезл позволяет говорить с Кролгом?",a="Дартол создал зачарованный Жезл Преображения, позволяющий владельцу принять облик фурболга. Искатели приключений используют уже восстановленный жезл, чтобы подойти к Кролгу в задании «Раэна – санитар Ясеневого леса».",al={"who is dartol","dartols rod backstory","кто такой дартол","история жезла дартола"}}},fp="5,261,15.439.0,15.374.1,27.256.0,25.113.0,32.173.0,28.158.0,40.214.1,60.177.0"}
P.entries["npc:krom-stoutarm"] = {n="Кром Крепкорук",s="Кром Крепкорук — дворф-ученый и чернокнижник, обитающий в глубине Библиотеки Зала Исследователей в Стальгорне. В отличие от большинства сородичей, изучающих лишь древний камень и реликвии титанов, Кром штудирует темные магические тексты и демонические ритуалы. Он служит незаменимым контактом для чернокнижников Альянса, ищущих тайные знания по всему Калимдору и Восточным королевствам.",h="Кром Крепкорук — дворф-ученый и чернокнижник, обитающий в глубине Библиотеки Зала Исследователей в Стальгорне.",kw={"hall of explorers","ironforge","krom stoutarm","library","stoutarm","tome of the cabal","warlock","зал исследователей","стальгорн","кром крепкорук","библиотека","крепкорук","фолиант заговора","чернокнижник"},ang={["class:Warlock"]="Чернокнижникам Альянса следует обращаться к Крому в поисках темных подчинений, особенно в опасном деле сбора Фолианта заговора.",["faction:Alliance"]="Кром дает скрытным практикам Альянса безопасное интеллектуальное убежище в могучих горных бастионах Стальгорна.",["race:Dwarf"]="Дворфы обычно отвергают темные искусства, поэтому положение Крома среди почтенных полок Зала Исследователей — любопытная редкость."},sec={{t="Темный уголок Зала",b="Зал Исследователей известен дворфами-археологами, одержимыми кирками, лопатами и артефактами титанов. Кром Крепкорук выделяется среди них. Скрываясь в Библиотеке среди огромных фолиантов, он изучает оккультные знания и обряды подчинения демонов. Его присутствие в Стальгорне показывает, что, хотя искусство чернокнижников повсеместно вызывает недоверие, ученые-практики, изучающие запретные искусства, все же работают в залах горного города."},{t="Фолиант заговора",b="Когда чернокнижники Альянса стремятся подчинить могущественных демонических слуг, например охотника Скверны, их путь неизбежно пересекается с Кромом. Зная о разрозненных оккультных томах, он отправляет начинающих призывателей далеко за моря, в том числе в опасные вылазки во враждебные земли вроде Степей, чтобы собрать оторванные страницы и фрагменты печально известного Фолианта заговора."}},faq={{q="Где найти Крома Крепкорука?",a="Кром Крепкорук находится в крыле Библиотеки Зала Исследователей в Стальгорне, столице дворфов.",al={"krom stoutarm location","where is krom stoutarm","krom stoutarm ironforge","местоположение крома крепкорука","где кром крепкорук","кром крепкорук стальгорн"}},{q="Какую роль Кром Крепкорук играет для игроков?",a="Кром — важный контакт по заданиям для чернокнижников Альянса, проходящих классовые демонические ритуалы, и особенно помогает им в поиске Фолианта заговора.",al={"what does krom do","krom stoutarm purpose","krom stoutarm quests","что делает кром","зачем нужен кром крепкорук","задания крома крепкорука"}},{q="Родственен ли Кром Крепкорук другим Крепкоруками?",a="Несколько дворфов носят фамилию Крепкорук, но родство Крома с остальными не подтверждено.",al={"krom relatives","sten stoutarm related","родственники крома","стен крепкорук родственник"}},{q="Почему чернокнижнику разрешено находиться в Зале Исследователей?",a="Krom is both a warlock and a scholar working from the Hall of Explorers. The source does not explain the terms under which his work is permitted.",al={"why is krom in hall of explorers","ironforge warlock allowed","почему кром в зале исследователей","чернокнижник в стальгорне разрешен"}},{q="Почему Кром связан со Степями?",a="Изучая темные рукописи, Кром отправляет чернокнижников за утерянными частями Фолианта заговора, и один из важнейших фрагментов спрятан в сундуке в глубине земель Степей, кишащих кабанами-иглошкурами.",al={"krom stoutarm barrens","why barrens quest krom","кром крепкорук степи","почему задание в степях кром"}},{q="Обучает ли Кром Крепкорук заклинаниям?",a="Кром — ученый, выдающий задания, а не обычный учитель класса. Он направляет чернокнижников по определенным обрядам посвящения, а не обучает повседневным гримуарам.",al={"can krom train me","krom warlock trainer","может ли кром обучить","кром учитель чернокнижников"}}},fp="13,374,27.471.0,21.373.0,31.110.0,46.181.0,44.113.0,56.145.0,37.214.0,32.162.0"}
P.entries["npc:krusk"] = {n="Круск",s="Круск — орк-разведчик, расквартированный на Мельнице Таррен в Предгорьях Хилсбрада. Он был направлен непосредственно по приказу вождя Тралла, чтобы разведать деятельность Синдиката и добыть реликвии из руин Крепости Дарнхольд. После того как его первое проникновение закончилось засадой, он руководит разведкой и спасательными действиями.",h="Круск — орк-разведчик, расквартированный на Мельнице Таррен в Предгорьях Хилсбрада.",kw={"drull","durnholde keep","gol'dir","hillsbrad","krusk","syndicate","tarren mill","thrall","tog'thar","друлл","крепость дарнхольд","гол'дир","хилсбрад","круск","синдикат","мельница таррен","тралл","тог'тар"},ang={["faction:Horde"]="Круск представляет непосредственные интересы вождя Тралла в Лордероне: он стремится сохранить историю Дарнхольда и не оставить ни одного плененного орка в руках Синдиката.",["race:Orc"]="Помощь Круску в спасении собратьев-разведчиков затрагивает честь и болезненную историю лагерей для интернированных орков, в частности крепости, где Тралл разорвал цепи своего народа."},sec={{t="Неудавшееся задание",b="Когда вождь Тралл вновь обратил внимание на руины Крепости Дарнхольд, он отправил Круска и небольшой отряд, чтобы разведать деятельность Синдиката и добыть реликвии, связанные с мрачным прошлым крепости. Однако люди-изгои оказались более укоренившимися и организованными, чем ожидалось. Засада в рушащихся стенах Дарнхольда сокрушила отряд орков-разведчиков. Круску удалось пробиться с боем, но трое его товарищей — Гол'дир, Друлл и Тог'тар — были схвачены и заточены в глубине руин. Собрав силы на Мельнице Таррен, Круск теперь направляет приключенцев Орды проникнуть в Дарнхольд, вернуть утраченные предметы и освободить его плененных соратников."},{t="Взгляд на Синдикат",b="Помимо спасения своих разведчиков, Круск одержим идеей сокрушить власть Синдиката над Хилсбрадом. Павшие дворяне Альтерака представляют собой изменчивую угрозу: они действуют из Крепости Дарнхольд и строят козни как против застав Орды, так и против своих бывших собратьев по Альянсу. Действуя с Мельницы Таррен, Круск следит за передвижениями вожаков Синдиката, например лорда Алидена Перенольда, надеясь обезглавить их, прежде чем они смогут угрожать непрочной опоре Орды в Лордероне."}},faq={{q="Кто такой Круск?",a="Круск — орк-разведчик, отправленный на Мельницу Таррен вождем Траллом. Ему было поручено расследовать деятельность Синдиката вокруг руин Крепости Дарнхольд и добыть исторические реликвии.",al={"krusk","who is krusk","krusk tarren mill","круск","кто такой круск","круск мельница таррен"}},{q="Что случилось с отрядом Круска?",a="Круск и его отряд попали в засаду Синдиката в Крепости Дарнхольд. Круск спасся, а его товарищи Гол'дир, Друлл и Тог'тар были схвачены и заключены в разрушенной крепости.",al={"krusk squad","what happened to krusk","durnholde ambush","отряд круска","что случилось с круском","засада в дарнхольде"}},{q="Почему Орда интересуется Крепостью Дарнхольд?",a="Дарнхольд имеет глубокое личное и историческое значение для вождя Тралла, который вырос там пленным гладиатором под властью Эдельаса Блэкмура, а затем возглавил восстание орков, разрушившее крепость.",al={"why durnholde","thrall durnholde","durnholde relics","почему дарнхольд","тралл дарнхольд","реликвии дарнхольда"}},{q="Где найти Круска?",a="Круск находится под открытым небом, в поселении Орды на Мельнице Таррен на севере Предгорий Хилсбрада.",al={"krusk location","where is krusk","где круск","местонахождение круска"}}},fp="5,305,20.659.0,21.475.0,13.182.0,31.194.0,46.200.0,23.99.0"}
P.entries["npc:kuray-bin"] = {n="Курай'бин",s="Курай'бин — разведчик из троллей джунглей племени Черного Копья, несущий службу на сторожевом посту у Заставы Расщепленного Дерева в Ясеневом лесу. Он наблюдает за лесными тропами, высматривая разведчиков ночных эльфов, подбирающихся к лагерю Орды.",h="Курай'бин — разведчик из троллей джунглей племени Черного Копья, несущий службу на сторожевом посту у Заставы...",kw={"ashenvale outrunners","darkspear","kuray'bin","kuraybin","silverwing sentinels","splintertree post","гонцы ясеневого леса","черное копье","курай'бин","среброкрылые часовые","застава расщепленного дерева"},ang={["faction:Horde"]="Курай'бин воплощает бдительность на передовой, необходимую, чтобы партизаны ночных эльфов не окружили и не захватили Заставу Расщепленного Дерева.",["race:Troll"]="Как и многие разведчики Черного Копья на службе Орды, Курай'бин использует чутье следопыта джунглей, чтобы обнаружить лазутчиков ночных эльфов там, где другие видят лишь деревья."},sec={{t="Дозор на краю леса",b="Курай'бин расположился неподалеку от Заставы Расщепленного Дерева и следит, чтобы Альянс не проник в глубь чащ Ясеневого леса. Среброкрылые Часовые постоянно патрулируют окрестные кроны, отправляя через границу проворных гонцов, чтобы собрать сведения о лесозаготовках и обороне Орды. Зная, что оставленные без надзора разведчики быстро превращаются в засадные отряды, Курай'бин посылает способных бойцов Орды выследить гонцов, прежде чем те донесут вести в Приют Среброкрылых."}},faq={{q="Кто такой Курай'бин?",a="Курай'бин — тролль-дозорный из племени Черного Копья, несущий службу у Заставы Расщепленного Дерева в Ясеневом лесу. Он поручает приключенцам Орды истреблять вражеских разведчиков ночных эльфов, скрывающихся в окрестных лесах.",al={"kuraybin","who is kuraybin","splintertree troll scout","курай'бин","кто такой курай'бин","тролль-разведчик застава расщепленного дерева"}},{q="Где найти Курай'бина?",a="Он стоит сразу за воротами частокола Заставы Расщепленного Дерева и охраняет подступы к дороге в центрально-восточной части Ясеневого леса.",al={"kuraybin location","where is kuraybin","где курай'бин","местонахождение курай'бина"}},{q="Почему Курай'бин хочет смерти среброкрылых гонцов?",a="Гонцы — это Среброкрылые Часовые, пробирающиеся к Заставе Расщепленного Дерева. Курай'бин хочет уничтожить их, прежде чем они соберут тактические сведения о позициях Орды или организуют внезапные нападения.",al={"why kill outrunners","ashenvale outrunners quest lore","зачем убивать гонцов","гонцы ясеневого леса задание"}},{q="Есть ли у Курай'бина другие поручения?",a="Нет. Его единственная задача на краю заставы — противодействие разведке неуловимых гонцов ночных эльфов.",al={"kuraybin quests","kuray bin task","задания курай'бина","поручение курай'бина"}}},fp="9,211,23.484.0,17.191.0,27.126.0,55.211.0,37.117.0"}
P.entries["npc:kzan-thornslash"] = {n="Кзан Шипоруб",s="Кзан Шипоруб — орк-торговец оружием в Долине Испытаний в Дуротаре. Он снабжает необходимым начальным оружием и припасами новобранцев, начинающих обучение в Орде.",h="Кзан Шипоруб — орк-торговец оружием в Долине Испытаний в Дуротаре.",kw={"durotar","horde","kzan","orc","thornslash","valley of trials","weapon vendor","weapons","дуротар","орда","кзан","орк","шипоруб","долина испытаний","торговец оружием","оружие"},ang={["class:Warrior"]="Для молодых воинов, начинающих с щербатыми клинками, Кзан сразу предлагает выбор дробящего и рубящего оружия на любой стиль боя.",["faction:Horde"]="Снабжение зарождающихся армий Тралла начинается с самых низов, где торговцы вроде Кзана следят, чтобы у каждого способного бойца была сталь для службы Орде."},sec={{t="Оружейник новобранцев",b="Кзан Шипоруб, обосновавшийся в пыльном красном каньоне Долины Испытаний, — главный торговец оружием для молодых орков и троллей Черного Копья, делающих первые шаги как воины Орды. Он предлагает набор простого вооружения — от грубых ручных топоров и коротких мечей до дубинок и метательных ножей — и следит, чтобы только что пробудившиеся новички были достаточно вооружены для встречи с местными животными и опасностями региона."}},faq={{q="Кто такой Кзан Шипоруб?",a="Кзан Шипоруб — орк-торговец в Долине Испытаний. Его задача — снабжать новых рекрутов Орды стандартным оружием для первых боевых испытаний.",al={"kzan thornslash","who is kzan","valley of trials weapon vendor","кзан шипоруб","кто такой кзан","торговец оружием долина испытаний"}},{q="Где найти Кзана Шипоруба?",a="Его можно найти на открытой тренировочной площадке Долины Испытаний на юго-западе Дуротара, среди начинающих искателей приключений и наставников.",al={"kzan location","where is kzan thornslash","kzan thornslash map","где кзан","где кзан шипоруб","кзан шипоруб на карте"}},{q="Какое снаряжение продает Кзан?",a="Кзан предлагает простое начальное оружие: топоры, мечи, кинжалы, посохи, дубинки и метательное оружие — для новобранцев, которым нужно надежное железо, пока они не обзавелись откованным или найденным снаряжением.",al={"what does kzan sell","kzan items","kzan weapons","что продает кзан","предметы кзана","оружие кзана"}}},fp="15,199,23.433.0,23.172.0,33.161.0,38.192.0"}
P.entries["npc:lady-anacondra"] = {n="Повелительница Анакондра",s="Повелительница Анакондра — одна из Повелителей клыка, возглавляющих Друидов Клыка в Пещерах Стенаний. Когда-то она была ночной эльфийкой-послушницей по имени Алыйлист и первой вызвалась участвовать в дерзком замысле Наралекса исцелить Степи. Когда единение ее наставника с Изумрудным Сном обернулось кошмаром, ее разум сломался, а преданность превратилась в ядовитое стремление увидеть Калимдор заполоненным змеями.",h="Повелительница Анакондра — одна из Повелителей клыка, возглавляющих Друидов Клыка в Пещерах Стенаний.",kw={"anacondra","barrens","druids of the fang","fanglord","gem of anacondra","lady anacondra","naralex","scarletleaf","wailing caverns","анакондра","степи","друиды клыка","повелитель клыка","самоцвет анакондры","повелительница анакондра","наралекс","алыйлист","пещеры стенаний"},ang={["class:Druid"]="Анакондра — поучительная трагедия для друидов Кенария: искренняя послушница, чье рвение исцелить землю сделало ее уязвимой для кошмара, превратившего ее единение в безумие.",["faction:Horde"]="Орда не может позволить Анакондре и Повелителям клыка угрожать хрупким источникам жизни Степей, поэтому ее устранение жизненно важно для безопасности Перекрестка и ближайших оазисов.",["race:NightElf"]="Видеть, как сестра из рода кальдораев отбросила свое наследие и облик ради извращенной змеиной мечты, — отрезвляющее напоминание об опасностях, таящихся в Изумрудном Сне."},sec={{t="От Алыйлист к змее",b="До того как принять змеиный титул, Повелительница Анакондра была известна как Алыйлист. Когда старший друид Наралекс задумал добраться до подземных источников Степей через Изумрудный Сон, она первой вызвалась ему помочь. Но ее рвение стало ее погибелью. Когда разум Наралекса захватили темные видения, кошмар просочился из мира грез и поразил его учеников, разрушив рассудок Алыйлист и обратив ее грезы в холодную, змеиную одержимость."},{t="Повелитель клыка в глубинах",b="Теперь называя себя Повелительницей Анакондрой, она стоит на страже в первых подземных залах Пещер Стенаний. Как и другие Повелители клыка, она отказалась от традиционных заветов Круга Кенария ради свирепых черт гадюки. Повелевая молниями, силами природы и сонными трансами, она поддерживает извращенный сон Наралекса и старается распространить скверну кошмара на засушливые земли наверху."}},faq={{q="Кем была Повелительница Анакондра раньше?",a="Раньше она была молодой ночной эльфийкой-послушницей по имени Алыйлист. Она первой из учеников вызвалась сопровождать друида Наралекса в его походе в Степи.",al={"anacondra real name","who is scarletleaf","scarletleaf backstory","настоящее имя анакондры","кто такая алыйлист","история алыйлист"}},{q="Почему она отвернулась от Круга Кенария?",a="Когда Наралекс попытался соединиться с Изумрудным Сном под Степями, его мысли захлестнул кошмар. Тот же кошмар поразил разум его послушников, исказив Алыйлист и заставив ее отринуть прежнюю жизнь ради служения извращенному сну.",al={"why is anacondra evil","how did she become a druid of the fang","why did scarletleaf fall","почему анакондра злая","как она стала друидом клыка","почему алыйлист пала"}},{q="Какова ее роль в Пещерах Стенаний?",a="Она — одна из четырех Повелителей клыка, возглавляющих Друидов Клыка. Она охраняет верхние ярусы пещер, следя, чтобы Наралекс оставался в плену искаженного сна, грезя о змеином будущем мира.",al={"what does anacondra do","lady anacondra purpose","why kill anacondra","что делает анакондра","зачем повелительница анакондра","зачем убивать анакондру"}},{q="Где ее можно найти в пещерах?",a="Повелительница Анакондра бродит по первой большой сети пещер у входа в Пещеры Стенаний. Она патрулирует среди пещерных ящеров и змей, часто перемещаясь между несколькими местами отдыха.",al={"anacondra location","where is lady anacondra","anacondra spawn","где анакондра","где повелительница анакондра","появление анакондры"}},{q="Какой предмет у нее нужно добыть для Круга Кенария?",a="У нее хранится Самоцвет Анакондры. Убить ее и забрать самоцвет требует друид Нара Буйногривая в Громовом Утесе, чтобы разорвать хватку Повелителей клыка над Степями.",al={"gem of anacondra","leaders of the fang anacondra","anacondra quest item","самоцвет анакондры","предводители клыка анакондра","предмет задания анакондры"}},{q="Какими силами она владеет в бою?",a="Она черпает силу природы, поражая врагов издалека жгучими молниями и насылая магический сон, чтобы обезвредить захватчиков, пока ее змеиные союзники атакуют.",al={"anacondra abilities","anacondra spells","anacondra attacks","способности анакондры","заклинания анакондры","атаки анакондры"}}},fp="14,388,27.516.0,22.419.0,34.172.0,45.267.0,40.229.0,42.196.0,52.169.0,37.176.0"}
P.entries["npc:lady-sarevess"] = {n="Леди Саревесс",s="Леди Саревесс — искаженная наг-чародейка, обитающая в затопленных руинах Непроглядной Пучины, где она занимается темным колдовством.",h="Леди Саревесс — искаженная наг-чародейка, обитающая в затопленных руинах Непроглядной Пучины, где она...",kw={"aku'mai","blackfathom deeps","lady sarevess","naga","pool of ask'ar","sarevess","sea witch","twilight's hammer","аку'май","непроглядная пучина","леди саревесс","наги","пруд аск'ара","саревесс","морская ведьма","сумеречный молот"},ang={["class:Mage"]="Саревесс показывает, как магические практики высокорожденных выродились в необузданные хаотичные молнии и колдовство приливов под гнетом многовекового океанского разложения.",["race:NightElf"]="Руины, где обитает леди Саревесс, когда-то были священным храмом Элуны. Для ночных эльфов вид того, как ее искаженные сородичи-наги оскверняют воды Аскара, — горькое напоминание о Расколе."},sec={{t="Грот в глубинах",b="В Пруду Аск'ара леди Саревесс проводит свои ритуалы в затопленном гроте разрушенного храма. Это крайне извращенная заклинательница, балующаяся темной магией, пока культисты Сумеречного Молота, также обитающие в затонувшем храме, совершают собственные обряды глубже в пещере."},{t="Колдовство приливов",b="Подобно морской ведьме глубоких океанов, Саревесс повелевает стихийными течениями и потрескивающими дугами молний. Окруженная верными стражами-нагами и призванными водными элементалями, она яростно защищает свое убежище от любых незваных гостей, угрожающих ее темным делам."}},faq={{q="Кто такая леди Саревесс?",a="Леди Саревесс — наг-заклинательница, обосновавшаяся в подземном Пруду Аск'ара в Непроглядной Пучине. Это крайне извращенная заклинательница, балующаяся темной магией.",al={"who is sarevess","sarevess lore","lady sarevess backstory","кто такая саревесс","предания о саревесс","история леди саревесс"}},{q="Где можно найти леди Саревесс?",a="Она устроила логово в Пруду Аск'ара — затопленном зале в начале храмового комплекса Непроглядной Пучины на побережье Ясеневого леса.",al={"sarevess location","where is lady sarevess","pool of askar","где саревесс","где леди саревесс","пруд аск'ара"}},{q="Какими силами повелевает леди Саревесс?",a="Опираясь на традиции морских ведьм наг, Саревесс владеет мощной водной и стихийной магией, особенно яростными разрядами ветвистой молнии, чтобы поразить любого, кто войдет в ее бухту.",al={"sarevess magic","sarevess abilities","магия саревесс","способности саревесс"}}},fp="13,134,21.274.0,20.262.0,21.188.0,33.156.0,39.192.0"}
P.entries["npc:laird"] = {n="Лайрд",s="Лайрд — ночной эльф, торговец рыбой в прибрежной гостинице Аубердина. Работая на туманном побережье Темных берегов, он снабжает путников и рыбаков, рискующих выходить на суровый берег, товарами и кулинарными рецептами.",h="Лайрд — ночной эльф, торговец рыбой в прибрежной гостинице Аубердина.",kw={"auberdine","darkshore","fillet of frenzy","fish vendor","laird","nessa shadowsong","аубердин","темные берега","филе бешенки","торговец рыбой","лайрд","несса песня теней"},ang={["profession:Cooking"]="Путешествующие повара, бывающие на Темных берегах, часто ищут Лайрда ради рецепта, как правильно разделывать и готовить свирепую бешенку, обитающую в водах Калимдора.",["race:NightElf"]="Лайрд олицетворяет простых ночных эльфов-торговцев, которые обосновались на берегах материка и поддерживают растущую прибрежную сеть Калимдора."},sec={{t="Портовый торговец",b="Лайрд находится в шумной гостинице Аубердина и продает свежую рыбу и припасы морякам, местным жителям и странствующим искателям приключений. Воды Темных берегов бурные и опасные, не то что защищенные берега Тельдрассила, но Лайрд хорошо знает: риск приносит награду. Для смелых рыболовов, готовых забросить удочки на туманных пляжах, местный улов приносит немалую прибыль."},{t="Связи через воду",b="Лайрд тесно связан с рыболовным промыслом по ту сторону пролива, в Тельдрассиле. Он служит важным контактом для курьерских рейсов между островными ветвями Деревни Рут'теран и портом на материке: принимает грузы от своей коллеги-рыбачки Нессы Песня Теней и следит за тем, чтобы прибрежная торговля не прерывалась."}},faq={{q="Где найти Лайрда?",a="Лайрд находится в помещении, на первом этаже гостиницы в Аубердине — главном поселении Альянса на побережье Темных берегов.",al={"laird location","where is laird","laird auberdine","лайрд местонахождение","где лайрд","лайрд аубердин"}},{q="Что продает Лайрд?",a="Он продает разную выловленную рыбу и кулинарные ингредиенты, а также рецепт приготовления филе бешенки.",al={"laird vendor","what does laird sell","laird wares","лайрд торговец","что продает лайрд","товары лайрда"}},{q="Какие задания связаны с Лайрдом?",a="Лайрд получает доставку от Нессы Песня Теней из Деревни Рут'теран в задании «Полет в Аубердин», после чего просит искателей приключений передать весточку через море.",al={"laird quests","auberdine fish quest","лайрд задания","задание про рыбу аубердин"}},{q="Почему Лайрд считает рыбалку на Темных берегах выгодной, несмотря на опасность?",a="Лайрд отмечает, что хотя туманный берег Темных берегов таит гораздо больше опасностей, чем спокойные воды Тельдрассила, обилие экзотических морских обитателей делает промысел намного прибыльнее для предприимчивых рыбаков.",al={"laird gossip","is darkshore good for fishing","лайрд болтовня","хороша ли рыбалка на темных берегах"}}},fp="5,224,17.404.0,21.323.0,23.128.0,21.123.0,26.193.0,72.215.0"}
P.entries["npc:lakota-windsong"] = {n="Лакота Песня Ветра",s="Лакота Песня Ветра — молодая тауренка, удерживаемая в плену на утесах Пика Темного Облака в Тысяче Игл. После того как она отвергла нежеланное предложение Арнака Зловещего Тотема, ее похитили силой, и теперь она ждет спасения от лап племени Зловещего Тотема.",h="Лакота Песня Ветра — молодая тауренка, удерживаемая в плену на утесах Пика Темного Облака в Тысяче Игл.",ang={["faction:Horde"]="Спасение Лакоты — удар по господству Зловещего Тотема над Тысячей Игл, обеспечивающий безопасный путь путникам, отдыхающим на Заставе Вольного Ветра.",["race:Tauren"]="Испытание Лакоты — суровое напоминание о предательстве, зреющем среди Зловещего Тотема, чье неповиновение руководству Кэрна Кровавого Копыта регулярно оборачивается насилием."},sec={{t="Смертельное ухаживание",b="Вскоре после Третьей войны за Лакотой Песня Ветра стал ухаживать Арнак Зловещий Тотем. Не желая вступать в его клан или принимать ухаживания, она отвергла его предложение. Арнак не принял отказа: он вернулся под покровом ночи, убил брата Лакоты, когда тот попытался вмешаться, и унес ее в неприступные выси Тысячи Игл. Заточенная высоко над дном каньона на Пике Темного Облака, она остается в плену под усиленной охраной, а Арнак по-прежнему настаивает на том, чтобы сделать ее своей женой."},{t="Спуск к безопасности",b="Окруженная коварными бандитами Зловещего Тотема, Лакота не может в одиночку спуститься со скал. Только храбрый спутник способен провести ее по подвесным мостам и извилистым тропам к котловине каньона внизу. Вырвавшись с Пика Темного Облака, Лакота бежит к безопасной Заставе Вольного Ветра, неся весть о своем спасении Талии Янтарной Шкуре и стоящим там защитникам."}},faq={{q="Почему Лакоту Песня Ветра держат на Пике Темного Облака?",a="Она отвергла предложение руки и сердца от Арнака Зловещего Тотема. Вместо того чтобы принять отказ, Арнак убил ее брата и похитил Лакоту, увезя ее в оплот Зловещего Тотема на Пике Темного Облака в надежде принудить ее к согласию.",al={"why is lakota captured","who kidnapped lakota","why is lakota in darkcloud pinnacle","почему лакота в плену","кто похитил лакоту","почему лакота на пике темного облака"}},{q="Куда идет Лакота после спасения?",a="Благополучно добравшись до подножия Пика Темного Облака, Лакота идет к Заставе Вольного Ветра, где найдет приют среди защитников Орды и расскажет о своих злоключениях Талии Янтарной Шкуре.",al={"where does lakota run","where does she go after escort","lakota destination","куда бежит лакота","куда она идет после сопровождения","цель лакоты"}},{q="Кто такой Арнак Зловещий Тотем?",a="Арнак — свирепый воин вероломного клана Зловещего Тотема, который убил брата Лакоты и похитил ее, когда она отказалась выйти за него замуж.",al={"who is arnak","who kidnapped her","arnak lore","кто такой арнак","кто похитил ее","история арнака"}}},fp="15,245,18.504.0,17.388.1,56.226.0,41.187.1,23.139.0"}
P.entries["npc:lanka-farshot"] = {n="Ланко Дальний Выстрел",s="Ланко Дальний Выстрел — тауренский наставник охотников в Лагере Нараче на Плато Красного Облака. Он направляет начинающих тауренов-охотников в их первых шагах в выслеживании, стрельбе и выживании на равнинах Мулгора.",h="Ланко Дальний Выстрел — тауренский наставник охотников в Лагере Нараче на Плато Красного Облака.",kw={"camp narache","hunter trainer","lanka farshot","mulgore","red cloud mesa","tauren hunter","лагерь нараче","наставник охотников","ланко дальний выстрел","мулгор","плато красного облака","таурен-охотник"},ang={["class:Hunter"]="Для тауренов-охотников, начинающих обучение в Мулгоре, Ланко Дальний Выстрел — самый первый наставник, которого они встречают; он учит основам стрельбы и выживания в дикой природе.",["race:Tauren"]="Ланко воплощает традиционную охотничью философию тауренов: он видит в стрельбе и выслеживании важный долг по защите племени и жизни в равновесии с равнинами."},sec={{t="Наставник Плато Красного Облака",b="Ланко Дальний Выстрел несет дозор в Лагере Нараче и встречает новых тауренов, призванных на путь охотника. Новобранцы приходят с выгравированной запиской, направляющей их за советом к нему. Под его бдительным оком ученики постигают основы дальнего боя, выслеживания добычи и уважения к диким зверям, бродящим по травянистым равнинам Мулгора. Его уроки позволяют каждому молодому охотнику стать умелым разведчиком и добытчиком для племени."}},faq={{q="Кто такой Ланко Дальний Выстрел?",a="Ланко Дальний Выстрел — тауренский наставник охотников в Лагере Нараче на Плато Красного Облака в Мулгоре. Он дает начальное обучение и наставления молодым охотникам, начинающим свой путь.",al={"who is lanka","lanka farshot npc","camp narache hunter","кто такой ланко","ланко дальний выстрел","охотник лагерь нараче"}},{q="Какие задания дает Ланко Дальний Выстрел?",a="Ланко Дальний Выстрел принимает молодых тауренов-охотников, которых присылают к нему с выгравированной запиской по прибытии в Лагерь Нараче, и направляет их на путь охотника, пока они осваивают основы своего ремесла.",al={"lanka farshot quests","hunter quests camp narache","задания ланко дальний выстрел","задания охотника лагерь нараче"}},{q="Родственник ли Ланко Дальний Выстрел Микси Дальний Выстрел?",a="Несмотря на одинаковую фамилию, нет свидетельств того, что Ланко Дальний Выстрел в родстве с гоблином Микси Дальний Выстрел.",al={"is lanka related to mixie","mixie farshot relation","родственник ли ланко микси","родство микси дальний выстрел"}}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="Лар Ночной Клык",s="Лар Ночной Клык — тролль-часовой из племени Черного Копья, несущий службу к юго-западу от Деревни Сен'джин в Дуротаре. Со своего поста на границе он следит за угрозами молодому поселению троллей и направляет искателей приключений сдерживать натиск ближайших врагов.",h="Лар Ночной Клык — тролль-часовой из племени Черного Копья, несущий службу к юго-западу от Деревни Сен'джин в...",kw={"darkspear","durotar","kolkar","lar prowltusk","northwatch","sen'jin village","troll","черное копье","дуротар","колкар","лар ночной клык","деревня сен'джин","тролль"},ang={["faction:Horde"]="Лар Ночной Клык воплощает борьбу Орды за защиту границ Дуротара от внешних угроз прямо у порога ее молодой столицы.",["race:Troll"]="Для племени Черного Копья разведчики вроде Лара Ночного Клыка жизненно важны для защиты хрупкого нового дома племени в Дуротаре от агрессивных кланов кентавров и наступающих сил людей."},sec={{t="Дозорный на побережье",b="Лар Ночной Клык, расположившийся к юго-западу от Деревни Сен'джин на суровом побережье Дуротара, — один из передовых часовых племени Черного Копья. Тролли все еще пытаются обрести постоянный дом после бегства с затонувшей цепи островов, и Деревня Сен'джин постоянно подвергается нападкам враждебных соседей. Лар руководит разведчиками и воинами, следя за передвижениями на побережье и сдерживая натиск враждебных сил, особенно кентавров Колкара, чтобы хрупкое поселение могло перевести дух."}},faq={{q="Кто такой Лар Ночной Клык?",a="Лар Ночной Клык — тролль из племени Черного Копья, выдающий задания, к юго-западу от Деревни Сен'джин в Дуротаре. Он помогает охранять окраины поселения, нанимая способных путников из Орды, чтобы поражать местные угрозы, пока они не добрались до самой деревни.",al={"lar prowltusk","who is lar prowltusk","lar prowltusk durotar","лар ночной клык","кто такой лар ночной клык","лар ночной клык дуротар"}},{q="На каких угрозах сосредоточен Лар Ночной Клык?",a="Лар сосредоточен на опасностях границы, угрожающих югу Дуротара, в первую очередь на разбойничьих стаях кентавров Колкара, вторгающихся на земли троллей.",al={"lar prowltusk quests","what does lar prowltusk want"}},{q="Где можно найти Лара Ночного Клыка?",a="Он находится на юге Дуротара и следит за тропами к юго-западу от Деревни Сен'джин.",al={"lar prowltusk location","where is lar prowltusk","лар ночной клык местонахождение","где лар ночной клык"}}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laris-geardawdle"] = {n="Ларис Обалдуй",s="Ларис Обалдуй — эксцентричный гном-исследователь, работающий в библиотеке Зала Исследователей в Стальгорне. Он посвятил свою научную жизнь изучению странной природы и происхождения слизи по всему Азероту. Искатели приключений, готовые собирать образцы едкой слизи, находят в нем увлеченного, хотя и слегка безумного покровителя.",h="Ларис Обалдуй — эксцентричный гном-исследователь, работающий в библиотеке Зала Исследователей в Стальгорне.",kw={"gnome","hall of explorers","ironforge","laris geardawdle","library","ooze","slime","гном","зал исследователей","стальгорн","ларис обалдуй","библиотека","слизь"},ang={["faction:Alliance"]="Работая в Зале Исследователей, Ларис трудится под широким покровительством науки, спонсируемой Альянсом, добавляя эксцентричное естествознание к историческим раскопкам Лиги.",["race:Gnome"]="Ларис воплощает истинно гномье стремление искать знания там, где все остальные ничего не замечают, даже если для этого приходится совать руки в зловонную болотную грязь."},sec={{t="Знаток слизи",b="Укрывшись среди высоких книжных полок и древних реликвий Зала Исследователей, Ларис Обалдуй занимается довольно непривлекательной областью натурфилософии: происхождением слизи. Пока его дворфийские коллеги корпят над табличками Титанов и древней каменной резьбой, Ларис убежден, что мерзкие студенистые чудовища Азерота хранят увлекательные алхимические и биологические тайны. Он поручает странствующим исследователям собирать едкие образцы в далеких уголках мира, стремясь проверить свои странные гипотезы о том, как эти бездумные лужицы злобы оживают."}},faq={{q="Кто такой Ларис Обалдуй?",a="Ларис Обалдуй — гном-исследователь, живущий в библиотеке Зала Исследователей в Стальгорне. Свои необычные исследования он посвящает слизи и странным механизмам ее самозарождения.",al={"laris","geardawdle","who is laris","ларис","обалдуй","кто такой ларис"}},{q="Where can I find Laris Geardawdle?",a="Его можно найти в северном крыле Стальгорна, в Зале Исследователей, в тихих уголках библиотеки.",al={"laris location","where is laris","find laris geardawdle"}},{q="Почему он изучает слизь?",a="Ларис обладает острым, эксцентричным научным умом и выработал особые теории о природе и возникновении живой слизи. Он полагает, что анализ едких остатков разных слизей позволит глубже понять, как формируются и размножаются эти странные организмы.",al={"why oozes","laris slime research","ooze study","почему слизь","исследование слизи ларис","изучение слизи"}},{q="Какие задания он дает искателям приключений?",a="Ларис нанимает смелых путников отправляться в опасные земли за образцами чистой слизи. В задании «Долгий путь слизнюка» он выдает пустые банки для сбора и просит искателей приключений собирать вязкие остатки с живой слизи.",al={"laris quests","a little slime goes a long way","задания ларис","долгий путь слизнюка"}}},fp="16,316,16.558.0,24.220.0,34.139.0,25.279.0,37.260.0"}
P.entries["npc:lars"] = {n="Ларс",s="Ларс — измученный человек-выживший, разбивший лагерь в глуши Сумеречного леса. Вместе со своим товарищем Свеном Йоргеном он пытается удержаться на северном краю Затихшего берега, противостоя ужасам, что рыщут в лесу.",h="Ларс — измученный человек-выживший, разбивший лагерь в глуши Сумеречного леса.",kw={"camp","duskwood","hushed bank","lars","sven yorgen","wolves","wolves at our heels","лагерь","сумеречный лес","затихший берег","ларс","свен йорген","волки","волки идут по пятам"},ang={["faction:Alliance"]="Ларс — измученный мирный житель-человек, выживающий за пределами досягаемости городской стражи; он рад найти защитников Альянса, готовых перебить волков, кружащих вокруг его стоянки."},sec={{t="Опасное пристанище",b="Расположившись в скромном лагере на северном краю Затихшего берега, Ларс с трудом выживает вдали от сомнительной безопасности Темнолесья. Сумеречный лес опасен в лучшие времена, но окрестные чащи кишат свирепыми зверями, неумолимой нежитью и подкрадывающимися воргенами. Ларс держится рядом со Свеном Йоргеном, стремясь лишь остаться в живых в становящейся все более враждебной глуши."},{t="Угроза из глуши",b="Выживание в лагере требует постоянной бдительности перед местными хищниками. Ларсу приходится туго из-за неумолимых стай голодных лютых волков, рыщущих в тенях вокруг их костра. Не в силах ни ослабить бдительность, ни отогнать их в одиночку, он полагается на способных путников, которые проредят голодных хищников, пока его маленький лагерь не был полностью захвачен."}},faq={{q="Кто такой Ларс?",a="Ларс — человек-выживший, разбивший лагерь в глуши Сумеречного леса. Он живет вместе со своим другом и товарищем Свеном Йоргеном на северной границе Затихшего берега, делая все возможное, чтобы пережить ужасы леса.",al={"lars duskwood","who is lars","lars npc","ларс сумеречный лес","кто такой ларс","ларс"}},{q="Где можно найти Ларса?",a="Ларс находится в небольшом лагере в глуши на северном краю Затихшего берега, на западе Сумеречного леса.",al={"where is lars","lars location","lars camp","где ларс","ларс местонахождение","лагерь ларса"}},{q="С какой проблемой сталкивается Ларс?",a="Ларса и Свена постоянно донимают голодные волки и хищники, скрывающиеся в близлежащем лесу. В задании «Волки идут по пятам» Ларс просит проходящих мимо искателей приключений выследить хищников, прежде чем они разорвут его лагерь.",al={"lars quest","wolves at our heels quest","why does lars need help","задание ларса","волки идут по пятам","зачем ларсу помощь"}},{q="Как Ларс связан со Свеном Йоргеном?",a="Ларс и Свен Йорген — товарищи, вместе выживающие в глуши. У Свена своя мрачная история и месть в этом краю, а Ларс помогает поддерживать их грубый, уединенный форпост.",al={"lars and sven","who is sven to lars","ларс и свен","кто такой свен для ларса"}}},fp="4,232,18.391.0,21.358.0,12.212.0,24.118.0,28.233.0,43.188.0"}
P.entries["npc:laurna-morninglight"] = {n="Лорна Утренний Свет",s="Лорна Утренний Свет — ночная эльфийка, наставница жрецов, живущая в тихом поселении Доланаар в Тельдрассиле. Преданная Сестринству Элуны, она обучает юных послушниц, покинувших Тенистую долину, духовным обрядам и целительным дарам Богини Луны. Ее уроки готовят молодых жрецов-ночных эльфов к растущим угрозам, подступающим к ветвям Мирового Древа.",h="Лорна Утренний Свет — ночная эльфийка, наставница жрецов, живущая в тихом поселении Доланаар в Тельдрассиле.",kw={"dolanaar","elune","kaldorei","laurna","morninglight","priest trainer","sisterhood of elune","teldrassil","доланаар","элуна","кальдораи","лорна","утренний свет","наставник жрецов","сестринство элуны","тельдрассил"},ang={["class:Priest"]="Для жрецов-ночных эльфов, пришедших из Тенистой долины, Лорна Утренний Свет — первая крупная наставница за пределами родной долины: она учит основным заклинаниям и направляет вашу раннюю преданность Элуне.",["race:NightElf"]="Лорна воплощает традиционную преданность кальдораев Богине Луны, напоминая искателям приключений, что служение жрецов в Тельдрассиле черпает силу из Элуны, а не из Света."},sec={{t="Проводник в Доланааре",b="Лорна Утренний Свет, живущая среди ветвей Доланаара, — одна из главных наставниц для молодых жрецов, завершивших первые обряды в Тенистой долине. Когда новые послушники выходят в более широкие просторы Тельдрассила, она учит их углублять связь с Элуной, сочетая свет исцеления с защитными обрядами, необходимыми, чтобы выжить во все более враждебных землях."},{t="Преданность Богине Луны",b="Служение жрецов у кальдораев тесно связано с поклонением Элуне, а не отвлеченному Свету, которому поклоняются люди и дворфы. Лорна поручает ученикам духовные труды: получить священные одеяния и исцелить раненого часового. Благодаря этим традициям послушники понимают, что их силы — прямой дар Матери Луны, призванный хранить и исцелять народ кальдораев."}},faq={{q="Где найти Лорну Утренний Свет?",a="Лорна Утренний Свет находится в деревне Доланаар в центральной части Тельдрассила, неподалеку по дороге от Тенистой долины.",al={"laurna location","where is laurna","dolanaar priest trainer","где лорна","местонахождение лорны","наставник жрецов доланаар"}},{q="Чем занимается Лорна Утренний Свет?",a="Она наставница жрецов для персонажей-ночных эльфов. Она обучает новым заклинаниям, повышает ранги известных умений и дает начальные наставления в обрядах класса.",al={"what does she do","laurna role","laurna priest trainer","чем занимается она","роль лорны","лорна наставник жрецов"}},{q="Какие задания она дает?",a="Она дает классовые задания начинающим жрецам, отправляя их помогать раненым соратникам и искать божественной милости Элуны с помощью церемониальных облачений и молитв.",al={"laurna quests","priest quests dolanaar","задания лорны","задания жрецов доланаар"}},{q="Обучает ли она другие расы?",a="Хотя Лорна культурно связана с Сестринством Элуны, наставники жрецов Альянса обучают любого союзного жреца, пришедшего за духовным наставлением.",al={"can humans train here","priest trainer any race","могут ли люди учиться здесь","наставник жрецов любая раса"}},{q="Связана ли она с Храмом Луны?",a="Да, как жрица кальдораев, она всецело посвятила свои обеты и магию богине Элуне и более широким традициям, которые направляет Храм Луны в Дарнассе.",al={"is she sisterhood of elune","laurna temple of the moon","состоит ли она в сестринстве элуны","лорна храм луны"}},{q="Есть ли у нее общая фамилия с другими ночными эльфами?",a="Родственники Лорны среди кальдораев Тельдрассила неизвестны.",al={"morninglight family","laurna relatives","семья утренний свет","родственники лорны"}}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lelanai"] = {n="Леланай",s="Леланай — ночная эльфийка, заведующая ездовыми животными в Анклаве Кенария в Дарнассе. Она предоставляет достойным всадникам свирепых саблезубых скакунов ночных эльфов, предлагая сородичам и доверенным союзникам Дарнасса как обычных ночных саблезубов, так и быстрых боевых зверей.",h="Леланай — ночная эльфийка, заведующая ездовыми животными в Анклаве Кенария в Дарнассе.",kw={"cenarion enclave","darnassus","frostsaber","jartsam","lelanai","mount vendor","nightsaber","анклав кенария","дарнасс","ледяной саблезуб","джартсам","леланай","торговец скакунами","ночной саблезуб"},ang={["faction:Alliance"]="Герои Альянса, достигшие уровня «Превознесение» с Дарнассом, могут обратиться к Леланай, чтобы отправиться в бой на легендарных саблезубах бок о бок с союзниками-кальдораями.",["race:NightElf"]="Для ночных эльфов визит к Леланай — важный обряд посвящения при получении традиционных кошачьих скакунов."},sec={{t="Заводчица Анклава Кенария",b="Леланай, стоящая рядом с инструктором верховой езды Джартсамом среди высоченных деревьев Анклава Кенария, ухаживает за одними из лучших больших кошек Калимдора. Ночные эльфы издавна связаны глубокими узами со свирепыми хищниками северных лесов и обучают ночных саблезубов и ледяных саблезубов нести часовых и разведчиков по трудной местности с хищной грацией. Леланай — главная поставщица этих почитаемых скакунов в столице."},{t="Узы, выходящие за пределы родства",b="While saber mounts are freely offered to any night elf of appropriate skill, outsiders face a much stricter threshold. Given the sacred nature of the cats and the natural aloofness of the kaldorei, Lelanai will not entrust a beast to non-night elf adventurers unless they have earned the highest degree of respect and renown with the city of Darnassus."}},faq={{q="Где найти Леланай?",a="Леланай находится в Анклаве Кенария в Дарнассе, рядом с наставником верховой езды на тиграх Джартсамом.",al={"lelanai location","where is lelanai","lelanai map","где леланай","местонахождение леланай","леланай на карте"}},{q="Что продает Леланай?",a="Она продает поводья разных пород ледяных и ночных саблезубов, включая быстрых бронированных скакунов для опытных всадников.",al={"lelanai wares","what mounts does she have","night elf mounts","товары леланай","какие скакуны у нее есть","скакуны ночных эльфов"}},{q="Могут ли не ночные эльфы покупать скакунов у Леланай?",a="Да, но только если они доказали исключительную верность и достигли уровня «Превознесение» в репутации с Дарнассом. В противном случае она откажется продавать своих зверей чужакам.",al={"can humans buy sabers","can dwarfs ride nightsabers","reputation required for sabers","могут ли люди купить саблезубов","могут ли дворфы ездить на ночных саблезубах","репутация для саблезубов"}},{q="Могут ли игроки Орды взаимодействовать с Леланай?",a="Нет. Леланай верна Дарнассу, фракции Альянса. Она и стражи анклава поблизости будут считать представителей Орды враждебными захватчиками.",al={"can horde buy sabers","is lelanai friendly to horde","может ли орда купить саблезубов","дружелюбна ли леланай к орде"}}},fp="7,257,31.437.0,20.352.0,25.112.0,23.126.0,44.160.0,40.150.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="Лейтенант Фаррен Оринель",s="Лейтенант Фаррен Оринель — офицер армии Штормграда, сейчас расквартированный в таверне Южнобережья в Предгорьях Хилсбрада. Крайне недовольный пограничным назначением, он проводит большую часть времени за выпивкой, перекладывая свои обязанности на проезжих путников. Его главное военное поручение — разобраться с наступающими вдоль побережья мурлоками, и эту работу он охотно сваливает на других в надежде добиться перевода обратно на юг.",h="Лейтенант Фаррен Оринель — офицер армии Штормграда, сейчас расквартированный в таверне Южнобережья в...",kw={"farren","hillsbrad","marshal redpath","murloc","orinelle","reassignment","southshore","stormwind","фаррен","хилсбрад","маршал редпат","мурлок","оринель","перевод","южнобережье","штормград"},ang={["faction:Alliance"]="Для защитников Альянса Оринель олицетворяет недовольных южных солдат, удерживающих одинокий северный форпост и готовых заплатить монетой и похвалой тому, кто выполнит его обязанности.",["race:Human"]="Для штормградского солдата, застрявшего вдали от Элвиннского леса, презрение Оринеля к службе на северной границе подчеркивает разрыв между удобной столичной жизнью и суровой заморской службой."},sec={{t="Ссылка в Южнобережье",b="Лейтенант Фаррен Оринель не выбирал Южнобережье. Отправленный далеко от Штормграда, лейтенант считает сырые, спорные берега Хилсбрада жалким падением по сравнению с цивилизованным комфортом столицы. Вместо того чтобы патрулировать поля или координировать оборону с вышестоящим офицером, маршалом Редпатом, Оринель практически поселился в таверне Южнобережья. Его дни проходят в унынии, выпивке и мечтах о приказе о переводе, который вернет его на юг."},{t="Перекладывание долга",b="Несмотря на удобное место в таверне, Оринель все же подчиняется маршалу Редпату, который поручил лейтенанту очистить ближайшее побережье от кишащих мурлоков. Не желая пачкать сапоги в прибрежной грязи, Оринель полагается на странствующих искателей приключений, которые истребляют тварей и собирают доказательства их гибели. Он надеется, что предъявленные начальству осязаемые результаты покажут, что долг исполнен, и ускорят его возвращение в Штормград."}},faq={{q="Кто такой лейтенант Фаррен Оринель?",a="Это офицер армии Штормграда, расквартированный в Южнобережье, городке в Предгорьях Хилсбрада. Его можно найти за выпивкой в таверне Южнобережья, где он ворчит на свое назначение.",al={"farren orinelle","who is orinelle","southshore lieutenant","фаррен оринель","кто такой оринель","лейтенант южнобережья"}},{q="Почему он в Южнобережье?",a="Его перевели на север из Штормграда, чтобы усилить местный гарнизон и поддержать маршала Редпата. Назначение ему крайне не нравится, и он мечтает вернуться домой.",al={"why is farren in southshore","orinelle transfer","почему фаррен в южнобережье","перевод оринеля"}},{q="Каково его официальное поручение?",a="Маршал Редпат приказал ему разобраться с враждебными мурлоками, наводнившими побережье Хилсбрада, хотя Оринель предпочитает платить странствующим наемникам, чтобы те сражались за него.",al={"farren duty","orinelle mission","farren murlocs","долг фаррена","задание оринеля","фаррен мурлоки"}},{q="Покидает ли он когда-нибудь таверну Южнобережья?",a="Нет. Оринель проводит почти все время у барной стойки таверны, не желая выходить на грязные пляжи и навстречу опасностям снаружи.",al={"where to find farren","farren location","orinelle inn","где найти фаррена","местонахождение фаррена","оринель таверна"}},{q="Какова конечная цель Фаррена?",a="Он хочет лишь одного — добиться официального перевода обратно в Штормград, подальше от опасностей и уныния побережья Лордерона.",al={"what does farren want","reassignment","чего хочет фаррен","перевод"}},{q="Кто командир Оринеля?",a="Он подчиняется маршалу Редпату, который командует военным отрядом Альянса, защищающим Южнобережье.",al={"farren superior","farren boss","who commands farren","начальник фаррена","командир фаррена","кто командует фарреном"}}},fp="26,423,19.515.0,16.458.0,34.183.0,24.167.0,32.172.0,38.136.0,31.143.0,28.98.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="Лейтенант Хаггердин",s="Лейтенант Хаггердин — офицер-дворф, расквартированный на Мысе в Альтеракских горах. Он стоит на страже у укрепленных ворот Альтеракской долины и служит главным офицером по набору и связи Стражи Грозовой Вершины. Он оценивает будущих героев Альянса и награждает тех, кто проявил доблесть в борьбе с кланом Северного Волка.",h="Лейтенант Хаггердин — офицер-дворф, расквартированный на Мысе в Альтеракских горах.",kw={"alterac","dwarf","frostwolf","haggerdin","headland","ironforge","lieutenant","proving grounds","stormpike","альтерак","дворф","северный волк","хаггердин","мыс","стальгорн","лейтенант","испытательные земли","грозовая вершина"},ang={["faction:Alliance"]="Лейтенант Хаггердин — ваш главный контакт у входа в Альтеракскую долину: он выдает удостоверения и официальные почести, заслуженные в схватках с кланом Северного Волка.",["faction:Horde"]="Стойкий часовой у портала Альянса в Альтеракскую долину, Хаггердин направляет подкрепления, посланные сокрушить орков Северного Волка.",["race:Dwarf"]="Гордый офицер клана Грозовой Вершины, Хаггердин воплощает решимость Стальгорна раскрыть наследие титанов среди заснеженных скал Альтерака."},sec={{t="Страж ворот Мыса",b="Лейтенант Хаггердин наблюдает с заснеженных высот Мыса над Предгорьями Хилсбрада за сборным пунктом для продолжающейся кампании Альянса в Альтеракской долине. Дворфийские знамена развеваются рядом с огромными деревянными воротами, а новобранцы и ветераны собираются под его бдительным взором, готовясь шагнуть в ледяную зону боевых действий."},{t="Голос Стражи Грозовой Вершины",b="Хаггердин служит в Экспедиции Грозовой Вершины и следит за тем, чтобы в долине Стальгорн и Великий Альянс представляли только проверенные воины. Через такие испытания, как Испытательные земли, он поручает новобранцам возвращать знамена и реликвии, а по мере продвижения солдат в рядах Стражи Грозовой Вершины вручает им официальные благодарности, знаки отличия и новые звания."}},faq={{q="Кто такой лейтенант Хаггердин?",a="Лейтенант Хаггердин — офицер-дворф, представляющий Стражу Грозовой Вершины. Он расквартирован у входа в Альтеракскую долину на Мысе в Альтеракских горах, ведет набор в Альянс и награждает за заслуги на поле боя.",al={"haggerdin","who is haggerdin","lieutenant haggerdin alterac","хаггердин","кто такой хаггердин","лейтенант хаггердин альтерак"}},{q="Где найти лейтенанта Хаггердина?",a="Он находится на севере Альтеракских гор, на Мысе, прямо у портала и ворот, ведущих в Альтеракскую долину.",al={"haggerdin location","where is lieutenant haggerdin","alterac valley entrance alliance","где хаггердин","где найти лейтенанта хаггердина","вход в альтеракскую долину альянс"}},{q="Какую роль играет Хаггердин в Страже Грозовой Вершины?",a="Он служит офицером связи и интендантом на передовой: проводит испытания для новобранцев, такие как Испытательные земли, и награждает бойцов Альянса более высокими званиями и знаками отличия по мере роста их репутации у Стражи Грозовой Вершины.",al={"what does haggerdin do","haggerdin quests","stormpike guard officer","что делает хаггердин","задания хаггердина","офицер стражи грозовой вершины"}},{q="Почему Альянс сражается в Альтеракской долине?",a="Экспедиция Грозовой Вершины отправилась в долину, чтобы раскопать древние реликвии и узнать историю дворфов, но ее прибытие вызвало жестокий спор за территорию с коренными орками клана Северного Волка и их союзниками из Орды.",al={"why alterac valley","stormpike expedition goal","alterac conflict","почему альтеракская долина","цель экспедиции грозовой вершины","конфликт в альтераке"}},{q="Могут ли игроки Орды общаться с лейтенантом Хаггердином?",a="Нет. Лейтенант Хаггердин — действующий офицер Альянса и нападет на любого героя Орды, который приблизится к воротам Мыса.",al={"is haggerdin hostile to horde","horde haggerdin","can horde talk to haggerdin","враждебен ли хаггердин к орде","хаггердин орда","может ли орда говорить с хаггердином"}},{q="Что такое испытание «Испытательные земли»?",a="Испытательные земли — вводное задание, которое Хаггердин дает будущим солдатам Альянса, чтобы проверить их умения и решимость, прежде чем они полностью посвятят себя войне в Альтеракской долине.",al={"proving grounds quest","proving grounds alterac","haggerdin proving grounds","задание испытательные земли","испытательные земли альтерак","хаггердин испытательные земли"}}},fp="20,345,26.335.0,28.362.0,28.224.0,38.145.0,53.231.0,47.213.0,53.126.0,34.195.0"}
P.entries["npc:lieutenant-lisande"] = {n="Лейтенант Лисанд",s="Лейтенант Лисанд — посланница Серебряного Рассвета, расквартированная на высоких плато Громового Утеса. Будучи человеком, открыто действующим в землях таурен, она служит связной в борьбе с общей смертельной угрозой — Плетью.",h="Лейтенант Лисанд — посланница Серебряного Рассвета, расквартированная на высоких плато Громового Утеса.",kw={"argent dawn","lieutenant lisande","lisande","mulgore","scourge","scourge invasion","thunder bluff","серебряный рассвет","лейтенант лисанд","лисанд","мулгор","плеть","вторжение плети","громовой утес"},ang={["faction:Horde"]="Лисанд напоминает, что война с Плетью требует прагматизма и порой сотрудничества с нейтральными человеческими орденами.",["race:Tauren"]="Хотя Лисанд чужая, таурены уважают преданность Серебряного Рассвета делу очищения земли от мерзкой скверны нежити."},sec={{t="Неожиданная посланница",b="Хотя человеческие лица редки на продуваемых ветрами высотах Громового Утеса, Серебряный Рассвет выше обычной вражды фракций. Лейтенант Лисанд служит священному ордену, высматривая признаки скверны Короля-лича даже в далеком Калимдоре. Когда на равнинах внизу пробуждается нежить, она созывает отважных героев Орды, чтобы те выехали и разведали надвигающуюся угрозу, пока она не осквернила священную землю."}},faq={{q="Почему человек стоит в Громовом Утесе?",a="Лисанд представляет Серебряный Рассвет — нейтральную организацию, посвятившую себя истреблению Плети. Поскольку Рассвет принимает в свои ряды расы и Альянса, и Орды, его посланникам разрешен дипломатический въезд в столицы для согласования обороны против нежити.",al={"human in thunder bluff","why is Lisande here","is she hostile","человек в громовом утесе","почему здесь лисанд","враждебна ли она"}},{q="Чем Серебряный Рассвет интересуется в Мулгоре?",a="Влияние Короля-лича угрожает каждому уголку Азерота, а не только Восточным королевствам. Лисанд следит за любыми признаками некромантии или вторжения Плети, угрожающими миру в Мулгоре, и следит, чтобы местные защитники знали об опасности.",al={"scourge in mulgore","why thunder bluff","undead in tauren lands","плеть в мулгоре","почему громовой утес","нежить в землях таурен"}},{q="Какие задания дает лейтенант Лисанд?",a="Лисанд посылает искателей приключений спуститься с утесов и расследовать вторжения Плети, замеченные в окрестностях, и просит доложить о результатах, чтобы Рассвет мог оценить масштаб угрозы.",al={"lisande quest","what does lisande do","investigate quest","задание лисанд","что делает лисанд","задание на расследование"}}},fp="18,223,17.412.0,41.280.0,46.253.0,44.211.0"}
P.entries["npc:lieutenant-nevell"] = {n="Лейтенант Невилл",s="Лейтенант Невилл — офицер Серебряного Рассвета, расквартированный у ворот Стальгорна в Дун Мороге. Служа оплотом против растущей тьмы Плети, он координирует местных защитников и предупреждает прибывающих искателей приключений о нежити, прощупывающей границы королевства дворфов.",h="Лейтенант Невилл — офицер Серебряного Рассвета, расквартированный у ворот Стальгорна в Дун Мороге.",kw={"argent dawn","dun morogh","ironforge","lieutenant nevell","nevell","scourge","серебряный рассвет","дун морог","стальгорн","лейтенант невилл","невилл","плеть"},ang={["faction:Alliance"]="Для героев Альянса, направляющихся в Стальгорн, Невилл — напоминание о том, что война с Плетью не ограничена севером.",["race:Dwarf"]="Дворфы ценят бдительное око Серебряного Рассвета у стен их горного дома: они знают, что бдительность против некромантии нужна даже на холодных склонах Дун Морога."},sec={{t="Дозор в снегах",b="Хотя Серебряный Рассвет больше всего известен удержанием рубежей в разоренных Чумных землях Лордерона, его бдительность простирается далеко на юг. Лейтенант Невилл, стоящий на ледяных ветрах у Стальгорна, воплощает упреждающую оборону ордена от вторжений некромантов. Когда Плеть пробуждается в горных проходах Дун Морога, Невилл направляет новобранцев и способных искателей приключений на передовую, чтобы заснеженный порог Стальгорна оставался в безопасности."}},faq={{q="Кто такой лейтенант Невилл?",a="Лейтенант Невилл — офицер Серебряного Рассвета, расквартированный близ Стальгорна в Дун Мороге. Его задача — собирать местных защитников и выявлять признаки присутствия Плети, подступающей к владениям дворфов.",al={"nevell role","who is nevell","lieutenant nevell","роль невилла","кто такой невилл","лейтенант невилл"}},{q="Почему Серебряный Рассвет находится у Стальгорна?",a="Хотя Серебряный Рассвет базируется в основном в Лордероне, он следит за вторжениями нежити на всем континенте. Если Король-лич попытается нанести удар в глубине союзных земель вроде Дун Морога, такие офицеры, как Невилл, направляются координировать оборону городов и разведывать передвижения врага.",al={"argent dawn in dun morogh","argent dawn ironforge","серебряный рассвет в дун мороге","серебряный рассвет стальгорн"}},{q="О чем лейтенант Невилл просит искателей приключений?",a="Невилл поручает способным героям выйти за ворота Стальгорна, разведать близлежащие силы Плети и разбить их, уничтожив угрозу нежити до того, как она закрепится в горных проходах.",al={"nevell quests","investigate the scourge","задания невилла","расследование плети"}}},fp="17,292,19.476.0,25.208.0,41.278.0,50.205.0"}
P.entries["npc:lieutenant-orrin"] = {n="Лейтенант Оррин",s="Лейтенант Оррин — офицер Серебряного Рассвета, расквартированный у ворот Штормграда. Находясь на Аллее Героев, он координирует местную оборону от вторжений Плети и направляет новобранцев разведывать угрозы нежити за стенами столицы.",h="Лейтенант Оррин — офицер Серебряного Рассвета, расквартированный у ворот Штормграда.",kw={"argent dawn","lieutenant orrin","necrotic crystal","orrin","scourge","stormwind","undead","valley of heroes","серебряный рассвет","лейтенант оррин","некротический кристалл","оррин","плеть","штормград","нежить","аллея героев"},ang={["class:Paladin"]="Паладины, служащие Свету, часто находят естественное единство с усилиями Серебряного Рассвета по изгнанию некромантии, где бы она ни гнездилась.",["faction:Alliance"]="Для героев Альянса, возвращающихся в столицу, Оррин — суровое напоминание о том, что даже южные земли не полностью защищены от влияния Короля-лича."},sec={{t="Часовой у ворот",b="Хотя Серебряный Рассвет известен прежде всего удержанием передовой в разоренных северных землях, его присутствие простирается на юг для защиты важнейших крепостей вроде Штормграда. Лейтенант Оррин стоит у высоких статуй Аллеи Героев и высматривает на дороге признаки скверны. Когда за пределами столицы пробуждается магия некромантов, он должен поднять тревогу и созвать искателей приключений, пока мерзкие силы не угрозили жителям."},{t="Взгляд на нежить",b="Оррин — главный связной между независимым орденом и добровольцами в южном королевстве. Когда за городскими воротами появляются признаки Плети, он собирает годных разведчиков и посылает их добывать сведения и забирать опасные артефакты, например треснувшие некротические кристаллы, чтобы лучше понять и отразить угрозу нежити."}},faq={{q="Кто такой лейтенант Оррин?",a="Лейтенант Оррин — офицер-человек на службе Серебряного Рассвета. Он расквартирован на Аллее Героев у входа в Штормград и отвечает за координацию обороны и набор разведчиков, когда Плеть угрожает окрестным землям.",al={"who is orrin","lieutenant orrin lore","who is the argent dawn officer","кто такой оррин","предания о лейтенанте оррине","кто офицер серебряного рассвета"}},{q="Почему Серебряный Рассвет находится в Штормграде?",a="Хотя Серебряный Рассвет в основном воюет с Плетью в Чумных землях, у него есть форпосты и посланники в крупных центрах Альянса и Орды. Расквартированные у ворот столицы офицеры вроде Оррина следят за вторжениями некромантов и вербуют способных бойцов, чтобы остановить распространение нежити.",al={"why is argent dawn in stormwind","argent dawn stormwind","what is argent dawn doing here","почему серебряный рассвет в штормграде","серебряный рассвет штормград","что здесь делает серебряный рассвет"}},{q="О чем лейтенант Оррин просит искателей приключений?",a="Оррин направляет новобранцев разведывать окрестности Штормграда, выяснять признаки активности Плети и добывать артефакты вроде треснувших некротических кристаллов, чтобы изучить нечестивую магию, стоящую за вторжениями.",al={"orrin quests","investigate the scourge of stormwind","what does orrin want","задания оррина","расследование плети штормграда","что хочет оррин"}}},fp="16,276,23.446.0,20.352.0,24.244.0,41.313.0,49.210.0"}
P.entries["npc:loganaar"] = {n="Логанаар",s="Логанаар — ночной эльф, наставник друидов, живущий в убежище Ночная Гавань на Лунной поляне. Он посвятил себя наставлению посвященных как из Альянса, так и из Орды и обучает молодых друидов, пока они настраиваются на дикую природу и готовятся к зову Изумрудного Сна.",h="Логанаар — ночной эльф, наставник друидов, живущий в убежище Ночная Гавань на Лунной поляне.",kw={"cenarion circle","druid trainer","emerald dream","loganaar","moonglade","nighthaven","круг кенария","учитель друидов","изумрудный сон","логанаар","лунная поляна","ночная гавань"},ang={["class:Druid"]="Для друидов и Дарнасса, и Громового Утеса Логанаар — один из первых наставников, которых они встречают, переместившись на Лунную поляну; он дает продвинутое обучение и духовные советы.",["race:NightElf"]="Логанаар отражает древние традиции кальдораев-друидов, которые тысячелетиями общались с природой и входили в Изумрудный Сон под предводительством Малфуриона Ярость Бури."},sec={{t="Хранитель священного искусства",b="Среди безмятежных ветвей Ночной Гавани Логанаар служит главным наставником новообращенных друидов, прибывающих на Лунную поляну. Откуда бы ни пришел посвященный — из Дарнасса или из Громового Утеса, — Логанаар учит равновесию, обороту и почитанию природы. Он напоминает ученикам, что даже среди холодного камня и чужих земель истинный покой нужно искать в себе. Он также встречает тех, кто углубляется в дела Круга Кенария, и направляет многообещающих учеников к странникам вроде Землепроходца Торвы в Кратере Ун'Горо или к более глубоким древним лесным обрядам."},{t="Зов Сна",b="Помимо основ заклинаний, Логанаар готовит учеников к высшему уделу, который разделяют исконные защитники Калимдора: глубокому сну в Изумрудном Сне. Он наставляет посвященных о священной связи между изначальным миром духов Азерота и миром яви, напоминая, что истинное мастерство однажды потребует многовекового сна, чтобы ходить среди чистейших, незапятнанных форм природы под руководством полубогов."}},faq={{q="Кто такой Логанаар?",a="Логанаар — ночной эльф, учитель друидов в Ночной Гавани, главном поселении Лунной поляны. Он принимает друидов любого происхождения для обучения их искусству и знакомит их с глубинными традициями Круга Кенария.",al={"loganaar npc","who is loganaar","loganaar lore","логанаар","кто такой логанаар","предания о логанааре"}},{q="Обучает ли Логанаар друидов Орды?",a="Да. Лунная поляна — священная нейтральная земля под надзором Круга Кенария. Как член Круга, Логанаар откладывает в сторону конфликт Альянса и Орды и обучает и таурен, и ночных эльфов.",al={"can tauren train at loganaar","loganaar horde","druid trainer moonglade horde","могут ли таурены учиться у логанаара","логанаар орда","учитель друидов лунная поляна орда"}},{q="Чему Логанаар учит об Изумрудном Сне?",a="Логанаар учит, что каждый истинный друид однажды почувствует притяжение Изумрудного Сна. Он объясняет, что ходить среди его нетронутых форм во время долгого глубокого сна — это и есть высшее обучение друида.",al={"loganaar dream","emerald dream quote","логанаар сон","изумрудный сон цитата"}},{q="Куда Логанаар посылает опытных друидов?",a="По мере роста опыта друидов Логанаар направляет их наружу — наблюдать и исцелять изначальные экосистемы Азерота. Среди прочего он посылает опытных учеников помогать натуралистам вроде Землепроходца Торвы в диких землях Кратера Ун'Горо.",al={"loganaar quests","torwa pathfinder quest loganaar","задания логанаара","землепроходец торва логанаар"}}},fp="8,261,24.626.0,21.439.0,16.225.0,33.211.0,49.225.0,41.245.0"}
P.entries["npc:lomac-gearstrip"] = {n="Ломак Демонтирс",s="Ломак Демонтирс — честолюбивый гном-изобретатель из Города механиков в Стальгорне. Он известен как создатель разрушительной взрывчатки NG-5 и поддерживает связь с другими гномами-исследователями, работающими по всему Калимдору.",h="Ломак Демонтирс — честолюбивый гном-изобретатель из Города механиков в Стальгорне.",kw={"an old colleague","gnome engineer","ineptitude + chemicals = fun","ironforge","lomac gearstrip","ng-5 explosive","stonetalon","tinker town","старый коллега","гном-инженер","некомпетентность плюс химия","стальгорн","ломак демонтирс","взрывчатка ng-5","когтистые горы","город механиков"},ang={["faction:Alliance"]="Агенты Альянса, перемещающиеся между Стальгорном и экспедиционными аванпостами в Калимдоре, часто обращаются от имени Ломака с секретными боеприпасами и нестабильными составами.",["profession:Engineering"]="Взрывчатка NG-5 Ломака — передний край гномьей пиротехники и источник вдохновения для механиков, интересующихся мощными взрывными составами.",["race:Gnome"]="Ломак воплощает стойкую увлеченность гномов Города механиков: даже в изгнании из Гномрегана он продолжает рискованные технические исследования."},sec={{t="Искра в Городе механиков",b="Среди лязга шестерен и шипения труб Города механиков в Стальгорне Ломак Демонтирс совершенствует тонкости гномьего вооружения. Как и многие изгнанные гномы, бежавшие от трагедии в Гномрегане, Ломак перенес свои механические разработки прямо в столицу дворфов. Его мастерская занимается нестабильными химическими смесями и особыми боеприпасами для штурма хорошо укрепленных вражеских твердынь."},{t="Взрывчатка NG-5",b="Главный вклад Ломака в современную боевую инженерию — взрывчатка NG-5. Это соединение создано для максимальной разрушительной силы и требует точного обращения и редких химических реагентов. Чтобы совершенствовать и применять такие опасные изобретения в полевых условиях, Ломак поддерживает связь со старыми коллегами в дальних краях, обмениваясь через Великое море техническими заказами и опасными поставками."}},faq={{q="Где найти Ломака Демонтирса?",a="Ломак Демонтирс живет в Городе механиков — гномьем квартале в восточной части горного города Стальгорна.",al={"lomac gearstrip location","where is lomac","find lomac gearstrip","ломак демонтирс местонахождение","где ломак","найти ломака демонтирса"}},{q="Чем прославился Ломак Демонтирс как изобретатель?",a="Ломак более всего известен как создатель взрывчатки NG-5 — мощной формулы боеприпасов, дающей разрушительную огневую мощь для гномьих предприятий.",al={"what did lomac make","lomac invention","ng-5 explosive creator","что создал ломак","изобретение ломака","создатель взрывчатки ng-5"}},{q="Почему Ломак связан с контактами в Калимдоре?",a="Ломак поддерживает связь с бывшими коллегами-исследователями, работающими в пограничных областях вроде Когтистых гор: он координирует поставки опасных химических ингредиентов и испытывает свою мощную взрывчатку в действующих операциях.",al={"lomac stonetalon","why stonetalon quest","lomac colleagues","ломак когтистые горы","почему задание в когтистых горах","коллеги ломака"}},{q="Какие поручения Ломак дает искателям приключений?",a="Ломак поручает надежным курьерам Альянса доставлять заказы на закупку и нестабильные химические реагенты между Стальгорном и исследователями за границей, часто в связи с опытами с его взрывчаткой NG-5.",al={"lomac quests","ineptitude chemicals fun","an old colleague quest","задания ломака","некомпетентность плюс химия","задание старый коллега"}},{q="Что такое квитанция о заказе на закупку, связанная с Ломаком?",a="Ломак составил квитанцию о заказе на закупку — накладную, с помощью которой упорядочивают и документируют поставки специального оборудования и опасных нестабильных реагентов между механиками.",al={"purchase order receipt","lomac receipt","квитанция о заказе на закупку","квитанция ломака"}},{q="Связан ли Ломак с беженцами из Гномрегана?",a="Да. Как и остальные жители Города механиков, Ломак входит в общину изгнанных из Гномрегана гномов, живущих под покровительством дворфов Стальгорна и продолжающих свою инженерную работу.",al={"is lomac from gnomeregan","lomac faction","ломак из гномрегана","фракция ломака"}}},fp="15,212,22.406.0,18.398.0,33.125.0,45.148.0,46.240.0,51.206.0,49.169.0,47.196.0"}
P.entries["npc:longbraid-the-grim"] = {n="Длиннокос Мрачный",s="Длиннокос Мрачный — дворфийский командир из Стальгорна, расположившийся у павшей крепости Дун Модр на севере Болотины. Скорбя о потере брата и захвате Моста Тандола, он руководит уцелевшими силами дворфов против вторгшегося клана Черного Железа.",h="Длиннокос Мрачный — дворфийский командир из Стальгорна, расположившийся у павшей крепости Дун Модр на севере...",kw={"dark iron","dun modr","longbraid","thandol span","the grim","wetlands","whelgar","черное железо","дун модр","длиннокос","мост тандола","мрачный","болотина","вельгар"},ang={["faction:Alliance"]="Длиннокос удерживает тонкую линию обороны у северных врат Каз Модана и стремится вновь открыть важнейший сухопутный путь через Мост Тандола в земли Арати.",["race:Dwarf"]="Для дворфов Стальгорна Длиннокос воплощает яростную, непрекращающуюся кровную вражду с коварными сородичами из Черного Железа, ударившими прямо по северным вратам."},sec={{t="Горькое дозорство",b="Находясь в виду моста к Нагорью Арати, Длиннокос Мрачный сплачивает остатки дворфийского гарнизона после того, как клан Черного Железа захватил Дун Модр. Внезапное нападение сокрушило местных защитников, а во время осады Моста Тандола погиб родной брат Длиннокоса. Охваченный горем и ненавистью, Длиннокос отказывается покидать северный рубеж и направляет путников и уцелевших горцев в точных ударах, сдерживающих наступление Черного Железа."},{t="Удержать рубеж",b="Помимо защиты подступов к мосту, Длиннокос руководит более широкими действиями дворфов по всей Болотине. Он отправил толковых солдат сопровождать Геолога Вельгара в болота и неустанно трудится над возвращением утраченных укреплений Дун Модра, поклявшись отомстить диверсантам Черного Железа."}},faq={{q="Кто такой Длиннокос Мрачный?",a="Длиннокос Мрачный — дворфийский командир, расположившийся у Дун Модра на севере Болотины. Он возглавляет местное сопротивление Альянса против дворфов Черного Железа, захвативших эти земли.",al={"who is longbraid","longbraid identity","dun modr dwarf","кто такой длиннокос","личность длиннокоса","дворф дун модра"}},{q="Почему Длиннокоса называют Мрачным?",a="Мрачный нрав он обрел после гибели брата во время разрушительного нападения Черного Железа на Мост Тандола. С тех пор им владеет желание отомстить за павшего родича.",al={"why is he grim","longbraid brother","longbraid backstory","почему он мрачный","брат длиннокоса","история длиннокоса"}},{q="Что случилось с Дун Модром?",a="Дун Модр был захвачен и занят кланом Черного Железа, напавшим из засады на дворфийский гарнизон и попытавшимся разрушить Мост Тандола, чтобы отрезать главный путь между Болотиной и Нагорьем Арати.",al={"fall of dun modr","what happened to the bridge","thandol span attack","падение дун модра","что случилось с мостом","нападение на мост тандола"}},{q="Как Длиннокос связан с Геологом Вельгаром?",a="Длиннокос выделил солдат из своих сил, чтобы они сопровождали и охраняли Геолога Вельгара, пока дворфийская экспедиция углублялась в опасную Болотину.",al={"whelgar longbraid","merrin letter","вельгар длиннокос","письмо меррина"}}},fp="18,280,14.492.0,16.312.0,26.184.0,35.189.0,26.205.0,53.161.0"}
P.entries["npc:lor-themar-theron"] = {n="Лор'темар Терон",s="Лор'темар Терон — лорд-регент Кель'Таласа, которому поручено управлять разрушенным королевством кровавых эльфов, пока принц Кель'тас отсутствует. Опытный лорд-следопыт и бывший заместитель генерала-следопыта Сильваны Ветрокрылой, он несет тяжелое бремя: сохранить жизнь своему истерзанному народу после вторжения Плети.",h="Лор'темар Терон — лорд-регент Кель'Таласа, которому поручено управлять разрушенным королевством кровавых...",kw={"blood elf","farstriders","kael'thas","lor'themar","quel'thalas","regent lord","silvermoon","sin'dorei","theron","эльф крови","странники","кель'тас","лор'темар","кель'талас","лорд-регент","луносвет","син'дорей","терон"},ang={["class:Hunter"]="Для опытных стрелков и разведчиков Лор'темар — вершина традиции Странников: мастер меткой стрельбы, из лесных дозоров перешедший к бремени государственных дел.",["race:Undead"]="Отрекшиеся путники часто вспоминают, что бывшие соратники Сильваны Ветрокрылой все еще живы на разоренном севере, а Лор'темар служит хрупким мостом между Луносветом и владениями Темной Госпожи."},sec={{t="От лорда-следопыта до регента",b="До Третьей войны Лор'темар Терон веками служил прославленным командиром Странников, защищая северные границы эльфов от троллей Амани и дослужившись до заместителя генерала-следопыта Сильваны Ветрокрылой. Когда Артас и Плеть опустошили Кель'Талас и уничтожили Солнечный Колодец, Лор'темар был среди уцелевших ветеранов, сплотивших живых. Когда принц Кель'Тас Солнечный Скиталец отправился на юг, а затем в неизвестность в поисках лекарства от страшной зависимости их народа от магии, он назначил Лор'темара лордом-регентом, чтобы тот охранял королевство в его отсутствие."},{t="Бремя Солнечных Скитальцев",b="Лор'темар никогда не стремился к короне или к политическому лабиринту эльфийской знати. По натуре он остается разведчиком и солдатом, предпочитающим лук и простые приказы придворной дипломатии. Но пока династия Солнечных Скитальцев вдали, а Кель'Талас окружен нежитью, бродящей по Призрачным землям, Терон руководит изнурительной повседневной борьбой эльфов крови за выживание. Его обязанности нередко влекут дипломатические осложнения с бывшей защитницей королевства, ныне Королевой банши, правящей Подгородом, чью помощь отчаявшимся выжившим Кель'Таласа трудно отвергнуть."}},faq={{q="Кто такой Лор'темар Терон?",a="Он лорд-регент Кель'Таласа и предводитель эльфов крови, оставшихся в Азероте. Прежде заместитель командира Странников при Сильване Ветрокрылой, он получил власть над родиной от принца Кель'Таса Солнечного Скитальца.",al={"lorthemar lore","who is regent lord","who leads blood elves","предания лор'темара","кто такой лорд-регент","кто возглавляет эльфов крови"}},{q="Каковы его отношения с Сильваной Ветрокрылой?",a="Лор'темар был доверенным заместителем Сильваны, когда она при жизни была генералом-следопытом Луносвета. Хотя они долго были соратниками среди Странников, ее смерть, превращение в банши и власть над Отрекшимися сделали их нынешние отношения куда более сложными и настороженными.",al={"lorthemar and sylvanas","did lorthemar know sylvanas","лор'темар и сильвана","знал ли лор'темар сильвану"}},{q="Лор'темар — король эльфов крови?",a="Нет. Лор'темар носит титул лорда-регента и правит от имени принца Кель'таса Солнечного Скитальца, который остается законным монархом и лидером син'дорей, пока отсутствует в поисках средства от их магической зависимости.",al={"is lorthemar king","is he prince kaelthas","who rules quel'thalas","лор'темар король","он принц кель'тас","кто правит кель'таласом"}},{q="Каков его боевой опыт?",a="Он опытный лорд-следопыт, сражавшийся во Второй войне против Старой Орды и троллей Амани и служивший стражем Солнечного Колодца. Веками он водил отряды Странников, пока политика не заставила его править.",al={"was lorthemar a farstrider","is lorthemar a ranger","был ли лор'темар странником","лор'темар следопыт"}}},fp="17,338,26.632.0,29.556.0,25.239.0,50.301.0,42.218.0,38.226.0"}
P.entries["npc:loramus-thalipedes"] = {n="Лорамус Многоног",s="Лорамус Многоног — отшельник, ночной эльф и охотник на демонов, укрывшийся на далеком острове у побережья Азшары. В окружении верных гончих Скверны он посвятил свою жизнь уничтожению Разелиха Осквернителя и направляет опытных героев через ритуалы, чтобы сразить повелителя ужаса.",h="Лорамус Многоног — отшельник, ночной эльф и охотник на демонов, укрывшийся на далеком острове у побережья...",kw={"azshara","demon hunter","felbane","felhound","hetaera's clutch","loramus","razelikh","thalipedes","азшара","охотник на демонов","погибель скверны","гончая скверны","гнездо хетайры","лорамус","разелих","многоног"},ang={["class:Warlock"]="Чернокнижники увидят в его подконтрольных гончих Скверны свидетельство исключительного подчинения демонов, хотя Лорамус связывает демонов исключительно ради истребления им подобных.",["race:NightElf"]="Ночные эльфы традиционно относятся к охотникам на демонов с глубоким ужасом и недоверием, видя в их ритуальном самоувечье и демонических договорах непростительный путь, повторяющий предательство Иллидари."},sec={{t="Слепой охотник островов",b="На одиноком, истерзанном штормами острове к юго-востоку от Гнезда Хетайры Лорамус Многоног живет особняком от своего народа. Он охотник на демонов — изгнанник, прошедший мучительный ритуал ослепления под руководством наставника, чтобы обрести духовное зрение. В окружении трех огромных гончих Скверны по имени Райтаф, Шахиар и Заман Лорамус наблюдает за незримыми течениями демонической порчи по всему Азероту и несет дозор над разрушенными руинами Азшары."},{t="Месть через континенты",b="Одержимость Лорамуса направлена через море, на Выжженные земли, и целиком сосредоточена на повелителе ужаса Разелихе Осквернителе. Зная, что обычная сталь не способна навсегда покончить с хитрым демоном, Лорамус проводит путников через древние ритуалы: им нужно собрать зачарованный азсарит и перековать легендарное оружие Погибель Скверны. Этими тайными приготовлениями он стремится сорвать защиту Разелиха, связать истинное имя демона и раз и навсегда довести месть до конца."}},faq={{q="Кто такой Лорамус Многоног?",a="Лорамус Многоног — ночной эльф, охотник на демонов, живущий на уединенном острове у побережья Азшары. Он посвятил себя борьбе с могущественными демонами, прежде всего с повелителем ужаса Разелихом Осквернителем.",al={"loramus identity","who is the demon hunter in azshara","who is loramus","личность лорамуса","кто охотник на демонов в азшаре","кто такой лорамус"}},{q="Почему у Лорамуса завязаны глаза?",a="Как и другие охотники на демонов, Лорамус лишил себя глаз под руководством своего наставника. Взамен обычного смертного зрения этот ритуал даровал ему духовное зрение, необходимое для обнаружения демонической энергии.",al={"why does loramus have no eyes","loramus blind","demon hunter blindfold","почему у лорамуса нет глаз","лорамус слепой","повязка охотника на демонов"}},{q="Почему его охраняют гончие Скверны?",a="Лорамус подчинил и связал трех могучих гончих Скверны — Райтафа, Шахиара и Замана, — обратив их хищные инстинкты на службу своей охоте на демонов, а не Пылающему Легиону.",al={"loramus felhounds","why does loramus have demons","raytaf shahiar zaman","гончие скверны лорамуса","почему у лорамуса демоны","райтаф шахиар заман"}},{q="Как он связан с Выжженными землями?",a="Он направляет поход по уничтожению повелителя ужаса Разелиха Осквернителя, правящего возвышенностями Выжженных земель. Лорамус дает необходимые знания, обряды и оружие, чтобы пробить защиту Разелиха.",al={"loramus blasted lands","razelikh quest","why does he care about the blasted lands","лорамус выжженные земли","задание разелих","почему его волнуют выжженные земли"}}},fp="18,274,29.484.0,28.473.1,26.193.0,27.208.0,37.189.0,44.216.0"}
P.entries["npc:lord-arkkoroc"] = {n="Лорд Арккорос",s="Лорд Арккорос — древний исполинский морской великан, обитающий в разрушенном Храме Арккоран на изрезанном побережье Азшары. Охотник на демонов Лорамус Многоног называет его младшим божеством: он властвует над окрестными водами и повелевает младшими морскими великанами, которые служат ему как сыновья.",h="Лорд Арккорос — древний исполинский морской великан, обитающий в разрушенном Храме Арккоран на изрезанном...",kw={"arkkoran","arkkoroc","azshara","hetaera","loramus","lord arkkoroc","sea giant","арккоран","арккорос","азшара","гетера","лорамус","лорд арккорос","морской великан"},ang={["race:NightElf"]="Руины Храма Арккоран стоят на землях бывших высокорожденных, где древнее морское существо теперь безраздельно властвует над павшим величием старого Калимдора."},sec={{t="Властелин затонувшего берега",b="Лорд Арккорос возлежит среди изъеденных солью руин Храма Арккоран и является куда большим, чем обычный морской великан. Отшельники вроде Лорамуса Многонога считают это колоссальное существо младшим божеством, чья воля определяет жизнь окрестных вод. Его сыновья обходят скалы и мелководья вокруг святилища, поддерживая его тихую власть над бурными берегами Азшары."},{t="Месть морским глубинам",b="Несмотря на огромную божественную силу, Арккорос несет потери среди приливов. Свирепая многоголовая гидра по имени Гетера выследила и убила многих его сыновей среди утесов. Не в силах или не желая сам расправиться со зверем, Арккорос обменивает ценные знания и тайную помощь на головы убийцы его потомства с любым странствующим искателем приключений, достаточно сильным, чтобы их принести."}},faq={{q="Кто такой лорд Арккорос?",a="Лорд Арккорос — громадный морской великан, живущий в Храме Арккоран в Азшаре. Его почитают как младшее божество морей, и он правит выводком морских великанов, которых считает своими сыновьями.",al={"who is arkkoroc","arkkoroc lore","temple sea giant","кто такой арккорос","арккорос предания","морской великан храм"}},{q="Где найти лорда Арккороса?",a="Он восседает среди руин Храма Арккоран на восточном побережье и скалистых рифах Азшары.",al={"arkkoroc location","where is arkkoroc","find arkkoroc","местонахождение арккороса","где арккорос","найти арккороса"}},{q="Почему Лорамус Многоног посылает искателей приключений к Арккоросу?",a="Лорамус Многоног направляет путников к Арккоросу за тайными знаниями о могущественном демоне. Как младшее морское божество, Арккорос хранит древние знания, но требует, чтобы искатели приключений убили гидру Гетеру, прежде чем он раскроет свои тайны.",al={"loramus arkkoroc quest","name of the beast","лорамус арккорос задание","имя зверя"}},{q="Почему Арккорос гневается на гидру Гетеру?",a="Свирепая морская тварь Гетера убила нескольких сыновей Арккороса, патрулировавших побережье. Желая отомстить за павших родичей, морской великан требует ее головы.",al={"why kill hetaera","arkkoroc hydra grudge","зачем убивать гетеру","арккорос гидра месть"}}},fp="13,294,24.378.0,26.398.1,21.195.0,31.129.0,57.247.0,45.170.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="Лорд Борлс К. Вишлок",s="Лорд Борлс К. Вишлок — дворянин, живущий в Палате просителей Крепости Штормграда. Известный среди трактирщиков неоплаченными счетами и любовью к крепким напиткам, он наткнулся на более мрачные дела, чем простое пьянство, в городских низах.",h="Лорд Борлс К.",kw={"baurles","house of nobles","petitioner's chamber","slaughtered lamb","stormwind keep","wishock","zardeth","борлс","дом знати","палата просителей","забитый ягненок","крепость штормграда","вишлок","зардет"},ang={["class:Warlock"]="Назойливое расследование Вишлока в «Забитом ягненке» представляет непосредственную угрозу для теневого ковена Штормграда, поэтому его тихое устранение — первоочередная задача для практикующих чернокнижников.",["race:Human"]="Его присутствие в Палате просителей отражает изнеженную, своекорыстную репутацию Дома знати в начале правления юного короля Андуина."},sec={{t="Опасное любопытство дворянина",b="Лорд Борлс К. Вишлок, держа двор среди просителей и сановников в Крепости Штормграда, — член влиятельного Дома знати. Несмотря на высокое положение, Вишлок завел привычку захаживать в злачные таверны Квартала магов, особенно в «Забитый ягненок», оставляя после себя крупные неоплаченные счета. Однако за выпивкой он прознал о ковене чернокнижников, занимающихся темными искусствами в подвалах под половицами. Решив закрыть таверну, Вишлок начал убеждать других дворян начать официальное расследование, не подозревая, что раскрытие демонических культов в Штормграде редко проходит безнаказанно."},{t="Отравленная чаша",b="Хлопоты Вишлока поставили его под прицел скрытых чернокнижников города. Не желая рисковать королевским вниманием или расследованием в отношении их подземного убежища, чернокнижник Зардет Черный Коготь организовал тихое устранение дворянина. Зная о страсти Вишлока к дорогим выдержанным напиткам, ковен приготовил смертельное зелье под видом отличного эля и нанял искателя приключений, чтобы тот доставил роковой напиток прямо под носом у стражи Крепости."}},faq={{q="Кто такой лорд Борлс К. Вишлок?",a="Лорд Борлс К. Вишлок — аристократ, связанный с Домом знати. Он проводит дни в Палате просителей в Крепости Штормграда, а в Квартале магов печально известен крупными неоплаченными счетами за выпивку.",al={"baurles wishock","who is wishock","noble petitioner","борлс вишлок","кто такой вишлок","дворянин проситель"}},{q="Где найти лорда Вишлока?",a="Он стоит в Палате просителей в восточной части Крепости Штормграда в окружении других придворных, дипломатов и просителей, ожидающих королевского внимания.",al={"wishock location","where is wishock","find lord wishock","местонахождение вишлока","где вишлок","найти лорда вишлока"}},{q="Почему чернокнижники под «Забитым ягненком» хотят его смерти?",a="Во время поздних попоек в «Забитом ягненке» Вишлок узнал, что под таверной действует ковен чернокнижников. Он начал убеждать Дом знати провести официальное расследование и закрыть заведение, грозя раскрыть их тайные дела.",al={"why kill wishock","zardeth wishock","why poison wishock","зачем убивать вишлока","зардет вишлок","зачем травить вишлока"}},{q="Как его убивают?",a="Зардет Черный Коготь варит смертельный яд и выдает его за изысканный напиток. Зная слабость Вишлока к хорошему спиртному и бесплатной выпивке, посланник доставляет отравленный бочонок прямо ему в Крепость Штормграда.",al={"how does wishock die","wishock poison","a noble brew","как умирает вишлок","яд вишлока","благородное пойло"}}},fp="23,241,32.635.0,14.479.1,31.233.0,32.179.0,63.276.1,23.222.1"}
P.entries["npc:lord-cobrahn"] = {n="Лорд Кобран",s="Лорд Кобран, прежде ночной эльф-друид Джарлакса, — один из оскверненных Друидов Клыка, обитающих в глубинах Пещер Стенаний. Некогда прославленный в Круге Кенария мастерством перевоплощений, он поддался кошмару, поразившему источники пещер. Назвав себя в честь новой смертоносной ипостаси, Кобран теперь повелевает выводками загадочных змей и защищает извилистый лабиринт.",h="Лорд Кобран, прежде ночной эльф-друид Джарлакса, — один из оскверненных Друидов Клыка, обитающих в глубинах...",kw={"cobrahn","deviate python","druids of the fang","fanglord","gem of cobrahn","jarlaxla","lord cobrahn","wailing caverns","кобран","загадочный питон","друиды клыка","повелитель клыка","самоцвет кобрана","джарлакса","лорд кобран","пещеры стенаний"},ang={["class:Druid"]="Кобран служит мрачным предостережением о том, как друидическое перевоплощение может быть извращено, если оно связано с кошмаром, а не с природным равновесием.",["faction:Horde"]="Искатели приключений Орды ищут Кобрана, чтобы положить конец мерзкой порче, просачивающейся в Степи, и защитить хрупкую экосистему равнин Калимдора.",["race:NightElf"]="Для ночных эльфов падение Кобрана — горькая трагедия: умелый брат по Кругу Кенария отрекся от своего наследия и повел чудовищ в подземных глубинах."},sec={{t="Оскверненный мастер обликов",b="До того как принять имя лорда Кобрана, Джарлакса был уважаемым членом Круга Кенария, прославленным среди собратьев-друидов исключительным умением принимать облики животных. Когда Наралекс отправился в Пещеры Стенаний под Степями, надеясь использовать их подземные источники и вернуть жизнь иссушенным землям, Джарлакса сопровождал его. Но когда единение Наралекса с Изумрудным Сном обратилось извивающимся кошмаром, разум Джарлаксы раскололся вместе с разумом его братьев."},{t="Объятия змея",b="Вместо традиционных тотемных зверей Кенария кошмар исказил искусство перевоплощения Джарлаксы в нечто хищное и змеиное. Приняв имя лорда Кобрана, он обрел смертоносный змеиный облик, который применяет в бою. В окружении ядовитых загадочных питонов и с жестокой когтистой правой рукой он правит своей частью гротов, беспощадно истребляя всех, кто пытается разорвать хватку кошмара над пещерами."}},faq={{q="Кем был лорд Кобран до того, как стал злодеем?",a="Лорда Кобрана первоначально звали Джарлакса. Он был видным ночным эльфом-друидом Круга Кенария, которого высоко ценили за редкий талант и глубокое родство с обликами животных.",al={"cobrahn real name","who is cobrahn","jarlaxla","настоящее имя кобрана","кто такой кобран","джарлакса"}},{q="Почему его зовут лордом Кобраном?",a="Став жертвой кошмара в Пещерах Стенаний, Джарлакса довел до совершенства смертоносный змеиный облик. Он отбросил прежнее имя и принял титул лорда Кобрана, отражая свою опасную новую силу и власть над змеями.",al={"why cobrahn","lord cobrahn name meaning","почему кобран","значение имени лорд кобран"}},{q="Где найти лорда Кобрана?",a="Лорд Кобран обитает в глубине Пещер Стенаний — извилистой подземной сети в центре Степей, в окружении загадочных питонов и других тварей, оскверненных кошмаром.",al={"cobrahn location","where is lord cobrahn","cobrahn room","местонахождение кобрана","где лорд кобран","комната кобрана"}},{q="Почему искателям приключений нужно победить его?",a="Он — один из главных Повелителей Клыка, возглавляющих Друидов Клыка. У него хранится Самоцвет Кобрана, который ищет друид Нара Буйногривая из Громового Утеса, чтобы сломить власть предводителей Клыка над Степями.",al={"why kill cobrahn","leaders of the fang cobrahn","зачем убивать кобрана","предводители клыка кобран"}},{q="Какими особыми внешними чертами он обладает?",a="В отличие от обычных ночных эльфов, Кобран заметно крупнее, носит острый коготь на правой руке и в бою может полностью превращаться в огромную ядовитую змею.",al={"what does cobrahn look like","cobrahn appearance","как выглядит кобран","внешность кобрана"}},{q="Как он связан с другими Друидами Клыка?",a="Кобран — один из четырех главных Повелителей Клыка наряду с Повелительницей Анакондрой и их сородичами. Это бывшие друиды Круга Кенария, вошедшие в пещеры с Наралексом и вместе павшие жертвой извращающей порчи кошмара.",al={"druids of the fang leaders","cobrahn and anacondra","предводители друидов клыка","кобран и анакондра"}}},fp="12,399,27.496.0,21.465.0,43.193.0,30.242.0,32.184.0,38.209.0,44.186.0,55.218.0"}
P.entries["npc:lord-ello-ebonlocke"] = {n="Лорд Элло Чернодрев",s="Лорд Элло Чернодрев — мэр Темнолесья и глава его совета, пребывающий в Ратуше Темнолесья. Окруженный тьмой и подползающими ужасами, он ежедневно борется за порядок и защиту осажденных горожан, почти не получая помощи от Штормграда.",h="Лорд Элло Чернодрев — мэр Темнолесья и глава его совета, пребывающий в Ратуше Темнолесья.",kw={"abercrombie","althea","council","darkshire","duskwood","ebonlocke","ello","lakeshire","mayor","аберкромби","алтея","совет","темнолесье","сумеречный лес","чернодрев","элло","приозерье","мэр"},ang={["faction:Alliance"]="Лорд Чернодрев олицетворяет забытые окраины Альянса, где одинокие мэры вынуждены вести свой народ сквозь кошмарные условия без помощи державы.",["race:Human"]="Для людей, путешествующих из Штормграда, разговор с лордом Чернодревом — отрезвляющее напоминание о том, насколько южные провинции погрузились в разорение и заброшенность."},sec={{t="Мэр в осаде",b="Сидя в сумраке Ратуши Темнолесья, лорд Элло Чернодрев несет тяжкое бремя управления поселением на грани гибели. Когда-то часть процветающего сельского уголка, известного как Большая деревня, Темнолесье теперь окутано вечной тенью и осаждено голодными упырями, скелетами-чудовищами и дикими зверями. Элло возглавляет Совет Темнолесья, пытаясь вопреки невозможным шансам сохранить остатки цивилизации, пока Штормград закрывает глаза на их бедственное положение."},{t="Разделенный рубеж",b="Поскольку гарнизон Штормграда отказывается выделять солдат для пограничья, Темнолесье почти целиком полагается на местные добровольческие ополчения вроде Ночного Дозора, которым командует его родственница Алтея Чернодрев. Когда соседние главы, например мировой судья Соломон из Приозерья, молят о подкреплении против орков Черной Горы, лорду Чернодреву приходится делать мучительный выбор. Как он серьезно объясняет посланникам из Красногорья, Темнолесье не может отдать ни одного клинка: отправив стражу за пределы леса, они оставили бы собственные дома на мгновенное разорение окрестным злом."},{t="Слепота к замыслам Отшельника",b="Помимо патрулирования дорог, лорд Чернодрев часто полагается на странствующих искателей приключений в решении необычных дел в лесу. Искренне желая помочь всем жителям Сумеречного леса, он налаживает связь с уединенными личностями вроде отшельника Аберкромби. К сожалению, неспособность Чернодрева разобраться в загадочных записях отшельника скрывала от него жуткий сшитый кошмар, зреющий сразу за границами города, пока не стало почти слишком поздно."}},faq={{q="Кто такой лорд Элло Чернодрев?",a="Лорд Элло Чернодрев — мэр Темнолесья и глава Совета Темнолесья. Из своего кресла в ратуше он руководит обороной, гражданскими делами и выживанием уцелевшего человеческого населения Сумеречного леса.",al={"who is ello","mayor of darkshire","ello ebonlocke lore","кто такой элло","мэр темнолесья","элло чернодрев предания"}},{q="Кем он приходится командиру Алтее Чернодрев?",a="Командир Алтея Чернодрев, стойкая предводительница Ночного Дозора, — близкая родственница лорда Элло. Он управляет гражданскими и дипломатическими делами Темнолесья, а она руководит ополчением, которое охраняет поселение.",al={"althea ebonlocke relation","is althea ello's daughter","родство алтеи чернодрев","алтея дочь элло"}},{q="Почему лорд Чернодрев отказывается посылать войска в Приозерье?",a="Когда мировой судья Соломон просит помощи против орков Черной Горы в Красногорье, лорд Чернодрев вынужден отказать. Темнолесье так сильно теснят нежить и чудовища, что, лишив город стражи, его бы полностью захватили еще до того, как ополчение дошло бы до границы леса.",al={"why no help for redridge","messenger to darkshire","magistrate solomon ello ebonlocke","почему нет помощи красногорью","посланник в темнолесье","мировой судья соломон элло чернодрев"}},{q="Где найти лорда Элло Чернодрева?",a="Он находится в Ратуше Темнолесья, которая стоит в центре Темнолесья на востоке Сумеречного леса.",al={"ello ebonlocke location","where is mayor ebonlocke","местонахождение элло чернодрева","где мэр чернодрев"}},{q="Почему Штормград не присылает войска на помощь лорду Чернодреву?",a="Штормград втянут во внутреннюю политическую борьбу после исчезновения короля Вариана Ринна. Из-за нехватки ресурсов королевства Дом знати в основном бросил южные земли, вынуждая местных правителей вроде лорда Чернодрева самим организовывать оборону.",al={"why won't stormwind help duskwood","stormwind neglect","почему штормград не помогает сумеречному лесу","штормград бросил"}},{q="Как лорд Чернодрев связан с Аберкромби?",a="Лорд Чернодрев помогает поддерживать связь с отшельником Аберкромби, участвуя в переводе странных записок.",al={"ello abercrombie note","translate abercrombie's note","элло аберкромби записка","перевод записки аберкромби"}}},fp="19,289,19.500.0,18.576.0,29.465.1,27.208.0,48.218.0,59.294.0,39.106.0,57.276.0,54.125.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {n="Лорд Грейсон Тенелом",s="Лорд Грейсон Тенелом — паладин-ветеран и командир Рыцарей Серебряной Длани, находящийся в Соборе Света Штормграда. Его легко узнать по огромному росту и отсутствию правого глаза. Он обучает начинающих защитников Света и руководит священными, трудными испытаниями, которые должны пройти старшие паладины, чтобы получить своих святых скакунов.",h="Лорд Грейсон Тенелом — паладин-ветеран и командир Рыцарей Серебряной Длани, находящийся в Соборе Света...",kw={"cathedral of light","charger","grayson","grimand elmore","jubeka","paladin","scholomance","shadowbreaker","silver hand","собор света","скакун","грейсон","гриманд элмор","джубека","паладин","некроситет","тенелом","серебряная длань"},ang={["class:Paladin"]="Грейсон — один из ваших высших духовных наставников в Альянсе: он направляет ваш путь в борьбе с Плетью в Лордероне и проводит строгие испытания, необходимые, чтобы призвать настоящего скакуна.",["faction:Alliance"]="Стойкий ветеран Серебряной Длани, лорд Грейсон помогает укреплять оборону Штормграда и усиливает экспедиционную помощь спорным северным королевствам."},sec={{t="Мастер Серебряной Длани",b="Лорд Грейсон Тенелом — один из главных защитников Альянса, опора присутствия ордена в Штормграде. Грейсон — воин-ветеран, потерявший правый глаз в бою, и он не просто обучает новобранцев боевому мастерству, но и проверяет их духовную стойкость. Когда многообещающие рыцари доказывают свою готовность, Грейсон отправляет их на север, на спорные передовые рубежи Западных Чумных земель, на помощь командиру Ашламу Смелонраву в Лагере Промозглого Ветра."},{t="Испытания святого скакуна",b="От паладинов, ищущих священного боевого коня, Тенелом требует глубокой жертвенности и безупречной добродетели. Его испытания включают смиренные акты милосердия, например помощь беднякам Стальгорна через верховного жреца Рохана, а также опасные походы, чтобы изгнать нечисть из Долины Ужаса и очистить древние души в Забытом Городе. Испытание завершается в темных глубинах Некроситета, где посвящаемый должен сразиться с рыцарем смерти Темным Похитителем и силой Света освободить нечестивого скакуна от рабства."}},faq={{q="Где найти лорда Грейсона Тенелома?",a="Лорд Грейсон Тенелом пребывает в Соборе Света на Соборной площади Штормграда. Он находится в главных залах и наблюдает за паладинами Серебряной Длани.",al={"where is grayson shadowbreaker","shadowbreaker location","where is lord grayson","где грейсон тенелом","где найти тенелома","где лорд грейсон"}},{q="Какова роль лорда Грейсона для паладинов?",a="Он — высокопоставленный наставник паладинов Альянса. Помимо того, что он направляет молодых рыцарей на передовую борьбы с Плетью в Лордероне, он руководит священной цепочкой заданий, необходимой, чтобы выковать святой чепрак и получить скакуна паладина.",al={"what does grayson do","grayson shadowbreaker purpose","why visit lord grayson","что делает грейсон","зачем нужен грейсон тенелом","зачем идти к лорду грейсону"}},{q="Как лорд Грейсон потерял правый глаз?",a="Грейсон потерял правый глаз в сражении за долгие годы службы Альянсу и Ордену Серебряной Длани. Шрам напоминает о десятилетиях войны.",al={"how did grayson lose his eye","why is grayson missing an eye","grayson eyepatch","как грейсон потерял глаз","почему у грейсона нет глаза","повязка грейсона"}},{q="Какая у него связь с Отрекшимися?",a="Его сестра Джубека погибла во время гибели Лордерона и была воскрешена как одна из Отрекшихся. Когда она позже разыскала его, надеясь на примирение, Грейсон отверг ее как нечестивого монстра, яростно утверждая, что его настоящая сестра умерла вместе с Лордероном.",al={"grayson sister","jubeka shadowbreaker","does grayson have undead family","сестра грейсона","джубека тенелом","есть ли у грейсона родные нежить"}},{q="Почему Грейсон отправляет паладинов к Гриманду Элмору?",a="Гриманд Элмор много лет назад выковал чепрак для скакуна самого Грейсона. Поскольку святой скакун требует безупречного мастерства, сочетающего физическую выносливость с духовной гармонией, Грейсон отправляет всех достойных посвящаемых к Гриманду, чтобы тот изготовил их Арканитовый чепрак.",al={"grayson and grimand elmore","who makes the paladin barding","arcanite barding quest","грейсон и гриманд элмор","кто делает чепрак паладина","задание арканитовый чепрак"}}},fp="26,338,25.479.0,30.494.1,44.193.0,41.263.0,40.179.0,39.260.0,49.261.0"}
P.entries["npc:lord-jorach-ravenholdt"] = {n="Лорд Джорах Черный Ворон",s="Лорд Джорах Черный Ворон — глава Черного Ворона, элитной гильдии разбойников и убийц, действующей из уединенного поместья в Альтеракских горах. Он руководит тайными операциями лиги, обучает перспективных агентов и ведет жестокую войну с местными бандитами Синдиката.",h="Лорд Джорах Черный Ворон — глава Черного Ворона, элитной гильдии разбойников и убийц, действующей из...",kw={"alterac","assassin's league","azure key","jorach","ravenholdt","rogue","syndicate","xylem","альтерак","лига убийц","лазурный ключ","джорах","черный ворон","разбойник","синдикат","ксилем"},ang={["class:Rogue"]="Лорд Черный Ворон — главный покровитель мастеров-разбойников по всему Азероту: тем, кто заслужил его доверие, он предлагает элитное обучение, яды и престижные контракты."},sec={{t="Глава Лиги убийц",b="Лорд Джорах Черный Ворон возглавляет Лигу убийц из своего скрытого поместья среди скал между Альтераком и Хилсбрадом. Дворянин с таинственным происхождением, он открывает свои залы изгоям, карманникам и убийцам независимо от их верности, если они обладают исключительным мастерством и уважают его власть. Под его началом лига — одновременно братство мастеров-воров и независимый синдикат «мокрых дел» и шпионажа. Черный Ворон питает яростную ненависть к Синдикату — шайке опозоренных альтеракских дворян, ставших изгоями, — и регулярно посылает своих подчиненных и приезжих наемников громить их лагеря и грабить их имущество."},{t="Тайны во тьме",b="Хотя лорд Черный Ворон внешне занят местными стычками, он руководит масштабными операциями по всему Азероту. Разбойники, доказавшие верность, привлекаются к сложным заданиям по всему континенту — добыть охраняемые артефакты. Среди них было возвращение загадочной Запечатанной лазурной сумки, украденной у него и переправленной фурболгам в Азшаре: для этого потребовалась тайная расшифровка верховного мага Ксилема и Лазурный ключ, добытый в Затонувшем храме. Черный Ворон также руководит созданием смертоносных новых составов и отправляет разведчиков собирать смертельный яд у древних чудовищ по всему миру."}},faq={{q="Кто такой лорд Джорах Черный Ворон?",a="Он — аристократ и глава Лиги убийц, тайного общества разбойников со штаб-квартирой в Поместье Черного Ворона в горах над Предгорьями Хилсбрада. Он обучает мастеров скрытности и координирует тайные убийства и сбор разведданных.",al={"who is jorach","ravenholdt leader","jorach lore","кто такой джорах","глава черного ворона","предания джорах"}},{q="Почему Черный Ворон ненавидит Синдикат?",a="Поместье Черного Ворона находится прямо на территории, спорной с Синдикатом — сетью бывших альтеракских дворян, ставших безжалостными изгоями. Он считает их грубый разбой заразой для нагорий и использует убийц своей гильдии, чтобы планомерно уничтожать их оплоты.",al={"why syndicate enemy","ravenholdt vs syndicate","syndicate rivalry","почему синдикат враг","черный ворон против синдиката","вражда с синдикатом"}},{q="Связан ли лорд Черный Ворон с Альянсом или Ордой?",a="Черный Ворон действует строго как независимая организация. Лорд Джорах принимает в своем поместье разбойников и Альянса, и Орды, заботясь лишь о профессиональном мастерстве, дисциплине скрытности и абсолютной осмотрительности, а не о расовой политике.",al={"is ravenholdt alliance","is jorach horde","ravenholdt faction","черный ворон альянс","джорах орда","фракция черного ворона"}},{q="Что внутри Запечатанной лазурной сумки, которую ищет Джорах?",a="Содержимое остается строго охраняемой тайной. Когда ему поднесли Лазурный ключ, чтобы наконец открыть зачарованную сумку, лорд Джорах был озарен жутким золотым светом, с изумлением заглянул внутрь и быстро спрятал ее.",al={"sealed azure bag contents","azure bag mystery","what did jorach get","содержимое запечатанной лазурной сумки","тайна лазурной сумки","что получил джорах"}}},fp="22,302,31.670.0,22.600.1,30.264.0,39.273.0,57.249.0,49.237.1"}
P.entries["npc:lord-maxwell-tyrosus"] = {n="Лорд Максвелл Тиросс",s="Лорд Максвелл Тиросс — верховный командир Серебряного Рассвета, расположенный в их передовом оплоте, Часовне Последней Надежды в Восточных Чумных землях. Паладин-ветеран Серебряной Длани со времен Третьей войны, он направляет крестовый поход союза против Плети и организует удары по оскверненным твердыням вроде Стратхольма.",h="Лорд Максвелл Тиросс — верховный командир Серебряного Рассвета, расположенный в их передовом оплоте, Часовне...",kw={"argent dawn","kirkessen","light's hope chapel","paladin","scourge","silver hand","stratholme","tyrosus","серебряный рассвет","киркессен","часовня последней надежды","паладин","плеть","серебряная длань","стратхольм","тиросс"},ang={["class:Paladin"]="Тиросс воплощает несломленный дух Серебряной Длани, сохраняя добродетели сострадания, единства и дисциплины после смерти Утера и трагического падения отколовшихся фракций ордена.",["faction:Alliance"]="Хотя Тиросс родился дворянином Лордерона и стал героем Альянса, теперь он отдает свои силы независимому ордену, принимающему любого, кто готов сражаться с Плетью.",["faction:Horde"]="В отличие от фанатиков в Дольном Очаге и Монастыре Алого ордена, Тиросс давно выступает за сотрудничество с нелюдьми и следит, чтобы воины и шаманы Орды принимались в Часовне Последней Надежды как равные."},sec={{t="Ветеран Лордерона",b="Максвелл Тиросс ехал бок о бок с Утером Светоносным в годы катастрофической Третьей войны, охраняя выходы из Андорала, когда Плеть захлестнула королевство. После падения Лордерона он присоединился к Верховному полководцу Александросу Могрейну в Дольном Очаге, чтобы поддерживать сопротивление нежити. Уже тогда Тиросс выступал за единство всех рас и вмешивался, когда ревностные соратники вроде Бригитты Аббендис пытались казнить чужаков, таких как жрица-троллиха Забра Хекс. Когда Александроса предали, а остатки Серебряной Длани выродились в фанатичный Алый орден, Тиросс отказался следовать за ними в ксенофобию и откололся, чтобы помочь основать Серебряный Рассвет."},{t="Командир Рассвета",b="После гибели лорда Рэймонда Джорджа Тиросс возглавил Серебряный Рассвет. Он принял Дариона Могрейна в ряды на Берегу Промозглого Ветра, а позже руководил обороной укреплений Часовни Последней Надежды. Во время жестокой Осады Кровавых Тиросс нанес сокрушительный удар Киркессену Ревностному, навсегда разрушив телесную оболочку лича. Со своего командного пункта в часовне он руководит широкими военными операциями в Чумных землях, включая тактические штурмы под началом герцога Николаса Зверенхоффа против барона Ривендера в руинах Стратхольма."}},faq={{q="Кто такой лорд Максвелл Тиросс?",a="Лорд Максвелл Тиросс — паладин-человек, ветеран и верховный лидер Серебряного Рассвета. Сражавшись под началом Утера Светоносного и Александроса Могрейна в Третьей войне, теперь он командует обороной Часовни Последней Надежды и руководит кампанией союза по очищению Чумных земель.",al={"who is maxwell tyrosus","tyrosus lore","leader of argent dawn","argent dawn boss","кто такой максвелл тиросс","предания тиросс","лидер серебряного рассвета","босс серебряного рассвета"}},{q="Почему Тиросс покинул Алый орден?",a="После убийства Александроса Могрейна остатки Серебряной Длани в Лордероне становились все более радикальными и ксенофобными, уничтожая всех, кто не был чистокровным человеком. Тиросс всегда верил в сотрудничество с другими расами для победы над Плетью, поэтому он оставил фанатиков и присоединился к Серебряному Рассвету.",al={"why did tyrosus leave scarlet crusade","tyrosus scarlet crusade","is tyrosus scarlet crusade","почему тиросс покинул алый орден","тиросс алый орден","тиросс из алого ордена"}},{q="Где можно найти Максвелла Тиросса?",a="Он находится внутри святилища Часовни Последней Надежды — укрепленного оплота Серебряного Рассвета на дальнем востоке Восточных Чумных земель.",al={"tyrosus location","where is maxwell tyrosus","tyrosus map","где тиросс","где максвелл тиросс","тиросс на карте"}},{q="Какова роль Тиросса в войне за Стратхольм?",a="Тиросс координирует общую военную стратегию с герцогом Николасом Зверенхоффом, поручая проверенным искателям приключений и ударным отрядам прорваться в павший город Стратхольм и уничтожить барона Ривендера, командира Короля-лича в этом регионе.",al={"tyrosus stratholme","tyrosus rivendare","тиросс стратхольм","тиросс ривендер"}},{q="Принимает ли Тиросс всех желающих?",a="Тиросс редко принимает посторонних: годами он провел в уединении на военных советах, руководя усилиями на передовой. Искателям приключений обычно нужно заслужить глубокое уважение Серебряного Рассвета или принести важные разведданные, чтобы привлечь его внимание.",al={"can i talk to tyrosus","tyrosus audience","можно ли поговорить с тиросом","аудиенция тиросса"}},{q="Какова была роль Тиросса в Осаде Кровавых?",a="В той битве Тиросс столкнулся с Киркессеном Ревностным, высокопоставленным личом на службе Короля-лича. Тиросс нанес решающий удар, навсегда лишивший Киркессена физического тела, и нежить-чародей больше не мог принимать телесную форму.",al={"tyrosus kirkessen","siege of the sanguine","тиросс киркессен","осада кровавых"}}},fp="20,330,22.695.0,21.592.0,28.295.0,42.313.0,35.161.0,53.230.0,43.245.0,53.273.0"}
P.entries["npc:lord-pythas"] = {n="Лорд Питонас",s="Лорд Питонас, в прошлом ночной эльф-воин по имени Арин, — один из четырех искаженных предводителей Друидов Клыка в Пещерах Стенаний. Когда-то он был другом детства и верным защитником верховного друида Наралекса, но пал жертвой кошмара, оскверняющего подземный оазис. Теперь он применяет против всех, кто пытается добраться до его спящего господина, и воинскую мощь, и извращенную магию змей.",h="Лорд Питонас, в прошлом ночной эльф-воин по имени Арин, — один из четырех искаженных предводителей Друидов...",kw={"aryn","druids of the fang","gem of pythas","leaders of the fang","lord pythas","naralex","pythas","wailing caverns","арин","друиды клыка","самоцвет питонаса","повелители змей","лорд питонас","наралекс","питонас","пещеры стенаний"},ang={["class:Druid"]="Питонас воплощает трагическую судьбу многообещающего ученика, который из преданности принял магию природы, но чья вера была искажена порчей Изумрудного Сна и превратилась в змеиную ересь.",["class:Warrior"]="До того как он стал змеиным сектантом, Питонас был дисциплинированным ночным эльфом-воином и личным защитником — мрачное напоминание, что одно воинское мастерство не защитит от безумия.",["race:NightElf"]="Для любого ночного эльфа, стремящегося восстановить равновесие на израненных землях Калимдора, горько видеть, как уважаемый защитник Арин впал в темное безумие."},sec={{t="Падение стража",b="До того как принять имя Питонас, этот ночной эльф был известен как Арин. Опытный воин и верный друг детства Наралекса, он служил личным охранником верховного друида, когда экспедиция отправилась в иссушенные земли Степей. Желая лучше послужить честолюбивой мечте Наралекса вернуть жизнь в безводный край, Арин занялся изучением друидизма и оказался исключительно способным учеником. Однако воинская дисциплина и доблесть не защитили его от коварной порчи, таившейся глубоко в подземных расселинах."},{t="Смертоносный часовой",b="Когда связь Наралекса с Изумрудным Сном была захвачена темными кошмарами, разум Арина поддался вместе с разумом его собратьев-учеников. Отбросив прежнее имя и верность, он стал лордом Питонасом, одним из предводителей Друидов Клыка. Если остальные змеиные лорды предпочитают коварные заклинания или звериные облики, то Питонас сочетает смертоносное боевое мастерство с магией природы. Теперь он бродит по извилистым туннелям пещер, намереваясь защищать искаженную власть кошмара над источником пещер."}},faq={{q="Кто такой лорд Питонас?",a="Лорд Питонас был ночным эльфом-воином по имени Арин. Он был другом детства и личным телохранителем верховного друида Наралекса и изучал друидизм, чтобы помогать работе своего господина в Степях.",al={"who is pythas","lord pythas lore","who was aryn","кто такой питонас","лорд питонас предания","кем был арин"}},{q="Почему он обратился против Наралекса?",a="Питонас предал Наралекса не по своей воле. Когда Наралекс попытался обратиться к Изумрудному Сну, чтобы исцелить Степи, кошмар захватил мысли верховного друида. Оскверненный сон проник в умы его учеников, лишил Арина рассудка и превратил его в змеиного лорда.",al={"why is pythas evil","how did pythas go mad","why did he become druid of the fang","почему питонас злой","как питонас сошел с ума","почему он стал друидом клыка"}},{q="Чем Питонас отличается от других предводителей Клыка?",a="В отличие от других предводителей, полагающихся только на магию природы и звериные облики, Питонас был опытным воином еще до обучения друидизму. Он сочетает боевое мастерство с магией друидов, и потому он один из самых грозных в физической схватке защитников пещер.",al={"pythas fighting style","pythas vs other leaders","стиль боя питонаса","питонас и другие предводители"}},{q="Почему искателям приключений нужно победить его?",a="Питонас носит один из четырех зачарованных самоцветов, необходимых для задания «Повелители Змей». Задание дает друид Нара Буйногривая в Громовом Утесе: ей нужны самоцветы всех четырех предводителей Клыка, чтобы освободить Степи от их извращенных снов.",al={"leaders of the fang quest","gem of pythas","задание повелители змей","самоцвет питонаса"}},{q="Где можно найти лорда Питонаса?",a="Лорд Питонас скрывается в глубоких внутренних залах Пещер Стенаний, в окружении искаженных зверей и других приверженцев Клыка.",al={"pythas location","where is pythas","где питонас","местонахождение питонаса"}},{q="Что происходит с его самоцветом?",a="После его поражения Самоцвет Питонаса извлекают из его останков. Искатели приключений относят его вместе с самоцветами трех других змеиных лордов Наре Буйногривой в Громовой Утес, чтобы доказать, что власть Клыка сломлена.",al={"gem of pythas use","what is gem of pythas","применение самоцвета питонаса","что такое самоцвет питонаса"}}},fp="11,387,16.558.0,19.501.0,19.193.0,32.286.0,56.259.0,38.253.0,31.132.0,24.228.0"}
P.entries["npc:lord-serpentis"] = {n="Лорд Серпентис",s="Лорд Серпентис — искаженный ночной эльф-друид, один из четырех предводителей отколовшихся Друидов Клыка в Пещерах Стенаний. Некогда могущественный и уважаемый друид ордена Наралекса, он сошел с ума, когда сон Наралекса превратился в кошмар в подземных источниках. Теперь он помогает командовать сектой змеепоклонников в глубине пещер, где спит искаженный Наралекс.",h="Лорд Серпентис — искаженный ночной эльф-друид, один из четырех предводителей отколовшихся Друидов Клыка в...",kw={"druids of the fang","gem of serpentis","leaders of the fang","lord serpentis","naralex","serpentis","wailing caverns","друиды клыка","самоцвет серпентиса","повелители змей","лорд серпентис","наралекс","серпентис","пещеры стенаний"},ang={["class:Druid"]="Серпентис воплощает трагическую опасность, таящуюся в Изумрудном Сне: он показывает, как даже могущественный друид может быть искажен, когда благородное видение становится кошмаром.",["race:NightElf"]="Для ночных эльфов Серпентис и его последователи — болезненный позор: прославленные кальдораи-ученые, которые отбросили священный долг перед природой и стали чудовищными змеиными лордами.",["race:Tauren"]="Таурены видят в порче Серпентиса гнусное осквернение равновесия Матери-Земли, которое грозит хрупкой экосистеме Степей противоестественным безумием."},sec={{t="От благородного друида к змеиному лорду",b="До того как тьма окутала источники пещер, Серпентис был могущественным и уважаемым друидом, одним из благородного ордена под началом Наралекса, надеявшегося с помощью источников пещер и Изумрудного Сна исцелить Степи. Однако когда видение Наралекса стало губительным кошмаром, Серпентис оказался среди друидов, чей разум поддался нарастающему безумию."},{t="Лорд Клыка",b="Полностью поддавшись порче, исходящей от извращенных снов Наралекса, Серпентис и его собратья-друиды стали Друидами Клыка. Отвергнув традиционное равновесие Кенария и древних тотемных животных, они теперь стремятся не исцелить Степи, а переделать их под свои извращенные сны. Серпентис правит сектой как один из ее четырех предводителей наряду с Повелительницей Анакондрой, лордом Кобраном и лордом Питонасом."},{t="Последнее препятствие",b="Лорд Серпентис обитает в глубине извилистых пещер и является одним из четырех предводителей отколовшейся секты, каждый из которых носит самоцвет сна. Тем, кто хочет пробудить плененного господина или вернуть воды оазиса, нужно сразить Серпентиса и забрать его самоцвет, разрушив власть змей над лабиринтом."}},faq={{q="Кто такой лорд Серпентис?",a="Лорд Серпентис — один из четырех предводителей Друидов Клыка, обитающих в глубине Пещер Стенаний. Некогда могущественный и уважаемый ночной эльф-друид из ордена Наралекса, он был искажен кошмаром Наралекса вместе с остальными друидами.",al={"who is serpentis","lord serpentis lore","serpentis background","кто такой серпентис","лорд серпентис предания","история серпентиса"}},{q="Почему Серпентис стал злым?",a="Когда попытка Наралекса исцелить Степи через Изумрудный Сон превратилась в кошмар, порча распространилась на последовавших за ним друидов и обратила разум Серпентиса к безумию и поклонению змеям.",al={"why did serpentis turn","serpentis corruption","why is serpentis bad","почему серпентис изменился","порча серпентиса","почему серпентис злой"}},{q="Как он связан с Наралексом?",a="Серпентис был одним из благородных друидов, последовавших за Наралексом в пещеры. Вместо того чтобы помочь исцелению своего господина, он стал предводителем Друидов Клыка, которые теперь стремятся переделать Степи под свои извращенные сны.",al={"serpentis and naralex","is serpentis related to naralex","naralex apprentice","серпентис и наралекс","связан ли серпентис с наралексом","ученик наралекса"}},{q="Почему игрокам нужно убить его?",a="Серпентис — один из четырех предводителей Друидов Клыка. Его уничтожение необходимо, чтобы сломить власть секты над Пещерами Стенаний, добыть его самоцвет для задания «Повелители Змей» и расчистить путь к пробуждению Наралекса.",al={"why kill serpentis","leaders of the fang serpentis","gem of serpentis","зачем убивать серпентиса","повелители змей серпентис","самоцвет серпентиса"}},{q="Кто такие Друиды Клыка?",a="Это отколовшаяся фракция ночных эльфов-друидов, последовавших за Наралексом в Пещеры Стенаний. Оскверненные Изумрудным Кошмаром, они отказались от традиционных друидических обликов и приняли облик, яды и повадки змей под началом Серпентиса и других своих повелителей клыков.",al={"druids of the fang lore","what are druids of the fang","fang druids","друиды клыка предания","кто такие друиды клыка","клыкастые друиды"}}},fp="14,426,32.350.0,18.412.0,18.316.1,22.250.0,28.208.0,36.242.0,32.234.0,31.285.0"}
P.entries["npc:lord-shalzaru"] = {n="Лорд Шалзару",s="Лорд Шалзару — жестокий предводитель наг Гребня Ненависти, действующих с Острова Ужаса у берегов Фераласа. Он правит своими змееподобными последователями с абсолютной жестокостью и руководит обширными раскопками среди затопленных руин эльфийских поселений. Недавняя находка странной древней реликвии привлекла внимание посторонних искателей, желающих отнять ее у него.",h="Лорд Шалзару — жестокий предводитель наг Гребня Ненависти, действующих с Острова Ужаса у берегов Фераласа.",kw={"feralas","hatecrest","isle of dread","lord shalzaru","mysterious relic","naga","shalzaru","фералас","гребень ненависти","остров ужаса","лорд шалзару","таинственная реликвия","наги","шалзару"},ang={["faction:Alliance"]="Добыв реликвию Шалзару и обезвредив военачальника Гребня Ненависти, вы поможете защитить отдаленные форпосты Альянса на диком побережье Фераласа.",["faction:Horde"]="Разведчики Орды следят за прибрежными угрозами в Фераласе, а гибель лорда наг устраняет непредсказуемую опасность вблизи сферы интересов Лагеря Мохаче.",["race:NightElf"]="Наги Гребня Ненависти оскверняют древние руины древнего Калимдора; вернув реликвии у Шалзару, ночные эльфы не дадут темному наследию высокорожденных усилить его змеиных сородичей."},sec={{t="Повелитель Гребня Ненависти",b="Лорд Шалзару командует нагами Гребня Ненависти и направляет их присутствие вдоль южного побережья Фераласа. Из своего подземного логова в пещере на Острове Ужаса он поддерживает власть жестокостью и безжалостным принуждением. Под его началом наги Гребня Ненависти прочесывают древние руины древнего Калимдора в поисках забытых сокровищ и могущественных реликвий, оставшихся после Раскола."},{t="Таинственная реликвия",b="Во время раскопок к югу от главных руин на Острове Ужаса Шалзару лично обнаружил странную древнюю реликвию. Назначение и сила этого артефакта остаются тайной, но то, что она оказалась у столь могущественного нага-военачальника, явно представляет угрозу. Агенты на материке ищут отважных героев, которые проникнут в змеиное логово, покончат с властью Шалзару и добудут необычную реликвию, прежде чем Гребень Ненависти обратит ее к более темным целям."}},faq={{q="Кто такой лорд Шалзару?",a="Лорд Шалзару — жестокий властитель наг Гребня Ненависти. Он руководит силами наг и раскопками на Острове Ужаса у берегов Фераласа.",al={"lord shalzaru lore","shalzaru","who is shalzaru","лорд шалзару предания","шалзару","кто такой шалзару"}},{q="Где можно найти лорда Шалзару?",a="Он обитает в пещере к югу от главных эльфийских руин за водой на Острове Ужаса, у юго-западного побережья Фераласа.",al={"shalzaru location","where is lord shalzaru","isle of dread cave","где шалзару","местонахождение шалзару","где лорд шалзару","пещера острова ужаса"}},{q="Что такое Гребень Ненависти?",a="Гребень Ненависти — враждебное племя наг, занимающее побережье и острова Фераласа; оно известно тем, что прочесывает древние руины и терроризирует прибрежные воды под началом Шалзару.",al={"hatecrest naga","hatecrest tribe","наги гребня ненависти","племя гребня ненависти"}},{q="Какой реликвией владеет лорд Шалзару?",a="Во время недавних раскопок на Острове Ужаса Шалзару обнаружил таинственную древнюю реликвию неизвестного происхождения и силы, из-за чего фракции материка посылают героев, чтобы завладеть ею.",al={"shalzaru relic","mysterious relic feralas","реликвия шалзару","таинственная реликвия фералас"}},{q="Почему необходимо победить лорда Шалзару?",a="Устранение Шалзару разрушает власть Гребня Ненависти на Острове Ужаса и позволяет героям забрать недавно найденную им таинственную реликвию, прежде чем наги смогут ее использовать.",al={"against lord shalzaru","kill lord shalzaru","против лорда шалзару","убить лорда шалзару"}},{q="Что ищут наги Гребня Ненависти в Фераласе?",a="Наги Гребня Ненависти раскапывают руины поселений ночных эльфов, разрушенных во время Великого Раскола, в поисках могущественных магических реликвий и остатков истории высокорожденных, скрытых под землей и волнами.",al={"hatecrest excavation","why are naga in feralas","раскопки гребня ненависти","почему наги в фераласе"}}},fp="13,392,23.394.0,20.439.0,21.159.0,33.135.0,22.183.0,38.189.0,35.182.0,46.194.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="Сказитель Тотем Дождя",s="Сказитель Тотем Дождя — старейшина тауренов, живущий на севере Мулгора, к югу от Красных скал. Он охраняет священные места захоронений и просит искателей приключений прогнать свинобразов-дыбогривов, которые их тревожат.",h="Сказитель Тотем Дождя — старейшина тауренов, живущий на севере Мулгора, к югу от Красных скал.",kw={"lorekeeper raintotem","mulgore","raintotem","red rocks","sacred burial","сказитель тотем дождя","мулгор","тотем дождя","красные скалы","священное захоронение"},ang={["class:Shaman"]="Бдительность Тотема Дождя над неупокоенными мертвыми у Красных скал напрямую связана с долгом шаманов — следить, чтобы духи предков обрели покой и почтение.",["race:Tauren"]="Помощь сказителю Тотему Дождя в защите Красных скал чтит предков и сохраняет погребальные традиции вашего народа."},sec={{t="Страж Красных скал",b="Сказитель Тотем Дождя живет у священных утесов Красных скал в Мулгоре и исполняет духовные обязанности своего народа. Он просит искателей приключений прогнать с места захоронения незваных дыбогривов и вернуть покой месту упокоения предков."},{t="Защитник земель предков",b="Помимо испытания начинающих героев, Сказитель Тотем Дождя охраняет священные места погребения у Красных скал. Когда свинобразы-Дыбогривы оскверняют освященные места упокоения умерших вождей и шаманов таурен, Тотем Дождя просит путников восстановить достоинство и успокоить потревоженных мертвых."}},faq={{q="Где найти Сказителя Тотема Дождя?",a="Сказитель Тотем Дождя находится на севере Мулгора, к югу от Красных скал, на тропе, ведущей к утесам предков.",al={"raintotem location","where is lorekeeper raintotem","find raintotem mulgore","где тотем дождя","где сказитель тотем дождя","найти тотем дождя мулгор"}},{q="Почему Тотем Дождя просит помочь с местом захоронения?",a="Он просит искателей приключений прогнать незваных дыбогривов из Красных скал, где свинобразы оскверняют священное место захоронения тауренов.",al={"raintotem sacred burial","why help raintotem","red rocks burial grounds","тотем дождя священное захоронение","почему помочь тотему дождя","красные скалы захоронение"}},{q="Почему Тотему Дождя нужна помощь у Красных скал?",a="Красные скалы — священное место погребения таурен, но свинобразы-Дыбогривы разоряют могилы. Тотем Дождя поручает способным героям навести порядок в оскверненных землях предков.",al={"red rocks problem","why sacred burial quest","проблема красных скал","зачем задание священное погребение"}}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:lorgus-jett"] = {n="Лоргус Джетт",s="Лоргус Джетт — человек, член культа Сумеречного Молота, действующий в затопленных коридорах Непроглядной Пучины. Блуждая по Руинам Лунного святилища, он служит безжалостным командиром в услужении культа Древним богам. Лидеры Орды назвали его главной целью, чтобы подорвать растущее влияние культа на побережье Ясеневого леса.",h="Лоргус Джетт — человек, член культа Сумеречного Молота, действующий в затопленных коридорах Непроглядной...",kw={"allegiance to the old gods","blackfathom deeps","fallen paladin","lorgus jett","moonshrine ruins","silver hand","twilight's hammer","верность древним богам","непроглядная пучина","падший паладин","лоргус джетт","руины лунного святилища","серебряная длань","сумеречный молот"},ang={["class:Paladin"]="Лоргус Джетт — ужасное предостережение для Серебряной Длани: бывший брат, отказавшийся от догматов Света ради безумных пророчеств Древних богов.",["class:Shaman"]="Джетт повелевает стихиями не в гармонии и не с почтением, а извращенными, жестокими методами, которым учит Сумеречный Молот.",["faction:Horde"]="Убийство Лоргуса Джетта исполняет срочную просьбу уничтожить руководство Сумеречного Молота, гноящееся под берегом Ясеневого леса.",["race:Human"]="Человек так далеко на западе Калимдора, служащий космическим ужасам, — леденящее напоминание о том, как далеко распространилась порча Сумеречного Молота."},sec={{t="Осквернитель в руинах",b="Хотя многие члены Сумеречного Молота, работающие под Непроглядной Пучиной, происходят из орков или тауренов, Лоргус Джетт выделяется как человек в глубинах древних руин ночных эльфов. Бродя где угодно между верхними Руинами Лунного святилища и пещерными туннелями за мурлоком-осквернителем Гелихастом, Джетт руководит темными ритуалами и жестокими замыслами культа."},{t="Тени Серебряной Длани",b="Хотя он владеет заклинаниями стихий, необычными для людей, Джетт носит с собой реликвии, намекающие на более темное прошлое. Среди его вещей есть брошенные догматы и доспехи со знаком Рыцарей Серебряной Длани, а также огромный молот, выкованный для праведного суда. Его присутствие говорит о том, что даже набожные святые воины Восточных королевств могут поддаться безумному шепоту Древних богов и отринуть священные обеты в обмен на апокалиптическую силу."}},faq={{q="Кто такой Лоргус Джетт?",a="Лоргус Джетт — человек, агент культа Сумеречного Молота, действующий в Непроглядной Пучине. Он руководит деятельностью культа в Руинах Лунного святилища и служит Древним богам.",al={"lorgus jett lore","who is lorgus","lorgus jett background","лоргус джетт предания","кто такой лоргус","лоргус джетт история"}},{q="Где в Непроглядной Пучине можно найти Лоргуса Джетта?",a="Лоргус Джетт патрулирует изменчивую область в Руинах Лунного святилища. Его можно встретить возле первых групп сумеречных культистов или дальше в затопленных проходах сразу за святилищем Гелихаста.",al={"lorgus jett location","where is lorgus jett","find lorgus jett","лоргус джетт местонахождение","где лоргус джетт","найти лоргуса джетта"}},{q="Почему Орда хочет смерти Лоргуса Джетта?",a="Орда добивается его смерти через задание «Верность Древним богам». Его присутствие в Ясеневом лесу угрожает стабильности региона и воплощает коварный союз, стремящийся освободить древних существ, способных погубить мир.",al={"why kill lorgus","allegiance to the old gods quest","зачем убивать лоргуса","задание верность древним богам"}},{q="Был ли Лоргус Джетт паладином?",a="Связанные с ним реликвии — например, брошенные догматы Серебряной Длани и доспехи паладина — убедительно говорят о том, что он был рыцарем Серебряной Длани, отрекшимся от Света ради служения Древним богам.",al={"lorgus jett silver hand","is lorgus a fallen paladin","лоргус джетт серебряная длань","падший паладин лоргус"}},{q="Почему человек использует силы шаманов?",a="Сумеречный Молот общается напрямую с хаотическими силами стихий и Древними богами, а не с духами предков, что позволяет нетрадиционным расам, например людям, обрушивать стихийное разрушение.",al={"lorgus jett magic","human shaman lorgus","магия лоргуса джетта","лоргус человек шаман"}},{q="Что связывает Лоргуса Джетта с Гелихастом?",a="Оба обитают в Руинах Лунного святилища в Непроглядной Пучине, объединенные служением темным силам, спящим под морем; Джетт часто патрулирует коридоры за алтарем Гелихаста.",al={"lorgus and gelihast","gelihast connection","лоргус и гелихаст","связь с гелихастом"}}},fp="11,350,22.373.0,26.480.0,19.179.0,52.199.0,41.223.0,26.202.0,40.200.0,45.198.0"}
P.entries["npc:lorna-crowley"] = {n="Лорна Кроули",s="Лорна Кроули — дочь лорда Дариуса Кроули, одного из ведущих дворян Гилнеаса. Изолированная за высокой Стеной Седогрива, она остается вовлеченной в меняющуюся внутреннюю политику и конфликты закрытого человеческого королевства.",h="Лорна Кроули — дочь лорда Дариуса Кроули, одного из ведущих дворян Гилнеаса.",kw={"darius crowley","gilneas","greymane wall","lorna crowley","silverpine","дариус кроули","гилнеас","стена седогрива","лорна кроули","серебряный бор"},ang={["faction:Alliance"]="Лорна Кроули и ее семья принадлежат к утраченному королевству Гилнеас, разорвавшему связи с Альянсом Лордерона, чтобы запереть свои ворота за Стеной Седогрива."},sec={{t="Дочь мятежа",b="За колоссальными каменными укреплениями Стены Седогрива королевство Гилнеас много лет назад отгородилось от остального Лордерона. Лорна Кроули — дочь лорда Дариуса Кроули, видного дворянина, решительно выступавшего против изоляционистского указа королевства и строительства стены. Выросшая среди глубоких политических волнений и Северных врат мятежа, Лорна разделяет яростный дух и воинскую гордость отца, оставаясь скрытой от событий, которые происходят на континенте за пределами стены."}},faq={{q="Кто такая Лорна Кроули?",a="Лорна Кроули — гилнеасская дворянка и дочь лорда Дариуса Кроули. Она известна сильной волей и острым умом, сформированными политическими трениями и замкнутой борьбой внутри Гилнеаса.",al={"lorna crowley","who is lorna","darius crowley daughter","лорна кроули","кто такая лорна","дочь дариуса кроули"}},{q="Могут ли игроки встретить Лорну Кроули сейчас?",a="Нет. Лорна остается запертой за огромной Стеной Седогрива в закрытом королевстве Гилнеас, ворота которого плотно закрыты для всех чужаков.",al={"where is lorna crowley","can you find lorna","is lorna in game","где лорна кроули","можно ли найти лорну","есть ли лорна в игре"}},{q="Какую роль играет ее отец в Гилнеасе?",a="Лорд Дариус Кроули — один из первых дворян королевства. Он выступил против решения короля Генна Седогрива отгородить страну стеной и в итоге возглавил мятеж Северных врат против короны.",al={"who is darius crowley","darius crowley","crowley gilneas","кто такой дариус кроули","дариус кроули","кроули гилнеас"}},{q="Что происходит в Гилнеасе за стеной?",a="Гилнеас остается в добровольной изоляции, отрезанный от Альянса и окрестных земель со времен окончания Второй войны. Его внутренние конфликты и повседневная жизнь полностью скрыты за массивными заграждениями.",al={"what is happening in gilneas","greymane wall status","gilneas situation","что происходит в гилнеасе","состояние стены седогрива","ситуация в гилнеасе"}}},fp="13,228,25.500.0,21.198.0,41.151.0,37.188.0,45.223.0"}
P.entries["npc:loslor-rudge"] = {n="Лослор Рудж",s="Лослор Рудж — предприимчивый дворф-поставщик инженерных товаров в Поселке Сталежара в Дун Мороге. Он поставляет механические детали, инструменты и боеприпасы изобретателям на заснеженных горных хребтах, поддерживая важные связи с оружейниками вроде Хегнара Громострела.",h="Лослор Рудж — предприимчивый дворф-поставщик инженерных товаров в Поселке Сталежара в Дун Мороге.",kw={"ammo","dun morogh","engineering","grizzled den","hegnar rumbleshot","loslor rudge","steelgrill's depot","боеприпасы","дун морог","инженерное дело","серая берлога","хегнар громострел","лослор рудж","поселок сталежара"},ang={["profession:Engineering"]="Лослор держит важные расходные материалы для раннего ремесла — флюсы, взрывчатый порошок, трубки и наборы изобретателя, — так что его пост в поселке удобная остановка для любого начинающего инженера, путешествующего по Дун Морогу.",["race:Dwarf"]="Как и многие ремесленники Дун Морога, Лослор зависит от надежных вьючных маршрутов между разбросанными лагерями дворфов, а это показывает, что даже местные хищники вроде вендиго способны нарушить горную торговлю."},sec={{t="Поставщик в снегах",b="Работая в Поселке Сталежара неподалеку от Караноса, Лослор Рудж держит стабильный запас необходимого для инженерии: от медных модуляторов и бронзовых трубок до взрывчатого порошка и гаечных ключей. Суровая погода Дун Морога и обширные мастерские изобретателей означают постоянный спрос на практичные детали, и Лослор гордится тем, что снабжает местных механиков. Однако глушь между поселениями опасна: когда курьера, пошедшего напрямик возле Серой берлоги, прогнали вендиго, важная партия боеприпасов для ценного клиента, оружейника Хегнара Громострела, осталась лежать в снегу."}},faq={{q="Кто такой Лослор Рудж?",a="Лослор Рудж — дворф-поставщик инженерных товаров, чья лавка находится в Поселке Сталежара в Дун Мороге. Он продает изобретательские инструменты, детали и боеприпасы приключенцам и мастерам всего региона.",al={"loslor rudge","who is rudge","steelgrills depot engineer","лослор рудж","кто такой рудж","инженер поселка сталежара"}},{q="С какой бедой нужна помощь Лослору?",a="Недавно он отправил курьера доставить партию боеприпасов оружейнику Хегнару Громострелу. Курьер пошел напрямик мимо Серой берлоги, наткнулся на диких вендиго и сбежал, бросив ящик в снегу. Лослору нужен тот, кто вернет груз, пока он не потерял ценного клиента.",al={"ammo for rumbleshot quest","what does rudge want","rudge courier","задание патроны для громострела","что нужно руджу","курьер раджа"}},{q="Где находится Поселок Сталежара?",a="Поселок Сталежара — оживленная дворфийская перевалочная база и механическая мастерская к востоку от Караноса, у главной дороги к Лок Модану.",al={"where is steelgrills depot","steelgrill location","где поселок сталежара","местонахождение поселка сталежара"}},{q="Кто такой Хегнар Громострел?",a="Хегнар Громострел — дворф-оружейник, живущий в лагере в Дун Мороге, который зависит от Лослора Руджа в поставках свежих боеприпасов и механических компонентов.",al={"who is hegnar","rumbleshot","кто такой хегнар","громострел"}}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
P.entries["npc:lotwil-veriatus"] = {n="Лотвиль Вериатус",s="Лотвиль Вериатус — эксцентричный гном-ученый, проводящий опасные опыты со стихиями в пыльных пустошах Бесплодных земель. Он живет к востоку от Каргата вместе с язвительным учеником Люсьеном Подай-Ключ и механическим помощником по имени Серво и стремится объединить тайную теорию, алхимию и инженерное дело в единую дисциплину.",h="Лотвиль Вериатус — эксцентричный гном-ученый, проводящий опасные опыты со стихиями в пыльных пустошах...",kw={"badlands","elemental","fam'retor","kargath","lotwil","lucien","servo","veriatus","бесплодные земли","элементаль","фам'ретор","каргат","лотвиль","люсьен","серво","вериатус"},ang={["profession:Engineering"]="Инженеры узнают в Лотвиле стремление встроить механические гироскопы и шестерни в тайные удерживающие поля, а также классическую инженерную ловушку — внезапную и жестокую поломку.",["race:Gnome"]="Лотвиль воплощает гномье интеллектуальное честолюбие, доведенное до безрассудной крайности: он стремится соединить инженерное дело и тайную магию, невзирая на катастрофические риски."},sec={{t="Единое поле хаоса",b="Родом из Караноса в Дун Мороге, Лотвиль мечтает о великом университете для своего Просвещенного собрания тайноведения, алхимии и инженерных наук. Он считает, что эти три дисциплины нельзя практиковать порознь, их нужно объединить. Ради этой мечты он выбрал суровые Бесплодные земли как лабораторию, чтобы изучать местных элементалей камня и создавать связывающие оковы, способные подчинять силы стихий. Хотя он опытный исследователь — в прошлом изучал стихийные механизмы и побеждал творения Черного Железа, — его одержимость часто не дает ему видеть взрывоопасность полевых работ."},{t="Оковы стихий",b="Главное стремление Лотвиля в Бесплодных землях — испытание его оков стихийного подчинения. Поручая приключенцам собирать ядра элементалей камня, охлаждающую жидкость и гирохроноатомы, он готовит сложный ритуал, чтобы подчинить стихийного слугу. Но когда устройство наконец включают, сочетание нестабильной магии, беспорядочной инженерии и неустойчивых алхимических реагентов приводит к катастрофе: возникает огромное разъяренное стихийное чудовище по имени Фам'ретор, которое обращается против создателя."}},faq={{q="Кто такой Лотвиль Вериатус?",a="Лотвиль Вериатус — гном-ученый, живущий в уединенном лагере к востоку от Каргата в Бесплодных землях. Он один из основателей Просвещенного собрания тайноведения, алхимии и инженерных наук и стремится соединить все три области в единую научную дисциплину.",al={"who is lotwil","lotwil veriatus lore","gnome in badlands","кто такой лотвиль","лотвиль вериатус предания","гном в бесплодных землях"}},{q="Почему Лотвиль находится в Бесплодных землях?",a="Лотвиль приехал в Бесплодные земли изучать плотную популяцию диких элементалей камня. Открытая пустыня дает и сырую стихийную материю, и достаточно места для опасных опытов по подчинению, не угрожая крупным поселениям.",al={"why is lotwil in badlands","lotwil badlands camp","what is lotwil doing","почему лотвиль в бесплодных землях","лагерь лотвиля","чем занят лотвиль"}},{q="Кто такой Люсьен Подай-Ключ?",a="Люсьен Подай-Ключ — многострадальный гном-помощник Лотвиля. Крайне циничный и измученный эксцентричной болтовней хозяина, Люсьен занимается снабжением, чинит механического слугу Серво и постоянно предупреждает окружающих об опасной беспечности Лотвиля.",al={"lucien tosselwrench","lotwil assistant","lotwil apprentice","люсьен подай-ключ","помощник лотвиля","ученик лотвиля"}},{q="Что происходит, когда Лотвиль завершает свой опыт?",a="Лотвиль пытается с помощью особых оков стихийного подчинения поработить стихийное создание. Гибридная технология с треском проваливается, призывая огромного разъяренного элементаля камня по имени Фам'ретор, которого нужно убить, пока он не разрушил лагерь.",al={"lotwil experiment fail","shackles of elemental binding","fam'retor","провал опыта лотвиля","оковы стихийного подчинения","фам'ретор"}}},fp="15,338,24.619.0,22.526.1,23.268.0,34.248.0,27.269.0,49.259.1"}
P.entries["npc:lucius"] = {n="Люций",s="Люций — дворф-агент, которого можно найти возле причалов Приозерья в Красногорье. Действуя как тайный полевой связной ШРУ, разведывательной службы Штормграда, он помогает агентам с особыми навыками разведки и ремесел.",h="Люций — дворф-агент, которого можно найти возле причалов Приозерья в Красногорье.",kw={"docks","dwarf","lakeshire","lockpick","lucius","redridge","rogue","si:7","причалы","дворф","приозерье","взлом замков","люций","красногорье","разбойник","шру"},ang={["class:Rogue"]="Для разбойников, отправленных из Штормграда, Люций — важный связной и наставник, помогающий отточить навыки взлома замков и разведки.",["race:Dwarf"]="Люций напоминает, что таланты дворфов выходят далеко за пределы кузни и передовой и находят место в тайных операциях Штормграда."},sec={{t="Глаза в горах",b="Хотя Люций держится на набережной Приозерья непринужденно, на деле он тайный агент, напрямую связанный с разведывательным аппаратом Штормграда — ШРУ. Со своего поста на причалах он следит за торговлей, необычным движением и угрозами региону, подбирающимися к Красногорью. Агентов, отправленных на восток из Штормграда, направляют к нему для координации скрытых заданий и оттачивания практических навыков вроде взлома замков, что обеспечивает Короне скрытое влияние далеко за пределами Элвиннского леса."}},faq={{q="Кто такой Люций?",a="Люций — дворф-агент, живущий в Приозерье и действующий от имени ШРУ, разведывательного ведомства Королевства Штормград.",al={"lucius identity","who is the dwarf on the docks","lucius npc","кто такой люций","кто дворф на причалах","люций нпс"}},{q="Чем занимается Люций в Приозерье?",a="Он служит полевым связным для тайных агентов, обучая местных воровскому делу и взлому замков и наблюдая за передвижениями в Красногорье.",al={"what is lucius doing here","lucius purpose","why is lucius on the docks","чем занят люций","зачем нужен люций","почему люций на причалах"}},{q="В каких заданиях участвует Люций?",a="Люций — связной по заданию ШРУ «Встречи в Красногорье» и отправляет молодых разбойников взламывать замки сундуков на Лесопилке Альтера, чтобы они получили Воровской сертификат.",al={"lucius quests","redridge rendezvous quest","alther's mill","задания люция","задание встречи в красногорье","лесопилка альтера"}}},fp="6,244,21.490.0,14.127.0,33.178.0,28.171.0"}
P.entries["npc:lyria-du-lac"] = {n="Лирия дю Лак",s="Лирия дю Лак — учитель воинов из числа людей, живущая в Златоземье в Элвиннском лесу. Она находится прямо за деревенской кузницей, обучает начинающих бойцов и наставляет молодых воинов, осваивающих боевые стойки и владение оружием.",h="Лирия дю Лак — учитель воинов из числа людей, живущая в Златоземье в Элвиннском лесу.",kw={"a warrior's training","blacksmith","elwynn forest","goldshire","lyria du lac","warrior trainer","обучение воина","кузнец","элвиннский лес","златоземье","лирия дю лак","учитель воинов"},ang={["class:Warrior"]="Для воинов, только что прибывших из Аббатства Североземья, Лирия дю Лак — первый крупный учитель, которого вы встречаете в Элвиннском лесу; она поможет вам отточить владение стойками и тактику ближнего боя.",["faction:Alliance"]="Расположившись за кузницей Златоземья, Лирия следит, чтобы местные новобранцы могли защитить сердце Штормграда от разбойников из Братства Справедливости и гноллов-налетчиков."},sec={{t="Учитель воинов Златоземья",b="Пока в таверне Гордость Льва в Златоземье шумят путники, а местный кузнец стучит молотом над товарами для торговли, Лирия дю Лак остается во дворе за кузницей. Опытная в воинской дисциплине, она служит Альянсу, обучая юных воинов, только что прибывших из Аббатства Североземья. Она оценивает их готовность и знакомит с особыми боевыми приемами, чтобы те, кто берет щит и клинок во имя Штормграда, могли противостоять угрозам Элвиннского леса."}},faq={{q="Где найти Лирию дю Лак?",a="Лирия дю Лак стоит на улице прямо за кузницей в Златоземье, к западу от таверны Гордость Льва в Элвиннском лесу.",al={"lyria du lac location","where is lyria","warrior trainer goldshire","лирия дю лак местонахождение","где лирия","учитель воинов златоземье"}},{q="Какие услуги предоставляет Лирия дю Лак?",a="Она учитель воинов. Она обучает начинающих воинов основным боевым приемам, азам боевых стоек и воинской дисциплине по мере роста их мастерства.",al={"what does lyria do","lyria du lac role","what does lyria teach","что делает лирия","роль лирии дю лак","чему учит лирия"}},{q="Какие задания связаны с Лирией дю Лак?",a="Лирия дает растущим воинам задание «Обучение воина», отправляя их к ветерану Гарри Берлгарду в таверну «Свинья и свисток» в Старом городе Штормграда.",al={"lyria du lac quests","warrior quest goldshire","задания лирии дю лак","задание воина златоземье"}}},fp="12,231,28.500.0,30.129.0,39.154.0,33.164.0"}
P.entries["npc:ma-stonefield"] = {n="Мамаша Стоунфилд",s="Мамаша Стоунфилд — человеческая матриарх, живущая на Ферме Стоунфилдов на западе Элвиннского леса. Она стоит прямо у фамильной усадьбы рядом с Тетушкой Бернис и справляется с ежедневными тяготами деревенской жизни среди соседских распрей и бед с вредителями.",h="Мамаша Стоунфилд — человеческая матриарх, живущая на Ферме Стоунфилдов на западе Элвиннского леса.",kw={"bernice stonefield","elwynn forest","ma stonefield","princess","princess must die","stonefield farm","бернис стоунфилд","элвиннский лес","мамаша стоунфилд","принцесса","принцесса должна умереть","ферма стоунфилдов"},ang={["faction:Alliance"]="Для искателей приключений Альянса в Элвиннском лесу помощь трудолюбивым хозяевам вроде Мамаши Стоунфилд помогает сохранить сельскохозяйственную опору Штормграда."},sec={{t="Беды усадьбы",b="Стоя у своего дома на юго-западе Элвиннского леса, Мамаша Стоунфилд присматривает за фермой вместе с «тетушкой» Бернис Стоунфилд. Жизнь между соседней усадьбой Маклюра и ближними тыквенными грядками редко бывает спокойной. Дикие кабаны постоянно угрожают урожаю семьи, и никто не досаждает больше, чем Принцесса — громадная призовая свиноматка, известная тем, что вытаптывает поля и пожирает с трудом собранный урожай."}},faq={{q="Кто такая Мамаша Стоунфилд?",a="Мамаша Стоунфилд — одна из старейших в семье Стоунфилдов; она живет на их ферме на юго-западе Элвиннского леса вместе с родственниками, например Тетушкой Бернис.",al={"who is ma stonefield","ma stonefield","stonefield mother","кто такая мамаша стоунфилд","мамаша стоунфилд","мать стоунфилд"}},{q="Где найти Мамашу Стоунфилд?",a="Ее можно найти на улице прямо перед главным домом на Ферме Стоунфилдов, к западу от Златоземья в Элвиннском лесу.",al={"ma stonefield location","where is ma stonefield","stonefield farm loc","мамаша стоунфилд местонахождение","где мамаша стоунфилд","ферма стоунфилдов где"}},{q="Какую проблему нужно решить Мамаше Стоунфилд?",a="Мамаша Стоунфилд ищет искателей приключений, чтобы покончить с Принцессой — огромной призовой свиньей, которая раз за разом опустошает окрестные поля и пожирает местный урожай.",al={"ma stonefield quest","princess sow quest","princess must die questgiver","задание мамаши стоунфилд","задание свиноматка принцесса","принцесса должна умереть"}}},fp="13,264,18.438.0,21.166.0,31.138.0,44.163.0"}
P.entries["npc:mad-magus-tirth"] = {n="Безумный волхв Тирт",s="Волхв Тирт — эксцентричный человек-чародей, живущий на соляной равнине Виражей на Миражах в Тысяче Игл. Известный в округе разведением кур и издевательствами над превращенным в животное учеником, он также ученый с огромными познаниями в тайной магии, растративший ценные книги на ставки в гонках.",h="Волхв Тирт — эксцентричный человек-чародей, живущий на соляной равнине Виражей на Миражах в Тысяче Игл.",kw={"ancona chicken","magus tirth","mirage raceway","plucky","plucky johnson","rituals of power","shimmering flats","thousand needles","tirth","анконская курица","волхв тирт","виражи на миражах","плюха","плюха джонсон","обряды силы","мерцающая равнина","тысяча игл","тирт"},ang={["class:Mage"]="Тирт — важная фигура для магов, стремящихся глубже понять тайную силу: он написал основополагающий трактат «Обряды Силы»."},sec={{t="Чародей в пыли",b="Пока большинство магов его уровня учатся в библиотеках Даларана или Штормграда, Волхв Тирт поселился среди смазки и рева Мерцающей равнины. Среди несущихся ракетных машин Тирт торгует курами и целыми днями отдает приказы Плюхе Джонсону, своему несчастному бывшему ученику, которого держит в облике птицы. Несмотря на эксцентричность, Тирт обладает подлинным мастерством в тайной магии: он написал эзотерические труды о магической силе, прежде чем проиграл их в безрассудных ставках на трассе."},{t="Обряды и долги",b="Научное наследие Тирта включает «Обряды Силы» — книгу по тайной магии, которую ищут практикующие маги. К несчастью для начинающих чародеев, Тирту его труд больше не принадлежит. Раздавленный игорными долгами на Виражах на Миражах, маг продал том агенту Алого ордена, чтобы покрыть убытки, и ученикам и искателям знаний приходится выслеживать книгу на вражеской территории."}},faq={{q="Почему Волхв Тирт живет в пустыне?",a="Тирт живет на Мерцающей равнине рядом с Виражами на Миражах, привлеченный зрелищем и азартом. Вместо ученой жизни в большом городе он наблюдает за гонщиками-гномами и гоблинами, продает кур и предается порокам.",al={"why is tirth here","magus tirth shimmering flats","tirth location","почему тирт здесь","волхв тирт мерцающая равнина","где тирт"}},{q="Кто эта курица рядом с ним?",a="Курица — это Плюха Джонсон, бывший ученик Волхва Тирта. Тирт магией превратил Джонсона в курицу и проводит много времени, издеваясь над ним и заставляя его плясать на соляной равнине.",al={"who is plucky","plucky johnson","tirth chicken apprentice","кто такой плюха","плюха джонсон","курица ученик тирта"}},{q="Что за книга «Обряды Силы»?",a="«Обряды Силы» — продвинутый трактат о тайной энергии, написанный Волхвом Тиртом. Это важный труд для магов, стремящихся к совершенству, хотя Тирт расстался с ним, чтобы расплатиться с растущими долгами от гонок.",al={"rituals of power","tirth book","mage quest book","обряды силы","книга тирта","книга для мага"}},{q="Кому Тирт продал свою книгу?",a="Чтобы покрыть игорные убытки на Виражах на Миражах, Тирт продал свой экземпляр «Обрядов Силы» члену Алого ордена.",al={"who has rituals of power","tirth debts","scarlet crusade book","у кого обряды силы","долги тирта","алый орден книга"}}},fp="15,290,20.541.0,17.418.1,37.236.0,31.207.0,34.214.0,31.136.0"}
P.entries["npc:madame-eva"] = {n="Мадам Ева",s="Мадам Ева — почитаемая гадалка и матриарх, живущая в Темнолесье в сумрачном Сумеречном лесу. Практикуя древние мистические искусства гадания и картомантии, она часто первой в городе чувствует неестественные беды в лесу. Путники нередко ищут ее, чтобы разгадать мрачные тайны или получить оккультные обереги от подступающей тьмы.",h="Мадам Ева — почитаемая гадалка и матриарх, живущая в Темнолесье в сумрачном Сумеречном лесу.",kw={"alyssa eva","cartomancy","darkshire","duskwood","fortune teller","ghost hair thread","madame eva","stalvan","алисса ева","картомантия","темнолесье","сумеречный лес","гадалка","прядь призрачных волос","мадам ева","сталван"},ang={["class:Priest"]="Пока Свет приносит утешение живым, жрецы найдут в опоре Евы на картомантию и остатки духов любопытный, земной контрапункт традиционной церковной литургии.",["faction:Alliance"]="Для защитников Альянса, вступающих в гнетущую тень Сумеречного леса, Мадам Ева — незаменимый проводник, чьи предчувствия рассеивают смертельную путаницу леса.",["profession:Tailoring"]="Портные оценят знания Евы о необычных материалах для плетения, особенно ее умение работать с призрачной нитью, добытой прямо у призраков этих мест."},sec={{t="Гадалка Темнолесья",b="Тихо живя среди мрака Темнолесья, Мадам Ева занимается картомантией и древними народными обрядами, на которые многие в соборе Штормграда смотрели бы с подозрением. В забытом краю, где рыщут дикие звери, нежить и худшие ужасы, ее жуткие прозрения терпят и ищут отчаявшиеся горожане и странствующие искатели приключений."},{t="Узы крови и пророчества",b="Помимо ремесла гадалки, Мадам Ева глубоко предана семье: она бабушка Алиссы Евы и маленького Логана. Когда карты открывают мрачные знамения, грозящие внучке, Ева без колебаний просит помощи у проходящих странников, чтобы обыскать лес и раскрыть давно погребенные трагедии, пока история не повторилась."},{t="Защита от ночи",b="Знания Евы простираются за пределы гадания на картах до ритуального ремесла и оберегов. От плетения сверхъестественных одеяний из призрачных нитей до изготовления странных народных реликвий вроде Тотема Кары — она понимает странную сумеречную логику, управляющую беспокойными духами Сумеречного леса, лучше почти всех в городе."}},faq={{q="Кто такая Мадам Ева?",a="Мадам Ева — пожилая человеческая гадалка и предсказательница, живущая в Темнолесье. Она занимается картомантией и древними народными ремеслами, чтобы увидеть незримые опасности, подстерегающие в Сумеречном лесу.",al={"madame eva","who is eva","darkshire fortune teller","мадам ева","кто такая ева","гадалка темнолесья"}},{q="Какова роль Мадам Евы в тайне Сталвана?",a="Мадам Ева раскладывает карты и чувствует надвигающуюся сверхъестественную опасность, нависшую над ее внучкой Алиссой. Ее предсказания направляют искателей приключений к забытым документам и следам, раскрывающим мрачную историю Сталвана Мистмантла.",al={"eva stalvan","legend of stalvan eva","why does eva care about stalvan","ева сталван","легенда о сталване ева","почему еву волнует сталван"}},{q="Мадам Ева — ведьма или маг?",a="Ева — прежде всего провидица и практик древних мистических искусств, таких как картомантия, плетение духовных нитей и создание народных фигурок. Ее магия больше похожа на традиционное гадание и оккультные знания, чем на упорядоченные тайные науки Даларана или Свет.",al={"is eva a witch","eva magic type","what magic does eva use","ева ведьма","какая магия у евы","какую магию использует ева"}},{q="Кто родственники Мадам Евы в Темнолесье?",a="Она бабушка Алиссы Евы и Логана Евы. В Ночной Дозор города также входит Дозорный Ева, который, как считается, связан с ее семьей.",al={"eva family","madame eva grandchildren","alyssa eva grandmother","семья евы","внуки мадам евы","бабушка алиссы евы"}},{q="Для чего нужна Прядь призрачных волос?",a="Мадам Ева собирает эфирные нити Пряди призрачных волос у беспокойных духов, чтобы плести особые ритуальные одеяния и снабжать необходимым союзников по всему миру.",al={"ghost hair thread","eva thread quest","прядь призрачных волос","задание евы нить"}},{q="Зачем Мадам Ева изготавливает Тотем Кары?",a="Мадам Ева изготавливает Тотем Кары как мрачную симпатическую фигурку. Связывая с ней особые материалы существ, тотем обращает проклятия и вред против злобных зверей, терроризирующих лес.",al={"totem of infliction","eva totem","тотем кары","тотем евы"}}},fp="10,372,31.351.0,26.353.0,36.319.0,18.177.0,52.237.0,32.252.0,42.149.0,35.178.0,50.201.0"}
P.entries["npc:magatha-grimtotem"] = {n="Магата Зловещий Тотем",s="Магата Зловещий Тотем — матриарх племени Зловещего Тотема и Мудрая старуха Громового Утеса. Грозная шаманка и политическая интриганка, она живет на Вершине Старейшин и постоянно оспаривает замыслы Кэрна Кровавого Копыта в отношении народа таурен.",h="Магата Зловещий Тотем — матриарх племени Зловещего Тотема и Мудрая старуха Громового Утеса.",kw={"arikara","bloodhoof","cairne","elder crone","elder rise","grimtotem","magatha","ragefire","thunder bluff","zamah","арикара","кровавое копыто","кэрн","мудрая старуха","вершина старейшин","зловещий тотем","магата","огненная пропасть","громовой утес","зама"},ang={["class:Shaman"]="Магата, безусловно, одна из самых могущественных шаманок Калимдора: она повелевает первобытными стихиями с властностью, с которой мало кто из живых таурен может сравниться.",["faction:Horde"]="Хотя Магата предлагает ценную помощь и советы против местных угроз, ее яростная преданность клану и открытое презрение к другим расам делают ее ненадежной союзницей.",["race:Tauren"]="Каждый таурен знает о мрачной репутации Зловещего Тотема, и присутствие Магаты на Вершине Старейшин тревожно напоминает о расколе во взглядах, угрожающем объединенным племенам.",["race:Undead"]="Отрекшиеся путники находят у Мудрой старухи на удивление теплый прием: она активно советуется с Королевским фармацевтическим обществом в Прудах Видений."},sec={{t="Матриарх Вершины Старейшин",b="Магата достигла абсолютной власти над Зловещим Тотемом через брак по договоренности, после которого ее супруг внезапно погиб при восхождении. Из Вершины Старейшин, окруженная личной свитой и телохранителями, она остается бесспорным политическим и духовным лидером своего замкнутого племени. В отличие от Кэрна Кровавого Копыта, Магата проповедует превосходство таурен и считает другие смертные расы захватчиками Калимдора, которых следует уничтожить или смести."},{t="Странный союз",b="Несмотря на открытое презрение к не-тауренам, Магата одной из первых выступила за принятие Отрекшихся в Орду. Она утверждает, что таурены могут научить нежить духовному равновесию и помочь ей вернуть человечность. Однако на деле Магата напрямую сотрудничает с Королевским фармацевтическим обществом под Громовым Утесом, советуясь с такими фигурами, как аптекарь Зама, по вопросам практической алхимии и изучения тайных реликвий."},{t="Политические интриги",b="За фасадом мудрых советов Магата деятельно подрывает власть Кэрна и проверяет оборону возможных противников. Она отправляет искателей приключений навстречу опасностям — от разведки сил троггов в Огненной пропасти до охоты на мстительного духа Арикару. Каждое ее поручение служит либо укреплению влияния Зловещего Тотема, либо подготовке ко дню, когда она сможет полностью сместить род Кровавого Копыта."}},faq={{q="Кто такая Магата Зловещий Тотем?",a="Магата — мудрая старуха и матриарх племени Зловещего Тотема. Одаренная шаманка с детства, она взяла в свои руки всю власть над кланом после гибели супруга при восхождении. Она живет на Вершине Старейшин в Громовом Утесе и является главной политической соперницей Кэрна Кровавого Копыта.",al={"magatha backstory","who is the elder crone","elder crone thunder bluff","магата история","кто такая мудрая старуха","мудрая старуха громовой утес"}},{q="Почему Магата поддерживает Отрекшихся?",a="На словах Магата считает, что традиции таурен и шаманское знание способны вернуть Отрекшихся к человечности. Однако многие подозревают, что ее дружба с Королевским фармацевтическим обществом вызвана стремлением к тайным алхимическим секретам и политическим союзникам вне верного окружения Кэрна.",al={"magatha and undead","why magatha likes forsaken","magatha apothecary zamah","магата и нежить","почему магата любит отрекшихся","магата аптекарь зама"}},{q="Какие отношения связывают Магату и Кэрна Кровавого Копыта?",a="Магата считает Кэрна мягкотелым, наивным и неспособным вести объединенных таурен. Пока Кэрн выступает за сосуществование в Орде и мир на всем Калимдоре, Магата уверена, что Зловещий Тотем должен силой вернуть земли предков и истребить чужаков.",al={"magatha vs cairne","does magatha hate cairne","cairne and magatha","магата против кэрна","ненавидит ли магата кэрна","кэрн и магата"}},{q="В чем заключалось задание в Огненной пропасти?",a="Магата отправила посланника по имени Маур в Огненную пропасть под Оргриммаром для переговоров с местными троггами. Вместо этого трогги убили Маура, и Магата послала искателей приключений из Орды в пещеру, чтобы вернуть сумку Маура и перебить троггов в отместку.",al={"magatha ragefire quest","why magatha sent maur","lost satchel magatha","задание магаты огненная пропасть","зачем магата послала маура","потерянная сумка магата"}},{q="Кто такая Арикара?",a="Арикара — мстительный дух крылатого змея, который, как говорят, жаждет отомстить народу таурен. Магата утверждает, что Арикара ищет мести лично Кэрну Кровавому Копыту, и поручает способным героям призвать и убить зверя с помощью зачарованной агавы.",al={"serpent of vengeance","arikara quest","magatha arikara","змей мести","задание арикара","магата арикара"}},{q="Где найти Магату Зловещий Тотем?",a="Магата живет в большом главном шатре на Вершине Старейшин в Громовом Утесе. При ней служитель Рахауро и двое невозмутимых стражей племени Зловещего Тотема.",al={"magatha location","where is magatha","magatha elder rise","где найти магату","где магата","магата вершина старейшин"}}},fp="17,243,27.449.0,18.431.0,22.412.1,25.284.0,38.301.0,53.256.0,39.270.0,15.251.0,37.140.0"}
P.entries["npc:magga"] = {n="Магга",s="Магга — орчиха, живущая в пыльном поселке Колючий Холм в Дуротаре. Она находится возле оживленной таверны и встречает новоприбывших искателей приключений Орды, покидающих Долину Испытаний.",h="Магга — орчиха, живущая в пыльном поселке Колючий Холм в Дуротаре.",kw={"durotar","horde","innkeeper grosk","magga","orc","razor hill","welcome","дуротар","орда","хозяин таверны гроск","магга","орк","колючий холм","добро пожаловать"},ang={["faction:Horde"]="Для новобранцев, оставивших позади суровые испытания Долины Испытаний, Магга — обнадеживающий прием в первом настоящем поселении Дуротара."},sec={{t="Радушный прием в Колючем Холме",b="Колючий Холм — первое настоящее знакомство с большим миром для молодых орков и троллей Черного Копья, покидающих Долину Испытаний. Магга стоит рядом с местным трактиром, помогает новичкам освоиться в поселении, рассказывает им об удобствах и гостеприимстве Хозяина таверны Гроска. Держась в тени среди занятых воинов и торговцев, она помогает сплотить небольшое поселение."}},faq={{q="Кто такая Магга?",a="Магга — мирная орчиха, живущая в Колючем Холме в Дуротаре. Она стоит возле трактира, встречает новых путников Орды и указывает им, где найти ночлег и отдых.",al={"magga durotar","magga razor hill","who is magga","магга дуротар","магга колючий холм","кто такая магга"}},{q="Как Магга связана с Хозяином таверны Гроском?",a="Магга направляет усталых путников к Хозяину таверны Гроску в трактир Колючего Холма, чтобы они могли привязать камни возвращения и отдохнуть после пути из Долины Испытаний.",al={"magga and grosk","magga innkeeper","магга и гроск","магга хозяин таверны"}},{q="Выдает ли Магга задания?",a="Да, Магга выдает короткое вводное задание «Добро пожаловать!», которое отправляет новичков поговорить с местным хозяином таверны.",al={"magga quests","welcome quest","задания магги","задание добро пожаловать"}}},fp="5,239,30.421.0,13.156.0,46.166.0,28.145.0"}
P.entries["npc:maggran-earthbinder"] = {n="Землепряд Маггран",s="Землепряд Маггран — закаленный в боях ветеран-таурен, назначенный верховным вождем Кэрном Кровавым Копытом командовать лагерем Орды в Приюте у Солнечного Камня. Ожесточенный жизнью, полной жестоких схваток, он руководит обороной скалистых долин Когтистых гор от свирепых зверей и агрессивных стай гарпий. Хотя бесчисленные битвы утомили его, он остается верным стражем поселения.",h="Землепряд Маггран — закаленный в боях ветеран-таурен, назначенный верховным вождем Кэрном Кровавым Копытом...",kw={"besseleth","bloodfury","cairne bloodhoof","earthbinder","harpies","maggran","stonetalon","sun rock retreat","бессилет","кровавая ярость","кэрн кровавое копыто","землепряд","гарпии","маггран","когтистые горы","приют у солнечного камня"},ang={["faction:Horde"]="Для путников, преодолевающих крутые подъемы Когтистых гор, Маггран — главный командир, который координирует местные патрули Орды и очищает пути снабжения от зверей и гарпий.",["race:Tauren"]="Маггран воплощает тяжелую цену войны для духа шу'хало и напоминает о том, как конфликт может ожесточить даже самых твердых детей Матери-Земли."},sec={{t="Приют ветерана",b="Землепряда Магграна в Когтистые горы послал сам верховный вождь Кэрн Кровавое Копыто. Ветеран бесчисленных стычек и кровавых походов, Маггран признает, что возраст и насилие ожесточили его сердце и лишили природной мягкости, свойственной его народу. Приют у Солнечного Камня должен был стать и заставой под его твердым командованием, и местом отдыха, где теплые ветры и горное солнце смогли бы исцелить его измученный битвами дух."},{t="Угрозы в скалах",b="Даже в Когтистых горах Маггран почти не знает покоя. Как начальник Приюта у Солнечного Камня, он координирует оборону от гарпий племени Кровавой Ярости, гнездящихся на вершинах, и собирает бойцов против хищных опасностей среди скал. Однажды он пережил засаду самой гигантской паучихи Бесселет, поэтому не питает иллюзий насчет смертельных дебрей вокруг и часто нанимает путников для уничтожения опасных местных хищников, пока те не захлестнули заставу."}},faq={{q="Кто такой Землепряд Маггран?",a="Землепряд Маггран — главный старейшина таурен в Приюте у Солнечного Камня в Когтистых горах. Закаленный бесчисленными битвами, он был поставлен сюда Кэрном Кровавым Копытом, чтобы охранять поселение и защищать его дороги снабжения и границы.",al={"maggran","who is maggran","sun rock retreat leader","маггран","кто такой маггран","предводитель приюта у солнечного камня"}},{q="Почему Магграна отправили в Приют у Солнечного Камня?",a="Кэрн Кровавое Копыто назначил его руководить Приютом у Солнечного Камня отчасти за опытное военное командование, отчасти как место отдыха. Тело и душа Магграна сильно изношены жизнью в боях, и тихое горное солнце дарит ему некоторое исцеление.",al={"why is maggran here","maggran background","cairne and maggran","почему маггран здесь","прошлое магграна","кэрн и маггран"}},{q="С какими угрозами Маггран просит справиться искателей приключений?",a="Маггран руководит обороной от свирепых гарпий племени Кровавой Ярости, заполонивших горы, и посылает воинов уничтожить гигантскую паучиху-матриарха Бесселет — страшного хищника, от которого он едва спасся ранее в своих странствиях.",al={"maggran quests","what does maggran want","harpies stonetalon","задания магграна","что нужно магграну","гарпии когтистые горы"}},{q="Что произошло между Магграном и Бесселет?",a="Магграна когда-то укусила громадная паучиха Бесселет. Ему удалось отбиться от нее и спастись, и теперь он посылает способных искателей приключений убить чудовище, чтобы никто больше не стал жертвой ее паутины.",al={"maggran besseleth","spider quest maggran","arachnophobia lore","маггран бессилет","задание про паука маггран","арахнофобия предания"}},{q="Играет ли Маггран роль в Громовом Утесе?",a="Маггран служит непосредственно по поручению Верховного вождя Громового Утеса Кэрна Кровавого Копыта. Хотя он несет службу вдали, в Приюте у Солнечного Камня, его власть и приказы исходят прямо из столицы.",al={"maggran thunder bluff","maggran cairne","маггран громовой утес","маггран кэрн"}},{q="Дружелюбен ли Землепряд Маггран к игрокам Альянса?",a="Нет. Маггран — стойкий лидер Орды и остается враждебным к любым искателям приключений Альянса, забредшим в Приют у Солнечного Камня.",al={"can alliance talk to maggran","maggran hostile","может ли альянс говорить с магграном","маггран враждебен"}}},fp="19,387,17.455.0,20.472.0,27.247.0,41.256.0,55.228.0,44.210.0,42.201.0,52.133.0"}
P.entries["npc:magis-sparkmantle"] = {n="Магис Искроплащ",s="Магис Искроплащ — гном, учитель магов, работающий в таверне «Громоварка» в Караносе. Он наставляет и обучает начинающих чародеев, выходящих из Холодной долины в самое сердце Дун Морога.",h="Магис Искроплащ — гном, учитель магов, работающий в таверне «Громоварка» в Караносе.",kw={"dun morogh","gnome mage","kharanos","mage trainer","magis","magis sparkmantle","sparkmantle","thunderbrew distillery","дун морог","гном-маг","каранос","учитель магов","магис","магис искроплащ","искроплащ","громоварка"},ang={["class:Mage"]="Для магов Альянса, путешествующих по Дун Морогу, Искроплащ — важный местный контакт для обучения заклинаниям и направления к более широким тайным кругам.",["race:Gnome"]="Гномы, изгнанные из Гномрегана, часто полагаются на таких наставников, как Искроплащ, чтобы сохранять свои научные и тайные традиции, живя среди дворфов."},sec={{t="Чародей в винокурне",b="Пока дворфы собираются в таверне «Громоварка» за крепким элем, Магис Искроплащ привносит тайную магию в мир бочек и бочонков Караноса. Гномы-маги часто тесно сближаются с дворфами-союзниками по всему Дун Морогу, а Искроплащ — важный наставник для новичков, готовых расширить теоретическое и практическое понимание тайных искусств."},{t="Наставник юных магов",b="Помимо обучения новичков основам заклинаний, Магис следит, чтобы многообещающие ученики связывались с более широкими магическими кругами. Когда маги перерастают местное начальное обучение или нуждаются в особом руководстве, Искроплащ отправляет их дальше — к таким коллегам, как Бинк, или к наставникам в главных центрах Альянса."}},faq={{q="Кто такой Магис Искроплащ?",a="Магис Искроплащ — гном, учитель магов, живущий в Караносе в Дун Мороге. Он обучает начинающих чародеев основам тайной магии.",al={"magis sparkmantle","who is magis","kharanos mage trainer","магис искроплащ","кто такой магис","учитель магов каранос"}},{q="Где найти Магиса Искроплаща?",a="Его можно найти в таверне «Громоварка» — главном трактире и зале собраний города Каранос.",al={"magis location","where is magis","find sparkmantle","где магис","где найти магиса","найти искроплаща"}},{q="Почему учитель магов-гном находится в дворфийской винокурне?",a="После падения Гномрегана многие гномы поселились среди своих родичей-дворфов в Дун Мороге. Таверна «Громоварка» — центр Караноса, что делает ее удобным местом для наставничества странствующих чародеев.",al={"why in distillery","gnome in distillery","why thunderbrew distillery","почему в винокурне","гном в винокурне","почему громоварка"}},{q="Выдает ли Магис Искроплащ задания?",a="По мере развития магов Магис направляет их к другим наставникам тайных искусств, в том числе отправляет поговорить с Бинк или явиться к учителям на человеческих землях.",al={"sparkmantle quests","magis quests","задания искроплаща","задания магиса"}}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="Мировой судья Генри Малеб",s="Мировой судья Генри Малеб руководит гражданским управлением портового города Южнобережье — главного прибрежного оплота Альянса в Предгорьях Хилсбрада. Ему поручено поддерживать порядок среди постоянных угроз, и значительную часть своей власти он посвящает охоте на заговорщиков Синдиката, нацелившихся на руководство города.",h="Мировой судья Генри Малеб руководит гражданским управлением портового города Южнобережье — главного...",kw={"alterac","assassins","henry maleb","hillsbrad","magistrate maleb","southshore","syndicate","альтерак","убийцы","генри малеб","хилсбрад","судья малеб","южнобережье","синдикат"},ang={["class:Rogue"]="Разбойники увидят, что Малеб глубоко интересуется искусством скрытности и убийства и полагается на зорких агентов, чтобы перехитрить скрытых убийц Синдиката.",["faction:Alliance"]="Для защитников Альянса, прибывших в Хилсбрад, мировой судья Малеб воплощает законную гражданскую власть в беззаконном пограничье: он назначает награды за головы головорезов Синдиката, подрывающих порядок в городе."},sec={{t="Страж порядка Южнобережья",b="Мировой судья Генри Малеб работает в ратуше Южнобережья и ведает гражданским управлением одного из последних настоящих поселений Альянса в Лордероне. Город постоянно осаждают Отрекшиеся с севера и запада, а в предгорьях рыщут безжалостные разбойники. Малеб занял свой нынешний пост после загадочного убийства прежнего судьи, в котором он прямо обвиняет Синдикат. Решив не повторить его участь, он ведет активное расследование: выявляет скрытых убийц, разрушает сети снабжения Синдиката и разоблачает мятежных дворян, дергающих за ниточки из руин Альтерака."},{t="Паутина дворянского предательства",b="Расследование Малеба показывает, что Синдикат — часть жестокого регионального конфликта. Убийцы, крадущиеся по садам у Южнобережья, — не простые бандиты, а наемники, выполняющие заказы павших альтеракских аристократов. Малеб направляет доверенных разведчиков Альянса перехватывать их шифрованные планы и уничтожать их главарей, неустанно стараясь сломить влияние Синдиката прежде, чем его замыслы подорвут оборону города."}},faq={{q="Кто такой мировой судья Генри Малеб?",a="Это главный гражданский судья Южнобережья в Предгорьях Хилсбрада. Он отвечает за поддержание порядка и защиту прибрежного убежища Альянса от внутренних угроз.",al={"henry maleb","southshore magistrate","who is maleb","генри малеб","судья южнобережья","кто такой малеб"}},{q="Почему Малеб расследует деятельность Синдиката?",a="Малеб занял свой пост после убийства прежнего мирового судьи Южнобережья. Его расследование указывает на наемных убийц Синдиката, посланных павшими дворянами Альтерака, и он активно нанимает искателей приключений из Альянса, чтобы предотвратить новое покушение на свою жизнь.",al={"why syndicate","maleb syndicate","southshore assassins","почему синдикат","малеб синдикат","убийцы южнобережья"}},{q="Где найти мирового судью Малеба?",a="Его можно найти в здании ратуши в Южнобережье, расположенном в южной части Предгорий Хилсбрада.",al={"maleb location","where is henry maleb","find magistrate maleb","где малеб","где генри малеб","найти судью малеба"}},{q="Какие угрозы подстерегают Малеба в Хилсбраде?",a="Помимо постоянной угрозы расширения Отрекшихся с севера и запада, Малебу особенно угрожают теневые убийцы Синдиката, которые рыщут вокруг города и замышляют падение городской власти Южнобережья.",al={"southshore threats","maleb enemies","угрозы южнобережья","враги малеба"}}},fp="22,313,30.640.0,24.434.1,30.175.0,41.278.0,36.121.0,42.222.0"}
P.entries["npc:magistrate-sevren"] = {n="Мировой судья Севрен",s="Мировой судья Севрен — главный управляющий поселения Брилл в Тирисфальских лесах. Находясь в ратуше, он организует первую оборону Отрекшихся и направляет прибывающих героев на укрепление земель вокруг Подгорода.",h="Мировой судья Севрен — главный управляющий поселения Брилл в Тирисфальских лесах.",kw={"agamand","brill","forsaken","magistrate","sevren","tirisfal","town hall","undercity","агамонд","брилл","отрекшиеся","мировой судья","севрен","тирисфаль","ратуша","подгород"},ang={["faction:Horde"]="Союзники Орды, прибывшие в Тирисфаль, увидят, что Севрен руководит усмирением Тирисфальских лесов на передовой — против бандитов, остатков Плети и мятежных группировок.",["race:Undead"]="Для недавно освободившихся Отрекшихся, покидающих Могильник, мировой судья Севрен — гражданское лицо державы Сильваны: он дает вам первые крупные поручения по защите вашей родины."},sec={{t="Мировой судья Брилла",b="Мировой судья Севрен работает в ратуше Брилла и координирует гражданскую власть и стратегические действия на землях к северу от Подгорода. Когда новые Отрекшиеся выходят в Тирисфальские леса, Севрен оценивает местные кризисы и посылает искателей приключений восстанавливать порядок, защищать разрушенные сооружения и подавлять угрозы, не исчезающие в окрестных холмах."},{t="Охрана могил",b="Главная забота Севрена — сохранность и возвращение мертвых Тирисфаля. Местные грабители могил, гнилошкуры и мятежная нежить оскверняют места захоронений, угрожая зарождающейся власти Сильваны Ветрокрылой. Севрен следит за тем, чтобы родовые гробницы, такие как Семейная усыпальница Агамондов, были отвоеваны и чтобы дезертиры или непокорные силы не подорвали власть Отрекшихся в регионе."}},faq={{q="Кто такой мировой судья Севрен?",a="Мировой судья Севрен — глава администрации Брилла, находящийся в ратуше. Он надзирает за управлением землями Отрекшихся и раздает задания искателям приключений, приходящим из Могильника на помощь молодому государству.",al={"magistrate sevren","who is sevren","brill magistrate","мировой судья севрен","кто такой севрен","судья брилла"}},{q="Где найти мирового судью Севрена?",a="Он находится в ратуше в центре Брилла, в Тирисфальских лесах.",al={"sevren location","where is magistrate sevren","find sevren","где севрен","где мировой судья севрен","найти севрена"}},{q="С какими угрозами имеет дело мировой судья Севрен?",a="Севрен борется с местными угрозами Тирисфальским лесам: людьми-грабителями могил, мятежными гнилошкурами, остатками Плети, оскверняющими местные склепы, и мятежной нежитью, отказывающейся подчиняться леди Сильване.",al={"sevren quests","what does sevren want","brill problems","задания севрена","чего хочет севрен","проблемы брилла"}},{q="Кому верен мировой судья Севрен?",a="Он верен Отрекшимся и управляет Бриллом от имени леди Сильваны Ветрокрылой и Подгорода.",al={"sevren faction","who does sevren serve","фракция севрена","кому служит севрен"}},{q="Почему Севрен посылает искателей приключений в семейную усыпальницу?",a="Усыпальницы древней династии Агамондов наводнены нежитью и мародерами. Севрен требует, чтобы искатели приключений защитили родовые места упокоения и не позволили врагам воспользоваться ими.",al={"agamand crypt","sevren crypt quest","усыпальница агамондов","задание севрена усыпальница"}},{q="Связан ли Севрен с руководством Подгорода?",a="Да. Как местный мировой судья, он часто общается с агентами и чиновниками из Подгорода, отправляя гонцов и направляя искателей приключений дальше в столицу, когда их умение проявится в Брилле.",al={"sevren undercity","sevren raleigh","севрен подгород","севрен рэйли"}}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.209.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magistrate-solomon"] = {n="Мировой судья Соломон",s="Мировой судья Соломон — выборный правитель и главный судья Приозерья, управляющий делами города из ратуши. Осажденный орками Черной горы и неутомимыми кланами гноллов, он целыми днями отчаянно просит военной помощи у равнодушного и отвлеченного Штормграда.",h="Мировой судья Соломон — выборный правитель и главный судья Приозерья, управляющий делами города из ратуши.",kw={"blackrock","bolvar","lakeshire","magistrate solomon","marris","prestor","redridge","solomon","town hall","черная гора","болвар","приозерье","мировой судья соломон","маррис","престор","красногорье","соломон","ратуша"},ang={["faction:Alliance"]="Политическая брошенность Соломона показывает глубокие трещины внутри Альянса Штормграда и то, как окраинным провинциям остается полагаться лишь на вольных героев.",["race:Dwarf"]="Дворфы могут увидеть трагическую связь в истории Соломона: попытка Стальгорна ответить на его зов о помощи закончилась засадой и пленением принцессы Мойры Бронзобород.",["race:Human"]="Для людей разговор с Соломоном раскрывает мрачное положение королевства за пределами безопасных внутренних границ Элвиннского леса."},sec={{t="Город в осаде",b="Мировой судья Соломон управляет Приозерьем в самый мрачный час его недавней истории. Тихий озерный город окружен врагами: гноллы Красногорья и Темношкуры рыщут по окрестным холмам, а орки Черной горы спускаются с севера организованными отрядами. Соломон вместе с маршалом Маррисом поддерживает порядок и собирает оборону, но местная стража и ополчение Приозерья напряжены до предела."},{t="Мольбы без ответа",b="Отчаянно пытаясь получить подкрепление, Соломон разослал гонцов по всему королевству — просить помощи у Западного Края, Темнолесья и самой столицы, Штормграда. Его прошения принесли горькое разочарование. Западный Край страдает в тисках Братства Справедливости, Сумеречный лес поглощен собственными ползучими ужасами, а Штормград отказывается посылать войска на восточную границу, оставляя Приозерье наедине с бедой."},{t="Отказ двора",b="Когда появляются доказательства того, что орки Черной горы заключили союз с черным драконьим родом, Соломон направляет предупреждение прямо верховному лорду Болвару Фордрагону. Несмотря на масштаб угрозы, королевская советница леди Катрана Престор отвергает мольбы Соломона как дикое преувеличение. Связанный ее советом и распыленными силами Штормграда, Болвар отказывается задействовать Армию Штормграда и предлагает Соломону лишь королевское разрешение нанимать независимых наемников."}},faq={{q="Кто такой мировой судья Соломон?",a="Мировой судья Соломон — выборный гражданский лидер Приозерья и председательствующий судья суда Приозерья. Работая в ратуше, он ведает местными административными делами и организует отчаянную оборону города от вторгшихся гноллов и орков.",al={"magistrate solomon lore","who is solomon","lakeshire leader","предания о судье соломоне","кто такой соломон","глава приозерья"}},{q="Почему Штормград не может послать ему войска?",a="Армия Штормграда и так растянута по нескольким неспокойным регионам. Когда Соломон просит помощи, на верховного лорда Болвара Фордрагона сильно влияет королевская советница леди Катрана Престор, которая подвергает сомнению донесения Соломона и открыто отговаривает от отправки в Красногорье регулярных войск королевства.",al={"why no stormwind army","why won't stormwind help lakeshire","bolvar aid redridge","почему нет армии штормграда","почему штормград не поможет приозерью","болвар помощь красногорью"}},{q="Пытался ли Стальгорн прислать помощь?",a="Да. По мольбе Соломона король Магни Бронзобород отправил отряд помощи во главе с принцессой Мойрой Бронзобород. Однако экспедиция так и не дошла до Красногорья: ее застигли врасплох и захватили в Пылающих степях.",al={"dwarf reinforcements lakeshire","ironforge help redridge","moira bronzebeard lakeshire","подкрепление дворфов приозерье","помощь стальгорна красногорью","мойра бронзобород приозерье"}},{q="Какие угрозы тревожат Приозерье?",a="Приозерью одновременно угрожают гноллы Красногорья и Темношкуры, терроризирующие холмы и дороги, а также агрессивные орки Черной горы, совершающие набеги на юг из Крепости Каменной Стражи и Пылающих степей.",al={"what is attacking lakeshire","redridge enemies","why is solomon worried","кто нападает на приозерье","враги красногорья","почему тревожится соломон"}},{q="Кто помогает Соломону оборонять город?",a="Соломон сотрудничает главным образом с маршалом Маррисом, который командует местной городской стражей. Поскольку регулярные подкрепления так и не приходят, обоим чиновникам приходится нанимать странствующих искателей приключений и наделять их полномочиями, чтобы отразить наступающие угрозы.",al={"lakeshire defenders","marshal marris and solomon","защитники приозерья","маршал маррис и соломон"}},{q="Почему Соломон посылает гонцов в Темнолесье и Западный Край?",a="Зная, что двор Штормграда бездействует, Соломон пытается заключить пакты о взаимопомощи с соседними поселениями Альянса. К несчастью, Западный Край парализован Братством Справедливости, а Темнолесье захлестнули нежить и дикие звери, так что ни один не может уделить ни единого защитника.",al={"messenger to darkshire","messenger to westfall","solomon aid other towns","гонец в темнолесье","гонец в западный край","соломон помощь других городов"}}},fp="18,281,18.445.0,20.447.0,19.458.1,26.257.0,44.300.1,31.224.1,37.213.0,42.241.0,57.292.0"}
P.entries["npc:magni-bronzebeard"] = {n="Магни Бронзобород",s="Магни Бронзобород — повелитель Стальгорна, тан клана Бронзобородов и правитель Каз Модана. Непревзойденный кузнец и ветеран Второй войны, он ведет свое горное королевство через скорбь и политическое напряжение, поддерживая дворфийскую археологию по всему Азероту.",h="Магни Бронзобород — повелитель Стальгорна, тан клана Бронзобородов и правитель Каз Модана.",kw={"ashbringer","brann","bronzebeard","explorers league","ironforge","khaz modan","magni","moira","muradin","испепелитель","бранн","бронзобород","лига исследователей","стальгорн","каз модан","магни","мойра","мурадин"},ang={["faction:Alliance"]="Стойкий основатель Великого Альянса вместе с Лордероном и Штормградом, Магни приносит коалиции боевую мощь, инженерное мастерство и непоколебимую верность.",["profession:Blacksmithing"]="Магни считается одним из величайших живых кузнецов Азерота: он выковал легендарный Испепелитель из неземного кристалла на Великой наковальне Стальгорна.",["race:Dwarf"]="Магни — ваш бесспорный государь и защитник Каз Модана, ведущий клан Бронзобородов через внешние войны и внутренние поиски земляного наследия вашей расы.",["race:Gnome"]="Король Магни предоставил свой город как убежище выжившим жителям Гномрегана, сохраняя тесную дружбу и технологический союз с главным механиком Меггакрутом."},sec={{t="Повелитель горы",b="Магни, старший из трех братьев, с детства остро сознавал, какое бремя ждет его под горой. Когда во время Второй войны Орда вторглась в его земли, он удерживал Стальгорн за неприступными вратами, а после снятия осады вышел и поклялся привести Каз Модан в Альянс Лордерона. В последовавшие мирные годы Магни приютил союзников-гномов в городе после падения Гномрегана, предоставив главному механику Гелбину Меггакруту и его беженцам убежище в горе. Чтобы объединить разделенные южные и северные королевства, Магни попросил Меггакрута построить беспрецедентное подземное чудо: Подземный поезд, напрямую соединяющий Стальгорн со Штормградом."},{t="Молот возмездия",b="За царственной осанкой Магни скрывается глубокая личная трагедия. Во время Третьей войны из Нордскола пришла весть, что принц Артас Менетил предал и убил любимого младшего брата Магни, Мурадина. Охваченный горем и гневом, Магни взялся за молот у Великой наковальни, когда верховный инквизитор Фэйрбанкс и Александрос Могрейн принесли ему кристалл чистого сияющего Света. Три дня без отдыха дворфийский король вкладывал в металл все свое горе, ярость и жажду мести. Получившийся клинок — Испепелитель — стал величайшим творением всей его жизни, откованным, чтобы погубить Артаса и Плеть."},{t="Раскопки прошлого",b="По указу Магни дворфийское общество в значительной мере сменило традиционную торговую добычу руды на раскопки древней истории. Побуждаемый открытиями странных реликвий титанов глубоко под землей, Магни вместе с уцелевшим братом Бранном Бронзобородом основал Лигу исследователей. Дворфийские раскопки теперь разбросаны по континентам, от Дун Морога до Калимдора, и стремятся раскрыть тайну того, как земельники стали современными дворфами. Однако мир в стране остается хрупким: дочь Магни, принцесса Мойра, пропала, и считается, что ее похитил ненавистный клан Черного Железа."}},faq={{q="Кто такой Магни Бронзобород?",a="Магни Бронзобород — король Каз Модана, тан Стальгорна и вождь клана Бронзобородов. Он правит горным королевством с Высокого трона в Стальгорне и является одним из верных столпов Великого Альянса.",al={"king of ironforge","dwarf king","who is magni","король стальгорна","король дворфов","кто такой магни"}},{q="Кто выковал Испепелитель?",a="Король Магни сам выковал легендарный меч на Великой наковальне в Стальгорне. Александрос Могрейн и верховный инквизитор Фэйрбанкс принесли ему загадочный кристалл живого Света, и Магни вложил в клинок горе и ярость из-за вести о гибели Мурадина, три дня безостановочно трудясь в кузне.",al={"did magni make ashbringer","ashbringer creator","who made the ashbringer","создал ли магни испепелитель","создатель испепелителя","кто сделал испепелитель"}},{q="Что случилось с братьями Магни?",a="Магни — старший из трех братьев. Его брат Мурадин служил послом Альянса в Лордероне и, по слухам, был убит принцем Артасом в Нордсколе. Младший брат, Бранн, — известный исследователь, который путешествует по самым дальним уголкам мира, возглавляя Лигу исследователей.",al={"muradin and brann","magni brothers","muradin bronzebeard fate","мурадин и бранн","братья магни","судьба мурадина бронзоборода"}},{q="Где принцесса Мойра?",a="Принцесса Мойра Бронзобород, единственное дитя Магни, исчезла из Стальгорна. По официальным сообщениям в горе, ее похитили враждебные дворфы из клана Черного Железа, и она томится в плену в глубинах Черной горы.",al={"magni daughter","where is moira","what happened to moira bronzebeard","дочь магни","где мойра","что случилось с мойрой бронзобород"}},{q="Почему гномы живут в Стальгорне?",a="После вторжения троггов и ужасного облучения Гномрегана король Магни открыл врата Стальгорна для главного механика Гелбина Меггакрута и уцелевших гномов. Магни выделил им целый район города, ныне известный как Город механиков.",al={"tinker town","why are gnomes in the dwarf city","gnome refugees ironforge","город механиков","почему гномы в городе дворфов","гномы-беженцы стальгорн"}},{q="Что такое Лига исследователей?",a="Лига исследователей — археологическая организация, основанная королем Магни и его братом Бранном. После обнаружения древних руин титанов Магни направил дворфийскую промышленность на поиски истины о происхождении их расы, разослав изыскательские группы по всему Азероту.",al={"explorers guild","dwarf archaeologists","why are dwarves digging","гильдия исследователей","дворфы-археологи","зачем дворфы копают"}}},fp="17,280,20.683.0,21.631.0,19.597.0,25.222.0,26.296.0,34.283.0,24.239.0,35.242.0,30.267.0"}
P.entries["npc:magus-rimtori"] = {n="Волхв Римтори",s="Волхв Римтори — отступница, чародейка из крови эльфов, возглавляющая экспедицию среди древних руин Азшары. Известная безжалостным коварством, она обманом заставила Орду обеспечить ей переправу через Калимдор, а затем перебила свою орочью охрану.",h="Волхв Римтори — отступница, чародейка из крови эльфов, возглавляющая экспедицию среди древних руин Азшары.",kw={"azshara","belgrom","blood elf","hawkhelm","kim'jael","magus rimtori","rimtori","thalassian base camp","азшара","белгром","эльф крови","соколиный шлем","ким'джаэль","волхв римтори","римтори","талассийское поселение"},ang={["class:Mage"]="Римтори показывает, на что готовы пойти талассийские маги в отчаянной погоне за тайной силой, перебирая руины Калимдора и демонические реликвии.",["faction:Horde"]="Римтори обманула Белгрома и перебила орочью стражу, назначенную ее сопровождать, поэтому ее убийство — первоочередная задача для воинов Орды, желающих отомстить за павших сородичей."},sec={{t="Смертельный обман",b="Волхв Римтори повела экспедицию высокорожденных эльфов крови через море к древним берегам Азшары. Чтобы ее отряд пережил опасности Калимдора, она обманула орка Белгрома, очаровывая его и играя им, пока он не согласился выделить вооруженный эскорт. Когда солдаты благополучно доставили ее к цели, Римтори показала свое истинное лицо, обратилась против защитников и истребила весь гарнизон. Расположив силы в Талассийском поселении, она отправилась в прибрежные дебри в сопровождении элитных телохранителей на поиски забытых магических артефактов."},{t="Тайны руин",b="Истинный мотив экспедиции Римтори остается скрытым тайной, хотя ее безжалостные методы нажили ей множество врагов. Кроме предательства Орды, она обманула и местных наемников, в том числе гоблина-землемера Ким'джаэль, которая утверждает, что Римтори одержимо искала древнюю руну. Окруженная реликвиями, такими как демонический призывающий том, оставленный в ее лагере, Римтори в погоне за силой навлекла на себя яростную месть Орды, которую так бессердечно предала."}},faq={{q="Почему Орда хочет смерти Римтори?",a="Римтори очаровала и обманула орка Белгрома, заставив его выделить ее экспедиции военный эскорт через Калимдор. Благополучно добравшись до Азшары, она предала и убила всех орочьих солдат под командованием Белгрома.",al={"why kill rimtori","belgrom rimtori lore","what did rimtori do to the horde","почему убить римтори","белгром римтори предания","что римтори сделала с ордой"}},{q="Где можно найти Волхва Римтори?",a="Пока ее экспедиция обустраивала Талассийское поселение, сама Римтори бродит по дебрям Азшары в сопровождении личных телохранителей-эльфов крови в поисках древних реликвий.",al={"rimtori location","where is magus rimtori","rimtori azshara location","где римтори","где волхв римтори","римтори азшара местонахождение"}},{q="Что Римтори искала в Азшаре?",a="По словам гоблина Ким'джаэля, которого она наняла, а затем предала, Римтори одержимо искала таинственную древнюю руну, а также другие могущественные реликвии, например книгу призыва кальдораев.",al={"what does rimtori want","rimtori purpose azshara","rimtori rune","что нужно римтори","цель римтори в азшаре","руна римтори"}},{q="Кто такой магистр Соколиный Шлем?",a="Магистр Соколиный Шлем — офицер из эльфов крови, которому Волхв Римтори поручила командовать Талассийским поселением и управлять им, пока она исследует окрестные руины.",al={"hawkhelm","thalassian camp leader","magister hawkhelm rimtori","соколиный шлем","глава талассийского лагеря","магистр соколиный шлем римтори"}}},fp="13,241,18.585.0,20.485.1,37.236.0,33.191.0,42.198.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="Май'ах",s="Май'ах — наставница магов из джунглевых троллей, живущая в выжженной солнцем котловине Долины Испытаний в Дуротаре. Она обучает начинающих чародеев из троллей Черного Копья, которые приходят в красные каньоны, чтобы отточить владение тайной магией. Юным троллям, вступающим на путь волшебства, она дает первые наставления и обучает основам магии.",h="Май'ах — наставница магов из джунглевых троллей, живущая в выжженной солнцем котловине Долины Испытаний в...",kw={"darkspear","durotar","mage trainer","mai'ah","maiah","troll","valley of trials","черное копье","дуротар","наставник магов","май'ах","тролль","долина испытаний"},ang={["class:Mage"]="Для чародеев Черного Копья Май'ах — начало магического пути: она учит дисциплине, необходимой, чтобы плести огонь, лед и тайную энергию под жестоким солнцем Дуротара.",["race:Troll"]="Май'ах дает юным троллям Черного Копья в Долине Испытаний культурное наставничество в искусстве, которое их союзники-орки практикуют редко."},sec={{t="Наставница тайной магии в Логове",b="Хотя орки в подавляющем большинстве предпочитают первобытный зов стихий или физическую мощь воина, тролли Черного Копья обладают редкой склонностью к изучению тайной магии. В Долине Испытаний Май'ах обучает юных троллей-магов, пришедших пройти обряд взросления. Она принимает кандидатов с глифическими надписями и начинает превращать их хаотичную сырую силу в упорядоченные заклинания, помогая освоить контроль, необходимый, чтобы пережить опасности Дуротара."}},faq={{q="Кто такая Май'ах?",a="Май'ах — наставница магов из троллей Черного Копья в Долине Испытаний в Дуротаре. Она дает первые наставления, обучение и базовые заклинания только что прибывшим троллям-чародеям, прежде чем те отправятся в более широкие земли Орды.",al={"who is maiah","maiah lore","troll mage trainer","кто такая май'ах","май'ах предания","наставница магов троллей"}},{q="Почему в стартовой зоне орков есть наставница магов-троллей?",a="После того как тролли Черного Копья бежали с тонущего родного острова и поселились в Дуротаре рядом с орками Тралла, юные тролли Черного Копья проходят испытания взросления вместе с юными орками. Поскольку орочья культура по большей части чурается тайной магии из-за былой демонической порчи, тролли-маги вроде Май'ах берут на себя наставничество своих сородичей.",al={"why troll mage here","valley of trials troll trainer","troll mage durotar","почему тролль маг здесь","наставник троллей долина испытаний","тролль маг дуротар"}},{q="Какую роль она играет в обучении новых магов?",a="Май'ах встречает новых троллей-магов с письменными указаниями, например глифическими пергаментами. Она начинает их формальное обучение, преподавая основы колдовства, чтобы они могли защитить Долину Испытаний от местных зверей и лазутчиков Пылающего Клинка.",al={"what does maiah do","glyphic parchment maiah","maiah quests","что делает май'ах","глифический пергамент май'ах","задания май'ах"}}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:major-mattingly"] = {n="Майор Маттингли",s="Майор Маттингли — опытный офицер Армии Штормграда, несущий службу у великих врат в Аллее Героев. Служа под началом генерала Маркуса Джонатана, он помогает охранять главный вход в столицу и советует умелым мастерам, как защитить героев от драконьих угроз.",h="Майор Маттингли — опытный офицер Армии Штормграда, несущий службу у великих врат в Аллее Героев.",kw={"dragonscale cloak","marcus jonathan","major mattingly","mattingly","stormwind army","valley of heroes","плащ из драконьей чешуи","маркус джонатан","майор маттингли","маттингли","армия штормграда","аллея героев"},ang={["class:Warrior"]="Дисциплинированный ветеран с длинным мечом у городских врат, Маттингли воплощает непоколебимую решимость офицеров пехоты Армии Штормграда.",["faction:Alliance"]="Для героев Альянса, желающих бросить вызов великим драконам вроде Ониксии, Майор Маттингли дает важные наставления по созданию защитных плащей из драконьей чешуи."},sec={{t="Страж врат столицы",b="Майор Маттингли, несущий дозор в Аллее Героев, — один из высокопоставленных офицеров, напрямую отвечающих за главную сухопутную оборону Штормграда. Седой ветеран, чье лицо хранит следы тяжело доставшегося опыта, он служит под началом генерала Маркуса Джонатана вместе с постоянным гарнизоном города. Помимо ежедневных обязанностей по надзору за патрулями у врат и прибывающими путниками, Маттингли обладает особыми тактическими знаниями о смертоносной природе драконов. Опытные искатели приключений знают его как важного помощника для тех, кто учится создавать защитное снаряжение из драконьей чешуи, необходимое, чтобы отважиться войти в самые опасные логова королевства."}},faq={{q="Где можно найти Майора Маттингли?",a="Майор Маттингли находится возле входа в Штормград, в Аллее Героев, и несет дозор вместе с другими гарнизонными солдатами сразу за главными вратами.",al={"mattingly location","where is major mattingly","find major mattingly","где маттингли","где майор маттингли","найти майора маттингли"}},{q="Каково звание и роль Майора Маттингли в Штормграде?",a="Он офицер Армии Штормграда, служащий под началом генерала Маркуса Джонатана. Он помогает руководить обороной городских врат и дает воинские советы искателям приключений.",al={"who is mattingly","mattingly job","what does mattingly do","кто такой маттингли","должность маттингли","чем занимается маттингли"}},{q="Почему кожевники ищут Майора Маттингли?",a="Маттингли знает, как обрабатывать шкуру черных драконов и изготавливать из нее чешуйчатые плащи, и наставляет умелых мастеров, желающих защитить союзников от драконьего пламени.",al={"onyxia scale cloak mattingly","mattingly quest","the journey has just begun mattingly","плащ из чешуи ониксии маттингли","задание маттингли","путь только начался маттингли"}},{q="Участвует ли Майор Маттингли в более масштабных конфликтах?",a="Он закаленный в боях ветеран Королевства Штормград, преданный защите державы, пока король Вариан Ринн остается пропавшим, а королевство сталкивается с сохраняющимися угрозами.",al={"mattingly background","mattingly lore","прошлое маттингли","предания маттингли"}}},fp="15,284,29.642.0,35.165.0,53.173.0,47.173.0,53.187.0"}
P.entries["npc:major-samuelson"] = {n="Майор Самуэльсон",s="Майор Самуэльсон — высокопоставленный офицер городской стражи Штормграда, несущий службу в тронном зале Крепости Штормграда. Опытный военный командир, он занимается важными кадровыми вопросами и ранее наставлял младших офицеров, таких как лейтенант Фаррен Оринель.",h="Майор Самуэльсон — высокопоставленный офицер городской стражи Штормграда, несущий службу в тронном зале...",kw={"farren orinelle","major samuelson","reassignment","samuelson","southshore","stormwind guard","stormwind keep","фаррен оринель","майор самуэльсон","перевод","самуэльсон","южнобережье","стража штормграда","крепость штормграда"},ang={["faction:Alliance"]="Майор Самуэльсон, служащий в королевском тронном зале, представляет собой административную опору армии Штормграда и руководит личным составом на спорных территориях, таких как Хилсбрад."},sec={{t="Опора стражи Штормграда",b="Майор Самуэльсон стоит в Крепости Штормграда перед королевским двором и представляет руководство городской стражи Штормграда. Он ведает назначениями офицеров и административными военными приказами по всему королевству. В частности, он был наставником лейтенанта Фаррена Оринеля, офицера, служащего далеко на севере, в Южнобережье в Предгорьях Хилсбрада. Когда младшие командиры оказываются перегружены или хотят перевестись из отдаленных пограничных гарнизонов, их просьбы и официальные донесения идут через все королевство прямо на стол майора Самуэльсона в столице."}},faq={{q="Кто такой майор Самуэльсон?",a="Майор Самуэльсон — офицер городской стражи Штормграда, несущий службу в тронном зале Крепости Штормграда. Он выступает как командир административной части, ведающий назначениями офицеров и кадрами.",al={"samuelson","major samuelson identity","who is the major in keep","самуэльсон","кто такой майор самуэльсон","кто майор в крепости"}},{q="Где можно найти майора Самуэльсона?",a="Он находится в Крепости Штормграда, в Штормграде, в тронном зале рядом с юным королем Андуином Ринном и верховным лордом Болваром Фордрагоном.",al={"samuelson location","where is major samuelson","find samuelson","где самуэльсон","где найти майора самуэльсона","местонахождение самуэльсона"}},{q="Как он связан с Южнобережьем?",a="Майор Самуэльсон был наставником лейтенанта Фаррена Оринеля, офицера, служащего в Южнобережье в Предгорьях Хилсбрада. Оринель через Самуэльсона добивается перевода с напряженной северной должности.",al={"samuelson southshore","lieutenant farren orinelle mentor","samuelson hillsbrad","самуэльсон южнобережье","лейтенант фаррен оринель наставник","самуэльсон хилсбрад"}},{q="Почему искатели приключений ищут его?",a="Искатели приключений, прибывающие с северного фронта в Хилсбраде, доставляют майору Самуэльсону в Крепость Штормграда официальную просьбу лейтенанта Фаррена Оринеля о переводе.",al={"stormwind ho quest turnin","reassignment quest","why talk to samuelson","сдать задание в штормграде","задание о переводе","зачем говорить с самуэльсоном"}}},fp="15,271,29.546.0,23.190.0,35.148.0,37.215.0,32.165.0"}
P.entries["npc:makaba-flathoof"] = {n="Макаба Плоское Копыто",s="Макаба Плоское Копыто — таурен, переживший нападение, родом из Лагеря Апарахе в Когтистых горах. Став свидетелем гибели своего дома и народа от рук клана Зловещего Тотема, он ищет храбрых защитников Орды, которые отомстят нападавшим и обеспечат безопасность его семьи.",h="Макаба Плоское Копыто — таурен, переживший нападение, родом из Лагеря Апарахе в Когтистых горах.",kw={"camp aparaje","flathoof","grimtotem","grundig darkcloud","kaya","makaba","stonetalon","лагерь апарахе","плоское копыто","зловещий тотем","грундиг темное облако","кайя","макаба","когтистые горы"},ang={["faction:Horde"]="Призывы Макабы о помощи позволяют защитникам Орды доказать верность союзникам-тауренам, наказав тех, кто режет жителей мирных лагерей.",["race:Tauren"]="Для героев-тауренов беда Макабы показывает горькое предательство Зловещего Тотема и напоминает, что не все их сородичи чтят путь мира и единства."},sec={{t="Трагедия в Лагере Апарахе",b="Макаба Плоское Копыто воплощает горькую цену междоусобиц среди тауренов. Его дом, Лагерь Апарахе в Когтистых горах, стал жертвой безжалостного внезапного нападения клана Зловещего Тотема. Хотя многие таурены стремятся к миру и единству под руководством Кэрна Кровавого Копыта, коварный Зловещий Тотем постоянно сеет раздор и насилие, оставляя таких уцелевших, как Макаба, без дома и в горе."},{t="Мольба о мести",b="Не в силах в одиночку вернуть павшее поселение, Макаба призывает путников из Орды нанести ответный удар. Он направляет жестокое возмездие против отступников Зловещего Тотема, захвативших его дом, и требует справедливости за убитых сородичей. Больше всего его заботят встреча с ответственным за нападение полководцем Грундигом Темным Облаком и вести о пропавшей родственнице Кайе."}},faq={{q="Кто такой Макаба Плоское Копыто?",a="Макаба Плоское Копыто — таурен-беженец из Лагеря Апарахе в Когтистых горах. Его деревню захватил и разграбил клан Зловещего Тотема, и он вынужден искать помощи у искателей приключений Орды.",al={"makaba","who is makaba flathoof","makaba flathoof lore","макаба","кто такой макаба плоское копыто","предыстория макабы плоское копыто"}},{q="Откуда родом Макаба?",a="Макаба родом из Лагеря Апарахе, небольшого поселения тауренов в Когтистых горах, на которое напал и которое разорил Зловещий Тотем.",al={"makaba origin","where is makaba from","camp aparaje makaba","происхождение макабы","откуда макаба","лагерь апарахе макаба"}},{q="Кто напал на деревню Макабы?",a="Лагерь Апарахе разграбил клан Зловещего Тотема — агрессивная и коварная группировка тауренов, которой на местах руководят такие фигуры, как Грундиг Темное Облако.",al={"who attacked camp aparaje","makaba enemies","who sacked aparaje","кто напал на лагерь апарахе","враги макабы","кто разграбил апарахе"}},{q="Что Макаба хочет от искателей приключений Орды?",a="Макаба жаждет мести за свой павший дом и просит умелых воинов перебить силы Зловещего Тотема в Лагере Апарахе, уничтожить их предводителя Грундига Темное Облако и выяснить судьбу Кайи Плоского Копыта.",al={"makaba quests","what does makaba ask for","makaba tasks","задания макабы","что просит макаба","поручения макабы"}},{q="Кем Кайя приходится Макабе?",a="Кайя Плоское Копыто — родственница Макабы, пропавшая во время нападения на Лагерь Апарахе. Макаба отчаянно надеется узнать, выжила ли она.",al={"kaya flathoof","who is kaya","makaba relative kaya","кайя плоское копыто","кто такая кайя","родственница макабы кайя"}},{q="Родственник ли Макаба Диму Плоское Копыто?",a="У Макабы и Дима одна фамилия — Плоское Копыто, что указывает на принадлежность к одному роду тауренов, хотя степень их родства подробно не раскрывается.",al={"dim flathoof","makaba and dim","flathoof family","дим плоское копыто","макаба и дим","род плоское копыто"}}},fp="15,291,23.401.0,20.378.1,23.189.0,27.144.0,30.141.0,46.199.0,22.152.0,34.172.0"}
P.entries["npc:malfurion-stormrage"] = {n="Малфурион Ярость Бури",s="Малфурион Ярость Бури — первый смертный друид и почитаемый предводитель ночных эльфов вместе с верховной жрицей Тирандой Шелест Ветра. Прославленный победами над Пылающим Легионом в Войне Древних и Третьей войне, он почитаем как Шан'до, то есть уважаемый учитель. Сейчас он погружен в беспробудный сон в Изумрудном Сне, и кальдораи лишены его живого руководства.",h="Малфурион Ярость Бури — первый смертный друид и почитаемый предводитель ночных эльфов вместе с верховной...",kw={"archdruid","cenarius","emerald dream","furion","hyjal","illidan","malfurion","shan'do","stormrage","tyrande","верховный друид","кенарий","изумрудный сон","фурион","хиджал","иллидан","малфурион","шан'до","ярость бури","тиранда"},ang={["class:Druid"]="Каждый друид возводит свои учения к Малфуриону, учившемуся непосредственно у Кенария. Его отсутствие в Изумрудном Сне бросает тяжелую тень на Круг Кенария.",["class:Priest"]="Малфурион — возлюбленный верховной жрицы Тиранды Шелест Ветра, соединяющий духовную преданность Элуне со священной защитой природы.",["race:NightElf"]="Малфуриона почитают как древнего защитника и спасителя вашего народа, хотя его затянувшийся сон оставляет управление целиком Тиранде и верховному друиду Фэндралу Оленьему Шлему."},sec={{t="Первый друид",b="Десять тысяч лет назад, до того как Великий Раскол разбил древний Калимдор, Малфурион учился у полубога Кенария. Пока королева Азшара и ее высокорожденные опасно погружались в магические энергии Источника Вечности, Малфурион обратился к первозданным силам природы и стал первым смертным друидом Азерота. Его подозрения насчет высокорожденных трагически подтвердились, когда безрассудное колдовство Азшары прорвало завесу и призвало в Азерот Саргераса и Пылающий Легион, развязав катастрофическую Войну Древних."},{t="Спаситель Калимдора",b="Вместе с Кенарием, Тирандой Шелест Ветра и своим братом-близнецом Иллиданом Малфурион возглавил сопротивление, остановившее натиск демонов, и закрыл портал над Источником Вечности. После раскола мира Малфурион посвятил друидов Изумрудному Сну, чтобы восстановить и защитить живую ткань Азерота. Десять тысячелетий спустя Тиранда пробудила его от долгого сна в пещерах, чтобы противостоять Архимонду в Третьей войне, и у Горы Хиджал он поднял лесных духов, чтобы вновь сокрушить Пылающий Легион."},{t="Потерянный в Сне",b="После Третьей войны Малфурион вернулся ко сну на Лунной поляне, чтобы общаться с Изумрудным Сном и восстановить истраченные силы. Однако его дух не вернулся в физическое тело, и он оказался в неестественном бессознательном состоянии. В Дарнассе верховный друид Фэндрал Олений Шлем взял на себя мирские обязанности руководства Кругом Кенария, а Тиранда и сестринство тревожно ждут признаков пробуждения своего великого Шан'до."}},faq={{q="Где сейчас Малфурион Ярость Бури?",a="Малфурион физически спит в пещерах-курганах Лунной поляны, а его сознание остается в ловушке глубоко в мире духов Изумрудного Сна. Его нельзя встретить как обычного персонажа в Дарнассе: его тело лежит в беспробудном сне и недоступно большинству искателей приключений.",al={"where is malfurion","where to find malfurion","malfurion location","is malfurion in game","где малфурион","где найти малфуриона","местонахождение малфуриона","есть ли малфурион в игре"}},{q="Почему Малфурион спит?",a="Друиды регулярно погружаются в спячку в Изумрудном Сне, чтобы общаться с природой, поддерживать флору и фауну мира и восстанавливать духовные силы. После огромного магического напряжения в победе над Архимондом у Горы Хиджал Малфурион вошел в Сон, чтобы восстановиться, но неестественный недуг отделил его дух от тела.",al={"why is malfurion sleeping","why is he comatose","what happened to malfurion","почему малфурион спит","почему он в коме","что случилось с малфурионом"}},{q="Кто правит ночными эльфами, пока Малфурион спит?",a="Верховная жрица Тиранда Шелест Ветра правит народом кальдораев из Храма Луны в Дарнассе, возглавляя Часовых и Сестринство Элуны. Между тем Кругом Кенария и делами друидов ведает верховный друид Фэндрал Олений Шлем.",al={"who leads night elves","who is the night elf leader","night elf ruler","кто возглавляет ночных эльфов","кто лидер ночных эльфов","правитель ночных эльфов"}},{q="Что означает «Шан'до»?",a="На дарнасском «Шан'до» означает «уважаемый учитель». Это титул высшего почтения, отведенный великим друидам, прежде всего Малфуриону Ярость Бури, который первым принес друидизм смертным расам под руководством Кенария.",al={"shando meaning","what is shando","shan'do","значение шан'до","что такое шан'до","шан'до"}},{q="Кто брат Малфуриона?",a="Брат-близнец Малфуриона — Иллидан Ярость Бури. Несмотря на общую юность в Сурамаре, одержимость Иллидана тайной магией и безрассудная погоня за демонической силой вызвали между ними жестокий разрыв в Войне Древних, и Малфурион заточил его на тысячелетия.",al={"malfurion brother","who is illidan to malfurion","stormrage brothers","брат малфуриона","кто иллидан малфуриону","братья ярость бури"}},{q="Что сделал Малфурион в битве на Горе Хиджал?",a="В кульминации Третьей войны Малфурион протрубил в Рог Кенария у Мирового Древа Нордрассила, призвав тысячи древних лесных духов (блуждающих огоньков). Духи облепили повелителя демонов Архимонда и взорвались, уничтожив демона и сжегши Мировое Древо ради спасения Калимдора.",al={"malfurion hyjal","battle of mount hyjal malfurion","how did malfurion defeat archimonde","малфурион хиджал","битва на горе хиджал малфурион","как малфурион победил архимонда"}}},fp="19,403,15.549.0,18.530.0,17.461.0,39.270.0,24.330.0,49.248.0,25.229.0,27.276.0,51.294.0"}
P.entries["npc:mangletooth"] = {n="Кривозуб",s="Кривозуб — пленный свинобраз из племени Иглогривых, которого Орда держит в заключении в Лагере Таурахо. Ему грозит казнь, и он обменивает стратегические сведения о своих противниках и древние предания об Агамаггане на услуги искателей приключений, готовых выполнить его поручения.",h="Кривозуб — пленный свинобраз из племени Иглогривых, которого Орда держит в заключении в Лагере Таурахо.",kw={"agamaggan","barrens","blood shards","bristleback","camp taurajo","mangletooth","quilboar","razormane","агамагган","степи","кровавые осколки","дыбогрив","лагерь таурахо","кривозуб","свинобраз","иглогривые"},ang={["faction:Horde"]="Стражи Лагеря Таурахо держат Кривозуба в клетке под пристальным надзором, однако Орда готова использовать горькие обиды пленника, чтобы сокрушить оплоты свинобразов по всем Степям.",["race:Tauren"]="Охотники-тауренов постоянно сражаются со свинобразами за земли на равнинах, поэтому готовность Кривозуба обратиться против своих делает его ценным, хотя и тревожным военным союзником."},sec={{t="Заложник в цепях",b="Кривозуб, пленный свинобраз из Иглогривых, сидит в клетке в Лагере Таурахо под охраной охотников-тауренов и орков-часовых и ждет казни. Не смиряясь со смертью, он пытается подтолкнуть своих тюремщиков и посещающих искателей приключений Орды к уничтожению врагов его племени, надеясь, что хитрость докажет его ценность или принесет спасение."},{t="Предатель в наших рядах",b="Сначала Кривозуб замышляет заслужить благодарность своего клана, направив силу Орды против соперничающего племени Дыбогривов. Однако вскоре он понимает, что его собратья-вожди Иглогривых — Нак, Каз и Лок Губитель Орков — полностью бросили его гнить в плену. В ярости от их предательства пленный свинобраз обращает свою месть против своих же, направляя искателей приключений казнить бывших союзников."},{t="Сила кровавых осколков",b="Хорошо зная религиозную историю своего народа, Кривозуб знает, что огромные шипы по всем Степям выросли из пролитой крови Агамаггана в древней Войне Древних. Собирая красные кристаллические Кровавые осколки с павших Дыбогривов, Кривозуб направляет остаточную божественную энергию павшего бога-вепря, даруя могучие древние благословения тем, кто ему помогает."}},faq={{q="Кто такой Кривозуб?",a="Кривозуб — пленный свинобраз из Иглогривых, сидящий в клетке в Лагере Таурахо. Ожидая казни от рук Орды, он торгуется с искателями приключений, предлагая наставления и древние дары в обмен на уничтожение его соперников.",al={"mangletooth","who is mangletooth","caged quilboar taurajo","кривозуб","кто такой кривозуб","свинобраз в клетке таурахо"}},{q="Почему Кривозуб сидит в клетке?",a="Его взяли в плен во время столкновений Орды и свинобразов на юге Степей. Таурены и орки Лагеря Таурахо держат его в клетке в ожидании казни.",al={"why is mangletooth captive","why in cage","why taurajo prisoner","почему кривозуб в плену","почему в клетке","почему пленник таурахо"}},{q="Почему Кривозуб просит напасть на других свинобразов-Иглогривых?",a="Кривозуб понял, что его соклановцы — Нак, Каз и Лок Губитель Орков — бросили его умирать, вместо того чтобы устроить спасение. Разъяренный их предательством, он поручает путникам казнить их из чистой злобы.",al={"why attack razormane","betrayal from within lore","why kill nak kuz","почему нападать на иглогривых","предатель в наших рядах предыстория","зачем убивать нака каза"}},{q="Что такое Кровавые осколки?",a="Кровавые осколки — кристаллические минералы, образовавшиеся там, где кровь Великого Древнего Вепря Агамаггана впиталась в землю, когда он пал в Войне Древних. Свинобразы-Дыбогривы часто носят их с собой.",al={"blood shards","blood shards lore","agamaggan blood","кровавые осколки","предания о кровавых осколках","кровь агамаггана"}},{q="Что можно сделать с Кровавыми осколками у Кривозуба?",a="Если принести Кривозубу Кровавые осколки, он направит священную силу Агамаггана во временные благословения, дарующие повышенную силу, ловкость, стойкость, дух или скорость.",al={"blood shard buffs","blood shard turn in","what does mangletooth give","бонусы кровавых осколков","сдать кровавые осколки","что дает кривозуб"}},{q="Где, по словам Кривозуба, умер Агамагган?",a="Кривозуб рассказывает, что Агамагган пал в бою в Войне Древних. Из его пролитой крови выросли огромные шипастые башни, а его колоссальный череп лежит, храня пещеру на юге.",al={"agamaggan lore","where did agamaggan fall","boar god skull","предания об агамаггане","где пал агамагган","череп бога-вепря"}}},fp="11,237,19.339.0,20.389.1,25.399.0,19.213.0,29.171.0,64.201.1,22.209.0,49.182.0,42.201.0"}
P.entries["npc:mankrik"] = {n="Манкрик",s="Манкрик — скорбящий орк-воин, дислоцированный на Перекрестке в Степях. После жестокой засады свинобразов, разлучившей его с женой Ольгрой, он посвятил жизнь мести и истреблению всех щетинистых тварей, которых только сможет найти.",h="Манкрик — скорбящий орк-воин, дислоцированный на Перекрестке в Степях.",kw={"barrens","crossroads","gold road","mankrik","olgra","quilboar","thork","степи","перекресток","золотой путь","манкрик","ольгра","свинобраз","торк"},ang={["faction:Horde"]="Для путников, прибывающих на Перекресток, беда Манкрика служит суровым знакомством с неумолимой угрозой щетинистых стай свинобразов в Степях.",["race:Orc"]="Манкрик воплощает чудовищную цену освоения диких рубежей Калимдора, где семья и честь постоянно подвергаются испытаниям жестокими местными угрозами."},sec={{t="Засада в пыли",b="Во время путешествия по кустарниковым равнинам Степей Манкрик и его жена Ольгра были атакованы полчищами свинобразов в стычке у небольшого поселения тауренов. В хаосе яростного боя они потеряли друг друга, и Манкрик увидел, как Ольгра исчезает под волной клыков и оружия, оплетенного терниями. Охваченный яростью, он безрассудно сражался, пока не потерял сознание от удара. Он выжил лишь потому, что проходивший мимо таурен-друид нашел его истекающим кровью у Золотого Пути и перевязал его раны."},{t="Одержимый местью",b="Оправляясь на Перекрестке, Манкрик оказался скован горем и всепоглощающей жаждой крови. Местные предводители, такие как Торк, предупреждают, что слепая ненависть затуманивает его рассудок, и отказываются собирать официальные военные отряды, но Манкрик не желает отступать. Терзаемый неизвестностью о судьбе Ольгры, он нанимает всех готовых помочь путников Орды, чтобы они искали в Степях следы его пропавшей жены и убивали всех встречных свинобразов."}},faq={{q="Кто такой Манкрик?",a="Манкрик — орк-воин, живущий на Перекрестке в Степях. Он пережил жестокую засаду свинобразов, разлучившую его с женой, и теперь им владеет ярость и жажда отомстить за нее.",al={"mankrik lore","who is mankrik","mankrik story","манкрик предания","кто такой манкрик","история манкрика"}},{q="Что случилось с женой Манкрика?",a="Во время схватки у поселения тауренов Манкрика и Ольгру разделили огромные полчища свинобразов. Манкрика сбили с ног в суматохе боя, а Ольгра пропала в сражении.",al={"mankriks wife","where is mankriks wife","what happened to olgra","olgra fate","жена манкрика","где жена манкрика","что случилось с ольгрой","судьба ольгры"}},{q="Как Манкрик пережил битву?",a="Манкрик потерял сознание под натиском свинобразов, и его, упавшего на Золотом Пути, нашел странствующий таурен-друид, который залечил его тяжелые раны и отвел в безопасное место.",al={"how did mankrik survive","who saved mankrik","как манкрик выжил","кто спас манкрика"}},{q="Почему Торк отказывается помогать Манкрику?",a="Торк, предводитель на Перекрестке, считает, что сильная ярость и жажда мести полностью затуманили рассудок Манкрика и не дают ему действовать разумно.",al={"why wont thork help","thork and mankrik","почему торк не поможет","торк и манкрик"}}},fp="7,244,18.488.0,21.432.0,15.194.0,32.198.0,35.186.0,38.175.0"}
P.entries["npc:marcus-redpath"] = {n="Маркус Редпат",s="Маршал Маркус Редпат — высший военный начальник, защищающий город Альянса Южнобережье в Предгорьях Хилсбрада. Прослужив городу еще до Второй войны, теперь он организует патрули и контракты на награды, чтобы сдерживать окрестных огров, мурлоков и наг. Его руководство необходимо для сохранения последнего южного оплота Лордерона на побережье.",h="Маршал Маркус Редпат — высший военный начальник, защищающий город Альянса Южнобережье в Предгорьях Хилсбрада.",kw={"anduin lothar","crushridge","headman","hillsbrad","marcus redpath","marshal","southshore","terenas","андуин лотар","раздробленный хребет","староста","хилсбрад","маркус редпат","маршал","южнобережье","теренас"},ang={["faction:Alliance"]="Маршал Редпат дает защитникам Альянса важные поручения по охране Хилсбрада от наступающих огров и прибрежных опасностей.",["race:Human"]="Редпат — живая связь с первыми днями Великого Альянса: он встретил Андуина Лотара и беженцев Штормграда, когда они впервые бежали на север."},sec={{t="Страж Южнобережья",b="Маркус Редпат служит Южнобережью десятилетиями. Много лет назад, до того как Вторая война охватила север, он был старостой деревни и принимал лорда Андуина Лотара, юного мага Каздгара и тысячи изможденных беженцев, бежавших от разорения Штормграда. Осознав серьезность их положения, он отправил на север своего самого быстрого гонца, чтобы предупредить короля Теренаса Менетила II, и сыграл раннюю роль в создании Великого Альянса Лордерона. Через падение столицы и разрушительное вторжение Плети Редпат оставался на посту, перейдя от гражданского управления к должности военного маршала, чтобы охранять уцелевших жителей порта."},{t="Оборона побережья",b="После Третьей войны Южнобережье почти в одиночку противостоит враждебным силам, наступающим со всех сторон. Маршал Редпат координирует оборону в Предгорьях Хилсбрада, привлекая опытных искателей приключений, чтобы оттеснить огров Раздробленного Хребта, спускающихся из Альтерака, и зачистить опасные лагеря наг и мурлоков на побережье. Поскольку Отрекшиеся занимают север, а Мельница Таррен неподалеку сильно укреплена, бдительность Редпата — один из немногих барьеров, не дающих присутствию Альянса в регионе рухнуть полностью."}},faq={{q="Кто такой Маркус Редпат?",a="Маркус Редпат — маршал и военный командир Южнобережья в Предгорьях Хилсбрада. Во время Второй войны он был старостой города, а теперь руководит местной обороной от окрестных угроз дикой природы и враждебных соседей.",al={"marcus redpath lore","who is the marshal in southshore","marcus redpath info","маркус редпат предания","кто маршал в южнобережье","маркус редпат информация"}},{q="Какую роль он сыграл во Второй войне?",a="Когда Королевство Штормград пало перед Орочьей Ордой, беженцы во главе с Андуином Лотаром и Каздгаром высадились в Южнобережье. Редпат встретил их на берегу и сразу отправил своего гонца Виллема сообщить королю Теренасу Менетилу II в Столицу.",al={"second war marcus","did marcus redpath meet lothar","вторая война маркус","встречал ли маркус редпат лотара"}},{q="С какими угрозами он борется?",a="Редпат организует военные действия против местных хищников и захватчиков, угрожающих Южнобережью. Он объявляет награды и поручения против племени огров Раздробленного Хребта в предгорьях Альтерака, прибрежных мурлоков и набегающих наг.",al={"marcus redpath quests","what does redpath want killed","задания маркуса редпата","кого редпат хочет убить"}},{q="Родственник ли он Редпатам из Дарроушира?",a="Хотя он носит фамилию Редпат, прославленную капитаном Джозефом Редпатом из Дарроушира в Восточных Чумных землях, прямое родство официально не установлено, кроме общего происхождения из Королевства Лордерон.",al={"redpath family","is marcus related to joseph redpath","redpath relatives","семья редпат","родственник ли маркус джозефа редпата","родственники редпата"}},{q="Где найти Маркуса Редпата?",a="Маршал Редпат находится в центре Южнобережья, пристани Альянса на южном побережье Предгорий Хилсбрада.",al={"where is marcus redpath","marcus redpath location","где маркус редпат","местонахождение маркуса редпата"}}},fp="14,364,24.648.0,17.550.0,22.246.0,40.247.0,39.227.0,45.222.0,34.134.0"}
P.entries["npc:mardant-strongoak"] = {n="Мардант Крепкий Дуб",s="Мардант Крепкий Дуб — ночной эльф, наставник друидов, живущий в Альдрассиле в сердце Тельдрассила. Он помогает начинающим друидам общаться с духами природы и посвящает их в тайны Изумрудного Сна.",h="Мардант Крепкий Дуб — ночной эльф, наставник друидов, живущий в Альдрассиле в сердце Тельдрассила.",ang={["class:Druid"]="Для молодых друидов-ночных эльфов Мардант Крепкий Дуб — первый мост между обыденной жизнью и священным долгом круга Кенария.",["race:NightElf"]="Мардант, находящийся в сердце Альдрассила, воплощает преданность кальдораев гармонии с развивающейся экосистемой Тельдрассила."},sec={{t="Наставник дикой природы",b="В ветвях Альдрассила к Мардант Крепкий Дуб обращаются молодые ночные эльфы, услышавшие зов природы. Его главная задача — учить новичков открывать чувства духам природы, понимать их шепот и направлять исцеляющую магию. Для тех, кто делает первые шаги как защитник дикой природы, он часто становится первым наставником, открывающим огромную сложность и древние опасности Изумрудного Сна."}},faq={{q="Кто такой Мардант Крепкий Дуб?",a="Мардант Крепкий Дуб — ночной эльф, наставник друидов в Тенистой долине в Альдрассиле. Он обучает вновь пробудившихся друидов Тельдрассила основам общения с природой и магии.",al={"mardant strongoak lore","who is mardant","mardant aldrassil","мардант крепкий дуб предания","кто такой мардант","мардант альдрассил"}},{q="Чему он учит новых друидов?",a="Он учит новичков разбирать послания диких духов, использовать простые заклинания, такие как Лунный огонь, и целительство, а также постигать природу Изумрудного Сна.",al={"what does mardant teach","mardant abilities","druid trainer shadowglen","чему учит мардант","умения марданта","учитель друидов тенистая долина"}},{q="Где найти Марданта Крепкого Дуба?",a="Он находится в Альдрассиле или рядом с ним, в Тенистой долине — начальной долине ночных эльфов в Тельдрассиле.",al={"mardant location","where is mardant strongoak","местонахождение марданта","где мардант крепкий дуб"}},{q="Что такое Зеленый знак?",a="Зеленый знак — учебный жетон, который получают начинающие друиды-ночные эльфы в Тенистой долине; он направляет их к Марданту Крепкому Дубу для начального обучения.",al={"verdant sigil quest","sigil for mardant","задание зеленый знак","знак для марданта"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marek-ironheart"] = {n="Марек Железносерд",s="Марек Железносерд — опытный охотник-дворф из Приюта Странников на юго-востоке Лок Модана. Верный традициям дикой природы, он испытывает странников и стрелков, прежде чем принять их в ряды почетных охотников приюта.",h="Марек Железносерд — опытный охотник-дворф из Приюта Странников на юго-востоке Лок Модана.",kw={"crocolisk hunting","farstrider lodge","hunter","hunting","ironheart","loch modan","marek ironheart","охота на кроколисков","приют странников","охотник","охота","железносерд","лок модан","марек железносерд"},ang={["class:Hunter"]="Для рейнджеров и следопытов зверей Марек Железносерд воплощает суровые традиции Приюта Странников и требует от охотников доказать меткость и умение выслеживать местных зверей.",["race:Dwarf"]="Марек воплощает культуру жизни на природе, дорогую многим дворфам Каз Модана: он выбрал тихую стражу гор вместо шумных кузнечных огней Стальгорна."},sec={{t="Мастер охоты",b="Приют Странников на живописном хребте над озером служит оплотом лучших стрелков и следопытов земель дворфов. Марек Железносерд воплощает дух этого рубежа. Не впечатляясь титулами и речами, Марек требует от каждого, кто ищет уважения приюта, показать мастерство на деле в схватках с разнообразными зверями Лок Модана и доказать, что у него есть терпение и выдержка настоящего охотника дикой природы."}},faq={{q="Кто такой Марек Железносерд?",a="Марек Железносерд — охотник-дворф, живущий в Приюте Странников в Лок Модане. Он испытывает посетителей, добивающихся признания в среде следопытов и лесных жителей, собравшихся в приюте.",al={"marek ironheart","who is marek","марек железносерд","кто такой марек"}},{q="Где найти Марека Железносерда?",a="Он находится в Приюте Странников среди холмов на юго-восточном берегу Лок Модана.",al={"marek ironheart location","where is marek","местонахождение марека железносерда","где марек"}},{q="Какие задания дает Марек?",a="Марек направляет охотников выслеживать и истреблять местную дичь вокруг озера, проверяя их навыки выживания в схватках с опасными кроколисками.",al={"marek ironheart quests","marek quests","задания марека железносерда","задания марека"}},{q="Состоит ли Марек в родстве с другими известными дворфами?",a="Носитель известной дворфийской фамилии, он может быть родственником археолога Адаманта Железносерда и Иммы Железносерд, однако Марек посвящает жизнь охоте, а не раскопкам реликвий.",al={"ironheart family","marek relatives","семья железносердов","родственники марека"}}},fp="15,264,18.444.0,23.177.0,33.104.0,36.144.0,44.176.0"}
P.entries["npc:marisa-du-paige"] = {n="Мариса дю Пэж",s="Мариса дю Пэж — редкая заклинательница-разбойница из людей, обитающая в обширной сети пещер у входа в Мертвые копи на юго-западе Западного Края. Она заодно с изгоями, действующими под Луноречьем, и применяет тайную магию наряду с рабочими и разбойниками, охраняющими туннели.",h="Мариса дю Пэж — редкая заклинательница-разбойница из людей, обитающая в обширной сети пещер у входа в Мертвые...",kw={"deadmines","human","mage","marisa du'paige","marisa dupaige","moonbrook","rare","westfall","мертвые копи","человек","маг","мариса дю пэж","луноречье","редкий","западный край"},ang={["class:Mage"]="Мариса дю Пэж напоминает, что тайное обучение в королевстве не ограничивается башнями Кирин-Тора или чародейской обителью Штормграда: отступники-заклинатели охотно продают свои таланты преступным сетям.",["faction:Alliance"]="Искателям приключений Альянса, разведывающим туннели под Луноречьем, стоит остерегаться дю Пэж: неожиданный заклинатель среди толп карманников способен быстро сделать стычку смертельной."},sec={{t="Тайный талант в туннелях",b="Глубоко в извилистых пещерах, ведущих к Мертвым копям под Луноречьем, большинство защитников — грубые карманники, мятежные шахтеры и громилы. Мариса дю Пэж выделяется среди них как умелая маг-человек. Хотя большинство заклинателей королевства учатся в признанных залах Квартала магов Штормграда или служат Кирин-Тору, дю Пэж встала на сторону преступников и разбойников, прячущихся в подземных глубинах Западного Края."}},faq={{q="Кто такая Мариса дю Пэж?",a="Мариса дю Пэж — редкий маг-человек, скрывающийся во внешней системе пещер, ведущих в Мертвые копи. В отличие от обычных воров и рабочих, патрулирующих эти проходы, она защищает подземную сеть тайными заклинаниями.",al={"marisa dupaige","who is marisa","rare in deadmines cave","мариса дю пэж","кто такая мариса","редкий моб в пещере мертвых копей"}},{q="Где ее можно найти?",a="Она появляется нечасто в общей системе пещер под Луноречьем в Западном Крае, в туннелях сразу у входа в подземелье Мертвые копи.",al={"marisa du'paige location","where is marisa dupaige","marisa spawn","местонахождение марисы дю пэж","где мариса дю пэж","появление марисы"}},{q="Почему маг-человек прячется в пещерах Мертвых копей?",a="Не каждый практик тайных искусств хранит верность высоким башням Штормграда. Дезертиры, мятежники и сочувствующие простолюдины стекались к делу преступников по всему Западному Краю, давая их укреплениям под Луноречьем и сталь, и колдовство.",al={"why is she here","marisa lore","marisa dupaige faction","почему она здесь","предания марисы","фракция марисы дю пэж"}}},fp="15,299,28.436.0,23.241.0,23.162.0,50.248.0"}
P.entries["npc:marleth-barleybrew"] = {n="Марлетта Ячменовар",s="Марлетта Ячменовар — честолюбивая дворфийка-пивовар, живущая в Поселке Пивоваров. Недовольная господством клана Громоваров на местном пивном рынке, она постоянно строит планы, чтобы доказать, что пиво ее семьи лучше знаменитого Громового эля из Караноса.",h="Марлетта Ячменовар — честолюбивая дворфийка-пивовар, живущая в Поселке Пивоваров.",kw={"bitter rivals","brewnall village","dwarf brewer","kharanos","marleth barleybrew","thunder ale","thunderbrew","горькие соперники","поселок пивоваров","дворф-пивовар","каранос","марлетта ячменовар","громовой эль","громоварское"},ang={["race:Dwarf"]="Для дворфов пивоварение — искусство, тесно связанное с престижем клана, поэтому вражда Марлетты с Громоварами — вопрос яростной семейной гордости."},sec={{t="Пивное соперничество",b="В Дун Мороге к выпивке относятся так же серьезно, как к стали, а соперничество семей Ячменоваров и Громоваров легендарно. Марлетта Ячменовар возмущена почти полной монополией, которую Рагнар Громовар и его родня держат через Таверну «Громоварка» в Караносе. Уверенная, что ее ремесло ничем не хуже, она ищет хитрые способы подсунуть бочонки Ячменоваров посетителям таверн. Вместо открытого конфликта она выбирает мелкие уловки: просит случайных путников тайно подменить прославленные бочки с элем в Караносе на ее собственные."}},faq={{q="Кто такая Марлетта Ячменовар?",a="Марлетта — дворфийка-пивовар, живущая в Поселке Пивоваров на западе Дун Морога. Она представляет семью Ячменоваров и активно пытается разрушить монополию соперничающей семьи Громоваров на местном рынке выпивки.",al={"who is marleth","marleth lore","marleth barleybrew","кто такая марлетта","марлетта предания","марлетта ячменовар"}},{q="Где найти Марлетту Ячменовар?",a="Ее можно найти в Поселке Пивоваров на западе Дун Морога, возле Заледеневшего озера.",al={"marleth location","where is marleth","find marleth","где марлетта","местонахождение марлетты","найти марлетту"}},{q="Почему Марлетта хочет подменить пиво Громоваров?",a="Марлетта считает, что эль ее семьи не хуже Громового эля, а то и лучше. Поскольку Громовары господствуют в торговле в Караносе, она нанимает искателей приключений тайно заменить бочонки в таверне запасами Ячменоваров, чтобы посетители попробовали ее напиток, и принести ей образец Громового эля для изучения.",al={"why swap the beer","bitter rivals quest reason","why hate thunderbrews","зачем подменять пиво","причина задания горькие соперники","почему ненавидит громоваров"}},{q="Кто еще входит в семью Ячменоваров?",a="В ее обширный клан входят другие известные пивовары и ремесленники, такие как Мальгин, Регольд, Велларт и Йорус Ячменовар, все они преданы традиционному дворфийскому пивоварению.",al={"barleybrew family","marleth relatives","семья ячменоваров","родственники марлетты"}}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="Маррик Нуррибит",s="Маррик Нуррибит — гном, наставник магов в Старой Наковальне в Холодной долине. Он больше любит местное пиво, чем строгую педагогику: знакомит начинающих гномов-чародеев с ремеслом и при этом часто выпрашивает мелочь на выпивку.",h="Маррик Нуррибит — гном, наставник магов в Старой Наковальне в Холодной долине.",kw={"anvilmar","beer","coldridge","gnome","mage","marryk","nurribit","trainer","старая наковальня","пиво","холодная долина","гном","маг","маррик","нуррибит","наставник"},ang={["class:Mage"]="Для начинающих гномов-магов в Холодной долине Маррик — первый учитель, к которому вы обращаетесь за базовыми заклинаниями и Таинственной запиской.",["race:Gnome"]="Беженцы, нашедшие приют в Дун Мороге, знают Маррика как пример гнома-ученого, слишком хорошо привыкшего к дворфийскому таверненному гостеприимству."},sec={{t="Тайные науки и эль",b="В теплом уюте Старой Наковальни Маррик Нуррибит дает тайные наставления юным гномам, делающим первые шаги в магии. Хотя он сведущ в тайных искусствах, держится он подчеркнуто непринужденно: его часто больше занимает кружка дворфийского эля и выклянчивание мелочи у новых учеников, чем муштра сложными теоремами. Несмотря на слабости, Маррик хорошо понимает опасности за пределами Холодной долины и регулярно предупреждает начинающих заклинателей о радиоактивных ужасах и троггах павшего Гномрегана."}},faq={{q="Кто такой Маррик Нуррибит?",a="Маррик Нуррибит — гном, наставник магов в Старой Наковальне, в Холодной долине Дун Морога. Он обучает недавно прибывших гномов-магов основам тайной магии.",al={"marryk nurribit","who is marryk","anvilmar mage trainer","маррик нуррибит","кто такой маррик","наставник магов старой наковальни"}},{q="Почему Маррик все время просит денег на пиво?",a="Маррик известен тем, что гораздо больше любит местные напитки, чем профессиональную строгость. Он регулярно донимает учеников просьбами о мелочи на выпивку в таверне.",al={"marryk drinking","marryk beer","why does he ask for coins","маррик пьет","маррик пиво","почему просит монеты"}},{q="Что Маррик говорит о Гномрегане?",a="Несмотря на свободное отношение к обучению, Маррик видит настоящую опасность и неоднократно предостерегает юных магов не недооценивать угрозы в зараженных радиацией руинах Гномрегана.",al={"marryk gnomeregan","gnomeregan warning","маррик гномреган","предупреждение о гномрегане"}}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {n="Маршал Дугхан",s="Маршал Дугхан — командир отряда Армии Штормграда в Златоземье. Ему поручено защищать сердце Элвиннского леса, но его гарнизон еле справляется с растущими набегами кобольдов, гноллов и бандитов. Чтобы защитить городок на перекрестке и окрестные фермы, он сильно полагается на независимых искателей приключений.",h="Маршал Дугхан — командир отряда Армии Штормграда в Златоземье.",kw={"elwynn forest","fargodeep","goldshire","hogger","jasperlode","marshal dughan","stormwind army","westbrook garrison","элвиннский лес","рудник подземных глубин","златоземье","дробитель","яшмовая шахта","маршал дугхан","армия штормграда","гарнизон у западного ручья"},ang={["class:Warrior"]="Для бойцов-воинов Дугхан воплощает обычную дисциплину и снабженческие трудности пехотинцев Штормграда, держащих рубеж против невероятного превосходства врага.",["faction:Alliance"]="Маршал Дугхан представляет передовую административную власть Альянса в Элвиннском лесу и дает новоприбывшим рекрутам первые военные задания от имени Штормграда."},sec={{t="Командир Перекрестка",b="Маршал Дугхан стоит у таверны Гордость Льва в Златоземье и несет тяжкое бремя защиты Элвиннского леса, пока военные силы Штормграда заняты в другом месте. Окрестные леса неуклонно приходят в упадок: паразиты забили шахты, гноллы собираются вдоль берегов рек, а разбойники грабят путников на Королевском тракте. Пехотинцев у него слишком мало, и Дугхан организует оборону, посылая новобранцев усиливать форпосты и разведывать спорные земли."},{t="Угрозы на всех границах",b="Главная забота Дугхана — кобольды, заполонившие Рудник Подземных Глубин и Яшмовую шахту и угрожающие добыче руды в Златоземье. На западе гноллы Речной Лапы под предводительством пресловутого Дробителя наседают на Гарнизон у Западного ручья. На востоке Дугхану приходится разбираться с донесениями Стражника Томаса о свирепых мурлоках, убивающих патрули вдоль реки. Из-за этих наложившихся кризисов при нехватке людей маршалу постоянно нужны умелые наемники."}},faq={{q="Кто такой маршал Дугхан?",a="Маршал Дугхан — офицер Армии Штормграда в Златоземье. Он отвечает за военную безопасность центральной части Элвиннского леса и координирует оборону от местных угроз: воров, гноллов и кобольдов.",al={"dughan","marshal dughan lore","goldshire marshal","дугхан","предания маршала дугхана","маршал златоземья"}},{q="Почему Дугхан не посылает больше стражи в Гарнизон у Западного ручья или на восток?",a="Армия Штормграда растянута, и у Дугхана едва хватает стражи для порядка в самом Златоземье. Поскольку людей не хватает на гарнизоны каждой фермы и пограничного поста, он полагается на приезжих искателей приключений: они разведывают горячие точки, доставляют донесения и уничтожают опасности в округе.",al={"why no guards","goldshire garrison strength","dughan troops","почему нет стражи","сила гарнизона златоземья","войска дугхана"}},{q="Что Дугхан думает об угрозе мурлоков в Элвиннском лесу?",a="Сначала Дугхан отмахивался от предупреждений Реми Повторюха о том, что мурлоки — серьезная угроза региону. Истинную опасность он осознал, лишь когда Стражник Томас прислал печальные донесения о гибели стражников Рольфа Хартфорда и Малакая Стоуна на восточных водных путях.",al={"dughan murlocs","remy two times murloc","dughan fish men","дугхан мурлоки","реми повторюх мурлоки","дугхан рыболюди"}},{q="Как Дугхан борется с преступностью и буйными жителями?",a="Дугхан строго следит за законом, но честно предупреждает, прежде чем отправить горожан за решетку. Когда местные или путники устраивают беспорядки в Златоземье, он предупреждает, что продолжение драк приведет их прямо в Тюрьму Штормграда, а за убийство он будет охотиться на них лично.",al={"dughan crime","goldshire law","stockade threat","дугхан преступность","закон златоземья","угроза тюрьмы"}},{q="Почему Дугхана беспокоят шахты?",a="Рудник Подземных Глубин и Яшмовая шахта — важные источники золота и руды для Штормграда. Кобольды захватили оба подземных комплекса, выгнали шахтеров и грозят проложить туннели прямо под поселениями Элвиннского леса.",al={"fargodeep mine dughan","jasperlode mine dughan","kobold infestation","рудник подземных глубин дугхан","яшмовая шахта дугхан","нашествие кобольдов"}},{q="Взаимодействует ли маршал Дугхан с Западным Краем?",a="Да. Когда искатель приключений проявит себя в Элвиннском лесу, маршал Дугхан направляет его в Западный Край к Гриану Камнегриву на Сторожевой холм, где Народное ополчение отчаянно нуждается в опытной помощи против Братства Справедливости.",al={"dughan gryan","report to westfall","dughan sentinel hill","дугхан гриан","доложить в западный край","дугхан сторожевой холм"}}},fp="14,358,27.516.0,23.494.0,22.220.0,75.308.0,53.277.1,55.311.0,40.237.0,45.244.0"}
P.entries["npc:marshal-marris"] = {n="Маршал Маррис",s="Маршал Маррис — осажденный офицер, командующий городской стражей Приозерья. Он стоит у городского моста и координирует оборону от огромного вторжения орков клана Черной горы, наступающих с высот Красногорья. Поскольку армии Штормграда нет, он полагается на приезжих искателей приключений, чтобы сдержать натиск орды.",h="Маршал Маррис — осажденный офицер, командующий городской стражей Приозерья.",ang={["faction:Alliance"]="Маршал Маррис воплощает бедственное положение сельских земель Альянса, оставленных уязвимыми из-за политического паралича Штормграда и вынужденных бороться за выживание в одиночку.",["race:Human"]="Для людей королевства Маррис — стойкий осажденный страж границы, удерживающий рубеж против остатков Старой Орды."},sec={{t="Город в осаде",b="Приозерье на грани краха: с запада гноллы, с востока грозная военная мощь клана Черной горы. Маршал Маррис командует линией стражи у главного городского моста, но ресурсы истощены, а солдат катастрофически не хватает. Поскольку Королевство Штормград не шлет королевских подкреплений, Маррис несет тяжкое бремя защиты поселения от грубой силы."},{t="Разгром авангарда клана Черной горы",b="Понимая, что одной обороной Красногорье не спасти, Маррис организует решительные наступательные удары по лагерям орков. Он посылает наемников истреблять воинов клана Черной горы, уничтожать их заклинателей тьмы и в итоге выследить Тарил'зуна, грозного командира, засевшего в руинах Крепости Каменной Стражи. Его приказы нацелены на разрушение командной структуры орков до того, как всеобщий штурм сокрушит Приозерье."}},faq={{q="Кто такой маршал Маррис?",a="Маршал Маррис — старший военный командир, отвечающий за оборону Приозерья. Его можно найти на страже у западного края городского моста: он старается укрепить поселение против враждебных набегов.",al={"marris","marshal marris lore","who is the guard at lakeshire bridge","маррис","предания маршала марриса","кто стражник у моста приозерья"}},{q="Почему маршал Маррис нанимает независимых искателей приключений?",a="Королевство Штормград не прислало достаточно подкреплений в Красногорье, и местная стража Приозерья безнадежно уступает в числе. Столкнувшись с бандами гноллов и укрепившимся вторжением орков клана Черной горы, Маррис вынужден нанимать героев-наемников для важнейших ударов.",al={"why does marris need help","why no stormwind army","почему маррису нужна помощь","почему нет армии штормграда"}},{q="С какими угрозами борется маршал Маррис?",a="Хотя гноллы терзают окрестности, Маррис в первую очередь занят орками клана Черной горы, захватившими Крепость Каменной Стражи. Эти орки под командованием Тарил'зуна, усиленные темной магией, — неминуемая смертельная угроза для Приозерья и всего королевства.",al={"marris enemies","who is attacking lakeshire","враги марриса","кто нападает на приозерье"}},{q="Родственник ли маршал Маррис Натаносу Маррису?",a="У них фамилия, распространенная в человеческих королевствах Лордерона и Штормграда, но никакие официальные записи не подтверждают прямого родства между маршалом Маррисом из Красногорья и знаменитым следопытом Натаносом Маррисом с севера.",al={"is marris related to nathanos","marris family","маррис родственник натаноса","семья маррис"}},{q="Каков план Марриса по разгрому клана Черной горы?",a="Маррис ведет войну на истощение и обезглавливание. Он посылает бойцов истреблять пехоту клана Черной горы, собирать магические компоненты у их заклинателей тьмы и проникнуть в Крепость Каменной Стражи, чтобы убить их предводителя Тарил'зуна.",al={"marris plan","how to beat blackrock orcs","план марриса","как победить орков черной горы"}},{q="Где найти маршала Марриса?",a="Маррис находится в Приозерье в Красногорье, на видном месте у моста в центре города.",al={"marris location","where is marshal marris","где маррис","местонахождение марриса","где маршал маррис"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="Маршал Максвелл",s="Маршал Максвелл — высокопоставленный офицер Армии Штормграда, расквартированный в Дозоре Моргана в Пылающих степях. Ему поручено удерживать самый северный укрепленный хребет Альянса над Красногорьем от клана Черной горы и дворфов Черного Железа, и он направляет разведывательные вылазки во враждебные скалы внизу. Он также играет важную роль в координации усилий по выяснению судьбы своего плененного товарища, маршала Реджинальда Винздора.",h="Маршал Максвелл — высокопоставленный офицер Армии Штормграда, расквартированный в Дозоре Моргана в Пылающих...",kw={"blackrock depths","burning steppes","general drakkisath","marshal maxwell","maxwell","morgans vigil","reginald windsor","stormwind army","глубины черной горы","пылающие степи","генерал драккисат","маршал максвелл","максвелл","дозор моргана","реджинальд винздор","армия штормграда"},ang={["class:Warrior"]="Максвелл воплощает дисциплину штормградской армии на передовой: он твердо стоит среди вулканического пепла и координирует глубокие удары в тылу врага.",["faction:Alliance"]="Для героев Альянса, идущих сквозь палящий зной Пылающих степей, маршал Максвелл олицетворяет власть Штормграда и острие кампании против Черной горы."},sec={{t="Одинокий пост в степях",b="Дозор Моргана — ненадежный форпост на южной окраине Пылающих степей, обращенный к пустоши, заваленной пеплом и населенной драконидами и орками клана Черной горы. Здесь стоит отряд штормградских войск под командованием маршала Максвелла, и для путников, отваживающихся идти по огненным ущельям, это редкая дружелюбная картина. Из этого скалистого оплота он руководит оборонительными маневрами, чтобы удержать враждебные силы горы, пока они не хлынули на юг, в Красногорье и Элвиннский лес."},{t="Раскрыть правду в горе",b="Помимо обычного сдерживания врага Максвелл — главный полевой связной в операциях, нацеленных в самое сердце Вершины Черной горы и Глубин Черной горы. Когда появляются слухи, что плененный маршал Реджинальд Винздор, возможно, еще жив в темницах дворфов Черного Железа, именно Максвелл получает разведданные, разбирает донесения и направляет доверенных героев на спасение. Его форпост — важное звено между пограничной разведкой и политическими волнениями, назревающими у ворот Штормграда."}},faq={{q="Кто такой маршал Максвелл?",a="Маршал Максвелл — командир Армии Штормграда, расквартированный в Дозоре Моргана в Пылающих степях. Он возглавляет местные силы Альянса, наблюдающие за орками клана Черной горы, черными драконами и дворфами Черного Железа.",al={"marshal maxwell lore","who is maxwell","маршал максвелл предания","кто такой максвелл"}},{q="Почему маршал Максвелл расквартирован в Дозоре Моргана?",a="Дозор Моргана — передовой лагерь Альянса на границе Пылающих степей. Максвелл направлен сюда, чтобы охранять горный перевал, ведущий вниз в Красногорье, и следить за угрозами, исходящими из Черной горы.",al={"why is maxwell in burning steppes","morgan's vigil commander","почему максвелл в пылающих степях","командир дозора моргана"}},{q="Как Максвелл связан с маршалом Винздором?",a="Максвелл — ключевой командир, помогающий в поисках маршала Реджинальда Винздора, которого захватили и утащили в Глубины Черной горы. Максвелл помогает координировать спасательные усилия и передает в Штормград важные сведения о Винздоре.",al={"maxwell and windsor","abandoned hope quest lore","максвелл и винздор","предания задания потерянная надежда"}},{q="Помогает ли маршал Максвелл организовывать удары по Вершине Черной горы?",a="Да. Максвелл направляет опытных героев Альянса на уничтожение верхушки клана Черной горы, отдавая приказы против генерала Драккисата и его сил, удерживающих высоты Вершины Черной горы.",al={"maxwell drakkisath","maxwell's mission","максвелл драккисат","задание максвелла"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="Маршал Макбрайд",s="Маршал Дуглас Макбрайд — командир штормградского гарнизона в Аббатстве Североземья. Ему поручена оборона Долины Североземья, и он направляет только что прибывших новобранцев против растущего нашествия кобольдов, угрожающего местным фермам и шахтам. Он главный военный начальник для новичков, начинающих службу королевству Штормград.",h="Маршал Дуглас Макбрайд — командир штормградского гарнизона в Аббатстве Североземья.",kw={"douglas mcbride","echo ridge","elwynn","kobold","marshal mcbride","northshire","northshire abbey","дуглас макбрайд","рудник горного эха","элвиннский лес","кобольд","маршал макбрайд","североземье","аббатство североземья"},ang={["class:Warrior"]="Макбрайд активно ищет крепких бойцов для службы королевству и полагается на воинов передовой, чтобы очистить туннели Рудника Горного Эха.",["faction:Alliance"]="Макбрайд представляет начальный рубеж Великого Альянса в сердце земель людей, принимая новобранцев на службу Короне.",["race:Human"]="Для людей, начинающих свои приключения в Североземье, маршал Макбрайд — первый представитель королевской власти Штормграда, которого они встречают."},sec={{t="Командир Североземья",b="Маршал Дуглас Макбрайд, стоящий прямо у Аббатства Североземья, представляет прямую власть Армии Штормграда в этой тихой долине. Хотя само аббатство — оплот веры и учености, нарастающие волнения в королевстве истончили военные гарнизоны. Макбрайду приходится поддерживать мир и охранять запасы продовольствия и ресурсов долины всего с горсткой присяжных стражей и притоком зеленых новобранцев, ищущих обучения у наставников аббатства."},{t="Нашествие кобольдов",b="Главная головная боль Макбрайда — внезапная агрессия местной нечисти. Кобольды, прежде всего лишь досаждавшие, захватили окрестные леса и Рудник Горного Эха — важный местный ресурс. Не имея регулярных солдат для их изгнания, Макбрайд собирает паладинов, воинов и других новичков, чтобы отбросить роющих норы вредителей и выяснить масштабы нашествия, пока долина не оказалась полностью отрезана."}},faq={{q="Кто такой маршал Макбрайд?",a="Маршал Дуглас Макбрайд — офицер Армии Штормграда, командир гарнизона в Аббатстве Североземья. Он отвечает за оборону Долины Североземья и направляет новобранцев на службу.",al={"marshal mcbride","who is mcbride","northshire commander","маршал макбрайд","кто такой макбрайд","командир североземья"}},{q="Почему Макбрайд заставляет новобранцев сражаться с кобольдами?",a="Кобольды заполонили леса вокруг Североземья и захватили Рудник Горного Эха. Поскольку войск Штормграда не хватает, Макбрайд полагается на недавно прибывших искателей приключений, чтобы истребить вредителей и обезопасить округу.",al={"why kill kobolds","kobold problem","echo ridge problem","зачем убивать кобольдов","проблема с кобольдами","проблема рудника горного эха"}},{q="Куда Макбрайд отправляет новобранцев дальше?",a="Когда новобранец доказал свои способности, справившись с угрозами в Долине Североземья, Макбрайд направляет его по южной дороге в Златоземье на помощь маршалу Дугхану.",al={"where do i go after mcbride","after northshire","next town","куда идти после макбрайда","после североземья","следующий город"}},{q="Что такое Рудник Горного Эха?",a="Рудник Горного Эха — богатая минералами пещера на северной окраине Долины Североземья. Недавно ее заполонили роющие туннели кобольды, и Макбрайд приказал провести несколько операций по ее возвращению.",al={"echo ridge","the mine in northshire","рудник горного эха","шахта в североземье"}},{q="Командует ли Макбрайд самим аббатством?",a="Нет. Аббатство Североземья содержится святыми орденами и жрецами Света. Макбрайд руководит военным гарнизоном, которому поручена оборона аббатства и окрестной долины.",al={"does mcbride lead northshire abbey","who is in charge of the abbey","руководит ли макбрайд аббатством североземья","кто главный в аббатстве"}},{q="Беспокоят ли Макбрайда угрозы помимо кобольдов?",a="Хотя кобольды — самая насущная досада, Макбрайд следит за более глубокой нестабильностью. Бандиты и разбойники кружат на окраинах долины, что говорит о более широких беспорядках, назревающих в Элвиннском лесу.",al={"defias in northshire","is northshire safe","отступники в североземье","безопасно ли в североземье"}}},fp="15,363,23.465.0,20.415.0,23.204.0,45.217.0,38.181.0,24.203.0,38.178.0,50.197.0"}
P.entries["npc:martie-jainrose"] = {n="Марти Джанроз",s="Марти Джанроз — местная травница Приозерья, ухаживающая за своим садом на берегу Озера Безмолвия в Красногорье. Помимо выращивания лекарственных трав и цветов для осажденного городка, ей приходится бороться с дикими зверями, вытаптывающими ее грядки, и она тайно питает нежные чувства к Стражнику Паркеру.",h="Марти Джанроз — местная травница Приозерья, ухаживающая за своим садом на берегу Озера Безмолвия в...",kw={"bellygrub","daffodils","guard parker","herbalist","lakeshire","martie jainrose","redridge","брюхорыл","нарциссы","стражник паркер","травница","приозерье","марти джанроз","красногорье"},ang={["faction:Alliance"]="Стойкость Марти в Приозерье отражает жизнестойкость жителей Красногорья, стремящихся сохранить обычный домашний уклад, даже когда Штормград оставляет городок почти на произвол судьбы.",["profession:Herbalism"]="Для практикующих травников, путешествующих по Красногорью, Марти — близкая по духу душа: она ухаживает за хрупкими растениями вопреки жестоким набегам диких кабанов и вторгающихся врагов."},sec={{t="Сад у озера",b="Марти Джанроз живет в Приозерье и усердно трудится как местная травница поселения. Даже когда орки клана Черной горы, гноллы и местные разбойники угрожают региону, Марти заботится о том, чтобы город был обеспечен свежими травами и цветочными букетами. Ее ежедневные труды часто нарушают местные животные — прежде всего чудовищный кабан Брюхорыл, который то и дело разоряет ее любимые грядки. Помимо занятий травничеством, Марти, как известно, нежно привязана к Стражнику Паркеру и порой посылает ему букеты собранных вручную нарциссов, чтобы скрасить его бдительную службу в городе."}},faq={{q="Кто такая Марти Джанроз?",a="Марти Джанроз — травница-человек, живущая в Приозерье в Красногорье. Она ухаживает за садом у Озера Безмолвия, выращивает растения и готовит травяные снадобья для местных жителей.",al={"martie jainrose","who is martie","lakeshire herbalist","марти джанроз","кто такая марти","травница приозерья"}},{q="Какие неприятности у Марти с местными животными?",a="Огромный и на редкость упрямый дикий кабан по имени Брюхорыл повадился грабить ее грядки, вытаптывая нежные посадки и поедая травы, прежде чем она успевает их собрать.",al={"martie boar problem","bellygrub garden","who is destroying her garden","проблема марти с кабаном","брюхорыл сад","кто разоряет ее сад"}},{q="Кто нравится Марти в Приозерье?",a="Марти питает романтические чувства к Стражнику Паркеру, одному из городских стражников, несущих службу неподалеку. Она часто собирает букеты свежих нарциссов, чтобы их доставили ему на пост.",al={"martie crush","martie guard parker","delivering daffodils romance","влюбленность марти","марти стражник паркер","доставка нарциссов романтика"}}},fp="15,293,20.588.0,23.202.0,54.182.0,35.184.0"}
P.entries["npc:marukai"] = {n="Марукайя",s="Марукайя — тролльша джунглей из племени Черного Копья, расквартированная в форте Зорам'гар на туманном побережье северо-запада Ясеневого леса. Преданная удержанию этого отдаленного плацдарма Орды, она координирует усилия по истреблению наступающих нага Гневного Хвоста, которые угрожают форпосту.",h="Марукайя — тролльша джунглей из племени Черного Копья, расквартированная в форте Зорам'гар на туманном...",kw={"ashenvale","darkspear","jungle troll","marukai","naga","wrathtail","zoram strand","zoram'gar outpost","ясеневый лес","черное копье","тролль джунглей","марукайя","нага","гневный хвост","зорамское взморье","форт зорам'гар"},ang={["faction:Horde"]="Марукайя удерживает один из самых ненадежных прибрежных лагерей Орды на землях ночных эльфов и полагается на союзных героев, чтобы местные нага не захватили их позицию.",["race:Troll"]="Вдали от теплого эха Деревни Сен'джин Марукайя олицетворяет стойкость племени Черного Копья, создающего укрепленные плацдармы для Орды по всему Калимдору."},sec={{t="Оборона взморья",b="Форт Зорам'гар одиноко стоит на северной окраине Зорамского взморья, окруженный древними руинами, враждебными землями ночных эльфов и неспокойным морем. Пока нага Гневного Хвоста массами выходят из воды и древних эльфийских руин, чтобы захватить берег, Марукайя старается не дать лагерю пасть. Она направляет героев Орды отбрасывать змеелюдей обратно в прибой и собирать их головы, чтобы форпост оставался пригодной прибрежной крепостью."}},faq={{q="Кто такая Марукайя?",a="Марукайя — тролльша джунглей, выдающая задания и защищающая форт Зорам'гар, отдаленный прибрежный лагерь Орды на северо-западном побережье Ясеневого леса.",al={"marukai lore","who is marukai","marukai npc","марукайя предания","кто такая марукайя","марукайя персонаж"}},{q="Почему Марукайя сражается с нага?",a="Нага Гневного Хвоста заполонили соседнее Зорамское взморье и окрестные руины. Чтобы обезопасить границы форпоста и обеспечить выживание Орды на побережье, Марукайя нанимает искателей приключений, чтобы они сокращали число нага, выслеживая их напрямую.",al={"why kill naga","marukai naga quest","zoram strand naga","зачем убивать нага","задание марукайи про нага","нага зорамского взморья"}},{q="Где находится Марукайя?",a="Ее можно найти рядом с сородичами в форте Зорам'гар, у начала Зорамского взморья на северо-западе Ясеневого леса, к югу от затопленных руин Непроглядной Пучины.",al={"where is marukai","marukai location","find marukai","где марукайя","местонахождение марукайи","найти марукайю"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="Мастер аптекарь Фаранелл",s="Мастер аптекарь Фаранелл — глава Королевского фармацевтического общества, находящийся в глубинах Апотекариума в Подгороде. При жизни он был уважаемым ученым Даларана, а в нежизни руководит поисками разрушительной Новой чумы, которая уничтожит и Плеть, и живых.",h="Мастер аптекарь Фаранелл — глава Королевского фармацевтического общества, находящийся в глубинах Апотекариума...",kw={"abomination","apothecarium","blight","faranell","master apothecary faranell","new plague","renferrel","royal apothecary society","sylvanas","undercity","тварь","апотекариум","порча","фаранелл","мастер аптекарь фаранелл","новая чума","ренферрель","королевское фармацевтическое общество","сильвана","подгород"},ang={["faction:Horde"]="Хотя союзников — орков, троллей и тауренов — могут смущать зеленая слизь и подопытные в клетках Апотекариума, исследования Фаранелла терпят как необходимое оружие против общей угрозы Плети.",["profession:Herbalism"]="Чаны Фаранелла поглощают бесконечное количество редких растений, мхов и грибных экстрактов — мрачный пример науки о растениях, обращенной в оружие разрушения.",["race:Undead"]="Для Отрекшихся Фаранелл — авангард биологического суверенитета: он трудится во тьме, чтобы у их народа было оружие, способное сокрушить Короля-лича."},sec={{t="Разум, расстроенный смертью",b="До Третьей войны Фаранелл был почтенным алхимиком и десятилетиями учился бок о бок с учеными магами Даларана. Живя смертным, он искал лекарства, снадобья и зелья для улучшения здоровья. Когда чума Плети отняла у него жизнь и он восстал свободным Отрекшимся, его прежняя научная любознательность переродилась в жестокость. Сохранив энциклопедический ум, он променял целебные мази на губительные реагенты и вскоре стал одним из самых ценных исследователей королевы Сильваны Ветрокрылой в недрах павшей столицы Лордерона."},{t="Мастер Апотекариума",b="Работая в зловонных лабораториях Апотекариума, Фаранелл координирует разбросанные по миру исследования Королевского фармацевтического общества. Он надзирает за созданием неуклюжих тварей и руководит подчиненными аптекарями, размещенными по всему Лордерону и за его пределами. Каждая партия странного яда, зараженной крови и проклятых растений, собранных полевыми исследователями на разных континентах, в конце концов проходит через его чаны для перегонки и очистки."},{t="Создание Новой чумы",b="Единственная одержимость Фаранелла — исполнить повеление Темной Госпожи и создать Новую чуму. Чтобы сварить заразу, способную уничтожить Артаса и его безмозглые легионы Плети, Фаранелл организует масштабный сбор реагентов. Он посылает искателей приключений за исследовательскими записями своего погибшего коллеги, аптекаря Берара, из Деревни Погребальных Костров, добывает гуано летучих мышей в глубоких логовах Лабиринтов Иглошкурых и испытывает кислотные коллоиды на органах фанатиков из Монастыря Алого ордена."}},faq={{q="Кто такой Мастер аптекарь Фаранелл?",a="Фаранелл — глава Королевского фармацевтического общества, алхимической гильдии, служащей леди Сильване Ветрокрылой в Подгороде. Он надзирает за всеми исследованиями токсинов, сшитых тварей и разработкой Новой чумы.",al={"who is faranell","faranell lore","apothecary leader","кто такой фаранелл","фаранелл предания","глава аптекарей"}},{q="Где можно найти Фаранелла?",a="Он обитает в Апотекариуме — алхимическом квартале в западной части Подгорода, среди кипящих котлов, клеток для опытов и подчиненных ему аптекарей.",al={"faranell location","where is master apothecary faranell","find faranell","местонахождение фаранелла","где мастер аптекарь фаранелл","найти фаранелла"}},{q="Кем был Фаранелл до смерти?",a="При жизни Фаранелл был признанным алхимиком и врачом, учившимся у чародеев Даларана. Он провел свои живые годы, изобретая средства от болезней, пока чума не убила его и не обратила его любознательность к смертоносным токсинам.",al={"faranell history","was faranell in dalaran","faranell mortal life","история фаранелла","был ли фаранелл в даларане","жизнь фаранелла при жизни"}},{q="Что пытается создать Королевское фармацевтическое общество?",a="По указанию королевы Сильваны общество создает Новую чуму. Его цель — выковать оружие, достаточно губительное, чтобы уничтожить Плеть и отомстить Королю-личу, а также защитить Отрекшихся от смертных врагов.",al={"what is the new plague","what are apothecaries making","apothecary goals","что такое новая чума","что создают аптекари","цели аптекарей"}},{q="Почему Фаранелл посылает искателей приключений в Деревню Погребальных Костров?",a="Он ищет исследовательский дневник своего бывшего коллеги, аптекаря Берара, который сошел с ума и поддался проклятию воргенов в Погребальных Кострах. Полевые записи Берара содержат важные данные о ядовитых веществах, нужных для доработки опытов с чумой.",al={"recipe for death quest faranell","why pyrewood village","apothecary berard journal","задание рецепт смерти фаранелл","почему деревня погребальных костров","дневник аптекаря берара"}},{q="Зачем ему реагенты из Лабиринтов Иглошкурых и Монастыря Алого ордена?",a="Фаранелл проверяет, как взаимодействуют противоположные нестабильные соединения. Он использует гуано, собранное в логовах свинобразов Иглошкурых, вместе со свежедобытыми сердцами фанатиков Алого ордена, чтобы испытывать кислотные коллоиды и биологическое заражение.",al={"kraul guano faranell","hearts of zeal","scarlet monastery hearts","гуано краул фаранелл","сердца фанатиков","сердца монастыря алого ордена"}}},fp="26,293,24.557.0,30.456.0,23.496.1,34.230.0,28.184.0,46.234.0,54.242.0,55.235.0,72.238.0"}
P.entries["npc:master-apothecary-lydon"] = {n="Главный аптекарь Лидон",s="Аптекарь Лидон — мрачный исследователь Королевского фармацевтического общества в Мельнице Таррен. Хронически подавленный и смертельно скучающий, он радуется лишь изготовлению смертоносных составов и страданиям живых. Он возглавляет разработку сильных новых ядов, чтобы закрепить Хилсбрад за Отрекшимися и продвинуть Новую чуму Сильваны.",h="Аптекарь Лидон — мрачный исследователь Королевского фармацевтического общества в Мельнице Таррен.",kw={"apothecary","elixir of agony","faranell","hillsbrad","lydon","royal apothecary society","tarren mill","umpi","аптекарь","эликсир агонии","фаранелл","хилсбрад","лидон","королевское фармацевтическое общество","мельница таррен","ампи"},ang={["faction:Alliance"]="Для людей Южнобережья Лидон — жуткое чудовище, которое варит смертельные болезни и без разбора испытывает их на пленных фермерах Хилсбрада и диких животных.",["profession:Herbalism"]="Мастерская Лидона набита реагентами, котлами и гниющими растениями — наглядный пример того, как Общество аптекарей обращает в оружие традиционные искусства собирательства.",["race:Undead"]="Лидон воплощает единственную цель Королевского фармацевтического общества: создать Новую чуму, чтобы обеспечить будущее Отрекшихся и истребить живых."},sec={{t="Затворник Мельницы Таррен",b="Аптекарь Лидон, работающий в часовне, превращенной в лабораторию в Мельнице Таррен, воплощает холодную расчетливость Королевского фармацевтического общества. Его терзает глубокая вялая меланхолия; цветущие цветы и свежий воздух Предгорий Хилсбрада вызывают у него отвращение. Единственное, что рассеивает его вечный мрак, — искусство смертоведения. Оставшись без дела, он коротает время, отравляя, вскрывая и вновь поднимая своего несчастного питомца — лягушку Ампи, в ожидании новых реагентов."},{t="Составы агонии",b="Работая вместе с Мастером аптекарем Фаранеллом в Подгороде, Лидон проводит обширные полевые опыты по всему Хилсбраду. Его работа переходит от Эликсира Страдания к смертоносному Эликсиру агонии. Чтобы проверить их силу, Лидон посылает искателей приключений испытывать зелья на местных мишенях: от безобидных диких и домашних животных до плененных человеческих фермеров. Его высшая верность принадлежит Темной Госпоже; он мечтает о дне, когда готовая Новая чума очистит мир живых."},{t="Яд лоа",b="Помимо обычных составов, любознательность Лидона распространяется на тайные яды. Когда в округе появляются загадочные флаконы с ядом, он советуется с троллями-мистиками, такими как Мастер Гадрин, чтобы выяснить их происхождение. Расследование приводит к следу, ведущему прямо к богине пауков Шадре во Внутренних землях. Добытый первобытный яд отправляют прямо в Апотекариум в Подгороде, чтобы продвинуть чумную программу Отрекшихся."}},faq={{q="Кто такой аптекарь Лидон?",a="Это алхимик Королевского фармацевтического общества, работающий в Мельнице Таррен в Предгорьях Хилсбрада. Он руководит разработкой различных опытных чум и токсинов от имени леди Сильваны Ветрокрылой.",al={"who is lydon","lydon tarren mill","apothecary lydon lore","кто такой лидон","лидон мельница таррен","предания аптекаря лидона"}},{q="Почему Лидон так подавлен?",a="Лидон страдает от глубокой меланхолии, и природная красота и свежий воздух Хилсбрада внушают ему отвращение. Поднимают ему настроение лишь жестокие опыты, страдания живых и запах алхимических бальзамирующих жидкостей.",al={"why is he sad","lydon depression","why is lydon gloomy","почему он грустит","депрессия лидона","почему лидон мрачный"}},{q="Кто такая Ампи?",a="Ампи — лягушка, которую Лидон держит в мастерской и иронично зовет своей помощницей. На деле он спасается от сильной скуки, раз за разом отравляя, убивая и вновь поднимая беспомощное земноводное.",al={"lydon frog","who is the frog","umpi lore","лягушка лидона","кто такая лягушка","предания об ампи"}},{q="Что такое Эликсир агонии?",a="Это сильный опытный яд, который Лидон варит из ингредиентов со всех Восточных королевств, включая обереги Синдиката, дворфийский эль и яд ползунов. В конце концов Лидон испытывает его на пленных людях в Хилсбраде, чтобы убедиться в его смертоносности.",al={"elixir of agony quest","what is elixir of agony","lydon elixir","задание эликсир агонии","что такое эликсир агонии","эликсир лидона"}},{q="Как Лидон стал Отрекшимся?",a="Он был молодым человеком-алхимиком в Лордероне и пал жертвой Плети во время Третьей войны. Когда Сильвана освободилась от власти Короля-лича, Лидон примкнул к ней, полностью отбросив прежнюю человеческую личность и посвятив свою нежизнь Темной Госпоже.",al={"lydon past","was lydon human","lydon third war","прошлое лидона","был ли лидон человеком","лидон третья война"}},{q="Что Лидон отправляет в Подгород?",a="Обнаружив во Внутренних землях древние сосуды с ядом и содействуя падению паучьего бога троллей Шадры, Лидон собирает ее концентрированный божественный яд и отправляет его прямо Мастеру аптекарю Фаранеллу, чтобы усилить исследования чумы общества.",al={"lydon undercity venom","shadra venom quest","яд лидона подгород","задание яд шадры"}}},fp="23,354,26.508.0,20.517.1,16.465.1,24.213.0,26.245.0,12.207.0,28.256.1,30.254.0,38.260.1"}
P.entries["npc:master-gadrin"] = {n="Мастер Гадрин",s="Мастер Гадрин — пожилой тролль джунглей и почтенный знахарь племени Черного Копья, ныне живущий в Деревне Сен'джин. Некогда он обучал жрецов и магов племени вместе с отступником-знахарем Залазаном, а теперь координирует усилия по помощи своему изгнанному народу и снятию темного проклятия с их похищенного дома на Островах Эха.",h="Мастер Гадрин — пожилой тролль джунглей и почтенный знахарь племени Черного Копья, ныне живущий в Деревне...",kw={"darkspear","durotar","echo isles","gadrin","master gadrin","minshina","sen'jin village","vol'jin","witch doctor","zalazane","черное копье","дуротар","острова эха","гадрин","мастер гадрин","миншина","деревня сен'джин","вол'джин","знахарь","залазан"},ang={["class:Mage"]="Гадрин совершил прорыв, обучив троллей Черного Копья тайным искусствам после Третьей войны и доказав, что магия троллей может выйти далеко за рамки простых ритуалов.",["class:Priest"]="Как старейшина, обучавший жрецов племени Черного Копья общению с духами и лоа, Гадрин воплощает традиции тени и веры троллей джунглей.",["faction:Horde"]="Мастер Гадрин — один из самых доверенных советников Вол'джина: он бдительно следит за побережьем Дуротара и предупреждает Колючий Холм, когда темные культы угрожают молодой стране Дуротар.",["race:Troll"]="Для троллей Черного Копья Мастер Гадрин — живая связь с вашим родным домом и традициями Сен'джина. Он на протяжении поколений направлял духовное руководство вашего племени и по-отечески скорбит о трагедии Островов Эха."},sec={{t="Наставник племени Черного Копья",b="Задолго до прибытия племени Черного Копья в Калимдор Мастер Гадрин служил знахарем своего племени на родовых островах Южных морей, где направлял мистическое обучение поколений троллей Черного Копья."},{t="Предательство Залазана",b="Когда племя Черного Копья поселилось на Островах Эха вместе с Ордой, Гадрин и молодой знахарь Залазан вместе руководили мистическим обучением жрецов и магов племени. К несчастью, Залазан поддался безумию, опьяненный темными силами вуду, которыми хотел управлять. Отступник поработил разумы соплеменников и изгнал Вол'джина и неразвращенных троллей Черного Копья на материк Дуротара. Теперь, живя в Деревне Сен'джин, Гадрин несет личную скорбь от того, что бывший товарищ стал тираном и чудовищем, и неустанно трудится, упокаивая убитых соплеменников и стремясь положить конец власти Залазана."},{t="Хранитель древних преданий",b="Помимо кризиса на Островах Эха, Гадрин — один из величайших живых знатоков спиритизма троллей и преданий о лоа в Орде. Ученые, шаманы и даже Королевское фармацевтическое общество ищут его совета в тайнах магии и алхимии. Когда странные угрозы вроде Пылающего Клинка подбираются к Дуротару или далеким исследователям нужны забытые ритуалы — например, расшифровка древних табличек в Зул'Фарраке для призыва паучьей лоа Шадры, — именно у Гадрина есть знания, чтобы создать нужные обряды связывания."}},faq={{q="Кто такой Мастер Гадрин?",a="Мастер Гадрин — знахарь и старейший духовный лидер троллей племени Черного Копья. Он живет в Деревне Сен'джин на побережье Дуротара и служит старшим советником вождя Вол'джина.",al={"master gadrin lore","who is gadrin","gadrin npc","предания мастера гадрина","кто такой гадрин","гадрин персонаж"}},{q="Что связывает Гадрина с Залазаном?",a="На Островах Эха Гадрин и молодой знахарь Залазан вместе руководили мистическим обучением жрецов и магов племени Черного Копья, но Гадрину пришлось с ужасом наблюдать, как Залазан пал под властью темной магии, обезумел и изгнал племя Черного Копья с родного острова.",al={"gadrin and zalazane","how does gadrin know zalazane","zalazane mentor","гадрин и залазан","откуда гадрин знает залазана","наставник залазана"}},{q="Почему Гадрин остается в Деревне Сен'джин?",a="Когда проклятие Залазана изгнало племя Черного Копья с Островов Эха, выжившие основали Деревню Сен'джин на южном побережье Дуротара как убежище. Гадрин остается в деревне, чтобы наставлять беженцев, следить за местными угрозами и направлять удары по силам Залазана.",al={"why is gadrin here","what is gadrin doing in senjin village","почему гадрин здесь","что делает гадрин в деревне сен'джин"}},{q="Кто такой Миншина?",a="Миншина был братом Мастера Гадрина. Он погиб во время смуты на Островах Эха, и его неупокоенный дух стал звать Гадрина во снах. Гадрин просит доверенных искателей приключений вернуть череп брата, чтобы его душа наконец обрела покой.",al={"minshina brother","minshinas skull quest lore","who was minshina","брат миншина","задание череп миншины","кто был миншина"}},{q="Помогает ли Гадрин против культа Пылающего Клинка?",a="Да. Получив от Зуриты Востроглазой весть о проникновении Пылающего Клинка в Долину Испытаний, Гадрин следит за присутствием культа около Деревни Сен'джин. Видя более широкую угрозу для Дуротара, он отправляет новобранцев на север с докладом к Оргнилу Душегрызу в Колючий Холм.",al={"burning blade durotar gadrin","orgnil soulscar gadrin","пылающий клинок дуротар гадрин","оргнил душегрыз гадрин"}},{q="Что Гадрин знает о лоа Шадре?",a="Гадрин — знаток древней теологии троллей. Когда Отрекшийся аптекарь Лидон ищет сильный яд, используемый троллями Сухокожих из Внутренних земель, Гадрин определяет его как дар паучьей лоа Шадры и направляет искателей приключений в Зул'Фаррак прочесть табличку с ее истинным именем, нужным ему для написания заклинания призыва.",al={"shadra spider loa gadrin","gadrin spider god","шадра паучья лоа гадрин","гадрин паучий бог"}}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {n="Мастер Ворнал",s="Мастер Ворнал — пожилой тролль джунглей из племени Черного Копья, живущий в деревне Сен'джин на южном побережье Дуротара. Несмотря на преклонный возраст и обширные познания в алхимических зельях, он упрямо отказывается брать учеников.",h="Мастер Ворнал — пожилой тролль джунглей из племени Черного Копья, живущий в деревне Сен'джин на южном...",kw={"a solvent spirit","darkspear","durotar","master vornal","sen'jin village","troll","vornal","растворитель","черное копье","дуротар","мастер ворнал","деревня сен'джин","тролль","ворнал"},ang={["profession:Herbalism"]="Те, кто сведущ в сборе растений, оценят острый глаз Ворнала на редкие катализаторы и резкие природные реагенты, необходимые для его растворителей.",["race:Troll"]="Для троллей Черного Копья мастер Ворнал олицетворяет упрямых старых мастеров, которые помогли основать деревню Сен'джин после того, как племя бежало с родного острова."},sec={{t="Упрямый зельевар из Сен'джина",b="Мастер Ворнал — неотъемлемая часть деревни Сен'джин, известный тем, что варит крепкие настои и напитки для собратьев-троллей из племени Черного Копья. Хотя возраст заметно берет свое, Ворнал остается крайне независимым и упрямо отказывается обучать учеников: он предпочитает смешивать свои лекарства и нестабильные смеси исключительно собственными руками."},{t="Растворитель",b="Ворнал время от времени поручает юным авантюристам собирать резкие или необычные ингредиенты в окрестных землях, например сильнодействующие материалы для растворителей и смесей. Тех, кто ему помогает, он готов вознаградить, но свои точные методы и рецепты держит в тайне и считает свое ремесло занятием для одиночки."}},faq={{q="Кто такой мастер Ворнал?",a="Мастер Ворнал — пожилой тролль джунглей из племени Черного Копья, живущий в деревне Сен'джин. Он варит крепкие напитки и лекарства для племени, но настаивает на том, чтобы работать без ученика.",al={"master vornal","vornal","sen'jin master vornal","who is vornal","мастер ворнал","ворнал","мастер ворнал сен'джин","кто такой ворнал"}},{q="Где найти мастера Ворнала?",a="Его можно найти среди хижин деревни Сен'джин, которая расположена на южном побережье Дуротара, к северу от Островов Эха.",al={"vornal location","where is master vornal","find master vornal","где ворнал","где мастер ворнал","найти мастера ворнала","местонахождение ворнала"}},{q="Почему мастер Ворнал отказывается брать учеников?",a="Ворнал известен своим упрямством. Несмотря на преклонный возраст и нужду общины в его ремесле, он предпочитает готовить свои смеси в одиночку, а не передавать секреты строптивым новичкам.",al={"vornal apprentice","why no apprentice","vornal students","ученик ворнала","почему нет ученика","ученики ворнала"}},{q="Какие задания он дает искателям приключений?",a="Ворнал отправляет странников собирать сырье по всему краю для своих растворяющих смесей: он полагается на путников в добыче материалов, а сам процесс варки оставляет только за собой.",al={"master vornal quest","a solvent spirit","vornal quest","задание мастера ворнала","растворитель","задание ворнала"}}},fp="13,247,30.334.0,16.319.0,21.176.0,31.134.0,50.193.0,37.181.0"}
P.entries["npc:mastok-wrilehiss"] = {n="Масток Райльшип",s="Масток Райльшип — офицер-орк, расквартированный на Заставе Расщепленного Дерева в восточной части Ясеневого леса. Как важный координатор обороны Орды в этом спорном лесу, он руководит разведчиками и воинами, чтобы защищать ближние границы и справляться с угрозами порченых элементалей. Его присутствие жизненно важно для удержания шаткого плацдарма Орды среди постоянной враждебности ночных эльфов.",h="Масток Райльшип — офицер-орк, расквартированный на Заставе Расщепленного Дерева в восточной части Ясеневого...",kw={"ashenvale","earthen ring","mastok","orc","splintertree","stonetalon","wrilehiss","ясеневый лес","служители земли","масток","орк","застава расщепленного дерева","когтистые горы","райльшип"},ang={["class:Shaman"]="Беспокойство Мастока о порченых элементалях в лесу часто заставляет авантюристов искать совета у Служителей Земли в форте Зорам'гар.",["faction:Alliance"]="Масток Райльшип олицетворяет прочно закрепившееся военное присутствие орков в Ясеневом лесу: он защищает укрепленное поселение Расщепленного Дерева от Часовых ночных эльфов.",["faction:Horde"]="Для защитников Орды, стремящихся удержать передовой плацдарм в Ясеневом лесу, Масток — ключевой командир, который может направить вас к важным заданиям по всему краю."},sec={{t="Бастион в древних лесах",b="Застава Расщепленного Дерева стоит в глубокой тени высоких крон Ясеневого леса, полностью окруженная враждебными землями ночных эльфов. Масток Райльшип — один из главных защитников заставы: он следит за путями снабжения и происходящим в лесу. Положение опасно: любой признак слабости навлекает быстрые удары Часовых, которые считают поселение осквернительным вторжением."},{t="Координация фронта",b="Со своего наблюдательного пункта внутри частокола Масток деятельно поручает проходящим мимо искателям приключений важные стратегические задачи. Он следит за границами, ведущими в соседние земли, такие как Когтистые горы, и отправляет разведчиков за советом к шаманам, например к Дже'неу Санкри из Служителей Земли в форте Зорам'гар. Его обязанности сочетают военную оборону и наблюдение за странными порчеными силами, поражающими местных элементалей."}},faq={{q="Кто такой Масток Райльшип?",a="Масток Райльшип — элитный орк, расквартированный на Заставе Расщепленного Дерева в Ясеневом лесу. Он выступает как офицер и персонаж, выдающий задания, которому поручено удерживать форпост от вторжений ночных эльфов и расследовать угрозы в окрестностях.",al={"who is mastok","mastok wrilehiss role","who is this orc","кто такой масток","масток райльшип роль","кто этот орк"}},{q="Где найти Мастока Райльшипа?",a="Он находится внутри Заставы Расщепленного Дерева — укрепленного форпоста Орды в центрально-восточной части Ясеневого леса, у главной лесной дороги.",al={"mastok location","where is mastok wrilehiss","mastok map","где масток","где масток райльшип","масток на карте","местонахождение мастока"}},{q="Какие задания Масток дает искателям приключений?",a="Масток поручает авантюристам Орды стратегические задачи: расследовать угрозы порченых элементалей в лесу, охранять проходы в сторону Когтистых гор и направлять посланников к Дже'неу Санкри из Служителей Земли.",al={"mastok quests","quests from mastok","задания мастока","задания от мастока"}},{q="Почему Застава Расщепленного Дерева постоянно под давлением?",a="Форпост служит главным центром лесозаготовок и оплотом Орды в Ясеневом лесу. Коренные ночные эльфы считают присутствие орков и вырубку леса страшным осквернением священных земель, из-за чего стычки не прекращаются.",al={"why are night elves attacking splintertree","splintertree post conflict","почему ночные эльфы нападают на заставу расщепленного дерева","конфликт на заставе расщепленного дерева"}},{q="Почему Масток отправляет путников к Дже'неу Санкри?",a="Шаманы Служителей Земли, в том числе Дже'неу из форта Зорам'гар, изучают и врачуют нестабильность стихий, терзающую Ясеневый лес. Масток связывает бойцов передовой с их духовным опытом для борьбы с оскверненными элементалями воды и странными явлениями.",al={"why contact earthen ring","mastok and jeneu","зачем идти к служителям земли","масток и дже'неу"}},{q="Враждебен ли Масток Райльшип к игрокам Альянса?",a="Да. Масток — преданный член Орды и элитный защитник Заставы Расщепленного Дерева, поэтому он нападет на игроков Альянса, едва они приблизятся к лагерю.",al={"can alliance talk to mastok","is mastok killable","может ли альянс говорить с мастоком","можно ли убить мастока"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {n="Матиас Шоу",s="Мастер Матиас Шоу — глава ШРУ, тайной разведывательной службы Королевства Штормград. Действуя из тени Старого города, он направляет шпионов и разведчиков на защиту королевства как от внутренних заговоров, так и от внешних ужасов.",h="Мастер Матиас Шоу — глава ШРУ, тайной разведывательной службы Королевства Штормград.",ang={["class:Rogue"]="Матиас Шоу — вершина человеческого искусства разбойников. Разбойников Альянса часто направляют к нему за сложными тактическими поручениями и особыми ядами.",["faction:Alliance"]="Как шпион королевства, Шоу — первая линия защиты от подрывной деятельности: он собирает ценные военные сведения для верховного лорда Болвара Фордрагона и юного короля Андуина.",["race:Human"]="Трагическая ссора Шоу с другом детства Эдвином ван Клифом отражает более широкий и горький раскол в Королевстве Штормград после его восстановления."},sec={{t="Глава ШРУ",b="Матиас Шоу — ведущий шпион и убийца Штормграда. Из неприметной штаб-квартиры ШРУ за казармами в Старом городе Шоу руководит тайной сетью, раскинувшейся по Восточным королевствам и за их пределами. Прагматичный, расчетливый и беззаветно преданный дому Ринов, он исходит из убеждения, что безопасность Штормграда зависит от невидимых кинжалов и похищенных донесений не меньше, чем от сияющих доспехов и дворцовых гарнизонов."},{t="Тень ван Клифа",b="Шоу связывает глубоко личная история с Эдвином ван Клифом, главой мятежного Братства Справедливости. Они были друзьями детства, и Шоу лично обучил ван Клифа искусству скрытности и убийства, надеясь, что одаренный каменщик направит свои таланты на службу королевству рядом с ним. Но когда после восстановления Штормграда Гильдию каменщиков изгнали, ван Клиф обратил эти смертоносные уроки против короны. Сегодня Шоу руководит слежкой и внедрением, цель которых — разгромить мятеж его старого друга в Западном Крае."},{t="Глаза по всем королевствам",b="While domestic insurrection consumes Westfall and Elwynn, Shaw's attention is constantly drawn outward to lethal unknowns. When reports reached him of bizarre Forsaken operations in the Eastern Plaguelands, he dispatched five of his finest agents to investigate. Only one returned alive—babbling in terror about \"Nathanos\" and a \"Blightcaller\" before dying in his sleep. Shaw relies on trusted independent champions to venture where his scouts vanish, seeking to pierce the gloom gathering at the kingdom's borders."}},faq={{q="Кто такой Матиас Шоу?",a="Матиас Шоу — глава ШРУ, разведывательной службы Штормграда и гильдии убийц. Действуя из Старого города, он руководит шпионажем и тайной обороной королевства по поручению трона.",al={"who is shaw","leader of si7","mathias shaw lore","stormwind spymaster","кто такой шоу","глава шру","матиас шоу предания","шпион штормграда"}},{q="Где найти Матиаса Шоу?",a="Он находится в штаб-квартире ШРУ в районе Старый город в Штормграде, скрытой за военными казармами.",al={"shaw location","where is mathias shaw","find mathias shaw","где шоу","где матиас шоу","найти матиаса шоу","местонахождение шоу"}},{q="Как он связан с Эдвином ван Клифом?",a="Шоу и Эдвин ван Клиф были друзьями детства. Шоу лично обучил ван Клифа ремеслу разбойника и шпионажу, надеясь, что они будут работать вместе. Когда спор с каменщиками стал насильственным, ван Клиф использовал те самые навыки, чтобы создать Братство Справедливости.",al={"shaw and vancleef","vancleef friend","mathias and edwin","шоу и ван клиф","друг ван клифа","матиас и эдвин"}},{q="Что означает ШРУ?",a="ШРУ — главная разведывательная организация Штормграда, специализирующаяся на наблюдении, разведке, шпионаже и тайных убийствах для защиты королевства и интересов Альянса.",al={"what is si:7","what does si7 mean","stormwind intelligence","что такое шру","что значит шру","разведка штормграда"}},{q="Почему Матиас Шоу интересуется Западным Краем?",a="Западный Край — оплот Братства Справедливости. Шоу держит в регионе действующих агентов, чтобы шпионить за мятежниками и срывать их планы против Штормграда.",al={"shaw westfall","si7 westfall","klaven's tower","шоу западный край","шру западный край","башня клейвена"}},{q="Что случилось с агентами, которых Шоу отправил в Чумные земли?",a="Shaw dispatched five operatives to scout suspicious Forsaken movement in the Eastern Plaguelands. Four never returned, and the sole survivor came back babbling about \"Nathanos\" and a \"Blightcaller\" before dying in his sleep days later.",al={"shaw plaguelands quest","five scouts shaw","marris stead scouts","задание шоу чумные земли","пять разведчиков шоу","разведчики марриса"}}},fp="12,246,14.449.0,18.587.1,24.517.0,20.212.0,32.125.0,41.254.0,25.191.0,43.166.0,57.235.0"}
P.entries["npc:mathredis-firestar"] = {n="Матредис Огнезвезд",s="Матредис Огнезвезд — эксцентричный маг-эльф крови, живущий в Пламенеющем Стяге в Пылающих степях. Он создает мощные чары, известные как малые арканумы, опираясь на чародейские исследования своего умершего наставника. При этом он поглощает остаточную энергию, высвобождающуюся в процессе связывания, чтобы сдерживать свою тягу к магии.",h="Матредис Огнезвезд — эксцентричный маг-эльф крови, живущий в Пламенеющем Стяге в Пылающих степях.",kw={"arcanum","burning steppes","dreamseeker","firestar","flame crest","libram","mathredis","telmius","арканум","пылающие степи","искатель снов","огнезвезд","пламенеющий стяг","манускрипт","матредис","телмиус"},ang={["class:Mage"]="Маги распознают в синтезе арканумов Матредисом отчаянный, нестабильный способ получать сырую магическую пищу из процесса связывания предметов."},sec={{t="Наследие наставника и магическая зависимость",b="Матредис Огнезвезд научился делать арканумы — сконцентрированные самоцветы тайного усиления — у своего наставника Телмиуса Искателя Снов. Телмиус погиб страшной смертью среди древних руин Забытого Города, пытаясь вырвать магические тайны у Шен'дралар. Телмиус изобрел эти магические узы, но Матредису не хватает мастерства для создания величайших из них, поэтому он специализируется на малых арканумах. Для Матредиса это не просто упражнение: как все эльфы крови после падения Солнечного Колодца, он терзается голодом по тайной силе. Связывание материалов с древними манускриптами высвобождает яростные выбросы магической энергии, которыми Матредис подпитывается."},{t="Искусство арканума",b="Авантюристы, которые приносят Матредису подходящие тома — такие как либрамы стойкости, упругости, размышления, упорства или жадности — вместе с редкими реагентами, найдут в нем охотного партнера по обмену. В ходе процесса нестабильные магические реагенты привязываются прямо к тексту, концентрируя свою сущность в арканум, способный навсегда зачаровать головной убор или поножи. Пока авантюристы поставляют компоненты, Матредис получает и плату, и окружающую чародейскую пищу, которой так жаждет."}},faq={{q="Кто такой Матредис Огнезвезд?",a="Матредис Огнезвезд — маг-эльф крови, расквартированный на нейтральном форпосте Пламенеющий Стяг в Пылающих степях. Он чародей, способный создавать малые арканумы для зачарования доспехов.",al={"mathredis lore","who is mathredis firestar","firestar blood elf","матредис предания","кто такой матредис огнезвезд","огнезвезд эльф крови"}},{q="Зачем Матредис создает арканумы?",a="После разрушения Солнечного Колодца эльфы крови страдают от тяжелой магической ломки. Матредис питается сырой остаточной магической энергией, высвобождающейся при создании и связывании арканумов, чтобы унять свою расовую зависимость.",al={"why make arcanums","mathredis motivation","why librams","зачем делать арканумы","мотивация матредиса","зачем либрамы"}},{q="Кто такой Телмиус Искатель Снов?",a="Телмиус Искатель Снов — покойный наставник Матредиса и изобретатель арканумов. Телмиус отправился в руины Забытого Города, чтобы почерпнуть знания у Шен'дралар, но был убит там, не успев передать все свое мастерство.",al={"telmius","mathredis master","who was his master","телмиус","наставник матредиса","кто был его наставник"}},{q="Какие арканумы может создавать Матредис?",a="Матредис может создавать малые арканумы стойкости, упругости, размышления, упорства и жадности. Самые мощные арканумы знал лишь его наставник Телмиус, и они остаются недоступны Матредису.",al={"which arcanums","lesser arcanums","libram list","какие арканумы","малые арканумы","список либрамов"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="Матренгил Медвежья Лапа",s="Матренгил Медвежья Лапа — мастер-наставник друидов и уважаемый старейшина Круга Кенария, живущий в Анклаве Кенария в Дарнассе. Когда-то он был непосредственным помощником верховного друида Фэндрала Оленьего Шлема и теперь наставляет молодых друидов Альянса в духовных испытаниях, обрядах превращения и их обязанностях на Калимдоре.",h="Матренгил Медвежья Лапа — мастер-наставник друидов и уважаемый старейшина Круга Кенария, живущий в Анклаве...",kw={"aquatic form","bear form","bearwalker","cenarion circle","cenarion enclave","darnassus","druid of the claw","druid trainer","fandral staghelm","mathrengyl bearwalker","morrowgrain","teldrassil","водный облик","облик медведя","медвежья лапа","круг кенария","анклав кенария","дарнасс","друид-медведь","наставник друидов","фэндрал олений шлем","матренгил медвежья лапа","утренняя трава","тельдрассил"},ang={["class:Druid"]="Для друидов Альянса Матренгил — важнейший наставник, связывающий Дарнасс с Лунной поляной и открывающий тайны облика медведя, Водного облика и лечения смертельных ядов травами.",["faction:Alliance"]="Матренгил воплощает стабильное, традиционное руководство Круга Кенария в Дарнассе и умеренно контрастирует с агрессивной позой Фэндрала Оленьего Шлема.",["race:NightElf"]="Образец друидизма кальдораев, Матренгил воплощает преданность природе и равновесию после Третьей войны и с ростом Тельдрассила."},sec={{t="Наставник Анклава Кенария",b="Матренгил Медвежья Лапа живет в зеленых пределах Анклава Кенария в Дарнассе и считается одним из самых почтенных и уравновешенных друидов Тельдрассила. Он главный наставник начинающих друидов Альянса: следит за их единением с Лунной поляной и проверяет их готовность овладеть первобытными обликами зверей. В юности он сам прошел трудное, ошеломляющее единение с Великим Духом Медведя, поэтому понимает вес этих обрядов и лично велит посвящаемым доказать силу духа в схватке со священным лунным совуном Лунным Когтем, прежде чем принять их на путь Друида-медведя."},{t="Служба Верховному друиду",b="Матренгил давно служит заместителем Фэндрала Оленьего Шлема: ведет повседневные дела Круга и занимается набором людей для честолюбивых замыслов Верховного друида. Когда Фэндрал потребовал огромное количество утренней травы, Матренгил организовал ее сбор у вернувшихся искателей приключений, хотя втайне признавался в смутной тревоге из-за неестественной природы этого странного растения. Он также согласует ответы Альянса на призывы с Лунной поляны и лавирует в тонкой политике Круга Кенария, пока Фэндрал обращает взор на юг Калимдора и Чумные земли."},{t="Более широкий взгляд",b="Если Оленьий Шлем известен своей непомерной гордыней и презрением к другим расам, то Матренгил часто проявляет задумчивость и открытость. Когда в Дарнасс прибыли вещи павшего друида Мулгриса Глубокая Река, погибшего в борьбе с Плетью в Западных Чумных землях, Матренгил был глубоко тронут, узнав, что тот исследователь был таурен. Размышляя об общей миссии Круга Кенария, он тихо заметил, что таурены, возможно, отошли от учения Кенария вовсе не так далеко, как настаивает Верховный друид."}},faq={{q="Кто такой Матренгил Медвежья Лапа?",a="Матренгил Медвежья Лапа — опытный наставник друидов из ночных эльфов, живущий в Анклаве Кенария в Дарнассе. Его почитают как одного из самых уравновешенных мудрецов Тельдрассила; он обучает посвящаемых превращениям, очищению от яда и обязанностям от имени Круга Кенария.",al={"who is mathrengyl","mathrengyl role","bearwalker","кто такой матренгил","роль матренгила","медвежья лапа"}},{q="Какие у него отношения с Фэндралом Оленьим Шлемом?",a="Матренгил был непосредственным помощником и заместителем верховного друида Фэндрала Оленьего Шлема. Послушно исполняя просьбы Фэндрала, включая сбор утренней травы и распределение поручений, Матренгил втайне сомневается в некоторых жестких взглядах и странных замыслах Фэндрала.",al={"fandral assistant","staghelm and mathrengyl","помощник фэндрала","олений шлем и матренгил"}},{q="Каким обликам Матренгил помогает научиться друидам?",a="Матренгил наставляет молодых друидов после их духовных паломничеств на Лунную поляну: он следит за их единением с Лунным Когтем для получения облика медведя, а также завершает их испытания на Темных берегах и в Западном Крае, чтобы они освоили Водный облик.",al={"bear form quest darnassus","aquatic form quest darnassus","druid forms mathrengyl","облик медведя задание дарнасс","водный облик задание дарнасс","облики друида матренгил"}},{q="Почему Матренгил собирает утреннюю траву?",a="Он помогает верховному друиду Фэндралу Оленьему Шлему в ботанических исследованиях на Тельдрассиле, собирая утреннюю траву, которую выращивают искатели приключений. Тем не менее Матренгил признавался, что ему глубоко не по себе в присутствии этого растения.",al={"morrowgrain quest","why morrowgrain darnassus","задание утренняя трава","зачем утренняя трава дарнасс"}},{q="Как Матренгил относится к друидам-таурен?",a="В отличие от Фэндрала Оленьего Шлема, который открыто скептически смотрит на друидов-таурен, Матренгил более рассудителен. Узнав о жертве друида-таурена, сражавшегося с Плетью в Западных Чумных землях, он признал, что таурены, возможно, идут ближе к учению Кенария, чем допускает Фэндрал.",al={"tauren druids","mathrengyl tauren","друиды таурены","матренгил таурены"}},{q="Что он делает с Кошмарным осколком?",a="Когда искатели приключений приносят оскверненный Кошмарный осколок Фолле Ветер Мудрости, она направляет их к Матренгилу, который в сильной тревоге осматривает его, чувствуя подступающую порчу, угрожающую Изумрудному Сну.",al={"nightmare shard mathrengyl","in nightmares quest","кошмарный осколок матренгил","задание в кошмарах"}}},fp="21,314,30.623.0,24.566.0,21.521.0,29.262.0,47.285.0,45.226.0,40.234.0,45.289.0,41.199.0"}
P.entries["npc:maur-grimtotem"] = {n="Маур Зловещий Тотем",s="Маур Зловещий Тотем был эмиссаром, отправленным Мудрой старухой Магатой Зловещим Тотемом в глубины Огненной пропасти. Посланный с обреченной дипломатической миссией к троггам, наводнившим подземные туннели под Оргриммаром, он жестоко погиб от их рук. Сегодня лишь его останки и личная сумка во тьме напоминают об этом безрассудном поручении.",h="Маур Зловещий Тотем был эмиссаром, отправленным Мудрой старухой Магатой Зловещим Тотемом в глубины Огненной...",kw={"grimtotem","magatha","maur","oggleflint","orgrimmar","ragefire","satchel","trogg","зловещий тотем","магата","маур","огглфлинт","оргриммар","огненная пропасть","сумка","трогг"},ang={["faction:Horde"]="Смертельная подземная пещера прямо под Оргриммаром — уже плохо, а отправка одиноких посланников на переговоры с троггами обернулась полной катастрофой для безопасности Орды.",["race:Tauren"]="У клана Зловещего Тотема непростые отношения с остальными племенами Громового Утеса, и странное роковое поручение Маура в туннели троггов лишь усиливает подозрения насчет истинных планов Магаты."},sec={{t="Обреченная дипломатия",b="Хотя большинство в Орде считает троггов безмозглыми дикарями, с которыми нельзя договариваться, Мудрая старуха Магата Зловещий Тотем думала иначе — или по крайней мере так заявляла. Она отправила Маура Зловещего Тотема в извилистые пещеры Огненной пропасти под Оргриммаром, чтобы попытаться мирно заговорить с подземными тварями. Как и следовало ожидать, дипломатия провалилась. Маур был быстро убит, а его тело осталось в пещерах под присмотром вождя троггов Огглфлинта."},{t="Интересы Мудрой старухи",b="После гибели Маура Магата искала искателей приключений не только чтобы отомстить за него, но и чтобы вернуть личную сумку, которую он унес в глубины. Действительно ли Маур верил в возможность мира с троггами или был лишь расходной пешкой в тайных замыслах матриарха Зловещего Тотема — остается открытым вопросом для тех, кто находит его вещи."}},faq={{q="Кто такой Маур Зловещий Тотем?",a="Маур был тауреном из клана Зловещего Тотема. По приказу Магаты Зловещего Тотема он отправился в пещеры Огненной пропасти под Оргриммаром как эмиссар к троггам, где и был убит.",al={"who is maur","maur grimtotem lore","what was maur doing","кто такой маур","маур зловещий тотем предания","что делал маур"}},{q="Почему он пытался договориться с троггами?",a="Мудрая старуха Магата заявляла, что отправила его искать мира и проверить силу этих подземных врагов. Учитывая дикую природу троггов, многие подозревают, что у Магаты были скрытые мотивы или она просто использовала Маура, чтобы разведать глубины Огненной пропасти.",al={"why make peace with troggs","trogg diplomacy","why talk to troggs","зачем мир с троггами","дипломатия с троггами","зачем говорить с троггами"}},{q="Кто убил Маура Зловещего Тотема?",a="Маура убило племя троггов, живущее в Огненной пропасти. Его тело нашли под плотной охраной Огглфлинта, вождя троггов Огненной пропасти.",al={"how did maur die","who killed him","maur death","как погиб маур","кто его убил","смерть маура"}},{q="Что случилось с его телом и вещами?",a="Тело Маура осталось в Огненной пропасти рядом с Огглфлинтом. Рахауро в Громовом Утесе поручает искателям приключений вернуть потерянную сумку Маура и принести ее Магате Зловещий Тотем на Вершину Старейшин.",al={"maur corpse","lost satchel","maur's satchel","тело маура","потерянная сумка","сумка маура"}}},fp="14,352,18.458.0,27.345.1,23.209.0,40.232.0,26.149.0,41.200.0"}
P.entries["npc:maur-raincaller"] = {n="Маур Заклинатель Дождя",s="Маур Заклинатель Дождя — таурен, живущий в Деревне Кровавого Копыта в Мулгоре. Связанный с природной и духовной жизнью равнин, он помогает старейшинам деревни и присматривает за местными делами, касающимися стад и диких зверей.",h="Маур Заклинатель Дождя — таурен, живущий в Деревне Кровавого Копыта в Мулгоре.",kw={"bloodhoof village","maur raincaller","mazzranache","mulgore","plainstrider","tauren","деревня кровавого копыта","маур заклинатель дождя","маззранач","мулгор","равнинный долгоног","таурен"},ang={["class:Hunter"]="Маур дает раннее охотничье испытание, отправляя вас за волками, пумами, равнинными долгоногами и крылоклювами открытых равнин ради частей, нужных ему для лечения ядовитого укуса Маззранача.",["race:Tauren"]="Для молодых таурен, покидающих Лагерь Нараче, Маур дает возможность защитить исконные земли вашего народа от бродячих хищников и буйных зверей."},sec={{t="Житель Деревни Кровавого Копыта",b="Маур Заклинатель Дождя живет почти в самом сердце Деревни Кровавого Копыта на берегу озера Каменного Быка и служит общине, занимаясь вопросами местной природы и зверей. Как и многие носители звания Заклинателя Дождя, он внимательно следит за равновесием стихий и дикой природы на плодородных равнинах Мулгора. После того как укус свирепого долгонога Маззранача вызвал у него заражение раны, Маур обращается к способным молодым путникам, чтобы они добыли части зверей для его лекарства."}},faq={{q="Кто такой Маур Заклинатель Дождя?",a="Маур Заклинатель Дождя — таурен, живущий в Деревне Кровавого Копыта среди зеленых лугов Мулгора. Он выдает задания, поручая искателям приключений усмирять буйных зверей в окрестностях.",al={"maur raincaller role","who is maur","maur raincaller lore","роль маура заклинателя дождя","кто такой маур","маур заклинатель дождя предания"}},{q="Где найти Маура Заклинателя Дождя?",a="Его можно найти под открытым небом среди типи и очагов Деревни Кровавого Копыта, к югу от Громового Утеса, на восточном берегу озера Каменного Быка.",al={"maur raincaller location","where is maur","maur coords","где маур заклинатель дождя","где маур","координаты маура"}},{q="С какой бедой столкнулся Маур?",a="Маура укусил Маззранач, свирепый долгоног из рассказов его деда, и рана воспалилась. Он просит искателей приключений принести ему части волков, пум, равнинных долгоногов и крылоклювов Мулгора, чтобы приготовить лекарство.",al={"maur raincaller quest","mazzranache problem","what does maur want","задание маура заклинателя дождя","проблема маззранач","чего хочет маур"}}},fp="15,241,31.493.0,23.204.0,33.168.0,34.243.0"}
P.entries["npc:maurin-bonesplitter"] = {n="Маурин Костолом",s="Маурин Костолом — Отрекшийся ученый и чародей, служащий на Заставе Скитающихся Духов в Пустошах. Назначенный Кельдраном следить за деятельностью демонического культа, он применяет глубокое знание древних преданий, чтобы уничтожить Пылающий Клинок. Маурин относится к культистам с полным презрением, считая их глупцами, слепыми к темным силам, дергающим за их ниточки.",h="Маурин Костолом — Отрекшийся ученый и чародей, служащий на Заставе Скитающихся Духов в Пустошах.",kw={"burning blade","corrupter","desolace","forsaken","ghost walker post","keldran","maurin bonesplitter","пылающий клинок","осквернитель","пустоши","отрекшиеся","застава скитающихся духов","кельдран","маурин костолом"},ang={["class:Mage"]="Маги, посещающие Заставу Скитающихся Духов, оценят расчетливый интеллектуальный подход Маурина к распутыванию темных ритуалов с помощью особых контрзаклинаний.",["class:Warlock"]="Чернокнижники оценят глубокое понимание Мауриным демонических пактов, хотя его презрение резко напоминает об опасности служения могущественным исчадиям.",["faction:Horde"]="Маурин олицетворяет особую поддержку Подгорода западным аванпостам Орды: он приносит темные научные знания, помогая союзникам-таурен против демонической порчи.",["race:Undead"]="Маурин показывает, что сила Отрекшихся зиждется не только на грубой мощи некромантии, но и на хитроумных магических исследованиях и использовании слабостей врага."},sec={{t="Ученый среди изгоев",b="Хотя Застава Скитающихся Духов служит в основном заставой таурен и Орды среди засушливых земель Пустошей, Маурин Костолом выделяется как один из немногих тамошних нежитей. Он не грубый солдат, а ученый чародей с обширными знаниями о запретной истории и оккультных силах. Его магические способности и острый ум привлекли внимание Кельдрана, который направил его в этот край наблюдать за растущим демоническим присутствием и координировать прицельные удары по нему."},{t="Презрение к Пылающему Клинку",b="Большую часть своей злобы Маурин направляет на культ Пылающего Клинка, закрепившийся в Пустошах. Он питает крайнее отвращение к их безрассудным амбициям и насмехается над культистами, не понимающими, что заимствованная сила лишь делает их рабами демонических хозяев. С помощью чар прорицания и ритуальных знаний Маурин привлекает искателей приключений Орды, чтобы систематически срывать призывы культа и подрывать его деятельность на бесплодных землях."}},faq={{q="Кто такой Маурин Костолом?",a="Маурин Костолом — Отрекшийся маг и ученый, живущий на Заставе Скитающихся Духов в Пустошах. Назначенный Кельдраном, он использует знание древних преданий и темной магии, чтобы искоренить культ Пылающего Клинка, действующий в этом краю.",al={"maurin bonesplitter lore","who is maurin","maurin desolace","маурин костолом предания","кто такой маурин","маурин пустоши"}},{q="Почему нежить находится на заставе таурен?",a="Застава Скитающихся Духов — важное поселение Орды в Пустошах. Кельдран разместил там Маурина именно потому, что застава — идеальный плацдарм для наблюдения за культистами Пылающего Клинка, наводнившими окрестные земли, и борьбы с ними.",al={"why is maurin at ghost walker post","undead in desolace","почему маурин на заставе скитающихся духов","нежить в пустошах"}},{q="Что Маурин думает о Пылающем Клинке?",a="Маурин глубоко презирает Пылающий Клинок. Он считает его членов жалкими невежественными пешками, которые заблуждаются, будто владеют истинной силой, и совершенно не осознают, что они лишь марионетки демонических хозяев.",al={"maurin burning blade","why does maurin hate burning blade","маурин пылающий клинок","почему маурин ненавидит пылающий клинок"}},{q="Кто направил Маурина Костолома в Пустоши?",a="Маурина на его роль в Пустошах назначил Кельдран. Оценив обширные познания Маурина о практиках культа и древних преданиях, Кельдран поручил ему активно мешать Пылающему Клинку и в итоге уничтожить его в этой местности.",al={"who sent maurin","maurin keldran","maurin boss","кто послал маурина","маурин кельдран","начальник маурина"}},{q="Какие задания Маурин дает искателям приключений?",a="Маурин просит искателей приключений расследовать деятельность Пылающего Клинка и добыть скальп Ненавистного Темного охотника и Кристалл Оракула наг. Эти реагенты он использует, чтобы разрушить защиту от прорицания и найти повелителя демонов, стоящего за культом.",al={"maurin quests","what does maurin want","задания маурина","чего хочет маурин"}},{q="Связан ли Маурин с Кругом Кенария или с Ордой?",a="Маурин — верный член Отрекшихся и служит Орде. Он действует строго из лагеря Орды на Заставе Скитающихся Духов, помогая чемпионам Орды очищать пустоши от деятельности культистов.",al={"is maurin horde","maurin faction","маурин орда","фракция маурина"}}},fp="19,361,24.495.0,30.459.0,27.228.0,42.252.0,46.222.0,41.236.0,48.214.0,59.199.0"}
P.entries["npc:maxan-anvol"] = {n="Максан Анвол",s="Максан Анвол — дворф, наставник жрецов в таверне «Громоварка» в Караносе. Преданный Свету, он обучает начинающих жрецов-дворфов направлять божественную силу в суровом климате Дун Морога. Он испытывает молодых послушников, чтобы убедиться, что они достойны носить облачение церкви.",h="Максан Анвол — дворф, наставник жрецов в таверне «Громоварка» в Караносе.",kw={"desperate prayer","dun morogh","garments of the light","holy light","kharanos","maxan anvol","priest trainer","thunderbrew distillery","молитва отчаяния","дун морог","облачение света","свет","каранос","максан анвол","наставник жрецов","таверна громоварка"},ang={["class:Priest"]="Максан — ваш первый наставник в Дун Мороге: он открывает вам доступ к основам священной школы, обучает расовым молитвам, например Молитве отчаяния, и вручает первое официальное облачение церкви.",["faction:Alliance"]="Максан заботится о телесной и духовной готовности горцев и разведчиков Альянса, охраняющих Дун Морог от троггов, ледяных троллей и диких зверей.",["race:Dwarf"]="Воплощая практичное благочестие Стальгорна, Максан укрепляет веру дворфов там, где народ действительно собирается: прямо рядом с пивными бочонками Караноса."},sec={{t="Жрец в пабе",b="Хотя может показаться странным видеть рукоположенного служителя Света в таверне «Громоварка», это хорошо созвучно культуре дворфов. Каранос — главный перевалочный пункт между Холодной долиной и Стальгорном, и местный трактир — естественное место встречи путников, горцев и служителей. Максан заботится о духовном благополучии селения за кружкой стаута, читая молитвы и давая советы каждому, кто переступит порог."},{t="Испытание верных",b="Максан Анвол отвечает за проверку жрецов-новичков перед тем, как они отправятся в большой мир. Он поручает посвящаемым показать владение основными исцеляющими молитвами на раненых защитниках Дун Морога. Тех, кто докажет свою преданность и практическое умение, он наделяет первым настоящим облачением жреца, официально закрепляя их признанное положение в Церкви Священного Света."}},faq={{q="Где найти Максана Анвола?",a="Максан Анвол находится в таверне «Громоварка» — главном трактире и месте сбора в городке Каранос, расположенном среди снежных заносов в центре Дун Морога.",al={"maxan anvol location","where is maxan","priest trainer kharanos","максан анвол где найти","где максан","наставник жрецов каранос"}},{q="Чему учит Максан Анвол?",a="Он наставник жрецов, обучающий новичков и подмастерьев заклинаниям священного исцеления, власти над Тенью и божественной защиты. Также он обучает жрецов-дворфов особым мольбам, например Молитве отчаяния.",al={"what does he train","maxan anvol spells","чему он учит","заклинания максана анвола"}},{q="Почему жрец Света околачивается в таверне?",a="В обществе дворфов жизнь, общение и празднества вращаются вокруг пивоварения и таверн. «Громоварка» служит для Караноса общественным собранием, ратушей и приютом для путников. Максан остается там, где до него могут добраться простой люд, стражи и проезжие путники, нуждающиеся в духовном утешении.",al={"why distillery","priest in a bar","почему таверна","жрец в баре"}},{q="Дает ли Максан Анвол особые задания?",a="Да. Он испытывает будущих жрецов заданиями «Во имя Света» и «Облачение Света», посылая их исцелять раненых горцев на снегу. Успешно выполнив их, посвящаемый получает официальную мантию служителя.",al={"maxan quests","garments of the light","задания максана","облачение света"}},{q="Что он говорит не жрецам?",a="Он предупреждает других искателей приключений никогда не отворачиваться от Света и напоминает, что божественная милость вполне может оказаться единственным, что однажды спасет им жизнь в бою.",al={"maxan dialogue","maxan quote","диалог максана","цитата максана"}},{q="Могут ли гномы учиться у Максана Анвола?",a="Хотя гномы как народ обычно не становятся жрецами, Максан радушно принимает всех членов Альянса, ищущих мудрости, и обучает любого жреца, давшего обет Свету.",al={"can gnomes talk to him","gnome priest trainer","могут ли гномы говорить с ним","наставник гномов-жрецов"}}},fp="11,322,19.445.0,20.399.0,29.164.0,28.218.0,49.282.0,41.243.0,32.178.0,34.188.0"}
